window.BIO_DATA = [{"i": 0,"n": "אבא (7)","l": "א","b": "חכם ארץ ישראלי קדום. קיבל מהזוגות. חי בימי הלל, כמאה שנה לפני חורבן בית שני. מובא במשנה: \"מעשה שזרע ר' שמעון איש המצפה, ובא לפני רבן גמליאל הזקן, ועלו ללשכת הגזית ושאלו, אמר נחום הלבלר: 'מקובל אני מרבי מיאשא, שקבל מאבא, שקבל מן הזוגות, שקבלו מן הנביאים, הלכה למשה מסיני בזורע' וכו'\" (פאה פ\"ב מ\"ו).","cat": "sage"},{"i": 1,"n": "רבי אבא (2)","l": "א","b": "אמורא בבלי בדור השלישי. תלמידם של רב הונא (מנחות כ\"ט ע\"א) ושל רב יהודה (יבמות ע\"ה ע\"ב), ועוד למד מרב (יומא ס\"ד ע\"ב) ושמואל (ברכות נ' ע\"א). עלה לא\"י לפני ר' זירא (חולין נ\"ז ע\"א - רש\"י), שהיה חברו המובהק (שם נ' ע\"א). בא\"י למד לפני רבי יוחנן (נדה כ\"ה ע\"ב) ושם התעלה, עד שהגמרא אומרת \"רבותינו שבארץ ישראל - רבי אבא\" (סנהדרין י\"ז ע\"ב), ושלח פסקים מא\"י לבבל (ב\"ב קכ\"ז ע\"ב). מדי פעם ירד לבבל והביא עמו מתורת חכמי א\"י (ב\"מ ק\"ז ע\"א) כשנפטר רב הונא רבו והביאוהו לא\"י\", הספידו ר' אבא (מו\"ק כ\"ה ע\"א). עסק במסחר המשי (ב\"ק קי\"ז ע\"ב) והיה עשיר (שבת קי\"ט ע\"א). נתן צדקה בדרך שלא לבייש את העניים (כתובות ס\"ז ע\"ב). האריך ימים, שכן דיבר עם שמואל [שנפטר בשנת ד' י\"ג (352)] (ירו' עירובין פ\"ו ה\"ז), ומאידך חי עוד בימי רבא [שנפטר בשנת ד' קי\"א (153)] (ב\"ק ק\"ד ע\"ב).","cat": "sage"},{"i": 2,"n": "ר' אבא אבוה דרב בריה דרב משרשיא","l": "א","b": "מובא בבבלי (עירובין כ\"ד ע\"א). \"סדר הדורות\" כתב: \"וטעות סופר יש כאן\". ע\"ע רב אבא אחוה דרב בריה דרב משרשיא.","cat": "sage"},{"i": 3,"n": "ר' אבא אבוה דר' אבא בר מרי","l": "א","b": "כתב ב\"סדר הדורות\": \"נ\"ל שצ\"ל אבא אבוי דר' אבא מרי\".","cat": "sage"},{"i": 4,"n": "ר' אבא אבוה דר' אבא מרי","l": "א","b": "אמורא ארץ ישראלי מובא בירושלמי (ברכות פ\"ט ה\"ג). מצינו שמסר בשם רבי אחא (שם).","cat": "sage"},{"i": 5,"n": "אבא אבוה דר' ירמיה בר אבא","l": "א","b": "אמורא בבלי בדור הראשון. בשמו הובאה ברייתא ששנה: \"דתני אבוה דרבי [צ\"ל דרב] ירמיה בר אבא\". (מנחות מ\"ז ע\"א). היה לו אח ושמו אחא, ואחד משניהם היה בעל תשובה גדול: \"דאמר רב 'אין לך גדול בבעלי תשובה וכו' ומנו? אבא אבוה דר' ירמיה בר אבא', ואמרי לה: אחא אחוה דאבא\" (שבת נ\"ו ע\"ב).","cat": "sage"},{"i": 6,"n": "אבא אבוה דר' שמלאי","l": "א","b": "אמורא בבלי בדור הראשון. נראה, שמושבו היה בנהרדעא. שאל לשמואל שאלה בסוד העיבור ולא ידע לענות לו (ר\"ה כ' ע\"ב) בנו רבי שמלאי היה תלמידו של יהודה נשיאה הראשון (ע\"ז ל\"ז ע\"א).","cat": "sage"},{"i": 7,"n": "אבא אבוה דשמואל","l": "א","b": "ע\"ע אבא בר אבא אבוה דשמואל.","cat": "sage"},{"i": 8,"n": "אבא אומנא","l": "א","b": "חסיד גדול שחי בבבל בדור השלישי לאמוראים. בכל יום שאלו לשלומו מן השמים ואילו לשלום אביי - רק בכל ערב שבת: דבר זה גרם לאביי חלישות דעת והוא שלח את תלמידיו לבדוק אחריו מה זכותו הגדולה, ואז נוכח בגודל חסידותו (תענית כ\"א ע\"ב). מלאכתו היתה הקזת דם. (שם).","cat": "sage"},{"i": 9,"n": "אבא אושעיא איש טורייא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. נולד ביום שנפטר רבין (ב\"ר נ\"ח - ב'). היה חסיד וזהיר במעשיו (ירו', ב\"ק פ\"י ה\"י). פעם קידש שם שמים, בהחזירו אבידה יקרה למלכה (ירו', ב\"מ פ\"ב ה\"ה). כשנפטר ריחפה מיטתו באויר (מד\"ר שה\"ש פ\"ח - ז').","cat": "sage"},{"i": 10,"n": "רב אבא אחוה דרב בריה דרב משרשיא","l": "א","b": "מובא בבבלי (עירובין כ\"ד ע\"א). כך גירסת מסורת הש\"ס.","cat": "sage"},{"i": 11,"n": "ר' אבא אחוה דר' יהודה בר זבדי","l": "א","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב יהודה. רב שמואל בר יהודה מסר משמו (יבמות פ\"ג ע\"ב). היה לו אח ושמו ר' סימון (ירו', ב\"ב רפ\"ג). ע\"ע ר' אבא בר זבדי.","cat": "sage"},{"i": 12,"n": "אבא אלעזר","l": "א","b": "תנא ארץ ישראלי בדור השלישי. חי בזמן הבית: \"א\"ר יוסי: 'סח לי אבא אלעזר: פעם אחת היה לנו עגל של זבחי שלמים והביאנוהו לעזרת נשים'\" (חגיגה ט\"ז ע\"ב).","cat": "sage"},{"i": 13,"n": "אבא אלעזר בן אליעזר בן דולעאי","l": "א","b": "תנא בדור הרביעי. חלק על תלמידי ר\"ע - רבי מאיר, רבי יהודה ורבי שמעון (מקואות ספ\"ב).","cat": "sage"},{"i": 14,"n": "אבא אלעזר בן גומל","l": "א","b": "מובא בבבלי (בכורות נ\"ח ע\"ב), והוא אבא אלעזר בן גימל (ביצה י\"ג ע\"ב).","cat": "sage"},{"i": 15,"n": "אבא אלעזר בן גימל","l": "א","b": "תנא שאין לקבוע זמנו המדויק. מובא בבבלי (ביצה י\"ג ע\"ב). ה\"יוחסין\" כתב עליו: \"נראה שהוא בזמן ר' יוחנן\". שמו נשתבש בכמה פנים.","cat": "sage"},{"i": 16,"n": "אבא אלעזר בן גמלא","l": "א","b": "מובא בבבלי (גיטין ל' ע\"ב), והוא אבא אלעזר בן גימל.","cat": "sage"},{"i": 17,"n": "אבא אלעזר בן גמליאל","l": "א","b": "מובא בספרי (קרח פ' ונחשב), והוא אבא אלעזר בן גימל.","cat": "sage"},{"i": 18,"n": "אבא אלעזר בן דולעאי","l": "א","b": "תנא בדור החמישי. חלק על רבי מאיר ורבי יהודה וחבריהם (מקואות ספ\"ב). \"סה\"ד\" מסתפק אם הוא אליעזר בן דגלאי.","cat": "sage"},{"i": 19,"n": "אבא אנטולי","l": "א","b": "חי בארץ ישראל, בדור הראשון לאמוראים. מובא בירושלמי (דמאי פ\"ה ה\"ח), ששאל את רבי יהודה בן לוי בענין מעשרות. ספק אם נמנה עם החכמים.","cat": "sage"},{"i": 20,"n": "אבא אריכא","l": "א","b": "הוא רב, כדמצינו בבבלי (חולין קל\"ז ע\"ב).","cat": "sage"},{"i": 21,"n": "אבא ביראה","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מוזכר פעם בבבלי (מנחות צ\"ג ע\"ב): \"דתניא, אבא ביראה ברבי אליעזר בן יעקב אומר\" [פירוש המלה ברבי כמו בדבי (עירובין י\"ט ע\"א רש\"י ד\"ה: בדבי)].","cat": "sage"},{"i": 22,"n": "אבא בן יוסי","l": "א","b": "מובא בספרי (נשא פמ\"ב), והוא אבא יוסי בן דוסתאי.","cat": "sage"},{"i": 23,"n": "אבא בנימין (2)","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. ארבעה מאמרי אגדה הובאו בשמו בבבלי (ברכות ה' ע\"ב). מצינו בירושלמי אבא פנימון (תרומות פ\"ג ה\"ג), ואולי חד הוא.","cat": "sage"},{"i": 24,"n": "אבא בר אבא","l": "א","b": "מובא בבבלי (ברכות י\"ח ע\"ב), והוא אבוה דשמואל. (ע\"ע).","cat": "sage"},{"i": 25,"n": "אבא בר אבא אבוה דשמואל","l": "א","b": "אמורא בבלי בדור המעבר בין התנאים לאמוראים. אביו של האמורא שמואל (ברכות י\"ח ע\"ב). היה הראש בנהרדעא (ביצה ט\"ז ע\"ב). נראה שקיבל מרב הונא ראש גלותא (מעילה ט' ע\"א). כשלוי ירד לבבל, היו לחברים ולמדו יחד (ב\"ב מ\"ב ע\"ב). זכו יחד לגילוי שכינה (מגילה כ\"ט ע\"א). [לוי נפטר לפניו (ירו', ברכות פ\"ב ה\"ח)]. ביקר בארץ ישראל והיה לתלמידו של רבי (ירו', ר\"ה פ\"ג ה\"ו). בנו שמואל, קיבל ממנו (זבחים כ\"ו ע\"א). וכן קיבל ממנו רב (כתובות נ\"א ע\"ב). שלחו לו שאלות מארץ ישראל (ב\"מ צ' ע\"א). עסק במסחר המשי. נפגש לרגל מסחרו עם ר' יהודה בן בתירא, והוא בירכו שיהיה לו בן גדול כשמואל הרמתי (מדרש שמואל פ\"י - ג). היה חסיד ונהג לפנים משורת הדין (ב\"מ כ\"ד ע\"ב) ולימד את שמואל בנו לנהוג כן (ירו', סוף פאה). היה לו בן חכם נוסף ושמו פנחס (מו\"ק י\"ח ע\"א). היו לו גם בנות (שבת ס\"ה ע\"א). נראה שהאריך ימים וחי אף בימי ר' יהודה נשיאה נכד רבי (יבמות קט\"ו ע\"ב).","cat": "sage"},{"i": 26,"n": "אבא בר אבא בר ממל","l": "א","b": "אמורא בדור הרביעי. מובא בירושלמי (פאה פ\"ח ה\"ה). נראה שם כאילו היה תלמידו של רבי אלעאי, אבל נראה יותר שהיו חברים.","cat": "sage"},{"i": 27,"n": "רבי אבא בר אבין","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. מסר יחד עם רבי תנחום, בשם רבי אחא (ב\"ר פל\"ג - ס\"ג).","cat": "sage"},{"i": 28,"n": "רבי אבא בר אבינא","l": "א","b": "אמורא ארץ ישראלי בדור השני. נראה שכך שמו, כמובא (שבת ס' ע\"ב). ושמו שובש בצורות שונות. תלמידו של רב (ירו', ב\"מ פ\"ד ה\"א). היה דיין בעירו (שם פ\"ה ה\"א). ר' אבא בר זבדי שאל ממנו (שבת שם). חיבר נוסח וידוי ליום הכיפורים (ירו', סוף יומא). היה לו אח ושמו חגרא (ירו', מגילה פ\"א ה\"ט).","cat": "sage"},{"i": 29,"n": "רבי אבא בר אדא","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (גיטין פ\"ד ה\"ו). מצינו ששאל לרב מני (שם). ואינו בהכרח תלמידו.","cat": "sage"},{"i": 30,"n": "אבא בר אחא","l": "א","b": "אמורא ארץ ישראלי בדור הראשון. מסר בשם רבי (ירו', ברכות פ\"א ה\"ו). מצינו שירד לבבל (שם). מאמרו המפורסם: \"אין אתה יכול לעמוד על אופיה של אומה זו, נתבעין לעגל ונותנין, נתבעין למשכן ונותנין\" (ירו', שקלים פ\"א ה\"א).","cat": "sage"},{"i": 31,"n": "אבא בר אחא כרסלא","l": "א","b": "הוא אבי אביו של רב. (סנהדרין ה' ע\"א).","cat": "sage"},{"i": 32,"n": "אבא בר איבו","l": "א","b": "הוא רב. ושם אביו היה איבו (סנהדרין ה' ע\"א). שמו של רב הוא אבא, כך פירש הרשב\"ם \"אבא כך שמו של רב אלא בכבוד קורין אותו רב בבבל\" (פסחים קי\"ט ע\"ב ד\"ה: אבא) ורש\"י סובר שאבא זה לשון חשיבות: \"ושמואל היה קורא לרב אבא לכבודו\" (ברכות מ\"ז ע\"א רש\"י ד\"ה: אילו) וכתבו התוספות: \"אמר שמואל ומודה לי אבא לא כמו שפירש בקונטרס לשון חשיבות אלא כך היה שמו של רב כדפירש 'בערוך' בערך אבא\" (יבמות נ\"ז ע\"ב ד\"ה: אמר). ומצינו שקראו לו רב (יומא כ' ע\"ב: חולין נ\"ד ע\"א).","cat": "sage"},{"i": 33,"n": "רבי אבא בר אילעי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. ר' זירא מסר בשמו. (ירו', ר\"ה פ\"ד ה\"י).","cat": "sage"},{"i": 34,"n": "ר' אבא בר אלישע","l": "א","b": "מובא בבראשית רבה (פ\"פ - ז').","cat": "sage"},{"i": 35,"n": "ר' אבא בר אמי","l": "א","b": "מובא בב\"ר (רפ\"ה), ר' ברכיה מאמוראי א\"י בדור הרביעי מסר בשמו.","cat": "sage"},{"i": 36,"n": "רבי אבא בר ביזנא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי: תלמידו של רבי אסי ומסר הלכה מרבו, בשם רבי יוחנן (ירו', ב\"ק פ\"ה ה\"ז).","cat": "sage"},{"i": 37,"n": "אבא בר בנימין","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (שביעית פ\"ו ה\"ג). חברו של רבי אבהו (שם).","cat": "sage"},{"i": 38,"n": "אבא בר בר חנא","l": "א","b": "הוא רבה בר בר חנא.","cat": "sage"},{"i": 39,"n": "אבא בר בר חנה","l": "א","b": "מובא בירושלמי (ברכות פ\"ב ה\"א), והוא רבה בר בר חנה [אבא הוא רבה]. וכן פרשב\"ם (ב\"ב ע\"ד ע\"א).","cat": "sage"},{"i": 40,"n": "ר' אבא בר בריה דר' חייא בר אבא","l": "א","b": "מובא בירושלמי (שבת פ\"ג ה\"ד). ט\"ס וצ\"ל: ר' אבא בריה דר' חייא בר אבא.","cat": "sage"},{"i": 41,"n": "ר' אבא בר גרשון","l": "א","b": "מוזכר בירושלמי (תרומות פ\"י ה\"ו). נראה שזהה לרב אידי בר אידי בר גרשום. וע\"ע ר' אידי בר גרשום.","cat": "sage"},{"i": 42,"n": "ר' אבא בר המנונא","l": "א","b": "אמורא בדור השלישי. מסר בשם רב אדא בר אחא [אדא זהה לאהבה] (ירו', גיטין פ\"ח ה\"ג).","cat": "sage"},{"i": 43,"n": "רבי אבא בר זבדא","l": "א","b": "מובא בבבלי (שבת ס' ע\"ב), והוא רבי אבא בר זבדי.","cat": "sage"},{"i": 44,"n": "ר' אבא בר זבדי","l": "א","b": "אמורא בדור השני - השלישי. בבבל למד לפני רב (ירו', ב\"מ פ\"ב ה\"ד). לאחר פטירת רב למד לפני רב הונא יחד עם חבריו רב גידל, ר' חלבו ורב ששת (יבמות ס\"ד ע\"ב). עלה לארץ ישראל, ומשם שלח שאלותיו לרב הונא (גיטין פ\"ו ע\"ב). היה תלמידו של רבי חנינא (ירו', יבמות ספ\"ו). וחברו של רבי אלעזר (שם). לאחר פטירת ר\"א נחשב כאחד מחשובי חכמי א\"י. היה הפותח בהלכה ור' אמי ור' אסי החותמים (ירו', ר\"ה פ\"ב ה\"ה). האריך ימים, שהרי רבא בצעירותו שלח אליו לברר קושיא (ב\"מ ט\"ז ע\"א). היו לו שני אחים חכמים: ר' יהודה (ירו', קידושין פ\"ד ה\"ב) ור' סימון (ירו', ב\"ב רפ\"ג).","cat": "sage"},{"i": 45,"n": "רבי אבא בר זבינא","l": "א","b": "מובא בירושלמי (דמאי פ\"א ה\"ג). ע\"ע ר' אבא בר זמינא.","cat": "sage"},{"i": 46,"n": "ר' אבא בר זוטרא","l": "א","b": "אמורא ארץ ישראלי בדור השני. תלמידם של ר' חנינא ור' יהושע בן לוי (ירו', גיטין פ\"ד ה\"ד). מתורגמן של ר' יוחנן (ירו', נדרים פ\"י ה\"ח). נראה, שירד לבבל לתקופה מסוימת ולמד שם אצל שמואל (ירו', יבמות פ\"ד הי\"א). ר' זירא מסר בשמו (ירו', שבת פי\"ד ה\"ד).","cat": "sage"},{"i": 47,"n": "אבא בר זימנא","l": "א","b": "ע\"ע ר' אבא בר זמינא.","cat": "sage"},{"i": 48,"n": "ר' אבא בר זמינא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זירא (ירו', ברכות פ\"ז ה\"ג). גם אביו זמינא היה חכם, והתגורר בעיר צור (ירו', בכורים פ\"ג ה\"ג). פרנסתו היתה מתפירת מנעלים. עמד בנסיון בעבדו אצל גוי, שאיים עליו להורגו אם לא יאכל נבלה (ירו', שביעית פ\"ד ה\"ב). מאמרו הנודע: \"אין הוון קדמאי בני מלאכים אנן בני אנש\" (ירו', דמאי פ\"א ה\"ג) מובא גם בבבלי: \"אם ראשונים בני מלאכים אנו בני אנשים\" (שבת קי\"ב ע\"ב).","cat": "sage"},{"i": 49,"n": "ר' אבא בר זעירא","l": "א","b": "מובא במדרש תהלים (פכ\"ח - ד'). אולי הוא אהבה בר זעירא.","cat": "sage"},{"i": 50,"n": "רב אבא בר חוניא","l": "א","b": "אמורא ארץ ישראלי. נראה שחי בדור הרביעי - החמישי. נותרו ממנו מאמרים באגדה (קה\"ר פ\"א - ב).","cat": "sage"},{"i": 51,"n": "אבא בר חייא","l": "א","b": "מובא בירושלמי (כלאים פ\"ב ה\"א). והוא רבה בר חייא קטוספאה.","cat": "sage"},{"i": 52,"n": "רבי אבא בר חייא בר אשי","l": "א","b": "מובא בירו' (שבת פ\"ז ה\"ב). יש גורסים שט\"ס וצ\"ל: ר' אבא ב\"ר: ב\"ר הם ראשי תיבות של \"בשם רב\" חייא בר אשי.","cat": "sage"},{"i": 53,"n": "ר' אבא בר חיננא","l": "א","b": "מובא בירושלמי (גיטין פ\"ג ה\"א), יחד עם רב אסי ורב יוחנן.","cat": "sage"},{"i": 54,"n": "אבא בר חליפיי בר קריי","l": "א","b": "ע\"ע אבא חליפא קרויא.","cat": "sage"},{"i": 55,"n": "אבא בר חמא","l": "א","b": "אמורא בבלי בדור השני. רב חסדא אמר: \"אמר לי אבא בר חמא\" וכו' (ע\"ז ל\"א ע\"א).","cat": "sage"},{"i": 56,"n": "אבא בר חנן","l": "א","b": "מובא בבבלי (ע\"ז ס' ע\"ב). אולי צ\"ל אבא בר חמא.","cat": "sage"},{"i": 57,"n": "אבא בר חסדא","l": "א","b": "מובא בבבלי (ע\"ז מ\"ט ע\"ב). אולי צ\"ל אבא בר חייא.","cat": "sage"},{"i": 58,"n": "ר' אבא בר טבליי","l": "א","b": "אמורא בבלי בדור השני - השלישי. מסר בשם רב (ירו', ב\"ב פ\"ד ה\"ח).","cat": "sage"},{"i": 59,"n": "ר' אבא בר יהודה","l": "א","b": "אמורא שאין לקבוע זמנו. מסר בשם רב (ירו', שבועות רפ\"ג), בשם ר' אחא (ב\"ר כ\"ג - ה'), ובשם ר' יהודה בר סימון (ויק\"ר פ\"ז - ב'). ממאמריו: \"כל מה שפסל הקב\"ה בבהמה, הכשיר באדם\" (ויק\"ר פ\"ז - ב').","cat": "sage"},{"i": 60,"n": "ר' אבא בר יודן","l": "א","b": "הוא ר' אבא בר יהודה.","cat": "sage"},{"i": 61,"n": "ר' אבא בר יוסף","l": "א","b": "הוא רבא, ע\"ע. כך מובא בבבלי (ביצה ח' ע\"ב), ובירושלמי (ביצה פ\"א ה\"ג).","cat": "sage"},{"i": 62,"n": "רב אבא בר יוסף בר רבא","l": "א","b": "אמורא בבלי בדור החמישי - הששי. בן בנו של רבא. עמד בקשר עם רב כהנא (חולין קמ\"א ע\"א).","cat": "sage"},{"i": 63,"n": "ר' אבא בר ימינא","l": "א","b": "מובא בב\"ר (פ\"ס - ח'), והוא ר' אבא בר זמינא.","cat": "sage"},{"i": 64,"n": "רבי אבא בר יסא","l": "א","b": "מובא בירושלמי (סנהדרין פ\"ד ה\"ח). יש גורסין ר' אבא [בשם] ר' יסא [ר' יסא הוא ר' אסי] בשם ר' יוחנן.","cat": "sage"},{"i": 65,"n": "ר' אבא בר יעקב","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (כתובות ע\"ז ע\"א). כן מסר בשם רבי יצחק רובא (ירו', ברכות פ\"ו ה\"א).","cat": "sage"},{"i": 66,"n": "ר' אבא בר יצחק","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב חסדא (מנחות ק\"י ע\"א).","cat": "sage"},{"i": 67,"n": "ר' אבא בר ירמיה","l": "א","b": "מובא בבבלי (נדה י\"א ע\"ב). ע\"ע רבה בר ירמיה.","cat": "sage"},{"i": 68,"n": "ר' אבא בר כהן","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. נראה שהיה דיין בכפר עקביה ליד צפת (ירו', נזיר פ\"ט ה\"ג). תלמידם של ר' יוסי (ירו', ביצה פ\"ה ה\"ב), ושל ר' יונה (ירו', מע\"ש פ\"ב ה\"ג). מסר שמועה בשם רב ששת (ירו', שבת פ\"ו ה\"א).","cat": "sage"},{"i": 69,"n": "ר' אבא בר כהנא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. כן מסר בשם חכמי בבל. רב (ירו', סוטה פ\"ט הי\"ג) ור' חייא בר אשי (ירו', ברכות פ\"ו ה\"ו). קיבל מרבי חנינא (שבת קכ\"א ע\"ב). ומסר בשם ר' יוחנן (ב\"ר פכ\"ו - ז') ובשם רבי אליעזר (ירו', ברכות רפ\"ו). היה חברו של ר' לוי ושל ר' זירא (ירו', מעשרות ספ\"ג). ר\"ז היה מקנטרו על היותו בעל אגדה ודרשן (ירו', מעשרות ספ\"ג). נפטר אחרי ר\"ז (קה\"ר פ\"א - פ\"ד).","cat": "sage"},{"i": 70,"n": "ר' אבא בר כהנא בר יודן","l": "א","b": "מובא בשהש\"ר (ספ\"ז). יש גורסין ר' אבא בר יודן.","cat": "sage"},{"i": 71,"n": "ר' אבא בר לוי","l": "א","b": "אמורא. זמנו ומקומו אינם ידועים. מובא בבבלי (כתובות נ\"ז ע\"ב).","cat": "sage"},{"i": 72,"n": "ר' אבא בר מדיא","l": "א","b": "מוזכר במדרש שמואל (פ\"א - ז'). יש גורסין ר' אבא בר מריא.","cat": "sage"},{"i": 73,"n": "ר' אבא בר מימי","l": "א","b": "מובא (שהש\"ר פ\"א פ' נאוו) \"כגון ר' אבא בר מימי וחביריו\".","cat": "sage"},{"i": 74,"n": "ר' אבא בר מינא","l": "א","b": "מובא בירושלמי (ב\"מ פ\"ה ה\"א), והוא רבי אבא בר אבינא.","cat": "sage"},{"i": 75,"n": "ר' אבא בר ממל","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. קיבל מר' אושעיא (ירו', ב\"ק פ\"ב ה\"א). וכן מסר בשם רב (ב\"ב ל\"ח ע\"א). וכשמלך ר' אמי היה מראשי הדור (ב\"ב נ\"ט ע\"א). נראה, שקיבל גם מר' אמי (יבמות ק\"ה ע\"א). ר' זירא שאל ממנו (חולין קכ\"ט ע\"א). נפטר לפני ר\"ז (ירו', שבועות פ\"ג ה\"ד).","cat": "sage"},{"i": 76,"n": "ר' אבא בר מניומי","l": "א","b": "מובא בבבלי (גיטין כ\"ט ע\"ב), והוא אבא בר מרתא.","cat": "sage"},{"i": 77,"n": "ר' אבא בר מריא","l": "א","b": "מובא במדרש שמואל (פ\"א - ז'). יש גורסין ר' אבא בר מדיא.","cat": "sage"},{"i": 78,"n": "אבא בר מרתא","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. והוא אבא בר מניומי. נקרא גם ע\"ש אמו, כנראה משום שהודות לסגולה שעשתה לו אמו, נתרפא מנשיכת כלב שוטה. היה תלמידו של רב יהודה (שבת קכ\"א ע\"ב). מצינו ששאל מאביי (ביצה כ\"ב ע\"א). בא לנחם את רבא באבלו (מו\"ק כ\"ו ע\"ב).","cat": "sage"},{"i": 79,"n": "ר' אבא בר נגרי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (פאה פ\"ה ה\"ד).","cat": "sage"},{"i": 80,"n": "ר' אבא בר נתן","l": "א","b": "מובא בירושלמי (מו\"ק פ\"ג ה\"ד), והוא רבה בר נתן.","cat": "sage"},{"i": 81,"n": "ר' אבא בר סיסי","l": "א","b": "מובא בילקוט ירמיה (רמז שו).","cat": "sage"},{"i": 82,"n": "ר' אבא בר עילאי","l": "א","b": "אמורא בדור השלישי. מסר בשם רב (ירו', ר\"ה פ\"ד ה\"י), חברם של ר' ברכיה ור' חלבו (ירו', תענית פ\"ג ה\"ט). ר\"ז קבל ממנו (ירו', ר\"ה פ\"ד ה\"י).","cat": "sage"},{"i": 83,"n": "ר' אבא בר פפא","l": "א","b": "אמורא בבלי בדור השלישי. חברו של ר' זירא. ר\"ז ביקשו שבדרכו לארץ ישראל ישאל שאלה את ר' יעקב בר אידי (ב\"מ מ\"ג ע\"ב). \"יוחסין\" סובר שהוא ר' אבא הכהן בר פפא.","cat": "sage"},{"i": 84,"n": "רבי אבא בר פפי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (ירו', גיטין רפ\"ה). רבו של רבי מנא (ירו', שבת פ\"ג ה\"א). חברו של רבי יהושע דסיכנון, ושניהם מסרו בשם לוי (ירו', יומא פ\"ד ה\"א). נהג לדרוש מקראות (ירו', סוטה פ\"א ה\"ז).","cat": "sage"},{"i": 85,"n": "אבא בר קוריה","l": "א","b": "מובא בב\"ר (פי\"ט - ג').","cat": "sage"},{"i": 86,"n": "אבא בר קפרא","l": "א","b": "מובא בקה\"ר (פ\"א ספ\"ג). אולי הוא בר קפרא.","cat": "sage"},{"i": 87,"n": "אבא בר רב הונא","l": "א","b": "מובא בירושלמי (תרומות פ\"א ה\"ד). ע\"ע רבה בר רב הונא.","cat": "sage"},{"i": 88,"n": "רב אבא בר שומני","l": "א","b": "אמורא בבלי בדור השני. חברו של רב מנשיא בר ירמיה, שהיה תלמידו של רב (עירובין ס\"ד ע\"א).","cat": "sage"},{"i": 89,"n": "רבי אבא בר שילא","l": "א","b": "מוזכר בבבלי (גיטין כ\"ו ע\"ב), והוא רבה בר שילא (כמובא בכתובות מ' ע\"א).","cat": "sage"},{"i": 90,"n": "ר' אבא בר שמואל","l": "א","b": "מובא בבבלי (ב\"ב ט\"ו ע\"ב). ע\"ע רבה בר שמואל.","cat": "sage"},{"i": 91,"n": "ר' אבא בר תחליפא","l": "א","b": "נראה, שצ\"ל ר' אחא בר תחליפא, והיימן כתב: \"ובאמת לא היה אמורא כזה\".","cat": "sage"},{"i": 92,"n": "רבי אבא בריה דרב ביבי","l": "א","b": "מובא בילקוט שמעוני (פ' אמור רמז תרמ\"ה).","cat": "sage"},{"i": 93,"n": "אבא בריה דרב בנימין בר חייא","l": "א","b": "מובא בבבלי (ר\"ה ל\"ה ע\"א). ע\"ע אבא בריה דרב מנימין בר חייא.","cat": "sage"},{"i": 94,"n": "אבא בריה דרב מנימין בר חייא (2)","l": "א","b": "אמורא בבלי בדור השלישי. נראה, שהיה תלמידו של רב הונא בר חייא (חולין פ' ע\"א). יש שיבושים בשמו בכמה מקומות בש\"ס, שכן המאמר \"עם שאחורי כהנים\" הנמסר בשמו (בסוטה ל\"ח ע\"ב), נמסר גם בשם אבא בריה דרב בנימין בר חייא (ר\"ה ל\"ה ע\"א), ובשם אביי בר בנימין (ירו', גיטין פ\"ה ה\"ט) ובשם אביי בי רבי בנימין (ירו', ברכות פ\"ה ה\"ד). ונראה שכולם אותו חכם.","cat": "sage"},{"i": 95,"n": "ר' אבא בריה דרב נחמן","l": "א","b": "מובא בירושלמי (ערלה פ\"ב ה\"ג). ע\"ע רבה בר נחמני.","cat": "sage"},{"i": 96,"n": "אבא בריה דרבה בר רב הונא","l": "א","b": "אמורא בדור הרביעי. בן בנו של רב הונא (סוטה מ\"ט ע\"א), והוא רבא בריה דרבה בר רב הונא.","cat": "sage"},{"i": 97,"n": "רבי אבא בריה דרבי חייא בר אבא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של רבי חייא בר אבא (חולין פ\"ו ע\"ב). חברו של רבי זירא (מו\"ק כ\"ב ע\"א). שניהם למדו אצל רבי אמי (חולין פ\"ו ע\"ב). הקשה לרבי אבהו (פסחים נ\"ט ע\"ב). נראה שלמד גם לפני ר' יוחנן (תמורה י\"ד ע\"ב). רבנן שיבחוהו על נוסח ברכה שלו בברכת האבל (ירו', ברכות ספ\"ז).","cat": "sage"},{"i": 98,"n": "ר' אבא בריה דר' יוסי בן חלפתא","l": "א","b": "תנא, והוא הוא רבי מנחם בר' יוסי בן חלפתא ומובא: (ירו', נדרים פי\"א ה\"א).","cat": "sage"},{"i": 99,"n": "ר' אבא בר' זירא","l": "א","b": "מובא בירושלמי (עירובין פ\"ו ה\"ז), והוא אהבה בריה דר' זירא.","cat": "sage"},{"i": 100,"n": "אבא גוריא","l": "א","b": "תנא. נראה שהיה בדור השלישי - הרביעי. משמו אמרו אבא גוריין איש צדיין וכן רבי יהודה בר אלעאי (קידושין פ\"ב ע\"א).","cat": "sage"},{"i": 101,"n": "אבא גוריין איש צדיין","l": "א","b": "תנא. נראה שהיה בדור הרביעי - החמישי. מסר משמו של אבא גוריא (קידושין פ\"ב ע\"א).","cat": "sage"},{"i": 102,"n": "רבי אבא דמן חיפא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מוזכר פעם בבבלי שר' אבא ור' אסי באו אליו לביקור (שבת מ\"ה ע\"ב).","cat": "sage"},{"i": 103,"n": "רבי אבא דמן כיפה","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - השישי. תלמידו של רבי יונה (ירו', סוכה פ\"ג ה\"י).","cat": "sage"},{"i": 104,"n": "ר' אבא דמן כיפה","l": "א","b": "מובא בירושלמי: \"קומי רבי יונה\" (סוכה פ\"ג ה\"י). \"פני משה\" מפרש שהיה חכם בשם זה, אך \"קרבן העדה\" פירש שר' אבא אמר: 'כוף ידך', ואם כן אין זה חכם אחר מאשר ר' אבא ב'.","cat": "sage"},{"i": 105,"n": "רבי אבא דמן עכו","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. נראה, שעבר לדור בקיסרין. כשרצו למנות את רבי אבהו לראש, המליץ שימנו את רבי אבא דמן עכו במקומו (סוטה מ' ע\"א), אבל לא מצינו שנתמנה לראש. מובא בבבלי (כתובות כ\"ב ע\"א): \"ורבי זירא אמר: 'הא מלתא מרבי אבא שמיע לי, ואי לאו רבי אבא דמן עכו שכחתה'\". היה עני מרוד (סוטה שם).","cat": "sage"},{"i": 106,"n": "רבי אבא דמן קיסרי","l": "א","b": "מובא בבבלי (תענית ט\"ו ע\"ב). גירסת הרי\"ף: ר' אדא דמן קיסרי.","cat": "sage"},{"i": 107,"n": "רבי אבא האדומי","l": "א","b": "מובא במד' תנחומא (בראשית ז'). ע\"ע ר' אבא סמוקה.","cat": "sage"},{"i": 108,"n": "אבא הדורש","l": "א","b": "תנא. שאין לקבוע זמנו המדוייק. מובא בספרי (האזינו).","cat": "sage"},{"i": 109,"n": "רב אבא הונא הכהן בר אבין","l": "א","b": "מובא במד\"ר (פ\"ג - ז'). זהה שהוא רב הונא הכהן בר אבין (ע\"ע).","cat": "sage"},{"i": 110,"n": "אבא הושעיא איש טרייא","l": "א","b": "מובא בירושלמי (ב\"ק פ\"י ה\"י). ע\"ע אבא אושעיא איש טורייא.","cat": "sage"},{"i": 111,"n": "רבי אבא הכהן","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. חברו של רבי יוסי הכהן (ר\"ה ט\"ו ע\"ב), ומסר בשמו: \"מעשה ומתו בניו של ר' יוסי בן רבי חנינא\" (תענית י\"ג ע\"א).","cat": "sage"},{"i": 112,"n": "ר' אבא הכהן בר פפא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' יוסי בר זבידא (מ\"ר פט\"ו - ז').","cat": "sage"},{"i": 113,"n": "ר' אבא הכהן בר' אליעזר","l": "א","b": "מובא בב\"ר (פ\"פ - ד').","cat": "sage"},{"i": 114,"n": "רבי אבא זוטי","l": "א","b": "מובא בבבלי (מנחות ט\"ו ע\"ב). ע\"ע רבה זוטי.","cat": "sage"},{"i": 115,"n": "אבא חילפא בן קרויא","l": "א","b": "מובא בתוספתא (מע\"ש רפ\"ד [צוקערמאנדל]). ע\"ע אבא חליפא קרויא.","cat": "sage"},{"i": 116,"n": "אבא חליפא קרויא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי חייא בר אבא (ב\"ב קכ\"ג ע\"א). רבן גמליאל (בנו של רבי יהודה נשיאה השני) הלך אליו להתפלל (מד' תהלים הישן פ\"כ) שמו מובא בכמה כתובים שונים.","cat": "sage"},{"i": 117,"n": "אבא חלפי","l": "א","b": "תנא שזמנו אינו ידוע. מובא במסכת דרך ארץ (פ\"א), שם מסר משום אביו אבא חגרא.","cat": "sage"},{"i": 118,"n": "אבא חלפתא","l": "א","b": "הוא רבי חלפתא, אביו של רבי יוסי בן חלפתא. ומצינו: \"אמר רבי יוסי: 'מודה אבא חלפתא בזה שמותר'\" (בכורות כ\"ו ע\"א) רש\"י שינה בד\"ה וכתב: \"אמר רבי יוסי מודה אבא ששמו חלפתא\". ובמקום אחר כתב רש\"י בד\"ה: אלו היה אבא חלפתא: \"אביו של רבי יוסי\" (מעילה י\"ז ע\"ב).","cat": "sage"},{"i": 119,"n": "אבא חלפתא איש כפר חנניא","l": "א","b": "תנא בדור החמישי. מובא באבות (פ\"ג מ\"ו). מאמרו שם: \"עשרה שיושבין ועוסקין בתורה שכינה שרויה ביניהם\". תלמידו של רבי מאיר (ב\"מ צ\"ד ע\"א), ושל שמעון בן חנניה (תוספתא כלים פ\"ד ה\"ט).","cat": "sage"},{"i": 120,"n": "אבא חלקיה","l": "א","b": "חסיד גדול שחי בזמן בית המקדש השני. בן בנו של חוני המעגל. מובא בבבלי (תענית כ\"ג ע\"א), שם מסופר על חסידותו והקפדתו היתרה בכל דרכי התנהגותו. כשהיו זקוקים לגשמים, שלחו אליו שיתפלל (שם). אשתו הקפידה מאד על מתן לחם לעניים, ובזכות תפילתה ירד גשם בטרם נענתה תפילת בעלה (שם). עליו אמרו: \"פועל צדק כגון אבא חלקיהו\" (מכות כ\"ד ע\"א).","cat": "sage"},{"i": 121,"n": "אבא חלקיה מן קרויה","l": "א","b": "תנא שזמנו אינו ידוע. מובא בתוספתא (מע\"ש פ\"ד ה\"ג). ובתוספתא צוקערמאנדל הגירסא: אבא חילפא מן קרויא.","cat": "sage"},{"i": 122,"n": "אבא חנן","l": "א","b": "תנא בדור השלישי - הרביעי. מסר הרבה בשם רבי אליעזר (יבמות ס\"ד ע\"א). וכן מסר פעם בשם ר' יהושע (נדה כ\"ט ע\"א). היה חברו של ר' שמעון שזורי (נזיר מ\"ה ע\"א).","cat": "sage"},{"i": 123,"n": "רבי אבא חסידא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי מובא בירושלמי (נדרים פ\"ח ה\"א). אומר בשם רבי זירא (שם).","cat": "sage"},{"i": 124,"n": "אבא יהודה","l": "א","b": "חי בדור השני - השלישי לתנאים. מובא בירושלמי (הוריות פ\"ג ה\"ד). חסיד ובעל צדקה. כשירד מנכסיו ולא היה לו לתת צדקה לחכמים, יעצה לו אשתו, שהיתה צדקת, למכור חצי שדהו שנשאר ויתן להם צדקה. וכך עשה, ובירכוהו ר' אליעזר ור' יהושע ור' עקיבא, ועושרו חזר אליו (שם).","cat": "sage"},{"i": 125,"n": "אבא יודן","l": "א","b": "מובא בב\"ר (פ\"י - ח'), והוא אבדן תלמידו הגדול דרב: תוספות כתבו שאבדן הוא אבא יודן בירושלמי (יבמות ק\"ה ע\"ב).","cat": "sage"},{"i": 126,"n": "אבא יודן איש ציידן","l": "א","b": "תנא בדור השלישי. העיד בשם רבי אליעזר (תוספתא אהלות פי\"ח ז').","cat": "sage"},{"i": 127,"n": "אבא יוסי","l": "א","b": "מובא בבבלי (מנחות ל\"ג ע\"ב), וצ\"ל: רב יוסף, כמו ברי\"ף, והוא רב יוסף מחכמי הסבוראים.","cat": "sage"},{"i": 128,"n": "אבא יוסי בן אבא (2)","l": "א","b": "נראה, שהיה בסוף תקופת התנאים. מרבותיו של ר' יוחנן. \"א\"ר יוחנן: 'משום אבא יוסי בן אבא שמיע לי'\" (חולין צ\"ז ע\"א).","cat": "sage"},{"i": 129,"n": "אבא יוסי בן דוסאי","l": "א","b": "מובא במשנה (מכשירין פ\"ב מ\"י), וצ\"ל אבא יוסי בן דוסתאי.","cat": "sage"},{"i": 130,"n": "אבא יוסי בן דוסתאי","l": "א","b": "תנא בדור הרביעי. מסר בשם רבי אליעזר (תוספתא פאה פ\"ד ב'), ובשם רבי יוסי הגלילי (שם פ\"ו ו'). רבי מסר בשמו (זבחים קט\"ז ע\"ב).","cat": "sage"},{"i": 131,"n": "אבא יוסי בן חנין","l": "א","b": "מובא בבבלי (פסחים נ\"ז ע\"א): \"אבא שאול בן בטניס משמו\". \"דק\"ס\" גורס: אבא יוסי בן חנן. אם אין שיבוש בשמו, הרי שחי בדור הראשון לתנאים.","cat": "sage"},{"i": 132,"n": "אבא יוסי בן חנן","l": "א","b": "תנא. מובא במשנה (מדות פ\"ב מ\"ו). גיר' \"דק\"ס\": אבא יוסי בן חנין.","cat": "sage"},{"i": 133,"n": "אבא יוסי בן יוחנן","l": "א","b": "מובא בבבלי (כריתות ו' ע\"ב). \"אבא\" הוא גם לשון כבוד, ואין לדעת מי הוא, שכן יש יוסי בן יוחנן איש ירושלים מחכמי ה\"זוגות\", ויש אבא יוסי בן יוחנן איש ירושלים שאמר משום רבי מאיר (יבמות נ\"ג ע\"ב), ויש אבא יוסי בן יוחנן איש ינוח (ירו', כלאים פ\"ב ה\"ד).","cat": "sage"},{"i": 134,"n": "אבא יוסי בן יוחנן איש יוני","l": "א","b": "הוא אבא יוסי בן יוחנן איש ינוח.","cat": "sage"},{"i": 135,"n": "אבא יוסי בן יוחנן איש ינוח","l": "א","b": "מאחרוני התנאים. מובא בירושלמי יחד עם רבי אלעזר בר' שמעון. (כלאים פ\"ב ה\"ד).","cat": "sage"},{"i": 136,"n": "אבא יוסי בן יוחנן איש ירושלים","l": "א","b": "תנא בדור החמישי. תלמידו של רבי מאיר ואמר משמו (יבמות נ\"ג ע\"ב).","cat": "sage"},{"i": 137,"n": "אבא יוסי בן סימאי","l": "א","b": "בדור המעבר בין התנאים לאמוראים. \"מעשה בשני ת\"ח שהיו באים עם אבא יוסי בן סימאי בספינה וטבעה והשיא רבי נשותיהן\" (יבמות קט\"ו ע\"א).","cat": "sage"},{"i": 138,"n": "אבא יוסי בן קטנותא","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. עליו אמרו: \"משמת אבא יוסי בן קטנותא בטלו חסידים, ולמה נקרא שמו אבא יוסי בן קטנותא? שהיה מקטני חסידים\" (סוף סוטה).","cat": "sage"},{"i": 139,"n": "אבא יוסי בר חנן","l": "א","b": "אמורא ארץ ישראלי בדור הראשון. מסר בשם אבא כהן ברדלא (ספרי דברים פסוק ב').","cat": "sage"},{"i": 140,"n": "אבא יוסי המחוזי","l": "א","b": "תנא בדור השלישי. מובא במכילתא שר' נתן אמר משמו. (פ' בשלח מס' ויהי פ\"ג).","cat": "sage"},{"i": 141,"n": "אבא יוסי התורתי","l": "א","b": "מובא בב\"ר (פל\"ד - י').","cat": "sage"},{"i": 142,"n": "אבא יוסי חלי קופרי איש טבעון","l": "א","b": "תנא בדור הראשון. ר' יהושע מסר משמו (מכשירין פ\"א מ\"ג).","cat": "sage"},{"i": 143,"n": "אבא יוסי חנן איש יוני","l": "א","b": "הוא אבא יוסף בן יוחנן איש ינוח.","cat": "sage"},{"i": 144,"n": "אבא יוסף בן דוסתאי","l": "א","b": "מובא בבבלי (ברכות כ\"ח ע\"א). נראה, שצ\"ל אבא יוסי בן דוסתאי.","cat": "sage"},{"i": 145,"n": "אבא יוסף הבנאי","l": "א","b": "תנא בדור הרביעי. כששאל אבנימוס הגרדי (מחכמי אומות העולם) לחכמים היאך ברא ה' את עולמו, שלחו לו לאבא יוסף הבנאי והוא השיבו (ש\"ר רפ\"ג).","cat": "sage"},{"i": 146,"n": "אבא יוסף החורני","l": "א","b": "תנא בדור השלישי. השיב לר' ישמעאל (תוספתא מקואות ספ\"ג).","cat": "sage"},{"i": 147,"n": "אבא ירמיה","l": "א","b": "תנא שאין לקבוע זמנו המדויק. מסר בשם רבי מאיר (ויק\"ר רפל\"ד).","cat": "sage"},{"i": 148,"n": "אבא כהן בר דלייה","l": "א","b": "ע\"ע אבא כהן ברדלא.","cat": "sage"},{"i": 149,"n": "אבא כהן ברדלא","l": "א","b": "תנא שאין לקבוע זמנו המדויק. היה מן התנאים האחרונים. ר\"ל מסר בשמו את הדין הידוע ש\"ד' אמות של אדם קונות לו בכל מקום\" (ב\"מ י' ע\"א). מובא בירושלמי ושם אבא בר דלייה (ב\"ב פ\"ח ה\"ג).","cat": "sage"},{"i": 150,"n": "אבא מהגרוניא","l": "א","b": "אמורא בבלי בדור השלישי. בנו, רב שמואל בר אבא מהגרוניא, שאל מרבי אבא (ב\"ק ז' ע\"ב). אחר פטירתו של אבא מהגרוניא, נשא רבי אבא את אלמנתו לאשה. (ב\"ק פ\"ח ע\"א).","cat": "sage"},{"i": 151,"n": "אבא מר בר רב אשי","l": "א","b": "מובא בבבלי (סוטה ל\"ח ע\"ב). אולי צ\"ל מר בר רב אשי.","cat": "sage"},{"i": 152,"n": "אבא מר בריה דרב פפא","l": "א","b": "אמורא בבלי בדור הששי. אביו רב פפא שיבחו ואמר עליו: \"כגון אבא מר ברי דקים לי בגוויה [שאינו משקר]\" (כתובות פ\"ה ע\"א), ולכבודו הפסיק רב פפא את סעודתו לפנים משורת הדין (ברכות מ\"ה ע\"ב). היה קשור בעסקי אביו (ב\"מ ס\"ט ע\"ב).","cat": "sage"},{"i": 153,"n": "ר' אבא מרומניא","l": "א","b": "מובא במ\"ר (פכ\"ב - ח'). זהה לר' אבא סרונגיא (ע\"ע).","cat": "sage"},{"i": 154,"n": "אבא מרי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' חזקיה (ירו', סוטה פ\"ו ה\"א). חברם של ר' אליעזר [בר' יוסי האמורא] (ירו', ביצה פ\"א ה\"ז), ור' מתניא (שם).","cat": "sage"},{"i": 155,"n": "ר' אבא מרי אחוי דר' יוסי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. אחיו של האמורא רבי יוסי (ירו', ברכות פ\"ז ה\"א).","cat": "sage"},{"i": 156,"n": "ר' אבא מרי בבלייה","l": "א","b": "אמורא שאין פרטים עליו. מובא פעם אחת בירושלמי (מגילה פ\"ב ה\"ה) ונראה שאין הוא אבא מרי הארץ ישראלי, שכן מודגש \"בבלייה\", שהיה מבבל.","cat": "sage"},{"i": 157,"n": "ר' אבא מרי בצלאה","l": "א","b": "מובא במדרש שמואל (פי\"ג).","cat": "sage"},{"i": 158,"n": "אבא מרי ריש גלותא","l": "א","b": "ראש הגולה בבבל בדור הרביעי לאמוראים. מובא בבבלי (נדה ס\"ז ע\"ב).","cat": "sage"},{"i": 159,"n": "אבא נהוראי","l": "א","b": "נראה, שהיה מן התנאים. רבי חנינא ורבי מרינוס מסרו משמו (ב\"ר פצ\"א - ט').","cat": "sage"},{"i": 160,"n": "ר' אבא סדרונגיא","l": "א","b": "מובא במ\"ר (פי\"ד - ד'). זהה לר' אבא סרונגיא (ע\"ע).","cat": "sage"},{"i": 161,"n": "ר' אבא סדרוניא","l": "א","b": "מובא במד\"ר (פ' י\"ד). זהה לר' אבא סרונגיא (ע\"ע).","cat": "sage"},{"i": 162,"n": "אבא סוראה","l": "א","b": "אמורא בבלי בדור הרביעי. חותנו של רב פפא (כתובות ל\"ט ע\"ב). רב פפא השיא לבנו את אחות אשתו, היא בת אבא סוראה (כתובות נ\"ב ע\"ב).","cat": "sage"},{"i": 163,"n": "אבא סימי","l": "א","b": "מובא בירושלמי (יבמות פט\"ז ה\"ה), רבא בר זבדא בשם רב: \"מעשה באבא סימי ששקעה ספינתו בים\". נראה, שהוא אבא יוסי בן סימאי (ע\"ע).","cat": "sage"},{"i": 164,"n": "ר' אבא סלא רבא","l": "א","b": "אמורא בדור הרביעי. מובא בבבלי (כתובות קי\"א ע\"א). אביי השיב על קושייתו.","cat": "sage"},{"i": 165,"n": "ר' אבא סמוקה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (ברכות פ\"ט ה\"א). ר' חלבו ור' ברכיה מסרו בשמו (שם). מאמרי אגדה שלו מובאים בירושלמי.","cat": "sage"},{"i": 166,"n": "אבא סמוקיד (2)","l": "א","b": "מובא במ\"ר (פ\"ג - ז'). ר' ברכיה מסר בשם ר' חלבו בשמו.","cat": "sage"},{"i": 167,"n": "ר' אבא סמיקא","l": "א","b": "מובא בירושלמי: ר' ברכיה ור' חלבו בשם ר' אבא סמיקא\" (ברכות פ\"ט ה\"ג). ונראה, שהוא ר' אבא סמוקה (ע\"ע).","cat": "sage"},{"i": 168,"n": "ר' אבא סנגוריא","l": "א","b": "מובא בתנחומא (מטות - ז'). זהה לר' אבא סרונגיא (ע\"ע).","cat": "sage"},{"i": 169,"n": "אבא סקרא","l": "א","b": "ראש בריוני ירושלים בזמן חורבן בית שני. בן אחותו של רבן יוחנן בן זכאי. עזר לריב\"ז לצאת מירושלים אל הרומאים (גיטין נ\"ו ע\"א). ע\"ע בן בטיח.","cat": "sage"},{"i": 170,"n": "ר' אבא סרונגיא","l": "א","b": "אמורא ארץ ישראלי שזמנו אינו ידוע. מובא בב\"ר (פ\"א - ו'). נמנה עם בעלי האגדה. שמו נשתבש בכמה אופנים.","cat": "sage"},{"i": 171,"n": "ר' אבא סרונגלא","l": "א","b": "מובא בפסיקתא רבתי (פ' ביום השמיני). זהה לר' אבא סרונגיא (ע\"ע).","cat": "sage"},{"i": 172,"n": "אבא פנימון","l": "א","b": "מובא בירושלמי (תרומות פ\"ג ה\"ג). לפי לשון הירושלמי יתכן שהוא אבא בנימין (ע\"ע).","cat": "sage"},{"i": 173,"n": "אבא צידוני","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בקה\"ר (פ\"ז - ג'). נזכר יחד עם תלמידי ר' אבא (שם).","cat": "sage"},{"i": 174,"n": "אבא קוריי","l": "א","b": "(מובא ב\"ר פי\"ט).","cat": "sage"},{"i": 175,"n": "ר' אבא קרתיגנאה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (שבועות פ\"ג ה\"א). ר' אלעאי מתרץ שם קושייתו.","cat": "sage"},{"i": 176,"n": "רבי אבא קרתיגניא","l": "א","b": "מובא בירושלמי (כלאים פ\"א ה\"ט). זהה לר' אבא קרתיגנאה (ע\"ע).","cat": "sage"},{"i": 177,"n": "אבא שאול (2)","l": "א","b": "תנא בדור השני. נראה, שזכה לראות את המקדש (מדות פ\"ב מ\"ה). קיבל מר' יוחנן בן זכאי (אבות פ\"ב מ\"ח). \"ארוך בדורו הוה\" (נדה כ\"ד ע\"ב).","cat": "sage"},{"i": 178,"n": "אבא שאול בן אמא מרים","l": "א","b": "תנא בדור החמישי או בדור קודם. שמואל מסר משמו (כתובות פ\"ז ע\"א).","cat": "sage"},{"i": 179,"n": "אבא שאול בן בטנית","l": "א","b": "תנא קדמון. נראה, שחי שני דורות לפני החורבן לפי: \"מעשה בימי אביו של רבי צדוק ובימי אבא שאול בן בטנית\" (שבת קנ\"ז ע\"א) - ורבי צדוק צם 04 שנה לפני החורבן (גיטין נ\"ו ע\"א): וא\"כ הם חיו שני דורות לפני החורבן. ושניהם היו חנוונים ומסופר על חסידותם (ירו', ביצה פ\"ג ה\"ח). וכשחלה באו חכמים לבקרו (שם). לפני פטירתו ציוה לבניו לקברו למרגלות אביו ולהתיר הציציות מטליתו (שמחות פי\"ב). רש\"י כתב: \"שהיה חכם גדול ובאים רבים לשאול הימנו\" (ביצה כ\"ט ע\"א ד\"ה: תנא).","cat": "sage"},{"i": 180,"n": "אבא שאול בן חוני","l": "א","b": "מובא בתוספתא (מקואות פ\"ג).","cat": "sage"},{"i": 181,"n": "אבא שאול בן ננס","l": "א","b": "מובא באבות דר\"נ (רפ\"ט).","cat": "sage"},{"i": 182,"n": "אבא שאול בר נש","l": "א","b": "מובא בבבלי (נדה כ\"ה ע\"ב).","cat": "sage"},{"i": 183,"n": "אבא שאול גבל דבי רבי","l": "א","b": "מובא בבבלי (פסחים ל\"ד ע\"א). אין ראיה מכרעת שהיה חכם.","cat": "sage"},{"i": 184,"n": "אבא שאול מבית מרמשא","l": "א","b": "כך היתה הגרסא לפני ה\"יוחסין\" (אבות פ\"ב מ\"ח): שכתב שהיה תלמיד חבר לרבי יוחנן בן זכאי (אם כן, היה בדור הראשון - השני לתנאים).","cat": "sage"},{"i": 185,"n": "אבא תחנא חסידא","l": "א","b": "מובא בקה\"ר (פ\"ט - ז'). שם מסופר עליו, שערב שבת עם חשכה הכניס מוכה שחין לעיר ונעשה לו נס והשמש זרחה שוב, להראות שעדיין לא היה שבת.","cat": "sage"},{"i": 186,"n": "אבא תנחומא","l": "א","b": "מובא במדרש תהלים (פ\"א - ק'), והוא ר' תנחומא.","cat": "sage"},{"i": 187,"n": "ר' אבדומא","l": "א","b": "הוא אבדימי.","cat": "sage"},{"i": 188,"n": "ר' אבדומא דמן חיפה","l": "א","b": "מובא בירושלמי (מו\"ק פ\"ג ה\"ה), והוא ר' אבדימי דמן חיפה (ע\"ע).","cat": "sage"},{"i": 189,"n": "ר' אבדומא מלחא","l": "א","b": "מובא בירושלמי (סוכה פ\"ב ה\"ט). והוא ר' אבדימא מלחא. (ע\"ע).","cat": "sage"},{"i": 190,"n": "ר' אבדומה דמן נחותא","l": "א","b": "מובא בירושלמי (שקלים פ\"ג ה\"ב), והוא ר' אבדימי.","cat": "sage"},{"i": 191,"n": "רבי אבדומי בר טוביא","l": "א","b": "נראה, שהוא ר' אבדימי בר טובי.","cat": "sage"},{"i": 192,"n": "אבדומי המדורי","l": "א","b": "הוא בר המדור.","cat": "sage"},{"i": 193,"n": "אבדומי נחותא","l": "א","b": "מובא בירושלמי (עירובין פ\"א ה\"ו). והוא רב דימי.","cat": "sage"},{"i": 194,"n": "אבדימא","l": "א","b": "הוא אבדומא.","cat": "sage"},{"i": 195,"n": "רבי אבדימא דציפורין","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי מנא (ירו', ברכות פ\"ד ה\"ג). אביו, שגם הוא היה חכם, נקרא על שם בנו: \"רבי אליעזר בשם ר' אימי אבוי דר' אבדומא דציפורי\" (ירו', ביצה פ\"א ה\"ט).","cat": "sage"},{"i": 196,"n": "ר' אבדימא מלחא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (ב\"מ ספ\"ד: סוכה פ\"ב ה\"ה).","cat": "sage"},{"i": 197,"n": "אבדימוס","l": "א","b": "תנא בדור החמישי, והוא רבי מנחם ברבי יוסי בן חלפתא המובא בירושלמי (יבמות פ\"א ה\"א).","cat": "sage"},{"i": 198,"n": "אבדימי","l": "א","b": "הוא אבדומא או אבדימא.","cat": "sage"},{"i": 199,"n": "ר' אבדימי","l": "א","b": "מאחרוני אמוראי ארץ ישראל. תלמידו של ר' מנא (ירו', עירובין פ\"י ה\"ב), יחד עם חברו ר' אליעזר [בנו של ר' יוסי].","cat": "sage"},{"i": 200,"n": "ר' אבדימי אחוה דר' יוסי","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אחיו של האמורא ר' יוסי מראשי דור הרביעי. ר' אחא כעס עליו וחלה ונטה למות, ואחיו ר' יוסי ביקרו ונתרפא (ירו', ב\"ב פ\"ב ה\"ג).","cat": "sage"},{"i": 201,"n": "ר' אבדימי בר ברתיה דר' טובי","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (סנהדרין פ\"ו ה\"ה). מסר (שם) בשם ר' יאשיה [שחי בדור השלישי].","cat": "sage"},{"i": 202,"n": "ר' אבדימי בר המדורא","l": "א","b": "מובא (סוכה כ' ע\"א), והוא בר המדורי.","cat": "sage"},{"i": 203,"n": "ר' אבדימי בר חמא","l": "א","b": "מובא בבבלי (ע\"ז י\"ט ע\"א). נראה שהוא ר' אבדימי בר חמא בר חסא (ע\"ע). אמר: \"כל העוסק בתורה, הקב\"ה עושה לו חפציו\" (שם).","cat": "sage"},{"i": 204,"n": "ר' אבדימי בר חמא בר חסא","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת פ\"ח ע\"א). שם מאמרו הידוע: \"מלמד שכפה הקב\"ה עליהם את ההר כגיגית\".","cat": "sage"},{"i": 205,"n": "ר' אבדימי בר חסא","l": "א","b": "מובא בבבלי (זבחים קי\"ח ע\"א). נראה שהוא ר' אבדימי בר חמא בר חסא.","cat": "sage"},{"i": 206,"n": "ר' אבדימי בר טובי","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מו\"ק פ\"ג ה\"ה). מסר בשם רבי אבהו (שם). יש גם אבימי בר טובי, תלמיד ר' אבהו (ירו', נזיר פ\"ט ה\"א). ואולי אחד הם.","cat": "sage"},{"i": 207,"n": "ר' אבדימי בר נחוניא","l": "א","b": "מובא במדרש תהלים (רפק\"ג).","cat": "sage"},{"i": 208,"n": "ר' אבדימי בר תנחום","l": "א","b": "מובא בירושלמי (מו\"ק פ\"ג ה\"ח).","cat": "sage"},{"i": 209,"n": "ר' אבדימי דמן חיפה","l": "א","b": "אמורא ארץ ישראלי בדור השני - שלישי. מסר בשם ריש לקיש (ירו', סוכה פ\"א ה\"א). מתלמידיו: רבי אבהו (ירו', מו\"ק פ\"ג ה\"ה) ור' זירא (ירו', תרומות פ\"ג ה\"ג). מושבו היה בחיפה, שם היה מורה הוראה (ירו', עירובין פ\"ב ה\"א).","cat": "sage"},{"i": 210,"n": "רב אבדימי נחותא","l": "א","b": "מובא בירושלמי (עירובין פ\"א ה\"ו), והוא רב דימי.","cat": "sage"},{"i": 211,"n": "רבי אבדימס","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (כתובות פי\"א ה\"ב).","cat": "sage"},{"i": 212,"n": "אבדן","l": "א","b": "בדור המעבר בין התנאים לאמוראים. תלמידו הגדול של רבי (ירו', ברכות פ\"ה ה\"א) והאמורא שלו (שם פ\"ד ה\"א). אירעו לו אסונות משפחתיים רבים (יבמות ק\"ה ע\"ב).","cat": "sage"},{"i": 213,"n": "אבהו","l": "א","b": "מוחלף לפעמים באבוה.","cat": "sage"},{"i": 214,"n": "רב אבהו","l": "א","b": "אמורא בבלי בדור הששי. נשא ונתן עם רב אשי (ב\"ק קי\"ז ע\"א). מראשי כלה דרפרם בפומבדיתא (חולין מ\"ט ע\"א). בנו, רב שמואל, היה מרבנן סבוראי.","cat": "sage"},{"i": 215,"n": "רבי אבהו","l": "א","b": "אמורא ארץ ישראלי בדור השלישי מתלמידיו המובהקים של רבי יוחנן (כתובות נ\"ז ע\"א). אמר על רבו: \"מפתח לנו רבי יוחנן פתח מאיר כאורה\" (ירו', פסחים פ\"ב סה\"ב). רש\"י כתב, שרבי אלעזר היה רבו (יומא פ' ע\"א), וכן קיבל מר\"ל (פסחים מ\"ו ע\"א). מושבו היה בקיסרי והיה מקורב למלכות (חגיגה י\"ד ע\"א). התווכח הרבה עם המינים וניצחם (ברכות י' ע\"א). חבריו הגדולים היו רבי אמי, רבי אסי, ורבי חייא בר אבא (יבמות ס\"ה ע\"ב). אחרי פטירת רבי אמי רצו להושיבו בראש ומרוב ענוה ביקש להושיב במקומו את רבי אבא מעכו (סוטה מ' ע\"א). היה מבורך בעושר (שבת קי\"ט ע\"א) ביופי (ב\"מ פ\"ד ע\"א). אמרו עליו \"שופריה דר' אבהו מעין שופריה דיעקב אבינו\" (שם). היה בעל כח רב (ברכות ס' ע\"א). היו לו תלמידים רבים וביניהם ראשי הדור הרביעי רבי יונה (ירו', סנהדרין ספ\"ו) ורבי יוסי (סנהדרין ספ\"ו) כן היו תלמידיו, אבימי (קדושין ל\"א ע\"ב), רבי זעירא (ירו', ברכות רפ\"ט), ורבי חנינא בנו (קידושין ל\"ג ע\"ב). חמו של רבי אבהו היה חכם ושמו רבי תחליפא דקיסרין, ורבי אבהו אמר משמו (קה\"ר ספ\"י). כשמת רבי אבהו הראו לו את חלקו המזומן לו לעוה\"ב, ואפילו עמודי השיש שבקיסרי זלגו דמעות (מו\"ק כ\"ה ע\"ב).","cat": "sage"},{"i": 216,"n": "ר' אבהו בר אחא","l": "א","b": "מובא במדרש תהלים (הישן פק\"ז). ב\"סה\"ד\" כתב: \"קרוב בעיני שהוא ר' אבא בר אחא\".","cat": "sage"},{"i": 217,"n": "אבהו בר גניבא","l": "א","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב קל\"ט ע\"א).","cat": "sage"},{"i": 218,"n": "ר' אבהו בר זוטרתי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יהודה בר זבידא (ברכות י\"ב ע\"ב).","cat": "sage"},{"i": 219,"n": "ר' אבהו בר זעירא","l": "א","b": "אמורא, כנראה, ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא במדרש תהלים (פ\"ד - י\"ב).","cat": "sage"},{"i": 220,"n": "ר' אבהו בר חנינא","l": "א","b": "מובא בתנחומא (הישן, ויצא - ג').","cat": "sage"},{"i": 221,"n": "ר' אבהו בר כהנא","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (מנחות צ\"ה ע\"ב).","cat": "sage"},{"i": 222,"n": "רבי אבהו בר נגרי","l": "א","b": "אמורא ארץ ישראלי. מובא פעם אחת בש\"ס הירושלמי (פאה פ\"ה ה\"ד): יתכן שהוא ר' אייבו בר נגרי.","cat": "sage"},{"i": 223,"n": "אבוברם","l": "א","b": "אמורא בבלי בדור החמישי - הששי. מובא בבבלי: \"אמר רבינא אמר לי סמא בר חילקאי אקשי בה אבוה דבר אבוברם\" (חולין ל\"ח ע\"א), ופרש\"י שם: \"זהו אבוברם עצמו ומכירין את הבן ולא את האב והיו קורין אותו על שם בנו שעשו את הבן סימן לו\".","cat": "sage"},{"i": 224,"n": "אבודמא","l": "א","b": "ע\"ע אבדימי או אבדימא.","cat": "sage"},{"i": 225,"n": "ר' אבודמא דציפורי","l": "א","b": "מובא בירושלמי (ביצה פ\"א ה\"ט). והוא ר' אבדימא דציפורין.","cat": "sage"},{"i": 226,"n": "אבוה (2)","l": "א","b": "חי בבבל בתקופת אביי בדור רביעי לאמוראים. אביו של רב יעקב בר אבוה. אביי אמר עליו שהוא \"בן תורה\" (קידושין ל\"א ע\"ב). אין לדעת אם נמנה עם האמוראים.","cat": "sage"},{"i": 227,"n": "אבוה בר איהי","l": "א","b": "אמורא בבלי בדור השני. מושבו בנהרדעא. תלמיד מובהק של שמואל (נזיר כ\"ד ע\"ב). הוא ואחיו מנימן בר איהי היו חסידים גדולים (מגילה כ\"ח ע\"א). לאחד מהם נתגלה אליהו הנביא (כתובות ס\"א ע\"א).","cat": "sage"},{"i": 228,"n": "אבוה דבר אבוברם","l": "א","b": "מובא בבבלי (חולין ל\"ח ע\"א), והוא אבוברם עצמו (ע\"ע).","cat": "sage"},{"i": 229,"n": "אבוה דבר נטה","l": "א","b": "מובא בירושלמי (תענית פ\"ד ה\"ב). ע\"ע ר' חיננא אבוה דר' ינטה.","cat": "sage"},{"i": 230,"n": "אבוה דרב אחא בריה דרב איקא","l": "א","b": "מובא בבבלי (ע\"ז ס\"ה ע\"א), והוא רב איקא עצמו (ע\"ע).","cat": "sage"},{"i": 231,"n": "רב אבוה דרב משרשיא","l": "א","b": "יש שכך גורסים בבבלי (עירובין כ\"ד ע\"א), ויש גורסים: ר' אבא אחוה דרב בריה דרב משרשיא.","cat": "sage"},{"i": 232,"n": "אבוה דרב ספרא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. שאל את רבי זירא (ירו', כלאים פ\"ט ה\"ד).","cat": "sage"},{"i": 233,"n": "אבוה דרבי אפטוריקי","l": "א","b": "אמורא, כנראה, ארץ ישראלי, שאין לקבוע זמנו המדוייק. שמו היה דוסתאי (חולין ס\"ד ע\"ב). נראה, שבנו היה מפורסם ממנו ועל כן נקרא על שם בנו. היה שונה ברייתות (ב\"מ ה' ע\"א).","cat": "sage"},{"i": 234,"n": "אבוה דר' אבין","l": "א","b": "אמורא בבלי בדור הרביעי. מובא מספר פעמים בבבלי כשונה ברייתות (גיטין נ\"ג ע\"א). פעם שנה ברייתא לפני רבי זירא (שם פ\"ה ע\"א). כנראה שנה ברייתות בישיבות האמוראים בבבל.","cat": "sage"},{"i": 235,"n": "אבוה דר' אושעיה","l": "א","b": "מובא בבבלי (מו\"ק כ\"ד ע\"א), והוא רבי חמא בר ביסא [אביו של רבי אושעיא]. ובירושלמי מובא: \"ר' חמא אבוה דר' הושעיא\" (מו\"ק פ\"ג ה\"ה).","cat": "sage"},{"i": 236,"n": "אבוה דר' זירא","l": "א","b": "אמורא בבלי בדור השני. אביו של האמורא רבי זירא. שמו היה איסי (מו\"ק כ' ע\"ב). הקשה על דברי ר' יהושע בן לוי (תענית כ\"ו ע\"ב). היה גבאי מסים של המלך, שהקל על העם (סנהדרין כ\"ה ע\"ב).","cat": "sage"},{"i": 237,"n": "אבוה דשמואל","l": "א","b": "ע\"ע אבא בר אבא אבוה דשמואל.","cat": "sage"},{"i": 238,"n": "אבוה דשמואל בר אבין","l": "א","b": "מובא בבבלי (סנהדרין נ\"א ע\"ב). \"דק\"ס\" גורס: אבוה דר' אבין.","cat": "sage"},{"i": 239,"n": "אבוה דשמואל בר יצחק","l": "א","b": "אמורא בבלי בדור השני. מובא בבבלי על שם בנו (זבחים קי\"א ע\"ב). בנו, ר' שמואל בר יצחק, מסר בשם אביו מאמר שקיבל מרב (ירו', שבועות פ\"ד ה\"א). היה חסיד גדול. ונפטר לאחר שצם יומיים בצום כיפור משום ספק (ירו', ר\"ה פ\"א ה\"ד).","cat": "sage"},{"i": 240,"n": "אבויה","l": "א","b": "ע\"ע אבוה.","cat": "sage"},{"i": 241,"n": "אבויה דר\"ש","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי נראה שרב יוסי קיבל ממנו (ירו', פאה פ\"א ה\"ה).","cat": "sage"},{"i": 242,"n": "אבון","l": "א","b": "ע\"ע אבין.","cat": "sage"},{"i": 243,"n": "רבי אבון בר ביסנא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יונתן דבית גוברין (ירו', יבמות פ\"א סה\"א), ובשם ר' אבא בר ממל (שם פ\"ו ה\"ב).","cat": "sage"},{"i": 244,"n": "ר' אבון בר חייא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. ר' שמאי (שמי) מסר משמו (ירו', שקלים פ\"ג ה\"א).","cat": "sage"},{"i": 245,"n": "אבון בר חסדאי","l": "א","b": "הוא רבין בר רב חסדא.","cat": "sage"},{"i": 246,"n": "רבי אבון הלוי","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבא בר כהנא (תנחומא, תזריע - ח'). מבעלי האגדה הנודעים. בעל המאמר: \"הנפטר מחבירו יאמר לו לך לשלום והנפרד מן המת יאמר לך בשלום\" (שילהי ברכות).","cat": "sage"},{"i": 247,"n": "אבונא","l": "א","b": "מובא בירושלמי (שביעית פ\"ד ה\"ב). ע\"ע ר' אבינא.","cat": "sage"},{"i": 248,"n": "ר' אבונא בר סחורה","l": "א","b": "מובא בירושלמי (פסחים פ\"י ה\"ה).","cat": "sage"},{"i": 249,"n": "רבי אבונא ספרא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (מגילה פ\"ג ה\"ז).","cat": "sage"},{"i": 250,"n": "רבי אבונה בר סחורה","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. נראה שחי בדור החמישי - הששי. מובא בירושלמי (פסחים פ\"י ה\"ה).","cat": "sage"},{"i": 251,"n": "רבי אבונה זעירא","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (שביעית פ\"ד ה\"ב), שם מסופר שגויים אנסוהו לרוץ בשבת אחרי חמור.","cat": "sage"},{"i": 252,"n": "אבורודימוס","l": "א","b": "כך מובא בירושלמי (שביעית פ\"ח ה\"ח) ובבבלי: ורדימס (ע\"ע).","cat": "sage"},{"i": 253,"n": "אבטולומוס","l": "א","b": "תנא ארץ ישראלי בדור השלישי. מובא בבבלי (עירובין ל\"ו ע\"א). רבו של ר' יוסי בר חלפתא.","cat": "sage"},{"i": 254,"n": "אבטולומוס בר ראובן","l": "א","b": "מובא בבבלי (ב\"ק פ\"ג ע\"א), והוא ר' ראובן בן איסטרובלי (ע\"ע), על פי גירסת התוס' (שם, בד\"ה: התירו).","cat": "sage"},{"i": 255,"n": "אבטולוס","l": "א","b": "אמורא ארץ ישראלי בדור הראשון. מובא בבבלי (מנחות נ\"ג ע\"א). היה דור עשירי לעזרא. בן בנו, רבי עזרא, בא לפני רבי פרידא (שם).","cat": "sage"},{"i": 256,"n": "ר' אבטולוס בן ראובן","l": "א","b": "מובא בבבלי (סוטה מ\"ט ע\"ב). והוא ר' ראובן בן איסטרובלי, (ע\"ע).","cat": "sage"},{"i": 257,"n": "רבי אבטולוס הזקן","l": "א","b": "תנא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא במכילתא (בשלח פ\"ג). וגירסת הילקוט והגר\"א וגירסא שלנו: \"רבי אבשלום הזקן\".","cat": "sage"},{"i": 258,"n": "רבי אבטילס","l": "א","b": "תנא בדור החמישי. מובא בבבלי (שבת קי\"ח ע\"ב). בנו הרביעי של רבי יוסי בן חלפתא.","cat": "sage"},{"i": 259,"n": "אבטליון","l": "א","b": "חכם קדום. חי יותר ממאה שנה לפני חורבן בית שני. נמנה עם ה\"זוגות\" שהיו אחר אנשי כנסת הגדולה. הוא וחברו שמעיה היו הזוג הרביעי. היה אב\"ד ושמעיה בן זוגו היה נשיא (חגיגה ט\"ז ע\"א). שניהם היו ממשפחת גרים (גיטין נ\"ז ע\"ב). תלמידיהם היו הלל ושמאי (אבות פ\"א מי\"ב). ע\"ע שמעיה.","cat": "sage"},{"i": 260,"n": "אבי רודימס","l": "א","b": "מובא בירושלמי (שביעית פ\"ח ה\"ה). והוא וורדימס (ע\"ע רבי מנחם בר' יוסי בן חלפתא).","cat": "sage"},{"i": 261,"n": "אביבי סנוותאה","l": "א","b": "מובא בבבלי (שבת י\"ז ע\"ב). כך הגירסא בדפוסים הישנים, ולפנינו: אבימי סנוותאה (ע\"ע אבימי נותאה).","cat": "sage"},{"i": 262,"n": "אבידן","l": "א","b": "מובא בבבלי (ברכות כ\"ז ע\"ב), והוא אבדן, תלמידו של רבי (ע\"ע).","cat": "sage"},{"i": 263,"n": "ר' אביה","l": "א","b": "מובא בתנחומא (פ\"ג - ז').","cat": "sage"},{"i": 264,"n": "ר' אביטול ספרא","l": "א","b": "אמורא בבלי, שאין לקבוע זמנו המדוייק. מובא בבבלי (מו\"ק י\"ח ע\"א), שמסר בשם רב.","cat": "sage"},{"i": 265,"n": "אביי","l": "א","b": "אמורא בבלי בדור הרביעי. מגדולי האמוראים. נולד בשנת ד' ל\"ז (772), ונפטר בגיל 06 (ר\"ה י\"ח ע\"א), בשנת ד' צ\"ז (733) (\"אגרת רב שרירא גאון\"). הוא וחברו הצעיר רבא הטביעו חותמם על הש\"ס, שנקרא \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). היה יתום מאביו ואמו - כשעברתו אמו מת אביו, וכשילדתו - מתה אמו (קידושין ל\"א ע\"ב). רבה בר נחמני, שהיה דודו (\"ערוך\" ערך אביי), גידלו בביתו (נדרים נ\"ד ע\"ב ר\"ן), והיה גם רבו המובהק (שבת כ\"ב ע\"א). רבו המובהק השני היה רב יוסף (קידושין ל\"ג ע\"א), ואביי נהפך אח\"כ לתלמיד חבר לו. שני רבותיו אלה עמדו בראש ישיבת פומבדיתא, ואחר פטירת רב יוסף נתמנה אביי ראש ישיבת פומבדיתא (סוף הוריות). הוא מלך משנת ד' פ\"ב עד ד' צ\"ז (423 - 733). היו לו מאות תלמידים (כתובות ק\"ו ע\"א). במחלוקת אביי ורבא הלכה כרבא, חוץ מ\"יע\"ל קג\"ם\" שבהם הלכה כאביי (ב\"מ כ\"ב ע\"ב). במחלוקת אביי ורב יוסף הלכה כאביי, חוץ מ\"במחצה\" (רמב\"ם בפסקי עירובין). שם אביו, כנראה, כייליל (זבחים קי\"ח ע\"ב ברש\"י). בנו רב ביבי היה חכם (סנהדרין ס\"ו ע\"ב). אשתו השניה היתה בת איסי, שהיה נכדו של רב יהודה. ונראה שסמוך לאחר נשואיו אלה, נפטר אביי (יבמות ס\"ד ע\"ב). היה חסיד במעשיו (גיטין מ\"ה ע\"א - רש\"י). כל יום ששי היתה בת קול יוצאת מן השמים ואומרת לו \"שלום עליך\" (תענית כ\"א ע\"ב רש\"י). אחריו היה רבא חברו ראש ישיבת פומבדיתא.","cat": "sage"},{"i": 266,"n": "ר' אביי","l": "א","b": "אמורא ארץ ישראלי בדור השני. מובא בירושלמי (ר\"ה פ\"א ה\"ח). נשא ונתן עם ריש לקיש (שם). ר' יונה מסר בשמו (ירו', תרומות פ\"ה ה\"ב).","cat": "sage"},{"i": 267,"n": "אביי בי רבי בנימין","l": "א","b": "מובא בירושלמי (ברכות פ\"ה ה\"ד). ע\"ע אבא בריה דרב מנימין בר חייא.","cat": "sage"},{"i": 268,"n": "אביי בר אבא","l": "א","b": "מובא בבבלי (יבמות ל\"ו ע\"א). והוא אביי בר אבין.","cat": "sage"},{"i": 269,"n": "אביי בר אבין","l": "א","b": "אמורא בבלי בדור הרביעי. למד לפני רבה יחד עם אחיו חנינא (פסחים ל\"ד ע\"א). היה חברו של אביי (עירובין פ\"ב ע\"ב).","cat": "sage"},{"i": 270,"n": "אביי בר בנימין","l": "א","b": "מובא בירושלמי (גיטין פ\"ה ה\"ט). ע\"ע אבא בריה דרב מנימין בר חייא.","cat": "sage"},{"i": 271,"n": "אביי בר הונא","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב חמא בר גוריא (זבחים ס\"ב ע\"ב). גירסת \"שיטה מקובצת\" שצ\"ל: אבין בר הונא, והשם אבין השתבש לאביי.","cat": "sage"},{"i": 272,"n": "אביי בר נאזי","l": "א","b": "מובא בבבלי (ב\"ב קט\"ו ע\"א). כך גירסת הרי\"ף. ולפנינו: אבימי בר נאזי, (ע\"ע).","cat": "sage"},{"i": 273,"n": "אביי בר רבין","l": "א","b": "מובא בבבלי (שבת פ\"ו ע\"ב), והוא אביי בר אבין.","cat": "sage"},{"i": 274,"n": "אביי בריה דר' אבהו","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי (קידושין י\"ט ע\"א). בנו של האמורא ר' אבהו. (שם). \"סה\"ד\" מפקפק: \"אולי צ\"ל אבימי בריה דר' אבהו\".","cat": "sage"},{"i": 275,"n": "אביי קשישא","l": "א","b": "אמורא בבלי בדור השני או השלישי. הקשה מרב על רב (שבת נ\"ו ע\"א). אביי מביאו (כתובות צ\"ד ע\"א). היה שונה ברייתות (יבמות כ\"ד ע\"א). נראה שהכנוי קשישא בא להבדילו מאביי הידוע.","cat": "sage"},{"i": 276,"n": "רב אבייא","l": "א","b": "מובא בירושלמי (סוכה פ\"ב ה\"ח), והוא ר' אביי, (ע\"ע).","cat": "sage"},{"i": 277,"n": "אבימוס","l": "א","b": "מובא בירושלמי (ריש יבמות). וב\"סה\"ד\" כתב: ט\"ס (ולי נראה שצ\"ל שם אביטלס כמו בשבת קי\"ח ע\"ב).","cat": "sage"},{"i": 278,"n": "אבימי (2)","l": "א","b": "אמורא בבלי בדור השני. מובא בבבלי (מנחות ז' ע\"א). רבו של רב חסדא (שם). משום סיבה שכח אבימי לימודו, ורב חסדא הזכירו (שם).","cat": "sage"},{"i": 279,"n": "אבימי אחוי דחיפא","l": "א","b": "מובא (ירו', נדרים פ\"ב ה\"ג), והוא אבימי בר רחבא.","cat": "sage"},{"i": 280,"n": "ר' אבימי בר טובי","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב אבהו (ירו', נזיר רפ\"ט). יש גם ר' אבדימי בר טובי בשם ר' אבהו (ירו', מו\"ק פ\"ג ה\"ה). ואולי אחד הם.","cat": "sage"},{"i": 281,"n": "אבימי בר נאזי","l": "א","b": "חי בבבל בדור הרביעי. מובא בבבלי (ב\"ק קט\"ו ע\"א). חמיו של רבינא.","cat": "sage"},{"i": 282,"n": "אבימי בר פפי","l": "א","b": "אמורא בבלי בדור השלישי. חברם של עולא ור' נחמן (ע\"ז ס\"ג ע\"א). ר' זירא פנה אליו בשאלה (ירו', כתובות פ\"ד הי\"ג).","cat": "sage"},{"i": 283,"n": "אבימי בר רחבה מפומבדיתא","l": "א","b": "אמורא בבלי בדור הרביעי. הוא ואחיו עיפה מכונים \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב), והיו תלמידיו של רבה (שבועות כ\"ח ע\"ב). אביו, רחבה דפומבדיתא, היה תלמידו המובהק של רב יהודה (פסחים נ\"ב ע\"ב).","cat": "sage"},{"i": 284,"n": "אבימי בריה דר' אבהו","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של האמורא ר' אבהו. פעם ביקשוהו חכמים לשאול שאלה אחת מאביו (גיטין כ\"ט ע\"ב). אביו סיפר על כבוד אב שקיים בנו זה (קידושין ל\"א ע\"ב). \"סה\"ד\" מפקפק אם אבימי ואביי בר אבהו אחד הם.","cat": "sage"},{"i": 285,"n": "אבימי דמן חבריא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בב\"ר (פי\"ג - ט\"ז). רבי חייא בר אבא דיבר עמו (שם).","cat": "sage"},{"i": 286,"n": "אבימי מבי חוזאי","l": "א","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. מובא בבבלי (נדה ה' ע\"ב).","cat": "sage"},{"i": 287,"n": "אבימי מהגרוניא","l": "א","b": "אמורא בבלי בדור החמישי. נראה, שהיה תלמיד של רבא, שכן מובא כמה פעמים: \"אמר ליה רב מרדכי לרב אשי: הכי אמר אבימי מהגרוניא, משמיה דרבא\" (כתובות ק\"ט ע\"ב: ב\"מ ע\"ז ע\"ב: שם צ\"ז ע\"א: ב\"ב קע\"ד ע\"ב: מכות י\"ג ע\"ב). פעם אחת מסר משם רב הונא (יבמות ס\"ד ע\"ב).","cat": "sage"},{"i": 288,"n": "אבימי נותאה","l": "א","b": "אמורא בבלי בדור השני. מסר בשם רב (ע\"ז ל\"ו ע\"ב). רבו של האמורא באלי (שם). במסכת שבת (י\"ז ע\"ב) הגירסא:\" אבימי סנוותאה\" (ע\"ע).","cat": "sage"},{"i": 289,"n": "אבימי סנוותאה","l": "א","b": "מובא בבבלי (שבת י\"ז ע\"ב). במסכת ע\"ז (ל\"ו ע\"ב). הגירסא:\" אבימי נותאה\" (ע\"ע), וכן גירסת \"דק\"ס\".","cat": "sage"},{"i": 290,"n": "אבין","l": "א","b": "ע\"ע רבין.","cat": "sage"},{"i": 291,"n": "ר' אבין אביו דר' אבין הלוי","l": "א","b": "מובא בתנחומא (בובר, תזריע).","cat": "sage"},{"i": 292,"n": "רבי אבין איש נחום","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בילקוט שמעוני (בא רמז קצ\"א). רבי ברכיה מסר בשמו (שם).","cat": "sage"},{"i": 293,"n": "אבין בר בנימין","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בויק\"ר (פ\"י - ה'). מסר בשם ר' אבא (שם). ע\"ע רבי אחא בר אבין בר בנימין.","cat": "sage"},{"i": 294,"n": "אבין בר הונא","l": "א","b": "אמורא בבלי בדור השלישי. מובא בבבלי (שבת ס\"ו ע\"ב) תלמיד תלמידו של רב, ותלמידו של רב חמא בר גוריא (שם).","cat": "sage"},{"i": 295,"n": "ר' אבין בר זוטרתי","l": "א","b": "מובא בבבלי (ברכות י\"ב ע\"ב), וכן גירסת \"יוחסין\". ולפנינו: \"ר' אבהו בר זוטרתי\".","cat": "sage"},{"i": 296,"n": "ר' אבין בר חייא (2)","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. למד לפני ר' יוחנן (קידושין מ\"ד ע\"א), לפני ריש לקיש (ירו', תרומות פ\"ו סה\"א), ולפני ר' זירא (ירו', מעשרות רפ\"ב). נפטר בגיל 82 ור\"ז הספידו ואמר עליו שיגע יותר מאשר תלמיד ותיק במאה שנה (ירו', ברכות פ\"ב ה\"ח).","cat": "sage"},{"i": 297,"n": "ר' אבין בר חנין","l": "א","b": "מובא במדרש שמואל (פי\"ז). המאמר מובא גם בפדר\"כ (מה) ושם: \"ר' אבין בשם ר' חנין\", ואולי במקום בר צ\"ל: בשם רבי.","cat": "sage"},{"i": 298,"n": "ר' אבין בר כהן","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מע\"ש פ\"ד ה\"ו). תלמידו של רבי אסי (שם).","cat": "sage"},{"i": 299,"n": "ר' אבין בר כהנא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. קיבל מרבי אלעאי (ירו', פסחים פ\"ג ה\"ח). שאל מר' אמי (ירו', ב\"ק רפ\"ה). ר' יוסי קיבל ממנו (ירו', עירובין פ\"ז ה\"א). בימי ר' מנא, כבר היה זקן מאד (ירו', מו\"ק ספ\"א).","cat": "sage"},{"i": 300,"n": "ר' אבין בר רב אדא","l": "א","b": "מובא בבבלי (פסחים ח' ע\"ב), הוא רבין בר רב אדא.","cat": "sage"},{"i": 301,"n": "ר' אבין בר רב אחא","l": "א","b": "מובא בבבלי (פסחים ל\"ד ע\"א). \"דק\"ס\" גורס: \"ר' אבין בר רב אדא\".","cat": "sage"},{"i": 302,"n": "ר' אבין בר ר' אלעזר","l": "א","b": "מובא בירושלמי (סנהדרין פ\"ב ה\"ד). יש גורסים: ר' אבין בשם ר' אלעזר.","cat": "sage"},{"i": 303,"n": "רבי אבין בר שבא","l": "א","b": "מובא בבבלי (חולין פ\"ו ע\"א): \"והאמר רבין בר אבא, ואמרי לה אמר רבי אבין בר שבא\".","cat": "sage"},{"i": 304,"n": "ר' אבין בריה דר' תנחום בר טרפון","l": "א","b": "מובא בירושלמי (בכורות רפ\"ב).","cat": "sage"},{"i": 305,"n": "אבין דמן נשיקיא","l": "א","b": "אמורא בבלי בדור השני. מובא בבבלי (שבת קכ\"א ע\"א). שם מוזכר שביקרו אצלו רב יהודה, רב ירמיה בר אבא ורב חנן בר רבא. אבין לימד את בנו (שם).","cat": "sage"},{"i": 306,"n": "ר' אבין הלוי","l": "א","b": "מובא בבבלי (סוף ברכות): \"א\"ר אבין הלוי: 'כל הדוחק את השעה, שעה דוחקתו, וכל הנדחה מפני השעה, שעה נדחת מפניו'\".","cat": "sage"},{"i": 307,"n": "ר' אבין הלוי בר חמא","l": "א","b": "מובא בתנחומא (וישב - ט\"ו). יש אומרים שצ\"ל: ר' אבין הלוי בר חייא. ושני יודין היו ל\"מם\".","cat": "sage"},{"i": 308,"n": "ר' אבין זוטרתי","l": "א","b": "מובא בבבלי (ברכות י\"ב ע\"ב). כן גירסת ה\"יוחסין\". ולפנינו: \"ר' אבהו בר זוטרי\".","cat": "sage"},{"i": 309,"n": "רב אבין נגרא","l": "א","b": "חי בבבל בדור השני. מלאכתו היתה חרש עצים (שבת כ\"ג ע\"ב). רב הונא רגיל היה לעבור ליד ביתו, ובראותו שהדליק נרות רבים לכבוד שבת, בירכו ששני חכמים יוולדו לו, ואכן נולדו לו רב אידי ורב חייא (שם).","cat": "sage"},{"i": 310,"n": "אבין צפיראה","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - הששי. מובא בבבלי (שבת כ\"ט ע\"ב). ישב לפני רבי יצחק בן אלעזר (שם).","cat": "sage"},{"i": 311,"n": "אבין רמאה","l": "א","b": "חי בארץ ישראל בימי ריש לקיש. מובא בבמד\"ר (פ\"ד - ד'). היה בעל צדקה גדול. ר\"ל כיבדו מאד עבור מעשיו (שם). אין להכריע שהיה מן החכמים.","cat": "sage"},{"i": 312,"n": "אבין תורן","l": "א","b": "אמורא בבלי בדור הראשון. מובא בבבלי (שבת קכ\"ב ע\"ב). שמו היה אבין והיה ממקום ששמו תורן (שם ברש\"י).","cat": "sage"},{"i": 313,"n": "אבין תכלא","l": "א","b": "מובא בבבלי (פסחים ע' ע\"ב), והוא רבין. ופרש\"י: קובר את בניו היה (לכן כינוהו כך).","cat": "sage"},{"i": 314,"n": "ר' אבינא","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (גיטין ס\"ו ע\"א). כן קיבל מר' ירמיה בר אבא (שבת קל\"ז ע\"ב), מרב חסדא (פסחים נ\"ט ע\"א) ומגניבא (חולין נ' ע\"ב). וגניבא הוריש לו ד' מאות זוז, לפני שהוצא להורג ע\"י המלכות (גיטין ס\"ה ע\"ב). עלה לא\"י וישב לפני ר' אמי (ירו', שביעית פ\"ד ה\"ב). בשמו מסרו: ר' יונה ור' יוסי (ירו', שביעית פ\"ב ה\"ג).","cat": "sage"},{"i": 315,"n": "אבירודימוס","l": "א","b": "תנא והוא הוא רבי מנחם בר יוסי בר חלפתא ומובא (ירו', שביעית פ\"ח ה\"ה).","cat": "sage"},{"i": 316,"n": "רבי אביתר","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי (גיטין ו' ע\"ב). עמד בקשר עם רב יהודה ורב חסדא (שם). זכה לגילוי אליהו (שם).","cat": "sage"},{"i": 317,"n": "רבי אבמכיס","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי (סנהדרין ספ\"ג) שבא לפני ר' אלעזר.","cat": "sage"},{"i": 318,"n": "אבמרי","l": "א","b": "מובא בירושלמי (תענית פ\"א ה\"ו). זהה לאבא מרי (ע\"ע).","cat": "sage"},{"i": 319,"n": "ר' אבמרי אחוי דרבי יוסי","l": "א","b": "מובא בירושלמי (שבת פ\"ג ה\"ו). ע\"ע ר' אבא מרי אחוי דר' יוסי.","cat": "sage"},{"i": 320,"n": "אבסקטא","l": "א","b": "מובא בירושלמי (ברכות פ\"ט ה\"א). \"פני משה\", (שם), מפרש מלשון \"נשיאות חן וכבוד\" והירושלמי (ע\"ז פ\"א ה\"ט) גרס: אבסקנטה (ע\"ע).","cat": "sage"},{"i": 321,"n": "אבסקנטה","l": "א","b": "מובא בירושלמי (ע\"ז פ\"א ה\"ט). \"פני משה\", (שם), מפרש מלשון \"נשיאות חן וכבוד\" (ואין זה כלל שם אדם), ו\"סה\"ד\" מפרש: \"שם חכם\". והירושלמי (ברכות פ\"ט ה\"א) גרס: אבסקטא (ע\"ע).","cat": "sage"},{"i": 322,"n": "אברם חוזאה","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (גיטין נ' ע\"א).","cat": "sage"},{"i": 323,"n": "רבי אבשלום הזקן","l": "א","b": "תנא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא במכילתא (בשלח פ\"ג). ע\"ע רבי אבטולוס הזקן.","cat": "sage"},{"i": 324,"n": "אגרא","l": "א","b": "אמורא ארץ ישראלי בדור השני. חותנו של ר' אבא (מנחות כ\"ט ע\"ב), ושאל מר' אבא חתנו (שם). מצינו ששנה ברייתא (חולין ק\"ד ע\"ב).","cat": "sage"},{"i": 325,"n": "רב אדא","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ר' שמלאי (סוטה ל\"ח ע\"ב), ושל רב (יבמות פ\"ג ע\"ב). בבבלי סוטה (שם) ובירושלמי (תרומות פ\"י ה\"ו) מובא בלי ר'. אבל בבבלי יבמות (שם) מובא: רב אדא.","cat": "sage"},{"i": 326,"n": "ר' אדא","l": "א","b": "פעמים מוחלף בר' אחא או בר' אבא.","cat": "sage"},{"i": 327,"n": "רב אדא א'","l": "א","b": "אמורא בבלי בדור החמישי. מובא בבבלי (מנחות מ\"ג ע\"א). תלמידו של רב יוסף (נדה כ\"ה ע\"ב) ושל רבא (מנחות שם).","cat": "sage"},{"i": 328,"n": "רבי אדא בי ר' שמעון","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו', מגילה פ\"א ה\"ט). אותו מאמר (ירו', ברכות פ\"ב ה\"ג) בשם ר' אידי בר שמעון בשם ר' יוחנן'.","cat": "sage"},{"i": 329,"n": "ר' אדא בר אבא","l": "א","b": "מובא בבבלי (ב\"ב כ\"ב ע\"א). וצ\"ל: ר' אדא בר אהבה (ב').","cat": "sage"},{"i": 330,"n": "ר' אדא בר אבוה","l": "א","b": "אמורא שאין לנו פרטים עליו ומובא פעם בש\"ס הירושלמי (ב\"ב פ\"ג ה\"ח).","cat": "sage"},{"i": 331,"n": "רב אדא בר אבימי","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי: תלמידו של ר' זירא (ירו', ברכות פ\"ט ה\"ב).","cat": "sage"},{"i": 332,"n": "רב אדא בר אבין","l": "א","b": "מובא בבבלי (כריתות כ\"א ע\"א). אך הגירסא במקום אחר (יומא ע\"ד ע\"ב): רב אידי בר אבין.","cat": "sage"},{"i": 333,"n": "רב אדא בר אהבה","l": "א","b": "אמורא בבלי בדור הראשון - השני. תלמידו המובהק של רב (ברכות מ\"ב ע\"ב). חברו של רב הונא (ברכות ה' ע\"ב). נולד ביום שמת רבי (קידושין ע\"ב ע\"ב). זכה לאריכות ימים (תענית כ' ע\"ב). לפי שיטת רש\"י חי עד תקופת ר' נחמן בר יצחק (קידושין ע\"ב ע\"ב), ותוס' חולקים וסוברים ששני ר' אדא בר אהבה היו (שם). מקום מושבו היה בפומבדיתא (יבמות ק\"י ע\"ב), שם הרביץ תורה, יחד עם חתנו רב חנא (שם). היה מופלג בצניעות (ברכות כ' ע\"א) ובחסידות (תענית כ' ע\"ב) ומלומד בנסים (שם בירו' תענית ספ\"ג).","cat": "sage"},{"i": 334,"n": "ר' אדא בר אהבה (2)","l": "א","b": "אמורא בדור הששי. תלמידו של רב פפא (חולין קל\"ג ע\"ב). חי בדורו של רב אשי. והוא שאמר: \"מימות רבי עד רב אשי לא מצינו תורה וגדולה במקום אחד\" (סנהדרין ל\"ו ע\"א). [והוא אינו ר' אדא בר אהבה הקודם, שכן הוא נפטר בחיי רבא (ב\"ב כ\"ב ע\"א) ורבא נפטר ביום שנולד רב אשי (קידושין ע\"ב ע\"ב)]. ולפי הגירסאות שצ\"ל רב אחא בריה דרבא במקום רב אדא בר אהבה, לא היו אלא שני רב אדא בר אהבה, ע\"ע רש\"י ותוספות (קידושין ע\"ב ע\"ב).","cat": "sage"},{"i": 335,"n": "אדא בר אוכמי","l": "א","b": "אמורא בבלי בדור השלישי, בזמנו של רב נחמן (ביצה כ\"ו ע\"ב) ופרש\"י: \"חכם א' שהיו מכירין בו שהיה גורס משניות ומשכח ומשבשן\". אין זה ר' אבא בר איכומה (ירו', תענית פ\"א ה\"ג), שם ט\"ס וצ\"ל ר' אדא בר אבימי.","cat": "sage"},{"i": 336,"n": "רב אדא בר אחא","l": "א","b": "מוזכר בירושלמי (ברכות פ\"א ה\"ב), והוא ר' אדא בר אהבה (ע\"ע).","cat": "sage"},{"i": 337,"n": "ר' אדא בר אחא","l": "א","b": "אמורא בבלי בדור הרביעי. מוזכר בבבלי (זבחים כ\"ב ע\"א). נראה, שחי בתקופת אביי (שם).","cat": "sage"},{"i": 338,"n": "רב אדא בר אחוה דר' יהודה","l": "א","b": "אמורא ארץ ישראלי בדור השני. רב זעירא מסר בשמו (ירו', בכורים פ\"א ה\"ה).","cat": "sage"},{"i": 339,"n": "רב אדא בר איכומה","l": "א","b": "מוזכר בירושלמי (תענית פ\"א ה\"ג). וצ\"ל רב אדא בר אבימי (ע\"ע).","cat": "sage"},{"i": 340,"n": "אדא בר בר חנא","l": "א","b": "מוזכר בירושלמי (יבמות ט\"ו ה\"ו). צ\"ל אבא בר בר חנא. והוא הוא רבה בר בר חנא (ע\"ע).","cat": "sage"},{"i": 341,"n": "אדא בר גרשון","l": "א","b": "אמורא שמובא בירושלמי (תרומות פ\"י ה\"ו) פעם אחת בלבד ואין לנו פרטים עליו.","cat": "sage"},{"i": 342,"n": "אדא בר זבדא","l": "א","b": "הוא ר' אבא בר זבדא מובא (ירו', כתובות פי\"ג ה\"ג).","cat": "sage"},{"i": 343,"n": "אדא בר חבו","l": "א","b": "אמורא בבלי בדור הששי - השביעי. שאל את רב אשי ונשא ונתן עמו בהלכה (חולין ע\"ה ע\"ב).","cat": "sage"},{"i": 344,"n": "רב אדא בר חמא","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב ששת (ב\"מ ל' ע\"א).","cat": "sage"},{"i": 345,"n": "רב אדא בר מניומי","l": "א","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא (ב\"ק ל\"א ע\"ב). היה ראש הדיינים בנהרדעא (סנהדרין י\"ז ע\"ב). במחלוקת שהיתה לו עם חברו הונא מר בריה דרב אידי, פסק רבינא כרב אדא (חולין מ\"ט ע\"א).","cat": "sage"},{"i": 346,"n": "רב אדא בר מתנא","l": "א","b": "אמורא בבלי בדור החמישי - הששי. תלמידו של רבא (ברכות ס\"ב ע\"ב), לפניו ישב עם רב פפא חברו (כתובות פ\"ה ע\"א), ותלמידו של אביי (שבת מ\"ח ע\"א), ואמר לאביי \"לאפוקי ממר\" (כתובות ע\"ז ע\"ב). ונראה שגם היה אח\"כ תלמידו של רבינא (זבחים ק' ע\"ב - רש\"י). היה עני גדול (עירובין כ\"ב ע\"א).","cat": "sage"},{"i": 347,"n": "רב אדא בר מתנה","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב (שבת ק\"ט ע\"א). ישב גם לפני רב יוסף, וכשרב יוסף חלה ושכח תלמודו, היה הוא מזכירו באמרו לו: \"בפירוש אמרת לן וכו'\" (פסחים י\"ג ע\"א). היה חברם של רב נחמן ורב ששת וקטן מהם כדמצינו: \"יתיב רב נחמן ורב ששת ויתיב רב אדא בר מתנה גבייהו\" (זבחים ה' ע\"ב).","cat": "sage"},{"i": 348,"n": "רב אדא בר נתן","l": "א","b": "מוזכר בבבלי (חולין מ\"ט ע\"א). ע\"ע רב אחא בר נתן.","cat": "sage"},{"i": 349,"n": "רב אדא בר עזא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אסי (קידושין פ\"א ע\"ב).","cat": "sage"},{"i": 350,"n": "רבי אדא בר פפא","l": "א","b": "מובא בבבלי (ב\"ק פ' ע\"ב).","cat": "sage"},{"i": 351,"n": "רב אדא בר שימי","l": "א","b": "אמורא בבלי בדור החמישי - הששי. הקשה למר בר רב אידאי על דברי רב ביבי בר אביי (חולין ס\"ג ע\"א). ע\"ע רב אידי בר שימי.","cat": "sage"},{"i": 352,"n": "רבי אדא בר תחליפא","l": "א","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי אושעיא (ירו', גיטין פ\"ו ה\"א). ר' חייא בר אבין היה תלמידו (שם).","cat": "sage"},{"i": 353,"n": "רב אדא ברבי חנינא","l": "א","b": "אמורא. אולי ארץ ישראלי. מאמרו: \"אילמלא לא חטאו ישראל לא ניתן להם אלא חמש חומשי תורה וספר יהושע בלבד\" (נדרים כ\"ב ע\"ב). \"ולפי שבעטו וחטאו, נוסף להם רוב חכמה, שאר הספרים, להטריחן יותר\".","cat": "sage"},{"i": 354,"n": "רב אדא בריה דרב אויא","l": "א","b": "מוזכר בבבלי (ב\"ק ס\"ב ע\"א). גירסת הרי\"ף:\" רב אחא בריה דרב אויא\" (ע\"ע).","cat": "sage"},{"i": 355,"n": "רב אדא בריה דרב איקא","l": "א","b": "מוזכר בבבלי (גיטין פ\"ד ע\"ב). אולי זהה לר' אידי בריה דרב איקא. מצינו שרבינא מתקיף על דבריו (שם).","cat": "sage"},{"i": 356,"n": "רב אדא בריה דרב יצחק","l": "א","b": "אמורא בבלי בדור הרביעי בתקופת רבא (זבחים קי\"א ע\"א). רב פפא מתקיף על דבריו, ואביי מוסיף עליהם (גיטין כ\"ח ע\"א).","cat": "sage"},{"i": 357,"n": "רב אדא בריה דרבא","l": "א","b": "מובא בבבלי (חולין נ\"ז ע\"ב). כן הגירסא שם לפי ה\"יוחסין\" ו\"סה\"ד\". לפנינו: ר' אחא בריה דרבא.","cat": "sage"},{"i": 358,"n": "רבי אדא דחוטרא","l": "א","b": "מובא בירושלמי (שקלים פ\"ב ה\"ה). כן גירסת \"יוחסין\" ו\"סה\"ד\". ולפנינו: רבי אידי דחוטרא.","cat": "sage"},{"i": 359,"n": "אדא דיילא","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (ב\"ק קי\"ט ע\"א). היה ארוך בדורו והגיע לכתפיו של רב יהודה (נדה כ\"ד ע\"ב).","cat": "sage"},{"i": 360,"n": "רבי אדא דמן יפו","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מאמרו בבבלי (מגילה ט\"ז ע\"ב) מובא בירושלמי (מגילה פ\"ג ה\"ז) בשם בנו, ר' חייא בריה דר' אדא דמן יפו: \"עשרת בני המן צריך לממרינהו בנשימה אחת\".","cat": "sage"},{"i": 361,"n": "ר' אדא דמן קיסרי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (מו\"ק כ' ע\"ב).","cat": "sage"},{"i": 362,"n": "רב אדא מבי כלוחית","l": "א","b": "אמורא בבלי בדור הרביעי. בן תקופת אביי ורבא. חברו של רב שלמן מבי כלוחית (ביצה ה' ע\"ב).","cat": "sage"},{"i": 363,"n": "רב אדא מסורא","l": "א","b": "מובא בבבלי (נדה ס\"ז ע\"ב). כן גירסת ה\"יוחסין\", \"סה\"ד\" והב\"ח. ולפנינו: רב אדא.","cat": "sage"},{"i": 364,"n": "אדא מרי","l": "א","b": "אמורא בבלי מובא (שבת ס\"ו ע\"ב): \"אמר אדא מרי [פרש\"י: כך שמו] אמר רב נחמן בר ברוך אמר רב אשי בר אבין אמר רב יהודה\". ומובא (זבחים ל\"ח ע\"א) לגירסת \"דק\"ס\": \"אמר רבא רב אדא מרי אסברא לי\". ולפנינו (שם) בר אבא מרי.","cat": "sage"},{"i": 365,"n": "רב אדא משוחאה","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (ב\"מ ק\"ז ע\"ב). נראה, שהוא בר אדא שמזכיר רבא \"בר אדא משוחאה אסברא לי\" (עירובין נ\"ו ע\"ב), ופרש\"י: \"משוחאה מציין תחומי העיר\" ועל שם מלאכתו שהיה מודד קרקעות מכונה משוחאה.","cat": "sage"},{"i": 366,"n": "רב אדא נרשאה","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף. חברו של אביי (שבת ס' ע\"א).","cat": "sage"},{"i": 367,"n": "רב אדא סבא","l": "א","b": "ע\"ע רב אחא סבא.","cat": "sage"},{"i": 368,"n": "אדא ציידא","l": "א","b": "מובא בבבלי (מו\"ק י\"א ע\"א). חי בבבל, בדור הראשון לאמוראים. ספק אם היה חכם. לימד לרב את תכונות הדגים (שם).","cat": "sage"},{"i": 369,"n": "רב אדא קרחינאה","l": "א","b": "אמורא בבלי בדור החמישי. תלמידו של רב כהנא. אמר קמיה משמיה דרבא (יבמות י' ע\"א).","cat": "sage"},{"i": 370,"n": "אדא שמשא","l": "א","b": "מובא בירושלמי (שבת פ\"ב ה\"א). חי בארץ ישראל, בדור השלישי. שאל לר' אמי (שם). היה משמש חולים (שם). ספק אם היה חכם.","cat": "sage"},{"i": 371,"n": "ר' אדאי","l": "א","b": "מובא בירושלמי (ברכות פ\"ב ה\"א), ונראה שהוא ר' אדא.","cat": "sage"},{"i": 372,"n": "רב אדומה נחותה","l": "א","b": "הוא רב דימי.","cat": "sage"},{"i": 373,"n": "ר' אדימי בר המדורא","l": "א","b": "אמורא בדור השני. ר' אבא מפרש דבריו (סוכה כ' ע\"א).","cat": "sage"},{"i": 374,"n": "אדמון","l": "א","b": "אחד מ\"דייני גזירות\" שהיו בירושלים (כתובות ק\"ה ע\"א), לפני חורבן הבית (יוחסין כתב שהיה בזמנו של אבטליון). שם אביו גדאי (שם). על דבריו אמר רבן גמליאל: \"רואה אני את דברי אדמון\" (שם).","cat": "sage"},{"i": 375,"n": "ר' אהבה בר זעירא","l": "א","b": "מובא בב\"ר (פפ\"ד - ט'). בילקוט שמואל הגיר' ר' אחא [אחא זהה לאהבה]. אולי הוא ר' אבא בר זעירא.","cat": "sage"},{"i": 376,"n": "רב אהבה בר כהנא","l": "א","b": "מובא בויק\"ר (פי\"א - א'). נראה, שהוא ר' אבא בר כהנא.","cat": "sage"},{"i": 377,"n": "אהבה בריה דרבי זירא","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. בנו ותלמידו של רבי זירא. שימש \"תנא\" אצל אביו (עירובין צ\"ו ע\"ב). ישב בקיסרין ושם שמע ממנו ר' מנא, בנו של ר' יונא (ירו', פסחים פ\"ב ה\"ד). שמו נשתבש בכמה אופנים.","cat": "sage"},{"i": 378,"n": "רב אהילאי","l": "א","b": "אמורא בבלי בדור השני. בנו נשא לאשה את בת רב יצחק בר שמואל בר מרתא (ברכות כ\"ה ע\"ב) - לגירסת ה\"יוחסין\" ו\"דק\"ס\". לפנינו שם: רב אחאי. ע\"ע רב אחאי. וע\"ע רב אחלי.","cat": "sage"},{"i": 379,"n": "רב אהרון","l": "א","b": "אמורא בבלי בדור הששי. חברו של רבינא, עמו נשא ונתן בהלכה. (ב\"ק ק\"ט ע\"ב).","cat": "sage"},{"i": 380,"n": "רב אויא","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (ברכות כ\"ח ע\"ב) חברו של אביי (שם) ושל רבא (שבת מ\"ו ע\"א). היה גם בארץ ישראל ולמד לפני רבי אמי (חולין נ' ע\"א).","cat": "sage"},{"i": 381,"n": "רב אויא סבא א'","l": "א","b": "אמורא בבלי בדור השני. תלמידו של רב הונא (ביצה כ\"א ע\"א).","cat": "sage"},{"i": 382,"n": "רב אויא סבא ב'","l": "א","b": "אמורא בבלי בדור החמישי. חברו של רב פפא (מו\"ק כ\"ד ע\"ב).","cat": "sage"},{"i": 383,"n": "אוירא סבא","l": "א","b": "ע\"ע רב עוירא סבא.","cat": "sage"},{"i": 384,"n": "רב אוירא סבא","l": "א","b": "מובא בבבלי (פסחים נ\"א ע\"א). ב\"סה\"ד\": \"אולי צ\"ל אויא\" (סבא).","cat": "sage"},{"i": 385,"n": "אולפנא","l": "א","b": "מובא בבבלי (עירובין ס\"ז ע\"א), ופירש\"י: \"ששמע מרבו ורבו מרבו\". \"יוחסין\" כתב: \"והיה נראה שהוא שם חכם או ר\"ל כמ\"ש במקומות אחרים משמיה דגמרא\".","cat": "sage"},{"i": 386,"n": "און בר אמי","l": "א","b": "מובא בירושלמי (שבת פ\"ו ה\"ה). כן גירסת ה\"יוחסין\" ו\"סה\"ד\". ולפנינו: אנן בר אימא, ולפני \"אור זרוע\" (ח\"ב ספ\"ד):\" חנן בר אימי\" (ע\"ע).","cat": "sage"},{"i": 387,"n": "ר' אוניא","l": "א","b": "מובא בשה\"ר (פ\"ב - ז').","cat": "sage"},{"i": 388,"n": "אונקלוס","l": "א","b": "יש מטילים ספק אם אונקלוס ועקילס הם אותו אדם. תנא בדור השלישי. גר צדק. בן אחותו של אדריאנוס (תנחומא משפטים ג'). בבבלי (גיטין נ\"ו ע\"ב) מובא שהיה בן אחותו של טיטוס הרשע (וגיר' הגר\"א: בן אחותו של אדריאנוס). רבותיו היו רבי אליעזר ורבי יהושע: \"תרגום של תורה אונקלוס הגר אמרו מפי ר\"א ור' יהושע\" (מגילה ג' ע\"א). וכן היה תלמידו של רבי עקיבא: \"תירגם עקילס הגר לפני ר\"ע\" (ירו', קידושין פ\"א ה\"א). חברו של רבן גמליאל (תוספתא מקואות פ\"ו). בתרגומו יש שאונקלוס מוסיף מלים על הפסוק. פרש\"י (קידושין מ\"ט ע\"א): \"ואונקלוס כשהוסיף לא מדעתו הוסיף שהרי בסיני ניתן אלא שנשתכח וחזר ויסדו\".","cat": "sage"},{"i": 389,"n": "אונקלוס בר קלונימוס","l": "א","b": "ע\"ע אונקלוס.","cat": "sage"},{"i": 390,"n": "ר' אורי","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו דרב יוסף (ירו' ברכות רפ\"ב).","cat": "sage"},{"i": 391,"n": "רב אושעיא","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו המובהק של רב יהודה (ב\"מ מ\"ג ע\"ב) וכן תלמידו של ר\"ה (ברכות ל\"ז ע\"ב). כשעלה לארץ ישראל היה תלמידו של ר' יוחנן, שרצה לסמוך אותו ולא עלתה בידו (סנהדרין י\"ד ע\"א). היה אחיו של רבה (מהרש\"א בסנהדרין שם). היה תדיר יחד עם אחיו השני רב חנינא (מכות י\"ט ע\"ב). ושניהם עסקו בספר היצירה (סנהדרין ס\"ה ע\"ב).","cat": "sage"},{"i": 392,"n": "רבי אושעיא","l": "א","b": "מגדולי אמוראי ארץ ישראל בדור הראשון. זכה לכינוי \"אבי המשנה\" (ירו', ב\"ק פ\"ד ה\"ו). תלמידם של בר קפרא (מו\"ק כ\"ד ע\"ב) ור' חייא (ירו', שבת פ\"ג ה\"א). הברייתות שהוא ורבו ר' חייא כתבו, היו מקובלות בבית המדרש כמהימנות ומדוייקות (חולין קמ\"א ע\"א). ישיבתו היתה בקיסרין (ירו', תרומות פ\"י ה\"ב). היה רבו של ר' יוחנן (עירובין נ\"ג ע\"א). אביו ר' חמא ואבי אביו ר' ביסא, היו חכמים גדולים, ועליהם אמרו: \"והחוט המשולש לא במהרה ינתק\" (ב\"ב נ\"ט ע\"א). שם בתוס' נראה שהיה גדול מאביו. עליו אמרו כדוגמת רבי מאיר \"לא יכלו חבריו לעמוד על סוף דעתו\" (עירובין שם).","cat": "sage"},{"i": 393,"n": "רבי אושעיא בנו של רבי יהודה הבשם","l": "א","b": "תנא בדור השלישי - הרביעי. תלמידו של ר\"ע. והעיד לפניו משמו של רבי טרפון (חולין נ\"ה ע\"ב). בתוספתא (חולין פ\"ג ה\"ז וכן בשביעית פ\"ה הי\"ב) הגירסא: ר' יהודה בן ישעיה הבשם, (ע\"ע).","cat": "sage"},{"i": 394,"n": "רבי אושעיא בנו של ר' חמא בר ביסא","l": "א","b": "מובא בבבלי (ב\"ב נ\"ט ע\"א). והוא רבי אושעיא סתם.","cat": "sage"},{"i": 395,"n": "רבי אושעיא בר אבא","l": "א","b": "מובא בירושלמי (גיטין פ\"ד ה\"ב), ואולי צ\"ל: רבי אושעיא רבה.","cat": "sage"},{"i": 396,"n": "אושעיא בר זבדא","l": "א","b": "אמורא שאין לקבוע זמנו ומקומו. התקיף על דברי רבי יהושע בן לוי, ור' יצחק תירץ קושייתו (תענית כ\"ו ע\"ב).","cat": "sage"},{"i": 397,"n": "ר' אושעיא בר חייא","l": "א","b": "אמורא ארץ ישראלי בדור הראשון. חברם של רבי חייא ורבי אושעיא (יבמות מ\"ו ע\"ב).","cat": "sage"},{"i": 398,"n": "רבי אושעיא בר שימי","l": "א","b": "אמורא ארץ ישראלי בדור הששי. מושבו היה בקיסרין (ירו', כלאים פ\"ו ה\"ג). בנו של ר' שמאי, שהיה מאמוראי א\"י בדור הרביעי. היה תלמידו של ר' יצחק בר אלעזר, וקרא לו ולחברו ר' בורקי: עדה קדושה (קה\"ר פ\"ט - ט'). ר' מנא עמד עמו בקשרי מכתבים (ירו', מגילה פ\"ג ה\"ב).","cat": "sage"},{"i": 399,"n": "רבי אושעיא בריבי","l": "א","b": "מובא בבבלי (עירובין נ\"ג ע\"א), והוא רבי אושעיא. ופרש\"י ד\"ה אושעיא בריבי: \"אדם גדול בדורו, וכל היכי דקרי בריבי הכי פירושו\".","cat": "sage"},{"i": 400,"n": "אושעיא זעירא דמן חבריא","l": "א","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. עוד בהיותו צעיר שבישיבה, היה מופלג בחסידות וכל מעשיו היו לשם שמים (תענית כ\"ד ע\"א). מצינו ששמו מובא (נדה כ\"ו ע\"א): ושם ר' אושעיא וכו'.","cat": "sage"},{"i": 401,"n": "רבי אושעיא תורגמא","l": "א","b": "אמורא ארץ ישראלי בדור השני. רבי תנחומא בר חייא (שמסר בשם רבי יהושע בן לוי), מסר בשמו (ב\"ר פנ\"א - ט').","cat": "sage"},{"i": 402,"n": "רב אושעיה","l": "א","b": "אמורא בבלי בדור החמישי. תלמידו של רבא \"תני ר' אושעיא קמיה דרבא\" (ברכות ט\"ו ע\"ב). וגירסת \"דק\"ס\": \"תני רבי יאשיה קמיה דרבא\".","cat": "sage"},{"i": 403,"n": "אחא","l": "א","b": "מובא בבבלי (שבת נ\"ו ע\"ב). חי בדור הראשון לאמוראי בבל. היה אחי אביו של רבי ירמיה בר אבא (שם). היה בעל תשובה גדול (שם).","cat": "sage"},{"i": 404,"n": "רב אחא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. היה דיין בעירו (ירו', ב\"ב פ\"ח ה\"א). מובא רבות בירושלמי. תלמידם של ר' יוסי בר חנינא (ירו', יבמות פ\"א ה\"ב) ור' אבא (ירו', שבת רפ\"ו). היה חברו ובן עירו של ר' יהודה בן פזי (ירו', סנהדרין פ\"א ה\"ב). גדולי דור הרביעי קבלו ממנו, וביניהם ר' יונה ור' יוסי (ירו', ברכות פ\"ב ה\"ד). כשנפטר חשכו השמים ונראו כוכבים בעצם היום (ירו', ע\"ז פ\"ג ה\"א).","cat": "sage"},{"i": 405,"n": "רבי אחא","l": "א","b": "תנא בדור הרביעי - החמישי. מסר משום ר\"ע (תוספתא שבת ספט\"ז). מצינו אותו חולק על תלמידי ר\"ע: רבי שמעון (שבת קכ\"ז ע\"א) ורבי אלעזר (שבת ל\"ב ע\"א) ור\"א בן יעקב (גיטין ל\"ב ע\"א - שם הגירסא ר' אחי). בשמו מסר רבי שמעון בן חלפתא (פסיקתא רבתי פסקא דביום השמיני).","cat": "sage"},{"i": 406,"n": "ר' אחא","l": "א","b": "ע\"ע ר' אדא או ר' אחי או ר' אחאי.","cat": "sage"},{"i": 407,"n": "רב אחא אחוה דמר אחאי","l": "א","b": "מובא בבבלי (שבת קי\"א ע\"ב). כן גירסת הדפוסים הישנים. וכך היתה הגירסא לפני ה\"יוחסין\" ו\"סה\"ד\". אך לפנינו הגירסא: רב אחדבוי אחוי דמר אחא.","cat": "sage"},{"i": 408,"n": "רב אחא אריכא","l": "א","b": "אמורא בבלי בדור השלישי. והוא רב אחא בר פפא המכונה רב אחא אריכא (שבת קי\"א ע\"א). תלמיד של רב הונא (מנחות ל\"ה ע\"ב). כשעלה לארץ ישראל, שאל מרבי אבהו (שבת שם), מרבי אבא (שבת קי\"ג ע\"א) ומרבי זעירא (ירו', מע\"ש פ\"ה ה\"ה). מצינו שהתיר נדר לרבי אמי (ירו', נדרים פ\"י ה\"ח).","cat": "sage"},{"i": 409,"n": "רב אחא בר אבא","l": "א","b": "שמו מובא בבבלי מספר פעמים (שבת קי\"ג ע\"ב: קידושין פ\"א ע\"ב: ע\"ז י\"ט ע\"ב ועוד), אך נראה שיש טעות בשם, ולפי גירסאות הרא\"ש, האשר\"י, \"דק\"ס\", ו\"מסורת הש\"ס\" לא היה מעולם אמורא בשם זה.","cat": "sage"},{"i": 410,"n": "ר' אחא בר אבא בר אחא","l": "א","b": "מובא בבבלי (ברכות כ\"ה ע\"ב): \"ר' אחא בר אבא בר אחא בשם רבינו\" י\"א שצ\"ל: ר' אבא בר אחא.","cat": "sage"},{"i": 411,"n": "רב אחא בר אביי","l": "א","b": "אמורא בבלי בסוף הדור הששי. נראה, כי היה חברו של רבינא, שעמו נשא ונתן (ב\"ק ל\"ט ע\"ב).","cat": "sage"},{"i": 412,"n": "רבי אחא בר אבין בר בנימין","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא (שהש\"ר פ\"ח - ו') אמר בשם רבי אחא בריה דרב פפא (הוא רבי אחא אריכא) ו\"סה\"ד\" כתב: \"נראה כי רב אחא ט\"ס\".","cat": "sage"},{"i": 413,"n": "רב אחא בר אדא","l": "א","b": "אמורא בבלי בדור השלישי. תלמידם של רב (ברכות כ\"ט ע\"ב) ושל רב המנונא (עירובין ע\"ז ע\"ב). אמר משמיה דרב יהודה (סנהדרין צ' ע\"ב). היה בארץ ישראל וחזר לבבל (קידושין ל' ע\"א). האריך ימים עד תקופת רבא (ב\"ב קס\"ז ע\"א).","cat": "sage"},{"i": 414,"n": "רב אחא בר אהבה","l": "א","b": "מובא בבבלי (עירובין צ\"ח ע\"א). אך \"דק\"ס\" גורס: \"רב אדא בר אהבה\", וכן יש גורסים במקום אחר (יומא מ\"ד ע\"ב).","cat": "sage"},{"i": 415,"n": "רב אחא בר אושעיא","l": "א","b": "מובא ברא\"ש (רפ\"א דעירובין).","cat": "sage"},{"i": 416,"n": "רב אחא בר אחווא","l": "א","b": "מובא בירושלמי (שבועות פ\"א ה\"א), והוא זהה לרב אחו בר אהבה.","cat": "sage"},{"i": 417,"n": "רב אחא בר אילא","l": "א","b": "מובא בב\"ר (פצ\"ד - ד'), והוא רב אחא בר עולא.","cat": "sage"},{"i": 418,"n": "רב אחא בר אלישיב","l": "א","b": "מובא בויק\"ר (פל\"ה - ו').","cat": "sage"},{"i": 419,"n": "אחא בר ביבי מר","l": "א","b": "אמורא בבלי בדור הששי. תלמידו של רבינא (יבמות ח' ע\"א). אמר שמועה בשם רבא (שם).","cat": "sage"},{"i": 420,"n": "רב אחא בר ביזנא","l": "א","b": "מובא בבבלי (ברכות ג' ע\"ב). יתכן שאמורא בעל שם זה לא היה כלל. שכן אותו מאמר מובא במקום אחר (סנהדרין ט\"ז ע\"א), ושם רב אחא בר ביזנא, וכן כתב \"סה\"ד\": \"ט\"ס, וכן הוא ב'עין יעקב' רב חנא בר ביזנא, ובשס\"ח לא תקנו\".","cat": "sage"},{"i": 421,"n": "ר' אחא בר גמדא","l": "א","b": "מובא ב\"ילקוט\" (משלי סוף רמז תתקל\"ב), ואולי ט\"ס וצ\"ל: ר' חייא בר גמדא, המובא בבבלי (מגילה ל\"א ע\"ב).","cat": "sage"},{"i": 422,"n": "ר' אחא בר זבינא","l": "א","b": "מובא (במד\"ר פ\"ח - ר') והגיר' (ירו', קידושין פ\"ד ה\"א) ר' אבא בר זמינא.","cat": "sage"},{"i": 423,"n": "רב אחא בר זעירא","l": "א","b": "(ע\"ע ר' אהבה בר זעירא). בלשון ירושלמי \"אחא\" הוא \"אהבה\".","cat": "sage"},{"i": 424,"n": "רבי אחא בר חיננא","l": "א","b": "מובא בירושלמי (פ\"ג ה\"ז), והוא רבי אחא בר חנינא.","cat": "sage"},{"i": 425,"n": "ר' אחא בר חנא","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב ששת (עירובין ס\"ח ע\"ב). \"דק\"ס\" גורס: רבה בר רב חנא.","cat": "sage"},{"i": 426,"n": "רבי אחא בר חנינא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מושבו היה בדרום (חולין קל\"ב ע\"ב). תלמידו של ר' אסי (סנהדרין מ\"ב ע\"א) ושל רבי אבהו (יבמות ס\"ה ע\"ב). ר' לוי מסר בשמו (ירו', ברכות פ\"ב ה\"ד), וכן ר\"ז (פסחים נ\"א ע\"א). על דבריו התבססו אמוראי בבל: \"והאמר ר' אחא בר חנינא\" (חולין קל\"ב ע\"ב: עירובין ס\"ד ע\"א). היה עני מרוד (שבת קי\"ד ע\"א).","cat": "sage"},{"i": 427,"n": "ר' אחא בר יאשיה","l": "א","b": "מובא בבבלי (נדרים כ' ע\"א), ונראה שצ\"ל: ר' אחי בר יאשיה.","cat": "sage"},{"i": 428,"n": "רב אחא בר יוסף","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (שבת ק\"מ ע\"א) ושל רב חסדא (ב\"מ פ\"ז ע\"א). רב נחמן בר יצחק היה בן אחותו (שם).","cat": "sage"},{"i": 429,"n": "רב אחא בר יעקב","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב הונא (יבמות ס\"ד ע\"ב). האריך ימים, ורב פפא עוד היה תלמידו (חולין ל\"ג ע\"א). רבא שיבחו לפני רב נחמן שהוא אדם גדול, ור\"נ לא ידע להשיב על שאלותיו (ב\"ק מ' ע\"א). היה מראשי העיר פפוניא, הסמוכה לפומבדיתא (נדה ס\"ז ע\"ב). היה מלומד בנסים (קידושין כ\"ט ע\"ב). נפטר מתוך עין הרע (ב\"ב י\"ד ע\"א).","cat": "sage"},{"i": 430,"n": "רבי אחא בר יצחק","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. שאל מר' זעירא (ירו', שבת פ\"ו ה\"ב). חברו של ר' אבא בר ממל (ירו', שבת פ\"ג ה\"ג).","cat": "sage"},{"i": 431,"n": "ר' אחא בר לא","l": "א","b": "הוא ר' אחא בר אילא מובא בירו' (דמאי פ\"ו ה\"ב).","cat": "sage"},{"i": 432,"n": "רב אחא בר מניומי","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב נחמן (ב\"ק ק\"ו ע\"א). נשא ונתן בהלכה עם אביי (ב\"ק נ\"ט ע\"ב), ומצינו שרבא משיב על דבריו (נדרים מ\"ז ע\"ב).","cat": "sage"},{"i": 433,"n": "רב אחא בר נתן","l": "א","b": "אמורא בבלי בדור החמישי. מובא בבבלי (חולין מ\"ט ע\"א) לפי גירסת הרא\"ש. חלק עם מר זוטרא בריה דרב מרי (שם).","cat": "sage"},{"i": 434,"n": "ר' אחא בר סימון","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בב\"ר (ספמ\"א). ור' עזריה אומר משמו (שם).","cat": "sage"},{"i": 435,"n": "רב אחא בר עויא","l": "א","b": "הוא רב אחא בר רב עויא.","cat": "sage"},{"i": 436,"n": "רב אחא בר עוירא","l": "א","b": "אמורא בבלי בדור השביעי. תלמיד של רב אשי (ברכות מ\"ד ע\"א). יתכן שהשם משובש, והוא: רב אחא בר אויא.","cat": "sage"},{"i": 437,"n": "ר' אחא בר עולא","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (שבת נ\"ד ע\"ב). עלה לארץ ישראל ונשא ונתן שם עם רבי זירא (ירו', עירובין פ\"א ה\"א). מצינו, שרב פפא בריה דרב אחא בר אדא אמר משמו (עירובין כ\"א ע\"ב). היה עמל בתורה ועל כן נתן לו ר' יונה מעשר, על אף שלא היה כהן (ירו', מע\"ש פ\"ה ה\"ג).","cat": "sage"},{"i": 438,"n": "רב אחא בר עזא","l": "א","b": "הוא רב אדא בר עזא.","cat": "sage"},{"i": 439,"n": "רב אחא בר עילא","l": "א","b": "מובא בירושלמי (עירובין פ\"א ה\"א), והוא רב אחא בר עולא.","cat": "sage"},{"i": 440,"n": "אחא בר פנחס","l": "א","b": "אמורא בבלי בדור הרביעי. מובא בבבלי (מו\"ק ט\"ו ע\"א). מסר בשמו של רב יוסף (שם).","cat": "sage"},{"i": 441,"n": "רב אחא בר פפא","l": "א","b": "מובא בבבלי (שבת קי\"א ע\"א), וע\"ע רב אחא אריכא.","cat": "sage"},{"i": 442,"n": "רב אחא בר פפי","l": "א","b": "מובא בירושלמי (יבמות פ\"ח ה\"ב). נראה, שהוא רב אחא בר פפא, וע\"ע רב אחא אריכא.","cat": "sage"},{"i": 443,"n": "רב אחא בר רב","l": "א","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא הראשון (קידושין י\"ג ע\"א), ומצינו שהקשה לו (חולין ל\"ג ע\"א). חלק עם רבינא האחרון ובענין זה באו לשאול אצל מר בר רב אשי (חולין צ\"ז ע\"ב, לפי גירסת הב\"ח).","cat": "sage"},{"i": 444,"n": "אחא בר רב הונא","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רבה (שבועות ל\"ו ע\"ב), של רב יוסף (קידושין י\"ב ע\"ב), של ר' ששת (ב\"ב ע' ע\"א) ושל רב נחמן (חולין ע\"ו ע\"ב). היה שליח להעברת הלכות בין רב חסדא לרבה (פסחים מ\"ז ע\"א). רבא קרא לו \"גברא רבא\" (נדרים צ' ע\"א). ושאל מרבא (קידושין נ' ע\"ב).","cat": "sage"},{"i": 445,"n": "רב אחא בר רב הונא","l": "א","b": "מובא בבבלי (חולין נ\"ט ע\"ב), יחד עם חכם סבוראי אחר - רב שמואל בריה דרב הונא. נפטר ביום א', ד' אדר תתי\"ז לשטרות [ד\"א רס\"ו] - (605), (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 446,"n": "רב אחא בר רב חנה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי (ע\"ז ל\"ח ע\"ב: מנחות ל\"א ע\"ב). תלמידו של רבי יוחנן (שם), ואולי הוא ר' אחא בר חנא.","cat": "sage"},{"i": 447,"n": "רב אחא בר רב עוא","l": "א","b": "מובא בבבלי (חולין נ' ע\"ב), וצ\"ל: רב אחא בר רב עויא.","cat": "sage"},{"i": 448,"n": "רב אחא בר רב עויא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (פסחים ל\"ג ע\"ב) ושל רבי אסי (ב\"ב נ\"ו ע\"א). כשירד לבבל, למד לפני רב חסדא (פסחים שם).","cat": "sage"},{"i": 449,"n": "רב אחא בר רב קטינה","l": "א","b": "ע\"ע רב חנינא בר רב קטינא ורב הונא בר רב קטינא.","cat": "sage"},{"i": 450,"n": "רב אחא בר רבינא","l": "א","b": "אמורא בבלי בדור הששי. בן דורו של רב אשי, ששלח לו שבסר זוזי בפדיון הבן (בכורות ג' ע\"א). יש סוברים, שצ\"ל: רב אחא בריה דרבא.","cat": "sage"},{"i": 451,"n": "אחא בר שילא איש כפר תמרתא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. בעל אגדה. ר' לוי מסר בשמו (אס\"ר ספ\"ו).","cat": "sage"},{"i": 452,"n": "רב אחא בר שישא","l": "א","b": "מובא בבבלי (שבת ס' ע\"א) לגירסת \"דק\"ס\", אבל לפנינו: רב אדא נרשאה.","cat": "sage"},{"i": 453,"n": "רב אחא בר תחליפא","l": "א","b": "אמורא בבלי בדור החמישי. תלמיד של רבא (ב\"ק ל\"ד ע\"ב). חברו של ר' אלעזר מהגרוניא: שניהם בקרו בביתו של רב אחא בר איקא (עירובין ס\"ג ע\"א). כשחלק עם רבינא, הכריע רבא כרב אחא בר תחליפא (גיטין ע\"ג ע\"א).","cat": "sage"},{"i": 454,"n": "רב אחא ברדלא","l": "א","b": "אמורא בבלי בדור השני. תלמיד של רב (סוכה כ\"ו ע\"א).","cat": "sage"},{"i": 455,"n": "רב אחא בריה דרב אויא","l": "א","b": "אמורא בבלי בדור הששי - השביעי. היה תלמידו של רב אשי (ב\"מ ק\"ט ע\"ב ברש\"י ד\"ה: כי מטית). נראה שהשתתף עם רב אשי בסידור הש\"ס (עירובין מ\"ח ע\"ב).","cat": "sage"},{"i": 456,"n": "רב אחא בריה דרב אחא","l": "א","b": "אמורא בבלי בדור השביעי. מצינו שהקשה לרב אשי (שבת ק\"א ע\"א). \"דק\"ס\" גורס: \"בריה דרבא\".","cat": "sage"},{"i": 457,"n": "רב אחא בריה דרב איקא","l": "א","b": "אמורא בבלי בדור החמישי. בן אחותו ותלמידו של רב אחא בר יעקב (כתובות ע\"ד ע\"א). חברו של רב פפא ונשא ונתן עמו (שבת ו' ע\"א) וכן עם רב אשי (ברכות ו' ע\"א). אביו נקרא על שמו. אולי היה גדול מאביו (ע\"ז ס\"ה ע\"א).","cat": "sage"},{"i": 458,"n": "רב אחא בריה דרב אמי","l": "א","b": "מובא בבבלי (יומא פ\"ד ע\"א). יתכן שאמורא בעל שם זה לא היה כלל. וגירסת \"דק\"ס\" שם: \"רב אחא בריה דרבא\", כפי שמובא אותו מאמר במקום אחר (ע\"ז כ\"ח ע\"א), ובמקום שלישי (זבחים ס\"א ע\"ב) אותו מאמר לפי גירסת \"שיטה מקובצת\": \"רב אחדבוי בר אמי\".","cat": "sage"},{"i": 459,"n": "רב אחא בריה דרב אשי","l": "א","b": "מובא בבבלי (זבחים צ\"א ע\"א). יתכן שאמורא בעל שם זה לא היה כלל. גירסת \"דק\"ס\": רב אחא בריה דרבא. וכן גירסת השאלתות במקום אחר (חולין צ\"ז ע\"ב - עיין מסורת הש\"ס): רב אחא בר רב. כן גרס הב\"ח.","cat": "sage"},{"i": 460,"n": "רב אחא בריה דרב חייא","l": "א","b": "אמורא בדור השביעי. שאל מרב אשי (נדרים י' ע\"ב).","cat": "sage"},{"i": 461,"n": "רב אחא בריה דרב יוסף","l": "א","b": "אמורא בבלי בדור הששי. שאל מרב אשי (יבמות ל\"א ע\"ב). היה חריף ומעמיק (ב\"מ ק\"ט ע\"ב ברש\"י ד\"ה: כי).","cat": "sage"},{"i": 462,"n": "רב אחא בריה דרב ייבא","l": "א","b": "אמורא בבלי בדור הששי - השביעי מצינו שאמר משמיה דמר זוטרא (נדה ס\"א ע\"ב), ורב אשי הקשה על דבריו (שם).","cat": "sage"},{"i": 463,"n": "רב אחא בריה דרב נחמן","l": "א","b": "אמורא בבלי בדור הרביעי. בנו של רב נחמן (שבת קי\"ד ע\"א). אך \"דק\"ס\" גורס שם: מר זוטרא, ואם כן לא היה קיים כלל אמורא ושמו רב אחא בריה דרב נחמן, שכן הוא נזכר בש\"ס רק בפעם זאת.","cat": "sage"},{"i": 464,"n": "רב אחא בריה דרבא","l": "א","b": "אמורא בבלי בדור הששי. תלמיד מובהק לר' כהנא (סוכה ל\"ב ע\"ב). נשא ונתן רבות עם רב אשי. יותר משבעים פעם נמצא בש\"ס הלשון: \"אמר ליה רב אחא בריה דרבא לרב אשי\". היה כתלמיד - חבר לרב אשי (חולין י\"ז ע\"ב), אמר על רב אשי \"מימות רבי ועד רב אשי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). היה גם חברו של רבינא (פסחים ל\"ט ע\"א). עמד בראש ישיבת פומבדיתא מד\"א קע\"ד (414) עד פטירתו בשנת קע\"ט (914) (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 465,"n": "ר' אחא בריה דרבה","l": "א","b": "מובא בבבלי (יבמות מ\"ה ע\"ב). והוא רב אחא בריה דרבא.","cat": "sage"},{"i": 466,"n": "ר' אחא בריה דר' בא בר ממל","l": "א","b": "מובא בירושלמי (שבת פ\"ו ה\"ו). יש דפוסים שבהם כתוב: ר' אחא בשם ר' בא בר ממל.","cat": "sage"},{"i": 467,"n": "רב אחא בריה דר' חייא בר אבא","l": "א","b": "מוזכר בבבלי (ברכות י\"ד ע\"א). יתכן שאמורא נושא שם זה לא היה כלל, שכן גירסת \"דק\"ס\": א\"ר אבא בריה דר' חייא בר אבא. ו\"סה\"ד\" מפקפק: \"אולי צ\"ל ר' אבא בריה דר' חייא בר אבא\", ועוד, אם נגרוס אחא ולא אבא, האם הוא זהה לר' אחא בריה דר' חייא המובא בבבלי? (נדרים י' ע\"ב).","cat": "sage"},{"i": 468,"n": "רב אחא גלילאה","l": "א","b": "מובא בבבלי (ע\"ז ג' ע\"ב). כן גירסת ה\"יוחסין\", \"סה\"ד\", \"עין יעקב\" ו\"דק\"ס\". ולפנינו: \"א\"ל רב אחא [בלי גלילאה] לרב נחמן בר יצחק: 'מיום שחרב בית המקדש אין שחוק להקב\"ה\".","cat": "sage"},{"i": 469,"n": "אחא כרסלא","l": "א","b": "מובא בבבלי (סנהדרין ה' ע\"א). חי בבבל בדור המעבר בין התנאים לאמוראים. אבי אביו של רבי חייא (שם). אין ראיה שהיה חכם.","cat": "sage"},{"i": 470,"n": "רב אחא מבי חוזאה","l": "א","b": "מובא בבבלי (גיטין ז' ע\"א). נראה, שהיה בזמנו של רב אשי (כן דעת \"סה\"ד\"). לפי גירסת רב שרירא גאון צ\"ל: \"רב אחא מבי חתים\", והוא מרבנן סבוראי. וכן דעת בעל ה\"כריתות\" שהוא היה ריש מרבנן סבוראי.","cat": "sage"},{"i": 471,"n": "רב אחא מבי חתים","l": "א","b": "ע\"ע רב אחא מבי חוזאה.","cat": "sage"},{"i": 472,"n": "רב אחא מגדלאה","l": "א","b": "מובא בילקוט (ישעיה רמז).","cat": "sage"},{"i": 473,"n": "רב אחא מדפתי","l": "א","b": "אמורא בבלי בדור השביעי. תלמיד של רבינא. עשרות פעמים מוזכר הלשון בש\"ס: \"אמר ליה רב אחא מדפתי לרבינא\" (שבת קל\"ט ע\"ב). תלמיד של מרימר (ברכות מ\"ה ע\"ב). חברם של יהודה בר מרימר ומר בר רב אשי (שם), והיו שווים בחכמה ושנים ולא היה אחד מופלג וגדול מחברו (שם ברש\"י). רצו למנותו לראש ישיבה, אך מר בר רב אשי הקדימו (ב\"ב י\"ב ע\"ב).","cat": "sage"},{"i": 474,"n": "רב אחא מהוצל","l": "א","b": "אמורא בבלי בדור הששי. מובא בבבלי (ביצה ל\"ב ע\"ב). חברו של רבינא (שם). היה לו נדר להתיר ובא לרב אשי (כריתות י\"ג ע\"ב).","cat": "sage"},{"i": 475,"n": "רב אחא מפרזקיא","l": "א","b": "אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי (יבמות נ\"ט ע\"ב - לגירסת הרא\"ש: וכן לגירסת התוספות בתמורה ל' ע\"ב ד\"ה: מנא). ולפנינו הגירסא: רבא מפרקין. ומסורת הש\"ס מתקן: רבא מפרזקיא.","cat": "sage"},{"i": 476,"n": "רב אחא סבא","l": "א","b": "אמורא בבלי בדור החמישי - הששי. נשא ונתן עם רב אשי (קידושין כ\"א ע\"א). היה בנו של רב מרי בר איסור (שם ס\"ה ע\"ב). (עיין מר זוטרא בריה דרב מרי). יש גירסא ר' אדא סבא, אך \"סה\"ד\" גורס: ר' אחא סבא.","cat": "sage"},{"i": 477,"n": "רב אחא קרחינאה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמיד של רבי אלעזר (ברכות ל\"ג ע\"א). בסנהדרין (צ\"ב ע\"א) מובא שמו בטעות: ר' אדא קרחינאה וצ\"ל: ר' אחא קרחינאה. ויש רב אדא קרחינאה, אמורא בבלי בדור החמישי.","cat": "sage"},{"i": 478,"n": "רב אחא קרטיגנאה","l": "א","b": "בשם זה יש שיבושים. בבבלי (ב\"ק קי\"ד ע\"ב) מובא: \"א\"ר חנא קרטיגנאה ואמרי לה רב אחא קרטיגואה\", ובאותו ענין: \"א\"ר חנן קרטיגנאה\" (כתובות כ\"ז ע\"ב). ובענין אחר מובא \"חיננא קרתיגנאה\" (ירו', שבת פט\"ז ה\"ב), ובאותו ענין בשיבוש: \"חיננא קרתחמה\" (שם ביצה פ\"א ה\"ו).","cat": "sage"},{"i": 479,"n": "ר' אחא רובא","l": "א","b": "אמורא ארץ ישראלי בדור השני. מצינו שרבי אסי מסר בשמו (ירו', ברכות פ\"ב ה\"ד).","cat": "sage"},{"i": 480,"n": "רבי אחא שר הבירא (2)","l": "א","b": "תנא בדור הרביעי. בבבלי (ב\"ב קמ\"ו ע\"א) מובא: \"וזו הלכה העלה רב [צ\"ל רבי] אחא שר הבירה לפני חכמים באושא\".","cat": "sage"},{"i": 481,"n": "רב אחאי (2)","l": "א","b": "מובא בבבלי (זבחים ק\"ב ע\"ב). בתוספות שם כתבו: \"שהיה מרבנן סבוראי דבתר רבינא ורב אשי דהוסיף הוראה וכתבו אחרי כן דבריו בסוף הש\"ס\".","cat": "sage"},{"i": 482,"n": "ר' אחאי (2)","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שמסר בשם רבי אבא בר ממל (תרומות פ\"י ה\"א).","cat": "sage"},{"i": 483,"n": "ר' אחאי בר יעקב","l": "א","b": "מובא בירושלמי (שבת פ\"ב ה\"ו), ונראה שהוא הוא ר' אחא בר יעקב.","cat": "sage"},{"i": 484,"n": "ר' אחאי בריבי","l": "א","b": "מובא בבבלי (בכורות כ\"ד ע\"ב), ופרש\"י: \"אדם גדול וחשוב בדורו\" ואין לקבוע במדוייק מי הוא. ע\"ע בריבי.","cat": "sage"},{"i": 485,"n": "רב אחדבוי","l": "א","b": "אמורא בבלי בדור השני. תלמידו של רב, כדמצינו: \"אמר רב אחדבוי אמר רב\" (ע\"ז ל\"ד ע\"ב). ופירש\"י: \"אחדבוי שם חכם\".","cat": "sage"},{"i": 486,"n": "רב אחדבוי אחוי דמר אחא","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת קי\"א ע\"ב). ע\"ע רב אחא אחוה דמר אחאי.","cat": "sage"},{"i": 487,"n": "רב אחדבוי בר אמי","l": "א","b": "אמורא בבלי בדור השני - השלישי. מסר בשם רב (תמורה ל' ע\"ב). מהלשון נראה כאילו קיבל תורה מפי רב חסדא (פסחים ע\"ה ע\"א), ואולי אף מרב ששת (סנהדרין נ\"ה ע\"א). אך נראה יותר שהיה חברם.","cat": "sage"},{"i": 488,"n": "רב אחדבוי בר רב מתנה","l": "א","b": "אמורא בבלי בדור השלישי. מצינו שמסר בשם רב מתנה אביו (שבת ס' ע\"ב). גם אחיו רב טובי היה אמורא (ב\"ב קנ\"א ע\"א).","cat": "sage"},{"i": 489,"n": "רב אחו בר אהבה","l": "א","b": "הוא רב אחא בר אחווא.","cat": "sage"},{"i": 490,"n": "אחוה בר זעירא","l": "א","b": "ע\"ע ר' אהבה בר זעירא. בלשון ירושלמי \"אחוה\" הוא \"אהבה\".","cat": "sage"},{"i": 491,"n": "אחוה דבר אבוברם","l": "א","b": "אמורא בבלי בדור החמישי - הששי. בנו של האמורא אבוברם (חולין ל\"ח ע\"א). ע\"ע אבוברם.","cat": "sage"},{"i": 492,"n": "ר' אחווא בר' זירא","l": "א","b": "מובא בירושלמי (פסחים פ\"ב ה\"ד). זהה עם אהבה בריה דר' זירא.","cat": "sage"},{"i": 493,"n": "ר' אחווה","l": "א","b": "בב\"ר: \"א\"ר אחווה בשם ר\"ז\". (פל\"ט - י\"א), וצ\"ל ר' אחווה בר זעירא. ע\"ע אהבה בריה דרבי זירא.","cat": "sage"},{"i": 494,"n": "אחי (2)","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. היה ממונה על הגיטין בימי ר' אסי (גיטין ה' ע\"ב), ואולי זה ר' אחי, שמסר בשמם של רבי אבהו ורבי שמואל בר נחמני (ע\"ע).","cat": "sage"},{"i": 495,"n": "רב אחי","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמיד של רב יוסף (עירובין י' ע\"א), ואולי זה ר' אחי שמסר בשמם של רבי אבהו ורבי שמואל בר נחמני (ע\"ע).","cat": "sage"},{"i": 496,"n": "רבי אחי (3)","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם רבי אבהו (ירו', סנהדרין פ\"ד ה\"ו) ובשם ר' שמואל בר נחמני (ילקוט מלכים א' רמז קע\"ג). אולי הוא ר' אחי תלמיד רב יוסף.","cat": "sage"},{"i": 497,"n": "ר' אחי","l": "א","b": "פעמים בא במקום ר' אחאי.","cat": "sage"},{"i": 498,"n": "ר' אחי בר חנינא","l": "א","b": "תנא. מובא בברייתא בבבלי (שבת ע\"ט ע\"ב). רבי אחא מסר בשמו (שם).","cat": "sage"},{"i": 499,"n": "אחי בר יאשיה","l": "א","b": "תנא בדור החמישי. רבינו הקדוש הזכירו לפני פטירתו (קידושין ע\"ב ע\"א). חלק עם אביו (גיטין מ\"ה ע\"א). נקבר בנהרדעא (שבת קנ\"ב ע\"ב).","cat": "sage"},{"i": 500,"n": "אחי שקיא","l": "א","b": "אמורא בבלי בדור השלישי. מובא בבבלי (ביצה כ\"ה ע\"ב). תלמיד של רב הונא (שם).","cat": "sage"},{"i": 501,"n": "רבי אחיא","l": "א","b": "מובא בבבלי (זבחים מ\"ח ע\"ב). ע\"ע רבי אחייה.","cat": "sage"},{"i": 502,"n": "אחיה","l": "א","b": "הוא ואחיו שמעיה היו מהרוגי מלכות בזמן הבית, ופירש\"י: \"חסידים היו\" (תענית י\"ח ע\"ב). וב\"ערוך\" ערך \"הרג\" כתב שהם: \"הרוגי לוד\" (פסחים נ' ע\"א), עליהם נאמר (שם) ש\"אין אדם יכול לעמוד במחיצתן\".","cat": "sage"},{"i": 503,"n": "רב אחיי בר אדא","l": "א","b": "מובא בבבלי (קידושין כ\"ב ע\"ב). נראה אולי שהיה בתקופת רב אשי (דור ששי לאמוראי בבל).","cat": "sage"},{"i": 504,"n": "ר' אחייא בר אבא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בב\"ר (פצ\"ח - ט'). ר' ירמיה אמר בשמו (שם).","cat": "sage"},{"i": 505,"n": "רבי אחייה","l": "א","b": "תנא בדור השלישי - הרביעי. היה ראש לבני הגולה בזמנו של חנניה בן אחי רבי יהושע (ברכות ס\"ג ע\"ב). נראה, שהוא המובא (מו\"ק כ' ע\"ב) \"רבי חייא לחוד רבי אחייה לחוד\", וכן נראה שהוא המובא (מנחות נ\"ו ע\"א) \"דתניא ר' אחייה אומר\" (סה\"ד: קבע להם ערכים נפרדים).","cat": "sage"},{"i": 506,"n": "אחייה בר זעירא","l": "א","b": "ע\"ע ר' אהבה בר זעירא. בלשון ירושלמי \"אחייה\" הוא גם \"אהבה\".","cat": "sage"},{"i": 507,"n": "ר' אחייה בר' זירא","l": "א","b": "מובא בירושלמי (ברכות פ\"א), והוא ואהבה בריה דר' זירא אחד הוא.","cat": "sage"},{"i": 508,"n": "רב אחלי","l": "א","b": "מובא בבבלי (עירובין י\"ב ע\"א). ה\"יוחסין\" סובר שהיה בזמן שמואל, ואין זה מוכרח מהגמרא. \"דק\"ס\" גרס: רב אהלי. ו\"סה\"ד\" כתב בערך אהילאי: \"עיין לקמן רב אחלי וכו' והכל אחד\".","cat": "sage"},{"i": 509,"n": "אחר","l": "א","b": "מובא בבבלי (ברכות נ\"ז ע\"ב). והוא אלישע בן אבויה.","cat": "sage"},{"i": 510,"n": "אחרים","l": "א","b": "מובא בבבלי (הוריות י\"ג ע\"ב). שם מובא ענין הסכסוך שהיה בין רשב\"ג ור\"מ וקנסו לר\"מ שיקראוהו בשם אחרים. אבל אין זה כלל בכל הש\"ס. (סוטה י\"ב ע\"א - בתוספות).","cat": "sage"},{"i": 511,"n": "איבו (4)","l": "א","b": "אמורא בדור המעבר של התנאים לאמוראים. אביו של רב. היה בארץ ישראל וקיבל מר\"א בר צדוק (סוכה מ\"ד ע\"ב). נשא לאשה את אחות רבי חייא. (פסחים ד' ע\"א - רש\"י). איבו ורבי חייא היו אחים מן האב.","cat": "sage"},{"i": 512,"n": "רבי איבו","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמיד של רבי ינאי (פסחים מ\"ו ע\"א). מבעלי האגדה החשובים. מדרשים רבים ממנו מצויים בבראשית רבה. הוא בעל המאמר: \"אין אדם יוצא מן העולם וחצי תאותו בידו\" (קה\"ר פ\"א - י\"ג).","cat": "sage"},{"i": 513,"n": "ר' איבו בר אגרא","l": "א","b": "מובא בב\"ר (פפ\"ה - ו'), והוא ר' איבו בר נגרי.","cat": "sage"},{"i": 514,"n": "ר' איבו בר כהנא","l": "א","b": "כתב \"סה\"ד\" בערך ר' אבא בר כהנא: \"ובתנחומא פ' ראה ר' איבא בר כהנא אולי אחד הוא\".","cat": "sage"},{"i": 515,"n": "רבי איבו בר נגרי","l": "א","b": "ע\"ע רבי אייבו בר נגרי.","cat": "sage"},{"i": 516,"n": "איבות בר איהי","l": "א","b": "מובא בבבלי (עירובין ע\"ד ע\"א). גירסת \"דק\"ס\": אבוה בר איהי.","cat": "sage"},{"i": 517,"n": "רב אידאי","l": "א","b": "אמורא בדור הרביעי - החמישי. אביו של אמורא ושמו מר בר רב אידאי (חולין ס\"ג ע\"א), ואין לנו מאומה מתורתו. מובא רק בהקשר לבנו (שם).","cat": "sage"},{"i": 518,"n": "רב אידי","l": "א","b": "אמורא בדור השלישי - הרביעי. עלה לארץ ישראל והיה שם תלמיד של רבי אסי (ירו', יבמות פי\"א ה\"ב). מצינו שמסר שמועה בשם רב חסדא (שם). נראה שחזר לבבל ורבא קבל ממנו (נדרים ה' ע\"ב).","cat": "sage"},{"i": 519,"n": "רב אידי אבוה דרבי יעקב בר אידי","l": "א","b": "אמורא ארץ ישראלי בדור השני. תלמיד של רבי יהושע בן לוי (עירובין ס' ע\"ב). היה אבי רבי יעקב בר אידי (חגיגה ה' ע\"ב). רבנן קראו לו \"בר בי רב דחד יומא\", לאחר שהלך ג' חדשים מביתו לבית המדרש ושהה שם רק יום אחד (שם). מצינו שר' יוחנן פייסו (שם).","cat": "sage"},{"i": 520,"n": "רב אידי בר אבין (2)","l": "א","b": "אמורא בבלי בדור הרביעי. תלמיד של רב חסדא (פסחים ק\"א ע\"ב). מתלמידיו: רב פפא ורב הונא בריה דר' יהושע (פסחים ל\"ה ע\"א). רב הונא בירך את אביו שיהיו לו בנים חכמים, ונולדו לו: הוא ואחיו רב חייא בר אבין (שבת כ\"ג ע\"ב). שלח לאביי (יבמות ע\"ו ע\"א). מצינו שהיה לו בן. (שבת קל\"ו ע\"א).","cat": "sage"},{"i": 521,"n": "רב אידי בר אידי בר גרשם","l": "א","b": "אמורא בדור השני - השלישי. מסר בשמו של ר' שמן בר אבא (חולין צ\"ח ע\"א). אולי הוא אדא בר גרשון.","cat": "sage"},{"i": 522,"n": "ר' אידי בר גרשום","l": "א","b": "אמורא בדור השני. מסר בשם רב אדא בר אהבה (כריתות ט' ע\"א), ואולי הוא ר' אדא בר גרשון.","cat": "sage"},{"i": 523,"n": "אידי בר יעקב","l": "א","b": "מובא ב\"זוהר\" (פ' לך).","cat": "sage"},{"i": 524,"n": "רב אידי בר שימי","l": "א","b": "מובא ב\"ילקוט\" (זכריה רמז תקע\"ח). ואולי צ\"ל: רב אדא בר שימי. (ע\"ע).","cat": "sage"},{"i": 525,"n": "רב אידי בר שישא","l": "א","b": "מובא בבבלי (פסחים ק\"ו ע\"א). אמורא שאין לקבוע את זמנו המדוייק.","cat": "sage"},{"i": 526,"n": "ר' אידי בר שמעון","l": "א","b": "מובא בירושלמי (ברכות פ\"ב ה\"ג), והוא ר' אדא בר שמעון.","cat": "sage"},{"i": 527,"n": "רב אידי בריה דרב איקא","l": "א","b": "אמורא בבלי בדור הששי. רב הונא בר מנוח מסר משמו (יבמות מ\"ג ע\"א), ואולי הוא ר' אדא בריה דרב איקא.","cat": "sage"},{"i": 528,"n": "רבי אידי דחוטריה","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמיד של ירמיה (ירו', שקלים פ\"ז ה\"ה).","cat": "sage"},{"i": 529,"n": "ר' אידי דקיסרין","l": "א","b": "מסר בשם ר\"י (ירו', מו\"ק פ\"ג ה\"ה) ושוב לא נזכר שמו.","cat": "sage"},{"i": 530,"n": "רב אידי סרסיה","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. סרסיה (שמש) ותלמיד של רב ששת (בכורות ל\"א ע\"ב). רב ששת הקפיד עליו שלא אמר בשמו (שם).","cat": "sage"},{"i": 531,"n": "רב אידית","l": "א","b": "אמורא בבלי בדור השני - השלישי. חי בזמנו של רב נחמן, שאמר עליו שרק היודע להשיב למינים כרב אידית, רשאי להתוכח עמהם (סנהדרין ל\"ח ע\"ב).","cat": "sage"},{"i": 532,"n": "איו","l": "א","b": "מובא בבבלי (עירובין ל\"ו ע\"ב). שם מצינו שרב מסתמך על ברייתא ששנה איו. ופירש\"י: איו - שם חכם.","cat": "sage"},{"i": 533,"n": "אייבו","l": "א","b": "הוא איבו.","cat": "sage"},{"i": 534,"n": "רבי אייבו בר נגרי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי חייא בר אבא (סנהדרין ס\"ז ע\"ב), ושניהם היו תלמידיו של רבי יוחנן (ר\"ה כ\"א ע\"א - רש\"י).","cat": "sage"},{"i": 535,"n": "ר' אייבון","l": "א","b": "מובא (ירו', עירובין פ\"א ה\"א) ע\"ע אבין.","cat": "sage"},{"i": 536,"n": "רבי אייניא בן פזי","l": "א","b": "אמורא בבלי בדור הרביעי. אמר בשם ר' יהודה (ירו', עירובין ספ\"ה). \"סה\"ד\" סובר שר' אונייא בן פזי ור' חנניא בן פזי אחד הוא.","cat": "sage"},{"i": 537,"n": "אילא","l": "א","b": "חי ביבנה בזמן התנאים. בזכות היותו חסיד, התירו לו חכמים לקחת כסף תמורת ראיית מומי בכורות (בכורות כ\"ט ע\"א).","cat": "sage"},{"i": 538,"n": "ר' אילא","l": "א","b": "מובא בבבלי (מו\"ק כ\"ה ע\"א), והוא רבי אלעאי האמורא.","cat": "sage"},{"i": 539,"n": "ר' אילא בריה דרב שמואל בר מרתא","l": "א","b": "אמורא בבלי בדור השני. אמר משמיה דרב (ברכות י\"ג ע\"ב).","cat": "sage"},{"i": 540,"n": "ר' אילאי דנציבין","l": "א","b": "מובא ב\"זוהר\" (שלח קס\"ב). הוא ובנו ירדו למערה (שם).","cat": "sage"},{"i": 541,"n": "ר' אילם","l": "א","b": "מובא באיכ\"ר (פ\"ב - י\"ב). הגירסא במקום אחר (ויק\"ר פי\"ב - ה'): ר' הלל בר הילני.","cat": "sage"},{"i": 542,"n": "ר' אילעא בר יברכיה","l": "א","b": "מובא בבבלי (סוטה מ\"ט ע\"א), והוא ר' אלעאי בר ברכיה.","cat": "sage"},{"i": 543,"n": "איסור גיורא","l": "א","b": "גר צדק בדור השני - השלישי. חתנו של שמואל (חברו דרב). והיה גר צדק, כמו שרש\"י מפרש: \"ובת שמואל היתה ונשבית לבין העמים ובא עליה אחד ונתעברה ממנו ואח\"כ התגייר ושמיה איסור\" (ברכות ט\"ז ע\"א). נראה שנעשה אח\"כ חכם: \"אמר רבא אמר לי איסור גיורא\" (ע\"ז ע' ע\"א). בנו ונכדיו היו אמוראים: בנו האמורא רב מרי, ושני בני רב מרי - מר זוטרא ורב אדא סבא.","cat": "sage"},{"i": 544,"n": "איסי (2)","l": "א","b": "חי בבבל בדור השלישי - הרביעי. בנו של ר' יצחק ונכדו של רב יהודה ואביה של חומה שנישאה לשלושה אמוראים שמתו תחתיה (רחבה דפומבדיתא, רב יצחק בריה דרבה בר בר חנא ואביי).","cat": "sage"},{"i": 545,"n": "איסי אחוה דרבי זירא","l": "א","b": "מובא בבבלי (מו\"ק כ' ע\"ב). ע\"ע אבוה דר' זירא.","cat": "sage"},{"i": 546,"n": "איסי בן גור אריה","l": "א","b": "והוא איסי בן עקביה (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 547,"n": "איסי בן גמליאל","l": "א","b": "והוא איסי בן עקביא (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 548,"n": "איסי בן יהודה","l": "א","b": "מובא בבבלי (גיטין ס\"ז ע\"א), והוא איסי בן עקביה.","cat": "sage"},{"i": 549,"n": "איסי בן יעקב","l": "א","b": "מובא בילקוט (משפטים רמז שכ\"ד) והוא ט\"ס, וצ\"ל: איסי בן עקביה כמו במקום אחר (מכילתא משפטים מס' דנזיקין פ\"ד).","cat": "sage"},{"i": 550,"n": "איסי בן מהללאל","l": "א","b": "והוא איסי בן עקביה (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 551,"n": "איסי בן מנחם","l": "א","b": "תנא בדור החמישי. חלק עם איסי בן יהודה (סוטה ט\"ז ע\"א).","cat": "sage"},{"i": 552,"n": "איסי בן עזאי","l": "א","b": "מובא ב\"ילקוט\" (בשלח רמז רמ\"ג). \"סה\"ד\" כתב כי ט\"ס הוא והגירסא: איסי בן שמאי (מכילתא בשלח מס' דשירה פ\"ב).","cat": "sage"},{"i": 553,"n": "איסי בן עקביה","l": "א","b": "תנא בדור החמישי. עלה מבבל לארץ ישראל. היו לו שמות רבים כמובא בבבלי: \"הוא יוסף איש הוצל, הוא יוסף הבבלי, הוא איסי בן גור אריה, הוא איסי בן יהודה, הוא איסי בן גמליאל, הוא איסי בן מהללאל, ומה שמו? איסי בן עקביה שמו\" (פסחים קי\"ג ע\"ב): ובירושלמי: \"הוא יוסף הבבלי, הוא יוסף בן יהודה, הוא יוסי קטנתא\" (ב\"ק פ\"ג ה\"ז). ובדרך כלל מובא בשם: איסי בן יהודה. היה תלמידו החביב של רבי אלעזר בן שמוע (מנחות י\"ח ע\"א), ותלמידו של רבי יוסי (נדרים פ\"א ע\"א) חברו של רבי שמעון בן יוחי (אדר\"נ ספי\"ח). היה מונה שבחם של חכמים (גיטין ס\"ז ע\"א). כשמת אמרו עליו: \"פסקו חסידים\" (סוטה מ\"ט ע\"א).","cat": "sage"},{"i": 554,"n": "איסי בן שימי","l": "א","b": "מובא במכילתא (בשלח פרשת ויסע סוף פרשה ג'). ונראה שהוא איסי בן שמאי.","cat": "sage"},{"i": 555,"n": "איסי בן שמאי","l": "א","b": "מובא במכילתא (בשלח מס' דשירה פ\"ב).","cat": "sage"},{"i": 556,"n": "איסי בר היני","l": "א","b": "אמורא בבלי בדור הראשון - השני. היתה לו ישיבה בבבל ועולא ביקר בה (שבת קמ\"ז ע\"א). עלה לארץ ישראל והקשה על דברי ר' יוחנן (חולין קל\"ז ע\"ב). כינה את רב \"אבא אריכא\" ורבי יוחנן הקפיד על כך (שם).","cat": "sage"},{"i": 557,"n": "איסי בר נתן","l": "א","b": "מובא בבבלי (ברכות ס\"ב ע\"א). גירסת \"דק\"ס\": רב אסי בר נתן.","cat": "sage"},{"i": 558,"n": "איסי בריה דרב יצחק בריה דרב יהודה","l": "א","b": "חי בבבל. היה בן בנו של האנורא המפורסם רב יהודה בר יחזקל. מובא פעם בש\"ס ובתו חומה נישאה לרחבא דפומבדיתא ומת, ונישאה לרב יצחק בריה דרבה בר בר חנה ומת, ונישאה לאביי ומת (יבמות ס\"ד ע\"ב). ואין ראיה שאיסי זה נמנה עם החכמים.","cat": "sage"},{"i": 559,"n": "ר' איסי דקיסרין","l": "א","b": "מובא בקה\"ר (פ\"ז - כ\"ו). \"סה\"ד\" גורס: ר' יוסי דמן קסרי.","cat": "sage"},{"i": 560,"n": "איפה","l": "א","b": "מובא בבבלי (שבת ס' ע\"ב), והוא עיפא בן רחבה דפומבדיתא (עיין רש\"י שם).","cat": "sage"},{"i": 561,"n": "רב איקא","l": "א","b": "אמורא בבלי בדור הרביעי. נשא לאשה את אחות רב אחא בר יעקב, שילדה לו את רב אחא בר איקא (כתובות ע\"ד ע\"א). רב הונא בר מנוח אמר משמו של רב איקא (ב\"ק כ\"ב ע\"א). בנו היה כנראה גדול מאביו, שכן נקרא ע\"ש בנו (ע\"ז ס\"ה ע\"א).","cat": "sage"},{"i": 562,"n": "רב איקא בר אבין","l": "א","b": "אמורא בבלי בדור השלישי. תלמידו של רב חננאל (קידושין ע\"ב ע\"א), שהיה תלמיד מובהק של רב.","cat": "sage"},{"i": 563,"n": "רב איקא בר חנינא","l": "א","b": "אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (חולין צ' ע\"ב).","cat": "sage"},{"i": 564,"n": "רב איקא בריה דרב אידי","l": "א","b": "מובא בבבלי (ב\"ק י\"ב ע\"א). מסורת הש\"ס גורס: רב איקא בריה דרב אמי.","cat": "sage"},{"i": 565,"n": "רב איקא בריה דרב אמי","l": "א","b": "אמורא בבלי בדור החמישי. נראה שהיה מבית מדרשו של רבא (ב\"ב קמ\"ט ע\"א). רבא הקפיד עליו (שם).","cat": "sage"},{"i": 566,"n": "רב איקא מפשרוניא","l": "א","b": "אמורא בבלי בדור הרביעי - החמישי. תלמידו של רבא. הקשה לרבא (עירובין ק\"ד ע\"א).","cat": "sage"},{"i": 567,"n": "ר' איתי","l": "א","b": "ע\"ע רב אסי.","cat": "sage"},{"i": 568,"n": "ר' אלאי היורש","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (גיטין פ\"ח ה\"ב) ופירש \"קרבן העדה\": \"כך שמו\".","cat": "sage"},{"i": 569,"n": "ר' אלוני בר טברי","l": "א","b": "מובא בש\"ר (פמ\"ד - ה'). אמר בשם ר' יצחק (שם).","cat": "sage"},{"i": 570,"n": "ר' אליהו","l": "א","b": "מובא בשהש\"ר (פ\"ב - י\"ד - ז').","cat": "sage"},{"i": 571,"n": "ר' אליהו עיני","l": "א","b": "אמורא ארץ ישראלי בדור השני. רבי שמואל בר נחמני מסר בשמו (ב\"ר נ\"א - ט').","cat": "sage"},{"i": 572,"n": "אליעזר","l": "א","b": "עיין אלעזר.","cat": "sage"},{"i": 573,"n": "רבי אליעזר","l": "א","b": "הוא רבי אליעזר בן הורקנוס.","cat": "sage"},{"i": 574,"n": "ר' אליעזר אבוי דר' יצחק בר נחמן","l": "א","b": "אמורא ארץ ישראלי בדור השני. תלמידו של רבי אושעיא (ירו', ב\"ב פ\"ח ה\"א). \"סה\"ד\" כתב: \"יש ט\"ס וכו' ואולי צ\"ל אחוי דר' יצחק בר נחמן\".","cat": "sage"},{"i": 575,"n": "אליעזר איש ביריא","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי: \"תניא נמי הכי, אליעזר איש ביריא אומר: 'יושבי צריפין כיושבי קברים'\" (עירובין נ\"ה ע\"ב), וב\"עין יעקב\" הגירסא: איש ברתותא.","cat": "sage"},{"i": 576,"n": "אליעזר בן גימל","l": "א","b": "מובא (בירו', תרומות פ\"א ה\"ד), והוא אבא אלעזר בן גימל.","cat": "sage"},{"i": 577,"n": "רבי אליעזר בן דהבאי","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. מובא במסכת כלה רבתי (ספ\"ב). אימרתו: \"האומר דבר בשם רבו מביא גאולה לעולם\" (שם).","cat": "sage"},{"i": 578,"n": "רבי אליעזר בן הורקנוס","l": "א","b": "תנא בדור השני. והוא סתם רבי אליעזר במשנה (הליכות עולם) או רבי אליעזר הגדול (גיטין נ\"ז ע\"א). היה חתנו של הנשיא רבן גמליאל הזקן (ב\"מ נ\"ט ע\"ב). מושבו היה בלוד, שם היתה לו ישיבה (סנהדרין ל\"ב ע\"ב). החל ללמוד תורה רק בגיל מבוגר (אבות דר\"נ פ\"ו ג'). מגדולי תלמידיו של רבן יוחנן בן זכאי (אבות פ\"ב מ\"ח), שאמר עליו שהוא שקול כנגד כל חכמי ישראל (שם). רבו הגדול של רבי עקיבא, שלמד אצלו 31 שנה (ירו', פסחים פ\"ו ה\"ג). חברו המובהק של רבי יהושע בן חנניה, ושניהם הוציאו את רבן יוחנן בן זכאי מירושלים בזמן החורבן (גיטין נ\"ו ע\"א). היה אחד מארבעה חכמי הסנהדרין ביבנה שהיו בקיאים בשבעים לשון (סנהדרין י\"ז ע\"ב). פעם חלק על החכמים ולא רצה לקבל דעתם, ואף שיצאה בת קול ואמרה שהלכה כר' אליעזר בכל מקום - נידוהו (ב\"מ נ\"ט ע\"ב). נשאר בנידויו עד יום מותו, ואז התירוהו (סנהדרין ס\"ח ע\"א). גיסו רבן גמליאל הנשיא, מת לפניו בגלל נדוי זה (ב\"מ שם). מהגמרא משתמע שהאריך ימים עד לאחר חורבן ביתר (גיטין נ\"ז ע\"א). עליו אמרו: \"משמת רבי אליעזר נגנז ס\"ת\" (סוטה מ\"ט ע\"ב).","cat": "sage"},{"i": 579,"n": "רבי אליעזר בן חלפתא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. רב אחא אמר בשמו (ויר\"ר פכ\"ז - ד').","cat": "sage"},{"i": 580,"n": "אליעזר בן חנוך","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. נידוהו על שפיקפק בנטילת ידים, ומת בנידויו, וסקלו ב\"ד את ארונו (עדיות פ\"ה מ\"ו).","cat": "sage"},{"i": 581,"n": "אליעזר בן יהודה איש איבלים","l": "א","b": "מובא בבבלי (חולין נ\"ה ע\"ב), והוא רבי אליעזר בן יהודה איש אבלים.","cat": "sage"},{"i": 582,"n": "רב אליעזר בן יעקב א'","l": "א","b": "תנא בדור הראשון, שראה בעיניו את הבית ותיארו, ועל לשכה אחת אמר: \"שכחתי מה היתה משמשת\" (מידות פ\"ב מ\"ה). ועוד סיפר, שפעם מצאו את אחי אמו (כהן בביהמ\"ק) ישן ושרפו את כסותו (שם פ\"א מ\"ב). גם הרמב\"ם בהקדמתו מונה אותו בדור שראו החורבן. הוא כתב את מסכת מדות (ירו', יומא פ\"ב ה\"ב - ובבלי יומא ט\"ו ע\"א). בן עזאי מצא מגילת יוחסין ובה כתוב: \"משנת רבי אליעזר בן יעקב קב ונקי\" (יבמות מ\"ט ע\"ב - וברש\"י שם: \"בכל מקום שנזכר הלכה כמותו\"). ר' אלעאי (אבי ר' יהודה בר אלעאי) קיבל ממנו (פסחים ל\"ט ע\"א).","cat": "sage"},{"i": 583,"n": "רבי אליעזר בן יעקב ב'","l": "א","b": "תנא בדור הרביעי. מתלמידי ר\"ע (ירו', חגיגה פ\"ג ה\"א). נמנה ששי מבין שבעת תלמידי ר\"ע המוזכרים שם. מסר בשם רבי פנחס בן יאיר, חתנו של רבי שמעון בר יוחאי (מד' תהלים ספל\"ב). נמנה עם חכמי אושא שנתכנסו אחר מרד בר כוכבא (שהש\"ר פ\"ב - ה'). מצינו שחלק עם ר\"מ (ר\"ה ד' ע\"ב). ולפי פרש\"י (יבמות צ\"ג א' - ד\"ה: ורב) קיבל ממנו רבי מאיר.","cat": "sage"},{"i": 584,"n": "רבי אליעזר בן פיאבי","l": "א","b": "הוא רבי אליעזר בן פילא.","cat": "sage"},{"i": 585,"n": "רבי אליעזר בן פילא","l": "א","b": "תנא שחי אחר רבי עקיבא בדור הרביעי או החמישי, והיה מנמק את דעתו של רבי עקיבא (טהרות פ\"ז מ\"ט).","cat": "sage"},{"i": 586,"n": "רבי אליעזר בן שמעיה איש כפר אותני","l": "א","b": "תנא בדור הראשון. שאל את רבי יוחנן בן זכאי (תוספתא פרה פ\"ט). ע\"ע שמעיה איש כפר עותני.","cat": "sage"},{"i": 587,"n": "אליעזר בר יוסי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - הששי. היה בנו של ר' יוסי, שהיה מראשי הדור הרביעי (ירו', תענית פ\"ב ה\"ב).","cat": "sage"},{"i": 588,"n": "רבי אליעזר ניותאה","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (גיטין נ' ע\"א). \"יוחסין\" מביא שתי גירסאות נוספות: רבי אליעזר ניזאה או שופאה.","cat": "sage"},{"i": 589,"n": "רב אליקים","l": "א","b": "אמורא בבלי בדור הרביעי - החמישי. שמשו של רבא. רבא שלחו לסגור הדלת בפני רב הונא בריה דרב נחמן \"שלא יקפחנו בהלכות על דברי מחלוקתם\" (ע\"ז נ\"ח ע\"א - רש\"י). ה\"יוחסין\" כתב שהיה תלמידו של רבא.","cat": "sage"},{"i": 590,"n": "אלישיב","l": "א","b": "אמורא שאין לקבוע זמנו ומקומו. מובא בבבלי (מו\"ק כ\"ה ע\"ב). שם מוזכר כי כל עוד שהיה חי, לא היו בזכותו גנבים במקום מגוריו.","cat": "sage"},{"i": 591,"n": "אלישע בן אבויה","l": "א","b": "תנא בדור השלישי, שיצא לתרבות רעה ומשום כך כינוהו \"אחר\". היה חברם של רבי עקיבא ובן עזאי ובן זומא: ארבעתם \"נכנסו לפרדס\", (ופירש רש\"י: \"עלו לרקיע ע\"י שם\"), בן עזאי הציץ ומת, בן זומא הציץ ונפגע, \"אחר\" קיצץ בנטיעות ורבי עקיבא יצא בשלום (חגיגה י\"ד ע\"ב). שמו מוזכר במשנה (אבות פ\"ד מ\"כ). היה רבו של רבי מאיר, שלמד ממנו גם לאחר שיצא לתרבות רעה, ואמרו: רבי מאיר רימון מצא, תוכו אכל קליפתו זרק (חגיגה ט\"ו ע\"ב). מת אחרי רבי עקיבא, והותיר אחריו בת שבאה לפני רבי וביקשתו שיפרנסנה (שם).","cat": "sage"},{"i": 592,"n": "אלישע בעל כנפים","l": "א","b": "ה\"יוחסין\" כתב שנראה שהיה בתקופת התנאים. מובא בבבלי: \"פעם גזרה המלכות שכל המניח תפילין ינקרו את מוחו והיה אלישע מניחם, ראהו ממונה ורץ אחריו ונטל אלישע תפילין מראשו ואחזן בידו ונהפכו לכנפי יונה\" (שבת מ\"ט ע\"א).","cat": "sage"},{"i": 593,"n": "ר' אלכסא","l": "א","b": "אמורא ארץ ישראלי בדור השני. מובא בירושלמי (כתובות פ\"ה ה\"א). תלמידו של חזקיהו, (בנו של ר' חייא ורבו של ר' יעקב בר אחא) (שם).","cat": "sage"},{"i": 594,"n": "אלכסנדר","l": "א","b": "מובא בירושלמי (ב\"ב פ\"ט ה\"ג) יחד עם שני אחיו החכמים: ר' שמואל בר סוסרטיי ור' הוריינא אחוי דר' שמואל. נראה, שהוא עצמו לא היה חכם.","cat": "sage"},{"i": 595,"n": "ר' אלכסנדר","l": "א","b": "מובא בירושלמי (מעשרות פ\"ה ה\"ה). ע\"ע רבי אלכסנדרי.","cat": "sage"},{"i": 596,"n": "ר' אלכסנדרא","l": "א","b": "מובא (ירו', מע\"ש פ\"ה ה\"ה), והוא ר' אלכסנדר.","cat": "sage"},{"i": 597,"n": "רבי אלכסנדרי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יהושע בן לוי (ברכות נ\"ט ע\"א). כן קיבל מרבי יוחנן (ב\"ר פע\"א - ז'). משמו מסרו חכמי הדרום (ב\"ר ס\"ג - ח') ורבי אחא (מדרש תהלים פק\"ב - ג'). מסופר שהלך והכריז מי מבקש חיים, וכשנתקבצו אליו אנשים אמר להם: \"מי האיש החפץ חיים וכו' נצור לשונך מרע וכו'\" (ע\"ז י\"ט ע\"ב).","cat": "sage"},{"i": 598,"n": "ר' אלכסנדרי בר הדרין","l": "א","b": "מובא בשהש\"ר (פ\"ה - י\"א), ונראה אולי שצ\"ל: ר' אלכסנדרי בר חגאי.","cat": "sage"},{"i": 599,"n": "ר' אלכסנדרי בר חגאי","l": "א","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מאמרו בשם ר' אלכסנדרי קרובה (ויק\"ר פי\"ט - ב'): \"אם מתכנסין כל באי עולם להלבין כנף אחד של עורב אין יכולין, כך אם מתכנשין כל באי העולם לעקור דבר אחד מן התורה אין יכולין\".","cat": "sage"},{"i": 600,"n": "ר' אלכסנדרי בר חגרי","l": "א","b": "כך גירסת ה\"יוחסין\". הגירסא לפנינו: ר' אלכסנדרי בר חגאי. (ע\"ע).","cat": "sage"},{"i": 601,"n": "ר' אלכסנדרי קרובה","l": "א","b": "מובא בויק\"ר (פי\"ט - ב'). ע\"ע ר' אלכסנדרי בר חגאי.","cat": "sage"},{"i": 602,"n": "ר' אלכסנדריא דצדוקא","l": "א","b": "אמורא ארץ ישראלי בדור השני. מובא בירושלמי (דמאי פ\"ב ה\"א). רבי זירא שאל ממנו (שם).","cat": "sage"},{"i": 603,"n": "ר' אלעא הזקן","l": "א","b": "מובא בבבלי ומאמרו (שם): \"אם רואה אדם שיצרו מתגבר עליו ילך למקום שאין מכירין אותו וילבש שחורים וכו'\" (חגיגה ט\"ז ע\"א). ע\"ע ר' אלעאי הזקן.","cat": "sage"},{"i": 604,"n": "רבי אלעאי (2)","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. שמו שובש ב - 02 צורות כתיב שונות. רש\"י פירש (בכורות מ\"ב ע\"ב): \"רבי אלעאי אמורא הוא, ולאו היינו האי דברייתא דאיירי לעיל משום רבי ישמעאל\". נראה, שמושבו היה בצור (ירו', שביעית פ\"ב ה\"ד), ובא מבבל ושם עוד קיבל מרב (שבת קמ\"ב ע\"א). כן מסר בשם שמואל (ירו', פסחים פ\"ט ה\"ו). חברו המובהק היה רב ברונא (תלמידו דרב), כדמצינו (ברכות ט' ע\"ב). בארץ ישראל קיבל עוד מרבי חנינא (עירובין כ\"ח ע\"ב), ומסר בשם רבי ינאי (ירו', עירובין פ\"ו ה\"ט), ר' יוחנן (עירובין פ\"א ע\"ב) ור\"ל (ירו', שבת פ\"ח ה\"ו). בארץ ישראל היה חברו ובר פלוגתיה דרבי זירא (ב\"ב נ\"ט ע\"א). בין תלמידיו: רבי יונה (ירו', תרומות פ\"ב ה\"ד) ורבי יוסי (שם), שהיו מראשי הדור הרביעי - החמישי.","cat": "sage"},{"i": 605,"n": "ר' אלעאי בן אלעזר","l": "א","b": "מובא (שבת ס' ע\"א) מקודם מובאים דברי שמואל ואח\"כ דבריו אך אין ראיה מזה מי קדם למי כי יתכן שזה ממסדר הש\"ס.","cat": "sage"},{"i": 606,"n": "ר' אלעאי בר ברכיה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין ק\"ד ע\"ב - לפי גירסת \"דק\"ס\"). מאמרו: \"שני תלמידי חכמים שהיו הולכים בדרך ואין ביניהן דברי תורה ראויין לישרף\" (תענית י' ע\"ב).","cat": "sage"},{"i": 607,"n": "ר' אלעאי בר מנחם","l": "א","b": "מובא בויק\"ר (פ\"א - י\"ג).","cat": "sage"},{"i": 608,"n": "ר' אלעאי בר שמעיה","l": "א","b": "מובא בויק\"ר (פ\"י - ה').","cat": "sage"},{"i": 609,"n": "ר' אלעאי הזקן","l": "א","b": "מובא (מו\"ק ט\"ז ע\"א) ייתכן שהוא אביו של רבי יהודה התנא. נראה, שהוא רבי אלעא. (ע\"ע ר' אלעא הזקן).","cat": "sage"},{"i": 610,"n": "אלעזר (2)","l": "א","b": "היה ממונה על הפרוכת בבית המקדש. מובא במשנה (שקלים פ\"ה מ\"א).","cat": "sage"},{"i": 611,"n": "רבי אלעזר","l": "א","b": "יש תנא בשם רבי אלעזר (בן שמוע), ויש אמורא בשם רבי אלעזר (בן פדת).","cat": "sage"},{"i": 612,"n": "אלעזר איש בירתא","l": "א","b": "מובא בבבלי (תענית כ\"ד ע\"א). לפי גירסת \"דק\"ס\" הוא אלעזר בן יהודה איש ברתותא.","cat": "sage"},{"i": 613,"n": "ר' אלעזר איש ברתות","l": "א","b": "מובא באבות (פ\"ג מ\"ז), והוא רבי אלעזר בן יהודה איש ברתותא.","cat": "sage"},{"i": 614,"n": "ר' אלעזר בוצראה","l": "א","b": "אמורא ארץ ישראלי. מובא באיכ\"ר (פ\"ד - פ\"ג). הוא ור' תנחום (שחי בדור החמישי) אמרו בשם ר' אחא (שם).","cat": "sage"},{"i": 615,"n": "ר' אלעזר בי ר\"ש","l": "א","b": "מובא בירושלמי (עירובין פ\"ח ה\"ג). אין לדעת משמעות ראשי התיבות: שמואל או שמעון. אמר בשם ר' אושעיא (שם).","cat": "sage"},{"i": 616,"n": "אלעזר בן אהווי","l": "א","b": "מובא בספרא (ויקרא ספ\"ב), ואולי הוא ר' אלעזר בן מהבאי.","cat": "sage"},{"i": 617,"n": "אלעזר בן אחוי","l": "א","b": "מובא בב\"ר (פצ\"ח - ג').","cat": "sage"},{"i": 618,"n": "רבי אלעזר בן אחוי","l": "א","b": "מובא בספרא (ויקרא סוף פ\"א). צ\"ל: ר\"א בן מהבאי.","cat": "sage"},{"i": 619,"n": "ר' אלעזר בן אנטיגנוס","l": "א","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי אלעזר ב\"ר ינאי (גיטין ל\"א ע\"א). רבי זירא היה תלמידו (ירו', ברכות פ\"ה ה\"ב).","cat": "sage"},{"i": 620,"n": "רבי אלעזר בן דגלאי","l": "א","b": "תנא שחי בזמן הבית (תמיד פ\"ג - דף ל' ע\"ב).","cat": "sage"},{"i": 621,"n": "רבי אלעזר בן דורדיא","l": "א","b": "אף שמכונה רבי, אינו תנא. חי בתקופת התנאים, ככל הנראה בזמנו של רבי או אף לפניו. היה בעל תשובה גדול ומת בתשובתו ויצאה בת קול ואמרה: \"רבי אלעזר בן דורדיא מזומן לחיי העולם הבא\". בכה רבי ואמר: 'יש קונה עולמו בכמה שנים ויש קונה עולמו בשעה אחת'. ואמר רבי: \"לא דיין לבעלי תשובה שמקבלין אותן אלא שקורין אותן רבי\" (ע\"ז י\"ז ע\"א).","cat": "sage"},{"i": 622,"n": "רבי אלעזר בן דלגוי","l": "א","b": "מובא בירושלמי (סוכה פ\"ה ה\"ג), והוא אלעזר בן דגלאי.","cat": "sage"},{"i": 623,"n": "אלעזר בן דמא","l": "א","b": "תנא בדור השלישי - הרביעי. שאל מרבי ישמעאל דודו \"כגון אני שלמדתי כל התורה כולה מהו ללמוד חכמת היונית\" (מנחות צ\"ט ע\"ב). מת מנשיכת נחש וקרא עליו רבי ישמעאל \"אשריך בן דמא שגופך טהור ויצאה נשמתך בטהרה\" (ע\"ז כ\"ז ע\"ב).","cat": "sage"},{"i": 624,"n": "רבי אלעזר בן הקפר","l": "א","b": "ע\"ע רבי אלעזר הקפר.","cat": "sage"},{"i": 625,"n": "רבי אלעזר בן זמרא","l": "א","b": "מובא בב\"ר (ספל\"ט). \"סה\"ד\" כתב: \"ואולי צ\"ל: בשם רבי יוסי בן זמרי\".","cat": "sage"},{"i": 626,"n": "ר' אלעזר בן חגייא","l": "א","b": "אמורא ארץ ישראלי בדור הששי. תלמידו של רבי מנא ב' (ירו', שקלים פ\"ז ה\"ב).","cat": "sage"},{"i": 627,"n": "אלעזר בן חנך","l": "א","b": "מובא בבבלי (ברכות י\"ט ע\"א), והוא אליעזר בן חנוך.","cat": "sage"},{"i": 628,"n": "אלעזר בן חנניה בן חזקיה בן גרון","l": "א","b": "תנא קדמון שחי בזמן הבית. הוא וסיעתו כתבו את מגלת תענית (מגילת תענית פי\"ב). פעם אבד לו ספר תורה שנקנה במאה מנה ועלה והקיף את הר הבית ולא זז משם עד שמצאו אותו (שמחות פ\"ו).","cat": "sage"},{"i": 629,"n": "רבי אלעזר בן חסמא","l": "א","b": "מובא בבבלי (גיטין ס\"ב ע\"א), וצ\"ל: רבי אלעזר חסמא, חסמא אינו שם אביו.","cat": "sage"},{"i": 630,"n": "ר' אלעזר בן חרסום","l": "א","b": "כהן גדול ששימש אחת עשרה שנה בכהונה גדולה (יומא ט' ע\"א). היה עשיר גדול ושימש כדוגמא לעשירות (קידושין מ\"ט ע\"א) וישב ועסק בתורה \"כל היום וכל הלילה\" (יומא ל\"ה ע\"ב), ועליו אמרו (שם): \"רבי אלעזר בן חרסום מחייב את העשירים\" (שלא יהיה להם פתחון מדוע לא למדו תורה).","cat": "sage"},{"i": 631,"n": "רבי אלעזר בן יהודה","l": "א","b": "מובא במשנה (זבים רפ\"א), והוא רבי אלעזר בן יהודה איש ברתותא (כדמוכח בתוספתא שם).","cat": "sage"},{"i": 632,"n": "אלעזר בן יהודה איש אבלים","l": "א","b": "תנא בדור החמישי. מסר בשם רבי יעקב [בן קורשאי] (זבחים כ\"ח ע\"א). שם מקומו נשתבש בכמה אופנים.","cat": "sage"},{"i": 633,"n": "אלעזר בן יהודה איש איבלייס","l": "א","b": "מובא בתוספתא (מע\"ש פ\"א), והוא אלעזר בן יהודה איש אבלים.","cat": "sage"},{"i": 634,"n": "רבי אלעזר בן יהודה איש ברתותא","l": "א","b": "תנא בדור השלישי. תלמידו של רבי יהושע (משנה טבול יום פ\"ג מ\"ד) וחברו של ר\"ע (שם). רבי שמעון בן יוחאי מסר בשמו (תוספתא זבים פ\"א ה\"ה). נתן לצדקה כל מה שהיה בידו וגבאי צדקה ברחו ממנו (תענית כ\"ד ע\"א).","cat": "sage"},{"i": 635,"n": "אלעזר בן יהודה איש כפר אובלון","l": "א","b": "מובא בתוספתא (סוף נדה), והוא אלעזר בן יהודה איש אבלים.","cat": "sage"},{"i": 636,"n": "רבי אלעזר בן יצחק איש כפר דרום","l": "א","b": "תנא. נראה, שחי בדור השלישי. חלק עם אבא יוסי בן חנן ועם רבי ישמעאל שנזכר אחריו (סוטה כ' ע\"ב).","cat": "sage"},{"i": 637,"n": "ר' אלעזר בן ירמיה","l": "א","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (סוטה ד' ע\"א). ב\"אגרת רב שרירא גאון\" נאמר שהיה בדורו של רשב\"ג.","cat": "sage"},{"i": 638,"n": "ר' אלעזר בן מהבאי","l": "א","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת ק\"ו ע\"ב).","cat": "sage"},{"i": 639,"n": "רבי אלעזר בן מתיא","l": "א","b": "תנא בדור השלישי - הרביעי. קיבל מר\"ע (תוספתא ברכות פ\"ד). מחכמי יבנה שהיו בקיאים בשבעים לשון (ירו', שקלים פ\"ח ה\"א). חבריו היו: שמעון בן עזאי, שמעון התימני וחנינא בן חכינאי (תוספתא ברכות שם). \"יוחסין\" סובר שהוא בנו של מתיא בן חרש.","cat": "sage"},{"i": 640,"n": "רבי אלעזר בן עזריה","l": "א","b": "תנא בדור השלישי. נתמנה זמנית לנשיא במקום רבן גמליאל (ברכות כ\"ז ע\"ב), לפי הבבלי (שם) בגיל שמונה עשרה, ולפי הירושלמי (ברכות פ\"ד ה\"א) בגיל שש עשרה. תלמידו של רבי יוסי הגלילי (ירו', כתובות פי\"א ה\"ג). הרמב\"ם, בהקדמתו לזרעים, שייך את ר\"א בן עזריה לדור השני, ואת ר' יוסי הגלילי לדור השלישי. היה חבר מובהק לר\"ע (סנהדרין ל\"ח ע\"ב), וכן חברם של ר' ישמעאל, ר\"ט ור' יהושע (ידים פ\"ד מ\"ג, ובהגדה של פסח). ר' מתיא בן חרש שאל ממנו (יומא פ\"ו ע\"א). ר\"א ב\"ר שמעון אמר משמו (תנחומא ויגש - ז'). היה דור עשירי לעזרא (יבמות ט\"ז ע\"א). כהן ועשיר מופלג (שבת נ\"ד ע\"ב). עשירותו שימשה כמשל בפי החכמים (קידושין מ\"ט ע\"ב). רבי יהושע אמר עליו: \"אין דור יתום שר\"א בן עזריה שרוי בתוכו\" (חגיגה ג' ע\"ב). בפרשנות המקרא קבע כלל \"דברה תורה כלשון בני אדם\" (קידושין י\"ז ע\"ב). אמרו עליו: \"משמת ר\"א בן עזריה בטלו עטרות חכמה\" (סוף סוטה).","cat": "sage"},{"i": 641,"n": "רבי אלעזר בן ערך","l": "א","b": "תנא בדור השני. מגדולי תלמידיו של ר' יוחנן בן זכאי, שאמר עליו שהוא \"כמעין המתגבר ושקול כנגד כל חכמי ישראל\" (אבות פ\"ב מ\"ח). לבסוף הלך בעצת אשתו לדיומסית מקום רחצה ויין, ונעקר תלמודו ושכחו. חבריו בקשו רחמים ותלמודו חזר אליו (שבת קמ\"ז ע\"ב - אבות דר\"נ ספי\"ד). חבריו היו: ר' אליעזר בן הורקנוס, יהושע בן חנניה, יוסי החסיד ור' שמעון בן נתנאל. דרש במעשה מרכבה וירדה אש מן השמים. עמד ר' יוחנן בן זכאי ונשקו על ראשו (חגיגה י\"ד ע\"ב).","cat": "sage"},{"i": 642,"n": "רבי אלעזר בן פדת","l": "א","b": "אמורא בדור השני. והוא ר' אלעזר סתם בגמרא (שבת י\"ט ע\"ב ברש\"י). בבבל שימש את רב ושמואל (חולין קי\"א ע\"ב). עלה לארץ ישראל בעודו צעיר ועדיין לא היה נשוי (ברכות ט\"ז ע\"א). רבו המובהק היה רבי יוחנן (יומא נ\"ג ע\"א). ואח\"כ הפך להיות לרבי יוחנן תלמיד - חבר (ירו', סנהדרין פ\"א ה\"א). היה תלמידם של רבי חנינא בר חמא (ברכות כ' ע\"ב) ושל רבי אושעיא (שם ל\"ב ע\"ב). נקרא \"מרא דארעא דישראל\" (נדה כ' ע\"ב). בכל מקום שאמרו \"שלחו מתם\" הוא ר\"א (סנהדרין י\"ז ע\"ב). היה עני מרוד (תענית כ\"ה ע\"א). מילא מקומו של ר' יוחנן כראש ישיבה (ירו', מגילה פ\"א הי\"א). נפטר באותה שנה שנפטר ר' יוחנן (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 643,"n": "רבי אלעזר בן פנחס","l": "א","b": "תנא. נראה שבדור הרביעי. נזכר במחלוקת לאחר ר\"א, ר' יהושע בן עזאי, ר\"ע וריב\"ב. (ירו', סוטה פ\"א ה\"ב). מסר בשם ר' יהודה בן בתירא (יומא י\"ח ע\"א).","cat": "sage"},{"i": 644,"n": "ר' אלעזר בן פרטא","l": "א","b": "תנא בדור השלישי - הרביעי. מושבו היה בציפורי (במד\"ר פכ\"ג - א'). מסר בשם רבי אלעזר המודעי (סנהדרין כ\"ב ע\"ב). חברו של רבי חנינא בן תרדיון (ע\"ז י\"ז ע\"ב). בברייתא מוזכר יחד עם רבי ישמעאל ורבי עקיבא (יומא ע\"ה ע\"ב). בזמן גזירת השמד נתפס על לימוד תורה וניצל (ע\"ז שם).","cat": "sage"},{"i": 645,"n": "רבי אלעזר בן צדוק","l": "א","b": "תנא בדור הרביעי - החמישי. כנראה נכדו של ר\"א בן צדוק הראשון. קיבל מר\"מ (כלאים פ\"ז מ\"ב) חברם של תלמידי ר\"ע: חלק עם רבי יהודה (כלים ספכ\"ו) ועם רבי יוסי (שם פ\"ב מ\"ו). התרועע עם רבי יהודה הנשיא (תוספתא סוכה פ\"ב ב'). אביו של רב מספר שעמד לפני ר\"א בן צדוק (סוכה מ\"ד ע\"ב), וכנראה שהכוונה אליו.","cat": "sage"},{"i": 646,"n": "רבי אלעזר בן שמוע","l": "א","b": "תנא בדור הרביעי, והוא סתם ר' אלעזר במשנה או ברייתא (שבת י\"ט ע\"ב ברש\"י). מתלמידיו האחרונים של רבי עקיבא (יבמות ס\"ב ע\"ב). נסמך על ידי רבי יהודה בן בבא (סנהדרין י\"ד ע\"א). חברו של רבי יוחנן הסנדלר (ספרי ראה פיסקא פ'). נשא ונתן עם רבי מאיר (תוספתא נזיר פ\"ה א'), ועם רבי יהודה (ירו', נזיר פ\"ו ה\"ז). רבי היה מתלמידיו (יומא ע\"ט ע\"ב). ר' יוחנן אמר עליו שלבו היה רחב כפתחו של היכל (עירובין נ\"ג ע\"א). האריך ימים ותלמידיו שאלו אותו \"במה הארכת ימים\" (סוטה ל\"ט ע\"א).","cat": "sage"},{"i": 647,"n": "רבי אלעזר בן תדאי","l": "א","b": "תנא בדור הרביעי. רב שרירא גאון כותב באיגרתו, שהיה בדורו של רשב\"ג. מובא בבבלי (שבת קכ\"ג ע\"א).","cat": "sage"},{"i": 648,"n": "רבי אלעזר בן תרדיון","l": "א","b": "תנא. חי בדור חכמי יבנה (\"אגרת רב שרירא גאון\"). מובא בירושלמי (גיטין פ\"ז ה\"ד).","cat": "sage"},{"i": 649,"n": "רבי אלעזר בנו של רבי אלעזר הקפר","l": "א","b": "מובא בירושלמי: \"זה אחד מד' דברים שהיה ר' חייא הגדול אומר שאין להם תשובה והשיב ר' אלעזר בנו של ר' אלעזר הקפר\" (ביצה פ\"א ה\"ג), ובבלי: \"השיב ר' אלעזר הקפר בריבי תשובה\" (חולין פ\"ד ע\"ב). יש סבורים, שבר קפרא הוא ר' אלעזר זה, והיה בנו של ר' אלעזר הקפר.","cat": "sage"},{"i": 650,"n": "רבי אלעזר בנו של רבי יוסי הגלילי","l": "א","b": "תנא בדור הרביעי. בנו של התנא ר' יוסי הגלילי. רבי יוחנן אמר: \"כל מקום שאתה מוצא דבריו של ר\"א בנו של ר' יוסי הגלילי בהגדה עשה אזנך כאפרכסת\" (חולין פ\"ט ע\"א). מיוחסת לו ברייתא \"דל\"ב מדות שהאגדה נדרשת בהן\" (יצא לאור ניו יורק, תרצ\"ד). רבנו שמשון מקינון בספר \"כריתות\" היה הראשון שהזכיר זאת.","cat": "sage"},{"i": 651,"n": "ר' אלעזר בר אבין","l": "א","b": "מובא בש\"ר (פמ\"ז - ה'), ואולי צ\"ל ר' אלעזר ור' אבין כמובא בב\"ר (פמ\"ח - י\"ד).","cat": "sage"},{"i": 652,"n": "ר' אלעזר בר אבינא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. ר' יודן (כצ\"ל) מסר בשמו (ב\"ר פצ\"ח - ב'). מאמרו: \"אין פורענות באה לעולם אלא בשביל ישראל\" (יבמות ס\"ג ע\"א).","cat": "sage"},{"i": 653,"n": "רבי אלעזר בר אושעיא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. חלק עם ר' יצחק בר אלעזר (ירו', ברכות פ\"ה ה\"ב).","cat": "sage"},{"i": 654,"n": "רבי אלעזר בר ביסנא","l": "א","b": "אמורא ארץ ישראלי. אמר בשם רבי אחא, שחי בדור הרביעי (ב\"ר פי\"ח - א').","cat": "sage"},{"i": 655,"n": "ר' אלעזר בר ברכיה","l": "א","b": "מובא בבבלי (סנהדרין צ\"ד ע\"ב).","cat": "sage"},{"i": 656,"n": "ר' אלעזר בר חנינא","l": "א","b": "מובא בירושלמי (כתובות פ\"ז ה\"ז). יש שסבורים שצ\"ל: ר\"א בשם ר' חנינא.","cat": "sage"},{"i": 657,"n": "רבי אלעזר בר יוסי","l": "א","b": "תנא בדור החמישי. בנו של התנא רבי יוסי בן חלפתא. כבר בחיי אביו היה גדול בתורה, ואביו מספר \"אלעזר בני אומר וכו' ונראין דבריו מדבריהם\" (פסחים קי\"ז ע\"א). הלך לרומי עם רבי שמעון בן יוחאי לבטל גזרה, ושם ראה את הפרוכת שלקח טיטוס הרשע מבית המקדש, והיו עליה כמה טיפות דמים מפר השעיר של יום הכיפורים שהוזו עליה. (מעילה י\"ז ע\"ב). ניצח את הכותים בויכוחים (סוטה ל\"ג ע\"ב).","cat": "sage"},{"i": 658,"n": "רבי אלעזר בר יוסף","l": "א","b": "הוא רבי אלעזר בר יוסי. מובא בירושלמי (ברכות ספ\"ז). מסר בשם רב (שם).","cat": "sage"},{"i": 659,"n": "רבי אלעזר בר ינאי","l": "א","b": "תנא בדורו של רבי. \"יוחסין\" כתב עליו: \"בזמן רבי יוחנן ואם כן אינו תנא\" והשיג עליו \"סה\"ד\" וכתב: \"לא ידעתי מי הגיד לו נבואה זו\". מסר בשם רבי אלעזר חסמא לפני רבי (תוספתא זבים פ\"א). רבי אלעזר בן אנטיגנוס מסר בשמו (גיטין ל\"א ע\"א).","cat": "sage"},{"i": 660,"n": "ר' אלעזר בר ישמעאל","l": "א","b": "מובא בירושלמי (תרומות פי\"א ה\"ב). ו\"סה\"ד\" כתב: \"טעות הוא וצ\"ל ר\"א כר' ישמעאל\".","cat": "sage"},{"i": 661,"n": "רבי אלעזר בר מלאי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\"ל (שבת קל\"ט ע\"א).","cat": "sage"},{"i": 662,"n": "רבי אלעזר בר מנחם","l": "א","b": "אמורא ארץ ישראלי בדור השלישי, בזמנו של רבי אבהו (ב\"ר ספכ\"ג). היה מבעלי האגדה.","cat": "sage"},{"i": 663,"n": "ר' אלעזר בר מניומי","l": "א","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (חולין י\"ט ע\"ב). ור\"נ אמר \"לאו היינו דר\"א בר מניומי דאמר\".","cat": "sage"},{"i": 664,"n": "רבי אלעזר בר מרון","l": "א","b": "מובא בשהש\"ר (רפ\"ז), ונראה שהוא ר\"א בר מרים.","cat": "sage"},{"i": 665,"n": "רבי אלעזר בר מרים","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי יונה (ירו', תענית פ\"ד ה\"ג).","cat": "sage"},{"i": 666,"n": "ר' אלעזר בר מרינוס","l": "א","b": "מובא באיכ\"ר (ספ\"ב).","cat": "sage"},{"i": 667,"n": "ר' אלעזר בר סימון","l": "א","b": "מובא (ב\"ר פ\"כ) ר' יוחנן בשמו, ויתכן שיש שם איזה שיבוש, ולא ידעתי מהו.","cat": "sage"},{"i": 668,"n": "רבי אלעזר בר צדוק","l": "א","b": "תנא בדור השני - השלישי. בנו של רבי צדוק שסופר עליו שצם ארבעים שנה כדי שלא תחרב ירושלים (גיטין נ\"ו ע\"א). ראה את הבית ומתאר כמה ממנהגיהם של אנשי ירושלים לפני החורבן (סוכה מ\"א ע\"ב). כן סיפר שבזמן החורבן ראה את בת נקדימון בן גוריון מלקטת שעורים מבין טלפי סוסים (כתובות ס\"ז ע\"א). תלמידו של רבי יוחנן בן החורני (יבמות ט\"ו ע\"ב).","cat": "sage"},{"i": 669,"n": "רבי אלעזר בר שמעון","l": "א","b": "תנא בדור החמישי. בנו ותלמידו של התנא רבי שמעון בן יוחאי (ירו', שבת פ\"י ה\"ה) לאחר פטירת אביו למד יחד עם חברו רבי, אצל רבן שמעון בן גמליאל ורבי יהושע בן קרחה (ב\"מ פ\"ד ע\"ב). היה גדול מרבי (ירו', שבת פ\"י ה\"ה). ישב עם אביו 31 שנה במערה (שבת ל\"ג ע\"ב).","cat": "sage"},{"i": 670,"n": "ר' אלעזר בר' יוסי בן זמרא","l": "א","b": "מובא בויק\"ר (פכ\"ז - ה'). יש גורסים: ר\"א בשם ר' יוסי בן זמרא.","cat": "sage"},{"i": 671,"n": "ר' אלעזר בר' יצחק","l": "א","b": "מובא בבבלי (סוכה מ\"ד ע\"ב) לפי גירסת \"דק\"ס\" וה\"יוחסין\" שם. וכן מובא במקום אחר (הוריות י\"ג ע\"ב). אבל \"סה\"ד\" כתב שהוא ט\"ס וצ\"ל: ר\"א בר צדוק.","cat": "sage"},{"i": 672,"n": "ר' אלעזר בר' סימאי","l": "א","b": "מובא בקה\"ר (פי\"א - א'). נראה שצ\"ל: ר\"א בשם ר' סימאי, וכן כתב \"סה\"ד\" שהוא ט\"ס.","cat": "sage"},{"i": 673,"n": "ר' אלעזר דמן ננוה","l": "א","b": "אמורא בדור השני - השלישי. רבה בר רב הונא ספר, שראהו הולך בתענית ציבור בסנדלי שעם (יומא ע\"ח ע\"ב).","cat": "sage"},{"i": 674,"n": "רבי אלעזר דמן רומא","l": "א","b": "אמורא בדור הראשון. רבי יוחנן מסר ממנו הלכה (גיטין ס\"ז ע\"ב).","cat": "sage"},{"i": 675,"n": "רבי אלעזר דרומה","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי חברו של ר' יונה (ירו', פאה פ\"ח ה\"ב).","cat": "sage"},{"i": 676,"n": "רבי אלעזר דרומייא","l": "א","b": "מובא בירושלמי (חגיגה פ\"ג ה\"ב), והוא ר\"א דרומה.","cat": "sage"},{"i": 677,"n": "רבי אלעזר המודעי","l": "א","b": "תנא בדור השני - השלישי. תלמידו של רבן יוחנן בן זכאי (ב\"ב י' ע\"ב). ישב עם ר' ישמעאל ורבי טרפון, וקרא לר\"ט \"רבי\" (יומא ע\"ו ע\"א). חברם של ר\"א, ר' יהושע ור\"ג (ב\"ב שם). רבן גמליאל אמר עליו: \"עדיין אנו צריכים למודעי\" (שם).","cat": "sage"},{"i": 678,"n": "ר' אלעזר הקליר","l": "א","b": "תנא. והוא רבי אלעזר ברבי שמעון [בן יוחאי] על פי דעה שמביא תוספות (חגיגה י\"ג ע\"א בד\"ה: ורגלי).","cat": "sage"},{"i": 679,"n": "רבי אלעזר הקפר","l": "א","b": "תנא בדור החמישי. מושבו היה בלוד (תוספתא אהלות פי\"ח ח'). חברם של רבי ור' ישמעאל בר יוסי, והיה ר' פנחס בן יאיר יושב לפניהם (שם). רבי יהושע בן לוי היה תלמידו (ע\"ז מ\"ג ע\"א). בנו, רבי אלעזר, מוזכר בירושלמי (ביצה פ\"א ה\"ג). יש אומרים שהוא רבי אלעזר בן קפרא. במסכת חולין (פ\"ד ע\"ב) \"אמר ר' אבא: 'זה אחד מן הדברים שאמר ר' חייא אין לי עליהם תשובה והשיב ר\"א הקפר תשובה'\". מאמרו המפורסם: \"הקנאה והתאוה והכבוד מוציאים את האדם מן העולם\" (אבות פ\"ד).","cat": "sage"},{"i": 680,"n": "רבי אלעזר הקפר בריבי","l": "א","b": "מובא בבבלי (ע\"ז מ\"ג ע\"א), והוא רבי אלעזר הקפר, ופרש\"י ד\"ה בריבי: \"כלומר, אדם גדול, וכן קורין לו בכינוי\".","cat": "sage"},{"i": 681,"n": "אלעזר זעירא","l": "א","b": "אמורא בבלי בדור הראשון. בהיותו בנהרדעא נעל נעליים שחורות כסימן אבל על חורבן ירושלים, ואנשי ראש הגולה חשבוהו כבעל גאוה וחבשוהו בכלא. ולאחר שנוכחו שהוא אדם גדול - שחררוהו (ב\"ק נ\"ט ע\"ב).","cat": "sage"},{"i": 682,"n": "רבי אלעזר חסמא","l": "א","b": "תנא בדור השלישי. מחכמי יבנה. תלמידו המובהק של רבי יהושע (תוספתא זבחים פ\"ד ד'). הלך להקביל פניו (חגיגה ג' ע\"א). הלך עמו ושאל ממנו (נגעים פ\"ז מ\"ב). והנימוק שקראו לו ר\"א חסמא מובא (ויק\"ר פכ\"ג ד'), וחסמא אינו שם.","cat": "sage"},{"i": 683,"n": "ר' אלעזר חרסנה","l": "א","b": "מובא באיכ\"ר (פ\"ב - ד'). היה מהרוגי מלכות (שם).","cat": "sage"},{"i": 684,"n": "רב אלעזר מהגרוניא","l": "א","b": "אמוראי בבלי בדור הרביעי - החמישי. תלמידו של רבא (תענית כ\"ד ע\"ב). חברו של רב אחא בר תחליפא, ושניהם ביקרו אצל רב אחא בריה דרב איקא.","cat": "sage"},{"i": 685,"n": "אלעזר ספרא","l": "א","b": "תנא בדור השלישי. חברו של רבי יוחנן בן גודגדא (חולין נ\"ה ע\"ב).","cat": "sage"},{"i": 686,"n": "ר' אלעשא","l": "א","b": "אמורא ארץ ישראלי. מובא בויק\"ר (פ\"ד - ו').","cat": "sage"},{"i": 687,"n": "אמוראי דנהרדעא","l": "א","b": "מובא בבבלי (סנהדרין י\"ז ע\"ב) \"אמוראי דנהרדעא רב חמא\" (וע\"ע נהרדעי).","cat": "sage"},{"i": 688,"n": "אמי","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. \"ואמי [בלי \"רבי\"] שם חכם\" וכן כתבו תוספות (זבחים נ' ע\"א ד\"ה: אמר). ור' יוסף אמר: \"היינו דשמענא לאמי וכו' ולא ידענא מאי ניהו\" (יבמות פ' ע\"א). רבא אמר: \"אמר לי אמי\" (כתובות מ\"ח ע\"ב). עלה לא\"י (ירו', תרומות רפ\"ז). נראה שהוא חתנו של ר' יונה (מראשי דור החמישי בא\"י) כמובא בירושלמי (גיטין פ\"ב ה\"א).","cat": "sage"},{"i": 689,"n": "רבי אמי","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. שם אביו נתן (גיטין מ\"ד ע\"א). היה בבבל (מו\"ק כ\"ה ע\"א) ויתכן לומר ששם היה מתלמידיו הקטנים של ר\"ה (שם). וגם כשהיו הוא וחברו רבי אסי \"כהני חשיבי דארעא ישראל\", היו כפופים לרב הונא (מגילה כ\"ב ע\"א). מסר בשם רב (נדרים מ' ע\"ב). בארץ ישראל היה תלמידו המובהק של רבי יוחנן (חולין קי\"א ע\"ב), וכן קיבל עוד מר' אושעיא (ירו', שבת פ\"ג ה\"א). חברו המובהק היה רבי אסי ונסמכו יחד ונזכרים תדיר יחד (כתובות י\"ז ע\"א), ועליהם אמרו: \"דייני דארץ ישראל רבי אמי ורבי אסי\" (סנהדרין י\"ז ע\"ב). ואח\"כ היה ראש הדור, כדמצינו: \"מיני אמי בר נתן תצא תורה לכל ישראל\" (גיטין מ\"ד ע\"א). עמד בראש ישיבת טבריה אחרי פטירת רבי יוחנן (\"אגרת רב שרירא גאון\"). בין תלמידיו היו ר\"ז (חולין פ\"ו ע\"ב). וגם רב חסדא אמר: \"הא מילתא מגברא רבה שמיע לי ומנו רבי אמי\" (יבמות כ\"א ע\"ב). האריך ימים עד ימי רבא ששלח לשאול ממנו (גיטין ס\"ג ע\"ב).","cat": "sage"},{"i": 690,"n": "רבי אמי אבוה דרבי אבדימא דציפורן","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. רבי יצחק בר אלעזר אמר בשמו (ירו', ביצה פ\"א ה\"ט). בנו היה האמורא רבי אבדימי דציפורן, תלמידו של רבינא.","cat": "sage"},{"i": 691,"n": "אמי אבוה דשמואל בר אמי","l": "א","b": "אמורא בדור השני - השלישי. אביו של האמורא הארץ ישראלי רבי שמואל בר אמי (ירו', יבמות פ\"י ה\"ו). אמר בשם רב יהודה (שם).","cat": "sage"},{"i": 692,"n": "רבי אמי אסי","l": "א","b": "אמורא ארץ ישראלי בדור הרביעי, ששמו אמי אסי, נראה שהיה תלמיד ר' ירמיה (ירו', ברכות פ\"ב ה\"ג).","cat": "sage"},{"i": 693,"n": "רב אמי בבליא","l": "א","b": "מובא בירושלמי (גיטין פ\"ב ה\"א) והוא ר' אמי סתם.","cat": "sage"},{"i": 694,"n": "ר' אמי בר אבא","l": "א","b": "אמורא בבלי בדור הרביעי - החמישי. חותנו של רב אשי (חולין קי\"א ע\"א). נראה, שקיבל מרב אשי (לפי גיר' הרי\"ף [שבת רפט\"ו]: \"א\"ר אמי בר אבא אמר רב אשי\").","cat": "sage"},{"i": 695,"n": "ר' אמי בר אבין","l": "א","b": "אמורא בבלי בדור הרביעי. מובא בבבלי (כריתות כ' ע\"א): \"אמי בר אבין ורב חנינא בר אבין דאמרי תרווייהו\": וס\"א גורסים שם: אביי בר אבין.","cat": "sage"},{"i": 696,"n": "רב אמי בר אדא הרפנאה","l": "א","b": "אמורא בבלי בדור הרביעי. תלמידו של רבה (עירובין נ\"ט ע\"ב).","cat": "sage"},{"i": 697,"n": "רב אמי בר אהבה","l": "א","b": "מובא בבבלי (יבמות כ\"ט ע\"ב). המאמר מובא במקום אחר (נדרים ע\"ד ע\"א) אבל \"מסה\"ש\" (שם) לא גורס \"בר אהבה\".","cat": "sage"},{"i": 698,"n": "רב אמי בר דיקולי","l": "א","b": "והוא רמי בר תמרי.","cat": "sage"},{"i": 699,"n": "רב אמי בר חייא","l": "א","b": "אמורא בבלי בדור השלישי. ר\"ז שאל ממנו (זבחים ק\"ה ע\"ב). גירסת \"שיטה מקובצת\": \"אבין בר חייא\".","cat": "sage"},{"i": 700,"n": "רב אמי בר חמא","l": "א","b": "והוא רמי בר חמא. כך נקרא בירושלמי, וכן בבבלי (כתובות מ\"ה ע\"ב).","cat": "sage"},{"i": 701,"n": "ר' אמי בר טביומי","l": "א","b": "אמורא שחי לפני אביי, ואביי מפרש דבריו מובא בבבלי (סוכה ט\"ז ע\"א).","cat": "sage"},{"i": 702,"n": "ר' אמי בר טובי","l": "א","b": "והוא ר' אמי בר טביומי.","cat": "sage"},{"i": 703,"n": "ר' אמי בר יחזקאל","l": "א","b": "מובא בירושלמי (תענית פ\"ב הי\"ד), והוא רמי בר יחזקאל.","cat": "sage"},{"i": 704,"n": "רב אמי בר מתנה","l": "א","b": "אמורא בבלי בדור השני. תלמידו של שמואל. (ברכות ס\"ג ע\"א).","cat": "sage"},{"i": 705,"n": "רבי אמי בר נתן","l": "א","b": "מובא בבבלי (גיטין מ\"ד ע\"א). והוא רבי אמי סתם בש\"ס, חברו דרבי אסי.","cat": "sage"},{"i": 706,"n": "רבי אמי בר עוקבא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מצינו שאמר בשם רבי יוסי בר חנינא (ירו', כתובות פ\"ז ה\"ז).","cat": "sage"},{"i": 707,"n": "ר' אמי בר פפי","l": "א","b": "מובא בירושלמי (כתובות פ\"ו ה\"ו), והוא אבימי בר פפי.","cat": "sage"},{"i": 708,"n": "ר' אמי בר קרחה","l": "א","b": "אמורא בבלי בדור השני. אמר בשם רב (ירו', ב\"ב פ\"י ה\"ח).","cat": "sage"},{"i": 709,"n": "רב אמי בר שמואל","l": "א","b": "אמורא בבלי בדור השני. תלמיד מובהק של שמואל שאמר: \"לדידי מפרשא לי מיניה דמר שמואל\" (נדה כ\"ה ע\"ב).","cat": "sage"},{"i": 710,"n": "אמי ורדינאה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. היה תלמידו של ר' אבהו (נדה י\"ט ע\"ב). לפי לשון ראשון ברש\"י (שם) הוא \"אמי שפיר נאה\" (מובא גיטין מ\"א ע\"א). כינויו ורדינא הוא על שם יופיו (ביצה כ\"ז ע\"ב רש\"י).","cat": "sage"},{"i": 711,"n": "ר' אמי חתנו דר' יונה","l": "א","b": "ע\"ע אמי.","cat": "sage"},{"i": 712,"n": "אמי שפיר נאה","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי יוחנן (גיטין מ\"א ע\"א). לפי לשון ראשון ברש\"י (נדה י\"ט ע\"ב) הוא אמי ורדינאה.","cat": "sage"},{"i": 713,"n": "אמי תנורא","l": "א","b": "רב יהודה (האמורא הבבלי המפורסם שחי בדור השני) הורה לו דין בחול המועד (מו\"ק י\"א ע\"א). ה\"יוחסין\": כתב \"לא ידעתי אם הוא חכם\". ו\"סה\"ד\" לא הוסיף מאומה, וגם לי נראה שאין להכריע שהיה חכם.","cat": "sage"},{"i": 714,"n": "אמימר","l": "א","b": "אמורא בדור החמישי. מסר משמו של רבא (קידושין י' ע\"א). אך רבו המובהק היה רב זביד מנהרדעא (ב\"מ ע\"ג ע\"ב). מושבו היה בנהרדעא (ב\"ב ל\"א ע\"א), שם היה הראש (ברכות י\"ב ע\"א). היה הקובע גם במחוזא (ר\"ה ל\"א ע\"ב). כנראה שעמד בראש ישיבה (ביצה כ\"ח ע\"ב). רב אשי היה תלמידו (מנחות ל\"ז ע\"ב): \"רב אשי היה יתיב קמיה דאמימר\", והפך להיות לו תלמיד - חבר (ברכות נ\"ה ע\"ב): \"אמימר ומר זוטרא ורב אשי הוו יתבי בהדי הדדי\". נפטר בחיי רב אשי (ב\"מ ס\"ח ע\"א) בשל פליטת פה של רב אשי. בנו של אמימר ששמו היה מר היה תלמידו של רב אשי (שם).","cat": "sage"},{"i": 715,"n": "רב אמימר בר מר ינוקא","l": "א","b": "אמורא בבלי בדור השביעי. תלמידו של ר' חייא בריה דרב אויא (חולין י\"ח ע\"ב). נתפס ע\"י המלכות, בחודש טבת שנת תשפ\"א לשטרות (ד\"א ר\"ל /074), יחד עם הונא מר בר ריש גלותא ומשרשיא בר פקוד, ובאדר אותה שנה נהרג (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 716,"n": "אנטונינוס","l": "א","b": "קיסר רומי ידידו ואוהבו בנפש של רבנו הקדוש. רבי לימדו תורה (ע\"ז י' ע\"ב). פעמים, ורבי קיבל את סברתו (סנהדרין צ\"א ע\"ב): \"אמר רבי דבר זה למדני אנטונינוס ומקרא מסייעו\". יש אומרים שנתגייר (ירו', מגילה פ\"א הי\"א). נראה, שמת אחרי רבי (קה\"ר פ\"י ה').","cat": "sage"},{"i": 717,"n": "רבי אנטיגנוס","l": "א","b": "אמורא ארץ ישראלי קדום בדור הראשון, ואפשר שחי בדור המעבר בין התנאים לאמוראים. רבי יהושע בן לוי מסר משמו (ירו', הוריות פ\"ג ה\"ד).","cat": "sage"},{"i": 718,"n": "אנטיגנוס איש סוכו","l": "א","b": "מראשוני החכמים בדור המעבר בין אנשי כנסת גדולה ל\"זוגות\", כ - 052 שנה לפני החורבן. תלמידו של שמעון הצדיק (אבות פ\"א מ\"ג). שני תלמידיו צדוק ובייתוס יצאו לתרבות רעה, ויסדו כתות צדוקים ובייתוסים (אבות דרבי נתן פ\"ה). יוסי בן יועזר ויוסי בן יוחנן, שהיו דור ראשון ל\"זוגות\", קיבלו ממנו (אבות פ\"א מ\"ד).","cat": "sage"},{"i": 719,"n": "ר' אנייני בן סוסיי","l": "א","b": "הוא רבי אנינייא בר סיסי (ע\"ע).","cat": "sage"},{"i": 720,"n": "רבי אנינייא בר סיסי","l": "א","b": "אמורא ארץ ישראלי בדור השני. ר' סימון מסר בשמו (ירו', יומא פ\"ג ה\"ה). דודו של רבי נסא (ירו', ברכות פ\"ז ה\"ב). \"סה\"ד\" סובר שהוא, ור' חנינא בר סיסי (ירו', סנהדרין פ\"ב ה\"ו) אחד הוא. ונראה לומר, שהיה אמורא נוסף בשם זהה, בדור החמישי - הששי. ע\"ע רבי חנינא בר סיסי.","cat": "sage"},{"i": 721,"n": "אנן בר אימא","l": "א","b": "מובא בירושלמי (שבת פ\"ו ה\"ה). גיר' \"אור זרוע\" ח\"ב ספ\"ד: חנן בר אימי (תלמידו של רב יהודה), (ע\"ע).","cat": "sage"},{"i": 722,"n": "רבי אסא","l": "א","b": "מובא במד\"ר (פ' נשא פ\"ו), ואולי ט\"ס היא וצ\"ל: ר' אסי.","cat": "sage"},{"i": 723,"n": "אסא בן עקיבא","l": "א","b": "מובא בירושלמי (עירובין פ\"ד ה\"א), והוא איסי בן עקביה.","cat": "sage"},{"i": 724,"n": "רב אסי","l": "א","b": "אמורא בבלי בדור הראשון (להבדילו מרבי אסי, אמורא ארץ ישראלי בדור השלישי). תלמיד חבר לרב (שבת קמ\"ו ע\"ב רש\"י ד\"ה: רב): לגמירי דרב הוו צריך ולא לסברתו (סנהדרין ל\"ו ע\"ב). ללוי קרא \"רבי\" (ע\"ז ל\"ח ע\"ב). היה הראש בעיר הוצל (מגילה ה' ע\"ב). נראה, שעמד בראש ישיבה אחרי פטירת רב ואח\"כ באו תלמידיו לפני שמואל (יבמות י\"ז ע\"א רש\"י). ר\"ה היה תלמידו (כתובות מ\"ח ע\"ב) וכן רב יהודה (שבת כ\"ב ע\"א). נפטר כעונש על שהכניס בשמתא את חברו (נדה ל\"ו ע\"ב).","cat": "sage"},{"i": 725,"n": "רבי אסי","l": "א","b": "אמורא ארצישראלי בדור השלישי. עלה מבבל ושם עוד הכיר אישית את שמואל וסיפר ששמע את רב יהודה שואל את שמואל (ירו', עירובין פ\"ו ה\"ח). ולמד מרב יהודה (ב\"מ מ\"ג ע\"א). בארץ ישראל היה תלמידו המובהק של רבי יוחנן (חגיגה י\"ג ע\"א). וכן קיבל מרבי אלעזר (ירו', חגיגה פ\"א ה\"ז) ומרבי חנינא (סנהדרין מ\"ג ע\"ב). היה חברו המובהק של רבי אמי, ושניהם נזכרים כמעט תמיד יחד בש\"ס, והיו כפופים לרב הונא (מו\"ק כ\"ה ע\"א) ונסמכו יחד בארץ ישראל (כתובות י\"ז ע\"א). והם המכונים \"דייני דארץ ישראל\" (סנהדרין י\"ז ע\"ב). בין תלמידיו היה ר\"ז (ב\"ב פ\"ד ע\"ב). גם רבי אבהו קיבל ממנו (יבמות ס\"ה ע\"ב). כשמת - נתקבצו החכמים על מנת לחזור על השמועות ששמעו מפיו, כדי שלא ישתכחו (קידושין י\"ג ע\"א).","cat": "sage"},{"i": 726,"n": "רבי אסי בן שאול","l": "א","b": "מובא בבבלי (שבת נ' ע\"א). צ\"ל: רבי יוסי בן שאול (תלמידו של רבי).","cat": "sage"},{"i": 727,"n": "רבי אסי בר אבא","l": "א","b": "מובא בבבלי לפי גירסת הרי\"ף מסר משם רבי יוחנן (יבמות ל\"ט ע\"ב).","cat": "sage"},{"i": 728,"n": "ר' אסי בר היני","l": "א","b": "הוא איסי בר היני.","cat": "sage"},{"i": 729,"n": "ר' אסי בר חייא","l": "א","b": "מובא בבבלי (ע\"ז נ\"א ע\"ב). \"סה\"ד\" מפקפק שמא הוא ור' אמי בר חייא אחד הוא. \"דק\"ס\" גורס: \"ר' שימי בר חייא\".","cat": "sage"},{"i": 730,"n": "ר' אסי בר חמא","l": "א","b": "מובא בבבלי (ב\"ק צ\"ג ע\"א). \"סה\"ד\" ו\"דק\"ס\" גורסים: \"רב יוסף בר חמא\" (אבי רבא).","cat": "sage"},{"i": 731,"n": "ר' אסי בר חנינא","l": "א","b": "מובא בבבלי (בכורות ל\"ד ע\"ב), והגיהו שם: ר' יוסי בר חנינא. וכ\"ה ב\"דק\"ס\" (ב\"ב נ\"ו ע\"א).","cat": "sage"},{"i": 732,"n": "רב אסי בר ממל","l": "א","b": "מובא בירושלמי (גיטין פ\"ג ה\"ח): \"חנינא בריה דרב אסי בר ממל\".","cat": "sage"},{"i": 733,"n": "ר' אסי בר מתיא","l": "א","b": "מובא ב\"ילקוט\" (פנחס רמז תשע\"ו).","cat": "sage"},{"i": 734,"n": "רב אסי בר נתן","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (נדרים ע\"ח ע\"א). שאל מרבי חייא בר אשי (שבת נ\"ג ע\"א), ודיבר עם רבי זירא (שם).","cat": "sage"},{"i": 735,"n": "רב אסי ג'","l": "א","b": "אמורא בבלי בדור הששי. תלמידו של רבא (שבת צ\"ה ע\"ב). חברו של רב אשי (כתובות ח' ע\"א). בנו, רב סמא, היה תלמידו של רב אשי (שם ל\"ג ע\"ב). בכתבי יד קדומים נקרא: רב אתי או איתי, ושיבשוהו לרב אסי.","cat": "sage"},{"i": 736,"n": "רב אסי דהוצל","l": "א","b": "אמורא בבלי בדור השלישי. נראה, שהיה בזמנו של ר\"ה (קידושין נ\"ח ע\"ב).","cat": "sage"},{"i": 737,"n": "ר' אסי מנהרביל","l": "א","b": "מובא בבבלי (חולין פ\"ז ע\"ב). גירסת ה\"יוחסין\": מנהר - בול. ושם (קל\"ו ע\"א): \"אמר רבי יוסי מנהרביל\". וב\"דק\"ס\": \"אסי ויוסי אחד הם\". \"יוחסין\" גרס שני שמות: ר' יוסי מנהר - בול ור' אסי מנהר - בול.","cat": "sage"},{"i": 738,"n": "רבי אפטוריקי","l": "א","b": "אמורא, כנראה ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא בבבלי (זבחים י\"ב ע\"א). רב אדא בר אהבה מתיב על דבריו (מנחות נ\"ה ע\"ב). אביו דוסתאי היה חכם שונה ברייתות (חולין ס\"ד ע\"ב: ב\"מ ה' ע\"א). נקרא על שם בנו אבוה דר' אפטוריקי (חולין שם).","cat": "sage"},{"i": 739,"n": "רבי אפס","l": "א","b": "אמורא ארץ ישראלי. מראשוני הדור הראשון. בדורו של ר' יהודה הנשיא. מושבו היה בדרום א\"י (עירובין ס\"ה ע\"ב: ירו', תענית פ\"ד ה\"ב). היה סופרו של ר' יהודה הנשיא (ב\"ר ע\"ה - ה'). אחר פטירת ר' יהודה הנשיא ישב בראש הישיבה (כתובות ק\"ג ע\"ב). בענין הלכה מוזכר שמו רק פעם אחת (יומא ס\"א ע\"א). ריש לקיש פנה אליו בשאלה (עירובין שם). רבי הושעיא מסר משמו (ירו', יומא פ\"ה ה\"ז). לוי היה כפוף לו (כתובות שם).","cat": "sage"},{"i": 740,"n": "אפקולוס","l": "א","b": "תנא דברייתא. מובא בתוספתא (חולין רפ\"ח). \"סה\"ד\" מביא גם את פירוש הר\"ן (חולין ק\"ד ע\"ב) \"אפקולוס פירוש מטלית\".","cat": "sage"},{"i": 741,"n": "אפרא הורמיז","l": "א","b": "אמו של מלך פרס בזמנו של רבא. מוזכרת לשבח בבבלי (נדה כ' ע\"ב). היתה נוכרית וקרובה להתגייר, ואף קרבנות היתה שולחת. כדי להוכיח לבנה המלך שבור מלכא את גדולתם של החכמים ביקשה מרבא שיבקש שירד גשם בתמוז וכן היה (תענית כ\"ד ע\"ב).","cat": "sage"},{"i": 742,"n": "אפרים","l": "א","b": "מובא בירושלמי (סוף ב\"מ). ע\"ע אפרים ספרא.","cat": "sage"},{"i": 743,"n": "אפרים מקשאה","l": "א","b": "תנא בדור החמישי. תלמידו של ר\"מ (ב\"מ פ\"ז ע\"א). פירוש השם \"מקשאה\": שומר קשואין או מקשה הלכות.","cat": "sage"},{"i": 744,"n": "אפרים ספרא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (סוף ב\"מ): \"אפרים בשם ריש לקיש\".","cat": "sage"},{"i": 745,"n": "אריוך","l": "א","b": "כינוי לשמואל (מנחות ל\"ח ע\"ב), ופרש\"י: \"לשון מלך כמו (בראשית מ\"ט) גור אריה יהודה, ולהכי קרי לשמואל - אריוך, דקיימא לן (בכורות מ\"ט ע\"ב) הלכה כשמואל בדיני, כי היכי דדינא דמלכותא דינא\". ע\"ע שבור מלכא.","cat": "sage"},{"i": 746,"n": "אריוס","l": "א","b": "מובא בספרי (דברים פ' י\"ג) ואין להכריע אם היה חכם. שאל את רבי יוסי (תנא ארץ ישראלי בדור הרביעי) (שם).","cat": "sage"},{"i": 747,"n": "ר' אריסטי","l": "א","b": "אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (תולדות י\"ט), שמסר בשם רבי ברכיה.","cat": "sage"},{"i": 748,"n": "רבי ארמניא","l": "א","b": "אמורא ארץ ישראלי בדור הששי. רבי מנא הורה לו בדיני אבלות (ירו', מו\"ק פ\"ג ה\"ה).","cat": "sage"},{"i": 749,"n": "רב אשי","l": "א","b": "גדול אמוראי בבל בדור הששי וראש הדור. נולד ביום שמת רבא (קידושין ע\"ב ע\"ב), בשנת ד\"א קי\"א (153) נפטר בשנת ד\"א קפ\"ו (624) (\"אגרת רב שרירא גאון\"). עמד בראש ישיבת סורא. סידר וערך את התלמוד הבבלי בשתי מהדורות במשך 06 שנה (ב\"ב קנ\"ז ע\"ב וברשב\"ם). בתוספות כתבו (חולין ב' ע\"ב ד\"ה: אנא): \"ומכאן ראיה שרב אשי סידר הגמרא\". \"רב אשי ורבינא סוף הוראה\" (ב\"מ פ\"ו ע\"א), ופרש\"י: \"סוף כל האמוראים\". עמד בראש במתא מחסא (שבת י\"א ע\"א רש\"י) שהיא סורא (\"אגרת רב שרירא גאון\" ב\"יוחסין\" הישן). רבותיו המובהקים היו רב כהנא (ברכות ל\"ט ע\"א), ר\"פ (ע\"ז מ' ע\"א) ורב מתנה (זבחים כ\"ט ע\"א). בין תלמידיו הרבים היה בנו מר בר רב אשי (חולין ע\"ו ע\"ב), שישב על כסא אביו (ב\"ב י\"ב ע\"ב). היה עשיר מופלג ועליו אמרו \"מימות רבי ועד רב אשי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). על פטירתו מסופר, שמלאך המות פגשו בשוק ורב אשי בקשו שימתין 03 יום טרם ימות, כדי שיחזור על תלמודו (מו\"ק כ\"ח ע\"א).","cat": "sage"},{"i": 750,"n": "רב אשי בר אבין","l": "א","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (שבת ס\"ו ע\"ב). גירסת הרי\"ף, הרא\"ש ו\"דק\"ס\": \"רב אידי בר אבין\".","cat": "sage"},{"i": 751,"n": "רב אשי מאויריא","l": "א","b": "אמורא בבלי בדור הרביעי. אמר בשם ר' זירא (שבועות כ\"ד ע\"ב). ישב באויריא (רש\"י שם).","cat": "sage"},{"i": 752,"n": "רב אשי מהוצל","l": "א","b": "מובא בבבלי: \"התקין רב אשי בהוצל\" (חולין ק\"ז ע\"א). יש גירסא:\" רב אסי דהוצל\" (ע\"ע).","cat": "sage"},{"i": 753,"n": "אשיאן א'","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי: \"בעא מיניה אשיאן תנא דבי רבי אמי מרבי אמי\" (ברכות י\"ד ע\"א).","cat": "sage"},{"i": 754,"n": "אשיאן בר נידבך","l": "א","b": "אמורא בדור השלישי. אמר משמו של רב יהודה (מנחות כ\"ט ע\"א). ר\"ז אמר משמו (ירו', מגילה פ\"א ה\"ט). היה חתנו של רבי ייבא (ב\"ב כ\"ב ע\"ב).","cat": "sage"},{"i": 755,"n": "רב אשיאן ב'","l": "א","b": "מובא בירושלמי (תרומות ספ\"א), והוא בן אשיין. נראה, שהוא גם רבי שיין. (ע\"ע).","cat": "sage"},{"i": 756,"n": "רב אשייאן בר יקום","l": "א","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר' אסי ושקיל וטרי עמו (ירו', יבמות פי\"א ה\"ז).","cat": "sage"},{"i": 757,"n": "אשייאן בר נידבה","l": "א","b": "מובא בירושלמי (מגילה פ\"א ה\"ט), והוא אשיאן בר נידבך.","cat": "sage"},{"i": 758,"n": "אשייאן נגרא","l": "א","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו', ע\"ז רפ\"ג).","cat": "sage"},{"i": 759,"n": "רבי אשיין","l": "א","b": "אמורא ארץ ישראלי בדור החמישי - הששי. מסר הרבה בשם רבי יונה (ירו', יומא פ\"ח ה\"ז). הוא ור' אשייאן אחד הם. נראה, שהוא גם רבי שיין (ירו', עירובין פ\"א ה\"ו).","cat": "sage"},{"i": 760,"n": "ר' אתי","l": "א","b": "ע\"ע רב אסי ג'.","cat": "sage"},{"i": 761,"n": "א\"ר יוסי בר'","l": "א","b": "כך מובא בירושלמי (ברכות פ\"ח ה\"א), והמאמר מובא בבבלי (פסחים ק\"ו ע\"ב תד\"ה: מקדש) בשם יוסי בר בון, ונראה שבירושלמי הושמט השם בון.","cat": "sage"},{"i": 762,"n": "ר' בא","l": "ב","b": "מגדולי אמוראי בבל ומראשי הדור הרביעי. אביו היה האמורא רב יוסף בר חמא (עירובין נ\"ד ע\"א). רש\"י כתב: \"רבא בריה דרב יוסף בר חמא (כצ\"ל) הוא והוא רבא בכולי גמרא בר פלוגתיה דאביי\" (חולין מ\"ג ע\"ב). היה ראש ישיבת מחוזא ארבע עשרה שנה נפטר בשנת ד' קי\"א (153). במותו נחלקה ישיבת מחוזא לשתים: רב נחמן בר יצחק תלמידו מלך בפומבדיתא ורב פפא תלמידו מלך בנרש (\"אגרת רב שרירא גאון\"). רב נחמן היה רבו המובהק (ברכות כ\"ג ע\"ב). רבא היה אצלו כשרב נחמן נפטר (מו\"ק כ\"ח ע\"א). וגם רב חסדא היה רבו (קידושין נ\"ג ע\"ב), וכן היה חותנו (יבמות ל\"ד ע\"ב). גם רב יוסף היה רבו המובהק (יומא נ\"ג ע\"א). וכשנודע לרב יוסף שרבא מכבדו מאוד, ברכו שיהיה ראש ישיבה (שם). ולדעת תוספות היה גם רב סחורה רבו המובהק. \"רב סחורה רבו המובהק של רבא היה\" (ע\"ז י\"ט ע\"א ד\"ה: אמר). חברו הגדול והמובהק היה אביי, ועל שמם נקרא הש\"ס: \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). מחלוקותיהם ושקלי וטרי שלהם פזורים בכל הש\"ס, וכבר בילדותם למדו יחד (ברכות מ\"ח ע\"א). כשנפטר רב יוסף, מינו את אביי לראש (סוף הוריות), וכשאביי נפטר בשנת ד' צ\"ח (833) בפומבדיתא, מלך רבא. אך במקום בפומבדיתא, יסד את ישיבתו במחוזא, והיא היתה הישיבה המרכזית בבבל (\"אגרת רב שרירא גאון\"), ורב נחמן בר יצחק שימש כראש כלה אצלו (ב\"ב כ\"ב ע\"א). דרך לימודו של רבא היה בחריפות: \"אמר רבא וכו' היינו דאמרי אינשי: 'טבא פילפלתא חריפתא ממלי צנא דקרי'\" (חגיגה י' ע\"א). אהב את הסברא: \"אמר להו (רבא): 'זיל בתר סברא'\" (גיטין ע\"ג ע\"א). והלכה כרבא שהוא בתראה (ברכות י\"ג ע\"ב תוס'). תוספות כתבו: \"בכל מקום שהרב והתלמיד חולקין הלכה כדברי הרב באמוראי עד אביי ורבא, אבל מכאן ואילך פסקינן כבתראי\" (קידושין מה ע\"ב ד\"ה: הוה). בין תלמידיו הרבים היו רבינא (ב\"ב ט\"ז ע\"ב), רב פפא (כתובות פ\"ה ע\"א), ובניו רב יוסף (חולין כ\"ח ע\"ב) ורב משרשיא (שם ע\"א), ועל שניהם אמר רבא: \"חכים ברי בטריפות\" (שם). היה מופלג בחסידות ולא בוש לומר: \"טעיתי\" (עירובין ק\"ד ע\"א). נהג לצום שני ימים ביום הכיפורים משום ספיקא (ר\"ה כ\"א ע\"א). ובכל ערבי יום כפורים יצאה בת קול מהשמים ושאלה לשלומו (תענית כ\"א ע\"ב). היה עשיר מופלג וחכם נדיר (מו\"ק כ\"ח ע\"א). היה מקורב למלכות (ב\"ב י' ע\"ב). לפי דרישתו של שבור מלכא מלך פרס, שניסה אותו, ביקש פעם מן השמים בחודש תמוז שירד גשם שוטף ובקשתו נתקבלה, ואביו בא לו בחלום ואמר שלא ישן במיטתו בלילה, שכן יש הקפדה מהשמים שהטריח בעניין הגשמים, ובלילה, חתכו השדים את מיטתו (תענית כ\"ד ע\"ב). ושוב שלחו מבית שבור מלכא לשאלו אם יודע להבחין בין סוגי דם, וידע להבחין יותר מששים סוגי דם (נדה כ' ע\"ב). ומסופר (מו\"ק שם) על פטירתו, שרב שעורים אחיו של רבא היה אצלו כשמת, וביקש רבא את אחיו שיאמר למלאך המות שלא יצערו. אחרי פטירתו נגלה לאחיו רב שעורים וסיפר לו שהיתה לו מיתה קלה בלי צער, והתחושה היתה כאילו הקיזו דם. כשמת רב יהודה, נולד רבא, וכשמת רבא, נולד רב אשי (קידושין ע\"ב ע\"ב).","cat": "sage"},{"i": 763,"n": "רבי בא בר בינא","l": "ב","b": "מובא בירושלמי (כתובות פ\"א ה\"ב). ע\"ע רבי אבא בר אבינא.","cat": "sage"},{"i": 764,"n": "רבי בא בר בינה","l": "ב","b": "מובא בירושלמי (מגילה פ\"א ה\"ט). ע\"ע רבי אבא בר אבינא.","cat": "sage"},{"i": 765,"n": "רבי בא בר חונא","l": "ב","b": "מובא בירושלמי (שבת רפי\"א). ע\"ע רבה בר רב הונא.","cat": "sage"},{"i": 766,"n": "רבי בא בר חייא בר אשי","l": "ב","b": "מובא בירושלמי (שבת פ\"ז ה\"ב). סביר שצ\"ל: ר' אבא [בשם] ר' חייא בר אשי.","cat": "sage"},{"i": 767,"n": "רבי בא בריה דרבי חייא בר יוא","l": "ב","b": "מובא בירושלמי (דמאי פ\"א ה\"ד), והוא רבי אבא בריה דרבי חייא בר אבא (ע\"ע).","cat": "sage"},{"i": 768,"n": "באלי","l": "ב","b": "אמורא בבלי בדור הרביעי. תלמידו של רב חייא בר אבא (תענית י\"ח ע\"א). כן מסר בשם רבי יעקב ברה דבת שמואל (ברכות כ\"ה ע\"ב).","cat": "sage"},{"i": 769,"n": "בבא בן בוטא","l": "ב","b": "תנא בדור הראשון. דור לפני החורבן. אף שהיה מתלמידיו של שמאי עשה כהלל (ביצה כ' ע\"א). כאשר הורדוס הרג את חכמי ישראל, השאיר בחיים את בבא בן בוטא, אך ניקר את עיניו. אח\"כ, בהשפעתו, חידש ובנה הורדוס את בית המקדש (ב\"ב ד' ע\"א). היה חסיד (כריתות כ\"ה ע\"א), ענו (נדרים ס\"ו ע\"א) וחכם (גיטין נ\"ז ע\"א).","cat": "sage"},{"i": 770,"n": "בג בג","l": "ב","b": "ראה בן בג בג.","cat": "sage"},{"i": 771,"n": "ר' בדלה","l": "ב","b": "מובא בבמד\"ר (פי\"ב - ח'), ונראה שצ\"ל: ר' בצלאל.","cat": "sage"},{"i": 772,"n": "בהא","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (תמורה כ\"ט ע\"א). עלה מבבל לארץ ישראל והיה חברו של ר' אבא (שם).","cat": "sage"},{"i": 773,"n": "רב בודיא","l": "ב","b": "אמורא בבלי בדור הששי - השביעי. הקשה לרב אשי (גיטין מ\"ה ע\"ב).","cat": "sage"},{"i": 774,"n": "בוהיין","l": "ב","b": "חי בתקופת התנאים, בדורו של ר\"ע, שבא לביתו לאיסוף כסף לצרכי צדקה (ירו', פסחים ספ\"ד). בבבלי (פסחים נ\"ז ע\"א) מובא: בן בוהיין נתן פאה לירק (על אף שפטורים מכך). בירושלמי (שם) מכונה \"בן מביא יין\".","cat": "sage"},{"i": 775,"n": "ר' בוטא","l": "ב","b": "מובא בזהר חדש (פ' נעשה אדם).","cat": "sage"},{"i": 776,"n": "בוטנית בריה דאבא שאול בן בוטנית","l": "ב","b": "תנא - אמורא בדור המעבר בין התנאים לאמוראים בארץ ישראל. מצא פתח לנדר של ר' שמעון, בנו של רבי (נדרים כ\"ג ע\"א).","cat": "sage"},{"i": 777,"n": "ר' בולאטה","l": "ב","b": "מובא (ירו', תענית פ\"ד ה\"ב) והוא בלוויטי.","cat": "sage"},{"i": 778,"n": "ר' בון","l": "ב","b": "ע\"ע אבין או רבין.","cat": "sage"},{"i": 779,"n": "בונה בר שילא","l": "ב","b": "מובא בירושלמי (גיטין פ\"ב ה\"ג), והוא רבינא בר שילא.","cat": "sage"},{"i": 780,"n": "בוני (2)","l": "ב","b": "ע\"ע נקדימון בן גוריון.","cat": "sage"},{"i": 781,"n": "בונייס בן בונייס","l": "ב","b": "אמורא ארץ ישראלי בדור רבי (עירובין פ\"ה ע\"ב). היה עשיר גדול (גיטין נ\"ט ע\"א). שלח לרבי מתנות יקרות (שם).","cat": "sage"},{"i": 782,"n": "בונים בן נונים","l": "ב","b": "מובא בבבלי (גיטין נ\"ט ע\"א), והוא בונייס בן בונייס.","cat": "sage"},{"i": 783,"n": "רבי בוסנא","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר' אלעאי (ירו', שבת פ\"ב ה\"ו), ובשם ר' חייא בר אבא (תנחומא שמיני - י\"ב), וחלק עם רבי ברכיה (ירו', מעשרות פ\"ה ה\"ג).","cat": "sage"},{"i": 784,"n": "רב בוריא","l": "ב","b": "כך גירסת \"יחוסי תנאים ואמוראים\", ולפנינו (גיטין מ\"ה ע\"ב) רב בודיא.","cat": "sage"},{"i": 785,"n": "רבי בורקי","l": "ב","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי מנא (ירו', קידושין פ\"ג ה\"ב), ושנה לפניו ברייתא (ירו' ע\"ז פ\"ג ה\"ה). הוא וחבריו היו משלשין את היום: שליש לתורה שליש לתפילה ושליש למלאכה (קה\"ר פ\"ט - ט').","cat": "sage"},{"i": 786,"n": "ר' בזירה","l": "ב","b": "מובא בירושלמי (ברכות פ\"ח ה\"ה), ונראה שהוא ט\"ס וצ\"ל בשם ר' נזירא.","cat": "sage"},{"i": 787,"n": "ר' ביבא","l": "ב","b": "ע\"ע רבי ביבי א'.","cat": "sage"},{"i": 788,"n": "ר' ביבא אבא","l": "ב","b": "מובא בירושלמי (תענית פ\"ב ה\"ד). אמר (שם) בשם ר' יוחנן. גיר' \"סה\"ד\" שצ\"ל: ר' ביבי בר אבין\".","cat": "sage"},{"i": 789,"n": "ר' ביבא בר אחא","l": "ב","b": "מובא בירושלמי (שקלים פ\"א), לגיר' ה\"יוחסין\".","cat": "sage"},{"i": 790,"n": "ר' ביבא בר זבדא","l": "ב","b": "מובא באיכ\"ר (פ\"ג פ' נחפשה). ויש גורסים: ר' בא בר זבדא.","cat": "sage"},{"i": 791,"n": "רב ביבא בריה דר' אבא","l": "ב","b": "מובא בויק\"ר (פ\"ג). ו\"סה\"ד\" סובר שצ\"ל: \"ר' ביבי בר אבין\".","cat": "sage"},{"i": 792,"n": "ר' ביבא סנגוריא","l": "ב","b": "מובא באיכ\"ר (פ\"א - נ\"א). נראה, שצ\"ל: ר' אבא סרונגיא.","cat": "sage"},{"i": 793,"n": "ר' ביבא רבה","l": "ב","b": "מובא בפסיקתא דר\"כ (קנ\"ד), ונראה שהוא רב ביבי ב'.","cat": "sage"},{"i": 794,"n": "ר' ביבון","l": "ב","b": "מובא בירושלמי (גיטין פ\"ג ה\"א).","cat": "sage"},{"i": 795,"n": "ר' ביבון בר חייא","l": "ב","b": "מובא בירושלמי (גיטין פ\"ג ה\"א).","cat": "sage"},{"i": 796,"n": "רבי ביבי א'","l": "ב","b": "אמורא בבלי בדור הרביעי. תלמידם של ר\"נ (חגיגה כ\"ב ע\"ב) ושל רב יהודה (עירובין כ\"ג ע\"ב). קיבל גם מרב המנונא [תלמיד חבר של רב חסדא] (נדה כ\"ז ע\"א). ר\"פ היה קטן ממנו (שם). התאכסן אצל רב יוסף, שקרא לו גברא רבא (קידושין ע\"ו ע\"ב).","cat": "sage"},{"i": 797,"n": "רב ביבי בר אביי (2)","l": "ב","b": "אמורא בבלי בדור החמישי. בנו של אביי (סנהדרין ס\"ו ע\"ב). תלמידו של רב יוסף (שם). לא מצינו בש\"ס שקבל מאביו אביי. רבו של רב פפי (חולין מ\"ג ע\"ב). מלאך המות היה שכיח גביה (חגיגה ד' ע\"ב). ביקש לראות שדים וניזוק, והתפללו עליו ונתרפא (ברכות ו' ע\"ב).","cat": "sage"},{"i": 798,"n": "רב ביבי בר אבין","l": "ב","b": "מובא בבבלי (נדה כ\"ה ע\"ב), לגיר' ה\"יוחסין\", והוא רבי ביבי ב' (ע\"ע).","cat": "sage"},{"i": 799,"n": "רב ביבי בר אבינא","l": "ב","b": "מובא ב\"ילקוט\" (משלי רמז תתקנ\"ט).","cat": "sage"},{"i": 800,"n": "רב ביבי בר אשי","l": "ב","b": "גיר' \"יוחסין\": א\"ר ביבי אמר רב אשי.","cat": "sage"},{"i": 801,"n": "רב ביבי בר ביזנא","l": "ב","b": "ע\"ע נהרבלאי.","cat": "sage"},{"i": 802,"n": "ביבי בר גוזלון","l": "ב","b": "אמורא בבלי בדור הראשון - השני. תלמידו של רב. רבו של רב הונא. (ירו', ב\"מ פ\"ב ה\"ה).","cat": "sage"},{"i": 803,"n": "ר' ביבי בר גוזלן","l": "ב","b": "ע\"ע ביבי בר גוזלון.","cat": "sage"},{"i": 804,"n": "ר' ביבי בר חייא","l": "ב","b": "נראה שהוא ר' אבון בר חייא.","cat": "sage"},{"i": 805,"n": "ר' ביבי בר כהנא","l": "ב","b": "מובא בירושלמי (שקלים פ\"ב ה\"ד). וצ\"ל: ר' בון [אבין] בר כהנא.","cat": "sage"},{"i": 806,"n": "ר' ביבי בריה דר' אמי","l": "ב","b": "מובא בב\"ר (פכ\"ו - ו').","cat": "sage"},{"i": 807,"n": "רבי ביבי ב'","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה שהוא ר' ביבי בר אביי, תלמידו המובהק של ר' יוחנן (נדה כ\"ה ע\"ב) [לא ר' ביבי בר אביי בנו של אביי]. וכן מצינו: \"אמר ר' ביבי אמר ר\"ל\" (מכות י\"ז ע\"א). היה תלמידם של ר' אמי ושל ר' אסי (שבת ע\"ד ע\"א).","cat": "sage"},{"i": 808,"n": "ר' ביבי מרגניא","l": "ב","b": "מובא באיכ\"ר (פ\"א - מ\"א). \"סה\"ד\": \"אולי ט\"ס ואולי צ\"ל ר' אבא סרונגיא\".","cat": "sage"},{"i": 809,"n": "ר' ביבי מרנגיא","l": "ב","b": "מובא באיכ\"ר (פ\"א - מ\"א), ונראה שצ\"ל: ר' אבא סרונגיא.","cat": "sage"},{"i": 810,"n": "ר' ביבי רבה","l": "ב","b": "מובא בירושלמי (תענית פ\"ב), ונראה שצ\"ל: ר' ביבי בר אבין.","cat": "sage"},{"i": 811,"n": "ר' ביבן","l": "ב","b": "ע\"ע רבי ביבי א'.","cat": "sage"},{"i": 812,"n": "ר' ביזנא בר זבדא","l": "ב","b": "מובא בבבלי: \"א\"ר ביזנא בר זבדא א\"ר עקיבא א\"ר פנדא וכו'\" (ברכות נ\"ה ע\"ב). ונראה לי כי יש כאן איזה שיבוש.","cat": "sage"},{"i": 813,"n": "ביטנית בריה דאבא שאול בן ביטנית","l": "ב","b": "מובא (נדרים כ\"ג ע\"א) שהתיר נדר לר' שמעון בנו של רבינו הקדוש (שחי בדור ראשון לאמוראים), ואם כן אין לומר שזה ביטנית בנו של אבא שאול בן ביטנית, שחי שתי דורות לפני החורבן. אם לא נאמר שיש כאן שיבוש הרי לא ידעתי מיהו ביטנית זה.","cat": "sage"},{"i": 814,"n": "ר' בייתוס","l": "ב","b": "מובא בירושלמי (עירובין פ\"ו ה\"ד). ר' יוסטי בר סימון אמר משמו.","cat": "sage"},{"i": 815,"n": "בייתוס בן זונין א'","l": "ב","b": "תנא בדור השני - השלישי. תלמידו של ר\"ג דיבנה (ירו', פסחים פ\"ב ה\"ד). עשה שדהו מכר, ע\"פ ר\"א בן עזריה (ב\"מ ס\"ג ע\"א). היה עשיר (ירו', ע\"ז פ\"ה ה\"ב).","cat": "sage"},{"i": 816,"n": "בייתוס בן זונין ב'","l": "ב","b": "תנא בדור החמישי (בנו של זונין בר בייתוס ב') שנה לפני רבי (ירו', שבת פ\"ח ה\"ו).","cat": "sage"},{"i": 817,"n": "בינה","l": "ב","b": "פעמים מוחלף עם אבינא.","cat": "sage"},{"i": 818,"n": "רבי בינה","l": "ב","b": "אמורא בבלי בדור השלישי - הרביעי. אמר בשם ר' ירמיה [בר אבא] (ירו', ב\"מ פ\"ו ה\"א). ר' חזקיה אמר משמו (ירו', ע\"ז פ\"ג ה\"ג), ושם - ר' כיני והוא ר' בינה.","cat": "sage"},{"i": 819,"n": "רבי ביסא","l": "ב","b": "אביו של רבי חמא וזקנו של רבי אושעיא מסדר הברייתות. עליהם אמרו: \"והחוט המשולש לא במהרה ינתק\" (ב\"ב נ\"ט ע\"א). הראב\"ד (בהקדמת הרמב\"ם) כתב שהיה מבית דינו של רבי, וזו גם דעתו של הרמב\"ם.","cat": "sage"},{"i": 820,"n": "ר' ביסנא","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. מסר משם ר' אלעאי (ירו', שבת פ\"ב ה\"ו) ורבי חייא בר אבא (תנחומא שמיני). חברו היה ר' אבין (ירו', יבמות פ\"ג ה\"ט).","cat": "sage"},{"i": 821,"n": "בירא","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' אמי (סוכה כ\"ז ע\"א). שמו נשתבש בכמה אופנים. ר' אבא בר כהנא מסר בשמו (ב\"ר פמ\"ז - ה').","cat": "sage"},{"i": 822,"n": "ביראה","l": "ב","b": "מובא בבבלי (סוכה ל\"ד ע\"ב), והוא בירא (ע\"ע).","cat": "sage"},{"i": 823,"n": "ר' בירי","l": "ב","b": "מובא בב\"ר (פמ\"ז - ה'), והוא בירא (ע\"ע).","cat": "sage"},{"i": 824,"n": "ביריי","l": "ב","b": "מובא בירושלמי (תרומות פ\"י ה\"ו), והוא בירא (ע\"ע).","cat": "sage"},{"i": 825,"n": "ביריים","l": "ב","b": "מובא בבבלי (חולין צ\"ח ע\"א), ונראה זהה לבירא (ע\"ע).","cat": "sage"},{"i": 826,"n": "ר' בירייס","l": "ב","b": "אמורא ארץ ישראלי. מסר משום רבי יהושע בן לוי (ב\"ק פ\"ב ע\"א), ואולי הוא ביריים.","cat": "sage"},{"i": 827,"n": "בית אבטינוס","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיו ממונים בבית שני על מעשה הקטורת. היתה להם לשכה מיוחדת למעשה הקטורת (יומא י\"ט ע\"א). מוזכרים לגנאי (יומא ל\"ח - ע\"א) על שלא רצו ללמד על מעשה הקטורת אך גם מוזכרים לשבח (שם), שמעולם לא יצאת כלה מבושמת מבתיהן, שלא יאמרו ממעשה הקטורת מתבסמין.","cat": "sage"},{"i": 828,"n": "בית בייתוס","l": "ב","b": "מובא בבבלי (פסחים נ\"ז ע\"א): \"אמר אבא שאול בן בטנית משום אבא יוסף בן חנין אוי לי מבית בייתוס אוי לי מאלתן\". היו כהנים גדולים בבית שני.","cat": "sage"},{"i": 829,"n": "בית גרמו","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיו ממונים בבית שני על מעשה לחם הפנים. מוזכרים לגנאי (יומא ל\"ח ע\"א) על שלא רצו ללמד על מעשה לחם הפנים וכן מוזכרים (שם) לשבח, ש\"מעולם לא נמצאת פת נקיה ביד בניהם, שלא יאמרו ממעשה לחם הפנים זה ניזונין\".","cat": "sage"},{"i": 830,"n": "ביתוס בר זונין","l": "ב","b": "מובא בתוספתא (סוף פסחים), והוא בייתוס בר זונין.","cat": "sage"},{"i": 831,"n": "בלוויטי","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ערכין י\"א ע\"א): \"בלויטי אמר רבי יוחנן\" - ופרש\"י שהוא שם חכם. בנו הוא חזקיה בר בילוטו (ערכין כ\"ח ע\"ב).","cat": "sage"},{"i": 832,"n": "בלצא","l": "ב","b": "מובא בשמ\"ר (פכ\"ט - מ'), ששאל את ר\"ע מהיכן נעשה הרעש. \"סה\"ד\" מסתפק אם היה חכם.","cat": "sage"},{"i": 833,"n": "בן אבטיח","l": "ב","b": "מובא בבבלי (בכורות ל\"ז ע\"ב). ע\"ע בן בטיח.","cat": "sage"},{"i": 834,"n": "בן אחייה","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית המקדש על הכהנים חולי מעיים. נראה שהיה רופא. יען שהכהנים היו הולכים יחף על הרצפה בעזרה ואוכלים בשר ושותים מים, סבלו ממחלת מעיים (שם בגמ').","cat": "sage"},{"i": 835,"n": "בן אטיטם","l": "ב","b": "מובא בירושלמי (חלה פ\"ד ה\"ה) שהעלה בכורות מבבל בזמן בית המקדש ולא קיבלו ממנו. בבבלי (חלה פ\"ד מי\"א) הגיר': בן אנטינוס. ובמקום אחר (תמורה כ\"א ע\"א): בן אנטיגנוס. \"יוחסין\" כתב (ערך ניתאי איש תקוע) \"כולם חסידים ואנשי מעשה לכן הזכרתים\".","cat": "sage"},{"i": 836,"n": "בן אילם","l": "ב","b": "מובא בירושלמי (מגילה פ\"א ה\"י), והוא יוסף בן אלם.","cat": "sage"},{"i": 837,"n": "בן אלעשה","l": "ב","b": "חתנו של רבי. לא נמנה על החכמים ובר קפרא קנטרו על כך. ורבי שהוקיר את חתנו הגיב על כך ואמר לבר קפרא שלעולם לא יתן לו סמיכה (ירו', מו\"ק רפ\"ג).","cat": "sage"},{"i": 838,"n": "בן אנטיגנוס","l": "ב","b": "מובא בבבלי (תמורה כ\"א ע\"א). ע\"ע בן אטיטם.","cat": "sage"},{"i": 839,"n": "בן אנטינוס","l": "ב","b": "מובא בבבלי (חלה פ\"ד מי\"א). ע\"ע בן אטיטם.","cat": "sage"},{"i": 840,"n": "בן ארזה","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על כלי שיר.","cat": "sage"},{"i": 841,"n": "בן בבי","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על הפתילות להדלקת המנורה.","cat": "sage"},{"i": 842,"n": "בן בג בג","l": "ב","b": "תנא שאין לקבוע במדוייק אם חי בימי הלל או בימי רבי יהושע. פתגמו המפורסם: \"הפוך בה והפוך בה דכולה בה\" (אבות פ\"ה מכ\"ב). תוספות (חגיגה ט' ע\"ב) מביא יש מפרשים שהיה גר. \"יוחסין\" כתב שהוא רבי יוחנן בן בג בג (קידושין י' ע\"ב), שעליו שלח רבי יהודה בן בתירא \"מוחזקני בך שאתה בקי בחדרי תורה\" (שם).","cat": "sage"},{"i": 843,"n": "בן בוהיין","l": "ב","b": "מובא בבבלי (פסחים נ\"ז ע\"א). שם אביו היה בוהיין. ובנו מכונה בן בוהיין. ע\"ע בוהיין.","cat": "sage"},{"i": 844,"n": "בן בוכרי","l": "ב","b": "תנא בדור הראשון - השני. העיד ביבנה וכו' ואמר לו רבן יוחנן בן זכאי וכו' (שקלים פ\"א מ\"ד).","cat": "sage"},{"i": 845,"n": "בן בטיח","l": "ב","b": "בן אחותו של רבן יוחנן בן זכאי ע\"ע אבא סקרא. היה איש גבה קומה ובעל אברים גדולים. מובא במשנה (כלים פי\"ז מי\"ב): \"אגרוף גדול זהו אגרופו של בן בטיח\".","cat": "sage"},{"i": 846,"n": "בן ביבאי","l": "ב","b": "מובא בבבלי (יומא כ\"ג ע\"א), והוא בן בבי.","cat": "sage"},{"i": 847,"n": "בן ביבי","l": "ב","b": "מובא בירושלמי (מע\"ש ספ\"ג), והוא ר' יוסה בן ביבי.","cat": "sage"},{"i": 848,"n": "בן בנו של זכריה בן קבוטל","l": "ב","b": "תנא בדור החמישי. חברו של זכריה בן קבוטל. שמו לא נזכר בש\"ס.","cat": "sage"},{"i": 849,"n": "בן בתירא","l": "ב","b": "מובא בבבלי (שבת ק\"כ ע\"א). סתם בן בתירא הוא רבי יהושע בן בתירא (רמב\"ם בהקדמתו לזרעים). ע\"ע רבי יהודה בן בתירא ב', ר' יהושע בן בתירא ורבי שמעון בן בתירא.","cat": "sage"},{"i": 850,"n": "בן גבר","l": "ב","b": "מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על נעילת שערים.","cat": "sage"},{"i": 851,"n": "בן גמלא","l": "ב","b": "מובא בבבלי (יומא ל\"ז ע\"א), והוא יהושע בן גמלא כהן גדול.","cat": "sage"},{"i": 852,"n": "בן דופאי","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על הלולב.","cat": "sage"},{"i": 853,"n": "בן דורתאי","l": "ב","b": "ע\"ע יהודה בן דורתאי.","cat": "sage"},{"i": 854,"n": "בן דמה","l": "ב","b": "מובא בבבלי (מנחות צ\"ט ע\"ב), והוא אלעזר בן דמה.","cat": "sage"},{"i": 855,"n": "בן הא הא","l": "ב","b": "תנא. מובא באבות (ספ\"ה). ובתוי\"ט מביא בשם הרשב\"ם שמובא במדרש שמואל, שבן הא הא ובן בג בג - היו גרים. וכן כתבו התוספות (חגיגה ט' ע\"ב).","cat": "sage"},{"i": 856,"n": "בן הסגן","l": "ב","b": "מובא בבבלי (יומא מ\"ד ע\"ב), והוא רבי שמעון בן הסגן.","cat": "sage"},{"i": 857,"n": "בן הקפר","l": "ב","b": "מובא (ירו', פ\"ו ה\"א), והוא רבי אלעזר הקפר.","cat": "sage"},{"i": 858,"n": "בן הרכינס","l": "ב","b": "מובא בירושלמי (יבמות פ\"א ה\"ו), והוא רבי דוסא בן הרכינס.","cat": "sage"},{"i": 859,"n": "בן זומא","l": "ב","b": "מובא באבות (רפ\"ד), והוא שמעון בן זומא.","cat": "sage"},{"i": 860,"n": "בן זכאי א'","l": "ב","b": "מובא בבבלי (סנהדרין מ\"א ע\"ב), והוא רבן יוחנן בן זכאי, כשהיה עוד כתלמיד היושב לפני רבו.","cat": "sage"},{"i": 861,"n": "בן זכאי ב'","l": "ב","b": "מובא בבבלי (חולין נ\"ב ע\"א). לגירסת רש\"י: בר זכאי. וגיר' התוס': עולא בן רבי זכאי. ע\"ע עולא בר ר' זכאי.","cat": "sage"},{"i": 862,"n": "בן חכינאי (2)","l": "ב","b": "מובא בבבלי (שבת קמ\"ז ע\"ב), והוא רבי חנניה בן חכינאי.","cat": "sage"},{"i": 863,"n": "בן טוטפת","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על המפתחות.","cat": "sage"},{"i": 864,"n": "בן יאסין","l": "ב","b": "תנא בדור השלישי. מובא בבבלי (יבמות צ\"ח ע\"א). חי בדורו של ר\"ע (שם).","cat": "sage"},{"i": 865,"n": "בן יהוצדק","l": "ב","b": "מובא בירושלמי (סוכה פ\"ה ה\"ד), שבזמן בית שני היה מהחסידים ואנשי מעשה. השתבח בקפיצותיו בשמחת בית השואבה.","cat": "sage"},{"i": 866,"n": "בן כוברי","l": "ב","b": "והוא בן בוכרי.","cat": "sage"},{"i": 867,"n": "בן כוזיבא","l": "ב","b": "מובא בבבלי (יבמות ע\"ב ע\"א). ע\"ע בר כוכבא.","cat": "sage"},{"i": 868,"n": "בן כלבא שבוע","l": "ב","b": "חי בדור חורבן בית שני. היה אחד מעשירי ירושלים (גיטין נ\"ו ע\"א). חותנו של רבי עקיבא (כתובות ס\"ב ע\"ב). לאחר שר\"ע למד והיה גדול בתורה נתן לו מחצית רכושו. (שם ס\"ג ע\"א). במגלת יוחסין בירושלים מצאו, שכתוב בה שהיה מיוצאי חלציו של כלב (ירו', תענית פ\"ד ה\"ב).","cat": "sage"},{"i": 869,"n": "בן מארא","l": "ב","b": "מובא בתנחומא (הישן ריש בהר). ב\"יוחסין\" ו\"סה\"ד\" הגיר': בן מאדא.","cat": "sage"},{"i": 870,"n": "בן מביא יין","l": "ב","b": "מובא בירושלמי (פסחים ספ\"ד), והוא בן בוהיין.","cat": "sage"},{"i": 871,"n": "בן מעדיה","l": "ב","b": "מובא בירושלמי (דמאי פ\"ב ה\"א). ר' יוסי דכפר דן אמר בשמו.","cat": "sage"},{"i": 872,"n": "רבי בן מעדיה","l": "ב","b": "מובא בירושלמי (דמאי פ\"ב ה\"א) ו\"סה\"ד\" גרס (בערך ר' יוסי דכפר דן) \"מערייה\".","cat": "sage"},{"i": 873,"n": "בן מקליט","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על המלח.","cat": "sage"},{"i": 874,"n": "בן נזירא","l": "ב","b": "מובא בירושלמי (שקלים ספ\"ב), ע\"ע בר טירא.","cat": "sage"},{"i": 875,"n": "בן ננס","l": "ב","b": "מובא בבבלי (כתובות צ' ע\"ב). ע\"ע רבי שמעון בן ננס.","cat": "sage"},{"i": 876,"n": "בן סירא","l": "ב","b": "שמו המלא היה יהושע בן סירא. מחכמי ישראל בימי הזוגות. כתב \"ספר בן סירא\" ובו דברי חכמה ומוסר השכל. מובא פעמים רבות בש\"ס: \"כתוב בספר בן סירא\" (חגיגה י\"ג ע\"א ועוד). נראה שספר בן סירא היה הראשון לאחר כתבי הקדש (תוספתא ידים פ\"ה). בכל זאת פסק רב יוסף (סנהדרין ק' ע\"ב), שאף בספר בן סירא אסור לקרוא. כנראה שרש\"י ובעלי התוספות לא קראו בו. רש\"י כתב: \"בדקתי אחר המקרא זה, ואינו בכל הכתובים, ושמא בספר בן סירא הוא\" (עירובין ס\"ה ע\"ב ד\"ה: בצר). ותוס' כתבו: \"אין זה מקרא בכל התורה, ושמא בבן סירא הוא\" (ב\"ק צ\"ב ע\"ב ד\"ה: משולש). ואמנם הפסוקים נמצאים בספר בן סירא.","cat": "sage"},{"i": 877,"n": "בן עזאי","l": "ב","b": "מובא בבבלי (ברכות ס\"ב ע\"א). ע\"ע שמעון בן עזאי.","cat": "sage"},{"i": 878,"n": "בן פדת","l": "ב","b": "הוא רבי אלעזר בן פדת, כמו שכתבו התוספות: \"ואין זה בן פדת, דבן פדת הוא רבי אלעזר בן פדת\" (תמורה י' ע\"א ד\"ה: איתמר).","cat": "sage"},{"i": 879,"n": "בן פזי","l": "ב","b": "מובא בבבלי (חולין מ\"ו ע\"א). מצינו, שעולא \"הוה קאימנא קמיה\" (שם), ונראה שזה רבי שמעון בן פזי.","cat": "sage"},{"i": 880,"n": "בן פטורא","l": "ב","b": "תנא. \"דרש בן פטירא מוטב שישתו שניהם וימותו ואל יראה וכו', עד שבא ר\"ע ולימד\" (ב\"מ ס\"ב ע\"א). מתוך שלא כתוב: \"ור\"ע אומר\", אלא: \"עד שבא ר\"ע\", נראה אולי לומר שחי לפני ר\"ע. \"יתו\"א\" גורס בן פטורין.","cat": "sage"},{"i": 881,"n": "בן פלח","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על העצים.","cat": "sage"},{"i": 882,"n": "בן ציצית הכסת","l": "ב","b": "חי בדור חורבן בית שני. היה אחד משלושת עשירי ירושלים (גיטין נ\"ו ע\"א). נקרא כן על כי ציצתו נגררה על גבי כסתות. ואיכא דאמרי: \"שהיתה כסותו מוטלת בין גדולי רומי\" (שם).","cat": "sage"},{"i": 883,"n": "בן קופיא","l": "ב","b": "חי בדור השלישי של התנאים. ספק אם היה חכם. כשגזרו על ר' יהודה הנחתום שיהרג, רצה בן קופיא להצילו, ונודע למלכות, וגזרו מות גם עליו (מדרש תהלים פ\"ט - ג).","cat": "sage"},{"i": 884,"n": "בן קטין","l": "ב","b": "כהן גדול. מובא במשנה (יומא ל\"ז ע\"א): \"עשה שנים עשר דד לכיור\" (בבית המקדש).","cat": "sage"},{"i": 885,"n": "בן ריפאי","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב). כך הגיר' בתוספתא צוקרמנדל. ולפנינו: בן דופאי.","cat": "sage"},{"i": 886,"n": "בן שלקות","l": "ב","b": "תנא בדור השלישי - הרביעי. בזמנו של ר\"ע, ורבי עקיבא אמר עליו: \"בן שלקות איני מכיר\" (נדה נ\"ב ע\"ב).","cat": "sage"},{"i": 887,"n": "בן תימא","l": "ב","b": "מובא בבבלי (פסחים ע' ע\"א). סביר שהוא ר' יהודה בן תימא (ע\"ע).","cat": "sage"},{"i": 888,"n": "רבי בנאה","l": "ב","b": "בדור המעבר בין התנאים לאמוראים. דבריו עוד נזכרו בברייתא (תענית ז' ע\"א). היה חכם גדול ודיין, והבין רמזים וחידות. המלכות אף מינתה אותו לשופט (ב\"ב נ\"ח ע\"א). רבי יוחנן היה תלמידו (ב\"ב נ\"ח ע\"ב).","cat": "sage"},{"i": 889,"n": "ר' בנאה בריה דר' עולא","l": "ב","b": "מובא בבבלי (פסחים נ\"ד ע\"א). \"סה\"ד\" סובר, שהוא רבינא בריה דר' עולא (ביצה ג' ע\"ב).","cat": "sage"},{"i": 890,"n": "רבי בנאי אחוה דר' חייא בר אבא","l": "ב","b": "מובא בבבלי (כתובות נ' ע\"ב), והוא רבנאי אחוה דר' חייא בר אבא.","cat": "sage"},{"i": 891,"n": "בני בתירא","l": "ב","b": "ע\"ע בן בתירא.","cat": "sage"},{"i": 892,"n": "בני רחבה","l": "ב","b": "מובא בבבלי (סנהדרין כ\"ו ע\"א), והם עיפא בן רחבא מפומבדיתא ואבימי (ע\"ע).","cat": "sage"},{"i": 893,"n": "ר' בניי","l": "ב","b": "אמורא, כנראה ארץ ישראלי, שאין לקבוע זמנו המדוייק. אמר בשם שמואל (ירו', סנהדרין ספ\"ג). ור' תנחומא מסר משמו (ב\"ר רפ\"ח). ע\"ע ר' בנייה.","cat": "sage"},{"i": 894,"n": "ר' בנייה","l": "ב","b": "אמורא שמסר בשם ר\"ה (פדר\"כ כ\"ד), ואולי הוא ר' בניי.","cat": "sage"},{"i": 895,"n": "בנימין (2)","l": "ב","b": "מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על תנורים.","cat": "sage"},{"i": 896,"n": "רבי בנימין","l": "ב","b": "תנא בדור הרביעי. מתלמידי רבי עקיבא ומסר בשמו (שמחות רפ\"ט). חלק עם רבי אלעזר [בן שמוע] (כתובות פ\"ד ע\"א).","cat": "sage"},{"i": 897,"n": "בנימין בר איהי","l": "ב","b": "ע\"ע מנימין בר איהי.","cat": "sage"},{"i": 898,"n": "בנימין בר אשתור","l": "ב","b": "אמורא בדור השלישי - הרביעי. תלמידו של רבי חייא בר אבא (ירו', בכורים פ\"א ה\"ד). \"פני משה\" כתב (שם) ש\"היה מבני גרים\".","cat": "sage"},{"i": 899,"n": "רבי בנימין בר גידל","l": "ב","b": "אמורא בדור הרביעי. הוא ור' אחא חלקו בדברי ר' יוסי בר חנינא (ירו', יבמות רפ\"א). מסר בשם רבי יוחנן (חולין קכ\"ה ע\"א).","cat": "sage"},{"i": 900,"n": "ר' בנימין בר חייא","l": "ב","b": "מובא בבבלי (סוף ר\"ה): \"אבא בריה דרב בנימין בר חייא\".","cat": "sage"},{"i": 901,"n": "בנימין בר יפת","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ברכות ל\"ח ע\"ב). ר\"ז אמר עליו, שאינו מדייק בשמועותיו כמו רב חייא בר אבא (שם). מסר בשם רבי אלעזר (יומא כ\"ט ע\"א).","cat": "sage"},{"i": 902,"n": "רבי בנימין בר לוי","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אמי (ירו', פאה רפ\"א). רבין אמר בשמו (ירו', פסחים פ\"ז ה\"ו).","cat": "sage"},{"i": 903,"n": "בנימין גנוביא (2)","l": "ב","b": "לפי גירסת ה\"יוחסין\" ו\"סה\"ד\", מובא בשם רב - דין מוטעה, ושמואל שמע - ואיקפיד, ומת בנימין, וקרא עליו: \"ברוך שנגפו\" (ירו', ברכות פ\"ב ה\"ו).","cat": "sage"},{"i": 904,"n": "בנימין גר מצרי","l": "ב","b": "מובא (ירו', יבמות פ\"ח ה\"ב), והוא מנימין גר מצרי.","cat": "sage"},{"i": 905,"n": "בנימין הצדיק","l": "ב","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (ב\"ב י\"א ע\"א), שהיה ממונה על קופה של צדקה. פעם פרנס אשה משלו, וכשנטה למות הוסיפו לו 22 שנה על שנותיו (שם). \"סה\"ד\" כתב שמקום מנוחתו בעיר רומי.","cat": "sage"},{"i": 906,"n": "בנימין רעיא","l": "ב","b": "חי בזמנו של רב. מובא בבבלי (ברכות מ' ע\"ב): \"כרך ריפתא ואמר: 'בריך מריה דהאי פיתא', אמר רב...\" גיר' \"יוחסין\": רבא. אין הכרעה מוחלטת שהיה אמורא.","cat": "sage"},{"i": 907,"n": "בנן של קדושים","l": "ב","b": "ע\"ע רבי מנחם ברבי סימאי.","cat": "sage"},{"i": 908,"n": "ר' בצלאל","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי. רבי ברכיה אמר בשמו (שהש\"ר ספ\"ג). ונראה שצ\"ל כן בבמד\"ר (פי\"ב - ח') ושם ר' בצלה.","cat": "sage"},{"i": 909,"n": "בר אבוה","l": "ב","b": "שכנו של אביי. ואביי היה מברך (ברכת מאורי האש בהבדלה) אדבי בר אבוה (ברכות נ\"ג ע\"ב). אין לדעת אם היה חכם.","cat": "sage"},{"i": 910,"n": "בר אבין","l": "ב","b": "דרשן וספדן. האריך ימים, שהרי מצינו אותו דורש בפני רבא (מו\"ק כ\"ה ע\"ב), והוא וחברו בר קיפוץ היו ספדנים בימי רב אשי (שם). נענש ע\"י רב אשי ונהפכו רגליו (שם).","cat": "sage"},{"i": 911,"n": "בר אדא בר אחוה דר' יהודה","l": "ב","b": "אמורא בבלי בדור השלישי. ר' זירא אמר משמו (ירו', בכורים פ\"א ה\"ה).","cat": "sage"},{"i": 912,"n": "בר אדא מרי","l": "ב","b": "אמורא בבלי בדור השלישי. מובא בבבלי (זבחים ל\"ח ע\"א): \"אמר רבא: 'בר אדא מרי אסברה לי'\".","cat": "sage"},{"i": 913,"n": "בר אדא משחאה","l": "ב","b": "נראה שהוא רב אדא משוחאה (ע\"ע).","cat": "sage"},{"i": 914,"n": "בר אדא סבולאה","l": "ב","b": "חי בבבל בדור החמישי לאמוראים. היה לו דין תורה בפני רב פפא (ב\"מ צ\"ג ע\"ב). \"סה\"ד\" כתב: \"לא ידעתי אם חכם היה\".","cat": "sage"},{"i": 915,"n": "בר אהינא","l": "ב","b": "אמורא בבלי בדור השלישי. היה מרבותיו של רבא: \"אמר רבא: 'בר אהיני אסברא לי'\" (סוטה ל\"ט ע\"ב). אפשר שהוא רבא בר אהיני (מנחות ל\"ז ע\"ב), ושם מובאת דעתו אחרת מר' יוסף.","cat": "sage"},{"i": 916,"n": "בר אושפזתי","l": "ב","b": "מובא בבבלי (תענית כ\"ד ע\"ב), והוא רב פפא. גירסתו של \"הערוך\": אושפרתי, וזה שם אמו של רב פפא.","cat": "sage"},{"i": 917,"n": "בר אלנתן","l": "ב","b": "מובא באיכ\"ר (בפתיחתא).","cat": "sage"},{"i": 918,"n": "בר ביבי בר גידל","l": "ב","b": "אמורא בבלי בדור השני - השלישי. תלמידו של ר' שמעון חסידא (ב\"ק קי\"ג ע\"ב).","cat": "sage"},{"i": 919,"n": "בר הדיא","l": "ב","b": "פותר חלומות שחי בזמן אביי ורבא. לאביי, שנתן לו כסף, פתר טוב: ולרבא שלא נתן לו כסף, פתר רע: פתרונותיו התגשמו ורבא כינהו: \"רשע\" (ברכות נ\"ו ע\"א). אין להעלות על הדעת שהיה חכם.","cat": "sage"},{"i": 920,"n": "בר הדיא א'","l": "ב","b": "אמורא בדור השלישי - הרביעי. תלמידו של רבי אמי (חולין ק\"ו ע\"ב). אביי הקשה על דבריו (מו\"ק י\"ח ע\"א). אין זה בר הדיא פותר החלומות שרבא כינהו: \"רשע\" (ברכות נ\"ו ע\"א).","cat": "sage"},{"i": 921,"n": "בר הי הי","l": "ב","b": "תנא בדור הראשון. שאל את הלל (חגיגה ט' ע\"ב). זכה לגילוי אליהו הנביא (שם). תוספות כתבו: \"ויש מפרשים שגר היה\" (שם). היימן כתב (ע' 582 ערך בר הא הא) שהלל זה הוא אמורא, ולא הלל הזקן, וא\"כ הפך את בר הי הי מתנא בדור הראשון, לאמורא.","cat": "sage"},{"i": 922,"n": "בר הידיא","l": "ב","b": "מובא בבבלי (מו\"ק י\"ח ע\"ב), והוא בר הדיא. כן גירסת הר\"ח.","cat": "sage"},{"i": 923,"n": "בר הינך","l": "ב","b": "מובא בבבלי (פסחים ק\"א ע\"ב). ע\"ע רב הינך.","cat": "sage"},{"i": 924,"n": "בר המדודי","l": "ב","b": "ע\"ע בר המדורי.","cat": "sage"},{"i": 925,"n": "בר המדורי","l": "ב","b": "אמורא בבלי בדור השלישי. תלמידו של שמואל (יומא פ\"ז ע\"ב). האריך ימים והיה רבו של רבא (שבת ק\"ז סע\"ב).","cat": "sage"},{"i": 926,"n": "בר זעירא","l": "ב","b": "מובא במדרש שמואל (פי\"ז) וצ\"ל רבי זירא.","cat": "sage"},{"i": 927,"n": "בר חבו","l": "ב","b": "כותב תפילין בזמנו של אביי (מגילה י\"ח ע\"ב: וב\"מ כ\"ט ע\"ב). אין להכריע שהיה חכם.","cat": "sage"},{"i": 928,"n": "בר חוטא","l": "ב","b": "מובא בשהש\"ר (פ\"ה - ד'), ואולי צ\"ל: בר חטייא.","cat": "sage"},{"i": 929,"n": "בר חוניא","l": "ב","b": "מובא (משלי פכ\"ב - ב'), ואולי צ\"ל: בר חטייא.","cat": "sage"},{"i": 930,"n": "בר חטייא (2)","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מובא מספר פעמים בב\"ר. פעם מובא בב\"ר שמו המלא: \"שמעון בר חוטא\" (פכ\"ו - ג'). רבי עזריה (תלמידו של רבי מנא) מסר בשמו (שם נ\"ג - י\"ב).","cat": "sage"},{"i": 931,"n": "בר טברי (2)","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל את רבי יצחק (ירו', מגילה פ\"ד ה\"י).","cat": "sage"},{"i": 932,"n": "בר טירא","l": "ב","b": "אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי (מו\"ק פ\"ג ה\"ז). וגירסא אחרת מצאנו לאותו ענין: ר' שמעון בר נזירא (ירו', שקלים פ\"ב ה\"ה). ובבבלי: \"אמר ר' יצחק בר זעירא, ואיתימא שמעון נזירא\" (יבמות צ\"ז ע\"א), ונראה שאחד הוא.","cat": "sage"},{"i": 933,"n": "בר יודני","l": "ב","b": "מובא בירושלמי (תרומות פ\"ח דפוס ווינציא), וצ\"ל: בר נטיזא.","cat": "sage"},{"i": 934,"n": "בר ינטה","l": "ב","b": "מובא בירושלמי (תענית פ\"ד ה\"ה).","cat": "sage"},{"i": 935,"n": "בר ישיטה","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של ר' חיננא (ירו', מגילה פ\"ד ה\"י). היה אמורא של ר' אבהו (שם).","cat": "sage"},{"i": 936,"n": "בר כדה","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי: \"בר כרה (צ\"ל כדה) אמר רבי אבהו\". (פאה פ\"ז ה\"ב).","cat": "sage"},{"i": 937,"n": "בר כוזבה","l": "ב","b": "מובא בירושלמי (תענית פ\"ד ה\"ה). ע\"ע בר כוכבא.","cat": "sage"},{"i": 938,"n": "בר כוכבא","l": "ב","b": "חי בדור השלישי לתנאים. רבי עקיבא אמר עליו שהוא משיח, ודרש עליו: \"דרך כוכב מיעקב\" (ירו', תענית פ\"ד ה\"ה). מלך שלוש וחצי שנים. עמד בראש מרד ביתר. מספר חייליו היה ארבע מאות אלף. מאתיים אלף מהם קטעו לעצמם בוהן כאות לאומץ לב, ומאתיים אלף האחרים - עקרו עץ ברכיבה על סוס (שם). שלוש וחצי שנים צר אדריינוס על ביתר עד שנפלה. בר כוכבא נהרג ע\"י נחש ואדריינוס אמר עליו, שאילולי אלקים הרגו מי יכול להרגו (שם). סיבת נפילת ביתר לפי המסופר (שם) היתה, שבר כוכבא הרג את דודו התנא רבי אליעזר המודעי בגלל חשד שוא, שרצה להסגיר את ביתר לאדריינוס.","cat": "sage"},{"i": 939,"n": "בר כרא","l": "ב","b": "הוא בר כדה.","cat": "sage"},{"i": 940,"n": "בר לוליתא","l": "ב","b": "אמורא ארץ ישראלי בדור השני. תלמידו של רבי חייא (ירו', חלה פ\"ב ה\"ג). מסר בשם רבי יהושע בן לוי (שם).","cat": "sage"},{"i": 941,"n": "בר ליואי א'","l": "ב","b": "מובא בבבלי (כתובות ע\"ז ע\"ב), והוא רבי יהושע בן לוי.","cat": "sage"},{"i": 942,"n": "בר ליואי ב'","l": "ב","b": "אמורא בבלי בדור השני. תלמידו של מר עוקבא (שבת ק\"ח ע\"ב). אין זה בר ליואי הידוע, שהוא רבי יהושע בן לוי (ע\"ע).","cat": "sage"},{"i": 943,"n": "בר לקיש","l": "ב","b": "מובא בבבלי (מגילה כ\"ח ע\"ב). ע\"ע רבי שמעון בן לקיש.","cat": "sage"},{"i": 944,"n": "בר מריון","l": "ב","b": "חי בבבל בדור הרביעי לאמוראים, היה עשיר גדול ובא לברר דין לפני אביי (ב\"מ כ\"ד ע\"ב). גם בניו היו עשירים (ב\"ב ח' ע\"א). אין ראיה שנמנה עם החכמים.","cat": "sage"},{"i": 945,"n": "בר מרינא","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. בירך על הפת לפני ר\"ז ור' חייא בר אבא (ירו', ברכות פ\"ו ה\"א). שאל מרבי אמי (ירו', שבת רפי\"ט).","cat": "sage"},{"i": 946,"n": "בר נטוזא","l": "ב","b": "מובא בירושלמי (תרומות פ\"ח), וצ\"ל: בר נטיזא.","cat": "sage"},{"i": 947,"n": "בר נטיזא","l": "ב","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר' אבא בר ממל (ירו', ע\"ז פ\"ב ה\"ג).","cat": "sage"},{"i": 948,"n": "בר נפחא","l": "ב","b": "והוא רבי יוחנן, כך פירש רש\"י (סנהדרין צ\"ו ע\"א). ומכונה כך על שם יופיו.","cat": "sage"},{"i": 949,"n": "בר נתן","l": "ב","b": "מובא בבבלי (מו\"ק כ\"ח ע\"א), והוא רב הונא בר נתן (כמוכח גיטין נ\"ט ע\"א תד\"ה: והא).","cat": "sage"},{"i": 950,"n": "בר נתן אסיא","l": "ב","b": "כך גירסת בעל \"יתו\"א\", ולפנינו: רב נתן בר אסיא (פסחים נ\"ב ע\"א).","cat": "sage"},{"i": 951,"n": "בר סירא","l": "ב","b": "מובא בירושלמי (חגיגה פ\"ב ה\"א), והוא בן סירא.","cat": "sage"},{"i": 952,"n": "בר עולא","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. ר' יונה ור' יוסי שאלו ממנו (ירו', שבת פ\"ד ה\"ב).","cat": "sage"},{"i": 953,"n": "בר עיטיין","l": "ב","b": "מובא בירושלמי: \"ר' יסא בשם רבנין וכו' מבי מדרשא דבר עיטיין\" (ב\"ב פ\"ו ה\"א).","cat": "sage"},{"i": 954,"n": "בר פאטי","l": "ב","b": "מובא במסכת סופרים (פי\"ב). ע\"ע לוי בר בוטי.","cat": "sage"},{"i": 955,"n": "בר פדא","l": "ב","b": "אמורא ארץ ישראלי בדור הראשון. בן אחותו ותלמידו של בר קפרא (מעילה ד' ע\"ב). שמו שובש בכמה פנים: בר פדייה, ר' פדיה, והוא רבי יהודה בן פדייה. היה מרבותיו של אילפא: \"אילפא אמרה קמיה דרב פדא\" (זבחים י\"ג ע\"ב), וכן היה רבו דרבי יוחנן (ירו', שבת פ\"א ה\"ב). תוספות כתבו: \"זהו בר פדא בן אחותו של בר קפרא\" (תמורה י' ע\"א ד\"ה: איתמר בר פדא).","cat": "sage"},{"i": 956,"n": "בר פדייה","l": "ב","b": "הוא בר פדא.","cat": "sage"},{"i": 957,"n": "בר פחתי","l": "ב","b": "כך קרא רבי חייא לרב (שבת ג' ע\"ב) ופרש\"י: \"בן גדולים\".","cat": "sage"},{"i": 958,"n": "בר פיולי","l": "ב","b": "מנקר בזמן שמואל ועמד לפני שמואל וניקר (חולין צ\"ו ע\"א), ואין הוכחה שנמנה עם החכמים.","cat": "sage"},{"i": 959,"n": "בר פיקא","l": "ב","b": "מובא בירושלמי ששאל לרבי וכו', א\"ל רבי: \"בר פיקא עומד בשטותו\" (נזיר פ\"ט ה\"ב). אין להכריע לאיזה רבי הכונה שכן כל הנשיאים מרבי ואילך מכונים לעתים בירושלמי: \"רבי\" (סיווגתיו לרבי הראשון והוא רבינו הקדוש).","cat": "sage"},{"i": 960,"n": "בר פתייא","l": "ב","b": "הוא בר פדא.","cat": "sage"},{"i": 961,"n": "בר קזא","l": "ב","b": "מובא בבבלי (כתובות ק\"ד ע\"א): \"אר\"נ בר יצחק: תני רב יהודה בר קזא במתניתא דבי בר קזא\" פרש\"י \"שם חכם\".","cat": "sage"},{"i": 962,"n": "בר קיפוף","l": "ב","b": "ספדן שחי בדור הרביעי לאמוראי בבל והאריך ימים עד ימי רב אשי, ונענש מפני שבגללו חלשה דעתו דרב אשי (מו\"ק כ\"ה ע\"ב) אין ראיה כי נמנה עם החכמים.","cat": "sage"},{"i": 963,"n": "רבי בר קיריא","l": "ב","b": "כן הגיר' בירושלמי (כלאים פ\"ט ה\"ג). יש גורסים: רבה בר קיריא (שם), ובפס' רבתי (פ' דשבת ור\"ח - ו') הגיר': ר' ברוקאי.","cat": "sage"},{"i": 964,"n": "בר קפרא","l": "ב","b": "תנא בדור המעבר בין התנאים לאמוראים. תלמידו של רבי (יבמות ל\"ב ע\"ב). לדעת הרמב\"ם (בהקדמתו לזרעים) היה מבית דינו של רבי. רבי עצמו שאל ממנו (פסחים מ\"ב ע\"א). היה חברו של רבי חייא (יבמות שם) ושל חזקיה בנו של ר' חייא, ועל שניהם - חזקיה ובר קפרא - אומרים התוספות שהיו תנאים (ע\"ז ל\"ח ע\"ב). גדולי דור הראשון לאמוראי א\"י קיבלו ממנו. על רבי אושעיא נאמר מפורש שהיה תלמידו (מו\"ק כ\"ד ע\"א). רבי יהושע בן לוי מסר משמו (ברכות ל\"ד ע\"א), וכן ר\"ל (פסחים ט\"ו ע\"א). קיבץ הלכות שנקראו \"משנת בר קפרא\" (ב\"ב קנ\"ד ע\"ב). פעם העליב את חתנו של רבי, ורבי הקפיד עליו ואמר לו: \"איני מכירך רבי [שלא יסמכהו]\" (ירו', מו\"ק רפ\"ג). היה בפטירתו של רבי וקרע בגדיו ואמר: \"אראלים ומצוקים אחזו בארון הקודש וכו' ונשבה ארון הקודש\" (כתובות ק\"ד ע\"א). היה גם דרשן ובעל משלים וחידות (נדרים נ\"א ע\"א, ויק\"ר כ\"ח - ב'). הגיע לזקנה (ברכות ל\"ט ע\"א), וכאשר כעס על שני תלמידיו אמר להם על עצמו: \"אם חכמה אין כאן, זקנה אין כאן\", פרש\"י: \"והלא זקן אני\". ולא יתכן לפרש זקן נסמך, כי לא נסמך מעולם (ירו', מו\"ק רפ\"ג).","cat": "sage"},{"i": 965,"n": "בר רב זביד אחוה דר\"ש בר ר' זביד","l": "ב","b": "מובא בבבלי (ברכות ל\"ח ע\"א). ע\"ע רב זביד אבוה דר' שמעון בר זביד.","cat": "sage"},{"i": 966,"n": "בר רחומי","l": "ב","b": "מובא בבבלי (נזיר י\"ג ע\"א) ששאל מאביי. ע\"ע רב רחומי א'.","cat": "sage"},{"i": 967,"n": "רב בר שבא","l": "ב","b": "אמורא בבלי בדור החמישי. נראה שהאריך ימים, שכן היה בביתו של רב נחמן בהיותו תלמיד (חולין קי\"א ע\"א) וסירב לאכול ורב נחמן הורה להלעיטו בעל כורחו, שאל מרב פפא (עירובין ל\"ג ע\"ב), ושקיל וטרי עם רב כהנא [רבו של רב אשי], (מו\"ק כ\"ו ע\"א). ואיקלע לגבי רבינא, ורבינא לא הפסיק ב\"הלל\" לשאול בשלומו, שכן שלא היה חשוב לגביו (ברכות י\"ד ע\"א). \"דק\"ס\" גרס בברכות: \"רבא בר שבא\" (תלמידו של רבינא).","cat": "sage"},{"i": 968,"n": "בר שלמיא ספרא","l": "ב","b": "סופר בארץ ישראל בדור הששי לאמוראים. שאל מרבי מנא, שאמר על השאלה, שיש להסתפק בה הרבה (ירו', תענית פ\"ד ה\"א).","cat": "sage"},{"i": 969,"n": "בר שפיר","l": "ב","b": "כך גירסת יחוסי תנאים ואמוראים ולפנינו הגירסא רב שפיר (מו\"ק י\"א ע\"א).","cat": "sage"},{"i": 970,"n": "רב בר שרביא","l": "ב","b": "אמורא בבלי בדור הששי. היה לו דין תורה לפני רב פפא, ו\"דק\"ס\" גרס רב בר שבא (שבועות ל' ע\"ב).","cat": "sage"},{"i": 971,"n": "בר תוטני","l": "ב","b": "אמורא ארץ ישראלי בדור הראשון. ר\"ל מסר משמו (שבת ע\"א ע\"א).","cat": "sage"},{"i": 972,"n": "ברדלא","l": "ב","b": "מובא בבבלי (מכות י\"ד ע\"ב): \"אמר רבי יוחנן: 'תני ברדלא'\", ופרש\"י: \"שם חכם\".","cat": "sage"},{"i": 973,"n": "רב ברדלא בר טביומי","l": "ב","b": "אמורא בבלי בדור השני. תלמידו של רב (חגיגה ה' ע\"א).","cat": "sage"},{"i": 974,"n": "ברוך רבו דרבי יהודה בר אלעאי","l": "ב","b": "מובא בירושלמי (תענית פ\"ד ה\"ה): \"תני א\"ר יהודה בן ר' אלעאי ברוך ר' היה דורש\", ולי נראה שיש כאן איזה ט\"ס ולא ידעתי מהו כי לא מצינו לרבי יהודה התנא רבי ושמו ברוך.","cat": "sage"},{"i": 975,"n": "רב ברונא","l": "ב","b": "אמורא בבלי בדור השני. תלמידו המובהק של רב (פסחים ק\"ג ע\"א). כן קיבל משמואל (עירובין ע\"ד ע\"א). חברם של רב חננאל (פסחים שם) ושל רבי אלעזר (ברכות ט' ע\"ב, לגיר' \"דק\"ס\" ו\"סה\"ד\"). מצינו אותו עם רב יהודה (עירובין ס' ע\"א). ר' טבלא אמר בשמו (סנהדרין כ\"ח ע\"ב). רבי אלעאי שלח מארץ ישראל לשאול בשלומו וקרא לו \"אחי\" (ברכות ט' ע\"ב).","cat": "sage"},{"i": 976,"n": "ר' ברוקא","l": "ב","b": "מובא בזהר חדש (בראשית פ' ויטע).","cat": "sage"},{"i": 977,"n": "ר' ברוקא חוזאה","l": "ב","b": "מובא בבבלי (תענית כ\"ב ע\"א), שאליהו הנביא היה שכיח אצלו.","cat": "sage"},{"i": 978,"n": "ר' ברוקאי","l": "ב","b": "אמורא ארץ ישראלי בדור השני. חברו של רבי אלעזר בן פדת (פס' רבתי פ' דשבת ור\"ח - ו'). אבל בירושלמי הגירסא: רבי בר קיריא (כלאים פ\"ט ה\"ג), ויש גורסים: רבה בר קיריא.","cat": "sage"},{"i": 979,"n": "ברוריה","l": "ב","b": "אשה חכמה ומלומדת בדור הרביעי של התנאים. בתו של התנא רבי חנניה בן תרדיון, שנהרג על קידוש ה', ואשתו של התנא המפורסם רבי מאיר (ע\"ז י\"ח ע\"א). אשה יחידה שהשתתפה במשא ומתן הלכתי עם התנאים. שמה מובא בשני התלמודים כאחד התנאים. ר' יהודה מכריע כדעתה: \"יפה אמרה ברוריא\" (ריש תוספתא כלים לפי גיר' אור הגנוז). בס' \"כריתות\" (לשון לימודים שער ב' ס' צ\"ג) נאמר: \"בת ר' חנינא בן תרדיון חולקת עם אביה והלכה כדבריה\". היתה לומדת כל יום שלוש מאות הלכות (פסחים ס\"ב ע\"ב). שני בניה מתו בחייה, בשבת (מדרש משלי פרק ל\"א). במסכת ע\"ז (י\"ח ע\"ב עיין שם רש\"י) מסופר: \"פעם אחת ליגלגה על שאמרו חכמים: 'נשים דעתן קלות', וציוה [ר\"מ] לאחד מתלמידיו לנסותה לדבר עבירה, והפציר בה ימים רבים עד שנתרצית, וכשנודע לה חנקה עצמה\".","cat": "sage"},{"i": 980,"n": "בריבי (2)","l": "ב","b": "תנא דברייתא ששמו בריבי. \"תנא, בריבי אומר: 'לא הרגו'\" (מכות ה' ע\"ב), ופרש\"י: \"כך היה שמו\", וכן פרש\"י: \"שם חכם\" (חולין נ\"ב ע\"ב). ל\"בריבי\" משמעות נוספת והיא גדול הדור, וכאשר כתוב: \"ר' יהודה בריבי אומר\", או \"אחאי בריבי\", המשמעות היא תיאור גדולתו (ע\"ע בריבי). במקום אחר מפקפק רש\"י בד\"ה: \"התניא בריבי אומר: 'לא ידעינון מנו אלא אחד גדול בדור היה וכו'\" (חולין י\"א ע\"ב).","cat": "sage"},{"i": 981,"n": "בריה דרב אידי בר אבין","l": "ב","b": "אמורא בבלי בדור החמישי. מובא בבבלי: \"רב פפא ורב הונא בריה דרב יהושע איקלעי לבי בריה דרב אידי בר אבין, ועביד להו עיגלא תילתא\" (שבת קל\"ו ע\"א).","cat": "sage"},{"i": 982,"n": "בריה דרב זוטרא בריה דרב זירא","l": "ב","b": "ע\"ע בריה דרב זוטרא בריה דרב זעירא.","cat": "sage"},{"i": 983,"n": "בריה דרב זוטרא בריה דרב זעירא","l": "ב","b": "מובא בבבלי (נדרים ע\"ז ע\"א). אביו רב זוטרא ואבי אביו רב זעירא לא מובאים שוב בש\"ס, ואין מהם תורה או מימרא כלשהי. ובמקום אחר (שבת קנ\"ז ע\"א) הגיר' זירא במקום זעירא.","cat": "sage"},{"i": 984,"n": "רב בריה דשמואל","l": "ב","b": "אמורא בבלי בדור השני. מסר בשם שמואל (מד' תהלים רפ\"ט). \"סה\"ד\" שיבש השם וכתב שצ\"ל: רבה בר שמואל. \"סה\"ד\" ו\"יוחסין\" סוברים שרבה בר שמואל היה בנו של שמואל.","cat": "sage"},{"i": 985,"n": "רבי ברייס","l": "ב","b": "אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"ר' תנחום ור' ברייס אמרו משום זקן אחד, ומנו: ר' יהושע בן לוי\" (ב\"ק פ\"ב ע\"א).","cat": "sage"},{"i": 986,"n": "רבי ברכיה","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. מגדולי בעלי האגדה. רבו המובהק היה רבי חלבו (ירו', כלאים פ\"ט ה\"ג): בשמו מסר את רוב מאמרי האגדה, וכן מסר מכל גדולי הדור ובשם אביו (תנחומא בובר חיי שרה ו'). ושניהם יחד מוסרים דברי אגדה (ויק\"ר ל' א'). נראה שאולי אביו הוא ר' חמא (לגיר' \"סה\"ד\") או ר' חייא. ר' מנא, מגדולי הדור הרביעי, קרא לו: \"רבי\" (ירו', יבמות פ\"ד הי\"א). אחיו, רבי שמואל היה מחכמי ההלכה (ירו', ערלה רפ\"ב). כן נזכר בן בתו של ר' ברכיה (ב\"ר פ\"ט - ה').","cat": "sage"},{"i": 987,"n": "ר' ברכיה בר אבא בר כהנא","l": "ב","b": "מובא בבמד\"ר (פ\"ט - מ\"ח), ונראה שהוא ט\"ס, כי המקור בירושלמי, ושם: \"ר' ברכיה [בשם] ר' אבא בר כהנא\" (סוטה פ\"ג ה\"ד).","cat": "sage"},{"i": 988,"n": "ר' ברכיה בר אבוה","l": "ב","b": "מובא ב\"ילקוט\" (הושע רמז תקכח). ואולי צ\"ל: ר' ברכיה [בשם] ר' אבהו.","cat": "sage"},{"i": 989,"n": "ר' ברכיה בר חייא הכהן","l": "ב","b": "מובא בויק\"ר (רפ\"ל). גיר' \"יוחסין\" ו\"סה\"ד\": חמא במקום חייא (אולי משני יודין נעשה מ\"ם). יש סבורים שזה רבי ברכיה המפורסם באגדה (ע\"ע).","cat": "sage"},{"i": 990,"n": "ר' ברכיה בר חמא הכהן","l": "ב","b": "ויש גור': ר' ברכיה בר חייא הכהן (ע\"ע). ויש סבורים שזה רבי ברכיה המפורסם באגדה (ע\"ע).","cat": "sage"},{"i": 991,"n": "ר' ברכיה בר חנינא בר איקא","l": "ב","b": "מובא במדרש תהלים (פע\"ח - י\"א).","cat": "sage"},{"i": 992,"n": "ר' ברכיה בר יהודה ב\"ר סימון","l": "ב","b": "מובא בב\"ר (פנ\"ג - ח).","cat": "sage"},{"i": 993,"n": "ר' ברכיה בר יעקב בר בת יעקב","l": "ב","b": "מובא בירושלמי (מע\"ש פ\"ה ה\"א), וצ\"ל: ר' ברכיה יעקב (ולא בר יעקב). והמשמעות: ר' ברכיה [בשם] יעקב בר בת יעקב, כמובא בירושלמי (מו\"ק פ\"א ה\"ב).","cat": "sage"},{"i": 994,"n": "ר' ברכיה בר יצחק","l": "ב","b": "מובא במדרש שמואל (פ\"כ - ז'), וכן מובא בתוספות (סוטה מ\"ב ע\"ב ד\"ה: מאה). הגיר' ברו\"ר (פ\"ב - כ): ר' ברכיה בשם ר' יצחק.","cat": "sage"},{"i": 995,"n": "ר' ברכיה בר סימון","l": "ב","b": "מובא בקה\"ר (פ\"י - ז').","cat": "sage"},{"i": 996,"n": "ר' ברכיה בר' חלבו","l": "ב","b": "מובא בויק\"ר (פל\"ו - ו'): \"אמר בשם רבה בר זבדא\", ו\"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: ר' ברכיה ור' חלבו, דבהרבה מקומות נזכרים יחד\" עכ\"ל. ואולי צ\"ל: ר' ברכיה בשם ר' חלבו, שכן היה רבו המובהק.","cat": "sage"},{"i": 997,"n": "ר' ברכיה הכהן (2)","l": "ב","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם ר' חלבו (תנחומא וארא כ\"ב).","cat": "sage"},{"i": 998,"n": "ר' ברכיה סבא","l": "ב","b": "מובא בויק\"ר (פ\"א - ד'), שר' אבין אמר בשמו.","cat": "sage"},{"i": 999,"n": "ברקא","l": "ב","b": "כך גורס \"יחוסי תנאים ואמוראים\", ולפנינו הגיר': רבי בורקי.","cat": "sage"},{"i": 1000,"n": "בתא","l": "ב","b": "מובא בבבלי (תמורה כ\"ט ע\"א), וכן הגיר' \"כפתור ופרח\" וה\"יוחסין\", ולפנינו: בהא.","cat": "sage"},{"i": 1001,"n": "בתירא","l": "ב","b": "ע\"ע רבי יהודה בן בתירא ב', ר' יהושע בן בתירא, רבי יוחנן בן בתירא, ר' יונתן בן בתירא ורבי שמעון בן בתירא.","cat": "sage"},{"i": 1002,"n": "גביהא בן פסיסא","l": "ג","b": "חי בתקופת בית המקדש, בזמנו של שמעון הצדיק. ליוה את המלך אלכסנדר מוקדון בביקורו בבית המקדש (מגילת תענית פ\"ג). היה חכם גדול, ובויכוחים שהיו לו עם אלכסנדר מוקדון ובני אפריקה, מצרים וישמעאל, ניצח את כולם (סנהדרין צ\"א ע\"א).","cat": "sage"},{"i": 1003,"n": "רב גביהא מארגיזא","l": "ג","b": "אמורא בבלי בדור הששי. רב הונא בר נתן, ראש הגולה, מסר לרב אשי בשמו (גיטין ז' ע\"א).","cat": "sage"},{"i": 1004,"n": "רב גביהה מבי כתיל","l": "ג","b": "אמורא בבלי בדור הששי. עמד בראש ישיבת פומבדיתא, בשנים ד\"א קע\"ט - קצ\"ג (914 - 334) (\"אגרת רב שרירא גאון\"). היה כפוף לרבא (ע\"ז כ\"ב ע\"א). חברם של רב אשי ואמימר (ביצה כ\"ג ע\"א). נראה שנטל חלק בעריכת הש\"ס עם רב אשי (יבמות ס' ע\"א).","cat": "sage"},{"i": 1005,"n": "גבילה","l": "ג","b": "מובא בירושלמי (נזיר פ\"ז ה\"א), ע\"ע מגבילה.","cat": "sage"},{"i": 1006,"n": "גביני","l": "ג","b": "מובא במשנה (שקלים רפ\"ה), שהיה ממונה במקדש להכריז, וקולו נשמע עד למרחק ג' פרסאות, ואגריפס המלך נתן לו על כך מתנות (יומא כ' ע\"ב).","cat": "sage"},{"i": 1007,"n": "גביעה בן קוסם","l": "ג","b": "מובא בב\"ר (ספס\"א), והוא גביהא בן פסיסא.","cat": "sage"},{"i": 1008,"n": "רב גדא","l": "ג","b": "אמורא בבלי בדור השלישי. היה שמשו של רב ששת (עירובין י\"א ע\"ב).","cat": "sage"},{"i": 1009,"n": "רב גדל","l": "ג","b": "מובא בבבלי (ברכות מ\"ט ע\"א), והוא רב גידל.","cat": "sage"},{"i": 1010,"n": "גוריא בר חמא","l": "ג","b": "מובא בבבלי (ברכות נ\"ג ע\"ב), שרבא בירך במוצאי שבת על אור שלו, שהיה סמוך לביתו. \"יוחסין\" קבע כי גוריון זה הוא בנו של רב חמא בר גוריון.","cat": "sage"},{"i": 1011,"n": "ר' גוריון","l": "ג","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם ר\"ל (ירו', מגילה פ\"ג ה\"א) ובשם ר' יוסי בר חנינא (ירו', נזיר רפ\"ח). ר' יונה ביקרו באבלו וקרא לו: \"ברנש זעיר\" (ירו', מו\"ק פ\"ג ה\"ה).","cat": "sage"},{"i": 1012,"n": "גוריון בן אסטיון","l": "ג","b": "אמורא בבלי בדור השני. מסר בשם רב (ב\"מ פ\"ו ע\"ב).","cat": "sage"},{"i": 1013,"n": "גוריון מאספורק","l": "ג","b": "מובא בבבלי: \"אמר רב יוסף: 'תני גוריון דמן אספורק'\" (תמורה ל' ע\"ב). \"יוחסין\" כתב שר' יוסף אמר בשמו ו\"סה\"ד\" תמה עליו.","cat": "sage"},{"i": 1014,"n": "גורסק בר דרי","l": "ג","b": "אמורא בבלי בדור השלישי. מובא בבבלי (עירובין כ\"ט ע\"א), שאמר משמיה דרב מנשיא בר שגובלי, שאמר משמיה דרב.","cat": "sage"},{"i": 1015,"n": "רב גזא","l": "ג","b": "מובא בבבלי (יבמות מ\"ה ע\"ב). סביב המובא על אודותיו יש כמה ספקות: \"אמר רבינא [בדור החמישי]: אמר לי רב גזא: איקלע וכו'. אמר רב ששת [בבבל, בדור השני - השלישי]: לדידי אמר לי רב גזא וכו'\" גירסת \"דק\"ס\": רב גדא (היה שמשו ותלמידו של רב ששת).","cat": "sage"},{"i": 1016,"n": "ר' גידול","l": "ג","b": "מובא בירושלמי (ביצה פ\"א ה\"א), והוא ר' גידל, תלמידם של רב ור\"ה.","cat": "sage"},{"i": 1017,"n": "גידול בר מיניימון","l": "ג","b": "מובא בירושלמי (סוטה פ\"ו ה\"ד), והוא רב גידל בר בנימין.","cat": "sage"},{"i": 1018,"n": "גידול בר רעילאי","l": "ג","b": "אמורא בבלי בדור הרביעי. מובא בבבלי (גיטין ל\"ד ע\"א) ששלח גט לאשתו, ואביו ורבא שקלו וטרו בענין גט זה. \"סה\"ד\" כתב: \"לא ידעתי אם חכם הוה\".","cat": "sage"},{"i": 1019,"n": "רב גידל","l": "ג","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (עירובין י\"ז ע\"א), וכן קיבל משמואל (נדרים ט\"ז ע\"ב). אחר פטירתו של רב היה לתלמידו של ר\"ה (יבמות ס\"ד ע\"ב), וכן קיבל מרב חייא בר יוסף (שבת ז' ע\"א) ומרב ירמיה בר אבא (בכורות ל\"ו ע\"ב). הלך לא\"י. קיבל מרב יוחנן (נדה כ\"ד ע\"א). בא\"י היה לו דין ודברים עם רבי אבא (קידושין נ\"ט ע\"א). ר\"ז אמר משמו (ברכות מ\"ט ע\"א). גם רבא בר רב הונא קיבל ממנו (קידושין מ\"ב ע\"א).","cat": "sage"},{"i": 1020,"n": "רב גידל בר בנימין","l": "ג","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (ירו', פסחים פ\"ח ה\"ח). וכן היה תלמידו של רב נחמן (ברכות מ\"ט ע\"א). רב חייא בר יוסף, מתלמידי רב, מסר בשמו (ירו', פסחים שם). ואין זה רב גידל סתמא, שכן רב נחמן בר יצחק מבדיל בפירוש בין שלושה חכמים ושמם רב גידל, וכולם היו תלמידי רב: \"אמר רב נחמן בר יצחק וכו' לא גידול בר מנשיא ולא גידול בר מניומי [הוא בנימין], אלא גידול סתמא\" (פסחים ק\"ז ע\"א).","cat": "sage"},{"i": 1021,"n": "גידל בר מניומי","l": "ג","b": "מובא בבבלי (ב\"ב ל\"ט ע\"ב), והוא רב גידל בר בנימין.","cat": "sage"},{"i": 1022,"n": "רב גידל בר מנשה מבירי דנרש","l": "ג","b": "מובא בבבלי (יומא פ\"א ע\"ב), ונראה שהוא רב גידל בר מנשיא.","cat": "sage"},{"i": 1023,"n": "רב גידל בר מנשיא","l": "ג","b": "אמורא בדור השני. תלמידם של רב (מו\"ק כ\"ד ע\"ב) ושל שמואל (שם כ\"ד ע\"א). היו שלושה רב גידל תלמידי רב. ע\"ע רב גידל בר בנימין.","cat": "sage"},{"i": 1024,"n": "רב גידל דמן נרש","l": "ג","b": "אמורא בבלי. נראה, שחי בדור השלישי, בזמן תלמידי ר\"ה. \"אמר ר\"ה אמר רב וכן תני רב גידל דמן נרש וכו'\" (פסחים ק\"ז ע\"א).","cat": "sage"},{"i": 1025,"n": "רב גמדא","l": "ג","b": "אמורא בבלי בדור הששי. בזמן רב אשי, היה גדול הדור (כתובות ס\"ג ע\"ב). מסר מאמריו של רבא (ב\"ק ע\"ב ע\"א). היה כחברם של אמימר, מר זוטרא ורב אשי (כתובות שם).","cat": "sage"},{"i": 1026,"n": "גמליאל (6)","l": "ג","b": "רבן גמליאל דיבנה - תנא בדור השני. נשיא ישראל. דור רביעי להלל הזקן. בנו של רבן שמעון בן גמליאל הנהרג ובן בנו של רבן גמליאל הזקן (שבת ט\"ו ע\"א), ואבי אביו של רבי (שם). הוא נקרא בדרך כלל סתם \"רבן גמליאל\" בש\"ס (נדה ו' ע\"ב תד\"ה: בשפחתו). בדורו היה חורבן בית המקדש. נתמנה לנשיא כשנתיים אחר החורבן (שבת נ\"ד ע\"ב תד\"ה: הוה). לפניו שימש כנשיא רבן יוחנן בן זכאי (שם), ורבן גמליאל היה תלמידו (ב\"ב י' ע\"ב). היה הראש ביבנה (סנהדרין ל\"ב ע\"ב). חבריו הגדולים היו: רבי אליעזר, שהיה גם גיסו, שנשא ר\"א את אימא שלום אחותו (ב\"מ נ\"ט ע\"ב), ורבי יהושע (הוריות י' ע\"א). ציוה על ר' יהושע לבוא אליו במקלו ובתרמילו ובמעותיו ביום כפור שחל להיות לפי חשבונו, וכשבא רבי יהושע עמד ר\"ג ונשקו על ראשו וקרא לו \"רבי בחכמה ותלמידי שקבלת דברי\" (ר\"ה כ\"ה ע\"א). ובגלל ענין אחר שהיה לו עם ר' יהושע הורידו את ר\"ג מנשיאותו לתקופה מסוימת ומינו במקומו את ר\"א בן עזריה (ברכות כ\"ז ע\"ב). עם תלמידיו נמנה ר\"ע (פסחים מ\"ח ע\"ב). היה בעל רוח הקודש (עירובין ס\"ד ע\"ב). נהג להחמיר על עצמו (ברכות ט\"ז ע\"א). הרומאים רצו להרגו וניצל (תענית כ\"ט ע\"א). נפטר בעקבות נידוי רבי אלעזר גיסו (ב\"מ נ\"ט ע\"ב).","cat": "sage"},{"i": 1027,"n": "רבי גמליאל בי רבי אבינה","l": "ג","b": "מובא בירושלמי (כתובות פ\"ג ה\"י), והוא ר' גמליאל בר' אלעאי.","cat": "sage"},{"i": 1028,"n": "גמליאל בי רבי ליאני","l": "ג","b": "מובא בירושלמי (נדה ספ\"ג), והוא ר' גמליאל בר ר' אלעאי.","cat": "sage"},{"i": 1029,"n": "ר' גמליאל בן אינינוא","l": "ג","b": "מובא בירושלמי (פאה רפ\"א), והוא ר' גמליאל בר ר' אלעאי.","cat": "sage"},{"i": 1030,"n": "רבי גמליאל בר אניא","l": "ג","b": "מובא בירושלמי (כתובות פ\"ד ה\"א), והוא ר' גמליאל בר ר' אלעאי.","cat": "sage"},{"i": 1031,"n": "ר' גמליאל בר ר' אלעאי","l": "ג","b": "אמורא ארץ ישראלי בדור הששי. תלמידו של ר' מנא (ירו', שביעית ספ\"ה). שמו שובש בכמה צורות: ר\"ג בן אינינוא (ירו', פאה רפ\"א), רבן גמליאל ברבי איניונא (ירו', פסחים פ\"א ה\"א), ר\"ג בר' איניוני (ירו', יומא פ\"א ה\"א), רבי גמליאל בי רבי אבינה (ירו', כתובות פ\"ג ה\"י), רבי גמליאל בר אניא (ירו', שם פ\"ד ה\"ח), גמליאל בי רבי ליאני (ירו', נדה ספ\"ג). לחינם חילקו אותו חוקרים שונים לאנשים שונים. מאידך, יש חוקרים ש\"צירפו\" את גמליאל ברבי חנינא וסברו שהוא הוא ר' גמליאל בר ר' אלעאי ולא היא, שכן הוא היה חכם אחר (קה\"ר פ\"ה - יב).","cat": "sage"},{"i": 1032,"n": "רבן גמליאל ברבי","l": "ג","b": "מובא בבבלי (שבת קט\"ו ע\"א), והוא רבן גמליאל דיבנה. ברבי פירושו גדול הדור, (ויש רבן גמליאל בר רבי והוא בנו של רבינו הקדוש).","cat": "sage"},{"i": 1033,"n": "רבן גמליאל ברבי איניונא","l": "ג","b": "מובא בירושלמי (פסחים פ\"א ה\"א), והוא ר' גמליאל בר ר' אלעאי.","cat": "sage"},{"i": 1034,"n": "ר' גמליאל ברבי חנינא","l": "ג","b": "אמורא ארץ ישראל בדור הששי. תלמידו של ר' מנא (קה\"ר פ\"ה - יב).","cat": "sage"},{"i": 1035,"n": "ר' גמליאל בר' איניוני","l": "ג","b": "מובא בירושלמי (יומא פ\"א ה\"א), והוא ר' גמליאל בר ר' אלעאי.","cat": "sage"},{"i": 1036,"n": "גמליאל דקונתיה","l": "ג","b": "אמורא ארץ ישראלי בדור השלישי. נפטר בחיי רבי סימון (ירו', מו\"ק פ\"ג ה\"ה). ר' מנא (חי בדור החמישי) התיר לו נדר (ירו', נדרים ספ\"י). נראה שקראו לו \"גמליאל דקונתיה\" (הזקן), שכן גם בן בנו גמליאל היה חכם (שם).","cat": "sage"},{"i": 1037,"n": "גמליאל זוגא","l": "ג","b": "אמורא ארץ ישראלי בדור השלישי. שאל מר' יוחנן (ירו', חלה פ\"ד ה\"ג), וקיבל מר\"ל (ירו', ע\"ז פ\"ג הי\"א). היה משמש לר' יהושע בן לוי [לפי גיר' \"סה\"ד\"] (ירו', ע\"ז פ\"ג הי\"א). היה לו אח צעיר ושמו הלל (ירו', מו\"ק פ\"ג ה\"ה).","cat": "sage"},{"i": 1038,"n": "גניבא","l": "ג","b": "אמורא בבלי בדור הראשון - השני. היה תלמידו של רב (ברכות כ\"ה ע\"א). אח\"כ היה לו כתלמיד חבר ורב אמר עליו \"אני זקן והוא זקן\" (ירו', ע\"ז פ\"ב ה\"ח). כן מסר בשם רב אסי [תלמיד חבר של רב] (חולין נ' ע\"ב). רבי חייא בר אבא אמר: \"לדידי מפרשא לי מיניה דגניבא\" (שם). היתה לגניבא מחלוקת קשה עם מר עוקבא, ומר עוקבא שלח לרבי אלעזר: \"בני אדם העומדים עלי וכו'\" ור\"א השיב לו: \"הדבר יצא מפי רבי אלעזר ונתנוהו לגניבא בקולר\" (גיטין ז' ע\"א). ופרש\"י: \"שלשלת של ברזל שנותנים שם המוכתבים למלכות להריגה\". ואמנם הוא הוצא להורג מטעם המלכות (גיטין ס\"ה ע\"ב).","cat": "sage"},{"i": 1039,"n": "ר' גרשום","l": "ג","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם ר' אחא. (ירו', נדרים פ\"ג ה\"ח).","cat": "sage"},{"i": 1040,"n": "ר' דוסא (2)","l": "ד","b": "אמורא ארץ ישראלי בדור השלישי. עולא שכפא שנה לפניו ברייתות, וא\"ל ר' דוסא: חזור בך [מאחת הברייתות], א\"ל ר\"ז: 'אל תחזור בך' (ירו', ע\"ז פ\"ב ה\"ט). ר' ברכיה אמר משמו (ב\"ר פי\"ב - ו), וכן רב הונא ב' (רות רבה פ\"א - ד). נפטר בר\"ח ניסן (ירו', סוף מו\"ק).","cat": "sage"},{"i": 1041,"n": "ר' דוסא בן ארכינס","l": "ד","b": "מובא בירושלמי (כתובות פי\"ב ה\"א), והוא ר' דוסא בן הרכינס. וכן גרס \"יתו\"א\": ר' דוסא בן ארקינס הזקן.","cat": "sage"},{"i": 1042,"n": "דוסא בן הורכניס","l": "ד","b": "תנא בדור הראשון והשני, שהאריך ימים והגיע לדור חכמי יבנה (לדעת הרמב\"ם בהקדמתו לזרעים, האריך ימים עד מאד). ידוע כר' דוסא וגם כבן הורכניס (יבמות ט\"ז ע\"א). חלק עם חכמים מדור הראשון, עם רבי יוחנן בן זכאי (ירו', כתובות פי\"ג ה\"א) ועקביא בן מהללאל (נגעים פ\"א מ\"ד), ועם רבי אליעזר (סנהדרין צ\"ט ע\"א) ועם רבן גמליאל מדור השני (ר\"ה כ\"ה ע\"א). רבי יהושע בא להוועץ עמו, לאחר שר\"ג גזר עליו לבוא אליו במקלו ובמעותיו ביום הכיפורים שחל להיות לפי חשבונו (שם). בדורם של חכמי יבנה כבר היה זקן מופלג ועיניו כהו מראות (יבמות ט\"ז ע\"א). היה עשיר מופלג, וכשר' יהושע ור' אליעזר ור' עקיבא באו לביתו הושיבם על מטות של זהב (שם). היה לו אח חריף ביותר ושמו יונתן, שהיה מתלמידי שמאי (שם).","cat": "sage"},{"i": 1043,"n": "ר' דוסא בן טבת","l": "ד","b": "מובא בשהש\"ר (פ\"ז - ח). ר' חנינא אמר בשמו (שם).","cat": "sage"},{"i": 1044,"n": "ר' דוסא בר חנינא","l": "ד","b": "מובא בפדר\"כ (קל\"ג), ואולי צ\"ל ר' יוסי בר חנינא.","cat": "sage"},{"i": 1045,"n": "ר' דוסא ממלחיא","l": "ד","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר' אחא שאמר בשם רבי אלעזר (ירו', סוטה פ\"ג ה\"ז).","cat": "sage"},{"i": 1046,"n": "דוסאי","l": "ד","b": "מובא ב\"ר פ\"א.","cat": "sage"},{"i": 1047,"n": "ר' דוסי סבא","l": "ד","b": "אמורא ארץ ישראלי, ככל הנראה בדור הרביעי. מובא בירושלמי: \"ר' חזקיה, ר' דוסתי, ר' אבא בר זמינא ומטו בה משמיה דר' דוסי סבא\" (חגיגה פ\"א ה\"ח).","cat": "sage"},{"i": 1048,"n": "ר' דוסתאי","l": "ד","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בב\"ר (פי\"א - ח') מובאת מחלוקת ר' ברכיה, ר' דוסתאי ור' שמואל בר נחמני.","cat": "sage"},{"i": 1049,"n": "דוסתאי אבוה דר' אפטוריקי","l": "ד","b": "אמורא ארץ ישראלי בדור הראשון. נמנה עם התנאים שוני ברייתות (חולין ס\"ד ע\"ב: ב\"מ ה' ע\"א). נזכר גם כאבוה דר' אפטוריקי (שם).","cat": "sage"},{"i": 1050,"n": "דוסתאי איש כפר איתמה","l": "ד","b": "מובא בירושלמי (ערלה פ\"ב ה\"ג), והוא דוסתאי איש כפר יתמה.","cat": "sage"},{"i": 1051,"n": "דוסתאי איש כפר יתמה","l": "ד","b": "תנא בדור הראשון, בזמן הבית. תלמידו של שמאי הזקן (ערלה פ\"ב מ\"ה).","cat": "sage"},{"i": 1052,"n": "ר' דוסתאי בר יהודה","l": "ד","b": "תנא בדור החמישי. מובא בבבלי (קידושין ס\"ז ע\"א). מסר בשם רבי שמעון בר יוחי (חולין קכ\"ג ע\"ב). חלק עם רבי (ערכין ל' ע\"א).","cat": "sage"},{"i": 1053,"n": "ר' דוסתאי בר ינאי","l": "ד","b": "תנא בדור החמישי. מסר כמה פעמים בשם רבי מאיר (עירובין נ\"ח ע\"א). מחלוקת אחת בינו לבין רבי נמסרה על ידי רבי אבהו (ירו', דמאי פ\"ז ה\"ז). ירד לבבל יחד עם חברו ר' יוסף בר כיפור. ר' יאשיה ביקש מהם לגבות חוב המגיע לו בנהרדעא (גיטין י\"ד ע\"ב). היו לו תלמידים (נדה ל\"א ע\"ב).","cat": "sage"},{"i": 1054,"n": "ר' דוסתאי בר מתון","l": "ד","b": "מובא בבבלי: \"ר' דוסתאי בר מתון א\"ר יוחנן\" (יומא ל' ע\"ב), אך נראה ט\"ס וצ\"ל כמו במקום אחר: \"ר' יוסטאי בר מתון\" (זבחים צ\"ט ע\"א), ור' דוסתאי בר מתון היה תנא: \"ותניא ר' דוסתאי בר מתון אמר\" (מגילה ו' ע\"ב).","cat": "sage"},{"i": 1055,"n": "ר' דוסתאי דמן בירי","l": "ד","b": "אמורא בדור השני. רבו של עולא (ע\"ז מ' ע\"א). לא ברור אם היה מא\"י שכן בירי הוא מקום גם בא\"י וגם בבבל. בירי מקום ליד צפת, או דבי בירי ודבי נרש בבבל (עירובין נ\"ו ע\"א). גם מהענין המובא במסכת ע\"ז (שם), אין להכריע אם הדבר היה בא\"י או בבבל, שכן הן עולא והן ר' זירא היו בא\"י וגם בבבל.","cat": "sage"},{"i": 1056,"n": "ר' דוסתאי מבי ישבב","l": "ד","b": "תנא בדור החמישי. מובא במדרש משלי (ספ\"ג) ששאל לר' מאיר.","cat": "sage"},{"i": 1057,"n": "ר' דוסתאי מן כוכבא","l": "ד","b": "מובא בפד\"כ (נ\"ט) ואולי צ\"ל ר' דוסתאי מבי ישבב.","cat": "sage"},{"i": 1058,"n": "דוסתאי סבא","l": "ד","b": "מובא ב\"זוהר\" (תזריע ע\"ו). אמר בשם יוסא סבא, ואולי הוא ר' דוסי סבא.","cat": "sage"},{"i": 1059,"n": "ר' דוסתאי סבא","l": "ד","b": "מובא בירושלמי (נדרים ספ\"י) והוא ר' דוסי סבא.","cat": "sage"},{"i": 1060,"n": "דורתאי","l": "ד","b": "חכם קדמון מימי הזוגות, חי בדורו של שמעיה ואבטליון (רבותיהם של הלל ושמאי). ומצינו \"פירוש הוא ודורתאי בנו והלך וישב לו בדרום\" (פסחים ע' ע\"ב), ופרש\"י: \"בן דורתאי פירש מן החכמים ונבדל מהם מפני שהיו אומרים אין חגיגת ארבעה עשר דוחה שבת\". \"סה\"ד\" כתב בערך יהודה בן דורתאי: \"ונראה שהיה צדוקי\", ואם הסיק כך מדברי רש\"י, פליאה בעיני אם אכן כך הבין את רש\"י, וכיצד הפך חכם קדמון ל\"צדוקי\" ואם היה לבעל \"סה\"ד\" מקור אחר, נעלם ממני.","cat": "sage"},{"i": 1061,"n": "דייני ארץ ישראל","l": "ד","b": "הם רבי אמי ורבי אסי (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1062,"n": "דייני גולה","l": "ד","b": "הוא קרנא (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1063,"n": "דייני גזירות","l": "ד","b": "הם אדמון בן גדאי, חנן המצרי וחנן בן אבשלום (כתובות ק\"ה ע\"א).","cat": "sage"},{"i": 1064,"n": "דייני דנהרדעא","l": "ד","b": "הוא רבי אדא (סנהדרין י\"ז ע\"ב), ו\"סה\"ד\" כתב שב\"ערוך\", ערך דן, כתב: רב אבא בר מניומי.","cat": "sage"},{"i": 1065,"n": "דייני דפומבדיתא","l": "ד","b": "הוא רב פפא בר שמואל (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1066,"n": "דייני דציפורי","l": "ד","b": "בתקופת התנאים. מובא במשנה (ב\"ב צ\"ט ע\"ב), ופירש הרשב\"ם: \"לא איתפריש\".","cat": "sage"},{"i": 1067,"n": "דייני דקיסרי","l": "ד","b": "מובא בבבלי (עירובין ע\"ו ע\"ב), שרבי יוחנן אמר כמותם, ולא ברור מי הם.","cat": "sage"},{"i": 1068,"n": "רב דימי","l": "ד","b": "אמורא בדור השלישי - הרביעי. נראה שהיה בבלי (\"אגרת רב שרירא גאון\"). היה מ\"הנחותי\", כלומר היה יורד להביא תורת א\"י לבבל והביא עשרות דינים מחכמי א\"י, ובחזרו הביא מתורת בבל לא\"י. כגון: \"כי אתא רב דימי א\"ר חנינא\" (שבת קכ\"ה ע\"ב), \"כי אתא רב דימי א\"ר יוחנן\" (שבת ז' ע\"א) \"כי סליק רב דימי\" (תמורה י\"ד ע\"א). בירושלמי נזכר כרב אבדימי נחותא (עירובין פ\"א ה\"ו). היה תלמידו של רב נחמן (חולין קי\"ב ע\"א). רבין חברו היה גם הוא מן הנחותי, ופעמים שבאו זה אחר זה \"כי אתא רב דימי אמר ר' אלעזר וכו', כי אתא רבין וכו' אמר ר' אלעזר\" (שבת קל\"ד ע\"ב). בסוף ימי אביי ורבא, באו כל \"הנחותי\" לבבל בגלל הגזירות בא\"י (\"אגרת רב שרירא גאון\"). כן מצינו: \"אתא רבין וכל נחותי וכו'\" (חולין קכ\"ד ע\"א).","cat": "sage"},{"i": 1069,"n": "רב דימי אחוה דרב ספרא","l": "ד","b": "אמורא בבלי בדור השלישי. אחיו של רב ספרא (ערכין ט\"ז ע\"א). ר' אבא אמר עליו לאחר פטירתו: \"ידענא ביה ברב דימי ולא אמיד\" (כתובות פ\"ה ע\"ב). ידוע מאמרו: \"אל יספר אדם בטובתו של חבירו, שמתוך טובתו בא לידי רעתו\" (ב\"ב קס\"ד ע\"ב).","cat": "sage"},{"i": 1070,"n": "רב דימי בר אבא","l": "ד","b": "אמורא בבלי. מובא בבבלי (ברכות כ\"ג ע\"ב). (לפי \"סה\"ד\" נפטר ד' ר\"י (054) דור שביעי לאמוראים).","cat": "sage"},{"i": 1071,"n": "רב דימי בר חיננא (2)","l": "ד","b": "אמורא בבלי בדור השלישי - הרביעי. מתשובתו לשאלת רב חייא, בנו של רבה, נראה שעוד זכה לקבל שמועות מרב (ר\"ה ל\"ד ע\"ב). דן על דברי רבה (ב\"ק צ\"ח ע\"ב). רב חסדא אמר עליו: \"מרגלא בפומיה דרב דימי בר חיננא\" (זבחים ל\"ו ע\"ב). האריך ימים - מצינו שבא לדין תורה בפני רבא (ב\"ב י\"ג ע\"ב).","cat": "sage"},{"i": 1072,"n": "רב דימי בר חמא","l": "ד","b": "מובא בבבלי (ע\"ז כ' ע\"ב), והוא רב אבדימי בר חמא.","cat": "sage"},{"i": 1073,"n": "ר' דימי בר חמא","l": "ד","b": "מובא בבבלי (ע\"ז ב' ע\"ב), והוא ר' אבדימי בר חמא בר חסא.","cat": "sage"},{"i": 1074,"n": "רב דימי בר יוסף","l": "ד","b": "אמורא בבלי בדור השני - השלישי. תלמידו המובהק של שמואל (נדה ס\"ו ע\"א), קיבל גם מרב (ברכות מ\"ה ע\"ב). ר\"נ קראו שיבוא להתדיין לפניו עם אחותו, וכשסירב איים עליו בנידוי (ב\"ב קנ\"א ע\"ב).","cat": "sage"},{"i": 1075,"n": "רב דימי בר יצחק","l": "ד","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (חולין מ\"ה ע\"ב).","cat": "sage"},{"i": 1076,"n": "רב דימי בר ליואי","l": "ד","b": "אמורא בבלי בדור הרביעי. אביי פסק לו בענין דין בשבת (ברכות כ\"ז ע\"ב).","cat": "sage"},{"i": 1077,"n": "דימי בר שישנא","l": "ד","b": "אמורא בבלי בדור השני. מסר מאמרים בודדים בשם רב (גיטין ס\"ב ע\"א).","cat": "sage"},{"i": 1078,"n": "רב דימי בריה דרב הונא מדמהוריא","l": "ד","b": "אמורא בבלי בדור הששי - השביעי. שאל מרבינא, ואין להכריע אם היה חבר או תלמיד לרבינא (מנחות פ\"א ע\"א: סנהדרין כ\"ט ע\"ב).","cat": "sage"},{"i": 1079,"n": "רב דימי בריה דרב נחמן בריה דרב יוסף","l": "ד","b": "מובא בבבלי (סנהדרין כ\"ד ע\"א).","cat": "sage"},{"i": 1080,"n": "רב דימי דמן חיפא","l": "ד","b": "מובא בבבלי (מגילה כ\"ט ע\"ב), והוא ר' אבדימי דמן חיפא.","cat": "sage"},{"i": 1081,"n": "רב דימי מנהרדעא","l": "ד","b": "אמורא בבלי בדור הרביעי - החמישי בימי רב יוסף (ב\"ב כ\"ב ע\"א). היה חכם בלתי ידוע ורבא שלח לבדוק אחריו (שם). לא ברור מי היו רבותיו. מלך בפומבדיתא משנת ד' קמ\"ה - קמ\"ח (583 - 883) (\"אגרת רב שרירא גאון\"). אמימר מסר בשמו (חולין נ\"א ע\"ב), ואין זה רב דימי סתם, כמוכח (ע\"ז י\"א ע\"א). האריך ימים ונפטר 56 שנה אחר רב יוסף (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 1082,"n": "רב דניאל בר רב קטינא","l": "ד","b": "אמורא בבלי בדור השלישי. תלמידו של רב (מו\"ק ח' ע\"א). אח\"כ היה לתלמידו של רב הונא (כתובות צ\"ז ע\"א), וכן מסר בשמו של רב אסי (ירו', שבת פ\"ג ה\"א). מסופר עליו נס מופלא כיצד הוריד גשם בתפילותיו רק למקומות מסויימים בגינתו (תענית ט' ע\"ב).","cat": "sage"},{"i": 1083,"n": "דניאל חייטא","l": "ד","b": "מובא בב\"ר (פס\"ד - ז').","cat": "sage"},{"i": 1084,"n": "דנין לפני חכמים","l": "ד","b": "הם שמעון בן עזאי, שמעון בן זומא, חנן המצרי וחנניא בן חכינאי. ורב נחמן בר יצחק אומר: אף שמעון התימני (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1085,"n": "דרו בר פפא","l": "ד","b": "אמורא בבלי בדור השני. אמר בשם רב וחלק עם רבי יוחנן (ע\"ז כ\"ז ע\"א).","cat": "sage"},{"i": 1086,"n": "דרומאי","l": "ד","b": "חכמי דרום שגרו בדרומה של ארץ ישראל, וגם ר' אפס ישב שם (עירובין ס\"ה ע\"ב). \"דרומאי מתני משמיה דרבי יהושע בן לוי\" (ב\"ב צ\"ו ע\"א). \"מתיב רבי שמעון בן לקיש לדרומאי\" (ירו', פסחים פ\"ז ה\"ז).","cat": "sage"},{"i": 1087,"n": "ר' דרומי","l": "ד","b": "כך הגירסא בירושלמי (קידושין פ\"א ה\"ז), וגירסת \"קרבן העדה\": ר' דרוסי: אם כן, לגירסתו ר' דרומי לא היה ולא נברא, שכן הוא מובא רק פעם אחת בש\"ס הירושלמי.","cat": "sage"},{"i": 1088,"n": "רבי דרוסא","l": "ד","b": "מובא בירושלמי (כלאים פ\"ט רה\"ג), והוא רבי דרוסי.","cat": "sage"},{"i": 1089,"n": "רבי דרוסי","l": "ד","b": "אמורא ארץ ישראלי בדור החמישי. חברו של רבי יוסי בר אלעזר וחלק עמו (ירו', שבת פ\"א ה\"ב). היה לו אח ושמו רבי פטרוקי (ירו', יומא פ\"ד ה\"ד).","cat": "sage"},{"i": 1090,"n": "רבי דרוסתאי","l": "ד","b": "מובא במדרש שמואל (כ\"ח - ד') ונראה שהוא רבי דרוסי.","cat": "sage"},{"i": 1091,"n": "ההוא מרבנן ורבי יעקב שמיה","l": "ה","b": "ע\"ע ר' יעקב.","cat": "sage"},{"i": 1092,"n": "הון בריה דרב נחמן","l": "ה","b": "אמורא בבלי בדור הרביעי. בנו ותלמידו של רב נחמן. הקשה לר\"נ (יבמות ל\"ד ע\"א) ושאל ממנו (שם קי\"ב ע\"א).","cat": "sage"},{"i": 1093,"n": "רב הונא (4)","l": "ה","b": "גדול אמוראי בבל בדור השני. חי למעלה משמונים שנה (מו\"ק כ\"ח ע\"א). נפטר בשנת ד' נ\"ו (692) (\"אגרת רב שרירא גאון\"). תלמידו המובהק של רב (שבת קכ\"ח ע\"א). לאחר פטירת רב נתמנה לראש ישיבת סורא ומלך 04 שנה (\"אגרת רב שרירא גאון\"). היה הראש בבבל. רבים מתלמידי רב באו לפניו אחרי פטירת רב, כגון: רב חלבו (יבמות ס\"ד ע\"ב), ר' חייא בר אבין (קידושין נ\"ח ע\"א) ורב גידל בר בנימין (ב\"ב ל\"ט ע\"ב). אחר פטירת ר' יוחנן בשנת ד' ל\"ט (972) היו גם ראשי ארץ ישראל כפופים לו: \"רבי אמי ורבי אסי כהני חשובי דא\"י מיכף הוו כייפי ליה\" (גיטין נ\"ט ע\"ב). רבי אלעזר בן פדת החשיב עצמו קטן מרב הונא (ב\"ב קכ\"ה ע\"א). היו לו 008 תלמידים, ו - 31 אמוראים היו משמיעים את דבריו לתלמידים הרבים שהיו סביבו (כתובות ק\"ו ע\"א). ר' יוסף היה תלמידו המובהק (סוכה י\"א ע\"א), וכן רבה (עירובין י\"ז ע\"א) ורב ששת (כתובות ס\"ד ע\"ב) ובנו רבה בר רב הונא (ברכות נ\"ג ע\"ב). רב חסדא היה תלמיד חבר שלו (יבמות פ\"ג ע\"ב ד\"ה: אמרי). היה חכם גדול, ורבא ביקש שיזכה לחכמתו של ר\"ה (מו\"ק כ\"ח ע\"א). היה חסיד גדול, ופעם אחת כאשר נהפכו לו רצועות התפילין, צם 04 תעניות (מו\"ק כ\"ה ע\"א). בתחילה היה עני מרוד, ורב בירכו והעשיר (מגילה כ\"ז ע\"ב). כשנפטר העלו את ארונו לא\"י, וקברוהו במערת קברו של רבי חייא ובניו (מו\"ק שם). את מקומו מילא רב חסדא (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 1094,"n": "רב הונא אביו של זעירא הכהן","l": "ה","b": "מובא בירושלמי (ברכות פ\"ח ה\"ה). יש שם אי בהירות או שיבוש, ואין הכרעה, וכבר האריך בזה \"סה\"ד\".","cat": "sage"},{"i": 1095,"n": "רב הונא אביו של ר' אחא","l": "ה","b": "מובא בבמד\"ר (פ\"ט - יב).","cat": "sage"},{"i": 1096,"n": "רב הונא בבלאה","l": "ה","b": "הוא רב הונא סתם.","cat": "sage"},{"i": 1097,"n": "רב הונא בר אבא","l": "ה","b": "מובא בתנחומא (ישן, תצוה). יתכן שצ\"ל: ר' חייא בר אבא (עיין תנחומא בובר סוף תצוה).","cat": "sage"},{"i": 1098,"n": "רב הונא בר אבין","l": "ה","b": "אמורא ארץ ישראלי בדור הרביעי ו\"שלח\" הרבה מא\"י לבבל. \"שלח לרבא\" (ר\"ה כ\"א ע\"א), וכן \"שלח\" (ב\"ב נ\"א ע\"א ושם נ\"ה ע\"א). היו לו בנים שבאו לשאול דין מר' אמי (קידושין ח' ע\"ב).","cat": "sage"},{"i": 1099,"n": "רב הונא בר אדא","l": "ה","b": "מובא בבבלי (ברכות ס\"ב ע\"ב), לפי גיר' \"דק\"ס\", ולפנינו: רב חנא בר אדא, ושוב לא נזכר בש\"ס.","cat": "sage"},{"i": 1100,"n": "רב הונא בר אויא","l": "ה","b": "אמורא בדור החמישי. חברו של רב אשי (חולין מ\"ז ע\"א). נפטר לפני רב אשי, ורב אשי סיפר לרב מרדכי שר\"ה אויא בא לו בחלום (ב\"ב קמ\"ג ע\"א).","cat": "sage"},{"i": 1101,"n": "רב הונא בר אחא","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי אלכסנדרי (ירו', סוף מע\"ש). ור' יוסי בן חנינא מוסיף על דבריו (שם).","cat": "sage"},{"i": 1102,"n": "רב הונא בר אידי","l": "ה","b": "אמורא בבלי בדור השני. תלמידו של שמואל (קידושין ע' ע\"א). רב יהודה אמר לרב נחמן: \"לא סבר לה מר, להא דאמר רב הונא בר אידי, אמר שמואל\" (שם).","cat": "sage"},{"i": 1103,"n": "רב הונא בר אמי","l": "ה","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של פדת [בנו של ר\"א בן פדת] (ברכות נ\"ה ע\"ב). ו\"סה\"ד\", בערך רב חנן בן אמי, מפקפק אם אין כאן ט\"ס.","cat": "sage"},{"i": 1104,"n": "רב הונא בר אשי","l": "ה","b": "אמורא בבלי בדור השני. תלמידו של רב (סוטה ט\"ז ע\"ב).","cat": "sage"},{"i": 1105,"n": "רב הונא בר ביזנא","l": "ה","b": "מובא בבבלי (יבמות ס' ע\"ב), ונראה שהוא רב חנא בר ביזנא.","cat": "sage"},{"i": 1106,"n": "רב הונא בר ברכיה","l": "ה","b": "אמורא ארץ ישראלי בדור הראשון. אמר משום אלעזר הקפר (ברכות ס\"ג ע\"א).","cat": "sage"},{"i": 1107,"n": "רב הונא בר גוריון","l": "ה","b": "מובא בב\"ר (פכ\"ו - ו'), ואולי צ\"ל: רב חמא בר גוריון (עיין קה\"ר פ\"ח - ט').","cat": "sage"},{"i": 1108,"n": "רב הונא בר גניבא","l": "ה","b": "מובא בקה\"ר (ספ\"ד).","cat": "sage"},{"i": 1109,"n": "רב הונא בר חיון","l": "ה","b": "אמורא בבלי בדור הששי. הבבלי (שבת קל\"ט ע\"ב) מפקפק אם שמו רב הונא בר חיון או רב הונא בר חלוון. תלמידיו התלוננו עליו, ורב אשי הצדיקו (שם).","cat": "sage"},{"i": 1110,"n": "רב הונא בר חייא","l": "ה","b": "אמורא בבלי בדור השלישי. חתנו ותלמידו של רבי ירמיה בר אבא [תלמיד חבר של רב] (שבת קנ\"ו ע\"א). קיבל משמואל (שבת נ\"א ע\"ב), מרב הונא (ב\"ב קי\"א ע\"ב) ומרב יהודה (סנהדרין ק' ע\"א). היה לו בית מדרש (\"אגרת רב שרירא גאון\"). רבה ורב יוסף וארבע מאות חכמים באו אליו לשאול ממנו הלכות, ולאחר ששמעו שנעשה גבאי המלך פרשו ממנו חלק מהחכמים, ורבה למד ממנו (בכורות ל\"א ע\"א).","cat": "sage"},{"i": 1111,"n": "רב הונא בר חיננא","l": "ה","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (עירובין י\"ד ע\"ב). ישב לפני רב חסדא ושאל מרב ששת (קידושין כ' ע\"ב). קיבל מרב נחמן (כתובות ק' ע\"א). כמה מהוראותיו היו בניגוד לדעתו של רבא (ע\"ז מ' ע\"א, וראה גם עירובין ס\"ז ע\"ב). חבריו היו: רחבה (שם כ\"ו ע\"ב) ואביי (ב\"ב קס\"ז ע\"ב). נראה, שרב פפא היה תלמידו. (ע\"ז מ' ע\"א) ובנו למד אצל ר\"פ (פסחים ט\"ז ע\"א).","cat": "sage"},{"i": 1112,"n": "רב הונא בר חלוב","l": "ה","b": "אמורא בבלי בדור הרביעי. שאל מרב נחמן (שבת קט\"ו ע\"ב).","cat": "sage"},{"i": 1113,"n": "רב הונא בר חלוון","l": "ה","b": "מובא בבבלי (שבת קל\"ט ע\"ב). ע\"ע רב הונא בר חיון.","cat": "sage"},{"i": 1114,"n": "הונא בר חנינא","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\"א (ירו', מעשרות פ\"ד ה\"ד).","cat": "sage"},{"i": 1115,"n": "רב הונא בר חנינא","l": "ה","b": "מובא בבבלי (כתובות ק' ע\"א), והוא רב הונא בר חיננא.","cat": "sage"},{"i": 1116,"n": "רב הונא בר יהודה","l": "ה","b": "אמורא בבלי בדור הרביעי. קיבל הרבה מרב ששת (עירובין כ\"ו ע\"ב), ומרב נחמן (פסחים מ' ע\"ב), וכן היה כתלמיד לרבא (פסחים י\"ב ע\"א) ושאל ממנו (נדרים י\"ט ע\"א). רב נחמן קרא לו מר (פסחים מ' ע\"ב).","cat": "sage"},{"i": 1117,"n": "רב הונא בר יצחק","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי. ר' יהושע בר נחמיה אמר בשמו (פס' רבתי פ' בחודש השביעי).","cat": "sage"},{"i": 1118,"n": "רב הונא בר יקי","l": "ה","b": "מובא בפס' רבתי (פ' את קרבני).","cat": "sage"},{"i": 1119,"n": "רב הונא בר ירמיה","l": "ה","b": "מובא בבבלי (פסחים מ\"ג ע\"א), ואולי הוא ר\"ה בר ירמיה בר אבא.","cat": "sage"},{"i": 1120,"n": "רב הונא בר כהנא","l": "ה","b": "מובא בילקוט (קהלת רמז תתקסו).","cat": "sage"},{"i": 1121,"n": "רב הונא בר לואי","l": "ה","b": "מובא בבבלי (ברכות נ\"ה ע\"ב) לגיר' \"עין יעקב\", ולפנינו סתם רב הונא.","cat": "sage"},{"i": 1122,"n": "רב הונא בר לוליאני","l": "ה","b": "מובא בב\"ר (פל\"ו - ח'). ואולי זה שיבוש מרבי חייא בר לולייני (ע\"ע).","cat": "sage"},{"i": 1123,"n": "רב הונא בר מנוח","l": "ה","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (תענית ט' ע\"א). חברם של רב שמואל בר אידי ורב חייא מוסתניא: שלושתם למדו אצל רבא, ולאחר פטירתו באו ללמוד אצל רב פפא. בכל פעם שאמר שמועה שלא נראתה להם, רמזו זה לזה וחלשה דעתו של ר\"פ, ושילחם מעל פניו, לבל ייענשו מן השמים (שם). מסר בשם רב אחא בריה דרב איקא (מגילה כ\"ה ע\"ב).","cat": "sage"},{"i": 1124,"n": "הונא בר מניומי","l": "ה","b": "אמורא בבלי בדור השלישי - הרביעי. בא לשאול דין מרב יוסף ולא ידע להשיב לו, ואח\"כ פגש בחנן חייטא שהשיב לשאלתו (ע\"ז ל\"ט ע\"א).","cat": "sage"},{"i": 1125,"n": "רב הונא בר משה בר עצרי","l": "ה","b": "אמורא בבלי בדור הרביעי. מובא בבבלי (ב\"ב קע\"ד ע\"ב). אביו לא היה חכם (שם).","cat": "sage"},{"i": 1126,"n": "הונא בר נתן","l": "ה","b": "מובא בבבלי (ב\"ב נ\"ה ע\"א), והוא רב הונא בריה דרב נתן.","cat": "sage"},{"i": 1127,"n": "רב הונא בר סחורה","l": "ה","b": "אמורא בבלי בדור הרביעי. תלמידו של רבא (בכורות ס' ע\"א). אמר רב נחמן בר יצחק: \"זכתה אמו שילדה בן כמותו\" (שם).","cat": "sage"},{"i": 1128,"n": "רב הונא בר עוקבא","l": "ה","b": "מובא ב\"ילקוט\" (איכה רמז תתרא).","cat": "sage"},{"i": 1129,"n": "רב הונא בר פפא","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. חלק עם ר' סימון (מדרש תהלים פק\"ד - י\"ד). רבי פנחס מסר בשמו (ב\"ר ספס\"ח).","cat": "sage"},{"i": 1130,"n": "ר' הונא בר רב יוסף","l": "ה","b": "מובא בב\"ר (פמ\"ד - י\"ב), ואולי זהה עם רב הונא בר יוסי.","cat": "sage"},{"i": 1131,"n": "רב הונא בר רב קטינא","l": "ה","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב חסדא (זבחים קט\"ו - ע\"ב). וגיר' \"שיטה מקובצת\" וה\"ב\"ח\": \"רב חונה\". ובמקום אחר: \"רב הונא ברב קטינא\" (חולין י\"ז ע\"ב), וגיר' \"דק\"ס\": רב חנא יש סבורים שהוא: רב חנא בר רב קטינא.","cat": "sage"},{"i": 1132,"n": "רב הונא בר רב תחליפא","l": "ה","b": "אמורא בבלי בדור החמישי - הששי. תלמידו של רבא (יבמות ח' ע\"ב). רבו של רב רחומי (זבחים ע\"ז ע\"א). גם אביו של רב הונא בר תחליפא (ר' תחליפא עצמו) היה תלמידו של רבא (יומא ו' ע\"ב).","cat": "sage"},{"i": 1133,"n": "רב הונא בר תורתא","l": "ה","b": "מובא בבבלי: \"אמר רב הונא בר תורתא: וכו' וכשבאתי לפני רבי שמעון החסיד [תנא דברייתא] אמר לי וכו'\" (חולין קכ\"ז ע\"א). נראה, שהיה תנא ו\"יוחסין\" מביא שהיה גר, ומפני שפרתו לא רצתה לחרוש בשבת נעשה יהודי והמעשה מובא (פס' רבתי פ' פרה) והגיר' שלנו: רבי יוחנן בן תורתא.","cat": "sage"},{"i": 1134,"n": "הונא בריה דמר זוטרא","l": "ה","b": "אמורא בבלי בדור הששי - השביעי. תלמידו של רבינא (ב\"ב פ\"ו ע\"א).","cat": "sage"},{"i": 1135,"n": "רב הונא בריה דרב אידי","l": "ה","b": "מובא בבבלי (ר\"ה כ\"ד ע\"ב). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: רב הונא בריה דרב יהושע\", וכן נראה מגיר' רש\"י (ע\"ז מ\"ב ע\"ב, ד\"ה: וכדרב הונא בריה דרב יהושע).","cat": "sage"},{"i": 1136,"n": "הונא בריה דרב איקא","l": "ה","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אבהו (פסחים נ\"ב ע\"ב). דייק מאד במסירת שמועות שקיבל מרבו (שם). נראה, שהיה גם בבבל ורב פפא ביקר אצלו (ברכות מ\"ג ע\"ב). ומצינו: \"אמר אביי וכו' מתיב ר\"ה בריה דרב איקא\" (ביצה ט\"ו ע\"א).","cat": "sage"},{"i": 1137,"n": "רב הונא בריה דרב הועיא","l": "ה","b": "מובא ב\"ילקוט\" (משלי רמז תתקנד), ונראה אולי שצ\"ל: ר\"ה בריה דרב יהושע (עיין סוטה ה' ע\"א).","cat": "sage"},{"i": 1138,"n": "רב הונא בריה דרב הושעיא","l": "ה","b": "מובא בבבלי (הוריות ג' ע\"ב).","cat": "sage"},{"i": 1139,"n": "רב הונא בריה דרב חייא","l": "ה","b": "מובא בבבלי (ע\"ז פ\"ז ע\"ב: נזיר ל\"ז ע\"ב). אך באותו ענין יש גירסא הפוכה (רב חייא בריה דרב הונא), בשני מקומות אחרים: (פסחים מ\"ד ע\"ב: ע\"ז ע\"ה ע\"ב).","cat": "sage"},{"i": 1140,"n": "רב הונא בריה דרב יהושע","l": "ה","b": "אמורא בבלי בדור החמישי. חברו המובהק של רב פפא. שניהם נזכרים יחד פעמים רבות בש\"ס הבבלי, ושניהם היו מתלמידיו המובהקים של אביי (פסחים קי\"א ע\"ב) ושל רבא (ב\"ב כ\"ב ע\"א: הוריות י' ע\"ב), וגם שלחו ידם במסחר יחדיו (גיטין ע\"ג ע\"א). לאחר פטירת רבא יסד רב פפא ישיבה בעיר נרש הסמוכה לסורא ובה שימש רב הונא בריה דרב יהושע כראש כלה (ברכות נ\"ז ע\"א). מחבריו היו רב מרי ורב פנחס בני רב חסדא (קידושין ל\"ב ע\"ב) ורב פנחס בר אמי (כתובות פ\"ה ע\"א) ורנב\"י (סנהדרין ל' ע\"ב). ר' יעקב מנהר פקוד אמר משמו לפני רבינא (סנהדרין ס\"ט ע\"א). חלה ונטה למות ובזכות שנהג להעביר על מידותיו ריחמו עליו מן השמים והבריא (ר\"ה י\"ז ע\"א).","cat": "sage"},{"i": 1141,"n": "רב הונא בריה דרב נחמיה","l": "ה","b": "מובא בבלי (חולין י\"ח ע\"ב), והוא רב הונא מר בריה דרב נחמיה.","cat": "sage"},{"i": 1142,"n": "הונא בריה דרב נחמן","l": "ה","b": "אמורא בבלי בדור הרביעי. בנו של רב נחמן (חולין מ\"ט ע\"ב). יחד עם חברו רב הונא בר חיננא, גרו בעיר סוכרא הסמוכה למחוזא, ושניהם חלקו על רבא (ע\"ז נ\"ז ע\"ב). כשנזדמן למחוזא, ציוה רבא לשמשו לסגור את הדלת, שכן פחד ממנו שמא יקפחנו בהלכות (שם נ\"ח ע\"א). תירץ לרב פפא קושיה ורב פפא נשקו על ראשו, ונתן לו את בתו לאשה (הוריות י\"ב ע\"ב).","cat": "sage"},{"i": 1143,"n": "רב הונא בריה דרב נתן","l": "ה","b": "אמורא בבלי בדור החמישי - הששי. ראש הגולה בימי רב אשי (\"אגדת רב שרירא גאון\"). תלמידו של רבא (נדרים י\"ב ע\"א) ושל אמימר (גיטין י\"ט ע\"ב). היה כפוף לרב אשי, אף שרב אשי מסר משמו (גיטין י\"ט ע\"ב; ב\"ב נ\"ה ע\"א). זכה לתורה וגדולה גם יחד (גיטין נ\"ט ע\"א), שלא היה כמותו מימות רבי מסדר המשנה (שם). היה מקורב מאד למלך הפרסי איזגדר (זבחים י\"ט ע\"א). נפטר בשנת ד' ר\"א (144) (ספר \"כריתות\").","cat": "sage"},{"i": 1144,"n": "רב הונא בריה דרב עילאי","l": "ה","b": "מובא בבבלי (יומא ל\"ה ע\"א), וגיר' \"דק\"ס\": \"רב עולא בריה דרב עילאי\".","cat": "sage"},{"i": 1145,"n": "רב הונא בריה דרב פנחס","l": "ה","b": "אמורא בבלי בדור הרביעי. אמר משמו של רב יוסף (מו\"ק ט\"ו ע\"ב).","cat": "sage"},{"i": 1146,"n": "רב הונא בריה דרב פפי","l": "ה","b": "אמורא בבלי בדור החמישי. בש\"ס אין הלכות ממנו. מובא בבבלי (חולין מ\"ח ע\"א) בהקשר לבנו מר זוטרא בריה דרב הונא בריה דרב פפי.","cat": "sage"},{"i": 1147,"n": "רב הונא בריה דרבא","l": "ה","b": "אמורא בבלי. למד יחד עם רב אשי (ב\"ק ע\"ב ע\"א).","cat": "sage"},{"i": 1148,"n": "רב הונא בריה דר' ירמיה בר אבא","l": "ה","b": "אמורא בבלי בדור השלישי. בנו של ר' ירמיה בר אבא [תלמיד חבר של רב], ואביו של מרי (ברכות כ\"ו ע\"א). לא מובאת בש\"ס הלכה ממנו.","cat": "sage"},{"i": 1149,"n": "רב הונא בריה דר' שמואל בר נחמני","l": "ה","b": "נראה שיבוש. עיין \"ילקוט משלי\" (רמז תתקסא) ובב\"ר (פע\"ה - ג').","cat": "sage"},{"i": 1150,"n": "רב הונא בר' יוסי","l": "ה","b": "מובא בתנחומא (נ\"ח - י\"ג), ואולי זהה עם רב הונא בר רב יוסף.","cat": "sage"},{"i": 1151,"n": "רב הונא דציפורין","l": "ה","b": "","cat": "sage"},{"i": 1152,"n": "ר' הונא דשאב","l": "ה","b": "מובא בתנחומא (מצורע ז'), ונראה שצ\"ל: ר' מנא דשאב.","cat": "sage"},{"i": 1153,"n": "ר' הונא הכהן","l": "ה","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי ירמיה (מד' תהלים פק\"ו - ב').","cat": "sage"},{"i": 1154,"n": "רב הונא הכהן בר אבין","l": "ה","b": "מובא בפס' רבתי (פ\"ח), וצ\"ל: רב הונא הכהן בר אבין.","cat": "sage"},{"i": 1155,"n": "רבי הונא הכהן בר אבין","l": "ה","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם ר' שמואל בר נחמני (מ\"ר פ\"ז - ד') ורב יוסף (פס' רבתי פ' אנכי מנחמכם). רבו של רבי תנחומא בר אבא שהוא בעל התנחומא (מד\"ר פ\"ג - ז').","cat": "sage"},{"i": 1156,"n": "רב הונא זוטי","l": "ה","b": "אמורא בבלי בדור הרביעי. בש\"ס אין הלכה בשמו, ומובא רק בהקשר לבנו: \"דרש רבא בר רב הונא זוטי\" (ביצה כ\"ט ע\"ב), וכן: (כתובות ס\"ט ע\"א). שלח וכו' לרבה בר רב הונא זוטא\".","cat": "sage"},{"i": 1157,"n": "רב הונא מברניש","l": "ה","b": "מובא בבבלי (שבת כ\"ח ע\"א), לגיר' \"יוחסין\" ו\"סה\"ד\", ולפנינו: רבא מברניש.","cat": "sage"},{"i": 1158,"n": "רב הונא מדמהריא","l": "ה","b": "אמורא בבלי בדור החמישי - הששי. אין בש\"ס הלכה בשמו, ומובא רק בהקשר לבנו: רב דימי בר רב הונא מדמהריא (סנהדרין כ\"ט ע\"ב: מנחות פ\"א ע\"א).","cat": "sage"},{"i": 1159,"n": "רב הונא מדסקרתא","l": "ה","b": "אמורא בבלי בדור הרביעי - החמישי. תלמידו של רבא (ב\"מ מ\"ז ע\"א). כשהקשה לפני רבא על דברי לוי, ענה לו רבא כי אילו לוי היה שם היה מנדה אותו על שחשד שלכך התכון בדבריו (שם).","cat": "sage"},{"i": 1160,"n": "רב הונא מסורא","l": "ה","b": "מובא בבבלי (זבחים צ\"א ע\"א).","cat": "sage"},{"i": 1161,"n": "רב הונא מר בר אויא","l": "ה","b": "מובא בבבלי (חולין מ\"ז ע\"א) שהקשה לרב אשי, והוא רב הונא בר אויא.","cat": "sage"},{"i": 1162,"n": "רב הונא מר בר חייא","l": "ה","b": "אמורא בבלי בדור הששי. היה חברו של רב אשי (חולין נ\"ח ע\"ב).","cat": "sage"},{"i": 1163,"n": "הונא מר בר מרימר","l": "ה","b": "אמורא בבלי בדור הששי. תלמידו של רבינא (ב\"מ פ\"א ע\"א).","cat": "sage"},{"i": 1164,"n": "הונא מר בריה דרב אידי","l": "ה","b": "אמורא בבלי בדור השביעי. חברו של רב אדא בר מניומי, ובענין מחלוקת ביניהם בדין טריפות, שאלו לרבינא (חולין מ\"ט ע\"א).","cat": "sage"},{"i": 1165,"n": "הונא מר בריה דרבא מפרזיקא","l": "ה","b": "אמורא בבלי בדור הששי - השביעי. הקשה לרב אשי (כתובות י' ע\"א).","cat": "sage"},{"i": 1166,"n": "רב הונא מר בריה דר' נחמיה","l": "ה","b": "אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי (חולין י\"ז ע\"ב) והקשה לו (גיטין י\"ד ע\"א), ושקיל וטרי עמו (קידושין ו' ע\"ב).","cat": "sage"},{"i": 1167,"n": "הונא מרי בר מר זוטרא","l": "ה","b": "מן האמוראים האחרונים בתחילת הסבוראים (\"אגרת רב שרירא גאון\"). נהרג בשנת ד' תרל\"א לשטרות (ד' רע\"ט /915) עם אמימר בר מר ינוקא ור' משרשיא, בן בנו של רב אחא בר רב.","cat": "sage"},{"i": 1168,"n": "רב הונא ספרא דסדרא","l": "ה","b": "מובא בירושלמי (שבת פ\"ט ה\"ב). פירש \"קרבן העדה\": \"סופר של בית המדרש\".","cat": "sage"},{"i": 1169,"n": "רב הונא צפוראה","l": "ה","b": "מובא בבבלי (יומא ע\"ז ע\"ב), והוא רבי הונא רובא דציפורין.","cat": "sage"},{"i": 1170,"n": "רב הונא רב","l": "ה","b": "מובא בירושלמי (שקלים פ\"א), ונראה שהוא רב הונא סתם.","cat": "sage"},{"i": 1171,"n": "רב הונא רבה","l": "ה","b": "מובא בבבלי (בכורות ל\"ז ע\"ב), והוא רב הונא סתם.","cat": "sage"},{"i": 1172,"n": "רב הונא רבה דציפורין","l": "ה","b": "מובא בירושלמי (שקלים פ\"א ה\"א), והוא רב הונא רובא דציפורין.","cat": "sage"},{"i": 1173,"n": "רב הונא רובא דציפורין","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי. מסר כמה פעמים בשם רבי יוחנן (ירו', ברכות ספ\"ד). ר' אחא בר יצחק מסר משמו קטע תפילה, שחלקים ממנה יש בסידורים שלנו (ירו', תענית פ\"ב ה\"ב).","cat": "sage"},{"i": 1174,"n": "רב הונא ריש גלותא","l": "ה","b": "ע\"ע רב הונא (תנא).","cat": "sage"},{"i": 1175,"n": "רבי הונדקס","l": "ה","b": "כך מובא בירושלמי (שבת פט\"ז ה\"ג), והוא רבי חדקא.","cat": "sage"},{"i": 1176,"n": "הורדוס","l": "ה","b": "מלך על ישראל החל מק\"ג שנה לפני חורבן בית שני (ע\"ז ט' ע\"א) [הלל החל את נשיאותו ק' שנה לפני הבית (שבת ט\"ו ע\"א)]. מזרע האדומים, שיוחנן כהן גדול הביאם בברית דת היהודים (יוסיפוס). בהיותו כבן 52 מינהו אביו אנטיפטר למושל על ארץ הגליל (שם). הועמד לדין בפני הסנהדרין על הריגה, ונמלט מהם. קיסר רומי עשהו למלך על ישראל (שם). כשמלך, הרג רבים מאד מחכמי ישראל (ב\"ב ג' ע\"ב), ובבא בן בוטא יעץ לו לבנות מחדש את בית המקדש, על מנת לכפר על מעשיו. ואכן זאת עשה - \"מי שלא ראה בנין הורדוס לא ראה בנין נאה מימיו\" (שם). ומן השמים סייעו לו: \"בימי הורדוס שהיו עוסקין בבנין בית המקדש, היו יורדין גשמים בלילה, ויצאו למחר, נשבה הרוח ונתפזרו העבים וזרחה החמה, ויצאו העם למלאכתן, וידעו שמלאכת שמים בידיהם\" (תענית כ\"ג ע\"א).","cat": "sage"},{"i": 1177,"n": "ר' הוריינא אחוי דר' שמואל בר סוסרטיי","l": "ה","b": "אמורא בדור השלישי - הרביעי. אין מימרה בש\"ס ממנו. נזכר בירושלמי (ב\"ב פ\"ט ה\"ג) יחד עם שני אחיו ר' שמואל בר סוסרטיי ואלכסנדרי, בענין ירושתם נראה שאחיו אלכסנדר לא היה חכם.","cat": "sage"},{"i": 1178,"n": "רבי הורקנוס","l": "ה","b": "מובא בבבלי (יבמות ק\"ו ע\"ב). ע\"ע הורקנוס בנו של רבי אליעזר בן הורקנוס.","cat": "sage"},{"i": 1179,"n": "הורקנוס בנו של רבי אליעזר בן הורקנוס","l": "ה","b": "תנא בדור השלישי. בנו של רבי אליעזר הגדול (סנהדרין ס\"ח ע\"א). חלק עם אביו (רב נסים גאון שבת ל\"ה ע\"ב). \"אמר לו הורקנוס בנו: 'בשביל וכו'\". מוזכר תמיד בלי תואר ר'. ו\"יוחסין\" ו\"סה\"ד\" מביאים אותו בתואר רבי. ואולי מה שמצינו במשנה (יבמות ק\"ו ע\"ב) \"וכשהקריא רבי הורקנוס\" - הכוונה להורקנוס זה.","cat": "sage"},{"i": 1180,"n": "הושעיא","l": "ה","b": "רבי הושעיא, הוא רבי אושעיא, ורב אושעיא הוא רב הושעיא.","cat": "sage"},{"i": 1181,"n": "רב הושעיא בר רב יצחק","l": "ה","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (ביצה פ\"א ה\"ז), שם מקשים על דבריו מר' אבהו.","cat": "sage"},{"i": 1182,"n": "רב הושעיא בריה דרב אידי","l": "ה","b": "מובא בבבלי (יבמות ל\"ו ע\"ב). ולפי גיר' רש\"י (שם ל\"ז ע\"א ד\"ה: הכא) צ\"ל: ר' יהושע בריה דרב אידי.","cat": "sage"},{"i": 1183,"n": "ר' הושעיא בריה דר' שמלאי דקיסרין","l": "ה","b": "מובא בויק\"ר (פל\"א - ט'), שם מסר בשמו של ר' יצחק בר זעירא.","cat": "sage"},{"i": 1184,"n": "רבי הושעיא רבה","l": "ה","b": "הוא רבי אושעיא.","cat": "sage"},{"i": 1185,"n": "ר' הושעיא תורגמנא","l": "ה","b": "אמורא ארץ ישראלי. מובא בב\"ר (פנ\"א - ט'). ר' תנחום בר חייא [אמורא ארץ ישראלי בדור השלישי] מסר בשמו (שם).","cat": "sage"},{"i": 1186,"n": "רבי הושעיה בן לוי","l": "ה","b": "והוא רבי יהושע בן לוי (ירו', נזיר פ\"ו ה\"ט).","cat": "sage"},{"i": 1187,"n": "רבי הושעיה בר שמי","l": "ה","b": "והוא רבי אושעיא בר שימי (ירו', פאה פ\"ב ה\"ה).","cat": "sage"},{"i": 1188,"n": "רב הינך","l": "ה","b": "מובא בבבלי: \"א\"ל רב אידי בר אבין לרב חסדאי: 'הכי תנינא לה במתניתא דבי רב הינך'. ואמרי לה 'במתניתא בר הינך כוותיך'\" (פסחים ק\"א ע\"ב).","cat": "sage"},{"i": 1189,"n": "הלל (2)","l": "ה","b": "דור י\"ג להלל הזקן. חי בדור החמישי לאמוראים. שמו ייזכר בזכות שהתקין את הלוח העברי וקידוש החדשים ועיבור השנים עד ימות המשיח, כלשון הרמב\"ן (ספר הזכות, מסכת גיטין, פרק השולח): \"מימי הלל בנו של רבי יהודה נשיאה שנת תר\"ע לשטרות (ד\"א קי\"ח /853) בטלה הסנהדרין בא\"י, ובטלו ממנה מומחים, והוא שתקן סדר העיבור ומנה שנים וקידש חדשים לדורות\". בימיו היו גזירות קשות בא\"י, הנצרות החלה להרים ראש ורבות מישיבות א\"י נחרבו.","cat": "sage"},{"i": 1190,"n": "רב הלל","l": "ה","b": "אמורא בבלי בדור הששי. תלמידו של רב כהנא (שבת ק\"ט ע\"א) ושל רבא (ביצה כ\"ו ע\"ב). חברו של רב אשי (יבמות כ\"א ע\"ב).","cat": "sage"},{"i": 1191,"n": "הלל אחוה דר' גמליאל זוגא","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי, מובא בירושלמי (מו\"ק פ\"ג ה\"ה).","cat": "sage"},{"i": 1192,"n": "רבי הלל בי רב אלם","l": "ה","b": "מובא בירושלמי (כלאים פ\"א ה\"א). נראה, שהוא רבי הלל בריה דר' וולס.","cat": "sage"},{"i": 1193,"n": "רבי הלל בן הליס","l": "ה","b": "מובא בירושלמי (חלה פ\"א ה\"ג), והוא ר' הלל בריה דר' וולס.","cat": "sage"},{"i": 1194,"n": "רבי הלל בן פזי","l": "ה","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (ירו', כתובות פ\"ט ה\"א). נראה, שקיבל גם מרבי יונה (ירו', דמאי פ\"ז ה\"ז). בנו רבי שמעון שאל ממנו (ירו', סנהדרין פ\"ז ה\"ה).","cat": "sage"},{"i": 1195,"n": "ר' הלל בר אלס","l": "ה","b": "הוא רבי הלל בריה דר' וולס.","cat": "sage"},{"i": 1196,"n": "ר' הלל בר ברכיה","l": "ה","b": "מובא באיכ\"ר (פ\"א ל\"א).","cat": "sage"},{"i": 1197,"n": "ר' הלל בר הילני","l": "ה","b": "מובא בויק\"ר (פי\"ב - ה'), והגיר' (איכ\"ר פ\"ב - י\"ב): ר' אילם.","cat": "sage"},{"i": 1198,"n": "רבי הלל בריה דרבי וולס","l": "ה","b": "תנא בדור המעבר שבין התנאים לאמוראים. חי בדורו של רבי, היה מבני פמלייתו ושאל ממנו (ירו', גיטין פ\"ו ה\"ז). קיבל גם מאביו (ירו', כלאים ספ\"ב). ידוע מאמרו: \"מימות משה עד רבי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). היה עשיר מופלג ונתן לרבי במתנה בגד ששוויו שלושים ריבוא דינר (ירו', כלאים פ\"ט ה\"א).","cat": "sage"},{"i": 1199,"n": "רבי הלל בריה דרבי שמואל בר נחמני","l": "ה","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי (שבת פ' ע\"א). בנו של בעל האגדה רבי שמואל בר נחמני. נזכר יחד עם בעל האגדה רבי לוי (ברכות כ\"ח ע\"ב).","cat": "sage"},{"i": 1200,"n": "ר' הלל דכיפרא","l": "ה","b": "אמורא ארץ ישראלי בדור הששי. מובא בירושלמי (פסחים פ\"ח ה\"ח): \"ר' מנא הורי לר' הלל\", אך אין הכרח שהיה תלמידו.","cat": "sage"},{"i": 1201,"n": "הלל הזקן (2)","l": "ה","b": "נשיא ארץ ישראל וראש שושלת הנשיאים של בית הלל, שנמשכה 51 דורות במשך כ - 054 שנה. נצר מגזע בית דוד (ירו', תענית פ\"ד ה\"ב). הוא וחברו שמאי היו אחרון הזוגות. וממנו ואילך החלה תקופת התנאים. נולד בבבל ג' תרמ\"ח (211 לפה\"ס) ומת בארץ ישראל בגיל 021 (בשנת תשס\"ח 8 לס') עלה מבבל בגיל 04 שנה, שימש חכמים 04 שנה ושימש את ישראל 04 שנה (ספרי ברכות סל\"ו). החל את נשיאותו 001 שנה לפני החורבן (שבת ט\"ו ע\"א). שימש את שמעיה ואבטליון (יומא ל\"ה ע\"ב). וזה הביא להתמנותו לנשיא (פסחים ס\"ו ע\"א), כי הלכה נתעלמה מבני בתירה: \"אמרו להן: אדם אחד יש שעלה מבבל, והלל הבבלי שמו, ששימש שני גדולי הדור שמעיה ואבטליון וכו', מיד הושיבוהו בראש ומינוהו נשיא עליהם\". היו לו תלמידים רבים: \"שמונים תלמידים היו לו להלל הזקן, שלשים מהן ראויים שתשרה עליהן שכינה כמשה רבינו, ושלשים מהן ראויים שתעמוד להם חמה כיהושע בן נון, עשרים בינונים. גדול שבכולן - יונתן בן עוזיאל, קטן שבכולן - רבן יוחנן בן זכאי\" (סוכה כ\"ח ע\"א). תלמידיו ותלמידי תלמידיו מכונים \"בית הלל\". תיקן תקנות גדולות: \"והלל התקין פרוזבול מפני תיקון העולם\" (ירו', גיטין פ\"ג). שימש את רבותיו בעוני גדול עד שאמרו עליו \"הלל מחייב את העניים\" (יומא ל\"ה ע\"ב). היה סמל הענווה והסבלנות. ועליו אמרו \"לעולם יהא אדם ענוותן כהלל\" (שבת ל' ע\"ב).","cat": "sage"},{"i": 1202,"n": "רבי הלל חתניה דר' יוסי בר אבון","l": "ה","b": "אמורא ארץ ישראלי בדור הששי. חתנו ותלמידו של רבי יוסי בר אבין (ירו', ברכות פ\"ב ה\"ה).","cat": "sage"},{"i": 1203,"n": "המכריעים לפני חכמים","l": "ה","b": "מובא בבבלי (קידושין כ\"ד ע\"ב), ולא איתפריש מי הם.","cat": "sage"},{"i": 1204,"n": "רב המנונא","l": "ה","b": "בדור המעבר שבין התנאים לאמוראים בבבל. רבו של רבי חנינא בר חמא: כשישב רבי חנינא בר חמא לפני רבי, והוא שאלו: רבי, ממי למדת מקרא, ענה לו: \"אצל רב המנונא בבבל\" (ירו', תענית פ\"ד ה\"ב).","cat": "sage"},{"i": 1205,"n": "רב המנונא בריה דרב אדא בר אהבה","l": "ה","b": "מובא בקה\"ר (פ\"א - ה). יש כאן איזה שיבוש.","cat": "sage"},{"i": 1206,"n": "המנונא בריה דרב יוסף","l": "ה","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ברכות כ\"ד ע\"א). ו\"דק\"ס\" גורס: ר' נחמיה בריה דרב יוסף. לפי גירסתו לא היה אמורא ששמו המנונא בריה דרב יוסף, שכן הוא מוזכר בש\"ס רק בפעם זאת.","cat": "sage"},{"i": 1207,"n": "רב המנונא בריה דרבא מפשרוניא","l": "ה","b": "מובא בבבלי (גיטין מ\"ה ע\"ב). במקום אחר (מנחות מ\"ב ע\"א) הגיר': רב חיננא. היה בדור הרביעי לאמוראי בבל, בזמנו של רבא (חולין קי\"ב ע\"א).","cat": "sage"},{"i": 1208,"n": "רב המנונא ב'","l": "ה","b": "אמורא בבלי בדור השני. תלמיד מובהק של רב (ב\"ק ק\"ו סע\"א), שקרא לו \"בני\" (עירובין נ\"ד ע\"א). בכל מקום שנאמר \"אמרי בי רב\" הכוונה לרב המנונא (סנהדרין י\"ז ע\"ב). היה הזקן שבחבורה (ירו', מעשרות ספ\"ד). חברו של רב חסדא (שבת צ\"ז ע\"א), ואולי הוא רב המנונא שקבע את הברכה \"אשר בחר בנו מכל העמים ונתן לנו את תורתו וכו'\" (ברכות י\"א ע\"ב).","cat": "sage"},{"i": 1209,"n": "רב המנונא ג'","l": "ה","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (שבועות ל\"ד ע\"ב). נראה, שגם היה תלמידו של רב הונא (קידושין כ\"ט ע\"ב). תלמיד חבר לרב חסדא (יבמות פ\"ג ע\"ב תד\"ה: אמר). רבו של רבי זירא (זבחים ק\"ה ע\"ב). נפטר יחד עם רבה בר רב הונא (מו\"ק כ\"ה ע\"ב).","cat": "sage"},{"i": 1210,"n": "רב המנונא ד'","l": "ה","b": "אמורא בבלי בדור הרביעי. חברו המובהק של רבא (תמורה כ\"ה ע\"ב), ושל אביי ושקיל וטרי עמם (נזיר ס\"ד ע\"ב). רבו של רב פפא (נדה כ\"ז ע\"א).","cat": "sage"},{"i": 1211,"n": "רב המנונא זוטא","l": "ה","b": "מובא בבבלי (ברכות ל\"א ע\"א). רב המנונא זוטי.","cat": "sage"},{"i": 1212,"n": "רב המנונא זוטי","l": "ה","b": "אמורא בבלי בדור השלישי. נשארה בידינו תפילת וידוי שלו, שבה מסיימים את תפילת יום כיפור: \"אלקי עד שלא נוצרתי איני כדאי וכו'\" (ברכות י\"ז ע\"א), ורבא נהג לסיים בוידוי זה את תפילתו (שם). היה בחתונת מר, בנו של רבינא, ושר שם שיר מוסר בלשון חכמים (ברכות ל\"א ע\"א).","cat": "sage"},{"i": 1213,"n": "רב המנונא סבא","l": "ה","b": "אמורא בבלי בדור השני. תלמידו של רב (פסחים ק\"ה ע\"א).","cat": "sage"},{"i": 1214,"n": "ר' המנונא סבא","l": "ה","b": "תנא המוזכר ב\"זהר\", נפטר לפני רבי שמעון בר יוחאי. \"סה\"ד\" תמה על ה\"יוחסין\" ו\"שארית יוסף\" שלא הזכירוהו.","cat": "sage"},{"i": 1215,"n": "רב המנונא ספרא","l": "ה","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (ב\"ב פ\"ו ה\"ב) ששאל לרב חנינא ולא השיבו, ושאל לרבי ירמיה.","cat": "sage"},{"i": 1216,"n": "רבי ווא","l": "ו","b": "הוא רבי אבא. כך מכונה בירושלמי.","cat": "sage"},{"i": 1217,"n": "רבי וולוס","l": "ו","b": "ע\"ע רבי וולס.","cat": "sage"},{"i": 1218,"n": "רבי וולס","l": "ו","b": "מן התנאים האחרונים בדור החמישי. אביו ורבו של רבי הלל בר ר' וולס (ירו', כלאים ספ\"ב) וגיר' רש\"י: רבי וולוס (סנהדרין ל\"ו ע\"א).","cat": "sage"},{"i": 1219,"n": "ויידא","l": "ו","b": "מובא בירושלמי: \"ויידא אמר דא וכו'\" (פסחים פ\"ז הי\"ג), ופירש \"קרבן העדה\" ד\"ה: ויידא אמר דא: \"והיכן אמר דבר זה\". \"ציון ירושלים\" כתב שם: \"ויידא אמר דא, עיין 'קרבן העדה' שפירש היכן אמר דבר זה, ובאמת אין הפירוש כן, כי ויידא שם חכם, וכן משמעות הכ\"מ פ\"י מקרבן פסח ה\"ד וכו' וכדומה לי שבכה\"ג סוף או\"ח ראיתי שכתב זה\" עכ\"ל. וכתב \"שיירי כנסת הגדולה\" ב\"כללי התלמוד\" אות צד\"י: \"ויידא שם חכם בירושלמי דפסחים פרק צולין: ויידא אמר דא וכו', הביא הירושלמי הזה הרב הכ\"מ הלכות קרבן פסח וכו'\".","cat": "sage"},{"i": 1220,"n": "ויתור מעונה","l": "ו","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי: \"רבי אבדימי דציפורי בשם רב יחונה משום ויתור מעונה\" (כתובות פ\"א ה\"ב). \"קרבן העדה\" ו\"פני משה\" פירשו שהוא חכם.","cat": "sage"},{"i": 1221,"n": "וסטיני","l": "ו","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\"ל (ב\"מ קי\"ז ע\"א). השם בא בשינויים: יוסטא יוסטני יוסטיני.","cat": "sage"},{"i": 1222,"n": "ורדימס","l": "ו","b": "תנא בדור החמישי. בנו של רבי יוסי בר חלפתא מובא בבבלי: \"היינו ורדימס, היינו מנחם\" (שבת קי\"ח ע\"ב). ע\"ע רבי מנחם בר' יוסי בן חלפתא.","cat": "sage"},{"i": 1223,"n": "זבדא","l": "ז","b": "ע\"ע רב זבדי.","cat": "sage"},{"i": 1224,"n": "זבדא בר לוי","l": "ז","b": "מובא בבבלי (כריתות ה' ע\"א), והוא זבדי בר לוי.","cat": "sage"},{"i": 1225,"n": "ר' זבדא חתניה דר' לוי","l": "ז","b": "מובא ברו\"ר (פ\"ב - י'), ונראה שצ\"ל: ר' זכריה חתניה דר' לוי.","cat": "sage"},{"i": 1226,"n": "רב זבדי","l": "ז","b": "אמורא בבלי בדור השלישי. תלמידו של ר\"ה. מובא בבבלי (ערכין י\"ג ע\"ב).","cat": "sage"},{"i": 1227,"n": "זבדי בר לוי","l": "ז","b": "אמורא ארץ ישראלי בדור הראשון. חברו של ר' יהושע בן לוי. אחרי פטירתו של ריב\"ל, נתגלה לו בחלומו והראה לר' זבדי את פניהם של צדיקים ושל רשעים שכבר מתו (קה\"ר פ\"ט - י'). באגדה נזכר פעמים רבות. בהלכה מובא פעם בבבלי: \"אמר ר' יוחנן תני זבדי בר לוי\" (זבחים כ\"ח ע\"ב): ופעם בירושלמי, שר' אושעיא רבה שלחו להפריש תרומה ומעשרות (דמאי רפ\"ז).","cat": "sage"},{"i": 1228,"n": "רב זבדי בריה דרבי יעקב בר זבדי","l": "ז","b": "אמורא ארץ ישראלי בדור החמישי. בנו של האמורא רבי יעקב בר זבדי (תלמידו של רבי אבהו). מסר בשם רבי יונה (ירו', ברכות פ\"א ה\"ב).","cat": "sage"},{"i": 1229,"n": "ר' זבדיה חתניה דר' לוי","l": "ז","b": "מובא במדרש שמואל (פ\"ב - ג'), ונראה שצ\"ל: ר' זכריה חתניה דר' לוי.","cat": "sage"},{"i": 1230,"n": "זבולון בן דן","l": "ז","b": "תלמיד בימי שמואל בדור הראשון לאמוראי בבל, שלימדו אבי אביו מקרא ומשנה וגמרא הלכות ואגדות (קידושין ל' ע\"א).","cat": "sage"},{"i": 1231,"n": "רב זביד","l": "ז","b": "אמורא בבלי בדור החמישי. עמד בראש ישיבת פומבדיתא אחרי ר' נחמן בר' יצחק, בשנים ד' קל\"ו - קמ\"ד (673 - 483) (\"אגרת רב שרירא גאון\"). היה תלמידו של רבא ומסר הרבה בשמו (שבת צ\"ג ע\"א) וכן של אביי (סוטה ל\"ב ע\"ב). מחבריו היו ר\"פ (ברכות מ\"ה ע\"ב) ורב מרי (חולין קי\"ז ע\"א). ומתלמידיו היה רב כהנא [רבו של רב אשי] (ב\"מ ק\"א ע\"א). אמימר אמר משמו (חולין ע\"ו ע\"ב). החמיר על אנשי ריש גלותא והשקוהו כוס חומץ ומת (ע\"ז ל\"ח ע\"ב).","cat": "sage"},{"i": 1232,"n": "רב זביד אבוה דר' שמעון בר זביד","l": "ז","b": "מובא בבבלי (ברכות ל\"ח ע\"א) לגיר' \"דק\"ס\", ולפנינו הגיר': בר רב זביד אחוה דר' שמעון בר ר' זביד.","cat": "sage"},{"i": 1233,"n": "רב זביד בר' אושעיא","l": "ז","b": "מובא בבבלי (יבמות צ\"ו ע\"א). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: בדבי ר' אושעיא\".","cat": "sage"},{"i": 1234,"n": "ר' זביד מנהרדעא","l": "ז","b": "אמורא בבלי בדור החמישי. והוא אינו רב זביד סתם (קידושין ע\"ב ע\"ב רש\"י). רבו המובהק של רב כהנא (יבמות י\"ח ע\"ב) ישב לפניו הרבה, וכשמת הספידו רב כהנא (מו\"ק כ\"ז ע\"ב).","cat": "sage"},{"i": 1235,"n": "זבידא","l": "ז","b": "חי בבבל בדור הששי. בגמרא מסופר: אמר רב אשי: 'אמר לי זבידא' (ע\"ז ט\"ז ע\"א) פרש\"י \"פטם היה\", ונראה שלא נמנה על החכמים.","cat": "sage"},{"i": 1236,"n": "רבי זבידא","l": "ז","b": "אמורא ארץ ישראלי בדור הרביעי. ר' קרוספא (תלמידו ר' יוחנן) אמר לו: \"לא תתניה הכי\" (ירו', מע\"ש ספ\"א). מסר מאמרי הלכה בשם ר' אבא בר ממל (ירו', ב\"ק פ\"ט ה\"ז) ובשם ר' יסא [הוא ר' אסי] (ירו', יומא פ\"ח ה\"ז).","cat": "sage"},{"i": 1237,"n": "ר' זבידי חתניה דר' לוי","l": "ז","b": "מובא בירושלמי (כלאים פ\"א ה\"ח), ונראה שצ\"ל: ר' זכריה חתניה דר' לוי.","cat": "sage"},{"i": 1238,"n": "זוג","l": "ז","b": "מובא בבבלי (סנהדרין י\"ב ע\"א). ע\"ע זוגא דמן הדייב.","cat": "sage"},{"i": 1239,"n": "זוגא (2)","l": "ז","b": "אמורא בבלי בדור הראשון היה תלמידו של רבי (ירו', נדה פ\"ג ה\"ב), חברם של רבי חמא אבי ר' אושעיה ושל בר קפרא (שם) ו\"פני משה\" מפרש: \"זוגא: שם אמורא\". ובמקום אחר לפנינו: זונא (ירו', מע\"ש רפ\"ה) וגיר' \"יוחסין\" ו\"סה\"ד\": זוגא.","cat": "sage"},{"i": 1240,"n": "זוגא דמהדייב","l": "ז","b": "מובא בבבלי (מו\"ק כ\"ח ע\"א). ע\"ע זוגא דמן הדייב.","cat": "sage"},{"i": 1241,"n": "זוגא דמן הדייב","l": "ז","b": "מובא בבבלי (מו\"ק כ\"ח ע\"א: נדה כ\"א ע\"א). ומחלוקת בין רש\"י ל\"ערוך\", רש\"י מפרש שני תלמידי חכמים מאותו מקום (נדה שם), וכעין זה פירש\"י: \"שלחו ליה לרבא זוג שני תלמידי חכמים\" (סנהדרין י\"ב ע\"א). ותוספות כתבו: פי' ב\"ערוך\" שם חכם (נדה כ\"ה ע\"ב ד\"ה: זוזא) ובירושלמי: \"שאלתי לרבי יצחק בר אליעזר ואמר לי: 'כך נהג זוגא'\" (דמאי פ\"ב ה\"א) ופירש \"פני משה\": \"כך נהג זוגא דרבנן\". ו\"סה\"ד\" כתב: \"ונראה כפי' ה'ערוך' דזווא או זוגא הוא שם חכם לא לשון שנים\".","cat": "sage"},{"i": 1242,"n": "רבי זוהמאי","l": "ז","b": "תנא בדור החמישי. מובא בבבלי (ברכות נ\"ג ע\"ב) יחד עם רבי זילאי ורבי זיואי.","cat": "sage"},{"i": 1243,"n": "זווא","l": "ז","b": "כך הגיר' לפי \"הערוך\". (מו\"ק כ\"ח ע\"א) ע\"ע זוגא דמן הדייב.","cat": "sage"},{"i": 1244,"n": "זוזא","l": "ז","b": "ע\"ע זוגא דמן הדייב.","cat": "sage"},{"i": 1245,"n": "זוטי","l": "ז","b": "מובא בבבלי (שבת קנ\"ז ע\"א). ע\"ע רב זוטי.","cat": "sage"},{"i": 1246,"n": "רב זוטי","l": "ז","b": "אמורא בבלי בדור החמישי. מובא שלוש פעמים בבבלי (שבת קנ\"ז ע\"א: נדרים ע\"ז ע\"א: יבמות כ\"ה ע\"ב). נראה, שהיה התנא שונה הברייתות בישיבת רב פפי.","cat": "sage"},{"i": 1247,"n": "רב זוטי דבי רב פפי","l": "ז","b": "ע\"ע רב זוטי.","cat": "sage"},{"i": 1248,"n": "רב זוטרא","l": "ז","b": "מובא בבבלי (מכות ו' ע\"ב) שמתקיף על דברי רב נחמן. ואולי הוא מר זוטרא.","cat": "sage"},{"i": 1249,"n": "רבי זוטרא","l": "ז","b": "תנא דברייתא בדור החמישי. יש סבורים שהיה בבלי. חלק עם ר' יאשיה (ברכות י\"ג ע\"ב).","cat": "sage"},{"i": 1250,"n": "רב זוטרא בר טוביא","l": "ז","b": "אמורא בבלי בדור החמישי. בש\"ס אין מימרה בשמו. מובא בבבלי בהקשר למתנה שאמו נתנה לו, ובא הענין לפני ביבי בר אביי (ב\"ב קנ\"א ע\"א).","cat": "sage"},{"i": 1251,"n": "רב זוטרא בר טוביה","l": "ז","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב. מסר כמה ממאמריו של רב בהלכה ובאגדה (ברכות מ\"ג ע\"ב). כן היה תלמידו של רב יהודה. פעם חש שרב יהודה נפגע מדבריו, ונהג בעצמו נזיפות ליום אחד (מו\"ק ט\"ז ע\"ב). כן מסר מאמר אחד בשם ר\"נ (יומא פ\"ו ע\"ב).","cat": "sage"},{"i": 1252,"n": "רב זוטרא בריה דרב זורא","l": "ז","b": "כך גירסת \"יתו\"א\", ולפנינו רב זוטרא בריה דרבי זירא.","cat": "sage"},{"i": 1253,"n": "רב זוטרא בריה דרב מרי","l": "ז","b": "ע\"ע מר זוטרא בריה דרב מרי.","cat": "sage"},{"i": 1254,"n": "רב זוטרא בריה דר' זירא","l": "ז","b": "מובא בבבלי (שבת קנ\"ז ע\"א). נראה, שהוא בנו של רבי זירא.","cat": "sage"},{"i": 1255,"n": "רב זוטרא בריה דר' זעירא","l": "ז","b": "הוא רב זוטרא בריה דר' זירא.","cat": "sage"},{"i": 1256,"n": "זוטרא חסידא","l": "ז","b": "ע\"ע מר זוטרא חסידא.","cat": "sage"},{"i": 1257,"n": "רב זוטראי","l": "ז","b": "מובא בבבלי (שבת קכ\"ד ע\"ב) שהקשה על דברי רב יהודה אמר שמואל. \"דק\"ס\" גורס: 'מר זוטרא'. ולגירסתו לא היה כלל חכם בשם זה.","cat": "sage"},{"i": 1258,"n": "זונא","l": "ז","b": "מובא (ירו', מע\"ש פ\"ד ה\"א). שאל מרבי וכנראה שהוא זונין ששאל מרבי (ע\"ע).","cat": "sage"},{"i": 1259,"n": "זונין (2)","l": "ז","b": "ממונה של ר\"ג הנשיא. חי בדור השני לתנאים (פסחים מ\"ט ע\"א). בנו הוא התנא בייתוס בן זונין. יש זונין ששאל לר\"ע (ע\"ז נ\"ה ע\"א) ופרש\"י: ישראל היה. \"חידושי אגדות\" מפרש שהיה עכו\"ם. \"יתו\"א\" גרס: זונן רבה, ואם כן לדעתו היה חכם.","cat": "sage"},{"i": 1260,"n": "רבי זיואי","l": "ז","b": "תנא בדור החמישי. מובא בבבלי, שחלק עם ר' זילאי ור' אחא (ברכות נ\"ג ע\"ב).","cat": "sage"},{"i": 1261,"n": "זיותאי","l": "ז","b": "תנא בדור החמישי. חתנו של ר\"מ מובא בקה\"ר (פ\"ט - ח') שאמר משום ר\"מ. אותו דבר מובא בבבלי, אך בלי הזכרת שמו המלא (שבת קנ\"ג ע\"א).","cat": "sage"},{"i": 1262,"n": "ר' זיכיי","l": "ז","b": "מובא בירו', (סוכה פ\"ד ה\"ג) והוא ר' זכאי תלמידו דר' יוחנן.","cat": "sage"},{"i": 1263,"n": "רבי זילאי","l": "ז","b": "תנא בדור החמישי. מובא בבבלי (ברכות נ\"ג ע\"ב), חלק עם רבי זיואי ור' אחא.","cat": "sage"},{"i": 1264,"n": "רבי זינון החזן","l": "ז","b": "חזן ביבנה בדור השני - השלישי של התנאים. נוכח ביבנה בעת שהעבירו את ר\"ג מנשיאותו (ירו', ברכות פ\"ד ה\"א): \"אמרו לרבי זינון החזן: 'אמור' התחיל ואמר וכו'\" ובבבלי הגיר': \"ואמרו לחוצפית המתורגמן עמוד [שתוק], ועמד\" (ברכות נ\"ז ע\"ב).","cat": "sage"},{"i": 1265,"n": "זירא","l": "ז","b": "פעמים זעירא ופעמים זעירי.","cat": "sage"},{"i": 1266,"n": "רב זירא","l": "ז","b": "הוא רבי זירא (ע\"ע).","cat": "sage"},{"i": 1267,"n": "רבי זירא","l": "ז","b": "מגדולי האמוראים בדור השלישי. ידוע גם כר' זעירא (ברכות נ\"ה ע\"ב). נקרא רב זירא, וכשעלה לא\"י ונסמך קראוהו רבי זירא (כתובות מ\"ג ע\"ב ברש\"י). ותוספות חולקים על רש\"י (מנחות מ' ע\"ב) וסוברים שהיו שנים: רב זירא ורבי זירא. נולד בבבל. למד בסורא אצל רב הונא (מנחות כ\"ט ע\"א), ובפומבדיתא לפני רב יהודה (יבמות ל\"ח ע\"ב). מסר הרבה בשם רב (שבת כ\"א ע\"ב) ובשם שמואל (שם נ\"ג ע\"א). לאחר שעלה לארץ ישראל (כתובות קי\"ב ע\"א) צם 001 תעניות, כדי לשכוח את דרכי לימודם של הבבלים (ב\"מ פ\"ה ע\"א). לבסוף אף נהג לומר: \"בבלאי טפשאי\" (ביצה ט\"ז ע\"א). בא\"י קיבל מרבי יוחנן (קידושין נ\"ב ע\"א), מריש לקיש (עירובין פ' ע\"א), ומר\"א (ירו', תרומות פי\"א סה\"ג), מר' אמי (חולין כ\"א ע\"א) ומר' אסי (ב\"ב פ\"ד ע\"ב). הקרוב אליו ביותר מבין תלמידיו הרבים היה רבי ירמיה, אף הוא בבלי, וקרא לו \"ירמיה בני\" (מו\"ק ד' ע\"א). צם 001 תעניות כדי להנצל מאש גיהנום (ב\"מ פ\"ה ע\"א). התפרנס מפשתן. אבי ר\"ז, היה גבאי המלך (סנהדרין כ\"ה ע\"ב). בנו רבי אהבה, היה אמורא בדור הרביעי (עירובין צ\"ו ע\"ב). האריך ימים (מגילה כ\"ח ע\"א).","cat": "sage"},{"i": 1268,"n": "רבי זירא בר אדא","l": "ז","b": "מובא בבבלי (כריתות כ\"ז ע\"א) והוא ט\"ס וצ\"ל: רבי חייא בר אבא.","cat": "sage"},{"i": 1269,"n": "ר' זירא בר ממל","l": "ז","b": "מובא בבבלי (קידושין ט' ע\"א). כתב \"סה\"ד\": \"ומצינו ר\"ז אמר לרבי אבא בר ממל, ואולי ט\"ס כאן\".","cat": "sage"},{"i": 1270,"n": "רבי זירא בר רב","l": "ז","b": "אמורא בדור השלישי. מובא ב\"זוהר\": \"רבי אבא הוה אזל ללוד פגע ביה ר' זירא בר רב\" (נשא קמ\"ח).","cat": "sage"},{"i": 1271,"n": "רב זירא ב'","l": "ז","b": "אמורא בבלי בדור הרביעי - החמישי. תלמידו של רב יוסף (ב\"ב קנ\"ד ע\"ב). חברם של אביי (כריתות י\"ב ע\"ב) ושל רבא (קידושין ע\"ג ע\"א). עלה לארץ ישראל והיה תלמידו המובהק של רבי ירמיה (ירו', ברכות פ\"ו ה\"ו) ותלמידו של ר' יוסי (ירו', כתובות פ\"א ה\"ט) ושל ר' מנא (ירו', נזיר פ\"ט ה\"ב). לאחר פטירתו של רב יוסף היו ארבעה מועמדים לתפקיד ראש ישיבת פומבדיתא: אביי, רבא, רבי זירא ורבה בר מתנה, ומתוכם נבחר אביי (סוף הוריות).","cat": "sage"},{"i": 1272,"n": "רבי זכאי (2)","l": "ז","b": "אמורא בבלי בדור השני. עלה לארץ ישראל ושימש \"תנא\" שונה ברייתות, בישיבתו של רבי יוחנן: \"תני רבי זכיי קומי רבי יוחנן וכו', א\"ל ר\"י: בבלייא עברת בידך תלתא נהרין ואיתברת\" (ירו', יבמות פ\"ח ה\"ג). נראה שנסמך, שכן קראו לו רבי זכאי. רב יהודה ורבי אבא למדו בבי מעצרתא דבי רב זכאי (עירובין מ\"ט ע\"א). ומר עוקבא קיבל ממנו (סנהדרין ל' ע\"א).","cat": "sage"},{"i": 1273,"n": "רבי זכאי דאלכסנדריאה","l": "ז","b": "אמורא ארץ ישראלי בדור החמישי. ישב באלכסנדריה במצרים. נראה שלמד בישיבות א\"י ונסמך וקיבל תואר רבי. רבי יוסי בר בון אמר עליו, שהוא יודע למתק את הים הגדול ויודע את חשבון המים שבים (ירו', ע\"ז פ\"ב ה\"ח).","cat": "sage"},{"i": 1274,"n": "רבי זכאי דכבול","l": "ז","b": "אמורא בדור הראשון. היה מגדולי עירו (ויק\"ר פ\"כ - ג'). רבי חיננא בר אנדריי (מדור הרביעי - החמישי) מסר בשמו (ירו', מגילה פ\"ד ה\"ה). יהודה והלל (נכדי רבי) התאכסנו אצלו בשהותם בעיר כבול (שמחות פ\"ח).","cat": "sage"},{"i": 1275,"n": "רבי זכאי דשאב","l": "ז","b": "אמורא בדור השלישי - הרביעי. מובא מספר פעמים במדרשים (במד\"ר פי\"ז - ג'). מסר בשם רבי שמואל בר נחמן (תנחומא, הוצאת בובר, פ' חוקת סי' י\"ח).","cat": "sage"},{"i": 1276,"n": "זכאי טבחא","l": "ז","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי יוחנן (ירו', מגילה פ\"ד ה\"א).","cat": "sage"},{"i": 1277,"n": "ר' זכאי רבה","l": "ז","b": "מובא בב\"ר (פצ\"ז - ג').","cat": "sage"},{"i": 1278,"n": "זכיי","l": "ז","b": "ע\"ע רבי זכאי.","cat": "sage"},{"i": 1279,"n": "רבי זכיי רבי אלכסנדריה","l": "ז","b": "מובא בירושלמי (יבמות פ\"ז ה\"ה), וצ\"ל: רבי זכאי דאלכסנדריה.","cat": "sage"},{"i": 1280,"n": "רבי זכריה","l": "ז","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי (ירו', סנהדרין פ\"א ה\"א). מסר עם ר' עזריה (תלמידו של רבי מנא) בשם ר' יצחק בר מריון (מדרש שמואל פכ\"ב - ה').","cat": "sage"},{"i": 1281,"n": "רבי זכריה בן אבקולס","l": "ז","b": "תנא בדור הראשון. חי בירושלים בדור החורבן. הוא שעיכב את הקרבת קרבנו של קיסר רומי, לאחר שהטילו בו מום. דבר זה גרם לחורבן בית המקדש השני (גיטין נ\"ו ע\"א), ור' יוחנן אמר: \"ענותנותו של ר' זכריה בן אבקולס החריבה את ביתנו ושרפה את היכלנו והגליתנו מארצנו\" (שם). היה בין החכמים שהשתתפו בסעודת קמצא ובר קמצא ולא מיחה כשגירשו את בר קמצא (איכ\"ר פ\"ד ג'). מובאת ממנו הלכה אחת (שבת קמ\"ג ע\"א).","cat": "sage"},{"i": 1282,"n": "רבי זכריה בן הקצב","l": "ז","b": "תנא בדור הראשון. חי בירושלים בדור החורבן ונשבע: \"המעון הזה לא זזה ידה מתוך ידי [נשבע שאשתו לא נאנסה], משעה שנכנסו גויים לירושלים ועד שיצאו\", אך עדותו לא נתקבלה שכן לא היו לו עדים ואין אדם מעיד על עצמו (כתובות כ\"ז ע\"א), והיות והיה כהן אסרו עליו חכמים את אשתו, ואעפ\"כ לא שילחה אלא ייחד לה בית בחצרו ולא היה מתייחד עמה אלא בפני בניה (שם). נזכר יחד עם ר' יוסי הכהן, תלמיד רבי יוחנן בן זכאי (עדויות פ\"ח מ\"ב). שמואל אמר: \"אפס זכריה\" (ב\"ב קי\"א ע\"א) ופירש רשב\"ם: \"אין הלכה כמותו\".","cat": "sage"},{"i": 1283,"n": "זכריה בן קבוטל","l": "ז","b": "חכם בדור הראשון של תנאים חי בזמן הבית. סיפר שפעמים רבות קרא לפני כהן גדול ביום כיפור בספר דניאל (יומא י\"ח ע\"ב) בן בנו היה מהתנאים בדור השלישי, ששלחוהו יחד עם יוסי בן כיפור לר' חנניה בן אחי ר' יהושע לצוות עליו להפסיק לעבר שנים בבבל (ברכות ס\"ג ע\"א).","cat": "sage"},{"i": 1284,"n": "ר' זכריה חתניה דר' לוי","l": "ז","b": "אמורא ארץ ישראלי בדור הרביעי. חתנו של בעל האגדה המפורסם רבי לוי. יש ממנו מאמרי הלכה (ירו', פסחים פ\"א ה\"א) ומאמרי אגדה (ירו', תענית פ\"ד ה\"ה). היו מלעיזים עליו שאינו צריך ליטול מן הצדקה ונוטל, וכשנפטר התברר כי את שלקח נתן לאחרים (ירו', סוף פאה).","cat": "sage"},{"i": 1285,"n": "ר' זכריה טבחא","l": "ז","b": "מובא בפס' רבתי (ר\"פ אפרים), וצ\"ל: רבי זכאי טבחא.","cat": "sage"},{"i": 1286,"n": "רבי זמינא","l": "ז","b": "אמורא בדור הרביעי. חברו של ר' יונה (ירו', בכורים פ\"ג סה\"ג).","cat": "sage"},{"i": 1287,"n": "זעיר בן חנינא","l": "ז","b": "מובא בירושלמי (תרומות ספ\"ח). נראה, שהוא זעירא בר חיננא.","cat": "sage"},{"i": 1288,"n": "זעירא","l": "ז","b": "פעמים זירא או זעירי.","cat": "sage"},{"i": 1289,"n": "ר' זעירא","l": "ז","b": "מובא בבבלי (ברכות נ\"ה ע\"ב), והוא רבי זירא.","cat": "sage"},{"i": 1290,"n": "זעירא א'","l": "ז","b": "תנא בדור השלישי. \"דאמר רבי יאשיה: שלשה דברים סח לי זעירא מאנשי ירושלים\" (סוטה כ\"ה ע\"א, פרש\"י שהיה מאנשי ירושלים). ובירושלמי הגיר': \"משום אנשי ירושלים\" (סוטה פ\"ד ה\"ב וסנהדרין פ\"ח ה\"ו) וכן בספרי (פ' תצא): \"סח לי זעירא משום אנשי ירושלים וכו' וכשבאתי אצל רבי יהודה בן בתירא לנציבין על שנים הודה לי וכו'\" (ירו', סנהדרין שם).","cat": "sage"},{"i": 1291,"n": "רבי זעירא בר אבונא","l": "ז","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם רבי ירמיה (ירו', שבת פ\"א סה\"ד).","cat": "sage"},{"i": 1292,"n": "רבי זעירא בר בא","l": "ז","b": "מובא בירושלמי (נזיר פ\"ז ה\"א), ונראה שט\"ס בשם וצ\"ל: רבי זעירא [הוא רבי זירא].","cat": "sage"},{"i": 1293,"n": "זעירא בר חייא בר אשי","l": "ז","b": "אמורא בבלי בדור השלישי. חלק עם רבי זעירא (ירו', שבת פ\"ז ה\"ב).","cat": "sage"},{"i": 1294,"n": "זעירא בר חיננא","l": "ז","b": "אמורא ארץ ישראלי בדור השני - השלישי. בירושלמי נזכר בלי תואר \"רבי\". ובבבלי נזכר רק פעם אחת בתואר \"רבי\" (נדה נ' ע\"ב). מסר בשם רבי חנינא [בר חמא] (ירו', סנהדרין רפ\"ד). פעם נשבה בידי גזלנים ונעשה לו נס וניצל (ירו', תרומות ספ\"ח).","cat": "sage"},{"i": 1295,"n": "רבי זעירא בר חמא","l": "ז","b": "חי בארץ ישראל בדור השני לתנאים. סיפר לרב יוסף בנו של ריב\"ל ממנהגי אביו ביום הכיפורים (יומא ע\"ח ע\"א). נראה, שהגיע לזקנה מופלגת, שכן התארחו אצלו ריב\"ל (מן הדור הראשון) וגם ר' אמי ור' אסי [מן הדור השלישי] (שם). נראה, שגם ר\"א התאכסן אצלו (ירו', ביצה פ\"ג ה\"ח).","cat": "sage"},{"i": 1296,"n": "ר' זעירא בר חנינא","l": "ז","b": "מובא בבבלי (נדה נ' ע\"ב), והוא זעירא בר חיננא.","cat": "sage"},{"i": 1297,"n": "זעירא בר ר' אבהו","l": "ז","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של האמורא המפורסם ר' אבהו. מושבו היה בקיסרין ושם היה דורש (ב\"ר פ\"ג - ו'). מסר בשם אביו (ירו', ברכות פ\"ט ה\"א).","cat": "sage"},{"i": 1298,"n": "ר' זעירא דכפר ראמין","l": "ז","b": "מובא ב\"זוהר\" (שמיני מא). גם בנו רבי יוסי נמנה על החכמים והיה תלמידו.","cat": "sage"},{"i": 1299,"n": "זעירא יתמא","l": "ז","b": "מובא: \"אמר רב אשי אנא ורב כהנא חתמינן אשטרא דאימיה דזעירא יתמא\" (גיטין נ\"ב ע\"ב). אין ראיה שנמנה עם החכמים.","cat": "sage"},{"i": 1300,"n": "זעירא מדיהבות","l": "ז","b": "אמורא בבלי בדור הששי. מצינו שהקשה לרבינא (תענית ז' ע\"ב). רש\"י גורס: מר זעירא מדיהבת.","cat": "sage"},{"i": 1301,"n": "ר' זעירא תנאי","l": "ז","b": "מובא בירושלמי: \"ר' זעירא תנאי, אחוה דר' חייא בר אבא\" (ברכות פ\"א ה\"א).","cat": "sage"},{"i": 1302,"n": "זעירי","l": "ז","b": "אמורא ארץ ישראלי בדור השני - השלישי. ירד לבבל (ברכות כ\"ב ע\"א). תלמידו המובהק של רבי יוחנן (קידושין ע\"א ע\"ב). קיבל מרבי חייא [שהיה רבו של רבי יוחנן] (שבת קנ\"ו ע\"א). היה חברו של רב (ב\"ק ל' ע\"ב). תלמידו המובהק היה רב חייא בר אשי (שבת ק\"ט ע\"ב). קיבלו ממנו גדולי תלמידי רב יהודה (מנחות כ\"א ע\"א), רב גידל (יומא ע\"ז ע\"ב), רב חסדא (ברכות מ\"ג ע\"א), וכן רב יוסף ורבה (נדרים מ\"ו ע\"ב). רבא אמר: \"כל מתניתא דלא מפרשא לה רב זעירי, לא מיפרשא\" (זבחים מ\"ג ע\"ב). \"סה\"ד\" כתב: \"נראה תיבת רב ט\"ס, כי בכל מקום אינו נקרא בשם רב זעירי\".","cat": "sage"},{"i": 1303,"n": "זקני דרום","l": "ז","b": "מובאים בבבלי (זבחים כ\"ב ע\"ב) ור\"ל הקשה עליהם. ותוספות כתבו (שם כ\"ג ע\"א ד\"ה: זקני): \"וזקני דרום תנאי הוו\".","cat": "sage"},{"i": 1304,"n": "זקני הגליל","l": "ז","b": "מובאים בירושלמי (נדרים פ\"ט ה\"א). ר\"ש בר רבי לא מצא פתח להתרת נדר, עד שבא אחד מזקני גליל (שם).","cat": "sage"},{"i": 1305,"n": "זקנים הראשונים","l": "ז","b": "קדומים מרבי עקיבא: \"זקנים הראשונים אמרו וכו', עד שבא ר\"ע וכו'\" (שבת ס\"ד ע\"ב).","cat": "sage"},{"i": 1306,"n": "ר' זריקא (2)","l": "ז","b": "אמורא בבלי בדור השלישי. תלמידם של ר\"ה (סוטה כ\"א ע\"ב), רב יהודה (ביצה ז' ע\"ב) ורב המנונא (ירו', עירובין רפ\"י). עלה לארץ ישראל וקיבל מרבי יוחנן (גיטין כ\"ג ע\"א) ומריש לקיש (ברכות י\"א ע\"ב) ומר\"א (סוטה ד' ע\"ב). אח\"כ קיבל גם מרבי אמי (ברכות ג' ע\"ב). חבריו היו רבי ביבי (מנחות ק\"ג ע\"ב) ורבי ירמיה (גיטין מ\"ד ע\"א). רבי חזקיה אמר משמו (ירו', פ\"א ה\"א).","cat": "sage"},{"i": 1307,"n": "ר' זריקן","l": "ז","b": "הוא ר' זריקא.","cat": "sage"},{"i": 1308,"n": "ר' זריקן בר חמוי דר' זריקן","l": "ז","b": "מובא בירושלמי (ברכות ספ\"ז).","cat": "sage"},{"i": 1309,"n": "רב חבוניה","l": "ח","b": "כך גירסת \"יתו\"א\" ולפנינו (חולין נ\"א ע\"א) רב חביבא, ובאמת אין אנו מוצאים בשום מקום בתלמוד רב חבוניה, אך לגירסתו היה אמורא בבלי בדור החמישי - הששי.","cat": "sage"},{"i": 1310,"n": "רב חביבא (2)","l": "ח","b": "אמורא בבלי בדור הששי. בנו של רבינא (חברו של רב אשי). נשא לאשה את בתו של רב חביבא (נדה ס\"ו סע\"א), לגיר' הרי\"ף, הרא\"ש והרשב\"א ולפנינו: רב חנינא. חלק עם מר בר רב אשי (ב\"ב קמ\"ג ע\"ב). יתכן לומר שרב חביבא סתם הוא רב חביבא מסורא דפרת, ששקיל וטרי תמיד עם רבינא (מו\"ק כ' ע\"א: כ\"ד ע\"ב).","cat": "sage"},{"i": 1311,"n": "רב חביבא בר סורמקי","l": "ח","b": "אמורא בבלי בדור הששי. \"אמר רב חביבא: 'אשתעי לי רב חביבא בר סורמקי וכו'\" (ב\"מ פ\"ה ע\"ב). היה בארץ ישראל: \"כי סליק רב חביבא בר סורמקי, אמרה וכו'\" (יומא י' ע\"א). וגירסת \"יתו\"א\": סורמסי.","cat": "sage"},{"i": 1312,"n": "רב חביבא בריה דרב יוסף בריה דרבא","l": "ח","b": "אמורא בבלי בדור החמישי - הששי. בן בנו של רבא ואמר בשמו של זקנו (ב\"ב קמ\"ג ע\"ב). היו לו שני אחים חכמים: רבי אבא (חולין קמ\"א ע\"א) ונאנאי (יבמות ס\"ו ע\"ב).","cat": "sage"},{"i": 1313,"n": "רב חביבא בריה דרבא","l": "ח","b": "מובא בבבלי (ע\"ז ל\"ד ע\"ב). וגיר' \"דק\"ס\": רב אחא בריה דרבא.","cat": "sage"},{"i": 1314,"n": "חביבא מחוזנאה","l": "ח","b": "אמורא בבלי בדור הששי. היה כתלמיד לרב אשי ושקיל וטרי עמו (עירובין נ\"ז ע\"א).","cat": "sage"},{"i": 1315,"n": "רב חביבא מסורא דפרת","l": "ח","b": "מובא (ב\"מ ק\"ו ע\"ב), ונראה שהוא רב חביבא סתם.","cat": "sage"},{"i": 1316,"n": "חביבי","l": "ח","b": "רב קרא כך לר' חייא דודו (ב\"ב מ\"ו ע\"א).","cat": "sage"},{"i": 1317,"n": "רב חגא (2)","l": "ח","b": "אמורא בבלי שעלה לארץ ישראל. תלמידו של רב הונא (תלמידו דרב) (מו\"ק כ\"ה ע\"א). כשנפטר רב הונא והעלו ארונו לא\"י היה ר' חגא בן 08 שנה, ונכנס למערת ר' חייא והכפילו לו את שנותיו וחי 061 שנה (ירו', כתובות פי\"ב ה\"ג).","cat": "sage"},{"i": 1318,"n": "ר' חגאי","l": "ח","b": "מובא ב\"זוהר\" (לך פ\"ט).","cat": "sage"},{"i": 1319,"n": "ר' חגי","l": "ח","b": "הוא ר' חגא או ר' חגיי.","cat": "sage"},{"i": 1320,"n": "ר' חגי בן אלעזר","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מאמרים ספורים באגדה הובאו בשמו במדרשים (שמו\"ר פמ\"ב - ג'). רבי יהודה בן שלום (תלמידו של רבי יוסי) מסר בשמו (שו\"ט קי\"ט - ג').","cat": "sage"},{"i": 1321,"n": "רב חגיי","l": "ח","b": "מובא בירושלמי (כתובות פי\"ב ה\"ג), והוא רב חגא.","cat": "sage"},{"i": 1322,"n": "חגרא אחיו דר' בא בר בינא","l": "ח","b": "אמורא בבלי בדור השני. מובא בירושלמי (מגילה פ\"א ה\"ט), שנתן ספר תורה לרב חננאל לקרות בו.","cat": "sage"},{"i": 1323,"n": "רבי חדקא","l": "ח","b": "תנא בדור הרביעי. מתלמידיו של ר\"ע. חברו של רבי שמעון השקמוני (ב\"ב קי\"ט ע\"א). מפורסמת ההלכה שלו שחייב אדם לאכול בשבת ארבע סעודות (שבת קי\"ז ע\"ב). ממאמריו מובאים באגדה (תענית י\"א ע\"ב: דרך ארץ זוטא פ\"א). גירסת \"יתו\"א\": חדקאי.","cat": "sage"},{"i": 1324,"n": "חולפנא","l": "ח","b": "מובא בבבלי (ערכין כ\"ח ע\"ב), ונראה שזהה לאולפנא (ע\"ע).","cat": "sage"},{"i": 1325,"n": "ר' חונא","l": "ח","b": "מובא בירושלמי (גיטין פ\"א ה\"ב), והוא רב הונא.","cat": "sage"},{"i": 1326,"n": "רב חונא בר אדא","l": "ח","b": "מובא בירושלמי (שביעית פ\"י ה\"ג).","cat": "sage"},{"i": 1327,"n": "רב חונא בר חייא","l": "ח","b": "מובא בירושלמי (שביעית פ\"ב ה\"ה), והוא רב הונא בר חייא.","cat": "sage"},{"i": 1328,"n": "רבי חונא דברת חוורין","l": "ח","b": "הוא רבי חוניה דברת חוורין.","cat": "sage"},{"i": 1329,"n": "ר' חונא דציפורין","l": "ח","b": "והוא רב הונא רובא דציפורן.","cat": "sage"},{"i": 1330,"n": "חונה","l": "ח","b": "הוא הונא.","cat": "sage"},{"i": 1331,"n": "ר' חונה בר חמא","l": "ח","b": "מובא בירושלמי (שביעית פ\"ב).","cat": "sage"},{"i": 1332,"n": "ר' חונה בר יוסף","l": "ח","b": "מובא (ירו', תענית פ\"ד ה\"ה), והוא ר' הונא בר יוסף.","cat": "sage"},{"i": 1333,"n": "ר' חונה רבה דציפורין","l": "ח","b": "מובא בירושלמי (ר\"ה ספ\"ד), והוא רב הונא רובא דציפורין.","cat": "sage"},{"i": 1334,"n": "ר' חוני","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אמי (ירו', שקלים פ\"ו ה\"ד).","cat": "sage"},{"i": 1335,"n": "חוני המעגל","l": "ח","b": "חכם קדמון בימי ה\"זוגות\". חי בדורו של שמעון בן שטח (תענית י\"ט ע\"א). היה חסיד גדול ומלומד בנסים. מנהגו היה להתוות עיגול מסביבו ולעמוד בתוכו ולהתפלל עד שנתקבלה בקשתו (שם), ומכאן כינויו (רש\"י מנחות צ\"ד ע\"ב ד\"ה: דעגיל). \"אמר: 'רבש\"ע, נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך\" (שם), שלח לו שמעון בן שטח: 'אלמלא חוני אתה, גוזרני עליך נידוי'\" (שם). מסופר שישן 07 שנה וכשהתעורר לא הכירו איש ולא כיבדוהו, וביקש רחמים, ומת (תענית כ\"ג ע\"א). וכן מסופר, שכאשר צר הורקנוס על אריסטובולוס, תפסוהו אנשי הורקנוס ורצו שיקלל בשם ה' את אריסטובולוס, וכשסירב הרגוהו (\"קדמוניות היהודים\"), יתכן שהיו שני חוני המעגל, והשני מיוצאי חלציו של הראשון. \"סה\"ד\" משער, שהראשון ישן 07 שנה, והשני היה בן בנו והוא הנהרג. ולפי הירושלמי נראה שהיו שנים: \"חונה המעגל בר בריה דחוני המעגל הוה\" (תענית פ\"ג ה\"ט) ו\"יתו\"א\" כתב בהרחבה על חוני המעגל וסיים: \"והירושלמי חולק על גמ' דידן\".","cat": "sage"},{"i": 1336,"n": "חוני הקטן","l": "ח","b": "מובא בתוספתא: \"והלא במעמד כולם זקני ב\"ש ירד חוני הקטן ואמר וכו'\" (ר\"ה ספ\"ב).","cat": "sage"},{"i": 1337,"n": "חוניא","l": "ח","b": "כהן גדול. בנו של שמעון הצדיק (מנחות ק\"ט ע\"ב). שמעון הצדיק ציוה לפני פטירתו, שישמש במקומו ככהן גדול, ושמעי אחיו הגדול, שנתקנא בו, לימדו את סדר העבודה והטעהו, ורצו הכהנים להרוג את חוניא, וברח לאלכסנדריה שבמצרים ובנה שם מזבח (שם).","cat": "sage"},{"i": 1338,"n": "ר' חוניא","l": "ח","b": "מובא בירושלמי (נדרים פ\"ג ה\"ב).","cat": "sage"},{"i": 1339,"n": "חוניא בן יוסף בן פכסס הכהן","l": "ח","b": "חי בזמן התנאים. מובא בירושלמי: \"מעשה ביוסף בן פכסס שעלתה נומי על רגלו, וביקש הרופא לחותכה וכו', קרא לנחונייה בנו וא\"ל: עד כאן היית חייב לטפל בי וכו'\" (נזיר רפ\"ז). אין הוכחה שנמנה עם החכמים.","cat": "sage"},{"i": 1340,"n": "ר' חוניא בר אלעזר","l": "ח","b": "מובא בב\"ר (פמ\"ב - ג').","cat": "sage"},{"i": 1341,"n": "ר' חוניא חמוהי דר' אמי","l": "ח","b": "מובא ב\"ילקוט\" (מלכים א' רמז קעט).","cat": "sage"},{"i": 1342,"n": "רבי חוניה דברת חוורין","l": "ח","b": "אמורא ארץ ישראלי בדור המעבר בין התנאים לאמוראים. קיבל מרבי שמעון בן חלפתא (ירו', שקלים פ\"ד רה\"ב). נראה, שמושבו היה בעבר הירדן בהר חוורן. לקח חלק בעיבור השנה בטבריה (ירו', ע\"ז פ\"ג ה\"א). היה בעל מופת, וכשעבר את ים כנרת בדרכו לטבריה לעבר את השנה, היה הים נקרע לפניו. גדולי הדור הראשון והשני קבלו ממנו: רבי יוחנן (סוכה מ\"ד ע\"א), ר' אבא בר זבדא (ירו', סוכה פ\"ד ה\"א) ור' יהושע בן לוי (ירו', נדה פ\"ג ה\"ד). בנו ר' עוזיאל מסר בשמו (ירו', מע\"ש רפ\"ה).","cat": "sage"},{"i": 1343,"n": "ר' חונייא דברת חוורין","l": "ח","b": "מובא בירושלמי (סוכה פ\"ד ה\"א), והוא ר' חוניה דברת חוורין.","cat": "sage"},{"i": 1344,"n": "רבי חונייה מברת חוורן","l": "ח","b": "מובא בירושלמי (נדה פ\"ג ה\"ד), והוא ר' חוניה דברת חוורין.","cat": "sage"},{"i": 1345,"n": "רבי חוצפית","l": "ח","b": "ע\"ע רבי חוצפית המתורגמן.","cat": "sage"},{"i": 1346,"n": "רבי חוצפית המתורגמן","l": "ח","b": "תנא בדור השלישי. היה מתורגמן בסנהדרין ביבנה, בנשיאותו של רבן גמליאל דיבנה (ברכות כ\"ז ע\"ב). שמו מובא פעם אחת במשנה בבבלי: \"בשם ר' חוצפית\" (שביעית פ\"י מ\"ו). חברם של רבי ישבב, רבי חלפתא ור' יוחנן בן נורי (תוספתא כלים ב\"ב ב' ב'). היה שקול כיונתן בן עוזיאל (\"אור זרוע\" סי' תק\"י בשם מדרש עשרה הרוגי מלוכה). היה אחד מעשרה הרוגי מלכות (איכ\"ר פ\"ב - ד'), וכן בתוספות (בכורות ל\"ו ע\"א). האריך ימים ונהרג בגיל 301 (ביהמ\"ד הוצאות ילינק ח\"ב עמ' 07). לא ניתן לקבורה ויש אומרים שאלישע בן אבויה יצא לתרבות רעה משום שראה את לשונו של רבי חוצפית נגררת על ידי דבר אחר [חזיר] (קידושין ל\"ט ע\"ב).","cat": "sage"},{"i": 1347,"n": "ר' חזאל","l": "ח","b": "לפי גירסת \"יתו\"א\" תנא בדור הראשון ומובא בפירקי דר\"א מ\"ז, ולפנינו מובא בפרק מ\"ח, אך בשינויים, ובנוסחאות שלנו אין זכר לשם חזאל כפי שהיה לפני \"יתו\"א\".","cat": "sage"},{"i": 1348,"n": "חזקיה (2)","l": "ח","b": "אמורא ארץ ישראלי. מראשוני הדור הראשון ועדיין כינוהו תנא (רש\"י חולין ק\"ו ע\"א ד\"ה: אין: תוספות ע\"ז ל\"ח ע\"ב ד\"ה: תנו). בנו של ר' חייא הגדול. אליהו הנביא גילה לרבי, שר' חייא ושני בניו יהודה וחזקיה הם דוגמת האבות (ב\"מ פ\"ה ע\"ב). ועליו ואחיו יהודה אמרו: \"תרי אמוראי במערבא\" (ב\"ב ע\"ה ע\"א). היה גדול בדורו (חולין נ\"ז ע\"א רש\"י ד\"ה: בריבי). ר\"ל אמר: \"כשנשתכחה תורה מישראל, עלה עזרא מבבל ויסדה, חזרה ונשתכחה, עלה הלל הבבלי ויסדה, חזרה ונשתכחה, עלו רבי חייא ובניו ויסדוה\" (סוכה כ' ע\"א). ונראה שסידר קובץ ברייתות, כדמצינו \"דבי חזקיה תנא\" (סנהדרין מ\"א ע\"א) והוא חזקיה, בנו של ר' חייא, כדמפורש בתוספות (כתובות ל\"ה ע\"א ד\"ה: ומי). היה מאוכלי שולחנו של רבי (סנהדרין ל\"ח ע\"א). היה קשיש מרבי יהודה נשיאה (ע\"ז ל\"ח ע\"ב תד\"ה: תנו). חבריו היו בר קפרא (סנהדרין ק' ע\"א) ור' ינאי שחלק עמו ועם אחיו (זבחים ט\"ו ע\"א) אבל רבי ינאי היה קשיש ממנו הרבה וקרא לו ולאחיו \"רובין\" [נערים] (חולין כ' ע\"א). מתלמידיו הגדולים: רבי יוחנן (שבת קי\"ב ע\"ב). ור\"ל מסר בשמו (ב\"ק ט' ע\"ב). מקומו הקבוע היה בטבריה (מגילה ה' ע\"ב) ונפטר ונקבר שם במערה לשמאל אביו (מו\"ק כ\"ה ע\"א), ואחיו יהודה לימין אביו. (יש עוד אמורא ארץ ישראלי בדור הרביעי בשם ר' חזקיה).","cat": "sage"},{"i": 1349,"n": "רבי חזקיה","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי ירמיה (זבחים ע\"ה ע\"ב). כן למד אצל רבי אבהו (ירו', ביצה פ\"א ה\"ב), שמצינו: \"ר' חזקיה אמר אביי\" (שבת ל\"ח ע\"ב), ובשם רבא (ירו', יבמות פ\"ח ה\"א). חברו של ר\"ה ב' (זבחים שם). ר' מנא היה לו כתלמיד (ירו', נדרים פ\"ד ה\"ה).","cat": "sage"},{"i": 1350,"n": "ר' חזקיה","l": "ח","b": "מובא הרבה ב\"זוהר\" (נח ס\"ט).","cat": "sage"},{"i": 1351,"n": "חזקיה אבי עיקש","l": "ח","b": "תנא בדור השלישי. העיד לפני רבן גמליאל ביבנה משום רבן גמליאל הזקן (בכורות ל\"ח ע\"א).","cat": "sage"},{"i": 1352,"n": "חזקיה איש עיקש","l": "ח","b": "מובא ב\"ילקוט\" (שמיני רמז תקלט), והוא חזקיה אבי עיקש.","cat": "sage"},{"i": 1353,"n": "חזקיה בן גרון","l": "ח","b": "\"סה\"ד\" כתב שהיה בזמן הלל. מובא בירושלמי: \"אלו ההלכות שאמרו בעליית חנניא בן חזקיה בן גרון שעלו לבקרו, ונמנו ורבו ב\"ש על ב\"ה\" (שבת פ\"א ה\"ד). וכן בבבלי (שבת י\"ג ע\"ב).","cat": "sage"},{"i": 1354,"n": "חזקיה בר בילוטו","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אבהו (ערכין כ\"ח ע\"ב). אביו בילווטו (כן הגירסא בערכין י\"א ע\"א) היה תלמידו של ר' יוחנן (שם).","cat": "sage"},{"i": 1355,"n": "ר' חזקיה בר יעקב בר אחא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר' יוסי בר חנינא (ירו', שבועות פ\"ג ה\"ד). יש סבורים שצ\"ל: ר' חזקיה [בשם] ר' יעקב בר אחא [בשם] ר' יוסי בר חנינא.","cat": "sage"},{"i": 1356,"n": "ר' חזקיה בר ירמיה","l": "ח","b": "מובא בירושלמי בשמו: \"אם יכל את לשלשל שמועה עד משה וכו'\" (קידושין פ\"א ה\"ז). אותו מאמר מובא במקום אחר: \"ר' חזקיה [בשם] ר' ירמיה [בשם] ר' חייא\" (ירו', שבת פ\"א ה\"ב). נראה שהוא ט\"ס ולא היה כלל אמורא ששמו ר' חזקיה בר ירמיה.","cat": "sage"},{"i": 1357,"n": "חזקיה בריבי","l": "ח","b": "מובא בירושלמי (בכורים פ\"ג ה\"ג), והוא חזקיה סתם בנו של רבי חייא בריבי גדול הדור.","cat": "sage"},{"i": 1358,"n": "חזקיה בריה דר' חייא","l": "ח","b": "כן הביא \"סה\"ד\" בשם הרשב\"א מפרק המגרש. ואין לפנינו בש\"ס.","cat": "sage"},{"i": 1359,"n": "חזקיה בריה דר' פרנק","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי, תלמידו של רבי יוחנן (ברכות ס\"ג ע\"ב).","cat": "sage"},{"i": 1360,"n": "ר' חזקיה חוקוק","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. חברם של רב הונא ב' ור' פנחס (ירו', סנהדרין פ\"ג ה\"ט).","cat": "sage"},{"i": 1361,"n": "ר' חזקיה עכייה","l": "ח","b": "מובא בירושלמי (שבת פי\"ד ה\"ד), שאמר בשם רבנן דקיסרין.","cat": "sage"},{"i": 1362,"n": "רבי חזקיה רבה","l": "ח","b": "מובא (ירו', כתובות פ\"ה ה\"ו). נראה שהוא רבי חזקיה סתם, בנו של רבי חייא.","cat": "sage"},{"i": 1363,"n": "חטיא","l": "ח","b": "מובא ב\"ילקוט\" (נביאים סי' קי\"ט). וזה לשון \"סה\"ד\": \"שם חכם בקמץ הח' בחירק הט' בקמץ היוד\".","cat": "sage"},{"i": 1364,"n": "רבי חידקא","l": "ח","b": "הוא רבי חדקא.","cat": "sage"},{"i": 1365,"n": "רבי חייא","l": "ח","b": "תנא - אמורא ארץ ישראלי בדור המעבר שבין התנאים לאמוראים (נדה כ\"ו ע\"א רש\"י: \"רבי חייא תנא ואמורא הוא\", ב\"מ ע\"א: ע\"ב \"ר' חייא תנא ופליג\"). בדורו של רבי, מבני פמלייתו של הנשיא וסמוך על שולחנו (עירובין ע\"ג ע\"א) והוא סתם ר' חייא בש\"ס הבבלי או, רבי חייא רבה (שבת י\"ח ע\"ב). ובירושלמי כמעט תמיד נקרא רבי חייא רובא או רבי חייא הגדול (אבל ר' חייא סתם בירושלמי הוא ר' חייא בר אבא). יליד בבל. עלה לא\"י יחד עם בניו יהודה וחזקיה (סוכה כ' ע\"א): \"וכשנשתכחה תורה מישראל וכו' חזרה ונשתכחה, עלו רבי חייא ובניו ויסדוה\". חיבר עם ר' אושעיא הברייתות שבידינו (חולין קמ\"א ע\"ב). רבי מסר לו הרבה מחכמתו (נדרים מ\"א ע\"א) והיה תלמיד חבר לרבי (נדה י\"ד ע\"ב תוס'), וגם רבי שאל ממנו (הוריות י\"א ע\"א). רבו ודודו של רב (מו\"ק ט\"ז ע\"ב). אליהו הנביא גילה לרבי, שר' חייא ובניו שקולים כאבות (ב\"מ פ\"ד ע\"ב). ר\"ל אמר: הריני כפרת ר' חייא ובניו (סוכה כ' ע\"א). צם 003 תעניות למען שיזכה לראות את ר' חייא בחלום (ירו', כלאים פ\"ט סה\"ג). מלאך המות לא יכול להתקרב אליו (מו\"ק כ\"ח ע\"א).","cat": "sage"},{"i": 1366,"n": "רבי חייא אבוי דרבי ברכיה","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. אבי רבי ברכיה בעל האגדה המפורסם בדור הרביעי. שניהם, רבי ברכיה ואביו, מסרו ביחד דברי אגדה (ויק\"ר פ\"ל - א'), וכן מסר רבי ברכיה בשם אביו (תנחומא פ' חיי שרה). גם בנו השני, רבי שמואל, היה מחכמי ההלכה (ירו', שבת ספט\"ו).","cat": "sage"},{"i": 1367,"n": "ר' חייא אבוי דר' אחא","l": "ח","b": "מובא בתנחומא (ישן פ' שלח), ונראה שיש שיבוש (עיין תנחומא בובר וכן מ\"ר פי\"ז - ב').","cat": "sage"},{"i": 1368,"n": "רבי חייא איש כפר עכו","l": "ח","b": "אמורא ארץ ישראלי בדור השני. אין מתורתו מאומה בש\"ס. מובא בהקשר לבנו: \"ר' תנחום בנו של ר' חייא איש כפר עכו\" (ברכות ס\"ג ע\"ב).","cat": "sage"},{"i": 1369,"n": "רבי חייא אריכא","l": "ח","b": "אמורא בבלי בדור הרביעי. בא לדין תורה לפני רבא (כתובות ק\"ד ע\"ב). ר' יצחק בן טבלי מסר בשמו (נדרים ח' ע\"ב). \"סה\"ד\" תמה על זה: \"כי ר' יצחק בן טבלי נראה קדום לו\", ונראה שיש איזה שיבוש.","cat": "sage"},{"i": 1370,"n": "רבי חייא בר אבא","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. בירושלמי נקרא ר' חייא או ר' חייא בר ווא או ר' חייא בר בא, ובבבלי ר' חייא בר אבא. יליד בבל (שבת ק\"ה ע\"ב). קיבל מרב (חולין צ\"ב ע\"א) ומגניבא (חולין נ' ע\"א). כשעלה לא\"י שימש את רבי חנינא (ירו', הוריות פ\"ג סה\"ד). ר' יוחנן היה רבו המובהק (ברכות ל\"ח ע\"ב) כן שימש את ריב\"ל (ירו', שבת פ\"א רה\"ב) וקיבל מר\"א בן פדת (ירו', חגיגה פ\"א ה\"ז). חבריו היו: ר' אמי ור' אסי, ושלושתם היו חשובים בעיני הנשיא (שם). מתלמידיו: ר' ירמיה (ברכות י\"ג ע\"ב) ור' חמא בר חנינא (סנהדרין כ\"ט ע\"א). מדי 03 יום היה חוזר על תלמודו לפני ר' יוחנן (ברכות ל\"ח ע\"ב): ודייק מאד בשמועותיו (שם). ירד מספר פעמים לבבל (\"אגרת רב שרירא גאון\"). היה עני מרוד (ברכות מ\"ג ע\"ב). היו לו שלושה בנים אמוראים: ר' אבא (חולין פ\"ו ע\"ב), ר' כהנא (ירו', שבת פ\"א סה\"ד) ור' נחמיה (ירו', דמאי פ\"א ה\"ב).","cat": "sage"},{"i": 1371,"n": "ר' חייא בר אבא דמן יפו","l": "ח","b": "מובא במדרש תהלים (פס\"ב - ג'), ואולי צ\"ל: ר' חייא בר אדא דמן יפו.","cat": "sage"},{"i": 1372,"n": "ר' חייא בר אבויה","l": "ח","b": "יתכן שהיה תנא. היה זקנו של ר' פרידא (סנהדרין פ\"ב ע\"א רש\"י), ומצא גולגלתו של המלך יהויקים ועסק בקבורתה.","cat": "sage"},{"i": 1373,"n": "רב חייא בר אבין","l": "ח","b": "אמורא בבלי בדור השלישי. זכה לקבל מרב (עירובין ל\"ח ע\"ב) ומשמואל (שבת נ\"ב ע\"א). היה תלמיד של ר\"ה (קידושין נ\"ח ע\"א). שאל מאדא בר אהבה (שבת ק\"מ ע\"א) ומרב חסדא (מנחות מ\"ט ע\"א). עלה ולמד אצל ר\"א בטבריה, ומשם שלח הוראות לבבל (יבמות מ\"ג ע\"א). וכן: \"אמר ר' חייא בר אבין אמר ר' יוחנן\" (עירובין מ\"ז ע\"ב). ר\"ה בירך את אביו שיצאו ממנו שני אנשים גדולים, ונולדו הוא ואחיו רב אידי בר אבין (שבת כ\"ג ע\"ב). רבא קרא לו \"ארי שבחבורה\" (קידושין מ\"ח ע\"ב). רנב\"י שאל ממנו (ברכות ו' ע\"א).","cat": "sage"},{"i": 1374,"n": "רב חייא בר אדא","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי אחא (ירו', ברכות פ\"ו סה\"א) ושל רבי מנא [בנו של ר' יונה] (ירו', דמאי פ\"ב ה\"א).","cat": "sage"},{"i": 1375,"n": "רבי חייא בר אדא","l": "ח","b": "אמורא ארץ ישראלי בדור השני - השלישי. בן אחותו של בר קפרא (פסיקתא דרב כהנא צ\"ז - א'). תלמידו של ר\"ל, ומת בחיי רבו (ירו', ברכות פ\"ב ה\"ח). שאל מרבי יוחנן (ירו', מעשרות פ\"א ה\"א). הצטיין בקול ערב (פסדר\"כ שם).","cat": "sage"},{"i": 1376,"n": "רבי חייא בר אחא","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם רשב\"ל (ירו', פסחים פ\"ז ה\"ב).","cat": "sage"},{"i": 1377,"n": "רב חייא בר אמי","l": "ח","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של עולא (ברכות ח' ע\"א). פעם ישב בחברתו של עולא: \"יתיב ר\"נ ועולא ואבימי בר פפי, ויתיב רב חייא בר אמי גבייהו\" (ע\"ז ס\"ג ע\"ב).","cat": "sage"},{"i": 1378,"n": "רב חייא בר אסי","l": "ח","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (תענית י\"ח ע\"א). כן מסר בשם ר' יוחנן (מדרש תהלים פע\"ב - ו').","cat": "sage"},{"i": 1379,"n": "רב חייא בר אשי","l": "ח","b": "אמורא בבלי בדור השני. מתלמידיו הגדולים והמובהקים של רב (ברכות י\"ז ע\"א). כן היה תלמידם של זעירי (שבת ק\"ט ע\"א) ושל שמואל (יבמות קי\"ג ע\"א). עמד בראש ישיבה בקורקוניא, הסמוכה לסורא (ע\"ז ט\"ז ע\"א). חלק על ר\"ה חברו, שעמד בראש ישיבת סורא, בדבר הלכה (חולין קי\"א ע\"ב). האומרים בשמו: רבי אבא (נדה ט\"ז ע\"ב), רבי זירא (שבת קמ\"ה ע\"א) ורב עמרם חסידא (סוכה י\"א ע\"א). פרש מאשתו והיא התחפשה לזונה והכשילתו, ורצה לשרוף עצמו, גם לאחר שאמרה לו כי לא נכשל, כי היא היתה זו, באמרו: \"אבל אני התכונתי לאיסורא\": וכל ימיו של אותו צדיק היה מתענה, עד שמת בשריפה (קידושין פ\"א ע\"ב).","cat": "sage"},{"i": 1380,"n": "חייא בר בון","l": "ח","b": "מובא בירושלמי (דמאי פ\"ג ה\"ד), והוא ר' חייא בר אבין.","cat": "sage"},{"i": 1381,"n": "רבי חייא בר ברתיה דר' ברכיה","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. בן בתו של ר' ברכיה, מחשובי בעלי האגדה הארץ ישראליים בדור הרביעי. מסר בשם סבו זה (ב\"ר פ\"ט - ה').","cat": "sage"},{"i": 1382,"n": "ר' חייא בר גוריא","l": "ח","b": "אמורא בבלי. מובא בבבלי. (נדה נ\"ה ע\"ב). אמר מ\"ט דרב.","cat": "sage"},{"i": 1383,"n": "רב חייא בר גמדא","l": "ח","b": "אמורא בבלי בדור השני. עלה לארץ ישראל, וכשהגיע לגבול התפלש בעפרה (כתובות קי\"ב ע\"ב). היה תלמידו של רבי יוסי בר שאול [מתלמידי רבי] (ר\"ה כ\"ד ע\"א), וקיהל ממנו מספר מאמרים בשם רבי. כן למד מר' יוסי בר חנינא (סוטה ז' ע\"ב). נראה שהאריך ימים, שכן מובא: \"א\"ר חייא בר גמדא: 'נזרקה מפי החבורה'\" (שבת ג' ע\"א) ומפרשים התוספות (ד\"ה: איתמר): \"חבורה של תנאים\" ואם כן, נראה שנפגש בשעתו עם חבורת התנאים.","cat": "sage"},{"i": 1384,"n": "ר' חייא בר זבדא","l": "ח","b": "מובא בב\"ר (פפ\"ד - ח').","cat": "sage"},{"i": 1385,"n": "ר' חייא בר זעירא","l": "ח","b": "מובא בבמד\"ר (פי\"א - ב'). יתכן שחל שיבוש בשם זה.","cat": "sage"},{"i": 1386,"n": "רבי חייא בר זרנוקי","l": "ח","b": "אמורא ארץ ישראלי בדור השני. חברו של ר' שמעון בן יהוצדק ב'. הלך לעבר שנה ופגש בר\"ל, ולאחר שלימד זכות על עוברי עבירה כינה אותו ר\"ל 'רועה בקר', והוא התלונן על כך בפני ר' יוחנן (סנהדרין כ\"ו ע\"א).","cat": "sage"},{"i": 1387,"n": "ר' חייא בר חיננא","l": "ח","b": "אמורא לאחר הדור השלישי. התקיף על דברי רבי חנינא בר פפא (מנחות נ\"ג ע\"ב).","cat": "sage"},{"i": 1388,"n": "ר' חייא בר טיטס","l": "ח","b": "אמורא ארץ ישראלי לאחר הדור השני - השלישי. רבנן דקיסרין אמרו בשמו (ירו', תרומות פ\"ח ה\"ג).","cat": "sage"},{"i": 1389,"n": "רב חייא בר יהודה","l": "ח","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (כתובות כ\"א ע\"א).","cat": "sage"},{"i": 1390,"n": "ר' חייא בר יוכי","l": "ח","b": "מובא בב\"ר (ספנ\"ה). \"סה\"ד\" כתב: \"אולי צ\"ל ר' חייא בר יוסי\".","cat": "sage"},{"i": 1391,"n": "ר' חייא בר יוסי","l": "ח","b": "מובא בבבלי (פסחים ז' ע\"א), והוא ר' חייא בר יוסף.","cat": "sage"},{"i": 1392,"n": "רב חייא בר יוסף","l": "ח","b": "אמורא בבלי בדור השני. תלמידם של רב (שבת ז' ע\"א) ושל שמואל (חולין מ\"ה ע\"ב). כשעלה לארץ ישראל היה לתלמידו של רבי יוחנן (גיטין לט ע\"א), ומסר מתורתו של רב לר' יוחנן ור\"ל (חולין נ\"ד ע\"א). עוד קיבל מר' אושעיא (ע\"ז נ\"א ע\"ב). האומרים משמו: ר' אלעאי (ב\"מ קי\"ז ע\"א) ור' חייא בר אבא (ירו', כלאים פ\"ד ה\"ד). בהיותו בבבל היה הריש בעיר סיכרא, והתקין שם תקנות (ב\"מ פ\"ג ע\"א). בא\"י ישב יחד עם ר' יוחנן בדין (ירו', ב\"מ פ\"ד ה\"ב). סחר במלח (שם).","cat": "sage"},{"i": 1393,"n": "ר' חייא בר ינאי","l": "ח","b": "מובא באס\"ר (פ\"ז - י').","cat": "sage"},{"i": 1394,"n": "ר' חייא בר יעקב","l": "ח","b": "מובא בתנחומא (הישן פ' עקב).","cat": "sage"},{"i": 1395,"n": "ר' חייא בר כהנא","l": "ח","b": "מובא באגדת בראשית (פ\"ב).","cat": "sage"},{"i": 1396,"n": "רבי חייא בר לוליבא","l": "ח","b": "מובא בירושלמי (ערלה רפ\"ב), והוא רבי חייא בר לולייני.","cat": "sage"},{"i": 1397,"n": "רבי חייא בר לולייני","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי - הששי. חברו של רבי יוסי בי רבי בון: שניהם מסרו יחד מאמרי הלכה בירושלמי (נזיר פ\"ד סה\"ד). נראה שהיה ראש ישיבה. בירושלמי מוזכרים תלמידיו (יומא פ\"ב רה\"ב). מסופר ששמע לעננים שרצו להוריד גשם בעמון ומואב והתפלל שירדו בא\"י, וכך הווה. (תענית כ\"ה ע\"א).","cat": "sage"},{"i": 1398,"n": "רבי חייא בר מדייא","l": "ח","b": "מובא בירושלמי (ב\"ב פ\"ח ה\"ח), והוא רבי חייא בר מרייה.","cat": "sage"},{"i": 1399,"n": "ר' חייא בר ממל","l": "ח","b": "כך גירסת \"יתו\"א\" (ב\"ק י\"ט ע\"א), ולפנינו הגיר' ר' חייא בר אבא.","cat": "sage"},{"i": 1400,"n": "ר' חייא בר מנחמא","l": "ח","b": "מובא בויק\"ר (פל\"ו - ו'). רבי תנחומא מסר בשמו, ו\"סה\"ד\" גרס: בר מנהמא.","cat": "sage"},{"i": 1401,"n": "רבי חייא בר מרייה","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי יונה וישב לפניו (ירו', כתובות פ\"ט ה\"א). כן היה תלמידו של רבי יוסי (ירו', ב\"ב פ\"ח ה\"ח). חברו של רבי מנא (בנו של ר' יונה), שמסר לו דעתו של ר' יונה אביו במספר ענינים (ירו', עירובין פ\"ח ה\"ט).","cat": "sage"},{"i": 1402,"n": "רב חייא בר מתנה","l": "ח","b": "אמורא בבלי בדור השלישי. מובא בבבלי: \"דרש משמיה דרב וכו' א\"ל רב נחמן וכו'\" (נדה ס' ע\"ב).","cat": "sage"},{"i": 1403,"n": "ר' חייא בר נחמן","l": "ח","b": "מובא בויק\"ר (רפי\"ח).","cat": "sage"},{"i": 1404,"n": "רב חייא בר נחמני","l": "ח","b": "תנא ארץ ישראלי בדור הרביעי. תלמידו של רבי ישמעאל (ברכות מ\"ח ע\"ב).","cat": "sage"},{"i": 1405,"n": "ר' חייא בר עוקבה","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם רבי יוסי (ירו', גיטין פ\"ג ה\"ז).","cat": "sage"},{"i": 1406,"n": "רב חייא בר עמרם","l": "ח","b": "מובא בבבלי (בכורות ל\"ו ע\"ב). ב\"שיטה מקובצת\" הגיר': ר' חייא בר אבין אמר ר' עמרם.","cat": "sage"},{"i": 1407,"n": "חייא בר פפא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' זירא (ירו', ברכות פ\"ו ה\"א).","cat": "sage"},{"i": 1408,"n": "רב חייא בר רב","l": "ח","b": "אמורא בבלי בדור השני. בנו ותלמידו המובהק של רב (פסחים ע' ע\"א). רב פיקח על לימודו של בנו, וגדולי תלמידי רב היו רבותיו. רב חייא בר אשי (עירובין מ\"ז ע\"א), רב חנן בר רבא [חתנו של רב] (יומא י\"ט ע\"ב) ורב יהודה (עירובין י\"ד ע\"א). עם ר\"ה היה כחבר ושניהם ישבו לפני שמואל (ערכין ט\"ז ע\"ב), וכן ישבו יחד כחברי בית דין (ב\"ב ל\"ט ע\"ב). בשמו מסרו ר\"ה בר חיננא (ברכות ל' ע\"א) ואביי (שבועות י\"ז ע\"ב). היה לו בן חכם ושמו שימי, שהיה חביב על רב זקנו (קידושין י\"ב ע\"א).","cat": "sage"},{"i": 1409,"n": "ר' חייא בר רב מדיפתי","l": "ח","b": "אמורא בבלי בדור השלישי. חי עד הדור החמישי. נראה, שהיה בקי בברייתות, ומצינו, שפעם ישבו רב חסדא ורבה בר רב הונא בדין כל היום וחלש לבם, ושנה להם ר' חייא בר רב מדיפתי ברייתא לעודדם (שבת י' ע\"ב). ומצינו אותו (כנראה בזקנותו) שאמר לרב פפא: \"שמא עני בא לידך ולא פרנסתו כדתניא וכו'\" (ב\"ב י' ע\"א). שמו מובא בדרך כלל בלי תואר רב רק פעם מובא בתואר רב (יבמות ע\"ד ע\"א).","cat": "sage"},{"i": 1410,"n": "ר' חייא בר רבא","l": "ח","b": "מובא במדרש משלי (פט\"ו).","cat": "sage"},{"i": 1411,"n": "רבי חייא בר ריבי","l": "ח","b": "כך גירסת הרי\"ף בבבלי (יבמות מ\"ו ע\"ב), והוא רבי חייא סתם. ו\"בריבי\" פירושו גדול הדור.","cat": "sage"},{"i": 1412,"n": "רב חייא בר שימי","l": "ח","b": "כך גירסת \"יתו\"א\" (עירובין מ\"ד ע\"ב), ולפנינו אין בכל הש\"ס השם רב חייא בר שימי וגירסתנו בעירובין רב שימי בר חייא.","cat": "sage"},{"i": 1413,"n": "רבי חייא ברבי","l": "ח","b": "הוא רבי חייא.","cat": "sage"},{"i": 1414,"n": "רב חייא בריה דאבא בר נחמני","l": "ח","b": "מובא בבבלי (ע\"ז ס' ע\"ב), והוא רב חייא בריה דרבה בר נחמני (\"דק\"ס\").","cat": "sage"},{"i": 1415,"n": "רב חייא בריה דרב אויא","l": "ח","b": "אמורא בבלי בדור הששי. רבו של רב אמימר בר ינוקא (חולין י\"ח ע\"ב). נהג לאכול מיני מגדים בשבת ויו\"ט, כדי להשלים מאה ברכות (מנחות מ\"ג ע\"ב).","cat": "sage"},{"i": 1416,"n": "רב חייא בריה דרב איקא","l": "ח","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (נדה מ\"ה ע\"א): \"מתקיף לה רב חייא בריה דרב איקא וכו', אמר רב חסדא: ת\"ש וכו'\".","cat": "sage"},{"i": 1417,"n": "רב חייא בריה דרב הונא","l": "ח","b": "אמורא בבלי בדור הרביעי. תלמיד מובהק של אביי ורבא (ברכות ל\"ד ע\"ב).","cat": "sage"},{"i": 1418,"n": "רב חייא בריה דרב ייבא","l": "ח","b": "אמורא בבלי אחרי הדור השלישי. הוסיף על דברי רב חסדא (סוכה מ\"ב ע\"ב).","cat": "sage"},{"i": 1419,"n": "רב חייא בריה דרב יצחק","l": "ח","b": "אמורא בבלי בדור החמישי. רבינא פסק לו דין (ע\"ז ל\"ג ע\"ב).","cat": "sage"},{"i": 1420,"n": "רב חייא בריה דרב נחמן","l": "ח","b": "אמורא בבלי בדור הרביעי. בנו של האמורא המפורסם רב נחמן. הוסיף על דברי רב (ב\"ב מ\"ו ע\"א).","cat": "sage"},{"i": 1421,"n": "רב חייא בריה דרב נתן","l": "ח","b": "אמורא בבלי. מובא בבבלי (פסחים מ\"א ע\"א: מנחות ל\"ט ע\"א).","cat": "sage"},{"i": 1422,"n": "ר' חייא בריה דרב פפי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. חברו של ר' יהושע דסכנין, והם אמרו בשם ר' לוי (ויק\"ר רפי\"ח).","cat": "sage"},{"i": 1423,"n": "רב חייא בריה דרבה בר נחמני","l": "ח","b": "אמורא בבלי בדור הרביעי. בנו של האמורא רבה בר נחמני, ראש ישיבת פומבדיתא. תלמידו של רב חסדא (סנהדרין ס\"ט ע\"ב). לא מצינו בשום מקום שדיבר עם אביו או קיבל ממנו.","cat": "sage"},{"i": 1424,"n": "ר' חייא בריה דרבי חייא בר נחמני","l": "ח","b": "מובא בבבלי (ע\"ז ל\"א ע\"א). \"דק\"ס\" גורס: ר' חייא בריה דרבה בר נחמני.","cat": "sage"},{"i": 1425,"n": "רבי חייא בריה דר' אדא דיפו","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. בנו של האמורא ר' אדא דמן יפו. מסר בשם ר' ירמיה, שחייבים בפורים לקרות במגילה את עשרת בני המן בנשימה אחת (ירו', מגילה פ\"ג ה\"ז). כן מסר בשם ר' שמואל בר נחמני (ש\"ר פמ\"ג - ג'). ר' ברכיה מחשובי בעלי האגדה מסר בשמו (שם).","cat": "sage"},{"i": 1426,"n": "ר' חייא בריה דר' יוסי","l": "ח","b": "מובא ב\"זוהר\" (יתרו).","cat": "sage"},{"i": 1427,"n": "חייא בריה דר' יצחק עטושיא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של יצחק עטושיא (תלמידו של ר\"ז). קיבל מר' ירמיה (ירו', נזיר פ\"ג ה\"א).","cat": "sage"},{"i": 1428,"n": "ר' חייא בריה דר' שבת","l": "ח","b": "אמורא ארץ ישראלי. רבי עקיבא (האמורא) מסר בשמו (ירו', יבמות ספ\"ב).","cat": "sage"},{"i": 1429,"n": "ר' חייא דכפר תחומין","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. ר' אבהו מספר עליו: \"פירשה ר' חייא דכפר תחומין\" (ירו', סוף תרומות). חלק עם ר' ברכיה (ירו', פאה פ\"א).","cat": "sage"},{"i": 1430,"n": "רבי חייא הגדול","l": "ח","b": "הוא רבי חייא.","cat": "sage"},{"i": 1431,"n": "ר' חייא מאבל ערב","l": "ח","b": "מובא בבבלי (פסחים ע\"ב ע\"א), ויתכן שיש שיבוש בשם.","cat": "sage"},{"i": 1432,"n": "רב חייא מהורמיז ארדשיד","l": "ח","b": "אמורא בבלי בדור השלישי. מובא בבבלי: \"אמר רב נחמן בר יצחק: אישתעי לי רב חייא מהורמיז ארדשיד\" (ב\"ב נ\"ב ע\"א).","cat": "sage"},{"i": 1433,"n": "רב חייא מוסתניא","l": "ח","b": "אמורא בבלי בדור החמישי. תלמידו של רבא, ואצלו למד יחד עם חבריו, רב שמואל בר אידי ורב הונא בר מנוח. לאחר פטירת רבא באו שלושתם לפני ר\"פ ללמוד, וכל פעם שאמר ר\"פ שמועה שלא נתקבלה על דעתם, היו מרמזים זה לזה: חלשה דעתו של ר\"פ ומחשש שיענשו שילחם מעל פניו (תענית ט' ע\"א).","cat": "sage"},{"i": 1434,"n": "ר' חייא מיוסתיניא","l": "ח","b": "מובא בבבלי (זבחים קי\"ב ע\"א). נראה לי, שהוא הוא רב חייא מוסתניא, ומה שפירש רש\"י (תענית ט' ע\"א ד\"ה: מווסתניא): \"מאותו מקום\" ובמסכת (זבחים קי\"ב ע\"א) פרש\"י ד\"ה: מיוסתינא \"מקום\", ונראה כאילו גרס רש\"י ששני מקומות נפרדים היו, אינו ראיה, שכן דרכו של רש\"י לפרש בכל מקום כפי הגיר' בגמ' שלפניו אם אינו משנה לסוגיא ופשט ולענין. ולכן גורס ששניהם חד הוא.","cat": "sage"},{"i": 1435,"n": "רב חייא פרוואה","l": "ח","b": "אמורא בבלי בדור החמישי. איקלע לבי ריש גלותא ופסק להם דין ורב זביד התנגד לדעתו והחמיר ועבדי ריש גלותא השקו את רב זביד כוס של חומץ ומת. (ע\"ז ל\"ח ע\"ב).","cat": "sage"},{"i": 1436,"n": "רבי חייא ציפוראה","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי (ירו', ערלה פ\"ג ה\"ב).","cat": "sage"},{"i": 1437,"n": "ר' חייא קטוספאה","l": "ח","b": "אמורא בבלי בדור השני. אמר משמיה דרב (ביצה ל\"ח ע\"ב). ואולי צ\"ל: רבה בר חייא קטוספאה, כמו שמצינו במקומות אחרים (ב\"ב צ\"ג ע\"ב: ירו', כלאים רפ\"ב).","cat": "sage"},{"i": 1438,"n": "ר' חייא קרא","l": "ח","b": "מובא באיכ\"ר (פ\"ד - ד'). אמר בשם רבי שמואל בר נחמני. מקור המימרה בירושלמי (סוכה פ\"ד ה\"ו) ושם הגיר': ר' יודא בר לקרה. ואולי אחד הוא.","cat": "sage"},{"i": 1439,"n": "רבי חייא רבה","l": "ח","b": "הוא רבי חייא.","cat": "sage"},{"i": 1440,"n": "רב חייא רובא","l": "ח","b": "הוא רבי חייא.","cat": "sage"},{"i": 1441,"n": "רבי חייא רובא בר לוליתא","l": "ח","b": "מובא בירושלמי (חלה פ\"ב ה\"ג), והוא רבי חייא בר לולייני.","cat": "sage"},{"i": 1442,"n": "ר' חייה","l": "ח","b": "","cat": "sage"},{"i": 1443,"n": "רבי חייה בר לוליינו","l": "ח","b": "מובא בירושלמי (כתובות י\"ג ע\"ב). והוא רבי חייא בר לולייני.","cat": "sage"},{"i": 1444,"n": "ר' חייה בר שיבתיי","l": "ח","b": "מובא בירושלמי (עירובין פ\"ה ה\"א), והוא ר' חייה בריה דר' שבתי.","cat": "sage"},{"i": 1445,"n": "חילפא בר אגרא","l": "ח","b": "תנא ארץ ישראלי בדור הרביעי. מסר בשם ר' יוחנן בן נורי. רבי שמעון בן אלעזר מסר בשמו (שבת ק\"ה ע\"ב).","cat": "sage"},{"i": 1446,"n": "חילפא בר אידי","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. מובא בויק\"ר (רפט\"ז), והוא ור' חייא בר אבא אמרו וכו'.","cat": "sage"},{"i": 1447,"n": "ר' חילפא דרומיה","l": "ח","b": "מובא בפס' רבתי (פ' אנכי מנחמכם סי\"ב).","cat": "sage"},{"i": 1448,"n": "חילפי בר אידי","l": "ח","b": "מובא בויק\"ר (רפט\"ז), ואולי הוא זהה לר' חליפי בר זטרי (פד\"כ קלג).","cat": "sage"},{"i": 1449,"n": "חילפיי","l": "ח","b": "מובא בירושלמי (קידושין פ\"א ה\"א), והוא אילפא.","cat": "sage"},{"i": 1450,"n": "ר' חילפיי בר בריה דר' אבהו","l": "ח","b": "אמורא בדור החמישי. מובא בירושלמי (בכורים רפ\"ב). ואותו ענין מובא בשינוי גיר' ב\"ילקוט\" (תהלים רמז תש\"פ).","cat": "sage"},{"i": 1451,"n": "רב חינא","l": "ח","b": "מובא בירושלמי (שבת פי\"ג ה\"ו), ונראה שהוא רב הונא.","cat": "sage"},{"i": 1452,"n": "רב חיננא","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של רב (בכורות ל\"ב ע\"א).","cat": "sage"},{"i": 1453,"n": "ר' חיננא (2)","l": "ח","b": "ע\"ע ר' חנינא או ר' חנניה.","cat": "sage"},{"i": 1454,"n": "ר' חיננא אבוה דבר ישיטה","l": "ח","b": "אמורא ארץ ישראלי בדור השני - השלישי. ר' אבהו אמר בשמו, ובנו של ר' חיננא היה ה\"אמורא\" של ר' אבהו (ירו', מגילה פ\"ד ה\"י).","cat": "sage"},{"i": 1455,"n": "ר' חיננא אבוה דר' ינטה","l": "ח","b": "מובא בירושלמי (פסחים רפ\"ד), ונראה שהוא אבוה דבר נטה (ירו', מגילה פ\"ד ה\"י).","cat": "sage"},{"i": 1456,"n": "ר' חיננא בי רבי חנניה","l": "ח","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (סנהדרין ספ\"ז).","cat": "sage"},{"i": 1457,"n": "רב חיננא בר אבא","l": "ח","b": "מובא בבבלי (יבמות ל\"ו ע\"א), והוא רב חיננא בר אבין.","cat": "sage"},{"i": 1458,"n": "רב חיננא בר אידי","l": "ח","b": "אמורא בבלי בדור השלישי. תלמידו של רב אדא בר אהבה (ע\"ז מ' ע\"א).","cat": "sage"},{"i": 1459,"n": "ר' חיננא בר אנדריי","l": "ח","b": "מובא בירושלמי (מגילה פ\"ד ה\"ה) והוא ר' חנינא בר אנדריי.","cat": "sage"},{"i": 1460,"n": "רב חיננא בר ביסנא","l": "ח","b": "מובא בבבלי (ביצה כ\"ב ע\"א). סביב שם זה יש גיר' שונות ב\"סה\"ד\" ו\"דק\"ס\".","cat": "sage"},{"i": 1461,"n": "רב חיננא בר חייא","l": "ח","b": "אמורא בבלי בדור השלישי. מצינו שהקשה לר' יהודה: \"ומי אמר שמואל הכי והא וכו'\" (כתובות כ\"א ע\"א).","cat": "sage"},{"i": 1462,"n": "רב חיננא בר יהודה","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של רב (סנהדרין ע\"ז ע\"ב).","cat": "sage"},{"i": 1463,"n": "ר' חיננא בר יצחק","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. מבעלי האגדה. מובא רק בירושלמי ובאגדות. ר' יהושע בר נחמיה מסר בשמו (ב\"ר פ\"ח - יא).","cat": "sage"},{"i": 1464,"n": "ר' חיננא בר כהנא","l": "ח","b": "מובא בבבלי (שבת צ\"ו ע\"א), והוא ר' חנינא בר כהנא.","cat": "sage"},{"i": 1465,"n": "רב חיננא בר שילת","l": "ח","b": "אמורא בבלי בדור השני. נראה, שהיה קרובו של רב, שאהבו מאד ואמר: כל מי שיבוא עלי במחתרת אהרגנו, חוץ מרב חיננא בר שילת (סנהדרין ע\"ב ע\"ב). נראה שהיה תלמידו של שמואל (עירובין י\"ב ע\"א). שמו נשתבש בכמה אופנים: ר' חנניה בר שילא ור' חנינא בר שילא. היה חשוב בעיני ראש הגולה (שבת נ\"ח ע\"א).","cat": "sage"},{"i": 1466,"n": "רב חיננא בר שלמיא","l": "ח","b": "אמורא בבלי בדור השני. מתלמידיו של רב (פסחים ק\"ה ע\"א). קיבל גם מרב ירמיה בר אבא (ירו', סוכה פ\"א ה\"א). אחר פטירת רב שאל משמואל (סנהדרין כ\"ד ע\"ב), אך נראה שלא בא לפני שמואל ממש, אלא רק שלח שאלותיו (שם). חברם של רב עמרם ורב המנונא סבא (שם). היה מרבותיו של רב חייא בר רב (עירובין צ\"ח ע\"ב).","cat": "sage"},{"i": 1467,"n": "חיננא בר שלמיה","l": "ח","b": "מובא בירושלמי (סוכה פ\"א ה\"ו), והוא רב חיננא בר שלמיא.","cat": "sage"},{"i": 1468,"n": "רב חיננא בריה דרב איקא","l": "ח","b": "אמורא בבלי בדור החמישי. יתכן אולי לדייק, שהיה תלמידם של אביי ורבא (ברכות כ\"ה ע\"ב). בגלל חילופי מלים עם רב פפא ורב הונא בריה דר' יהושע, נענש ומת (שם נ\"ח ע\"ב).","cat": "sage"},{"i": 1469,"n": "ר' חיננא בריה דרב אסי בר ממל","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ר' אלעזר (ירו', גיטין פ\"ג ה\"ח), ונראה שהוא ר' חיננא בריה דרב אסי (ירו', שם פ\"א ה\"א). היה רופא.","cat": "sage"},{"i": 1470,"n": "רב חיננא בריה דרבא מפשרוניא","l": "ח","b": "אמורא בבלי בדור הרביעי. היה הריש בפשרוניא. רבא אמר עליו: \"מאן חכים למישרי מלתא כי הא, אי לאו רב חיננא בריה דרבא מפשרוניא, דגברא רבה הוא\" (פסחים ע\"ו ע\"א). מימרתו (מנחות מ\"ב ע\"א) מובאת (גיטין מ\"ה ע\"ב) בשם ר' המנונא בריה דרבא מפשרוניא. אחיו רב עוקבא, שהיה חכם, גר בפשרוניא והקשה לרבא (פסחים צ\"א ע\"א). אולי רב עוקבא בר חיננא מפרישנא הוא בנו (פסחים צ\"א ע\"א).","cat": "sage"},{"i": 1471,"n": "ר' חיננא בריה דר' אסי","l": "ח","b": "מובא בירושלמי (גיטין פ\"א ה\"א), ונראה שהוא ר' חיננא בריה דר' אסי בר ממל.","cat": "sage"},{"i": 1472,"n": "ר' חיננא בריה דר' הלל","l": "ח","b": "מובא בירושלמי (תרומות פ\"ד ה\"ו), והוא ר' חנינא בריה דר' הלל.","cat": "sage"},{"i": 1473,"n": "רב חיננא בריה דר' יהושע","l": "ח","b": "מובא בבבלי (פסחים ק\"י ע\"ב). ו\"דק\"ס\" גורס: \"רב הונא בריה דר' יהושע\".","cat": "sage"},{"i": 1474,"n": "רב חיננא וורדאן","l": "ח","b": "אמורא בבלי בדור השני - השלישי. הקשה על דברי רב חסדא ועל תשובתו (גיטין ס\"ד ע\"ב).","cat": "sage"},{"i": 1475,"n": "ר' חיננא חברה דרבנן","l": "ח","b": "מובא בירושלמי (עירובין פ\"ג ה\"ה).","cat": "sage"},{"i": 1476,"n": "רב חיננא מסורא","l": "ח","b": "אמורא בבלי בדור החמישי - הששי. חלק עם מר זוטרא (נדה ס\"ז ע\"ב) ועם רב מרי (זבחים פ\"ה ע\"ב).","cat": "sage"},{"i": 1477,"n": "רב חיננא סבא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' אסי. (פסחים ע\"ה ע\"א).","cat": "sage"},{"i": 1478,"n": "ר' חיננא קרת חייה","l": "ח","b": "מובא בירושלמי (ביצה פ\"א ה\"ו). ע\"ע רב אחא קרטיגנאה.","cat": "sage"},{"i": 1479,"n": "ר' חיננא קרתיגנאה","l": "ח","b": "מובא בירושלמי (שבת פט\"ז ה\"ב). ע\"ע רב אחא קרטיגנאה.","cat": "sage"},{"i": 1480,"n": "חיפא","l": "ח","b": "מובא בירושלמי (נדרים פ\"ב ה\"ג), והוא עיפא בן רחבה דפומבדיתא.","cat": "sage"},{"i": 1481,"n": "ר' חכינאי","l": "ח","b": "תנא בדור השני - השלישי. אביו של התנא הנודע ר' חנניא בן חכינאי. מובא (בפדר\"א פמ\"א).","cat": "sage"},{"i": 1482,"n": "רבי חלבו","l": "ח","b": "אמורא בבלי בדור השלישי. מחשובי תלמידי ר\"ה. למד יחד עם חבריו: ר' אבא בר זבדא, רב גידל, רב ששת ורב אחא בר יעקב (יבמות ס\"ד ע\"ב). כן קיבל מרב חמא בר גוריון, תלמידו של רב (שבת ל\"ז ע\"ב), ומסר שמועות בשם רב (ירו', ברכות ספ\"ט). עלה לארץ ישראל ושם היה תלמידם של שמואל בר נחמני (ירו', מגילה פ\"א ה\"א), רבי אמי (ירו', כלאים פ\"ט ה\"ג) ור' יצחק נפחא (גיטין ס' ע\"א). תלמידו היה רבי ברכיה (ב\"ר פע\"ח - א'). ידוע מאמרו: \"קשים גרים לישראל כספחת\" (קידושין ע' סע\"ב).","cat": "sage"},{"i": 1483,"n": "ר' חלבו בקרוייה","l": "ח","b": "מובא במדרש תהלים (פ\"כ - ט'), והוא אבא חליפא קרויא.","cat": "sage"},{"i": 1484,"n": "ר' חלבו בר חונה","l": "ח","b": "מובא בירושלמי (נזיר רפ\"ג), ויתכן מאד שצ\"ל: ר' חלבו [בשם] ר' חונה [הוא ר\"ה].","cat": "sage"},{"i": 1485,"n": "ר' חלבו בר חילפא בר סמקאי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר' יהודה בר' סימון (ב\"ר פנ\"א - ב').","cat": "sage"},{"i": 1486,"n": "ר' חלבו בר חנן","l": "ח","b": "אמורא בבלי בדור השני. מסר בשם רב, ורב ששת מתיב עליו (ירו', ברכות פ\"ז ה\"א).","cat": "sage"},{"i": 1487,"n": "ר' חליפי בר זטרי","l": "ח","b": "מובא בפד\"כ (קלג), ויש גירסא אחרת (ויק\"ר רפט\"ז ובאיכ\"ר פ\"ד - יח).","cat": "sage"},{"i": 1488,"n": "חלפא בר אידי","l": "ח","b": "מובא בויק\"ר (פט\"ז), ונראה שיש שיבוש בשם.","cat": "sage"},{"i": 1489,"n": "רבי חלפו בר זביד","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אסי (איכ\"ר פ\"ד - י\"ח).","cat": "sage"},{"i": 1490,"n": "ר' חלפון","l": "ח","b": "מובא בב\"ר (פי\"ט - ז').","cat": "sage"},{"i": 1491,"n": "חלפי בר זביד","l": "ח","b": "מובא באיכ\"ר (פ\"ד - י\"ח), ואולי הוא זהה לר' חליפי בר זטרי (פד\"כ קלג).","cat": "sage"},{"i": 1492,"n": "רבי חלפתא (2)","l": "ח","b": "תנא בדור השלישי. אביו ורבו של התנא הנודע רבי יוסי בר חלפתא. חי בזמן הבית ומסר לרבן גמליאל דיבנה מעשה מזקנו רבן גמליאל הזקן, שראהו עומד על גבי מעלה בהר הבית (שבת קט\"ו ע\"א). היה הריש בצפורי (ר\"ה כ\"ז ע\"א). חברם של רבי יוחנן בן נורי (תוספתא ב\"ב פ\"ב י') ורבי חנניה בן תרדיון (תענית ט\"ז ע\"ב). הלך עם חבריו אלעזר בן מתיא וחנניה בן חכינאי לראות את האבנים שהעמיד יהושע בן נון בירדן (סוטה ל\"ד ע\"א). היה עם ר' חוצפית המתורגמן ורבי ישבב אצל רבי אלעזר בן עזריה בצפורי (תוספתא כלים ב\"ב ב'). חוץ מבנו, לא מצינו לו תלמידים.","cat": "sage"},{"i": 1493,"n": "ר' חלפתא איש כפר חנניה","l": "ח","b": "מובא בתוספתא (כלים פ\"ד ט'), והוא אבא חלפתא איש כפר חנניא.","cat": "sage"},{"i": 1494,"n": "ר' חלפתא בן קוינא","l": "ח","b": "מובא בתוספתא (מכשירין פ\"ג ב').","cat": "sage"},{"i": 1495,"n": "רבי חלפתא בן שאול","l": "ח","b": "אמורא בדור המעבר בין התנאים לאמוראים. היה משוני הברייתות (ירו', ברכות פ\"א ה\"ה). יש השערה שהיה אחיהם של ר' יוסי בן שאול (תלמידו של רבי) ור' יוחנן בן שאול. פעם אחת הובאו יחד רבי חלפתא ורבי יוסי (ירו', שבת פ\"ד ה\"ב).","cat": "sage"},{"i": 1496,"n": "ר' חלפתא בר כהנא","l": "ח","b": "מובא בתנחומא (פ' חיי שרה - ו').","cat": "sage"},{"i": 1497,"n": "רבי חלפתא ברבי יוסי","l": "ח","b": "תנא בדור החמישי. אחד מחמשת בניו של ר' יוסי בר חלפתא (שבת קי\"ח ע\"ב).","cat": "sage"},{"i": 1498,"n": "רבי חלפתא דמן הוה","l": "ח","b": "מובא בירושלמי (גיטין פ\"ט ה\"ג), והוא רבי חלפתא דמן הונא.","cat": "sage"},{"i": 1499,"n": "רבי חלפתא דמן הונא","l": "ח","b": "אמורא ארץ ישראלי בדור הראשון. ר' יוחנן מסר לבני ר' חלפתא הלכות בשם אביהם (גיטין פ\"ו ע\"ב).","cat": "sage"},{"i": 1500,"n": "רבי חלפתא דמן חיפא","l": "ח","b": "מובא בבבלי (גיטין פ\"ו ע\"ב), והוא רבי חלפתא דמן הונא.","cat": "sage"},{"i": 1501,"n": "ר' חלפתא קסריא","l": "ח","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי שמעון בן לקיש (שהש\"ר פ\"ד - י\"א).","cat": "sage"},{"i": 1502,"n": "רבי חלקיה","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי סימון (ירו', שקלים פ\"א ה\"ד). רבו של רבי פנחס (ב\"ר פ\"ט - י\"ב). אולי הוא רבי חלקיה הדרומי, כמובא בתנחומא: \"רבי פנחס בשם רבי חלקיה הדרומי\" (פ' קדושים א').","cat": "sage"},{"i": 1503,"n": "רב חלקיה בר טובי","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של רב (ב\"ב ל\"ט ע\"ב). התרועע עם גדולי תלמידיו של רב (שם). היה עובד אדמה, ובדרך מיוחדת הניב שדהו כפליים תבואה (מנחות פ\"ה ע\"ב).","cat": "sage"},{"i": 1504,"n": "רב חלקיה בר טוביה","l": "ח","b": "מובא בבבלי (גיטין נ\"ז ע\"א), והוא רב חלקיה בר טובי.","cat": "sage"},{"i": 1505,"n": "רבי חלקיה בריה דרב אויא","l": "ח","b": "אמורא בבלי כנראה בדור הרביעי. מובא בבבלי: \"אמר ליה ההוא מרבנן ורב חלקיה בריה דרב אויא שמיה וכו', אלא אמר רבא וכו'\" (ב\"מ צ\"ו ע\"ב).","cat": "sage"},{"i": 1506,"n": "ר' חלקיה הדרומי","l": "ח","b": "ע\"ע רבי חלקיה.","cat": "sage"},{"i": 1507,"n": "רב חלקיה מהגרוניא","l": "ח","b": "אמורא בבלי שזמנו אינו ידוע. מובא בבבלי (יבמות ט' ע\"א: הוריות ח' ע\"א).","cat": "sage"},{"i": 1508,"n": "רב חמא","l": "ח","b": "אמורא בבלי בדור הרביעי - החמישי. מושבו היה בנהרדעא (סנהדרין י\"ז ע\"ב). עמד בראש ישיבת פומבדיתא כעשרים שנה. נפטר בשנת ד' קל\"ז (773) לאחר פטירתו של רב נחמן בר יצחק (\"אגרת רב שרירא גאון\"). מסר בשם רבא (כתובות פ\"ו ע\"א). רב פפא היה חברו (שם). אמימר מסר משמו (שם). מלך פרס פנה אליו בשאלה בענין קבורת מתים (סנהדרין מ\"ו ע\"ב) ולא מצא מה להשיב לו, ואמר עליו רב אחא בר יעקב: \"אימסר עלמא בידא דטפשאי\" (שם). פרנסתו היתה הלואת כסף - ונענש (ב\"מ ס\"ט ע\"ב).","cat": "sage"},{"i": 1509,"n": "ר' חמא אבוה דר' אושעיא","l": "ח","b": "מובא בירושלמי (מו\"ק פ\"ג ה\"ה). והוא ר' חייא בר ביסא.","cat": "sage"},{"i": 1510,"n": "ר' חמא אבוי דבר קפרא","l": "ח","b": "מובא בירושלמי (שבועות פ\"ו ה\"ב). \"סה\"ד\" כתב שהוא ט\"ס, וצ\"ל: ר' חמא אבי ר' הושעיה, ובר קפרא.","cat": "sage"},{"i": 1511,"n": "חמא אבוי דרב יוסף","l": "ח","b": "אמורא בבלי בדור השני. מובא בבבלי: \"בעא מיניה אבוה דרב יוסף בר חמא מרבה בר נתן\" (סנהדרין פ\"א ע\"א). היה זקנו של רבא (עירובין נ\"ד ע\"א).","cat": "sage"},{"i": 1512,"n": "ר' חמא אבוי דר' יהושעיה","l": "ח","b": "מובא בירושלמי (שקלים פ\"ה ה\"ד), והוא ר' חייא בר ביסא.","cat": "sage"},{"i": 1513,"n": "ר' חמא בן לקיש","l": "ח","b": "מובא בשאלתות (בראשית). מאמרו שם, מובא בתנחומא בשם ר' יהודה בן גדיא: \"כל העונה אמן בעוה\"ז זוכה ועונה לעוה\"ב\" (פ' צו - ט').","cat": "sage"},{"i": 1514,"n": "רב חמא בר אבא","l": "ח","b": "אמורא בבלי בדור השני - השלישי. רב נחמן הוסיף על דבריו והסבירם (יבמות ס\"ב ע\"ב).","cat": "sage"},{"i": 1515,"n": "חמא בר אדא","l": "ח","b": "אמורא בבלי בדור השני - השלישי. היה רגיל לעלות לירושלים (ביצה כ\"ה ע\"ב) ורב נחמן אמר לו פעם: \"כי סלקת להתם אקיף וכו' וזיל לגבי דר' יעקב בר אידי ובעי מיניה וכו'\", ועד שהגיע לשם נפטר ר' יעקב בר אידי (שם).","cat": "sage"},{"i": 1516,"n": "ר' חמא בר אושעיא","l": "ח","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (סנהדרין כ\"ה ע\"א).","cat": "sage"},{"i": 1517,"n": "ר' חמא בר אשי","l": "ח","b": "מובא בירושלמי (כתובות פ\"ב ה\"ט). \"סה\"ד\" מפקפק אם הוא ט\"ס וצ\"ל: רב חנין בר אשי. יש גורסים: ר' חייא בר אשי.","cat": "sage"},{"i": 1518,"n": "רב חמא בר בוזי","l": "ח","b": "אמורא בבלי בדור החמישי. תלמידו המובהק של רבא. חברו של רבינא (ב\"ב ט\"ז ע\"ב). רבא קרא לשניהם: \"דרדקי\" (שם), ומובא ששניהם באו לביתו של ריש גלותא (ברכות נ' ע\"א).","cat": "sage"},{"i": 1519,"n": "רב חמא בר ביסא","l": "ח","b": "תנא בדור החמישי. מאחרוני התנאים. רבי אמר עליו שהוא אדם גדול (נדה י\"ד ע\"ב). אביו של האמורא מחבר הברייתות רבי אושעיא רבה. מושבו היה בדרום (ירו', נדה פ\"ג ה\"ב). למד בישיבה 21 שנה וכשחזר לא הכיר את בנו ר' אושעיא (כתובות ס\"ב ע\"ב). ר' אושעיא בנו חלק עליו וניצחו (ב\"ב נ\"ט ע\"א). תוספות מפרשים (שם) שהיה גדול מאביו, ואכן מוזכר על שם בנו ר' חמא אבוי דר' אושעיא בירושלמי (שקלים פ\"ה ה\"ד: נדה רפ\"ב). רמי בר חמא אמר: \"והחוט המשולש לא במהרה ינתק זה ר' אושעיא בנו של ר' חמא בנו של ר' ביסא\" (כתובות שם). בר פלוגתיה דבר קפרא (מו\"ק כ\"ד ע\"א). רבי יוסי בר חנינא מסר בשמו (ירו', שביעית פ\"ב ה\"ב לפי דפוס וינציה).","cat": "sage"},{"i": 1520,"n": "רב חמא בר ברתיה דחסא","l": "ח","b": "אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי: \"אמר רב כהנא: אישתעי לי רב חמא בר ברתיה דחסא: רבה בר נחמני אגב שמדא, נח נפשיה\" (ב\"מ פ\"ו ע\"א).","cat": "sage"},{"i": 1521,"n": "רב חמא בר גוריא","l": "ח","b": "אמורא בבלי בדור השני. תלמידו המובהק של רב והרבה למסור בשמו (ירו', יבמות פ\"ד הט\"ו: בבלי שבת י\"א ע\"ב). למד גם לפני שמואל (ב\"ק צ\"ט ע\"ב). רבים קיבלו ממנו וביניהם רב חסדא (מנחות ע\"ח ע\"א), ר' חלבו (שבת ל\"ז ע\"א) ורבה (עירובין ע\"ט ע\"ב).","cat": "sage"},{"i": 1522,"n": "רב חמא בר חלפתא","l": "ח","b": "מובא בויק\"ר (פכ\"ח - ו').","cat": "sage"},{"i": 1523,"n": "רבי חמא בר חנינא","l": "ח","b": "אמורא ארץ ישראלי בדור השני. בנו ותלמידו של האמורא הגדול רבי חנינא בר חמא (שמו\"ר פכ\"א - ז'). עוד זכה להיות בחברתו של רבי (שבת ל\"ח ע\"א). מושבו בציפורי (ירו', שבת פ\"ו ה\"ב) והיה מגדולי העיר (תענית כ\"ה ע\"א). חלק עם רבי אושעיא (ירו', עירובין פ\"ה סה\"א) ונמצא בחברתו בביקורם בלוד (ירו', סוף פאה). חלק עם רבי יוחנן (שבת קמ\"ז ע\"ב). הצטיין באגדה כאביו. בעל האגדה הנודע רבי לוי, מסר הרבה בשמו (ב\"ר פ\"ט - א').","cat": "sage"},{"i": 1524,"n": "ר' חמא בר חנינא","l": "ח","b": "מובא בבבלי: \"אמר ר' חמא בר חנינא מפירקיה דרבי חייא בר אבא שמיע לי\" (סנהדרין כ\"ט ע\"א). אם אין כאן איזה ט\"ס צריך לומר שאין זה רבי חמא בר רבי חנינא (ע\"ע) בנו של ר' חנינא, שזכה להיות בחברתו של רבי, כי איך יאמר: מפירקיה דרבי חייא בר אבא שמיע לי? הרי ר' חייא בר אבא היה מאוחר יותר.","cat": "sage"},{"i": 1525,"n": "ר' חמא בר חנינא בר פפא","l": "ח","b": "מובא במדרש חזית (פ' הסבי עינך). \"סה\"ד\" גרס, שנראה שהוא ר' חמא בר פפא.","cat": "sage"},{"i": 1526,"n": "רב חמא בר טוביה","l": "ח","b": "אמורא בבלי בזמנו של רב יוסף או לפניו. דן למיתה בת כהן שזנתה (סנהדרין נ\"ב ע\"ב).","cat": "sage"},{"i": 1527,"n": "רבי חמא בר יוסי","l": "ח","b": "מובא בירושלמי (כלאים פ\"ב ה\"ה), והוא רבי חמא בר יוסף.","cat": "sage"},{"i": 1528,"n": "רבי חמא בר יוסף","l": "ח","b": "אמורא ארץ ישראלי בדור השני. מושבו היה בחמתא דגדר [סמוכה לטבריה] (ירו', עירובין פ\"ה ה\"ז). והיה שם הריש (שם פ\"ו ה\"ד). בימי רבי יוחנן ור\"ל כבר היה זקן הדור (שם). היה תלמידו של רבי אושעיא (סנהדרין ט\"ז ע\"ב). התיב קומי רבי יוחנן בהלכה (ירו', ערלה פ\"ב ה\"ה). רבי חייא בר אבא, רבי אסי ורבי אמי, פנו אליו בשאלה הלכתית (ירו', עירובין פ\"ו ה\"ד). רבי דימי מסר בשמו (ע\"ז י\"ד ע\"ב).","cat": "sage"},{"i": 1529,"n": "רבי חמא בר עוקבא","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוסי בר חנינא, ומסר בשמו עשרות מאמרים בש\"ס הבבלי והירושלמי (סוכה ל\"ז ע\"ב). כן אמר בשם רבי יהושע בן לוי (ירו', יומא פ\"ב ה\"א), ובשם ר\"ל (ירו', שבת פ\"ז סה\"ב). התרועע עם רבי לוי (ב\"ר ספמ\"ב). אמרו בשמו רבי יונה (ירו', עירובין פ\"ג ה\"ז) ורבי ירמיה (ירו', כלאים פ\"ז ה\"א).","cat": "sage"},{"i": 1530,"n": "רב חמא בר עקיבא","l": "ח","b": "מובא בבבלי (קידושין נ\"ה ע\"א), ונראה שהוא רב חמא בר עוקבא. \"מסורת הש\"ס\" כתב: \"אפשר דצ\"ל: בר עוקבא\" \"סה\"ד\" כתב: ט\"ס.","cat": "sage"},{"i": 1531,"n": "רבי חמא בר פפא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי יהודה בר סימון (ויק\"ר פכ\"ב - ה'). מאמרו בבבלי: \"כל אדם שיש עליו חן, בידוע שהוא ירא שמים\" (סוכה מ\"ט ע\"ב).","cat": "sage"},{"i": 1532,"n": "רב חמא בריה דרבה בר אבהו","l": "ח","b": "אמורא בבלי בדור השלישי. בנו של האמורא המפורסם רבה בר אבהו. היה גיסו של ר\"נ (יבמות פ' ע\"ב). חברו של אביי (עירובין ג' ע\"א). הלך לא\"י והתרועע שם עם אבימי בריה דרבי אבהו (כתובות פ\"ה ע\"א) כשחזר לבבל ביקש ממנו אבימי להחזיר עבורו בבבל חוב כסף שהיה חייב.","cat": "sage"},{"i": 1533,"n": "ר' חמא דכפר תחומין","l": "ח","b": "אמורא בבלי בדור השני. רב יהודה אמר משמו (מדרש חזית, פסוק \"יונתי בחגוי הסלע\").","cat": "sage"},{"i": 1534,"n": "רב חמא חברהון דרבנן","l": "ח","b": "מובא בירושלמי (ר\"ה פ\"א ה\"א).","cat": "sage"},{"i": 1535,"n": "רב חמא מנהרדעא","l": "ח","b": "מובא בבבלי (ב\"ב ז' ע\"ב תד\"ה: נהרדעי), והוא רב חמא.","cat": "sage"},{"i": 1536,"n": "חנא","l": "ח","b": "אמורא בבלי בדור השלישי. חתנו של ר' אבא בר אהבה. מובא בבבלי (יבמות ק\"י ע\"ב). לגירסת \"יתו\"א\": רב חגא חתניה של רב אדא בר אהבה.","cat": "sage"},{"i": 1537,"n": "רב חנא","l": "ח","b": "אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי: \"אמר רב חנא אמר רב יהודה\" (שבת צ\"ז ע\"א). רב יוסף קרא לו מר (שם). גיר' התוספות (שבת ד' ע\"ב ד\"ה: זרק) \"רב חסדא\" במקום רב יהודה.","cat": "sage"},{"i": 1538,"n": "רב חנא בגדתאה","l": "ח","b": "אמורא בבלי בדור השני. היה מהעיר בגדד שבבבל (רש\"י כתובות ו' ע\"ב) תלמיד מובהק של שמואל (יבמות ס\"ז ע\"א), ומסר משמו כמה מאמרים בש\"ס. בירר אצל רבי יהודה כיצד אמר שמואל בענין מסויים (עירובין פ\"א ע\"ב). בבבלי (כתובות י' ע\"ב) יש ממנו מספר מאמרים ברציפות.","cat": "sage"},{"i": 1539,"n": "רב חנא בר אבא","l": "ח","b": "מובא בירושלמי (שבת ספ\"ד). גיר' \"קרבן העדה\": \"רבי אבא בר חנה\".","cat": "sage"},{"i": 1540,"n": "רב חנא בר אדא","l": "ח","b": "אמורא בבלי בדור השלישי. מובא בבבלי (יבמות ע\"ח ע\"ב). מסר בשם רב סמא בריה דרב מרי [הנזכר בש\"ס רק במקום זה] (ברכות ס\"ב ע\"ב). רבא ביקר אצל בנו מר יוחנא ואכל אצלו (חולין קל\"ג ע\"א).","cat": "sage"},{"i": 1541,"n": "רב חנא בר אחא","l": "ח","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. מובא בבבלי: \"אמר רב חנא בר אחא: אמרי בי רב וכו'\" (סוכה נ\"ב ע\"ב).","cat": "sage"},{"i": 1542,"n": "רב חנא בר ביזנא","l": "ח","b": "אמורא בבלי בדור השני - השלישי. היה דיין בפומבדיתא. ר\"נ ביטל את פסק דינו (כתובות נ' ע\"ב). היה בעל אגדה. מאמרים מעטים אמר בשם עצמו (סנהדרין ק\"ח ע\"ב), ורובם מסר בשם רבי שמעון חסידא (ברכות ז' ע\"א). נראה, שעלה לארץ ישראל וקיבל שם משמעון חסידא (שהיה אמורא ארץ ישראלי בדור הראשון). התוכח עם רב ששת, ולבסוף אמר לו רב ששת: \"בהדי חנא באגדתא למה לי\" (סוכה נ\"ב ע\"ב) ופרש\"י: \"מה לי אצלו באגדה, בקי הוא בהגדה ממני ולא אוכל לו\".","cat": "sage"},{"i": 1543,"n": "רבי חנא בר הינדא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי פדת [בשם] רבי יוחנן (שאלתות פ' מקץ).","cat": "sage"},{"i": 1544,"n": "רב חנא בר חיננא","l": "ח","b": "אמורא בבלי בדור השלישי. מובא בבבלי: \"בעי מרב הונא\" (פסחים ק\"ו ע\"ב).","cat": "sage"},{"i": 1545,"n": "רב חנא בר חנילאי","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של ר\"ה (ביצה מ' ע\"א). התרועע עם רב חסדא (שם כ\"א ע\"א). היה בעל צדקה גדול - בביתו היו 06 אופים שאפו לנצרכים, ובביתו היו ארבעה שערים לארבע רוחות השמים וכל עני שהיה נכנס רעב יצא שבע, ובשנות בצורת היה משליך חטים ושעורים מסביב לבית, כדי שהמתבייש להנות מצדקה יקח מהן בלילה (ברכות נ\"ח ע\"ב). נפטר לפני עולא ורב חסדא (שם).","cat": "sage"},{"i": 1546,"n": "רב חנא בר יהודה","l": "ח","b": "אמורא בבלי בדור החמישי. מסר משמו של רבא (ברכות מ\"ח ע\"א).","cat": "sage"},{"i": 1547,"n": "רב חנא בר ליוואי","l": "ח","b": "מובא בבבלי (סנהדרין ק\"ח ע\"ב). גיר' \"דק\"ס\": ר\"ה בר יהודה.","cat": "sage"},{"i": 1548,"n": "רב חנא בר רב קטינא (2)","l": "ח","b": "אמורא בבלי בדור השלישי. בנו של האמורא רב קטינא. מובא בבבלי (יומא נ\"ד ע\"א) יחד עם אביו, ורב נחמן שהיה חברו (חולין י\"ט ע\"א). הקשה לרבה (נדרים ס\"ה ע\"ב, לגיר' פסקי הרא\"ש). היה לו אח אמורא ושמו רב דניאל בר רב קטינא.","cat": "sage"},{"i": 1549,"n": "ר' חנא בר שאונה","l": "ח","b": "מובא בבבלי (נדה ס\"ה ע\"ב). ע\"ע ר' חנא בר שאינה.","cat": "sage"},{"i": 1550,"n": "ר' חנא בר שאינה","l": "ח","b": "מובא בבבלי (ע\"ז ע\"ה ע\"א). הגמ' מפקפקת אם שמו ר' חנא שאינה או ר' חנא בר שאינה. ובאותו ענין מפקפקת הגמ' אם שמו ר' חנא שאונא או ר' חנא בר שאונא (נדה ס\"ה ע\"ב). \"סה\"ד\" סובר, שהוא ור' יוחנן בר שאונה, המובא בויק\"ר (פ\"ה - ב'), אחד הם.","cat": "sage"},{"i": 1551,"n": "רב חנא חתניה דרב אדא בר אהבה","l": "ח","b": "אמורא בבלי. מובא בבבלי: \"אמר רב נחמן: 'אשכחתיה לרב אדא בר אהבה ולרב חנא חתניה'\" (יבמות ק\"י ע\"ב).","cat": "sage"},{"i": 1552,"n": "רבי חנא פתוראי","l": "ח","b": "אמורא ארץ ישראלי בדור השני. היה שולחני. ר' יוחנן (בר נפחא) שאלו בענין מטבעות (חולין נ\"ד ע\"ב).","cat": "sage"},{"i": 1553,"n": "ר' חנא קרטיגנאה","l": "ח","b": "מובא בבבלי (ב\"ק קי\"ד ע\"ב). ע\"ע רב אחא קרטיגנאה.","cat": "sage"},{"i": 1554,"n": "ר' חנא שאונא","l": "ח","b": "מובא בבבלי (נדה ס\"ה ע\"ב). ע\"ע ר' חנא בר שאינה.","cat": "sage"},{"i": 1555,"n": "ר' חנא שאינה","l": "ח","b": "מובא בבבלי (ע\"ז ע\"ה ע\"א). ע\"ע ר' חנא בר שאינה.","cat": "sage"},{"i": 1556,"n": "חנה","l": "ח","b": "אחי אביו (דודו) של רב ואביו של רבה בר חנה. היו לו ארבעה אחים: איבו, שילא, מרתא ורבי חייא (סנהדרין ה' ע\"א).","cat": "sage"},{"i": 1557,"n": "ר' חנה ציפוראי","l": "ח","b": "מובא בבבלי (ר\"ה ל\"ד ע\"ב), ולגיר' \"דק\"ס\" צ\"ל: ר' חונא ציפוראה. ע\"ע רב הונא דציפורין.","cat": "sage"},{"i": 1558,"n": "ר' חנון בן פזי","l": "ח","b": "מובא בויק\"ר (פכ\"ה - ו'). יש סבורים שהוא ר' חנינא בן פזי.","cat": "sage"},{"i": 1559,"n": "ר' חנילאי","l": "ח","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי שאמר משום ר\"א בר שמעון (נדה מ\"ג ע\"ב). מצינו: ר' תנחום אמר ר' חנילאי (יבמות ס\"ב ע\"ב).","cat": "sage"},{"i": 1560,"n": "רב חנילאי בר אידי","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של שמואל (כתובות ע\"ט ע\"א). מר עוקבא אמר: \"הכי אמר ר' חנילאי בר אידי\" (שם). ר' נחמן הסתמך על שמועותיו (גיטין נ\"ב ע\"א).","cat": "sage"},{"i": 1561,"n": "ר' חנילאי בר חנילאי","l": "ח","b": "מובא בבבלי (ע\"ז י\"ח ע\"ב). \"מסורת הש\"ס\" גורס: ר' תנחום בר חנילאי, וכן גיר' \"דק\"ס\" וכן נראה לגיר' \"סה\"ד\".","cat": "sage"},{"i": 1562,"n": "רב חנילאי מחוזנאה","l": "ח","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (עירובין נ\"ז ע\"א). \"סה\"ד\" מפקפק אם הוא ור' חנין מחוזנאה חד הם.","cat": "sage"},{"i": 1563,"n": "חנין","l": "ח","b": "שם המתחלף בחנן.","cat": "sage"},{"i": 1564,"n": "רב חנין (2)","l": "ח","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (גיטין פ\"ה ע\"ב). \"סה\"ד\" שקיל וטרי בענין הגירסא שם.","cat": "sage"},{"i": 1565,"n": "ר' חנין (2)","l": "ח","b": "אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם ר' חנינא (ברכות ל\"ב ע\"ב, ו\"דק\"ס\" גורס אחרת), ובשם ר' יהושע בן לוי (ירו', ב\"ב פ\"ח ה\"ח). היה בעיקר בעל אגדה.","cat": "sage"},{"i": 1566,"n": "ר' חנין בן פזי","l": "ח","b": "מובא במדרש תהלים (פצ\"ב - י\"ב). יש סבורים שהוא ר' חנינא בן פזי.","cat": "sage"},{"i": 1567,"n": "חנין בן פנחס","l": "ח","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (סוטה ד' ע\"א).","cat": "sage"},{"i": 1568,"n": "ר' חנין בר אביי","l": "ח","b": "מובא בבבלי: \"דא\"ר חנין בר אביי א\"ר פדת אמר רבי יוחנן\" וא\"כ, היה אמורא ארץ ישראלי בדור הרביעי. (פסחים ק\"א ע\"א). אך \"דק\"ס\" גורס: \"ר' חנין בר אמי\", ו\"סה\"ד\" כתב: \"ר' חנין בר אביי, בודאי ט\"ס\".","cat": "sage"},{"i": 1569,"n": "ר' חנין בר אדא","l": "ח","b": "מובא במדרש תהלים (פ\"ה - ב').","cat": "sage"},{"i": 1570,"n": "רב חנין בר אמי","l": "ח","b": "מובא בבבלי (שבת י\"ג ע\"א). ואולי צריך לגרוס (כמו בחולין ק\"ז ע\"ב): רב חנן בר אמי.","cat": "sage"},{"i": 1571,"n": "ר' חנין בר אשי","l": "ח","b": "מובא בבבלי (בכורות ל\"ד ע\"א), ואולי צריך לגרוס ר' חנין בר אמי, או ר' חנן בר אמי, כמו במקומות אחרים (שבת קי\"א ע\"ב: כתובות ל\"א ע\"א: בכורות כ\"ה ע\"א).","cat": "sage"},{"i": 1572,"n": "ר' חנין בר בא","l": "ח","b": "מובא (ירו', שבת פ\"ו ה\"ב). ע\"ע ר' חנן בר אבא.","cat": "sage"},{"i": 1573,"n": "רב חנין בר ביזנא","l": "ח","b": "מובא בבבלי (סוטה י' ע\"ב). ונראה שצ\"ל: ר' חנא בר ביזנא.","cat": "sage"},{"i": 1574,"n": "ר' חנין בר לוי","l": "ח","b": "מובא בירושלמי (ביצה רפ\"ד).","cat": "sage"},{"i": 1575,"n": "רב חנין בר פפא","l": "ח","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (עירובין ס\"ה ע\"א).","cat": "sage"},{"i": 1576,"n": "ר' חנין בר רבא","l": "ח","b": "מובא בבבלי (פסחים קי\"ז ע\"א). ע\"ע רב חנן בר רבא.","cat": "sage"},{"i": 1577,"n": "רב חנין בריה דרב ייבא","l": "ח","b": "אמורא בבלי בדור הרביעי בזמנו של רבא, שאמר עליו: \"מאן חכים למעבד כי הא מלתא, אי לאו רב חנין בריה דרב ייבא\" (ב\"ב קע\"ד ע\"א).","cat": "sage"},{"i": 1578,"n": "ר' חנין בריה דרבי","l": "ח","b": "מובא בויק\"ר (רפ\"ב - כ\"ב). ונראה שצ\"ל: ר' חנן בריה דר' ברכיה בוצריה, כמו בשהש\"ר (פ\"ז - א').","cat": "sage"},{"i": 1579,"n": "ר' חנין דציפורי","l": "ח","b": "ע\"ע רב הונא דציפורין.","cat": "sage"},{"i": 1580,"n": "ר' חנין חתניה דבי נשיאה","l": "ח","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מת ביום שילדה אשתו בן, וקראו לבן: חנין על שמו. (מו\"ק כ\"ה ע\"א).","cat": "sage"},{"i": 1581,"n": "חנין מגופתייה","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של שמואל (ירו', שבת פ\"ה ה\"ב). שמואל קנסו על שעקר כלאים (ירו', ערלה פ\"ג ה\"ז).","cat": "sage"},{"i": 1582,"n": "ר' חנין מחוזנאה","l": "ח","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (גיטין פ\"ה ע\"ב). \"סה\"ד\" מפקפק אם הוא ור' חנילאי מחוזנאה אחד.","cat": "sage"},{"i": 1583,"n": "רבי חנינא (2)","l": "ח","b": "מובא (ע\"ז ל\"ח ע\"ב), והוא רבי חנינא דציפורין.","cat": "sage"},{"i": 1584,"n": "ר' חנינא (2)","l": "ח","b": "תנא בדור השלישי. בהיותו צעיר ניבא לו רבן גמליאל שיהיה מורה הוראה בישראל, וכן היה (נזיר כ\"ט ע\"ב). ובירושלמי \"אמר רבי אלעזר בר צדוק: 'אני ראיתיו יושב ודורש ביבנה'\" (נזיר ספ\"ד). מובא בברייתא (ברכות ב' ע\"ב) אחרי ר' מאיר ור' יהודה.","cat": "sage"},{"i": 1585,"n": "ר' חנינא אביו של ר' אחא","l": "ח","b": "מובא בתנחומא (בובר פ' נשא), ואולי צ\"ל: ר' הונא אביו של ר' אחא.","cat": "sage"},{"i": 1586,"n": "ר' חנינא אחוה דר' מנא","l": "ח","b": "מובא בירושלמי ששאל ר' מנא לר' יוסי כשמת בנו (מו\"ק פ\"ג ה\"ד). אם צריך לכפות המטה.","cat": "sage"},{"i": 1587,"n": "ר' חנינא איש אונו","l": "ח","b": "תנא בדור השלישי - הרביעי. מובא במשנה: \"וזו הלכה העלה ר' חנינא איש אונו מבית האסורין\" (גיטין ס\"ו ע\"א - פירש\"י: משמו של ר' עקיבא). ושם: \"א\"ר שמעון ברבי לפני רבי, מאחר שר\"מ וחנינא איש אונו חולקין, מה ראה רבי לומר הלכה כר' יוסי\" (ס\"ז ע\"א).","cat": "sage"},{"i": 1588,"n": "ר' חנינא בן אורי","l": "ח","b": "תנא בדור הרביעי - החמישי. מובא בדרך ארץ רבה (רפ\"א), שמסר משום ר' נתן.","cat": "sage"},{"i": 1589,"n": "חנינא בן אחי ר' יהושע","l": "ח","b": "מובא בבבלי (שבועות ל\"ה ע\"ב), והוא חנניה בן אחי ר' יהושע.","cat": "sage"},{"i": 1590,"n": "ר' חנינא בן אנטיגנוס","l": "ח","b": "תנא בדור השלישי. נראה, שהאריך ימים ובשעתו ראה את בית המקדש (תוספתא ערכין ספ\"א). רבן שמעון בן גמליאל (אבי רבי) אמר: \"נראין דברי רבי חנינא בן אנטיגנוס מדברי ומדבריהם\" (נדה נ\"ח ע\"ב). גם בנו היה חכם, ור' יהודה ור' יוסי, תלמידי ר\"ע, שלחו אל בנו לשאול הלכה (בכורות ל' ע\"ב).","cat": "sage"},{"i": 1591,"n": "ר' חנינא בן בינאי","l": "ח","b": "מובא בתוספתא (נגעים פ\"א). ו\"סה\"ד\" כתב: נ\"ל ט\"ס וצ\"ל: ר' חנינא בן חכינאי.","cat": "sage"},{"i": 1592,"n": "ר' חנינא בן גמלא","l": "ח","b": "מובא בבבלי (סנהדרין קי\"א ע\"א), ויש גורסים ר' חנינא בן גמליאל.","cat": "sage"},{"i": 1593,"n": "ר' חנינא בן גמליאל","l": "ח","b": "תנא בדור הרביעי בנו של רבן גמליאל דיבנה (נדה ח' ע\"ב רש\"י). אחיו הגדול של רבן שמעון בן גמליאל (אבי רבי). רשב\"ג מסר משמו (תוספתא נדה פ\"ז ה'). נראה שהיה תלמידו של ר' טרפון (נדרים ס\"ב ע\"א) חלק עם ר' עקיבא (נדה שם) ועם תלמידיו של ר' עקיבא (תוספתא ע\"ז פ\"ד).","cat": "sage"},{"i": 1594,"n": "רבי חנינא בן דוסא","l": "ח","b": "תנא בדור הראשון. מופלג בחסידות ומלומד בנסים ותפילתו נשמעה בכל עת: ונהג להתפלל על חולים ולומר \"זה חי וזה מת\" (ברכות ל\"ד ע\"ב). הלך ללמוד תורה אצל ר' יוחנן בן זכאי וכשחלה בנו של ריב\"ז אמר לו \"חנינא בני, בקש עליו רחמים ויחיה הניח ראשו בין ברכיו ובקש עליו רחמים וחיה\" (שם). היה עני מרוד ובזכותו התקיימו בני דורו \"בכל יום ויום בת קול יוצאת ואומרת כל העולם כולו ניזון בשביל חנינא בני וחנינא בני דיו לו בקב חרובים מערב שבת לערב שבת\" (תענית כ\"ד ע\"ב). \"פעם ביקשתו אשתו ואמרה: עד מתי נצטער בקש רחמים\" - \"יצאה כמין פיסת יד\" ונתנה להם רגל של שולחן זהב; לבסוף חזרה בה אשתו וביקש רחמים ונטלו מהשמים את רגל הזהב. \"תנא: גדול היה נס אחרון יותר מן הראשון\" (שם). הקב\"ה זימן לו חמישה מלאכים שעזרו לו (ראש קה\"ר). בפטירתו אמרו: \"משמת רבי חנינא בן דוסא בטלו אנשי מעשה\" (סוף סוטה).","cat": "sage"},{"i": 1595,"n": "חנינא בן חזקיה","l": "ח","b": "מובא בבבלי (מנחות מ\"ה ע\"א), והוא חנניה בן חזקיה בן גרון.","cat": "sage"},{"i": 1596,"n": "חנינא בן חכינאי","l": "ח","b": "מובא במשנה (כלאים פ\"ד ע\"א), והוא חנניה בן חכינאי.","cat": "sage"},{"i": 1597,"n": "ר' חנינא בן עקביא","l": "ח","b": "תנא בדור הרביעי. חברו של ר' יהודה. כשנפטר בנו של ר' יהודה נכנס עמו לבית המדרש וישב לצידו (מו\"ק כ\"א ע\"א). פעם חלק עמו כיצד אמר רבן גמליאל. כן חלק עם ר' יוסי (תוספתא ערכין פ\"א ג'). נראה שהיה הריש בטבריה (עירובין פ\"ז ע\"ב).","cat": "sage"},{"i": 1598,"n": "רבי חנינא בן פזי","l": "ח","b": "מובא בב\"ר (פ' לך לך פ' מ\"ו), והוא חנניא בן פזי.","cat": "sage"},{"i": 1599,"n": "ר' חנינא בן פזי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. הקשה לר' חלבו (ירו', מגילה פ\"ד ה\"ג).","cat": "sage"},{"i": 1600,"n": "ר' חנינא בן שמואל","l": "ח","b": "מובא בירושלמי (סוכה פ\"א ה\"א), והוא ר' חנניה בן שמואל.","cat": "sage"},{"i": 1601,"n": "רבי חנינא בן תרדיון","l": "ח","b": "תנא בדור השלישי. אביה של ברוריה וחותנו של ר\"מ (ע\"ז י\"ח ע\"א). אחד מעשרה הרוגי מלכות (איכ\"ר פ\"ב פ' בלע). נשרף על קידוש השם, ספר תורה עמו (ע\"ז שם), ביום כ\"ז סיון (סוף מגילת תענית). נהרג אחרי ר\"ע (שמחות פ\"ה). כן נגזר על אשתו להריגה ועל בתו לישב בקובה של זונות (ע\"ז שם). בנו נתפס לליסטות (שמחות ספי\"ב). מסר משום ר' אליעזר (יומא ע\"ח ע\"ב). היתה לו ישיבה בסיכנין (סנהדרין ל\"ב ע\"ב). מאמרו הידוע: \"שנים שיושבין ואין ביניהן דברי תורה, הרי זה מושב לצים\" (אבות פ\"ג מ\"ב).Uלםכ","cat": "sage"},{"i": 1602,"n": "ר' חנינא בנו של ר' יוסי הגלילי","l": "ח","b": "תנא בדור הרביעי. מובא בבבלי (ר\"ה ל\"ב ע\"א): \"ירד רבי חנינא בנו של רבי יוסי הגלילי ועשה כרבי עקיבא, אמר רשב\"ג: 'כך היו נוהגין ביבנה'\". מצינו שחלק עם ר' יהודה (חולין י\"ב ע\"א).","cat": "sage"},{"i": 1603,"n": "ר' חנינא בנו של ר' ישמעאל","l": "ח","b": "מובא בש\"ר (פל\"ח - ח').","cat": "sage"},{"i": 1604,"n": "רב חנינא בר אבדימי","l": "ח","b": "אמורא בבלי בדור השני. תלמידו של רב (נדרים ס\"א ע\"ב).","cat": "sage"},{"i": 1605,"n": "רב חנינא בר אבין","l": "ח","b": "אמורא בבלי בדור הרביעי. הוא ואחיו אביי בר אבין היו תלמידי רבה (פסחים ל\"ד ע\"א). אביי היה חברם וקטן מהם (עירובין ס\"ב ע\"א).","cat": "sage"},{"i": 1606,"n": "ר' חנינא בר אחא","l": "ח","b": "אמורא ארץ ישראלי בדור השני. חלק עם ר' חמא בר חנינא (ב\"ר פצ\"ה - ג').","cat": "sage"},{"i": 1607,"n": "ר' חנינא בר איבו","l": "ח","b": "תנא בדור החמישי. מובא בבבלי (שבועות ל\"ה ע\"ב). חלק עם ר' אחי בר יאשיה (ספרא קדושים סק\"ב).","cat": "sage"},{"i": 1608,"n": "ר' חנינא בר אידי","l": "ח","b": "אמורא שזמנו ומקומו אינם ידועים. בבבלי מובא מאמרו: \"למה נמשלו דברי תורה למים וכו', מה מים מניחין מקום גבוה והולך למקום נמוך, אף דברי תורה אין מתקימין אלא במי שדעתו שפלה\" (תענית ז' ע\"א).","cat": "sage"},{"i": 1609,"n": "ר' חנינא בר איסי","l": "ח","b": "מובא בירושלמי (תרומות פ\"ד ה\"ג), ונראה שהוא ר' חנינא בר אסי. ע\"ע ר' חיננא בריה דרב אסי בר ממל.","cat": "sage"},{"i": 1610,"n": "חנינא בר איקא","l": "ח","b": "מובא בירושלמי (כתובות פ\"ז ה\"ו), והוא חנינא בר יקא.","cat": "sage"},{"i": 1611,"n": "ר' חנינא בר אמי","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי. מובא בב\"ר (פט\"ז - ג'), שמסר בשם ר' יהושע דסכנין.","cat": "sage"},{"i": 1612,"n": "ר' חנינא בר אנדריי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שמסר בשם ר' שמואל בר סוטר (ברכות פ\"א ה\"א).","cat": "sage"},{"i": 1613,"n": "רבי חנינא בר חמא","l": "ח","b": "אמורא ארץ ישראלי בדור הראשון. עלה מבבל לא\"י יחד עם בנו (ירו', פאה פ\"ז ה\"ג). ידוע כר' חנינא הגדול (תענית כ\"ז ע\"ב). \"סה\"ד\" כתב שנראה כי הוא סתם ר' חנינא בש\"ס. היה תלמידו המובהק של רבי, שאמר עליו בשעת פטירתו: \"חנינא בר חמא ישב בראש\" (כתובות ק\"ג ע\"ב). אך רבי לא הסמיכו בחייו (ירו', תענית פ\"ד ה\"ב). וכשקיסר אנטונינוס בא בהסתר לרבי ישב ר' חנינא אצלו (ע\"ז י' ע\"ב). קיבל מר' ישמעאל בר' יוסי (קידושין ע\"א ע\"ב) מר' חייא (ירו', שביעית פ\"ו ה\"א) ומבר קפרא (ירו', נדה פ\"ב ה\"ז). בין תלמידיו הרבים היו ר' יוחנן (ירו', הוריות פ\"ג ה\"ד).","cat": "sage"},{"i": 1614,"n": "ר' חנינא בר חנינא","l": "ח","b": "מובא בירושלמי (נזיר ספ\"ד), והוא ר' חנינא (התנא).","cat": "sage"},{"i": 1615,"n": "חנינא בר יונה","l": "ח","b": "מובא ב\"ילקוט\" (מלאכי רמז תקפט).","cat": "sage"},{"i": 1616,"n": "ר' חנינא בר יוסף","l": "ח","b": "מובא בבבלי (עירובין ס\"ה ע\"ב). ויש לפקפק (וכן ב\"סה\"ד\") אם אין כאן שיבוש בשם.","cat": "sage"},{"i": 1617,"n": "ר' חנינא בר יסא","l": "ח","b": "מובא בירושלמי (ע\"ז פ\"ג ה\"ה), והוא ר' חנינא בר יקא.","cat": "sage"},{"i": 1618,"n": "ר' חנינא בר יקא","l": "ח","b": "אמורא בבלי בדור השלישי. בשמו יש כמה וכמה שיבושים. מסר בשם רבי יהודה: \"שורשי חטה בוקעין וכו'\" (ירו', ברכות פ\"ט ה\"ב), ואותו מאמר בשם ר' חנינא בר יסא (ירו', ע\"ז פ\"ג ה\"ה), וכן בשם ר' חנינא בריקא (ירו', תענית פ\"א ה\"ג). וכן מצינו: \"ר' חנינא בן ברוקא בני מישא וכו'\" (ירו', קידושין פ\"ד ה\"א), ואותו מאמר בשם ר' חנינא ברוקא (ירו', יבמות פ\"א ה\"ו). וכן מצינו שיבושים נוספים: ר' חנינא בר עיזקא (ב\"ר ספ\"ג), חנינא בר איקא (ירו', כתובות פ\"ז ה\"ו) והכל אחד הוא.","cat": "sage"},{"i": 1619,"n": "רב חנינא בר כהנא (2)","l": "ח","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (ביצה ו' ע\"א) ושל שמואל (ב\"ק קי\"ג ע\"ב). מסר גם בשם ר' אלעזר (שבת צ\"ו ע\"א).","cat": "sage"},{"i": 1620,"n": "ר' חנינא בר ליוואי","l": "ח","b": "מובא בבבלי (סנהדרין ק\"ח ע\"ב), לפי גיר' \"יוחסין\" ו\"דק\"ס\", לפנינו ר' חנא בר ליוואי.","cat": "sage"},{"i": 1621,"n": "רב חנינא בר מיניומי","l": "ח","b": "אמורא בבלי בדור החמישי. הקשה לאביי (ב\"ב קל\"א ע\"א). שנה ברייתא של דבי ר' אלעזר בן יעקב (התנא) (יומא מ\"ה ע\"ב).","cat": "sage"},{"i": 1622,"n": "רבי חנינא בר סיסי","l": "ח","b": "מובא בירושלמי (סנהדרין פ\"ב ה\"ו). היה דיין בציפורן. רבי יוחנן כינהו רבי. \"סה\"ד\" סבור שהוא רבי אנינייא בר סיסי.","cat": "sage"},{"i": 1623,"n": "ר' חנינא בר סנסן","l": "ח","b": "מובא בב\"ר (פי\"ט - ב').","cat": "sage"},{"i": 1624,"n": "רבי חנינא בר סרסי","l": "ח","b": "מובא בבבלי (ברכות מ\"ח ע\"א תד\"ה: ולית). ע\"ע רבי חנינא בר סיסי. נראה, שיש שם איזה ט\"ס, שכן לפי התוספות היה תנא בדור השלישי דודו של רבי יוסי בר חלפתא וזה לשון התוספות: \"ומיהו קאמר בירושלמי אמר רבי יוסי זמנין אכלית עם רבי חלפתא אבא ועם רבי חנינא בר סרסי חביבי\" [דודי], ואכן \"סה\"ד\" כתב (בערך ר' חנינא בר סיסי) שהיה דודו של רבי יוסי בר חלפתא, בהסתמך על התוס' בברכות.","cat": "sage"},{"i": 1625,"n": "ר' חנינא בר עגול","l": "ח","b": "מובא בירושלמי (יבמות פ\"ו ה\"ו), והוא ר' חנינא בר עגיל.","cat": "sage"},{"i": 1626,"n": "ר' חנינא בר עגיל","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי הרביעי. שאל מר' חייא בר אבא: מפני מה בדברות הראשונות לא נאמר בהם טוב ובדברות האחרונות נאמר בהם טוב? ולא ידע להשיב לו, ושלחו לר' תנחום בר חנילאי והוא השיב לו (ב\"ק נ\"ה ע\"א).","cat": "sage"},{"i": 1627,"n": "ר' חנינא בר עטל","l": "ח","b": "מובא באס\"ר (פ\"ב - ה'), והוא ר' חנינא בר עיגול (כמובא מדרש אבא גוריון פסוק ובמלאת).","cat": "sage"},{"i": 1628,"n": "ר' חנינא בר עיזקא","l": "ח","b": "מובא בב\"ר (ספי\"ג), והוא ר' חנינא בר יקא.","cat": "sage"},{"i": 1629,"n": "ר' חנינא בר פפא","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. מתלמידי ר' יוחנן (ירו', ב\"ק פ\"י ה\"ב). היה תלמידו של ר' שמואל בר נחמני באגדה (ירו', שביעית ספ\"ה). חברם של ר' אבהו, ר' יצחק נפחא (גיטין כ\"ט ע\"ב) ור' אמי (יבמות מ\"ח ע\"ב). רב יוסף ואביי שלחו לשאול אצלו הכרעה, ואביי לא קיבל את הכרעתו (כתובות פ\"א ה\"ב). ר' אלעאי אמר משמו (חגיגה כ\"א ע\"ב). היה חסיד גדול (קידושין ל\"ט ע\"ב). שימש לאמוראים כסמל הצניעות (שם פ\"א ע\"א). מלאך המות אהבו והיה רגיל אצלו (כתובות ע\"ז ע\"ב). וכשנפטר הפסיק עמוד אש בינו לבין העם, דבר המוכיח שהיה מיחידי סגולה בדורו (כתובות ע\"ז ע\"ב).","cat": "sage"},{"i": 1630,"n": "ר' חנינא בר פפי","l": "ח","b": "מובא בבבלי (כתובות פ\"ד ע\"ב), ונראה שזהה לר' חנינא בר פפא.","cat": "sage"},{"i": 1631,"n": "רב חנינא בר רב קטינא","l": "ח","b": "שמו שובש בכמה צורות. מובא בבבלי (גיטין ל\"ח ע\"א). אותו ענין מובא: \"אמר רב הונא בר רב קטינא\" (שם מ\"ג ע\"ב), ושוב אותו ענין מובא:\" רב אחא בר רב קטינה\" (יבמות ס\"ו ע\"א) (ע\"ע).","cat": "sage"},{"i": 1632,"n": "ר' חנינא בר שילא","l": "ח","b": "מובא בבבלי (סנהדרין ע\"ב ע\"ב), ועיין רב חיננא בר שילת.","cat": "sage"},{"i": 1633,"n": "ר' חנינא בר שלדא","l": "ח","b": "מובא באסת\"ר (פ\"ה - ג'), ונראה שהוא ר' חנינא שלקא.","cat": "sage"},{"i": 1634,"n": "רבי חנינא בר שלמיא","l": "ח","b": "מובא בבבלי (חולין ל\"ז ע\"ב), והוא רב חיננא בר שלמיא.","cat": "sage"},{"i": 1635,"n": "ר' חנינא ברוקא","l": "ח","b": "מובא בירושלמי (יבמות פ\"א ה\"ו), והוא ר' חנינא בר יקא.","cat": "sage"},{"i": 1636,"n": "ר' חנינא בריה דר' אבא","l": "ח","b": "מובא בויק\"ר (פכ\"ג - ה').","cat": "sage"},{"i": 1637,"n": "ר' חנינא בריה דר' אבהו","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של ר' אבהו (קידושין ל\"ג ע\"ב). אביו שלחו לטבריה ללמוד תורה (ירו', פסחים פ\"ג ה\"ז). היה דיין בעירו (ירו', יבמות פ\"ב ה\"ד). האומרים בשמו: ר' ברכיה (מדרש תהלים פקי\"ט - י\"ד) ור' חזקיה (בכורים פ\"ג ה\"ה).","cat": "sage"},{"i": 1638,"n": "ר' חנינא בריה דר' אדא","l": "ח","b": "מובא בשהש\"ר (פ\"א - ב').","cat": "sage"},{"i": 1639,"n": "ר' חנינא בריה דר' בחיי","l": "ח","b": "מובא בירושלמי (פסחים פ\"ג), ואפשר שהוא רב חיננא בר חייא.","cat": "sage"},{"i": 1640,"n": "ר' חנינא בריה דר' הלל","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי. פעם הביא מחלוקת של ר' יונה ור' יוסי (ירו', שבת פ\"ג ה\"ה).","cat": "sage"},{"i": 1641,"n": "ר' חנינא בריקא","l": "ח","b": "אמורא בבלי בדור השלישי. בשמו יש כמה וכמה שיבושים. מסר בשם רבי יהודה: \"שורשי חטה בוקעין וכו'\" (ירו', ברכות פ\"ט ה\"ב), ואותו מאמר בשם ר' חנינא בר יסא (ירו', ע\"ז פ\"ג ה\"ה), וכן בשם ר' חנינא בריקא (ירו', תענית פ\"א ה\"ג). וכן מצינו: \"ר' חנינא בן ברוקא בני מישא וכו'\" (ירו', קידושין פ\"ד ה\"א), ואותו מאמר בשם ר' חנינא ברוקא (ירו', יבמות פ\"א ה\"ו). וכן מצינו שיבושים נוספים: ר' חנינא בר עיזקא (ב\"ר ספ\"ג), חנינא בר איקא (ירו', כתובות פ\"ז ה\"ו) והכל אחד הוא.","cat": "sage"},{"i": 1642,"n": "רבי חנינא דברת חוורן","l": "ח","b": "מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא רבי חוניה דברת חוורן.","cat": "sage"},{"i": 1643,"n": "ר' חנינא דציפורין","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי הששי. הרבה למסור בשם ר' פנחס (ירו', מעשרות פ\"ג ה\"א). כן מסר בשם ר' אבהו (ירו', פ\"ז ה\"ב). היה חברו ובר פלוגתיה דר' מנא (ירו', פסחים פ\"ג ה\"א). היה הריש בישיבת ציפורי, וכשנחרבה ישיבת טבריה מקום ר' מנא, מסר לו ר' חנינא את הנהגת הישיבה בציפורי. וזה שמצינו: \"ג' הניחו כתרן בעוה\"ז וירשו חיי העוה\"ב וכו' ר' חנינא דציפורן לר' מנא\" (ירו', פסחים פ\"ו ה\"א). ישב לפני ר' מנא (ירו', מע\"ש פ\"ג ה\"ו).","cat": "sage"},{"i": 1644,"n": "ר' חנינא דקיסרין","l": "ח","b": "והוא ר' חנינא בריה דר' אבהו.","cat": "sage"},{"i": 1645,"n": "ר' חנינא הגדול","l": "ח","b": "והוא ר' חנינא בר חמא.","cat": "sage"},{"i": 1646,"n": "ר' חנינא הזקן","l": "ח","b": "אמורא ארץ ישראלי בדור השני. הקשה לר' חנינא (תנחומא שופטים - ח').","cat": "sage"},{"i": 1647,"n": "ר' חנינא חברון דרבנן","l": "ח","b": "מובא (ירו', ברכות פ\"א ה\"א), והוא רב חנניה (ע\"ע) אחיו של רבה.","cat": "sage"},{"i": 1648,"n": "רב חנינא חוזאה","l": "ח","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של ר' חסדא (מו\"ק כ' ע\"א). בא לשאול מרב נחמן (חולין צ\"ה ע\"ב). ממנו ההלכה: \"חזקה הוא על חבר שאינו מוציא דבר שאינו מתוקן\" (עירובין ל\"ב ע\"א).","cat": "sage"},{"i": 1649,"n": "רבי חנינא טירנאה","l": "ח","b": "מובא בבבלי (כריתות ט' ע\"א), והוא רבי חנינא תורתייא.","cat": "sage"},{"i": 1650,"n": "רבי חנינא טירתא","l": "ח","b": "מובא בבבלי (מנחות מ\"ח ע\"א), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1651,"n": "ר' חנינא כתובה","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר' אחא, שאמר בשם ר' שמעון בן לקיש (ירו', הוריות רפ\"ג).","cat": "sage"},{"i": 1652,"n": "רב חנינא מסורא","l": "ח","b": "מובא בבבלי (ב\"ב קל\"ו ע\"א), והוא ר' חיננא מסורא.","cat": "sage"},{"i": 1653,"n": "רב חנינא מסורא דפרת","l": "ח","b": "אמורא בבלי בדור הששי. חברו של רבינא. כשרבינא בא לסורא דפרת (פרש\"י: ואין זו סורא סתם) שאלו ר' חנינא (ב\"מ ס\"א ע\"ב).","cat": "sage"},{"i": 1654,"n": "רבי חנינא סגן הכהנים","l": "ח","b": "תנא בדור הראשון. היה בזמן הבית ואמר: \"אני ראיתיה [אש של הקדש] ורבוצה ככלב\" (יומא כ\"א ע\"ב). גם אביו שימש במקדש: \"רבי חנינא סגן הכהנים אומר: 'דוחה היה אבא את בעלי מומין מעל גבי המזבח'\" (זבחים פ\"ד ע\"א). ראה את החורבן בעיניו (תענית י\"ג ע\"א). חלק עם ר' דוסא בן הרכינס, ועם עקביא בן מהללאל ועם ר\"ע (נגעים פ\"ה מ\"ד). רבי שמעון בן הסגן הוא בנו (לדעת הרמב\"ם). נהרג כ\"ה סיון (שו\"ע או\"ח סי' תק\"פ). \"יתו\"א\" כתב, שנהרג עם רשב\"ג ועם רבי ישמעאל כהן גדול בזמן שבית המקדש היה קיים.","cat": "sage"},{"i": 1655,"n": "ר' חנינא ספרא","l": "ח","b": "אמורא ארץ ישראלי בדור השני. ר' חנינא בר פפא אמר בשמו (מדרש שמואל פכ\"ה - ב').","cat": "sage"},{"i": 1656,"n": "רבי חנינא ענתונא","l": "ח","b": "מובא בירושלמי (תרומות פ\"ב ה\"א), והוא ר' חנינא ענתונייא.","cat": "sage"},{"i": 1657,"n": "רבי חנינא ענתונייא","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' מנא (ירו', פאה פ\"א ה\"א). מסר בשם ר' שמעון בן לקיש (ירו', ע\"ז פ\"ה הי\"א). שמו השתבש בכמה אופנים: ענתוניא (ירו', תרומות פ\"ב ה\"א), ענתנייה (ירו', ברכות פ\"ו ה\"ה), סנתוניא (ירו', פאה פ\"א ה\"א).","cat": "sage"},{"i": 1658,"n": "ר' חנינא ענתנייה","l": "ח","b": "מובא בירושלמי (ברכות פ\"ו ה\"ה), והוא ר' חנינא ענתונייא.","cat": "sage"},{"i": 1659,"n": "ר' חנינא קרא","l": "ח","b": "אמורא ארץ ישראלי בדור השני. תלמידם של ר' ינאי (ברכות ל' ע\"ב) ושל ר' חנינא (תענית כ\"ז ע\"ב). היה מלמד תינוקות (שם).","cat": "sage"},{"i": 1660,"n": "ר' חנינא שלקא","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (תנחומא תצא - י').","cat": "sage"},{"i": 1661,"n": "רבי חנינא תורתייא","l": "ח","b": "אמורא ארץ ישראלי בדור השני - השלישי. שמו שובש בכמה צורות. היה תלמידו של ר' יוחנן. מסר בשם חזקיה [רבו של ר' יוחנן] (ירו', פאה פ\"ג ה\"ז), בשם ר' ינאי (ירו', תרומות ספ\"ז) ובשם ר' אושעיא (שם פ\"י ה\"ו). ר' יונה מסר בשמו (ירו', פאה שם). נראה, שר' חייא בר אבא היה תלמידו (ירו', ברכות פ\"ג ה\"ה).","cat": "sage"},{"i": 1662,"n": "רבי חנינא תורתייה","l": "ח","b": "מובא בירושלמי (תרומות ספ\"ז), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1663,"n": "רבי חנינא תיתרא","l": "ח","b": "מובא בירושלמי (תרומות פ\"י ה\"ו), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1664,"n": "רבי חנינא תריתאה","l": "ח","b": "מובא בבבלי (נדרים נ\"ז ע\"ב), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1665,"n": "ר' חנינה בן ברוקא","l": "ח","b": "מובא בירושלמי (קדושין פ\"ד ה\"א), והוא ר' חנינא בן בריקא.","cat": "sage"},{"i": 1666,"n": "ר' חנינה תרתיה","l": "ח","b": "מובא בירושלמי (ברכות פ\"ג ה\"ה), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1667,"n": "חנן","l": "ח","b": "ע\"ע חנין.","cat": "sage"},{"i": 1668,"n": "רב חנן (3)","l": "ח","b": "מובא בבבלי (חולין צ\"ה ע\"ב), ולגיר' רבנו גרשום: רב חנן בר רבא, והוא היה חתנו דרב (שם).","cat": "sage"},{"i": 1669,"n": "רבי חנן","l": "ח","b": "תנא בדור החמישי. מסר בשם ר' מאיר. (מגילה י\"ב ע\"א) וקיבל מרבי (סוכה ט\"ו ע\"ב).","cat": "sage"},{"i": 1670,"n": "ר' חנן","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"אר' חנן, אר' יעקב בר אידי, אר' יהושע בן לוי, משום בר קפרא\" (חולין ה' ע\"ב). אולי הוא ר' חנין, שמסר בשם ר' יהושע בן לוי.","cat": "sage"},{"i": 1671,"n": "ר' חנן אבוה דר\"ש","l": "ח","b": "אמורא ארץ ישראלי בדור השני. מסר בשם ר' יהושע בן לוי. שמו המדוייק לא ברור - ר' שמעון או ר' שמואל, שכן בגמ' יש ראשי תיבות ר\"ש.","cat": "sage"},{"i": 1672,"n": "חנן בן אבישלום","l": "ח","b": "מדייני גזירות בירושלים בדור החורבן (כתובות ק\"ה ע\"א). חברו של אדמון, גם מדייני גזירות. על שנים מפסקי דינו חלקו בני כהנים גדולים ור' דוסא בר הרכינס, רבן יוחנן בן זכאי סבר כמוהו ואמר: \"יפה אמר חנן\" (שם ק\"ה ע\"א - ק\"ז ע\"ב).","cat": "sage"},{"i": 1673,"n": "רב חנן בן פזי","l": "ח","b": "מובא במ\"ר (פ\"ג - א'), ונראה שהוא רבי חנינא בן פזי.","cat": "sage"},{"i": 1674,"n": "חנן בן פנחס","l": "ח","b": "מובא בבבלי (קידושין ע\"ב ע\"א). נראה, שאולי חי בבבל בדור החמישי לאמוראים.","cat": "sage"},{"i": 1675,"n": "ר' חנן בר אבא","l": "ח","b": "מובא בבבלי (פסחים ל\"ו ע\"ב). ע\"ע רב חנן בר רבא.","cat": "sage"},{"i": 1676,"n": "רב חנן בר אביי","l": "ח","b": "מובא בבבלי (פסחים ק\"א ע\"א), ואולי צ\"ל: רב חנן בר אמי (כמו ע\"ז ל\"ח ע\"א).","cat": "sage"},{"i": 1677,"n": "רב חנן בר אדא","l": "ח","b": "מובא במדרש שמואל (פי\"ד - ב').","cat": "sage"},{"i": 1678,"n": "חנן בר אימי","l": "ח","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה. מובא בירושלמי (שבת פ\"ו ה\"ה) לפי גיר' \"אור זרוע\" (ח\"ב ספ\"ד), ולפנינו הגיר': אנן בר אימא. ולפי \"יוחסין\" ו\"סה\"ד\" הגיר': און בר אימי.","cat": "sage"},{"i": 1679,"n": "רב חנן בר אמי","l": "ח","b": "אמורא בבלי בדור השני. תלמידם של רב (חולין ט\"ו ע\"א) ושל שמואל (שבת קי\"א ע\"ב). פעמים הגיר': ר' חנין בר אמי, ונראה ששניהם אחד. (ע\"ע ר' חנין בר אשי).","cat": "sage"},{"i": 1680,"n": "ר' חנן בר אשי","l": "ח","b": "נראה שצ\"ל: ר' חנין בר אמי. ע\"ע ר' חנין בר אשי.","cat": "sage"},{"i": 1681,"n": "חנן בר בא","l": "ח","b": "והוא ר' חנן בר אבא. ע\"ע רב חנן בר רבא.","cat": "sage"},{"i": 1682,"n": "ר' חנן בר יוסף","l": "ח","b": "מובא בש\"ר (פמ\"ב - ד').","cat": "sage"},{"i": 1683,"n": "ר' חנן בר מולדה","l": "ח","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (סנהדרין ע' ע\"א).","cat": "sage"},{"i": 1684,"n": "רבי חנן בר פיטום","l": "ח","b": "תנא בדור הרביעי. תלמידו של רבי עקיבא (תענית כ\"ב ע\"ב).","cat": "sage"},{"i": 1685,"n": "רב חנן בר רב חסדא","l": "ח","b": "אמורא בבלי בדור השלישי. בנו ותלמידו של האמורא רב חסדא (חולין ס\"ג ע\"א). קיבל מרב (ע\"ז י\"א ע\"ב).","cat": "sage"},{"i": 1686,"n": "רב חנן בר רב יצחק","l": "ח","b": "מובא בבבלי (פסחים ל' ע\"ב), לפי גיר' הרי\"ף, ולפנינו: רבא בר אבא.","cat": "sage"},{"i": 1687,"n": "רב חנן בר רב קטינא","l": "ח","b": "מובא בבבלי: \"א\"ל רב חנן בר רב קטינא לר\"נ\" (חולין י\"ט ע\"א): ול\"דק\"ס\" הגיר': אמר רב חנא בר רב קטינא לר\"נ.","cat": "sage"},{"i": 1688,"n": "רב חנן בר רבא","l": "ח","b": "אמורא בבלי בדור השני. חתנו ותלמידו של רב (חולין צ\"ה ע\"ב בפי' ר' גרשום). וכן היה תלמידו של שמואל (ירו', ברכות פ\"א ה\"ה). חברו של רב הונא (עירובין ו' ע\"א). רב חסדא היה חתנו ותלמידו (חולין ס\"ג ע\"א ורש\"י שם). שמו של ר' חנן בר רבא השתבש פעמים לר' חנן בר רבה או אבא.","cat": "sage"},{"i": 1689,"n": "ר' חנן בר רבה","l": "ח","b": "מובא בבבלי (סוכה ב' ע\"ב). ע\"ע רב חנן בר רבא.","cat": "sage"},{"i": 1690,"n": "רב חנן בר תחליפא","l": "ח","b": "אמורא בבלי בדור השלישי. שלח לרב יוסף (סנהדרין צ\"ז ע\"ב).","cat": "sage"},{"i": 1691,"n": "ר' חנן בריה דר' ברכיה בוצרייה","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. מסר בשם ר' ירמיה (שהש\"ר פ\"ז - א'). ר' שמואל בר תנחום מסר בשמו (שם).","cat": "sage"},{"i": 1692,"n": "ר' חנן דציפורי","l": "ח","b": "מובא בב\"ר (פ\"י - ד'). סביב שם זה יש כמה גירסאות ב\"סה\"ד\".","cat": "sage"},{"i": 1693,"n": "חנן המצרי א'","l": "ח","b": "היה מדייני גזירות בירושלים בזמן הבית. חי בדור ראשון לתנאים, הוא דורו של ר' יוחנן בן זכאי (כתובות ק\"ה ע\"א).","cat": "sage"},{"i": 1694,"n": "חנן המצרי ב'","l": "ח","b": "תנא בדור השלישי. מחכמי יבנה. חברם של בן עזאי ובן זומא (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1695,"n": "חנן הנחבא","l": "ח","b": "חסיד ומלומד בניסים, שחי בזמן בית שני, בימי ה\"זוגות\". בן בנו של חוני המעגל. כאשר היו זקוקים לגשמים פנו אליו שיתפלל (תענית כ\"ג ע\"ב).","cat": "sage"},{"i": 1696,"n": "חנן חייטא","l": "ח","b": "אמורא בבלי בדור השלישי. כשר' יוסף לא ידע להשיב, אמר עליו: \"יוסף עניא מנא ליה\" (ע\"ז ל\"ט ע\"א).","cat": "sage"},{"i": 1697,"n": "רב חנן מבי כלוחית","l": "ח","b": "אמורא בבלי בדור הרביעי. אין מתורתו בש\"ס. מובא בבבלי בהקשר לבנו ר' פפא, שהיה תלמידו של ר' שימי בר אשי (כתובות מ' ע\"ב).","cat": "sage"},{"i": 1698,"n": "רב חנן מנהרדעא","l": "ח","b": "אמורא בבלי בדור השני. חלק עם רב חסדא ורב המנונא (שבת פ\"ב ע\"א). יתכן שהיה עוד חכם ושמו ר' חנן מנהרדעא, בדור החמישי בבבל, שכן מצינו אותו עם רב כהנא מפום נהרא (קידושין פ\"א ע\"ב), ושמא בקידושין ט\"ס, וצריך לגרוס: רב נחמן מנהרדעא.","cat": "sage"},{"i": 1699,"n": "רב חנן קרטיגנאה","l": "ח","b": "מובא בבבלי (כתובות כ\"ז ע\"ב). ע\"ע רב אחא קרטיגנאה.","cat": "sage"},{"i": 1700,"n": "ר' חננא","l": "ח","b": "ע\"ע ר' חנניה או ר' חנינא או ר' חיננא.","cat": "sage"},{"i": 1701,"n": "רב חננאל","l": "ח","b": "אמורא בבלי בדור השני. תלמידו המובהק של רב. חברו של רב ברונא (פסחים ק\"ג ע\"א). נראה שהיה מחשובי דורו, ופעם כשנשאל רב הונא, הפנה את השואלים לרב חננאל (בכורות כ\"ד ע\"ב). משמו אמרו: רב איקא בר אבין (מגילה ג' ע\"א) ור' זירא (ירו' מגילה פ\"א ה\"ט). אביי היה לו קשר אישי עמו (קידושין ע\"ב ע\"א). התפרנס מהיותו סופר מומחה (מגילה י\"ח ע\"ב). פעם מצאו רב חסדא כותב ספרים שלא מן הכתב \"אמר ליה: 'ראויה כל התורה כולה ליכתב על פיך אלא כך אמרו חכמים אסור לכתוב אות אחת שלא מן הכתב'\" (שם). בנו מובא בירושלמי (מגילה שם).","cat": "sage"},{"i": 1702,"n": "רב חננאל בר פפא","l": "ח","b": "מובא בבבלי (שבת פ\"ח ע\"ב).","cat": "sage"},{"i": 1703,"n": "ר' חננה","l": "ח","b": "עיין ר' חנינא או ר' חנניה או ר' חיננא.","cat": "sage"},{"i": 1704,"n": "ר' חנניא בן בינאי","l": "ח","b": "מובא בתוספתא (נגעים פ\"א). \"סה\"ד\" כתב: \"נ\"ל ט\"ס וצ\"ל חכנאי\" (כלומר ר' חנניה בן חכנאי).","cat": "sage"},{"i": 1705,"n": "רבי חנניא בן יהודה","l": "ח","b": "תנא בדור השלישי - הרביעי. התוכח עם רבי עקיבא (ספרא צו פרשה ב'). רבי יהודה מסר דרשתו: \"קשה הקפדה, שגרמה לו למשה לטעות\" (ספרא שמיני ספ\"א).","cat": "sage"},{"i": 1706,"n": "רב חנניא חבריהון דרבנן","l": "ח","b": "מובא בירושלמי (תרומות פ\"ה ה\"ג).","cat": "sage"},{"i": 1707,"n": "רב חנניא טריטאה","l": "ח","b": "מובא בבבלי (תמורה כ\"ט ע\"א), והוא רבי חנינא תורתייא.","cat": "sage"},{"i": 1708,"n": "רב חנניה","l": "ח","b": "אמורא בבלי בדור השלישי, שעלה לארץ ישראל. הוא ואחיו רב אושעיא (לא רבי אושעיא מסדר הברייתות) היו אחיו של רבה (סנהדרין י\"ד ע\"א מהרש\"א). ושלחו מא\"י לבבל לרבה שיבוא לארץ ישראל, ללמוד לפני רבי יוחנן (כתובות קי\"א ע\"א). עליית אחיו רב אושעיא לא\"י מובאת בבבלי (חולין קכ\"ד ע\"א). קיבל מרבי יוחנן (סנהדרין י\"ד ע\"א). ר' יוחנן הצטער שרצה להסמיכו ולא עלה בידו (סנהדרין שם), ונראה שמשום כך נקרא: \"ר' חנניה חברון דרבנן\" (ירו', מעשרות פ\"ה ה\"ב), יען כי לא נסמך על ידי ר' יוחנן. קיבל גם מר' אלעזר (בכורות ה' ע\"ב). ר' יונה שאל ממנו (ירו', מו\"ק פ\"ג ה\"ה). ר' ירמיה אמר בשמו (ירו', עירובין פ\"ג ה\"ה). הוא ואחיו ר' אושעיא עסקו בספר יצירה, ובראו עגלא תילתא כל ערב שבת (סנהדרין ס\"ה ע\"ב).","cat": "sage"},{"i": 1709,"n": "ר' חנניה (2)","l": "ח","b": "מובא בירושלמי (ערלה פ\"א ה\"ה), והוא ר' חנינא ציפורין.","cat": "sage"},{"i": 1710,"n": "ר' חנניה אחי ר' אחא בר' חנינא","l": "ח","b": "מובא במ\"ר (פי\"ז - ב'), ונראה שיש כאן ט\"ס.","cat": "sage"},{"i": 1711,"n": "ר' חנניה איש כפר טבעון","l": "ח","b": "לפי גיר' \"ילקוט\" (בספרי האזינו פ' אם לא). וגיר' שלפנינו ר' יהודה איש טבעים.","cat": "sage"},{"i": 1712,"n": "ר' חנניה בן אחוי דרב הושעיא","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי (ירו', תענית פ\"א ה\"ב).","cat": "sage"},{"i": 1713,"n": "חנניה בן אחי יאשיה","l": "ח","b": "מובא בבבלי (כתובות ע\"ט ע\"ב). יש חנניה בן אחי יהושע שהיה תנא, ויש רבי חנניה בן אחוי דר' הושעיא שהיה אמורא.","cat": "sage"},{"i": 1714,"n": "חנניה בן אחי רבי יהושע","l": "ח","b": "תנא בדור השלישי, והוא סתם חנניה בברייתא (יוחסין). ירד לבבל (ספרי דברים פיסקא ב') וחזר לא\"י (סוכה כ' ע\"ב), ואח\"כ שוב ירד לבבל, השתקע שם (ברכות ס\"ג ע\"א) ויסד ישיבה גדולה בפומבדיתא (סנהדרין ל\"ב ע\"ב): \"צדק צדק תרדוף וכו' הלך אחר ר' חנניה בן אחי ר' יהושע לגולה\" (שם, רש\"י). היה תלמידו של דודו ר' יהושע (נדה כ\"ד ע\"ב) ומגדולי הדור (ברכות שם). עיבר שנים בבבל ושלחו לו שלוחים מא\"י שיפסיק מלעבר שנים אחרת יהיה בנידוי, ואחרי שהתיעץ עם רבי יהודה בן בתירא, נשמע לשליחים ופסק מלעבר שנים (שם). נפטר בבבל (קה\"ר פ\"א - ח').","cat": "sage"},{"i": 1715,"n": "חנניה בן חזקיה בן גורן","l": "ח","b": "מראשוני התנאים בדור הראשון. אלמלא הוא, היו גונזים את ספר יחזקאל שהיו סותרין דברי תורה: \"מה עשה? העלו לו ג' מאות גרבי שמן וישב בעליה ודרשן\" (שבת י\"ג ע\"ב). ביתו היה מפגש לחכמים: \"ואלו מן ההלכות שאמרו בעליית חנניה בן חזקיה בן גרון\" (שם). פעם נמנו ורבו ב\"ש על בית הלל וגזרו בעלית חנניה בן חזקיה י\"ח דברים (שם).","cat": "sage"},{"i": 1716,"n": "חנניה בן חכינאי","l": "ח","b": "תנא בדור השלישי. היה בישיבת יבנה מה\"דנין לפני חכמים\", יחד עם שמעון בן עזאי, שמעון בן זומא וחנן המצרי (סנהדרין י\"ז ע\"ב). תלמידו של רבי עקיבא (חגיגה י\"ד ע\"ב). ישב שתים עשרה שנה בבית המדרש ולמד, וכשחזר פתאום, ואשתו ראתה אותו, יצאה נפשה מרוב בהלה וביקש רחמים ונפשה שבה אליה (כתובות ס\"ב ע\"ב), והפכה למופת כאשת חיל (ב\"ר פי\"ז - ג').","cat": "sage"},{"i": 1717,"n": "חנניה בן חכנאי","l": "ח","b": "לדעתו של בעל \"יתו\"א\" היו שני חנניה בן חכנאי שהקדמון בזמנו של רבי יוחנן בן זכאי, והשני שני דורות לאחריו.","cat": "sage"},{"i": 1718,"n": "ר' חנניה בן חלניפי","l": "ח","b": "מובא במכילתא (בשלח פ\"ג). ונראה שצ\"ל: חכינאי.","cat": "sage"},{"i": 1719,"n": "חנניה בן חנילא","l": "ח","b": "מובא בירושלמי (שקלים פ\"ה ה\"א), וצ\"ל: חנניה בן חכינאי.","cat": "sage"},{"i": 1720,"n": "ר' חנניה בן יעקב","l": "ח","b": "מובא באבות דר\"נ (פכ\"ט מ\"ג).","cat": "sage"},{"i": 1721,"n": "ר' חנניה בן עדו","l": "ח","b": "מובא בתוספתא (סוף עדיות), ויש גירסאות: ר' חנניא בר עדיי.","cat": "sage"},{"i": 1722,"n": "רבי חנניה בן עקביא","l": "ח","b": "מובא בבבלי (מו\"ק כ\"א ע\"ב), והוא ר' חנינא בן עקביא.","cat": "sage"},{"i": 1723,"n": "רבי חנניה בן עקשיא","l": "ח","b": "תנא שאין לקבוע זמנו המדוייק. מפורסם מאמרו שנוהגים לסיים בו קריאת כל פרק מפרקי אבות: \"רצה הקב\"ה לזכות את ישראל, לפיכך הרבה להם תורה ומצוות, שנאמר: 'ה' חפץ למען צדקו יגדיל תורה ויאדיר'\" (מכות כ\"ג ע\"ב).","cat": "sage"},{"i": 1724,"n": "רבי חנניה בן פזי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מגילה פ\"ד ה\"ג), יחד עם רבי חלבו. \"סה\"ד\" סבור, שרבי חנינא בן פזי ורבי איניא בן פזי אחד הם.","cat": "sage"},{"i": 1725,"n": "רבי חנניה בן שמואל","l": "ח","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (ירו', דמאי פ\"ב ה\"א).","cat": "sage"},{"i": 1726,"n": "ר' חנניה בר אידי","l": "ח","b": "אמורא בבלי בדור החמישי. מובא בבבלי: \"שלח להו רב שמואל בר אידי: 'חנניא אחי אומר'\" (פסחים ק\"ד ע\"א).","cat": "sage"},{"i": 1727,"n": "רב חנניה בר ביבי","l": "ח","b": "אמורא בבלי בדור הששי. מובא בבבלי: \"אמר רב אשי חזינא לרב חנניה בר ביבי וכו'\" (פסחים ק\"י ע\"א). \"יוחסין\" סובר שהיה בן בנו של אביי.","cat": "sage"},{"i": 1728,"n": "רבי חנניה בר מניומי","l": "ח","b": "מובא בבבלי (יומא מ\"ה ע\"ב). זהה לר' חנינא בר מניומי.","cat": "sage"},{"i": 1729,"n": "רבי חנניה בר עכברי","l": "ח","b": "אמורא ארץ ישראלי בדור הרביעי. מצינו אותו אצל ר' חייא ציפוראי (ירו', סוף תרומות).","cat": "sage"},{"i": 1730,"n": "רב חנניה בר שילא","l": "ח","b": "מובא בבבלי (עירובין י\"ב ע\"א), וע\"ע רב חיננא בר שילת.","cat": "sage"},{"i": 1731,"n": "רב חנניה בר שלמיא","l": "ח","b": "מובא בבכורות (כ\"ד ע\"ב), והוא רב חיננא בר שלמיא.","cat": "sage"},{"i": 1732,"n": "ר' חנניה בריה דרבי הלל","l": "ח","b": "מובא בירושלמי (יומא פ\"ח ה\"ז), והוא ר' חנינא בריה דר' הלל.","cat": "sage"},{"i": 1733,"n": "ר' חנניה בריה דר' איבי","l": "ח","b": "מובא בשהש\"ר (פ\"ז - ב').","cat": "sage"},{"i": 1734,"n": "ר' חנניה בר' יהושע","l": "ח","b": "מובא במ\"ר (פ\"י - ד'), ואולי צ\"ל: ר' חנניה בן אחי ר' יהושע.","cat": "sage"},{"i": 1735,"n": "ר' חנניה ב'","l": "ח","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (כריתות ז' ע\"א).","cat": "sage"},{"i": 1736,"n": "ר' חנניה חברון דרבנן","l": "ח","b": "מובא בירושלמי (מעשרות פ\"ה ה\"ב).","cat": "sage"},{"i": 1737,"n": "רבי חנניה סגן הכהנים","l": "ח","b": "מובא בבבלי (יומא כ\"א ע\"ב), והוא ר' חנינא סגן הכהנים.","cat": "sage"},{"i": 1738,"n": "רב חנניה סנתוניא","l": "ח","b": "מובא בירושלמי (פאה פ\"א ה\"א), והוא ר' חנינא ענתונייא.","cat": "sage"},{"i": 1739,"n": "רבי חנניה תרתייה","l": "ח","b": "מובא בירושלמי (קידושין פ\"א ה\"ה), והוא ר' חנינא תורתייא.","cat": "sage"},{"i": 1740,"n": "חסא","l": "ח","b": "גברא רבה בדור השלישי בבבל. טבע, ויש אומרים שר' נחמן הורה לאשתו שמותר לה להנשא (יבמות קכ\"א ע\"ב). והמובא בבבלי: \"שכיב חסא\" (כתובות פ\"ה ע\"ב), ופרש\"י: \"שהוא חסא המובא ביבמות, שטבע בנהר\", ותוספות כתבו: \"משמע דרב נחמן לא פליג ארב חסא רבו\" (ב\"מ נ\"ז ע\"א ד\"ה: אמר), והשיג \"סה\"ד\" וכתב: \"לא ידעתי מנ\"ל דחסא רבו\".","cat": "sage"},{"i": 1741,"n": "ר' חסא","l": "ח","b": "מובא ברו\"ר (פ\"ה - ד').","cat": "sage"},{"i": 1742,"n": "רב חסדא","l": "ח","b": "אמורא בבלי מפורסם בדור השני - השלישי. עמד בראש ישיבת סורא משנת ד' נ\"ח - ס\"ח (892 - 803) (\"אגרת רב שרירא גאון\"). תלמידו של רב (ביצה כ\"ה ע\"א רש\"י ד\"ה: מדברי). תלמיד חבר לרב הונא (יבמות פ\"ג ע\"ב תד\"ה: אמרי). בגלל חילופי דברים חריפים עם רב הונא צם 04 תעניות (ב\"מ ל\"ג ע\"א). שניהם, ר\"ה ור' חסדא מכונים \"סבי דסורא\" (סנהדרין י\"ז ע\"ב) ו\"חסידי בבל\" (תענית כ\"ג ע\"ב). קיבל גם מר' ירמיה בר אבא (ברכות נ\"ה ע\"ב) ומחותנו רב חנן בר רבא (חולין ס\"ג ע\"א). חבריו היו רב נחמן ורב ששת (עירובין ס\"ז ע\"א) ורב ששת היה \"מרתע\" כל גופו מפלפולו של רב חסדא (שם). בין תלמידיו החשובים היו: רבא (קידושין נ\"ג ע\"ב) ורמי בר חמא (עירובין ח' ע\"ב), ושניהם היו חתניו (יבמות ל\"ד ע\"ב, רש\"י ותוס' שם). בימי נעוריו היה עני (שבת ק\"מ ע\"ב). התעשר מעשיית שכר (פסחים קי\"ג ע\"א). בגיל 61 התחתן (קידושין כ\"ט ע\"ב) עם בת בתו של רב (ע\"ז י\"א ע\"ב). היתה לו משפחה ענפה (מו\"ק כ\"ח ע\"א). חי 29 שנה (שם). בעת פטירתו לא יכול מלאך המות לקרב אליו, אלא לאחר שהבהילו (שם). לאחר פטירתו לא נתמנה ריש מתיבתא בסורא, עד שמלך שם רב אשי (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 1743,"n": "רב חסדא בן עוירא","l": "ח","b": "מובא ב\"ילקוט\" (שמואל רמז קי\"ח), ויתכן שיש ט\"ס בשם.","cat": "sage"},{"i": 1744,"n": "רב חסדא בר אבדימי","l": "ח","b": "מובא בבבלי (ברכות נ\"ג ע\"ב).","cat": "sage"},{"i": 1745,"n": "רב חסדאי","l": "ח","b": "כך נקרא לפעמים ר' חסדא בירושלמי.","cat": "sage"},{"i": 1746,"n": "רב חסדי","l": "ח","b": "מובא בירושלמי (מגילה פ\"א ה\"ו), והוא רב חסדא.","cat": "sage"},{"i": 1747,"n": "חסיד","l": "ח","b": "כל מקום שמובא \"מעשה בחסיד אחד\" הוא רבי יהודה בן בבא או רבי יהודה בר' אילעאי (ב\"ק ק\"ג ע\"ב).","cat": "sage"},{"i": 1748,"n": "ר' חסידא","l": "ח","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של ר' חזקיה (ירו', סוף מע\"ש) ושל ר' יוסי (ירו', נדרים פ\"ה ה\"ה).","cat": "sage"},{"i": 1749,"n": "חסידי דבבל","l": "ח","b": "כך כונו רב הונא, ורב חסדא (תענית כ\"ג ע\"א), ורב נחמן (גיר' רש\"י: רב נחמן בר יצחק), (מגילה כ\"ח ע\"ב), ור' זירא (חולין קכ\"ב ע\"א).","cat": "sage"},{"i": 1750,"n": "חסידים הראשונים","l": "ח","b": "מובאים ללא שם, כגון בבבלי (נדרים י' ע\"א), ואין לדעת מי הם.","cat": "sage"},{"i": 1751,"n": "ר' חפני בר יצחק","l": "ח","b": "מובא בב\"ר (פנ\"ו - ה').","cat": "sage"},{"i": 1752,"n": "ר' חצנא","l": "ח","b": "מובא בירושלמי (ברכות פ\"א ה\"א).","cat": "sage"},{"i": 1753,"n": "חריפי דפומבדיתא","l": "ח","b": "מובאים בבבלי: \"חריפי דפומבדיתא עיפה ואבימי\" (סנהדרין י\"ז ע\"ב).","cat": "sage"},{"i": 1754,"n": "רב טבות","l": "ט","b": "אמורא בבלי בדור החמישי. מובא בבבלי (ב\"מ מ\"ט ע\"א).","cat": "sage"},{"i": 1755,"n": "טבות רישבא","l": "ט","b": "מובא בבבלי (שבת קמ\"ו ע\"ב), והוא טבי רישבא.","cat": "sage"},{"i": 1756,"n": "טבי","l": "ט","b": "עבדו של רבן גמליאל דיבנה, שאמר עליו שהוא \"תלמיד חכם\" (סוכה כ' ע\"ב) והיה ראוי לסמיכה: \"הרבה בנים היו לו לכנען שראויין ליסמך כטבי, עבדו של רבן גמליאל\" (יומא פ\"ז ע\"א). כשמת קיבל רבן גמליאל תנחומין עליו (ברכות ט\"ז ע\"ב).","cat": "sage"},{"i": 1757,"n": "ר' טבי","l": "ט","b": "אמורא בדור השלישי שאין לקבוע מקומו. מסר בשם חכמי בבל: רב (ירו', תרומות פ\"ח ה\"ג), ר' ששת (תמורה ל\"ד ע\"א) ור' חסדא (ירו', שבת פ\"ג ה\"ז), וכן בשם חכמי א\"י: ר' יאשיה (ירו', שקלים פ\"א ה\"א). בשמו מסרו ר' חזקיה (ירו', תרומות שם) ור' יוסי (ירו', סוכה פ\"ג ה\"א).","cat": "sage"},{"i": 1758,"n": "רב טבי בר קיסנא","l": "ט","b": "מובא בבבלי (עירובין ק\"ד ע\"ב), וצ\"ל: טובי בר קיסמא, וכן גיר' התוס' (סוטה כ' ע\"ב ד\"ה: לא).","cat": "sage"},{"i": 1759,"n": "טבי בריה דמרי טבי","l": "ט","b": "אמורא בבלי בדור השני - השלישי. מובא בבבלי: \"אמר טבי בריה דמרי טבי, אמר מר עוקבא, אמר שמואל\" (ר\"ה כ\"ב ע\"א).","cat": "sage"},{"i": 1760,"n": "טבי רישבא","l": "ט","b": "אמורא בבלי בדור השני. תלמידו של שמואל (שבת י\"ז ע\"ב). היה צד חיות ועופות (שם ברש\"י).","cat": "sage"},{"i": 1761,"n": "טביומי","l": "ט","b": "הוא מר בר רב אשי (ב\"ב י\"ב ע\"ב).","cat": "sage"},{"i": 1762,"n": "רב טביומי","l": "ט","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ק מ\"א ע\"ב) ושל אביי (ב\"מ נ\"ד ע\"ב). נראה, שעבר לארץ ישראל, שכן מצינו ששאל לר' חזקיה (ירו', ברכות פ\"א ה\"ב). מסר בשם ר' ירמיה (ויק\"ר פל\"ג - ב').","cat": "sage"},{"i": 1763,"n": "רב טביומי בר קיסנא","l": "ט","b": "מובא בבבלי (מנחות ע' ע\"א), והגיר' במקום אחר: \"רב טובי בר קיסנא\" (כתובות ס\"ד ע\"א), ונראה שאחד הוא, וכן גרס \"דק\"ס\".","cat": "sage"},{"i": 1764,"n": "רב טבית","l": "ט","b": "מובא בבבלי (חולין מ\"ט ע\"ב). ונראה שצ\"ל: רב טבות.","cat": "sage"},{"i": 1765,"n": "רבי טבלא","l": "ט","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (שבת ק\"א ע\"א). היה כפוף לר\"נ (ב\"ב קי\"א ע\"א: חולין קל\"ב ע\"ב). היה דיין (שם). היה גם תלמידו של רב ברונא [תלמיד רב] (סנהדרין כ\"ח ע\"ב). אולי היה בא\"י ונסמך, ולכן נקרא בירושלמי כמעט תמיד רבי טבלא (שבת פ\"ו ה\"ב). ר' יוסף אמר: \"היינו דשמענא לר' טבלא וכו' ולא ידענא מאי קאמר\" (עירובין ע\"ה ע\"א).","cat": "sage"},{"i": 1766,"n": "ר' טבלאי","l": "ט","b": "מובא בירושלמי (עירובין פ\"ח ה\"ו), והוא ר' טבלא.","cat": "sage"},{"i": 1767,"n": "ר' טבלי","l": "ט","b": "הוא רבי טבלא.","cat": "sage"},{"i": 1768,"n": "רבי טבליי","l": "ט","b": "מובא בירושלמי (שבת פ\"ו ה\"ב), והוא ר' טבלא.","cat": "sage"},{"i": 1769,"n": "רבי טובי","l": "ט","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר' אבהו (ירו', נדה פ\"א ה\"א).","cat": "sage"},{"i": 1770,"n": "ר' טובי בר יצחק","l": "ט","b": "מובא בב\"ר (פמ\"א - ד').","cat": "sage"},{"i": 1771,"n": "ר' טובי בר קיסמא","l": "ט","b": "כן גיר' תוס' (סוטה כ' ע\"ב ד\"ה: הא), ולפנינו טבי בר קיסנא.","cat": "sage"},{"i": 1772,"n": "רב טובי בר קיסנא","l": "ט","b": "אמורא בבלי בדור השני. תלמידו של שמואל (כתובות ס\"ד ע\"א).","cat": "sage"},{"i": 1773,"n": "רב טובי בר קסנא","l": "ט","b": "מובא בבבלי (מנחות ע\"ו ע\"א), וצ\"ל: רב טובי בר קיסנא.","cat": "sage"},{"i": 1774,"n": "רב טובי בר רב מתנה","l": "ט","b": "אמורא בבלי בדור השלישי. ר' יוסף מסתמך על מאמרו (ב\"ב כ\"ג ע\"א) מאידך, שלח ר' טובי בר מתנה לקמיה דר' יוסף (חולין ל\"ט ע\"ב). האריך ימים אחר ר' יוסף, וכאשר שוחט העז פנים כנגדו, נידוהו אביי ורבא (מו\"ק ט\"ז ע\"א). נפטר לפני אביי, ונקבר בפומבדיתא (ב\"ב נ\"ח ע\"א).","cat": "sage"},{"i": 1775,"n": "רב טובי בר רב קטינא","l": "ט","b": "מובא בבבלי (נדה ו' ע\"ב), ונראה שצ\"ל: רב טובי בר קיסנא (כמו נדרים י\"ב ע\"ב).","cat": "sage"},{"i": 1776,"n": "רב טובי בר רב קיסנא","l": "ט","b": "אמורא בבלי בדור החמישי. הקשה לרבא (קידושין ל\"ט ע\"ב).","cat": "sage"},{"i": 1777,"n": "רב טובי בריה דרב נחמיה","l": "ט","b": "אמורא בבלי בדור השלישי - הרביעי. בא לשאול דין אצל ר' יוסף (ביצה י\"ב ע\"ב).","cat": "sage"},{"i": 1778,"n": "ר' טוביה","l": "ט","b": "מובא בקה\"ר (פ\"א - י\"ג).","cat": "sage"},{"i": 1779,"n": "טוביה הרופא","l": "ט","b": "מובא בירושלמי: \"מעשה בטוביה הרופא שראה את החודש\" (ר\"ה פ\"א מ\"ו) שם מוכח, שהיה בזמן הבית ואין ראיה שנמנה עם החכמים.","cat": "sage"},{"i": 1780,"n": "ר' טיופה סמוקא","l": "ט","b": "אמורא ארץ ישראלי בדור החמישי. מצינו ש\"בעי קמי רבי יוסי\" (ירו', יבמות רפ\"ח). מסר בשם ר' אבהו (ירו', דמאי פ\"ג רה\"ד).","cat": "sage"},{"i": 1781,"n": "ר' טייפה סמוקה","l": "ט","b": "מובא בירושלמי (ירו', דמאי פ\"ג ה\"ד), והוא ר' טיופה סמוקא.","cat": "sage"},{"i": 1782,"n": "טרטירוי","l": "ט","b": "חי בזמן הבית. שם מקום מגוריו היה מחלול, והיה עולה לעשות שבת בבית המקדש (ירו', מע\"ש פ\"ה ה\"ב). ואין ראיה כלל שנמנה עם החכמים.","cat": "sage"},{"i": 1783,"n": "ר' טרייא","l": "ט","b": "מובא בשהש\"ר (פ\"א).","cat": "sage"},{"i": 1784,"n": "רבי טרפון (2)","l": "ט","b": "תנא בדור השני - השלישי. ראה את הבית בבניינו וזכה לשמוע את קולו של הכהן הגדול (קידושין ע\"א ע\"א). נראה, שקיבל מרבן יוחנן בן זכאי (תוספתא חגיגה ספ\"ג). מתלמידי בית שמאי (יבמות ט\"ו ע\"א רש\"י). מזקני דורו וקראו לו \"אביהן של כל ישראל\" (ירו', יומא פ\"א ה\"א). מראשי המדברים ביבנה: \"וזו שאלה נשאלה לפני חכמים בכרם יבנה וכו', נענה ר\"ט וכו'\" (זבחים נ\"ז ע\"א). מקומו הקבוע היה לוד (חגיגה י\"ח ע\"א). חברם של ר' יהושע ורבי אלעזר בן עזריה (ידים פ\"ד מ\"ג). הגמרא מפקפקת אם היה רבו או חברו של ר\"ע (כתובות פ\"ד ע\"ב). ר\"ט אמר לר\"ע: \"כל הפורש ממך, כפורש מחייו\" (תוספתא מקואות ספ\"א). בין תלמידיו היו אלעזר בן מתיא, חנינא בן חכינאי, שמעון בן עזאי ושמעון התימני (תוספתא ברכות פ\"ד), וכן ר' יהודה (תלמידו של ר\"ע) למד אצלו בילדותו (מגילה כ' ע\"א). היה עשיר גדול (מסכת כלה רבתי פ\"ב). קיים בהקפדה מלאה מצות כיבוד אם (קידושין ל\"א ע\"ב). נהג לומר \"אקפח את בני\" (פרש\"י שבת י\"ז ע\"א: \"מצטער היה על תורה המשתכחת ומקלל את עצמו\"), ובאמת קיפח את בניו ולא נשאר לו בן, רק בן בתו (ב\"מ פ\"ה ע\"א) נפטר אחרי רבי אליעזר (גיטין פ\"ג ע\"א).","cat": "sage"},{"i": 1785,"n": "רב יאשיה","l": "י","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב כ\"ב ע\"א). חברו של ר' עובדיה (שם). לשניהם התיר רבא וכו' לפנים משורת הדין (שם).","cat": "sage"},{"i": 1786,"n": "רבי יאשיה","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של רבי אלעזר (סוטה י\"ט ע\"א). ר' חייא בר אבא, רבי אמי ורבי אסי היו חבריו (ירו', תענית פ\"ב ה\"א). ר' זירא פנה אליו בשאלה (ירו', שבת פי\"ח רה\"א). ר' טובי הרבה למסור בשמו (ברכות ט\"ו ע\"ב ועוד). בימי ר' ירמיה היה גדול הדור ור' ירמיה כינהו \"אריות\", בעוד שעל עצמו אמר \"שועלים\" (ירו', שבועות פ\"ט ה\"ד). בשעת פטירתו ביקש ר' יאשיה שילבישוהו בגדים לבנים (ירו', כלאים פ\"ט ה\"ג).","cat": "sage"},{"i": 1787,"n": "ר' יאשיה","l": "י","b": "תנא בבלי בדור הרביעי. מכונה ר' יאשיה רבה (סנהדרין י\"ט ע\"א). היה הריש בהוצל והרביץ שם תורה (סנהדרין י\"ט ע\"א: גיטין ס\"א ע\"א). עלה לארץ ישראל והיה תלמידו המובהק של ר' ישמעאל (מנחות נ\"ז ע\"ב). למד גם לפני ר' יהודה בן בתירא בנציבין (ירו', סנהדרין פ\"ח ה\"ו). היה חברו של ר' יונתן (מנחות נ\"ז ע\"ב) ושל ר' מתיא בן חרש (אבות דר' נתן רפ\"א). נפטר לפני רבי (קידושין ע\"ב ע\"א). אחריו היה בנו, ר' אחי, הריש בהוצל (שם).","cat": "sage"},{"i": 1788,"n": "ר' יאשיה בי רבי ינאי","l": "י","b": "מובא בירושלמי (תרומות פ\"ב ה\"א), ואולי צ\"ל: בשם ר' ינאי.","cat": "sage"},{"i": 1789,"n": "ר' יאשיה בן לוי","l": "י","b": "מובא בב\"ר (פצ\"ב - ג'), ונראה שצ\"ל: ר' יהושע בן לוי.","cat": "sage"},{"i": 1790,"n": "ר' יאשיה דמן אושה","l": "י","b": "אמורא ארץ ישראלי בדור השני. בן העיר אושה. מסר בשם שמואל (מנחות ל\"ט ע\"א לפי ס\"א). היה רבו של רבה בר בר חנא (שם).","cat": "sage"},{"i": 1791,"n": "רבי יאשיה רבה","l": "י","b": "מובא בבבלי (סנהדרין י\"ט ע\"א), והוא רבי יאשיה התנא.","cat": "sage"},{"i": 1792,"n": "ידוע הבבלי","l": "י","b": "תנא בדור החמישי. תלמידו של ר\"מ. מובא במשנה בש\"ס בבלי: \"ידוע הבבלי אומר, משום ר\"מ\" (ב\"מ צ\"ג ע\"ב).","cat": "sage"},{"i": 1793,"n": "רב יהודה","l": "י","b": "הוא רב יהודה בר יחזקאל.","cat": "sage"},{"i": 1794,"n": "רבי יהודה","l": "י","b": "הוא התנא רבי יהודה בר אלעאי.","cat": "sage"},{"i": 1795,"n": "רב יהודה אחוה דרב כהנא","l": "י","b": "מובא בבבלי: \"יתיב ר' כהנא אחוה דרב יהודה וכו'\" (חולין קי\"א ע\"ב) וגיר' הרא\"ש: \"יתיב ר' כהנא אחוריה דר' יהודה\".","cat": "sage"},{"i": 1796,"n": "רב יהודה אחוה דרב סלא חסידא","l": "י","b": "אמורא בבלי בדור השלישי - הרביעי. שאל מאביי (שבת קי\"ב ע\"א). נראה שהאריך ימים, כי דיבר עם ר\"ה (ברכות ה' ע\"ב). היה חסיד גדול ואליהו הנביא היה רגיל אצלו (ברכות כ\"ט ע\"ב), וסיפר לו בעוון מה מתעכבת הגאולה (יומא י\"ט ע\"ב).","cat": "sage"},{"i": 1797,"n": "יהודה איש הוצא","l": "י","b": "מובא בירושלמי (נדרים פי\"א ה\"א), וצ\"ל: יוסי איש הוצל, והוא איסי בן עקביה.","cat": "sage"},{"i": 1798,"n": "יהודה איש הוצי","l": "י","b": "מובא בירושלמי (שביעית פ\"ח ה\"ה), והוא איסי בן עקביה.","cat": "sage"},{"i": 1799,"n": "ר' יהודה איש טיבעים","l": "י","b": "מובא בספרי (האזינו פסוק איכה ירדוף), וגיר' ה\"ילקוט\" שונה.","cat": "sage"},{"i": 1800,"n": "ר' יהודה איש כפר גבור חיל","l": "י","b": "מובא בבבלי (מגילה י\"ח ע\"א).","cat": "sage"},{"i": 1801,"n": "ר' יהודה איש כפר גבוריא","l": "י","b": "מובא בבבלי (מגילה י\"ח ע\"א).","cat": "sage"},{"i": 1802,"n": "רבי יהודה איש כפר נביריא","l": "י","b": "מובא בבבלי (כתובות ס\"ה ע\"א), וגיר' \"מסה\"ש\": \"גבוריא\".","cat": "sage"},{"i": 1803,"n": "ר' יהודה איש כפר נפור חיל","l": "י","b": "מובא בבבלי (כתובות ס\"ה ע\"א). וגיר' \"מסה\"ש\": \"איש כפר גבור חיל\".","cat": "sage"},{"i": 1804,"n": "יהודה איש כפר עכו","l": "י","b": "מובא במכילתא (יתרו פ' ויאמר משה לחותנו). ונראה שהוא ר' יהודה בן אגרא איש כפר עכו.","cat": "sage"},{"i": 1805,"n": "ר' יהודה בן אגרא","l": "י","b": "תנא בדור הרביעי - החמישי. מסר בשם רבי מאיר (חולין קל\"ד ע\"א), ובשם רבי יוסי (נדה נ\"ב ע\"ב).","cat": "sage"},{"i": 1806,"n": "רבי יהודה בן אגרא איש כפר עכו","l": "י","b": "תנא בדור הרביעי - החמישי. שאל מרבן גמליאל דיבנה (מכילתא יתרו מסכתא דעמלק פ\"ב). מסר בשם ר' מאיר (חולין קל\"ד ע\"א), ובשם ר' יוסי (נדה נ\"ב ע\"ב). רבן שמעון בן גמליאל (אבי רבי) מסר הלכה בשמו (תוספתא כלאים פ\"א י\"ב). ר' שמעון בן יהודה איש כפר עכו (סוטה ל\"ז ע\"ב) הוא אולי בנו.","cat": "sage"},{"i": 1807,"n": "רבי יהודה בן אחותו של רבי יוסי בר חנינא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם דודו ר' יוסי בר חנינא (ירו', תרומות פי\"א סה\"ד). רבין, באגרתו לבבל, מסתמך על דבריו (כתובות מ\"ט ע\"ב).","cat": "sage"},{"i": 1808,"n": "רבי יהודה בן בתירא א'","l": "י","b": "תנא בדור הראשון. מושבו בנציבין שבבבל ושם היתה לו ישיבה (סנהדרין ל\"ב ע\"ב). ראה את בית המקדש בבניינו. כאשר ארמי התפאר שאכל בירושלים מקרבן הפסח, הערים עליו ולכדו והרגוהו ושלחו לו: \"אתה בנציבין ומצודתך פרוסה בירושלים\" (פסחים ג' ע\"ב).","cat": "sage"},{"i": 1809,"n": "רבי יהודה בן בתירא ב'","l": "י","b": "תנא בבלי בדור השלישי. נולד ברומי (ירו', סנהדרין פ\"ז הי\"ג). חי בארץ ישראל. חברו של ר\"ע ובר פלוגתיה (שבת צ\"ו ע\"ב). מפאת רדיפות המלכות, עזב את א\"י והלך לבבל. בהגיעו לגבול יחד עם חבריו ר' מתיא בן חרש (שפנה לרומי ויסד שם ישיבה) ור' חנינה בן אחי ר' יהושע (שיצא לנהר פקוד שבבבל ויסד ישיבה), זכרו את א\"י וזלגו עיניהם דמעות וקרעו בגדיהם (ספרי דברים פיסקא פ'). \"צדק צדק תרדוף... אחרי ר' יהודה בן בתירא לנציבין\" (סנהדרין ל\"ב ע\"ב). ר\"א בן שמוע ור' יוחנן הסנדלר הלכו לנציבין ללמוד אצלו תורה, וכשהגיעו לצידון החליטו לשוב מפאת חשיבות ישיבת א\"י (ספרי שם). מתלמידיו: ר' יאשיא (ירו', סנהדרין פ\"ח ה\"ו). ר' חנינא בן אחי ר' יהושע התיעץ עמו כשאסרו עליו לעבר שנים בחו\"ל ושמע לעצתו (ברכות ס\"ג ע\"א). נראה, שלו אמר ר' אליעזר: \"חכם גדול אתה\" (נגעים פ\"ט מ\"ג).","cat": "sage"},{"i": 1810,"n": "יהודה בן גדידיה","l": "י","b": "חי בימי בית שני, בזמנו של שמעון בן שטח (דור שלישי לחכמי ה\"זוגות\"). אמר לינאי המלך: \"רב לך כתר מלכות\" וינאי הרג אח\"כ כל חכמי ישראל (קדושין ס\"ו ע\"א).","cat": "sage"},{"i": 1811,"n": "רבי יהודה בן גדיש","l": "י","b": "תנא בדור השני - השלישי. העיד לפני רבי אליעזר (עירובין כ\"ז ע\"א).","cat": "sage"},{"i": 1812,"n": "יהודה בן גוריא","l": "י","b": "תנא בדור השלישי. תלמידו של רבי אליעזר. הורה לפני רבו ולא הוציא שנתו (עירובין ס\"ג ע\"א).","cat": "sage"},{"i": 1813,"n": "רבי יהודה בן גירין","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. הוא ורבי יהושע דסכנין אמרו בשם רבי לוי (מדרש שמואל).","cat": "sage"},{"i": 1814,"n": "רבי יהודה בן גמדא איש כפר עכו","l": "י","b": "מובא בבבלי (סוטה מ\"ג ע\"ב), ונראה שהוא ר' יהודה בן אגרא איש כפר עכו.","cat": "sage"},{"i": 1815,"n": "ר' יהודה בן גמליאל","l": "י","b": "תנא בדור הרביעי. בנו של רבן גמליאל דיבנה ואחיהם של רבן שמעון בן גמליאל (אבי רבי) ושל ר' חנינא בן גמליאל. מסר בשם אחיו ר' חנינא (ע\"ז ל\"ד ע\"ב).","cat": "sage"},{"i": 1816,"n": "רבי יהודה בן גרים","l": "י","b": "תנא בדור הרביעי - החמישי. בן גר וגיורת (שבת ל\"ג ע\"ב ברש\"י). תלמידו של רבי שמעון בר יוחאי (מו\"ק ט' ע\"א). רשב\"י שלח אליו ולחברו ר' יונתן בן עסמיי את בנו שיברכהו (שם). פעם דיבר רשב\"י נגד מלכות רומי ויהודה בן גרים שמע וסיפר זאת למקורביו, ונודע למלכות ורצו להרוג את רשב\"י, וברח והסתתר במערה י\"ג שנה, וכשיצא רשב\"י פגש את יהודה תלמידו, ונתן עיניו בו ונהפך לגל עצמות (שבת ל\"ג ע\"ב).","cat": "sage"},{"i": 1817,"n": "רבי יהודה בן דוסתאי","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. מובא במשנה, שאמר משום רבי שמעון בן שטח (ברכות ז' ע\"א).","cat": "sage"},{"i": 1818,"n": "יהודה בן דורתאי","l": "י","b": "מחכמי א\"י בתקופת ה\"זוגות\", כמאה שנה לפני חורבן הבית בדורם של שמעיה ואבטליון (הזוג הרביעי). פרש עם בנו והלך וישב בדרום, משום שחלק על החכמים בענין דין קרבן חגיגה (פסחים ע' ע\"ב). מובא פעם אחת בלבד בש\"ס. \"סה\"ד\" כתב: \"ונראה שהיה צדוקי\", ותמוה מנין לו.","cat": "sage"},{"i": 1819,"n": "ר' יהודה בן דמא","l": "י","b": "בפיוט \"אלה אזכרה\" למוסף יום הכיפורים נמנה בין עשרת הרוגי מלכות שנהרגו על קידוש ה' יחד עם ר' עקיבא וחבריו. במקומות אחרים לא הובא שם זה כלל.","cat": "sage"},{"i": 1820,"n": "ר' יהודה בן דרדייא","l": "י","b": "מובא בירושלמי (נדרים פ\"ז ה\"א). אולי אפשר להסיק מהענין שהוא אמורא ארץ ישראלי בדור הרביעי.","cat": "sage"},{"i": 1821,"n": "רבי יהודה בן חגרא","l": "י","b": "מובא בירושלמי (פאה פ\"ד ה\"ז), והוא רבי יהודה בן אגרא.","cat": "sage"},{"i": 1822,"n": "ר' יהודה בן חנניה","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. מובא בספרי (האזינו פסוק א').","cat": "sage"},{"i": 1823,"n": "רבי יהודה בן חרגא","l": "י","b": "מובא בירושלמי (כתובות פ\"א ה\"ג). \"סה\"ד\" כתב: \"ודאי שהוא רבי יהודה בן אגרא\".","cat": "sage"},{"i": 1824,"n": "יהודה בן טבאי","l": "י","b": "מחכמי ישראל הקדומים, שעמדו בראש הסנהדרין בימי בית שני. והוא וחברו שמעון בן שטח היו השלישי ב\"זוגות\". היה הנשיא או אב\"ד (חגיגה ט\"ז ע\"ב). רצו למנותו נשיא וברח לאלכסנדריה (ירו', חגיגה פ\"ב ה\"ב). שמעיה ואבטליון היו תלמידיו. פעם טעה והרג עד זומם, ומיד קיבל עליו לא להורות אלא בפני שמעון בן שטח (חגיגה שם). הוא בעל המאמר: \"אל תעש עצמך כעורכי הדיינין, וכשיהיו בעלי הדין עומדים לפניך, יהיו בעיניך כרשעים, וכשנפטרים מלפניך, יהיו בעיניך כזכאין וכו'\" (אבות פ\"א מ\"ח).","cat": "sage"},{"i": 1825,"n": "רבי יהודה בן טיטוס","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי אחא (ירו', ברכות פ\"ג ה\"ד). מסר גם בשמו של יהודה בן פזי (ירו', שבת פי\"ג ה\"ב). הלך לרומי ולפני נסיעתו קבל סמיכה, בתנאי שיחזור לארץ ישראל (ירו', בכורים פ\"ג סה\"ג).","cat": "sage"},{"i": 1826,"n": "רבי יהודה בן יאיר","l": "י","b": "תנא בדור השלישי. רבן שמעון בן גמליאל (אבי רבי) מסר בשמו (יבמות פ' ע\"ב).","cat": "sage"},{"i": 1827,"n": "ר' יהודה בן יעקב מבית גוברין","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. מובא בתוספתא (אהלות פי\"ח ט\"ז).","cat": "sage"},{"i": 1828,"n": "ר' יהודה בן ישעיה הבשם","l": "י","b": "תנא בדור השלישי - הרביעי. תלמידו של רבי טרפון והעיד לפני רבי עקיבא משמו של ר\"ט (תוספתא שביעית פ\"ה י\"ב). (ובחולין נ\"ה ע\"ב, הגירסה: \"ר' אושעיא בנו של ר' יהודה הבשם\"). מלאכתו היתה מכירת בשמים (חולין נ\"ה ע\"ב - רש\"י). ע\"ע רבי אושעיא בנו של רבי יהודה הבשם.","cat": "sage"},{"i": 1829,"n": "רבי יהודה בן כיני","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי אמי (ירו', תרומות פי\"א סה\"א).","cat": "sage"},{"i": 1830,"n": "רבי יהודה בן לוי","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. תלמידו של ר' יהושע בן לוי (ירו', שבת פ\"ז סה\"ב), ויש סבורים שהיה אחיו. רבי יוחנן שאל ממנו (שבת קי\"ג ע\"א) נראה, שגם בנו מנחם היה חכם (ירו', דמאי פ\"ה ה\"ח).","cat": "sage"},{"i": 1831,"n": "ר' יהודה בן לקיש","l": "י","b": "תנא בדור החמישי. מסר בשם רבן שמעון בן גמליאל (קה\"ר פ\"א - ט\"ו).","cat": "sage"},{"i": 1832,"n": "ר' יהודה בן לקרח","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם רבי שמואל בר נחמן. היה מבעלי האגדה (ירו', סוכה פ\"ד ה\"ו).","cat": "sage"},{"i": 1833,"n": "ר' יהודה בן מנשי","l": "י","b": "מובא בבבלי (מגילה י\"ד ע\"א), ובמקום אחר (ברכות י' ע\"א): הגיר': ר' יהודה בר מנסיא.","cat": "sage"},{"i": 1834,"n": "ר' יהודה בן נקוסא","l": "י","b": "תנא בדור החמישי. תלמידו של רבי (ב\"ב ע\"א ע\"א) ושל סומכוס (ב\"ק ל\"ט ע\"א). מסר בשם ר' יעקב (חולין קי\"ח ע\"ב). כל מעשיו היו לשם שמים (ב\"ק פ\"א ע\"ב). הרבה להתוכח עם מינים (קה\"ר פ\"א פסוק ח' - ד').","cat": "sage"},{"i": 1835,"n": "יהודה בן פדייה","l": "י","b": "מובא בב\"ר (פצ\"ד - ה'). ונראה שהוא בר פדא.","cat": "sage"},{"i": 1836,"n": "ר' יהודה בן פדייה","l": "י","b": "מובא בתנחומא (וארא - ב'). ונראה שהוא בר פדא.","cat": "sage"},{"i": 1837,"n": "ר' יהודה בן פזי (2)","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. לדעת תוספות (ב\"ב קמ\"ט ע\"א ד\"ה: רב) שם אמו של ר' יהודה היתה פזי (אולי בתו של ר' חייא - יבמות ס\"ה ע\"ב). מסר בשם ריב\"ל (ירו', ברכות פ\"ג ה\"א) ובשם ר' יוחנן (ירו', מע\"ש פ\"ג ה\"ג). התאכסן בבית הנשיא (ירו', שבת פי\"ב ה\"ג).","cat": "sage"},{"i": 1838,"n": "יהודה בן פטורא","l": "י","b": "ע\"ע יהודה בן פטורי.","cat": "sage"},{"i": 1839,"n": "יהודה בן פטורי","l": "י","b": "תנא בדור השני. מובא בבבלי: \"דרש בן פטוראי וכו', עד שבא ר\"ע ולימד וכו'\" (ב\"מ ס\"ב ע\"א).","cat": "sage"},{"i": 1840,"n": "ר' יהודה בן פילויה","l": "י","b": "מובא בש\"ר (פמ\"ב - ט'), ונראה שהוא ר' יודן בר פליא.","cat": "sage"},{"i": 1841,"n": "ר' יהודה בן פפוס","l": "י","b": "תנא בדור השני. ור' יהושע אמר עליו: \"שכל מעשיו לשם שמים\" (ירו', ברכות פ\"ב ה\"ט).","cat": "sage"},{"i": 1842,"n": "ר' יהודה בן קנוסא","l": "י","b": "מובא בבבלי (ב\"ק פ\"א ע\"ב), וצ\"ל: ר' יהודה בן נקוסא.","cat": "sage"},{"i": 1843,"n": "יהודה בן רבי חייא","l": "י","b": "אמורא בדור הראשון. נולד בבבל ועלה יחד עם אביו ואחיו לא\"י (סוכה כ' סע\"א). הוא ואחיו חזקיה היו תאומים, אחד נולד בתחילת ז' חדשים והשני לסוף ט' חדשים (יבמות ס\"ה ע\"ב), ונראה שיהודה היה הבכור, שכן נזכר תחילה בכל מקום. הם נקראו \"אמוראי דמערבא\" (ב\"ב ע\"ה ע\"א). התחתן עם בתו של ר' ינאי (כתובות ס\"ב ע\"ב). נפטר בחיי חותנו (שם) ונקבר לימין אביו [בטבריה] (מו\"ק כ\"ה ע\"א). כשעלה מבבל כבר היה גדול הדור (חולין פ\"ו ע\"א). היה כה גדול, עד שר' ינאי קראו: \"יהודה בריבי\" (ירו', בכורים פ\"ג ה\"ג). היה מאוכלי שולחנו של רבי (סנהדרין ל\"ה ע\"א). חלק עם רבי יונתן בהלכה (עירובין ק\"ג ע\"ב). אליהו הנביא גילה לרבי שרבי חייא ובניו הם דוגמת אברהם יצחק ויעקב (ב\"מ פ\"ה ע\"ב).","cat": "sage"},{"i": 1844,"n": "ר' יהודה בן רועץ","l": "י","b": "מובא בבבלי: \"שאלו תלמידיו את ר' יהודה בן רועץ וכו'\" (סנהדרין ד' ע\"א).","cat": "sage"},{"i": 1845,"n": "יהודה בן שמוע","l": "י","b": "תנא בדור הרביעי - החמישי. תלמידו של רבי מאיר (ר\"ה י\"ט ע\"א). רשב\"ג (אבי רבי) מסר הלכה אחת בענייני טומאה, שיהודה בן שמוע אמר בשם ר\"מ (שם). פעם גזרה המלכות ביום כ\"ח באדר שלא יעסקו בתורה ושלא ימולו את בניהם ושיחללו את השבת, והלך יהודה בן שמוע וחבריו, ונטל עצה ממטרונית אחת שכל גדולי רומי מצויין אצלה וביטל הגזרה (שם).","cat": "sage"},{"i": 1846,"n": "ר' יהודה בן תימא","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. היה מראשי דורו ועליו אמרו: \"בעלי משנה כגון ר' יהודה בן תימא וחבריו, פליגי בה ר\"פ ורבנן, חד אמר: 'שש מאות סדרי משנה' וחד אמר: 'שבע מאות סדרי משנה'\" (חגיגה י\"ד ע\"א). מפורסם מאמרו: \"הוי עז כנמר וקל כנשר ורץ כצבי וגבור כארי, לעשות רצון אביך שבשמים\" (אבות פ\"ה מ\"כ).","cat": "sage"},{"i": 1847,"n": "רב יהודה בנו של רב שמואל בר שילת","l": "י","b": "אמורא בבלי בדור השלישי. מסר פעמים רבות בשם רב (ברכות מ\"ז ע\"א). היה חברם של רב יהודה (תענית י\"ד ע\"א) ורב הונא בר חיננא (מו\"ק ט\"ז ע\"א).","cat": "sage"},{"i": 1848,"n": "רבי יהודה בנו של רבן יוחנן בן זכאי","l": "י","b": "תנא בדור השני. הלכה אחת בלבד הובאה בשמו (נדה ט\"ו ע\"א), וכן הוא בתוספתא (שם פ\"ג).","cat": "sage"},{"i": 1849,"n": "רב יהודה בר אבא","l": "י","b": "מובא בבבלי (מנחות ל\"א ע\"ב), ויש גירסאות שונות בשם.","cat": "sage"},{"i": 1850,"n": "רב יהודה בר אביי","l": "י","b": "מובא בבבלי (פסחים צ\"ב ע\"ב), וגיר' \"מסורת הש\"ס\" ו\"דק\"ס\": \"רבי יהודה בר אמי\".","cat": "sage"},{"i": 1851,"n": "ר' יהודה בר אבין","l": "י","b": "מובא בירושלמי (ר\"ה פ\"א ה\"ח).","cat": "sage"},{"i": 1852,"n": "רב יהודה בר אושעיא","l": "י","b": "אמורא בבלי בדור השלישי. שאלוהו שאלה ולא ידע להשיב, וחזרו ושאלוה לר' מתנה ולא ידע להשיב, ושאלוה מר' יהודה והשיב: \"הכי אמר שמואל\" (עירובין פ' ע\"א). נראה, שמושבו היה בפומבדיתא, שמצינו: \"רב יהודה בר אושעיא היה קא קליף ליה טחלא ללוי בריה דר\"ה בר חייא\" (חולין צ\"ג ע\"א), ור\"ה בר חייא הרביץ תורה בפומבדיתא (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 1853,"n": "רב יהודה בר אחותאי","l": "י","b": "מובא בבבלי (כריתות י\"ג ע\"ב).","cat": "sage"},{"i": 1854,"n": "רב יהודה בר אידי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (ר\"ה ל\"א ע\"א).","cat": "sage"},{"i": 1855,"n": "רב יהודה בר אישתתא","l": "י","b": "אמורא בבלי בדור הרביעי. רב נתן בר אושעיה היה תלמידו (עירובין נ\"ב ע\"א).","cat": "sage"},{"i": 1856,"n": "רבי יהודה בר אלעאי","l": "י","b": "תנא בדור הרביעי, והוא סתם רבי יהודה בש\"ס (מנחות י\"ח ע\"א). \"כל היכא דאמר מעשה בחסיד אחד או ר' יהודה בן בבא או ר' יהודה בר אילעאי\" (ב\"ק ק\"ג ע\"ב). בנו ותלמידו של התנא רבי אילעאי (מנחות שם). מושבו היה באושא (שהש\"ר פ\"ב - ה). בילדותו למד אצל ר\"ט בלוד (מגילה כ' ע\"א) ואצל ר' ישמעאל (מו\"ק כ\"ד ע\"ב). מגדולי תלמידיו של רבי עקיבא (יבמות ס\"ב ע\"ב). על פיו כתב את הספרא: \"סתם ספרא רבי יהודה, סתם סיפרי ר\"ש, וכולהו אליבא דר\"ע\" (סנהדרין פ\"ו ע\"א). כן קיבל מר\"א בן עזריה (ברכות ט\"ו ע\"ב). הוא וארבעת חבריו: ר\"מ, ר' יוסי, ר\"ש ור\"א בן שמוע, נסמכו ע\"י ר' יהודה בן בבא (סנהדרין י\"ד ע\"א). מגדולי התנאים וראש המדברים בכל מקום (שבת ל\"ג ע\"ב). בכל מחלוקת בינו לבין ר' מאיר או ר' שמעון, ההלכה כר' יהודה (עירובין מ\"ו ע\"ב). בין תלמידיו: רבנו הקדוש (שבועות י\"ג ע\"א) ורבי ישמעאל ברבי יוסי (סוכה י\"ח ע\"א). חלק עם ר' יוחנן בן ברוקה (עירובין ק\"ד ע\"ב) ועם ר' שמעון שזורי (מנחות ל' ע\"ב). מצינו מחלוקת: \"איזו היא משנה? ר\"מ אומר הלכות ר' יהודה אומר מדרש\" (קידושין מ\"ט ע\"א). לבן עזאי אמר: \"עד כאן העזת פניך ברבך\" [ר\"ע] (ברכות ס\"ב ע\"א). היה עני מרוד עד שלא היתה לו כסות (נדרים מ\"ט ע\"ב). פניו האירו תמיד (שם). מנהגו בערב שבת: \"רוחץ פניו ידיו ורגליו, ומתעטף ויושב בסדינין המצוייצין, ודומה למלאך ה' צבאות\" (שבת כ\"ה ע\"ב). נראה שהאריך ימים, שכן נפטר אחרי רבי מאיר (נזיר מ\"ט ע\"ב), וכנראה גם אחרי רבי יוסי (סוכה י\"ח ע\"א). הורה הלכות בבית רבי (מנחות ק\"ד ע\"א). הניח אחריו בן חכם ושמו רבי יוסי (מנחות ס\"ג ע\"ב), שהיה מן התנאים בדור החמישי. בן אחר נפטר על פניו (מו\"ק כ\"א ע\"א).","cat": "sage"},{"i": 1857,"n": "רבי יהודה בר אמי","l": "י","b": "אמורא ארץ ישראלי. מסר בשם ר\"ל (ירו', תרומות ספ\"ב) ובשם רב יהודה (עירובין ל' ע\"ב). ר\"ז, כשהתעייף מלימוד, היה יושב ליד פתח ביתו של רבי יהודה בר אמי, כדי לקיים מצות קימה לפני חכמים (שם כ\"ח ע\"ב).","cat": "sage"},{"i": 1858,"n": "רב יהודה בר אשי","l": "י","b": "אמורא בבלי בדור השלישי. אמר משמו של רב (ברכות י\"ט ע\"ב) גיר' \"דק\"ס\": ר' יהודה בר אמי.","cat": "sage"},{"i": 1859,"n": "רב יהודה בר בבא","l": "י","b": "תנא בדור השלישי. תלמידו של שמואל הקטן (תוספתא סוטה פי\"ג ד'). חברו של רבי עקיבא (יבמות קכ\"ב ע\"א) וחלק עמו (יומא פ\"ו ע\"ב). היה מופלג בחסידות עד שאמרו: \"כל היכא דאמרינן מעשה בחסיד אחד או רבי יהודה בן בבא או רבי יהודה בר אילעאי\" (ב\"ק ק\"ג ע\"ב). נהרג על קידוש ה' והיה מעשרת הרוגי מלכות: \"זכור אותו איש לטוב ורבי יהודה בן בבא שמו, שאילמלא הוא וכו' בטלו דיני קנסות מישראל, שפעם אחת גזרה המלכות גזרה על ישראל שכל הסומך יהרג וכו', וסמך שם חמישה זקנים ואלו הן: רבי מאיר ורבי יהודה ורבי שמעון ורבי יוסי ורבי אלעזר בן שמוע\" (כולם תלמידי רבי עקיבא), והכירו אויביהם בהם ונעצו בו 003 חניתות של ברזל (סנהדרין י\"ג ע\"ב). רבי עקיבא נהרג קודם לו (מסכת שמחות פ\"ח).","cat": "sage"},{"i": 1860,"n": "ר' יהודה בר ביזנא","l": "י","b": "מובא בבבלי (נדרים ל\"ב ע\"א).","cat": "sage"},{"i": 1861,"n": "ר' יהודה בר ביני","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר' אמי (ירו', תרומות פי\"א סה\"א).","cat": "sage"},{"i": 1862,"n": "רבי יהודה בר גדיא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. סיפר על מנהגו של ר' יעקב בר בון בענייני מעשרות (ירו', מע\"ש פ\"ד ה\"א).","cat": "sage"},{"i": 1863,"n": "יהודה בר גרוגרות","l": "י","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (יומא ע\"ח ע\"א). תוספות ישנים גורסים: יהודה גרוגרות.","cat": "sage"},{"i": 1864,"n": "רבי יהודה בר זבדא","l": "י","b": "מובא בירושלמי (ברכות פ\"א ה\"ה), והוא ר' יהודה בר זבידא.","cat": "sage"},{"i": 1865,"n": "רב יהודה בר זבדי","l": "י","b": "מובא בבבלי (קידושין ע\"ג ע\"ב), והוא ר' יהודה בר זבדא.","cat": "sage"},{"i": 1866,"n": "רבי יהודה בר זבידא","l": "י","b": "אמורא ארץ ישראלי בדור השני. ר' שמואל בר נחמן (תלמידו של ר' יוחנן) מסר בשמו (ירו', ברכות פ\"א ה\"ה). רבי אבהו בר זוטרי היה תלמידו (ברכות י\"ב ע\"ב). היו לו שני אחים: ר' אבא (יבמות פ\"ג ע\"ב) ור' סימון (ירו', ב\"ב רפ\"ג).","cat": "sage"},{"i": 1867,"n": "רב יהודה בר זבינא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. חברו ובר פלוגתיה דר' חנינא [חברון דרבנן] (חולין צ\"ט ע\"ב).","cat": "sage"},{"i": 1868,"n": "ר' יהודה בר זכריה","l": "י","b": "מובא ב\"ילקוט\" (תבוא - תתק\"ל).","cat": "sage"},{"i": 1869,"n": "רב יהודה בר חביבא","l": "י","b": "אמורא ארץ ישראלי בדור השני. תלמידו של שמואל (כתובות ס' ע\"א). בתו התחתנה עם בנו של רב יהודה (ברכות מ\"ב ע\"א).","cat": "sage"},{"i": 1870,"n": "רב יהודה בר חיננא","l": "י","b": "אמורא בבלי בדור החמישי. תלמידו של רב הונא בריה דרב יהושע (ב\"ק י\"ד ע\"ב).","cat": "sage"},{"i": 1871,"n": "ר' יהודה בר חמא","l": "י","b": "מובא בתנחומא (נ\"ח - ח').","cat": "sage"},{"i": 1872,"n": "רבי יהודה בר חנינא","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. מרבותיו של ר\"ל, כמובא בגמרא: \"הא דידיה הא דרביה\" (עירובין י\"א ע\"ב). ר\"ל מסר בשמו על תקנות אושא (ירו', פאה פ\"א ה\"א). ר\"ל קנס אדם בליטרא זהב, לאחר שהעליב את רבו זה (ירו', ב\"ק פ\"ח ה\"ו).","cat": "sage"},{"i": 1873,"n": "רב יהודה בר יחזקאל","l": "י","b": "מגדולי אמוראי בבל בדור השני. מייסדה של ישיבת פומבדיתא [שהתקיימה כ - 008 שנה] (\"אגרת רב שרירא גאון\"). נולד ביום שנפטר רבי יהודה הנשיא (קידושין ע\"ב ע\"ב). האריך ימים ונפטר בשנת ד\"א נ\"ח (842) (\"אגרת רב שרירא גאון\"). תלמידם של רב (קידושין פ\"א ע\"א) ושל שמואל (יבמות י\"ז ע\"א). אחרי פטירת רב היה כפוף לר\"ה (חולין קי\"א ע\"ב, לגירסת הרא\"ש), וישב זמן מה לפני רב אסי מהוצל (יבמות ט\"ז ע\"ב). אחר פטירת ר\"ה היתה פומבדיתא לישיבה המרכזית והוא היה ראש הדור. בין תלמידיו המובהקים: רבה (עירובין י\"ז ע\"א), ור' יוסף (יבמות י\"ז ע\"א) ור' זירא (שם ע\"ח ע\"ב). הוא ור' עינא כונו: \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב), עד שאמרו עליהם שיודעים להכניס פיל בנקב של מחט (ב\"מ ל\"ח ע\"ב). אביו של ר' יהודה היה חכם גדול, שאפילו שמואל היה קם בפניו (קידושין ל\"ג ע\"ב). ר' יהודה היה גדול מאביו (שם רש\"י). שמואל אמר עליו ש\"אין זה ילוד אשה\" [אלא מלאך] (נדה י\"ג ע\"א). כשהיה גוזר תענית בגלל עצירת גשמים וחולץ נעל אחת לאות אבל, מיד ירד גשם (תענית כ\"ד ע\"ב). היה בקי בהויות העולם והטבע (שבת ע\"ז ע\"ב). התנגד חריפות שתלמידי בבל יעזבוה ויעלו לא\"י (ברכות כ\"ד ע\"ב). היה גבה קומה מאד (נדה כ\"ד ע\"ב). לעת זקנתו כהו עיניו (גיטין י\"ט ע\"א). אחיו, רמי בר יחזקאל, היה אף הוא אמורא, וחלק עם אחיו ר' יהודה כמה פעמים (כתובות כ\"א ע\"א). על כסאו ישב תלמידו רבה בר נחמני (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 1874,"n": "רב יהודה בר יצחק","l": "י","b": "מובא בבבלי (תענית ו' ע\"ב).","cat": "sage"},{"i": 1875,"n": "ר' יהודה בר ישמעאל","l": "י","b": "מובא בבבלי (חולין קי\"ח ע\"ב). אמורא שאין לקבוע את זמנו המדוייק. ניהל ישיבה והיו לו תלמידים (ירו', ברכות פ\"ה ה\"א). פעם נפלה לו גלימתו, ונחש שמרה (שם).","cat": "sage"},{"i": 1876,"n": "רבי יהודה בר ליואי","l": "י","b": "מובא בבבלי (שבת קי\"ג ע\"א), והוא כנראה ר' יהודה בן לוי.","cat": "sage"},{"i": 1877,"n": "ר' יהודה בר לקרה","l": "י","b": "הוא ר' יהודה בר לקרח.","cat": "sage"},{"i": 1878,"n": "ר' יהודה בר מנסיא","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי (ברכות י\"א ע\"א). אותה אימרה מובאת בשמו במקום אחר (מגילה י\"ד ע\"א), ושם הגירסא ר' יהודה בר מנשי. יתכן מאוד, שר' יודן בר מנשה (ירו', תענית רפ\"ז) הוא ר' יהודה בר מנסיא.","cat": "sage"},{"i": 1879,"n": "ר' יהודה בר מספרתא","l": "י","b": "אמורא ארץ ישראלי בדור השני. ר' אלעאי מסר בשמו (סנהדרין מ\"ד ע\"א), ואולי הוא ר' יהודה בן ספרא.","cat": "sage"},{"i": 1880,"n": "ר' יהודה בר מערבא","l": "י","b": "מובא בבבלי (סוטה מ\"א ע\"ב).","cat": "sage"},{"i": 1881,"n": "יהודה בר מרימר","l": "י","b": "אמורא בבלי בדור השביעי. חברם של מר בר רב אשי ורב אחא מדיפתי. שלושתם היו שקולים, ולא היה אחד גדול מחברו (ברכות מ\"ה ע\"ב).","cat": "sage"},{"i": 1882,"n": "ר' יהודה בר נחמיה","l": "י","b": "מובא בתנחומא (סוף תשא), והוא ר' יהודה בר נחמני.","cat": "sage"},{"i": 1883,"n": "יהודה בר נחמן","l": "י","b": "מובא בירושלמי (סוכה פ\"א ה\"א), והוא ר' יהודה בר נחמני.","cat": "sage"},{"i": 1884,"n": "יהודה בר נחמני","l": "י","b": "תנא בדור השלישי. נפטר בחיי ר\"ט ור\"ע, כעונש שהשיב על דברי ר\"ט (כנראה בלגלוג מסויים): \"א\"ל ר\"ע: 'יהודה צהבו פניך שהשבת את זקן, תמהני אם תאריך ימים'\". ואמנם לא הוציא שנתו ונפטר לפני תום השנה (מנחות ס\"ח ע\"ב).","cat": "sage"},{"i": 1885,"n": "ר' יהודה בר נחמני","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. הוא וחברו ר' לוי היו דרשנים בבית מדרשו של רבי יוחנן (ירו', סוכה רפ\"ה). היה מתורגמנו של רבי שמעון בן לקיש (סנהדרין ז' ע\"ב). רבי שמעון בן לקיש הלך עמו לנחם אבלים ואמר לו: \"קום אימא מילתא\" (כתובות ח' ע\"ב).","cat": "sage"},{"i": 1886,"n": "ר' יהודה בר נריא","l": "י","b": "אמורא ארץ ישראלי בדור הראשון מרבותיו של רבי יהושע בן לוי (מד' קהלת פ' כי העושק).","cat": "sage"},{"i": 1887,"n": "יהודה בר נתן","l": "י","b": "מובא בבבלי (ברכות ס' ע\"א) שהלך אחר רב המנונא, ואין להכריע לאיזה רב המנונא הכוונה.","cat": "sage"},{"i": 1888,"n": "ר' יהודה בר סיגנא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם ר' אחא (איכ\"ר פ\"א - ל\"ט).","cat": "sage"},{"i": 1889,"n": "ר' יהודה בר ספרא","l": "י","b": "אמורא ארץ ישראלי בדור השני. ר' אלעאי מסר בשמו (פסחים ע' ע\"ב), ואולי הוא ר' יהודה בר מספרתא.","cat": "sage"},{"i": 1890,"n": "ר' יהודה בר פזי דברדליה","l": "י","b": "מובא בירושלמי (שקלים ספ\"ז).","cat": "sage"},{"i": 1891,"n": "ר' יהודה בר פלמא","l": "י","b": "מובא בתנחומא (וירא - מ\"ה). ונראה שהוא ר' יודן בר פליא.","cat": "sage"},{"i": 1892,"n": "ר' יהודה בר פפי","l": "י","b": "מובא בירושלמי (תענית פ\"ד ה\"א). וצ\"ל: ר' יהודה בר פזי.","cat": "sage"},{"i": 1893,"n": "רב יהודה בר קזא","l": "י","b": "נראה שהוא אמורא בבלי שהיה לו בית מדרש. מובא בבבלי: \"אמר רב נחמן: 'תני רב יהודה בר קזא [פרש\"י: שם חכם] במתניתא דבי בר קזא'\" (כתובות ק\"ד ע\"א).","cat": "sage"},{"i": 1894,"n": "רב יהודה בר שילא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אסי (זבחים כ\"ב ע\"א). הביא עמו לבבל מסורות מארץ ישראל, שמצינו: \"כי אתא רב יהודה בר שילא, אמר: 'אמרי במערבא'\" (יבמות כ\"א ע\"ב). נראה כי המובא: \"אמר רב יהודה בר שילא, אמר רב אשי\" (נדה ס\"ג ע\"א), צ\"ל: רב אסי ולא רב אשי.","cat": "sage"},{"i": 1895,"n": "רב יהודה בר שילת","l": "י","b": "מובא בבבלי (שבת קכ\"ו ע\"א), והוא ר' יהודה בר שילא.","cat": "sage"},{"i": 1896,"n": "רב יהודה בר שלום","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי [חברו דר' יונה] (ירו', דמאי פ\"ו ה\"ב). חברו של רבי פנחס (תנחומא וארא ס' כ\"ב). חלק עם ר' מתניה (ירו', שבת פי\"ב ה\"ד) נמנה עם בעלי המדרש. בבבלי מובא פעם אחת: \"דרש ר' יהודה בר שלום: כשם שמזונותיו של אדם קצובין לו מר\"ה, כן חסרונותיו וכו'\" (ב\"ב י' ע\"א). ואולי הוא הנקרא ר' יהודה הלוי בר שלום (מד' תהלים פקי\"ט - ב'). היה דיין בעירו (ירו', תרומות פ\"ה סה\"ד).","cat": "sage"},{"i": 1897,"n": "יהודה בר שמואל","l": "י","b": "מובא בבמד\"ר (פי\"ב - ג') שראה קטב מרירי ומת.","cat": "sage"},{"i": 1898,"n": "רבי יהודה בר שמואל","l": "י","b": "מובא (שבת ל\"ח ע\"א). יתכן שהוא רבי יהודה, בנו של שמואל בר שילת.","cat": "sage"},{"i": 1899,"n": "רבי יהודה ברבי","l": "י","b": "מובא בבבלי: \"א\"ר יוסי: 'ומודה לי רבי יהודה ברבי'\" (מנחות ל\"ד ע\"ב), ופרש\"י: \"יהודה החכם\", וא\"כ, סבר שזה רבי יהודה התנא בר פלוגתיה דר' יוסי.","cat": "sage"},{"i": 1900,"n": "רבי יהודה ברבי שמעון","l": "י","b": "אמורא ארץ ישראלי בדור המעבר בין התנאים לאמוראים. תלמידו של התנא רבי אלעזר בר שמעון (חולין מ\"ח ע\"א). רבו שאינו מובהק של רבי יוחנן (ב\"ב קי\"ד ע\"ב - רשב\"ם). ר' יוחנן שלח אליו שאלה (חולין שם).","cat": "sage"},{"i": 1901,"n": "רב יהודה בריה דרב יהושע","l": "י","b": "מובא בבבלי (ע\"ז מ\"ג ע\"ב), והוא ט\"ס וצ\"ל: רב הונא בריה דרב יהושע. וכן מוכח מרש\"י (ע\"ז מ\"ב ע\"ב ד\"ה: \"וכדרב הונא בריה דרב יהושע\"), וכן גירסת הרי\"ף והרא\"ש.","cat": "sage"},{"i": 1902,"n": "ר' יהודה בריה דר' שמעון בן פזי","l": "י","b": "נראה אולי שהוא זהה לר' יהודה בן פזי.","cat": "sage"},{"i": 1903,"n": "ר' יהודה בר' אלעזר","l": "י","b": "מובא בויק\"ר (פכ\"א - ז').","cat": "sage"},{"i": 1904,"n": "ר' יהודה בר' יעקב","l": "י","b": "מובא ב\"זהר חדש\" (בראשית פסוק תוצא הארץ).","cat": "sage"},{"i": 1905,"n": "ר' יהודה בר' סיחון","l": "י","b": "מובא בב\"ר (פצ\"ד - ט') והוא ט\"ס וצ\"ל: ר' יהודה בר סימון.","cat": "sage"},{"i": 1906,"n": "ר' יהודה בר' סימון","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו של האמורא ר' סימון (ירו', מו\"ק פ\"ג סה\"ה). מסר בשם ר' יהושע בן לוי (ויק\"ר פי\"ב פסוק ויותר) ובשם רבי יוחנן (תנחומא נשא י\"ט). משמו מסרו ר' עזריה (ב\"ר פ\"ו - ה'). ועוד. ר' ירמיה ור' יוסי שאלו אצלו ממנהגי אביו (ירו', ברכות פ\"ד ה\"א). התחתן בבית הנשיא (ירו', שבת פי\"ב ה\"ג).","cat": "sage"},{"i": 1907,"n": "יהודה ב\"ר","l": "י","b": "מובא בירושלמי (שבת פ\"ז ה\"ב). והוא יהודה בר ריבי, כלומר יהודה בנו של רבי חייא (רבי חייא נקרא \"בריבי\" שפירושו: גדול בדורו).","cat": "sage"},{"i": 1908,"n": "ר' יהודה גוזריא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם ר' אחא (ירו', ר\"ה פ\"ג ה\"ט). נראה שמלאכתו היתה מוהל, כמו שפירש רש\"י (שבת ק\"ל ע\"ב ד\"ה): \"ר' יהודה הגוזר את התינוקות\".","cat": "sage"},{"i": 1909,"n": "ר' יהודה גלוסטרא","l": "י","b": "מובא בבבלי (ברכות כ\"ב סע\"א), ואין להכריע אם היה תנא או אמורא. מהלשון נראה כתנא בדורו של רבי עקיבא. \"יוחסין\" כתב שהיה אמורא מתלמידיו של רבי יוחנן, ותמה עליו \"סה\"ד\" וכתב: \"וצ\"ע מנ\"ל שיהיה תלמיד רבי יוחנן, וה'שארית יוסף' לא הביאו בתלמידיו\".","cat": "sage"},{"i": 1910,"n": "יהודה גרוגרות","l": "י","b": "מובא בתוספות ישנים (יומא ע\"ח ע\"א), והוא יהודה בר גרוגרות.","cat": "sage"},{"i": 1911,"n": "ר' יהודה דסכנין","l": "י","b": "מובא בתנחומא (הישן, עקב). ואולי צ\"ל: ר' יהושע דסכנין.","cat": "sage"},{"i": 1912,"n": "ר' יהודה דציפורן","l": "י","b": "מובא במ\"ר (פט\"ז - כ\"ד), ואולי ט\"ס וצ\"ל: ר' הונא דציפורן.","cat": "sage"},{"i": 1913,"n": "ר' יהודה הגוזר","l": "י","b": "תנא - אמורא בדור המעבר שבין התנאים לאמוראים. רבי אושעיא (בעל הברייתות) סיפר ששאל ממנו הלכה (שבת ק\"ל ע\"ב). היה מוהל.","cat": "sage"},{"i": 1914,"n": "רב יהודה הינדואה","l": "י","b": "אמורא בבלי בדור הששי. היה גר ללא יורשים (קידושין כ\"ב ע\"ב). ומר זוטרא ביקרו בעת שמת, וזכה בממונו (שם). מובא ממנו מעשה מופלא שסיפר שראה על הים (ב\"ב ע\"ד ע\"ב).","cat": "sage"},{"i": 1915,"n": "רבי יהודה הכהן","l": "י","b": "תנא בדור השלישי. מובא פעם אחת, שהעיד על הלכה יחד עם רבי יהודה בן בבא (עדיות פ\"ח מ\"ב).","cat": "sage"},{"i": 1916,"n": "רבי יהודה הכהן בר אבין","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רב ביבי (מדרש תהלים פ\"ב).","cat": "sage"},{"i": 1917,"n": "ר' יהודה הלוי","l": "י","b": "מובא באגדה, ונראה שהוא ר' יהודה בר שלום.","cat": "sage"},{"i": 1918,"n": "ר' יהודה הלוי בר שלום","l": "י","b": "מובא במדרש תהלים (פקי\"ט - ב'), ואולי הוא ר' יהודה בר שלום. ו\"סה\"ד\" חילקו לשנים.","cat": "sage"},{"i": 1919,"n": "רבי יהודה הנחתום","l": "י","b": "תנא בדור השלישי בדורו של ר\"ע (ר\"ה כ\"ב ע\"א). היה מעשרה הרוגי מלכות. יש אומרים שאלישע בן אבויה שראה את לשונו נתונה בפי כלב, אמר: \"זו תורה וזו שכרה\" ויצא לתרבות רעה (ירו', חגיגה פ\"ב ה\"א).","cat": "sage"},{"i": 1920,"n": "רבי יהודה הנשיא","l": "י","b": "נשיא וראש הדור כולו, בדור החמישי לתנאים. דור שביעי להלל הזקן. ידוע בשם \"רבי\" (כתובות ק\"ג ע\"ב), בשם \"רבינו הקדוש\" (שבת קי\"ח ע\"ב), ובשם \"רבי יהודה הנשיא\" (שבת ל\"ה ע\"ב). נולד כשנפטר רבי עקיבא (קידושין ע\"ב ע\"ב). מושבו היה בית שערים, שם היתה ישיבתו (סנהדרין ל\"ב ע\"ב). בשבע עשרה שנותיו האחרונות גר בציפורי (כתובות שם). ערך וסידר את המשנה (יבמות ס\"ד ע\"ב): \"מכדי מתניתין מאן תיקן? רבי\". \"סה\"ד\" כתב: \"וחתם שמו בראש חיבורו מאימתי גימטריא: אני יהודה קדוש\" (כ\"כ בהקדמה לס' באר אברהם בשם בעל מגלה עמוקות). קיבל תורה מחמשת תלמידי ר\"ע הגדולים: רבי יוסי (נדה ס\"ח ע\"ב), רבי מאיר (עירובין י\"ג ע\"ב), רבי אלעזר בן שמוע (שם י\"ג ע\"א) ורבי שמעון בן יוחאי (שבת קמ\"ז ע\"ב). מרבי יהודה למד עוד בטרם היה בר מצוה (מגילה כ' ע\"א) וכן מר' יעקב בר קרשאי (ירו', פסחים פ\"י ה\"א). למד יחד עם חברו רבי אלעזר בר' שמעון, לפני אביו רבן שמעון בן גמליאל ור' יהושע בן קרחה (ב\"מ פ\"ד ע\"ב). תלמידיו של רבי היו רבים ומהם היו ראשי דור הראשון לאמוראים, כגון רב (חולין קל\"ז ע\"ב), רבי יוחנן (שם, ושם נ\"ד ע\"א), לוי (סנהדרין י\"ז ע\"ב) ור' חנינא בר חמא (ע\"ז י\"ט ע\"ב). היה משכמו ומעלה (נדה כ\"ד ע\"ב). עשיר מופלג (ב\"מ פ\"ה ע\"א). עליו נאמר: \"מימות משה ועד רבי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). הוציא 021 אלף ממון לבטל גזירת הקרבת שור פטום ביום אידם (ע\"ז ט\"ז ע\"א). בשנות בצורת פתח אוצרותיו לעניים (ב\"ב ח' ע\"א). כשנפטר זקף עשר אצבעותיו ואמר שלא נהנה אפילו באצבע קטנה (כתובות ק\"ד ע\"א). היה ישן ביום לא יותר ממשך ששים נשימות (סוכה כ\"ו ע\"ב). היה לו תדיר גילוי אליהו (ב\"מ פ\"ה ע\"א). קיסר רומי אנטנינוס היה ידידו בנפש ולמד תורה עמו (ע\"ז י' ע\"ב). לאחר פטירתו מילא בנו ר\"ג את מקומו בנשיאות, ולו מסר סדרי הנשיאות (כתובות ק\"ג ע\"א). כשמת רבי בטלה ענוה ויראת חטא והוכפלו הצרות (שם).","cat": "sage"},{"i": 1921,"n": "ר' יהודה הסבר","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (עירובין ע\"ב ע\"ב). רש\"י ותוספות חולקים במשמעות השם.","cat": "sage"},{"i": 1922,"n": "ר' יהודה הענתותי","l": "י","b": "\"סה\"ד\" מביא ממנו מעשה נורא וכיצד קרה לו נס גדול וניצל. לדבריו חי בדור הרביעי לתנאים, בזמנו של רבי מאיר ואינו מוזכר בשום מקום בש\"ס או במדרשים.","cat": "sage"},{"i": 1923,"n": "ר' יהודה חייטא","l": "י","b": "סופר מומחה בדור החמישי לתנאים. כתב ספר תהלים ורבי שבח את כתיבתו (ב\"ב קס\"ד ע\"ב).","cat": "sage"},{"i": 1924,"n": "רב יהודה מדאסקרתא","l": "י","b": "אמורא בבלי בדור הרביעי - החמישי. הקשה הרבה לרבא (יבמות פ\"ז ע\"ב). רב פפא היה תלמידו (נדה ל\"ט ע\"א).","cat": "sage"},{"i": 1925,"n": "רב יהודה מדפתי","l": "י","b": "אמורא בבלי בדור החמישי. מרבותיו של רבינא (ברכות כ\"ה ע\"א), וגירסת \"דק\"ס\": \"ר' ירמיה מדפתי\".","cat": "sage"},{"i": 1926,"n": "רב יהודה מהגרוניא","l": "י","b": "אמורא בבלי בדור השני. נראה, שהיה תלמידו של שמואל (ע\"ז ל\"ט ע\"א). חנן חייטא שאל ממנו, וענה לו \"הכי אמר שמואל\" (שם).","cat": "sage"},{"i": 1927,"n": "ר' יהודה מנשייא בר מנשה","l": "י","b": "מובא בירושלמי (שבת פ\"ו רפ\"ה), ואפשר שצ\"ל: ר' יהודה בר מנשיה או בר מנשה, וערבוב גירסאות יש כאן. ע\"ע ר' יהודה בר מנסיא.","cat": "sage"},{"i": 1928,"n": "רב יהודה מסורא","l": "י","b": "אמורא שאין לקבוע את זמנו המדוייק. מובא בבבלי (ב\"מ פ\"ט ע\"א).","cat": "sage"},{"i": 1929,"n": "יהודה מר בר מרימר","l": "י","b": "אמורא בבלי בדור החמישי. תלמידו של רבא. חברו של רב פפא (כתובות פ' ע\"ב). היה עם ר\"פ, כשר\"פ הלך לכתוב כתובה לנשואי בנו ור\"פ כיבד את דבריו (כתובות נ\"ב ע\"ב).","cat": "sage"},{"i": 1930,"n": "רבי יהודה נשיאה א'","l": "י","b": "נשיא וראש הדור וריש מתיבתא, בדור הראשון לאמוראי ארץ ישראל. דור תשיעי להלל ונכדו של רבי יהודה הנשיא. \"נשיאה\" הוא בארמית מקביל ל\"נשיא\" בעברית. (ע\"ז ל\"ו ע\"א תד\"ה: אשר). מוזכר במשנה שהוא ובית דינו התירו השמן (ע\"ז ל\"ה ע\"ב). בנו ותלמידו של רבן גמליאל ג' (ירו', ביצה פ\"א הי\"א). ר\"ל היה תלמידו המובהק (נזיר כ' ע\"ב). גדולי דור הראשון היו חבריו: ר' חנינא (ירו', סנהדרין ספ\"ב), ר' הושעיא (מגילה ז' ע\"ב) ור' יונתן (ירו', קידושין פ\"ג הי\"ב). ר' יהודה נשיאה היה אחרון הנשיאים שגם החזיק בנזר התורה והיה גדול בתורה (ירו', ע\"ז פ\"א ה\"א). מוזכר יחד עם אחיו הלל (פסחים נ\"א ע\"א). הצטיין בענוה ובפשטות (ירו', סנהדרין שם), אך בתוקף סמכותו נהג נשיאותו בתקיפות (נדה נ\"ב ע\"א).","cat": "sage"},{"i": 1931,"n": "ר' יהודה נשיאה ב'","l": "י","b": "נשיא בדור השני - השלישי לאמוראי ארץ ישראל. דור אחד עשר להלל. אביו רבן גמליאל ד' לא נזכר בתלמוד בבלי. היה תלמידו של רבי יוחנן (ר\"ה כ' ע\"א). אחרי פטירת ר' יוחנן ישב לפני ר' אמי (מנחות כ\"ט ע\"ב). נראה שהמעשה שקיסר דיקליטיינוס קרא לנשיא ישראל לפתע (ירו', תרומות ספ\"ח), מתייחס אליו לפי סדר הזמנים, כי דיקליטיינוס נתקסר בשנת 482 ור' יוחנן נפטר בשנת 972.","cat": "sage"},{"i": 1932,"n": "ר' יהודה נשיאה ג'","l": "י","b": "נשיא בדור השלישי - הרביעי לאמוראי ארץ ישראל. דור י\"ג להלל הזקן. בזמנו היה ר' ירמיה (ירו', מגילה פ\"ג ה\"ב). אביו ר' גמליאל ה', היה תלמידו של ר' אבהו (ירו', ע\"ז פ\"א ה\"א), והוא עצמו זכה להעמיד בן גדול ושמו הלל שחיבר את הלוח עד ביאת המשיח.","cat": "sage"},{"i": 1933,"n": "ר' יהודה קלוסטרא","l": "י","b": "מובא בבבלי (ברכות כ\"ב ע\"א). \"סה\"ד\" כתב שה\"יוחסין\" מביאו בין תלמידי ר' יוחנן, ותמה מנ\"ל לו שהיה תלמיד ר' יוחנן.","cat": "sage"},{"i": 1934,"n": "רב יהושע","l": "י","b": "מובא בבבלי: \"אמר רב יהושע: דרש רבא\" (פסחים נ\"ג ע\"ב), ולא ברור מי הוא רב יהושע זה. \"סה\"ד\" מביא: \"ר' יהושע ור' נחמיה בש\"ר אחא\" (מדרש ריש פתיחתא דאיכה) וגם הוא תמה וכותב: \"ר' יהושע זה לא ידעתי מי הוא\".","cat": "sage"},{"i": 1935,"n": "רבי יהושע","l": "י","b": "הוא רבי יהושע בן חנניה.","cat": "sage"},{"i": 1936,"n": "ר' יהושע אונייא","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. מ\"התנאים\" שוני הברייתות. ר' שמואל בר יצחק מסר קטע אחד מהברייתא ששנה (ירו', פסחים פ\"ג ה\"א), ושם משובש שמו לר' יושוע אונייה.","cat": "sage"},{"i": 1937,"n": "יהושע איש עוזי","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (נדרים ל\"ח ע\"ב).","cat": "sage"},{"i": 1938,"n": "ר' יהושע בן אביין","l": "י","b": "מובא בירושלמי (יומא פ\"ג ה\"ה), וצ\"ל: יהושע בן אבין.","cat": "sage"},{"i": 1939,"n": "ר' יהושע בן אבין","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מסר בשם ר' סימון (ירו', יומא פ\"ג סה\"ה). ור' מנחמא מסר משמו (רו\"ר פ\"ג - י\"ט).","cat": "sage"},{"i": 1940,"n": "ר' יהושע בן אבירם","l": "י","b": "מובא באס\"ר (פ\"ה - ד'), והגירסא במדרש שמואל (פי\"ג - ה'): ר' יהושע בריה דר' בירי.","cat": "sage"},{"i": 1941,"n": "ר' יהושע בן אלישע","l": "י","b": "תנא מראשי דורו: \"דתניא מעשה שמת וכו' ושאל את רבי יהושע בן אלישע וד' זקנים שעמו\" (נזיר מ\"ד ע\"א).","cat": "sage"},{"i": 1942,"n": "ר' יהושע בן ביתות","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר' יהודה בר סימון (ב\"ר פפ\"ד - י\"ח).","cat": "sage"},{"i": 1943,"n": "ר' יהושע בן בתירא","l": "י","b": "תנא בדור השלישי. זכה לראות את הבית (מנחות ק\"ג ע\"ב). לפני שסמכוהו נקרא \"בן בתירא\", ולאחר שסמכוהו קראו לו: \"ר' יהושע בן בתירא\" (תענית ג' ע\"א). ר' יהודה [תלמידו של ר\"ע] קיבל ממנו (שם).","cat": "sage"},{"i": 1944,"n": "יהושע בן גמלא","l": "י","b": "כהן גדול בזמן בית שני (יומא י\"ח ע\"א). תקנתו מוזכרת בתלמוד: \"דאמר רב יהודה אמר רב: 'ברם, זכור אותו האיש לטובה, ויהושע בן גמלא שמו, שאלמלא הוא נשתכחה תורה מישראל'\" (ב\"ב כ\"א ע\"א).","cat": "sage"},{"i": 1945,"n": "רבי יהושע בן הורקנוס","l": "י","b": "תנא בדור הרביעי. תלמידו של רבי עקיבא (סוטה כ\"ז ע\"ב רש\"י).","cat": "sage"},{"i": 1946,"n": "ר' יהושע בן זירוז","l": "י","b": "תנא בדור הרביעי. בן חמו (גיסו) ותלמידו של רבי מאיר (חולין ו' ע\"ב). פעם העיד לפני רבי על רבי מאיר, שאכל עלה של ירק בבית שאן ללא הפרשת מעשר, והתיר רבי על ידו את בית שאן כולה (שם).","cat": "sage"},{"i": 1947,"n": "יהושע בן זריז","l": "י","b": "מובא בירושלמי (דמאי פ\"ב ה\"א), והוא יהושע בן זירוז.","cat": "sage"},{"i": 1948,"n": "רבי יהושע בן חנניה","l": "י","b": "מראשי התנאים בדור השני. והוא רבי יהושע סתם במשנה (נזיר נ\"ו ע\"ב רש\"י). היתה לו ישיבה בפקיעין (סנהדרין ל\"ב ע\"ב). עליו אמרו: \"אשרי יולדתו\" (אבות פ\"ב מ\"ח). היה משבט לוי, ועוד זכה לשמש במקדש עם המשוררים (ערכין י\"א ע\"ב). כשרבן גמליאל נתמנה לנשיא, שימש כאב בית דין על ידו (ב\"ק ע\"ד ע\"ב). מתלמידיו המובהקים ביותר של רבי יוחנן בן זכאי (גיטין נ\"ו ע\"א). היה חברו הגדול של רבי אליעזר - מחלוקתם מובאת הרבה בש\"ס. יחד הוציאו את רבם ר' יוחנן בן זכאי מירושלים הנצורה (שם). אחר פטירתו של רבי אליעזר, כשבאו חכמים להשיב על דברי רבי אליעזר, לא הניחם ר' יהושע ואמר: \"אין משיבין את הארי לאחר מיתה\" (גיטין פ\"ג ע\"א). היה במחלוקת הגדולה של רבי אליעזר נגד החכמים בענין תנור של עכנאי, כשיצאה בת קול ואמרה: \"הלכה כרבי אליעזר בכל מקום, עמד רבי יהושע על רגליו ואמר: לא בשמים היא... אין אנו משגיחים בבת קול\". ולבסוף נידו את רבי אליעזר (ב\"מ נ\"ט ע\"ב). וכשפגע רבן גמליאל (דיבנה) כמה פעמים בכבודו של רבי יהושע, הורידוהו מנשיאותו ומינו את רבי אלעזר בן עזריה במקומו (ברכות כ\"ז ע\"ב). בין תלמידיו המובהקים היה רבי עקיבא (שם ס\"ב ע\"א), שהיה אח\"כ תלמיד חבר שלו (מסכת כלה רפ\"ב). וכן היה תלמידו ר' ישמעאל (ע\"ז כ\"ט ע\"ב), ואת ר' ישמעאל זה פדה בממון רב מבית האסורים ברומי אחר החורבן (גיטין נ\"ח ע\"ב). היה מחכמי הסנהדרין שידע לשונות רבים (סנהדרין י\"ז ע\"ב). היה לו ידע רב בתכונה (הוריות י' ע\"א). היה חכם מופלג והצטיין בויכוחים עם מינים (חגיגה ה' ע\"ב) עם קיסר רומי (חולין נ\"ט ע\"ב) ועם חכמי אתונא (בכורות ח' ע\"ב), ואת כולם ניצח. ומשמת אמרו עליו: \"בטלה עצה ומחשבה\" (סוף סוטה). אמר: \"מימי לא נצחני אדם חוץ מאשה תינוק ותינוקת\" (עירובין נ\"ג ע\"ב). היה עני גדול (ברכות כ\"ח ע\"א). האריך ימים והגיע לזקנה מופלגת (שבת קנ\"ב ע\"א).","cat": "sage"},{"i": 1949,"n": "ר' יהושע בן יאיר","l": "י","b": "מובא בירושלמי (תענית פ\"ג ה\"ד). אמר בשם ר' פנחס בן יאיר.","cat": "sage"},{"i": 1950,"n": "רבי יהושע בן כפיסאי","l": "י","b": "תנא בדור השלישי - הרביעי. חתנו של רבי עקיבא. האריך ימים ודיבר עם רבי (שבת קמ\"ז ע\"א). העיד על מה שראה ממעשיהם של רבן גמליאל ואונקלוס הגר (תוספתא מקואות פ\"ו ג'). רבן שמעון בן גמליאל מסר בשמו (ע\"ז ל\"ב ע\"ב). שם אביו נשתבש לכמה אופנים: קבסאי, קבוסיו, קבסוי, קפוסאי, קפוצאי.","cat": "sage"},{"i": 1951,"n": "רבי יהושע בן לוי","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. היה גם מגדולי חכמי האגדה (ב\"ק נ\"ה ע\"א). מושבו היה בדרום (איכ\"ר פ\"ג - ו'). תלמידם של רבי אלעזר הקפר (ע\"ז מ\"ג ע\"א) ורבי יהודה בן פדיה (תנחומא וארא ב'). מסר הרבה גם בשם בר קפרא (תענית כ\"ו ע\"ב). ומשמע שהיה גם תלמידו של רבי (שבת מ\"ו ע\"א). בין תלמידיו הרבים היו רבי יוחנן (סוכה ל\"ב ע\"ב), רבי אלעזר (ברכות י\"ט ע\"א) ואף רבי חייא בר אבא (ירו', שבת פ\"א ה\"ב). היה חסיד מופלג והיה מיחידי סגולה בכל הדורות שלא טעם טעם מיתה וזכה להכנס חי לגן עדן (כתובות ע\"ז ע\"ב). אליהו הנביא נגלה לו תדיר (סנהדרין צ\"ח ע\"א), וזכה לדבר עם משיח צדקנו (שם). פניו היו כפני מלאך (ירו', ברכות פ\"ה ה\"א). יצג את היהודים בפני המלכות (שם). מאמר אחד שלו זכה להכנס למשנה (בסוף מסכת עוקצין) ומשמש חתימה לששה סדרי משנה: \"עתיד הקב\"ה להנחיל לכל צדיק וצדיק וכו'\".","cat": "sage"},{"i": 1952,"n": "ר' יהושע בן לוי בר שלום","l": "י","b": "מובא בויק\"ר (פט\"ו - ט\"ז).","cat": "sage"},{"i": 1953,"n": "ר' יהושע בן לקיש","l": "י","b": "מובא בתוספתא (סנהדרין פ\"א), ונראה שצ\"ל: ר' יהודה בן לקיש.","cat": "sage"},{"i": 1954,"n": "רבי יהושע בן ממל","l": "י","b": "תנא בדור השלישי. מסר בשם רבי יהושע (נזיר נ\"ו ע\"ב). ר\"מ אמר עליו: \"בעל הלכות היה\" (תוספתא נזיר פ\"ה א').","cat": "sage"},{"i": 1955,"n": "רבי יהושע בן מתיא","l": "י","b": "תנא בדור הרביעי. יתכן שהיה תלמידו של רבי ישמעאל: \"שלשה דברים אמרו לפני רבי ישמעאל ולא אמר בהם איסור ולא היתר, ופירשו ר' יהושע בן מתיא\" (עדיות פ\"ב מ\"ה).","cat": "sage"},{"i": 1956,"n": "רבי יהושע בן עוזאה","l": "י","b": "מובא בבבלי (יומא מ\"ז ע\"ב). \"אמר רבי יוחנן: הדר פשט' יהושע בן עוזאה\".","cat": "sage"},{"i": 1957,"n": "ר' יהושע בן פדיה","l": "י","b": "כך מביא \"סה\"ד\" ממדרש משלי (פ\"ו), ואולי ט\"ס שם.","cat": "sage"},{"i": 1958,"n": "יהושע בן פרחיה","l": "י","b": "היה נשיא (חגיגה ט\"ז ע\"ב). הוא וחברו ניתאי הארבלי היו השני בחמשת ה\"זוגות\" בזמן הבית, לפני התחלת תקופת התנאים (אבות פ\"א מ\"ו). חי שלושה דורות לפני הלל הזקן. היה תלמידם של יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים, ורבם של יהודה בן טבאי ושמעון בן שטח (שם). בימיו היה יוחנן כהן גדול שנעשה צדוקי והרג לחכמי ישראל (קידושין ס\"ו ע\"א), והוא ברח לאלכסנדריה של מצרים (סוטה מ\"ז ע\"א). מסופר (שם לפי הגירסא בדפוסים ישנים) שדחה בשתי ידיו לאחד מתלמידיו שיצא לתרבות רעה, והיו שסברו שזה ישו הנוצרי אך נראה שהיה מסית ומדיח אחר, כי יהושע בן פרחיה חי שני דורות לפני ישו הנוצרי.","cat": "sage"},{"i": 1959,"n": "רבי יהושע בן פתייה","l": "י","b": "מובא בירושלמי (שקלים פ\"ג ה\"ב: שם פ\"ח ה\"א).","cat": "sage"},{"i": 1960,"n": "ר' יהושע בן פתר ראש","l": "י","b": "תנא בדור הרביעי - החמישי. תלמידו של רבי מאיר. ורבי אלעזר מספר שראהו דן לפני רבי מאיר בהלכה (נזיר נ\"ו ע\"ב). רש\"י כתב: בן פתר ראש \"כך שמו\" ותוספות כתבו: בן פתר ראש \"כך שם אביו\".","cat": "sage"},{"i": 1961,"n": "ר' יהושע בן קבוסיו","l": "י","b": "מובא בתוספתא (סוף מעשרות), והוא ר' יהושע בן כפוסאי.","cat": "sage"},{"i": 1962,"n": "ר' יהושע בן קבסוי","l": "י","b": "מובא בירושלמי (דמאי פ\"ג ה\"ד), והוא ר' יהושע בן כפוסאי.","cat": "sage"},{"i": 1963,"n": "ר' יהושע בן קפוסאי","l": "י","b": "מובא בבבלי (בכורות ל\"ה ע\"ב), והוא ר' יהושע בן כפוסאי.","cat": "sage"},{"i": 1964,"n": "ר' יהושע בן קפוצאי","l": "י","b": "מובא בבבלי (בכורות ל\"ט ע\"א), והוא ר' יהושע בן כפוסאי.","cat": "sage"},{"i": 1965,"n": "רבי יהושע בן קרחה","l": "י","b": "תנא בדור הרביעי. לדעתו של רבנו גרשום ורש\"י (בכורות נ\"ח ע\"א) היה בנו של רבי עקיבא. לדעתו של רש\"י היה תלמידו של אביו רבי עקיבא (שבועות ו' ע\"א). תוס' סוברים (בכורות נ\"ח ע\"א) שרבי עקיבא לא היה אביו. היה חברו של רבן שמעון בן גמליאל (אביו של רבי) ושניהם היו רבותיהם של רבי אלעזר בר שמעון ורבי (ב\"מ פ\"ד ע\"ב). התוכח עם המינים (שבת קנ\"ב ע\"א) והשיב להם תשובות ניצחות (ויק\"ר פ\"ד - ו'). זכה לאריכות ימים מופלגת ורבי שאלו: \"במה הארכת ימים\" (מגילה כ\"ח ע\"א). בשעת פטירתו בירך את רבי: \"יהי רצון שתגיע לחצי ימי\" (שם).","cat": "sage"},{"i": 1966,"n": "רבי יהושע בנו של רבי עקיבא","l": "י","b": "מובא בבבלי (שבועות ו' ע\"א) ופרש\"י: הוא יהושע בן קרחה. ומובא: \"ז' דברים צוה ר\"ע את ר' יהושע בנו\" (פסחים קי\"ב ע\"א). תוס' חולקים על רש\"י וסוברים שרבי יהושע בן קרחה אינו בנו של רבי עקיבא (בכורות נ\"ח ע\"א).","cat": "sage"},{"i": 1967,"n": "רבי יהושע בר אבא","l": "י","b": "אמורא בדור השלישי. נראה שהיה ארץ ישראלי שקיבל סמיכה וירד לבבל, ולכן נקרא רבי ולא רב.","cat": "sage"},{"i": 1968,"n": "ר' יהושע בר בנימין בר לוי","l": "י","b": "מובא בשהש\"ר (ספ\"ד).","cat": "sage"},{"i": 1969,"n": "ר' יהושע בר זידל","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. \"כשחלה ר' ינאי בר ישמעאל ובאו לבקרו ר\"ג ור' הושעיא ור' חנינא ור' אבין בר כהנא, מצאו שם את ר' יהושע בן זידל ואמרו אליו: 'הרי בעל השמועה והרי בעל העובדא'\" (ירו', תרומות פ\"ח ה\"ג).","cat": "sage"},{"i": 1970,"n": "ר' יהושע בר מנחמה","l": "י","b": "מובא בב\"ר (פנ\"ג - י').","cat": "sage"},{"i": 1971,"n": "רבי יהושע בר נחמיה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מסר בשם ר' חנינא בר יצחק (ב\"ר פ\"ח - י\"א). ר' מנחמא מסר בשמו (ויק\"ר פ\"כ - י').","cat": "sage"},{"i": 1972,"n": "ר' יהושע בר נחמן","l": "י","b": "מובא בויק\"ר (פ\"ב - ג'), ונראה אולי שהוא ר' יהושע בר נחמיה.","cat": "sage"},{"i": 1973,"n": "ר' יהושע בר סימון","l": "י","b": "מובא בויק\"ר (פל\"ד - ח'). מסר בשם לוי. וצ\"ל: ר' יהודה בר סימון.","cat": "sage"},{"i": 1974,"n": "רבי יהושע בריה דרב אידי","l": "י","b": "אמורא בבלי בדור החמישי - הששי. היה מגדולי דורו. מצינו שרב אשי הקשה לו (יבמות ל\"ו ע\"ב). לפנינו רב הושעיא, אך רש\"י (יבמות ל\"ד ע\"א ד\"ה: הכא) גרס ר' יהושע בריה דרב אידי. כשביקר את רב אשי כבדו בעיגלא תילתא (שבת י\"א ע\"א). כשהלך לבקר את רב כהנא [רבו של ר' אשי], מצא שכבר נפטר (פסחים ג' ע\"ב). אביו ר' אידי היה נקרא רב אידי בר אבין, ונשא כהנת והיו לו שני בנים חכמים: רב שישא ורב יהושע (פסחים מ\"ט ע\"א).","cat": "sage"},{"i": 1975,"n": "ר' יהושע בריה דרב חננאל","l": "י","b": "מובא בירושלמי (מגילה פ\"א ה\"ט), ואם נאמר שהוא בנו של רב חננאל, תלמידו דרב, הרי היה אמורא בבלי בדור השלישי.","cat": "sage"},{"i": 1976,"n": "ר' יהושע בריה דר' בירי","l": "י","b": "מובא במדרש שמואל (פי\"ג - ה). והגירסא במקום אחר (אס\"ר פ\"ה - ד'): ר' יהושע בן אבירם.","cat": "sage"},{"i": 1977,"n": "ר' יהושע בריה דר' טומי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. חברו של ר' בורקי, ואת שניהם כינה ר' יצחק בן אלעזר \"עדה קדושה\", משום שהיו משלשין את היום שליש לתורה, שליש לתפילה ושליש למלאכה (קה\"ר פ\"ט - ט').","cat": "sage"},{"i": 1978,"n": "ר' יהושע בריה דר' תנחום בר חייא דכפר אגין","l": "י","b": "מובא ב\"ילקוט\" (ישעיה רמז שיז).","cat": "sage"},{"i": 1979,"n": "ר' יהושע בריה דר' תנחום דכפר חנון","l": "י","b": "מובא בקה\"ר (פ\"ג - ב').","cat": "sage"},{"i": 1980,"n": "רבי יהושע דיימא","l": "י","b": "מובא בירושלמי פעם אחת: \"בעא קומי רבי יונה\" (שבועות פ\"ו ה\"א) ונראה לי שט\"ס הוא, וצ\"ל: רבי יהושע דרומיא.","cat": "sage"},{"i": 1981,"n": "רבי יהושע דסכנין","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי לוי (ירו', ברכות פ\"ד ה\"א). בשמו מסרו רבי אבא בריה דרבי פפי (ירו', ברכות פ\"ד ה\"א), ר' יוסי ממלחייא (פסיקתא דר' כהנא ל\"א א'), רבי מני דשאב (שם ל\"ח א'), ור' יוסטא בר שונם (תנחומא בובר ויצא סי' ו').","cat": "sage"},{"i": 1982,"n": "ר' יהושע דרומיא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידם של רבי יונה (ירו', סוכה ספ\"ד) ושל רבי יוסי (ירו', שבת פ\"י ה\"ה). מסר גם בשם ר' אחא (ירו', שבת פ\"י ה\"ה).","cat": "sage"},{"i": 1983,"n": "רבי יהושע הגרסי","l": "י","b": "תנא בדור הרביעי. מתלמידיו המובהקים של רבי עקיבא ומשרתו הנאמן עד יום מותו. כשהיה ר\"ע בבית האסורים עמד רבי יהושע הגרסי לשרתו (עירובין כ\"א ע\"ב), ומסופר: \"ומעשה בר\"ע שהיה חבוש בבית האסורים ורבי יהושע הגרסי תלמידו היה משמשו וכו', נפטר ממנו והלך לביתו. בא אליהו ועמד על פתח ביתו, א\"ל וכו': 'באתי להגיד לך שרבי עקיבא מת בבית האסורים', מיד הלכו שניהם וכו'\" (מד' משלי פ\"ט - ב'). היה לו אח ושמו נימוס (בכורות ו' ע\"ב).","cat": "sage"},{"i": 1984,"n": "ר' יהושע הכהן בר נחמני","l": "י","b": "מובא בתנחומא (תשא ה'), ונראה שאולי הוא ר' יהושע בר נחמיה.","cat": "sage"},{"i": 1985,"n": "ר' יהושע הלוי בר שלום","l": "י","b": "מובא במ\"ר (פט\"ו - ט\"ז), ואולי צ\"ל: ר' יהודה הלוי בר שלום.","cat": "sage"},{"i": 1986,"n": "ר' יהושע חילפיי","l": "י","b": "מובא בפדר\"כ (קכ\"ה).","cat": "sage"},{"i": 1987,"n": "ר' יהושעיא בריה דר' שמאי","l": "י","b": "מובא בירושלמי (כתובות פ\"ב ה\"ד), וסביר שצ\"ל: ר' הושעיא בריה דר' שמאי.","cat": "sage"},{"i": 1988,"n": "ר' יוד","l": "י","b": "מובא בבבלי: \"אמר ר' אמי בר יוד\" (תענית כ\"ב ע\"ב), ופרש\"י: \"חכם ששמו יוד\".","cat": "sage"},{"i": 1989,"n": "יוד קרת","l": "י","b": "מובא בבבלי (קידושין ט\"ז ע\"ב), ופירש \"הערוך\" שהוא שם חכם.","cat": "sage"},{"i": 1990,"n": "יודא","l": "י","b": "ע\"ע יהודה.","cat": "sage"},{"i": 1991,"n": "ר' יודא בר אימי","l": "י","b": "מובא בירושלמי (תרומות ספ\"ב), והוא ר' יהודה בר אמי.","cat": "sage"},{"i": 1992,"n": "ר' יודא בר דרדייא","l": "י","b": "מובא בירושלמי (נדרים פ\"ז ה\"א).","cat": "sage"},{"i": 1993,"n": "ר' יודא בר סיסין","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם ר' אחא (ירו' קידושין פ\"ג ה\"ג). ספק הוא אם הוא זהה לר' יהודה בר סיגנא.","cat": "sage"},{"i": 1994,"n": "רבי יודה בי ר' בון","l": "י","b": "מובא בירושלמי (כתובות פ\"ה ה\"ו).","cat": "sage"},{"i": 1995,"n": "ר' יודה ענתורייא","l": "י","b": "מובא בירושלמי (שקלים ספ\"ח), ואולי זהה לר' יודן ענתונדריא.","cat": "sage"},{"i": 1996,"n": "ר' יודן (2)","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מבעלי האגדה וההלכה. תלמידו של ר' אבא (ירו', כתובות פ\"ב ה\"ד). מסר גם בשם ר' יוחנן (ירו', קידושין פ\"ב ה\"ה) ור' אלעזר ב\"ר פמ\"ד - י\"ב). חברו של רבי יוסי (ירו', כתובות שם). רבו של רבי מנא (ירו', ביצה פ\"א ה\"ה).","cat": "sage"},{"i": 1997,"n": "ר' יודן אבוי דר' מתליא","l": "י","b": "מובא בירושלמי (כלאים פ\"ג ה\"א), ונראה שצ\"ל: מתניא.","cat": "sage"},{"i": 1998,"n": "ר' יודן אבוי דר' מתניא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. נקרא על שם בנו ר' מתניא. מובא בירושלמי (דמאי פ\"ה ה\"ג). שמו השתבש בכמה אופנים.","cat": "sage"},{"i": 1999,"n": "ר' יודן אבויה דר' מתנה","l": "י","b": "מובא בירושלמי (תענית פ\"א ה\"ג), ונראה שהוא ר' יודן אבויה דר' מתניה.","cat": "sage"},{"i": 2000,"n": "ר' יודן אבויה דר' מתניתא","l": "י","b": "מובא בירושלמי (יבמות פ\"א), ונראה שצ\"ל: ר' יודן אבויה דר' מתניא.","cat": "sage"},{"i": 2001,"n": "ר' יודן אנתודרייא","l": "י","b": "מובא בירושלמי (ע\"ז פ\"א ה\"ב), ואולי זהה לר' יודן ענתונדריא.","cat": "sage"},{"i": 2002,"n": "ר' יודן אנתורדייא","l": "י","b": "מובא בירושלמי (ברכות פ\"ד ה\"א), ואולי זהה לר' יודן ענתונדריא.","cat": "sage"},{"i": 2003,"n": "ר' יודן אנתורי","l": "י","b": "מובא בירושלמי (ברכות פ\"ד ה\"ג), ואולי זהה לר' יודן ענתונדריא.","cat": "sage"},{"i": 2004,"n": "ר' יודן בי רבי חנן","l": "י","b": "מובא בירושלמי (קידושין פ\"ב ה\"ה), והוא ר' יודן בר חנין.","cat": "sage"},{"i": 2005,"n": "ר' יודן בי ר' ישמעאל","l": "י","b": "מובא בירושלמי (ברכות פ\"ד ה\"ב), ונראה שהוא ר' יהודה בר ישמעאל.","cat": "sage"},{"i": 2006,"n": "ר' יודן בן גדיא","l": "י","b": "מובא באיכ\"ר (פ\"ג - ת'), ונראה שהוא ר' יהודה בר גדיא.","cat": "sage"},{"i": 2007,"n": "ר' יודן בן טרפון","l": "י","b": "כן גורס \"פני משה\" בירושלמי (שבועות פ\"א ה\"ו), ולפנינו הגיר': \"ר' יודן כד טריפן וכו'\".","cat": "sage"},{"i": 2008,"n": "ר' יודן בר ברתיה דר' שמעון בן יוחאי","l": "י","b": "כך מובא בירושלמי (קידושין פ\"א ה\"ז).","cat": "sage"},{"i": 2009,"n": "ר' יודן בר גורייא","l": "י","b": "מובא בירושלמי (שבועות פ\"ב ה\"ג), ואולי הוא זהה לר' יודן גיריא.","cat": "sage"},{"i": 2010,"n": "ר' יודן בר דורתי","l": "י","b": "ע\"ע ר' יודן בר ברתיה דר' שמעון בן יוחאי.","cat": "sage"},{"i": 2011,"n": "ר' יודן בר חלפיי","l": "י","b": "כך מביא היוחסין ו\"סה\"ד\" מויק\"ר (פ\"ז - ג').","cat": "sage"},{"i": 2012,"n": "ר' יודן בר חנין","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם ר' ברכיה (ירו', סנהדרין פ\"י ה\"א).","cat": "sage"},{"i": 2013,"n": "ר' יודן בר חנינא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר' שמואל בר נחמני (רו\"ר פ\"ב ט\"ז).","cat": "sage"},{"i": 2014,"n": "ר' יודן בר יודן בר שלום","l": "י","b": "מובא בירושלמי (מגילה פ\"א ה\"ט), ואולי ט\"ס וצ\"ל: ר' יודן בר שלום (הוא ר' יהודה בר שלום). במדרש תהלים (פק\"ו - ז') מצינו: ר' יודן בריה דר' יודן.","cat": "sage"},{"i": 2015,"n": "ר' יודן בר ישמעאל","l": "י","b": "ע\"ע ר' יהודה בר ישמעאל.","cat": "sage"},{"i": 2016,"n": "ר' יודן בר מנשה","l": "י","b": "מובא בירושלמי (תענית רפ\"ב), שחלק עם ר' שמואל בר נחמן. נראה, שאולי הוא ר' יהודה בר מנסיא.","cat": "sage"},{"i": 2017,"n": "יודן בר נחמיה","l": "י","b": "מובא באיכ\"ר (פ\"א פ' ומרוב), והוא ר' יהודה בר נחמני.","cat": "sage"},{"i": 2018,"n": "ר' יודן בר פדיא","l": "י","b": "כך הגיר' בירושלמי (שביעית פ\"ה ה\"א), אך \"פני משה\" גורס: \"ר' יודן בר פליא\".","cat": "sage"},{"i": 2019,"n": "ר' יודן בר פיליא","l": "י","b": "מובא בויק\"ר (פכ\"ד - ב'), ונראה שהוא ר' יודן בר פליא.","cat": "sage"},{"i": 2020,"n": "ר' יודן בר פליא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' יונה (ירו', שביעית פ\"ה ה\"א - לגיר' \"פני משה\"). שמו נשתבש לכמה אופנים: בר פדיא, ר' יהודה בן פלויה, בר פילייא, ר' יהודה בר פלמא.","cat": "sage"},{"i": 2021,"n": "ר' יודן בר פלייא","l": "י","b": "מובא במדרש תהלים (רפק\"א), ונראה שהוא ר' יודן בר פליא.","cat": "sage"},{"i": 2022,"n": "ר' יודן בר שלום","l": "י","b": "ע\"ע רב יהודה בר שלום.","cat": "sage"},{"i": 2023,"n": "ר' יודן בר שקלי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. הביא שאלה בפני רבי יוסי (ירו', כתובות פ\"ט ה\"י).","cat": "sage"},{"i": 2024,"n": "ר' יודן ברבי שמואל","l": "י","b": "מובא בויק\"ר (פט\"ו - ב').","cat": "sage"},{"i": 2025,"n": "יודן בריבי","l": "י","b": "תנא מובא בבבלי (קידושין כ\"א ע\"ב). ופרש\"י: יודן שמו וגדול בדורו היה.","cat": "sage"},{"i": 2026,"n": "ר' יודן בריבי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם ר' ברכיה (ויק\"ר ספל\"ו).","cat": "sage"},{"i": 2027,"n": "ר' יודן בריה דרב","l": "י","b": "מובא בירושלמי (ע\"ז פ\"ב ה\"א).","cat": "sage"},{"i": 2028,"n": "ר' יודן בריה דר' אייבו","l": "י","b": "מובא בירושלמי (ברכות פ\"ב ה\"ד), ואולי צ\"ל: ר' יודן בשם ר' אייבו.","cat": "sage"},{"i": 2029,"n": "ר' יודן בריה דר' חמא דכפר תחומין","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם חזקיה (ירו', תענית פ\"א ה\"ז).","cat": "sage"},{"i": 2030,"n": "ר' יודן בריה דר' יודן","l": "י","b": "מובא במדרש תהלים (פק\"ו - ז'). ע\"ע ר' יודן בר יודן בר שלום.","cat": "sage"},{"i": 2031,"n": "ר' יודן בר' יוסי","l": "י","b": "מובא בויק\"ר (פ\"ט - ט').","cat": "sage"},{"i": 2032,"n": "ר' יודן בר' שמעון","l": "י","b": "מובא בב\"ר (פ\"ד - ב').","cat": "sage"},{"i": 2033,"n": "ר' יודן גזורי","l": "י","b": "מובא בירושלמי (מגילה פ\"א ה\"ה), ואולי זהה ליודן גירי.","cat": "sage"},{"i": 2034,"n": "יודן גירי","l": "י","b": "מובא בב\"ר (פל\"ה - ג'), ואולי הוא יהודה בן גרים.","cat": "sage"},{"i": 2035,"n": "ר' יודן גיריא","l": "י","b": "מובא בירושלמי (תענית פ\"ג ה\"ט), ואולי זהה לר' יודן גירי.","cat": "sage"},{"i": 2036,"n": "ר' יודן דיפו","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מובא בויק\"ר (פ\"כ - י'). הגירסא במקום אחר: \"ר' יוחנן דיפו\" (מד\"ר פ\"ב - כ\"ד).","cat": "sage"},{"i": 2037,"n": "ר' יודן דכפר אימי","l": "י","b": "מובא בירושלמי (שבת פט\"ז ה\"ז). אותו מעשה מובא במקום אחר: \"ר' יונה דכפר אימי\" (ירו', נדרים פ\"ד ה\"ט).","cat": "sage"},{"i": 2038,"n": "ר' יודן דמן גלייא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. חברו של ר' שמואל בר נחמני. שניהם מסרו משום ר' אליהו עיני (ב\"ר פנ\"א - י\"א).","cat": "sage"},{"i": 2039,"n": "ר' יודן דמן גלילא","l": "י","b": "מובא בויק\"ר (פ\"ב - ד').","cat": "sage"},{"i": 2040,"n": "ר' יודן מגדלייא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. ר' יוסי בר יעקב בא לבקרו בחוליו (ירו', ברכות פ\"ט ה\"ב).","cat": "sage"},{"i": 2041,"n": "ר' יודן נסייא","l": "י","b": "מובא בירושלמי (עירובין פ\"ז ה\"י), והוא ר' יהודה נשיאה.","cat": "sage"},{"i": 2042,"n": "ר' יודן ענתדרייא","l": "י","b": "מובא בירושלמי (שבת פ\"ט ה\"ג), ואולי זהה לר' יודן ענתנדריא.","cat": "sage"},{"i": 2043,"n": "ר' יודן ענתונדריא","l": "י","b": "מובא בירושלמי (תענית פ\"ב ה\"ב), ואולי זהה לר' יודן ענתנדריא.","cat": "sage"},{"i": 2044,"n": "ר' יודן ענתנדריא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. שאל מר' יוסי (ירו', שקלים ספ\"ח). מובא בשם ר' יודן ענתונדריא (ירו', תענית פ\"ב ה\"ב). שמו השתבש בש\"ס הירושלמי לכמה אופנים: ענתונדרייא, ענתדרייא, ענתורייא, אנתורי, אנתורדיא, אנתודרייא.","cat": "sage"},{"i": 2045,"n": "ר' יודן קפודקיא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' יוסי (ירו', פאה פ\"א ה\"ד).","cat": "sage"},{"i": 2046,"n": "ר' יוחי בר יודן","l": "י","b": "מובא בפדר\"כ (ל\"ח), ונראה שיש ט\"ס בשם.","cat": "sage"},{"i": 2047,"n": "רבי יוחנן","l": "י","b": "גדול אמוראי ארץ ישראל בדור השני וראש הדור כולו: גם חכמי בבל היו כפופים לו. בטרם נולד, אמר עליו רבי את הפסוק: \"בטרם אצרך בבטן ידעתיך\" (יומא פ\"ב ע\"ב). היה יתום כפול מלידה, כי כשעיברתו אמו - מת אביו, וכשילדתו - מתה (קידושין ל\"א ע\"ב). בצעירותו למד לפני רבי (פסחים ג' ע\"ב). רבותיו היו: חזקיה (עירובין כ\"ד ע\"א), ר' ינאי (ב\"ב קנ\"ד ע\"ב), ר' חנינא (ירו', הוריות פ\"ג ה\"ד) ור' אושעיא (עירובין נ\"ג ע\"א). המשיך לבוא לפני ר' אושעיא במשך 31 שנה, אף שכבר לא היה צריך לו (ירו', עירובין פ\"ה ה\"א). בישיבה של מעלה יושב ר' יוחנן אצל ר' ינאי (ב\"מ פ\"ה ע\"ב). כשנפטר רבי חנינא קרע עליו ר' יוחנן שלושה עשר בגדים (מו\"ק כ\"ד ע\"א). את רב החשיב לרבו, ונהג לכתוב לרב לבבל: \"לקדם רבותינו שבבבל\" (חולין צ\"ה ע\"ב). יסד ישיבה גדולה בטבריה. היה ראש ישיבה 08 שנה (סה\"ד). הראש והראשון בישיבתו היה ר' שמעון בן לקיש, שהיה לו גם כתלמיד (תענית ח' ע\"א), ואח\"כ הפך להיות לו תלמיד חבר (כתובות פ\"ד ע\"ב). רבי יוחנן הביא את רשב\"ל ללימוד תורה, וגם נתן לו את אחותו לאשה, ובסוף ימיהם היה ביניהם דין ודברים חריף, ור' יוחנן העניש את רשב\"ל והוא מת, ואח\"כ מרוב צער נעקרה דעתו של ר' יוחנן וביקשו רחמים ומת גם ר' יוחנן (ב\"מ פ\"ד ע\"א). רבי אלעזר בן פדת היה בתחילה תלמידו המובהק (יבמות צ\"ו ע\"ב), ואח\"כ הפך תלמיד חבר (ירו', סנהדרין פ\"א ה\"א), ולבסוף ישב על כסאו של ר' יוחנן כראש מתיבתא (\"אגרת רב שרירא גאון\"). לר' יוחנן היו תלמידים רבים מאד, וביניהם: ר' אמי [שהיה ממלא מקומו אחרי ר' אלעזר, שנפטר באותה שנה שנפטר ר' יוחנן] (כתובות ס\"ב ע\"א), ר' אסי (שם), ר' חייא בר אבא (ברכות ל\"ח ע\"ב), ר' יוסי בר חנינא (סנהדרין ל' ע\"ב), ר' אבהו (כתובות נ\"ז ע\"א) ורבים אחרים שהיו ראשי הדור וראשי ישיבות אחריו. היה מבורך בכח גופני גדול (ב\"מ ס\"ב ע\"א), יופי נדיר (שם פ\"ד ע\"א) ובעושר (תענית כ\"א ע\"א רש\"י). היו לו יסורים של אהבה וכל עשרת בניו מתו עליו בחייו (ברכות ה' ע\"ב רש\"י). היה לו כח להחיות מתים ולאחר שהעניש בטעות את ר' כהנא, החיה אותו (ב\"ק קי\"ז ע\"א). היה גדול כל כך, עד שאמרו: \"רב ור' יוחנן, הלכה כרבי יוחנן\" (ביצה ד' ע\"א), וכן: \"שמואל ור' יוחנן, הלכה כרבי יוחנן\" (ב\"ק ק\"ד ע\"ב תד\"ה: ורבי יוחנן). יש \"ראשונים\" (ביניהם הרמב\"ם) שמייחסים לו את סידור ש\"ס הירושלמי. נפטר בשנת ד' ל\"ט (972) \"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 2048,"n": "ר' יוחנן אחוה דמר בריה דרבינא","l": "י","b": "אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (שבת צ\"ד ע\"א), שהקשה לרב נחמן בר יצחק.","cat": "sage"},{"i": 2049,"n": "ר' יוחנן אחוה דרב ספרא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (חגיגה פ\"א ה\"ו), שם מתיב על דברי ר' יוסי [חברו של ר' יונה].","cat": "sage"},{"i": 2050,"n": "יוחנן אחי ר' שמעון בן יהוצדק הכהן","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. אחיו של ר' שמעון בן יהוצדק (שהיה מרבותיו של רבי יוחנן) (שמחות פ\"ד הי\"א).","cat": "sage"},{"i": 2051,"n": "ר' יוחנן בן אלעאי","l": "י","b": "תנא בדור השלישי. תלמידו של רבי אליעזר. כשרבי אליעזר שבת בסוכתו של ר' יוחנן ברבי אלעאי, שאלו דיני סוכה, ור' אליעזר השתמט מלענות לו (סוכה כ\"ז ע\"ב).","cat": "sage"},{"i": 2052,"n": "ר' יוחנן בן אלעזר","l": "י","b": "מובא בבבלי (פסחים נ\"א ע\"א), ונראה שצ\"ל: ר' יונתן (כמו בשבת מ\"ט ע\"ב).","cat": "sage"},{"i": 2053,"n": "ר' יוחנן בן ארזא","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. חברו של ר' יוסי בן נהוראי. על חילוקי דעות ביניהם הוסיף ר' יהושע בן לוי את הסבריו (ע\"ז נ\"ח ע\"א).","cat": "sage"},{"i": 2054,"n": "יוחנן בן בג בג","l": "י","b": "מובא בבבלי (קידושין י' ע\"ב). ע\"ע בן בג בג.","cat": "sage"},{"i": 2055,"n": "רבי יוחנן בן ברוקא","l": "י","b": "תנא בדור השלישי. תלמידו המובהק של רבי יהושע. חברו של רבי אלעזר חסמא - שניהם הלכו לקבל פני ר' יהושע בפקיעין, ולבקשת רבם מסרו לו תוכן דרשתו של ר' אלעזר בן עזריה (חגיגה ג' ע\"א). השאיר אחריו בן חכם ושמו ר' ישמעאל (ברכות נ\"ט ע\"א).","cat": "sage"},{"i": 2056,"n": "רבי יוחנן בן בתירא","l": "י","b": "מובא בבבלי (זבחים ס\"ג ע\"א), וב\"שיטה מקובצת\": \"ר' יהודה בן בתירא\", וכן במקום אחר (מנחות מ\"א ע\"ב), גיר' \"שיטה מקובצת\": \"ר' יונתן בן בתירא\".","cat": "sage"},{"i": 2057,"n": "ר' יוחנן בן גודגדא","l": "י","b": "תנא בדור השני. היה לוי, ושימש בבית המקדש כממונה על נעילת שערים. פעם רצה ר' יהושע בן חנניה לעזור לו, ואמר לו: \"חזור בני וכו'\" (ערכין י\"א ע\"ב). מובא במשנה (גיטין נ\"ה ע\"א) שהעיד ד' דברים: \"על חרשת וכו' על קטנה וכו'\". נהג בחסידות ובזהירות מופלגת (חגיגה י\"ח ע\"ב).","cat": "sage"},{"i": 2058,"n": "רבי יוחנן בן דהבאי","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מסר בשמו של רבי יהודה בן תימא (סנהדרין ד' ע\"ב). חלק עם רבי חנינא בן גמליאל (מנחות מ\"ב ע\"ב).","cat": "sage"},{"i": 2059,"n": "רבי יוחנן בן החורנית","l": "י","b": "תנא בדור הראשון. תלמידו של שמאי (יבמות ט\"ו ע\"ב). רבו של רבי אלעזר בר צדוק א' (שם). זקני בית שמאי וזקני בית הלל הלכו לבקרו בסוכתו (סוכה כ\"ח ע\"א).","cat": "sage"},{"i": 2060,"n": "ר' יוחנן בן החרבות","l": "י","b": "מובא בתוספתא (סוכה פ\"ב), והוא רבי יוחנן בן החורנית.","cat": "sage"},{"i": 2061,"n": "רבי יוחנן בן המשולם","l": "י","b": "תנא בדור הרביעי - החמישי. מובא בבבלי: \"העיד ר' יוסי בן המשולם, משום ר' יוחנן אחיו, שאמר משום רבי אלעזר חסמא\" (גיטין ס\"ב ע\"א).","cat": "sage"},{"i": 2062,"n": "רבן יוחנן בן זכאי","l": "י","b": "תנא בדור הראשון. מגדולי התנאים. היחיד מבין כל חכמי ישראל שזכה בתואר \"רבן\", אף שלא היה ממשפחת הנשיאים. אחרון שקיבל מן \"הזוגות\" (אבות פ\"ב מ\"ח). מתלמידיו החשובים של הלל הזקן, שאמר עליו: \"שהוא אב לחכמה ואב לדורות\" (ירו', נדרים ספ\"ה). חי מאה ועשרים שנה \"ארבעים שנה עסק בפרקמטיא, ארבעים שנה למד, ארבעים שנה לימד\" (ר\"ה ל\"א ע\"ב). כבר 04 שנה לפני החורבן היה מראשי הדור (יומא ל\"ט ע\"ב). אחרי החורבן שימש נשיא ישראל שנה או שנתיים (שבת נ\"ד ע\"ב תד\"ה: היה). זכה לראות 4 נשיאים בחייו: הלל, שמעון, ר\"ג הזקן ורשב\"ג הנהרג. היתה לו ישיבה גדולה בברור חיל (סנהדרין ל\"ב ע\"ב). בחירי תלמידיו היו חמישה: רבי אליעזר בן הורקנוס, רבי יהושע בן חנניה, רבי יוסי הכהן, רבי שמעון בן נתנאל ורבי אלעזר בן ערך (אבות שם). כשדרש לפני קהל, נאלץ לדרוש בצילו של היכל (פסחים כ\"ו ע\"א פרש\"י: \"שאין לך בית המדרש מחזיקן\" את המוני השומעים). היה עד לחורבן הבית: ערב החורבן הוציאוהו תלמידיו מירושלים הנצורה, והוא התייצב לפני אספסינוס הרומי וביקש ממנו שלוש בקשות: יבנה וחכמיה, שלשלת הנשיאות של רבן גמליאל ורופא שירפא את רבי צדוק (שצם 04 שנה שבית המקדש לא יחרב) (גיטין נ\"ו ע\"ב). אחר החורבן תיקן תקנות \"זכר למקדש\" (ר\"ה ל' ע\"א). \"מימיו לא שח שיחת חולין, ולא הלך ד' אמות בלא תורה ובלא תפילין\" (סוכה כ\"ח ע\"א). הבין שיחת מלאכי השרת ושיחת שדים ושיחת דקלים (שם). לפני פטירתו קראו לו תלמידיו: \"נר ישראל, עמוד הימיני, פטיש חזק\", והוא אמר להם: \"הכינו כסא לחזקיה מלך יהודה שבא אלי ללוותי\" (ברכות כ\"ח ע\"ב). \"סה\"ד\" כתב בשם \"צמח דוד\" שנולד ג' תשי\"ג (35) ונפטר תתקל\"ג (371) ועליו אמרו: \"משמת רבי יוחנן בן זכאי בטל זיו החכמה\" (סוף סוטה).","cat": "sage"},{"i": 2063,"n": "רבי יוחנן בן יהושע בן חמיו של רבי עקיבא","l": "י","b": "תנא בדור השלישי. גיסו של רבי עקיבא. מובא במשנה, שאמר כדברי בן עזאי (ידים פ\"ג מ\"ה).","cat": "sage"},{"i": 2064,"n": "רבי יוחנן בן יוסף","l": "י","b": "מובא בבבלי (חולין קמ\"ט ע\"א). לפי גירסת \"סה\"ד\" הוא רבי יונתן בר יוסף (והוא רבי יונתן התנא).","cat": "sage"},{"i": 2065,"n": "ר' יוחנן בן לוי","l": "י","b": "מובא בב\"ר (פי\"ג - ט\"ז), ואולי צ\"ל: ר' יהושע בן לוי.","cat": "sage"},{"i": 2066,"n": "ר' יוחנן בן מתיא","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. חי בזמנו של רבן שמעון בן גמליאל (שחי בדור הרביעי) או לפניו. מסופר שאמר לבנו: \"צא ושכור לנו פועלים וכו'\" (ב\"מ פ\"ג ע\"א).","cat": "sage"},{"i": 2067,"n": "ר' יוחנן בן נורי","l": "י","b": "תנא בדור השלישי, מושבו היה בנגנינר (ירו', כלאים פ\"ד ה\"ב). מסר משום רבי אליעזר (קידושין ל\"ט ע\"א). חברו המובהק של רבי עקיבא (ערכין ט\"ז ע\"ב). דיבר לר' יהושע כחבר: \"יהושע, אין שומעין לך\" (עירובין מ\"א ע\"א). ר' יוסי הגלילי מסר בשמו (מנחות ל\"ח ע\"ב). ר' יהושע בן קרחה הלך אצלו (ירו', כלאים שם). היה חכם מופלג וידע לשער כמה טיפות יש בים (ספרי דברים ט\"ז). היה עני מרוד ולא היה לו פת לאכול (ספרי שם). ואמרו: \"הרואה ר' יוחנן בן נורי בחלום, צפה ליראת חטא\" (אדר\"נ ספ\"מ).","cat": "sage"},{"i": 2068,"n": "ר' יוחנן בן ניזוף","l": "י","b": "מובא בתוספתא (שבת רפ\"ג), והוא ר' יוחנן הנזיף.","cat": "sage"},{"i": 2069,"n": "ר' יוחנן בן פדיה","l": "י","b": "מובא ב\"ילקוט תהלים\" (רמז תשץ), ואולי צ\"ל: ר' יוחנן בר מריה כמו במקום אחר (ב\"ר פי\"ג - ה').","cat": "sage"},{"i": 2070,"n": "ר' יוחנן בן פזי","l": "י","b": "מובא בפסיקתא רבתי (פ' פרה ס\"ו).","cat": "sage"},{"i": 2071,"n": "ר' יוחנן בן קצרתה","l": "י","b": "מובא בשהש\"ר (פ\"ב - ט'), ונראה שצ\"ל: ר' יצחק בן קצרתה (ירו', ר\"ה פ\"א ה\"א).","cat": "sage"},{"i": 2072,"n": "ר' יוחנן בן שאול","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. חלק עם ר' יוסי בן שאול (שבת קכ\"ה ע\"ב). ר' יוסי בר שאול (שהיה תלמידו של רבי), אולי הוא אחיו. ר' לוי מסר בשמו (ב\"ר צ\"ח - א').","cat": "sage"},{"i": 2073,"n": "רבי יוחנן בן תורתא","l": "י","b": "תנא בדור השלישי. חברו של רבי עקיבא. כשדרש רבי עקיבא על בר כוכבא \"דרך כוכב מיעקב\" שהוא מלך המשיח, אמר לו רבי יוחנן בן תורתא: \"עקיבא, יעלו עשבים בלחייך ועדיין בן דוד לא יבוא\" (ירו', תענית פ\"ד ה\"ה). ואולי עליו מסופר (פסיקתא רבתי פ' פרה ב') שישראל מכר פרתו לעכו\"ם, ובשבת לא רצתה הפרה לחרוש, ובא היהודי ולחש באזני הפרה: שנמכרה לעכו\"ם וחייבת לחרוש בשבת, ואזי התחילה לחרוש בשבת. ודן העכו\"ם ק\"ו בעצמו: \"ומה פרה כך, אדם על אחד כמה וכמה\". והתגייר ולמד תורה, וקראו לו: יוחנן בן תורתא. יש גורסים: רב הונא בר תורתא.","cat": "sage"},{"i": 2074,"n": "רבי יוחנן בנו של ר' יהושע בן קרחה","l": "י","b": "תנא בדור החמישי. בן בנו של רבי עקיבא (לשיטת רש\"י שבועות ו' ע\"א). מובא בספרא (ריש אחרי).","cat": "sage"},{"i": 2075,"n": "ר' יוחנן בנו של ר' יוסי בן קיסמא","l": "י","b": "מובא במדרש תהלים (פק\"י - ד').","cat": "sage"},{"i": 2076,"n": "ר' יוחנן בר חנינא","l": "י","b": "מובא בבבלי (סנהדרין ל\"ח ע\"ב). \"דק\"ס\" גורס: ר' חמא או ר' אחא בר חנינא.","cat": "sage"},{"i": 2077,"n": "ר' יוחנן בר יאשיה","l": "י","b": "מובא במכילתא (משפטים פט\"ז). \"ילקוט\" גורס: ר' אחי בר יאשיה.","cat": "sage"},{"i": 2078,"n": "ר' יוחנן בר יודן דמן גלילא","l": "י","b": "מובא בתנחומא (הישן פ' אחרי). יתכן שיש שיבוש בשם.","cat": "sage"},{"i": 2079,"n": "ר' יוחנן בר יישוע","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. \"אמר רבי מתנייה סלקית לסחורה [עליתי למקום ששמו סחורה] ושמעית ר' יוחנן ור' ישמעאל בני יישוע\" (ירו', יבמות פ\"ז ה\"ו).","cat": "sage"},{"i": 2080,"n": "ר' יוחנן בר מדייא","l": "י","b": "מובא בירושלמי (פסחים פ\"ז הי\"ב), והוא ר' יוחנן בר מריא.","cat": "sage"},{"i": 2081,"n": "ר' יוחנן בר מולדא","l": "י","b": "כן הגירסא בכמה דפוסים ישנים, והנכון שצ\"ל: ר' חנן בר מולדא.","cat": "sage"},{"i": 2082,"n": "ר' יוחנן בר מרי","l": "י","b": "מובא בירושלמי (תרומות רפי\"א), והוא ר' יוחנן בר מריא.","cat": "sage"},{"i": 2083,"n": "ר' יוחנן בר מריא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של ר' פנחס (ירו', פסחים פ\"ז הי\"ב). מסר בשם ר' יוחנן (ירו', פאה פ\"א ה\"א). שמו נשתבש בכמה אופנים: מרייא, מדייא, מרי, מרייה. היה בקי בחשבון העיבור (ירו', ע\"ז פ\"א ה\"א).","cat": "sage"},{"i": 2084,"n": "ר' יוחנן בר מרייא","l": "י","b": "מובא בירושלמי (פסחים פ\"ה ה\"ו), והוא ר' יוחנן בר מריא.","cat": "sage"},{"i": 2085,"n": "ר' יוחנן בר מרייה","l": "י","b": "מובא בירושלמי (שבת פ\"ג ה\"א), והוא ר' יוחנן בר מריא.","cat": "sage"},{"i": 2086,"n": "ר' יוחנן בר נחמן","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. ר' יהודה הלוי בר שלום מסר בשמו (תנחומא וירא ח').","cat": "sage"},{"i": 2087,"n": "ר' יוחנן בר סימון","l": "י","b": "מובא ב\"ילקוט\" (שהש\"ר רמז תתקפ\"ב), ואולי צ\"ל: ר' יהודה בר' סימון כמו בשהש\"ר (פ\"א - ז').","cat": "sage"},{"i": 2088,"n": "ר' יוחנן בר פפא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. ר' עזריה אמר בשמו (ב\"ר פמ\"ה - ד'). יש סבורים שצ\"ל: ר' חנינא בר פפא.","cat": "sage"},{"i": 2089,"n": "ר' יוחנן בר שאונה","l": "י","b": "בויק\"ר (פ\"ה - ב') מביא ר' לוי בשמו. \"סה\"ד\" סבור, שר' יוחנן בר שאונה הוא ר' חנא בר שאונה.","cat": "sage"},{"i": 2090,"n": "ר' יוחנן בר שילא","l": "י","b": "מובא בירושלמי (שבת פ\"ד ה\"א).","cat": "sage"},{"i": 2091,"n": "ר' יוחנן דבית גוברין","l": "י","b": "מובא בתנחומא (תולדות כ\"ג), ונראה שצריך אולי לגרוס ר' יונתן דבית גוברין.","cat": "sage"},{"i": 2092,"n": "ר' יוחנן דיפו","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מובא בבמד\"ר (פ\"ב - כ\"ד), שפנה בשאלה לר' פנחס בר חמא. והגירסא במקום אחר (ויק\"ר פ\"כ - י'): ר' יודן דיפו.","cat": "sage"},{"i": 2093,"n": "ר' יוחנן דצפרין","l": "י","b": "מובא מאמרו בשהש\"ר (פ\"ח - פי\"א - ג'): \"מי שהוא טפש אומר: 'מי הוא יכל ללמוד כל התורה' וכו' והחכם אומר: 'הריני לומד ג' הלכות היום ב' למחר' וכו'\". יש סבורים שצריך לגרוס ר' חנוך דצפורין.","cat": "sage"},{"i": 2094,"n": "ר' יוחנן דקציון","l": "י","b": "מובא בירושלמי (ביצה פ\"ה ה\"ה), והוא ר' יוחנן דקרציין.","cat": "sage"},{"i": 2095,"n": "ר' יוחנן דקרציין","l": "י","b": "מובא בירושלמי (ברכות פ\"ח ה\"ו).","cat": "sage"},{"i": 2096,"n": "רבי יוחנן החורני","l": "י","b": "מובא בבבלי (יבמות ט\"ו ע\"ב), והוא רבי יוחנן בן החורנית.","cat": "sage"},{"i": 2097,"n": "יוחנן הכהן הסופר","l": "י","b": "מובא בירושלמי (מע\"ש פ\"ה ה\"ד), והוא יוחנן סופר.","cat": "sage"},{"i": 2098,"n": "ר' יוחנן המכיתי","l": "י","b": "תנא בדור החמישי. רבו דרבו של רבי יוחנן. מובא בבבלי: \"רבי יוחנן משום ר' שמעון המחוזי, משום ר' יוחנן המכיתי\" (סוכה מ\"ח ע\"ב).","cat": "sage"},{"i": 2099,"n": "ר' יוחנן הנזוף","l": "י","b": "תנא בדור השלישי. מובא בבבלי: \"א\"ר יוסי: 'מעשה באבא חלפתא שהלך אצל ר\"ג בריבי לטבריה, ומצאו שהיה יושב על שולחנו של יוחנן הנזוף'\" (שבת קט\"ו ע\"א).","cat": "sage"},{"i": 2100,"n": "ר' יוחנן הסנדלר","l": "י","b": "תנא בדור הרביעי. עיר מולדתו היתה אלכסנדריה של מצרים (ירו', חגיגה פ\"ג ה\"ח). וזה אולי הכינוי הסנדלר, למרות שמקובל שהכינוי הוא על שם שהיה סנדלר. וה\"יוחסין\" כתב שהיה \"נוקב מרגליות\", ותרגום: סנדלרון (לכן נקרא הסנדלר). תלמידו המובהק של רבי עקיבא (ברכות כ\"ב ע\"א). אמר לרבי מאיר: \"שימשתי את ר\"ע עומדות, מה שלא שימשת ישובות\" [כלומר שימשתי את ר\"ע הרבה ממך] (ירו', שם). כשישב רבי עקיבא בבית הסוהר בזמן גזירת שמד ואיסור לימוד תורה, והיו צריכים לשאול ממנו דין, עשה עצמו ר' יוחנן הסנדלר כרוכל המכריז על סחורתו ושאלו ור\"ע ענה לו ברמיזות (ירו', יבמות פי\"ב ה\"ה). אחרי חורבן ביתר, כשבוטלו גזירות אדריינוס, מסופר \"מעשה שנכנסו שבעה זקנים לעבר את השנה בבקעת רימון, ומי היו? ר\"מ ור' יהודה ור' יוסי ור\"ש ור' נחמיה ור\"א בן יעקב ור' יוחנן הסנדלר\" (ירו', חגיגה שם). (\"סה\"ד\" כתב: \"אני הכותב יחיאל בידי מגילת יוחסין כתובה דאבי אמי מזרע דר' יוחנן הסנדלר, וסדר שלשלת היוחסין ממנו, רש\"י מאור הגולה, והגאון מהרש\"ל\").","cat": "sage"},{"i": 2101,"n": "יוחנן חקוקאה","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. בא לפני רבי לשאול דין בענין פסח (פסחים י\"ג ע\"א). תוספות מפרש (שם ג' ע\"ב) שהיה מעיר חקוקה. ור\"ח פירש (שם) שהיה סופר.","cat": "sage"},{"i": 2102,"n": "רבי יוחנן מלחשך","l": "י","b": "מובא בבבלי (עירובין צ\"א ע\"א). לגיר' תוספות (שם) הוא רבי יוחנן (בר פלוגתיה דרבי שמעון בן לקיש).","cat": "sage"},{"i": 2103,"n": "יוחנן סופר","l": "י","b": "סופרו של רבן גמליאל דיבנה (דור שלישי לתנאים). חי בזמן הבית (סנהדרין י\"א ע\"ב).","cat": "sage"},{"i": 2104,"n": "ר' יוחנן ספרא דגופתא","l": "י","b": "סופר ארץ ישראלי מהעיר גופתא, בדור הרביעי לאמוראי ארץ ישראל. מובא בירושלמי (סוכה פ\"ב ה\"ה), שרב הונא הלך לקדש את החודש, והיה צמא ונכנס לסוכתו לשתות.","cat": "sage"},{"i": 2105,"n": "ר' יוחנן ענתנייתא","l": "י","b": "מובא בירושלמי (ברכות פ\"ה ה\"א). מאמרו: \"היגע בתלמודו בצנעה לא במהרה הוא משכח\" (שם).","cat": "sage"},{"i": 2106,"n": "יוחנן שר הבירה","l": "י","b": "מובא במדרש תהלים (הישן פ\"ג), ואולי צ\"ל: יונתן שר הבירה.","cat": "sage"},{"i": 2107,"n": "ר' יולימנא בר עבדי","l": "י","b": "מובא בפס' רבתי (רפ\"ז), שאמר בשם ר' יצחק. יש גורסים ר' לוליאני בר טברי.","cat": "sage"},{"i": 2108,"n": "רבי יונה","l": "י","b": "מגדולי אמוראי ארץ ישראל בדור הרביעי - החמישי. קיבל תורה מרבי יוחנן (בכורות ל' ע\"א). רבותיו המובהקים היו: רבי אלעאי (ירו', תרומות פ\"ב ה\"ד), רבי זירא (בכורות שם) וכן למד מר' ירמיה (ירו', מגילה פ\"ד ה\"ה). חברו המובהק היה רבי יוסי, ושניהם עמדו בראש ישיבת טבריה, ושניהם יצאו לקדם את המלך מאנטיוכא (ירו', ברכות פ\"ה ה\"א). בזמן הרדיפות הקשות התירו שניהם ליהודי הגליל לאפות לחם בשבת לצבאו של אורסיקינוס (ירו', שביעית פ\"ד ה\"ב). ר' יונה כונה: \"תקיפי דארעא דישראל\" (תענית כ\"ג ע\"ב). הביא גשם בתפילתו (שם). פעם נפלה אש בשכונתו, ופרס את טליתו והאש ברחה (ירו', נדרים פ\"ד ה\"ט). נפטר לפני ר' יוסי חברו (ירו', מע\"ש פ\"ד ה\"ו). זכה לבן גדול בתורה, מגדולי האמוראים בארץ ישראל בדור החמישי - ר' מנא (ירו', דמאי רפ\"ד).","cat": "sage"},{"i": 2109,"n": "רבי יונה אבוה דרבי מני","l": "י","b": "מובא בבבלי (תענית כ\"ג ע\"ב), והוא רבי יונה, חברו דרבי יוסי, מגדולי אמוראי א\"י בדור הרביעי.","cat": "sage"},{"i": 2110,"n": "ר' יונה אביו דר' ישמעאל","l": "י","b": "מובא בירושלמי (סנהדרין ריש חלק), ונראה שיש ט\"ס בשם.","cat": "sage"},{"i": 2111,"n": "רבי יונה בוצירוי","l": "י","b": "מובא בירושלמי (כלאים פ\"ט ה\"א), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2112,"n": "ר' יונה בוצריא","l": "י","b": "מובא בירושלמי (יומא פ\"ה ה\"א), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2113,"n": "יונה בוצריה","l": "י","b": "מובא בירושלמי (מו\"ק פ\"ב ה\"ג), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2114,"n": "רבי יונה בוצריי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' מנא (ירו', כלאים רפ\"ט). שאל גם מר' הונא ב' (ירו', מו\"ק פ\"ב ה\"ג). שמו שובש בכמה אופנים: בוצירוי, בוצרייה, בוצרייא, בוצריא, מבוצרצא, בוצריה.","cat": "sage"},{"i": 2115,"n": "רבי יונה בוצרייא","l": "י","b": "מובא בירושלמי (שביעית פ\"ב ה\"ז), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2116,"n": "רבי יונה בוצרייה","l": "י","b": "מובא בירושלמי (כלאים פ\"ח ה\"ג), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2117,"n": "ר' יונה בן צדיה","l": "י","b": "מובא בפדר\"כ, והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2118,"n": "ר' יונה בן צרויה","l": "י","b": "מובא בירושלמי (שבת פ\"ה ה\"א), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2119,"n": "ר' יונה בר אבא","l": "י","b": "מובא בויק\"ר (ספל\"ה). נראה שאולי יש ט\"ס בשם.","cat": "sage"},{"i": 2120,"n": "רבי יונה בר תחליפא","l": "י","b": "אמורא בבלי בדור הרביעי - חמישי. מובא בבבלי: \"רבא הוה בדיק להו גירא [חץ] לרבי יונה בר תחליפא, ושחט בה עופא וכו'\" (חולין ל' ע\"ב).","cat": "sage"},{"i": 2121,"n": "רבי יונה דכפר אימי","l": "י","b": "מובא בירושלמי (נדרים פ\"ד ה\"ט). אותו מעשה מובא בשם \"ר' יודן דכפר אימי\" (ירו', שבת פט\"ז ה\"ז).","cat": "sage"},{"i": 2122,"n": "ר' יונה חמוה דר' אמי","l": "י","b": "מובא בירושלמי (גיטין פ\"ב ה\"א).","cat": "sage"},{"i": 2123,"n": "ר' יונה מבוצרצא","l": "י","b": "מובא בפסיקתא רבתי (פ' תשא ס\"ח), והוא ר' יונה בוצריי.","cat": "sage"},{"i": 2124,"n": "רבי יונתן","l": "י","b": "תנא בדור הרביעי. נראה שסתם ר' יונתן בר יוסף ור' יונתן בי ר' יוסי חד הם. היה תלמידו של רבי עקיבא (ירו', מעשרות פ\"ה ה\"ב). חברו של ר' יאשיה, ושניהם היו תלמידיו המובהקים של ר' ישמעאל (מנחות נ\"ז ע\"ב). מסופר: \"א\"ר יונתן: 'נמתי לו לבן עזאי וכו' נם לי 'ומה ישמעאל אומר בדבר הזה וכו' ובלשון הזה אמר לי [בן עזאי] חבל על שלא שמשתי את ר' ישמעאל'\" (חולין ע' ע\"ב).","cat": "sage"},{"i": 2125,"n": "ר' יונתן","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. היה מבבל ועלה לארץ ישראל (חולין מ\"ה ע\"א רש\"י). מבעלי האגדה. תלמידו של ר' שמעון בר יוסי בר לקוניא ושל רבי חייא (ירו', עירובין פ\"ג ה\"ד). חברם של ר' חנינא ושל ר' יהושע בן לוי (ירו', מע\"ש פ\"ג ה\"ג). רבו המובהק של ר' שמואל בר נחמני (פסחים כ\"ד ע\"א). רבי יוחנן אמר על ר' יונתן: \"ידעין חברין וכו'\" (חולין מ\"ה ע\"א). מקומו היה כנראה בטבחה (קה\"ר פ\"ג - י\"ד).","cat": "sage"},{"i": 2126,"n": "ר' יונתן איש הבירה","l": "י","b": "מובא במדרש תהלים (פ\"ג - ג'), ונראה שהוא ר' יונתן רבו של ר' שמואל בר נחמני.","cat": "sage"},{"i": 2127,"n": "רבי יונתן בי רבי יוסי","l": "י","b": "מובא בירושלמי (מעשרות פ\"ה ה\"ב), והוא ר' יונתן התנא.","cat": "sage"},{"i": 2128,"n": "ר' יונתן בן אבטולמוס","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (נדה י\"ט ע\"א). במקום אחר (זבחים מ\"ט ע\"ב) הגירסא: ר' נתן בן אבטולמוס.","cat": "sage"},{"i": 2129,"n": "ר' יונתן בן אלעזר","l": "י","b": "מובא בתנחומא (בחוקותי - ד'), ונראה שהוא ר' יונתן רבו של ר' שמואל בר נחמני.","cat": "sage"},{"i": 2130,"n": "יונתן בן אריה","l": "י","b": "מובא ב\"ילקוט\" (תהלים רמז תתנט), ונראה שיש ט\"ס בשם.","cat": "sage"},{"i": 2131,"n": "ר' יונתן בן בתירא","l": "י","b": "מובא בבבלי (מנחות מ\"א ע\"ב), לפי גירסת \"שיטה מקובצת\". ולפנינו: יוחנן בן בתירא.","cat": "sage"},{"i": 2132,"n": "ר' יונתן בן הרכינס","l": "י","b": "תנא מתלמידי שמאי. האריך ימים עד דור השלישי. אחיו של ר' דוסא בן הרכינס, שקראו בכור שטן (פרש\"י: חריף ועומד על שמועתו). ור' דוסה הזהיר את ר' יהושע, רבי עקיבא ורבי אלעזר בן עזריה, שלא יקפחם בהלכות, לפי שיש עמו ג' מאות תשובות וכו' (יבמות ט\"ז ע\"א). ובירושלמי (יבמות פ\"א ה\"ו) ומסופר שמרוב חריפותו לא הבינו את הסבריו.","cat": "sage"},{"i": 2133,"n": "יונתן בן הרסא","l": "י","b": "מובא בתוספתא (כלים), והוא ר' יונתן בן חרשא איש גנוסר.","cat": "sage"},{"i": 2134,"n": "ר' יונתן בן חגי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מובא בקה\"ר (פ\"ט - י\"ב), שמסר יחד עם ר' עזריה בשם ר' יצחק בר מריון.","cat": "sage"},{"i": 2135,"n": "ר' יונתן בן חלי","l": "י","b": "מובא בירושלמי (סנהדרין פ\"ו ה\"ה).","cat": "sage"},{"i": 2136,"n": "יונתן בן חרשא איש גינוסר","l": "י","b": "תנא בדור השלישי - הרביעי. מובא בירושלמי (מעשרות פ\"א ה\"ב). ששאל את רבן גמליאל וחכמים ביבנה.","cat": "sage"},{"i": 2137,"n": "רבי יונתן בן יוסי","l": "י","b": "מובא בירושלמי (כלאים פ\"ב ה\"ו), והוא ר' יונתן התנא.","cat": "sage"},{"i": 2138,"n": "ר' יונתן בן יוסי בן לקוניא","l": "י","b": "מובא בבבלי (שבועות י\"ח ע\"א). יתכן שיש שיבוש בשם.","cat": "sage"},{"i": 2139,"n": "ר' יונתן בן יוסף","l": "י","b": "מובא בבבלי (יומא פ\"ה ע\"ב), והוא ר' יונתן התנא.","cat": "sage"},{"i": 2140,"n": "יונתן בן משולם","l": "י","b": "תנא בדור הרביעי. רבי אלעזר בן יעקב (תלמידו של ר\"ע) שאל ממנו, והוא השיב לו משמו של רבי עקיבא (ילקוט ח\"א, רמז תשפה).","cat": "sage"},{"i": 2141,"n": "יונתן בן עוזיאל","l": "י","b": "תנא בדור הראשון. הגדול שבתלמידי הלל (סוכה כ\"ח ע\"א). \"אמרו עליו על יונתן בן עוזיאל בשעה שיושב ועוסק בתורה כל עוף שפורח עליו מיד נשרף\" (פרש\"י שם: \"שהיו מלאכי השרת מתקבצין סביביו לשמוע דברי תורה מפיו\") וכשתרגם הנביאים \"יצתה בת קול ואמרה לו דייך\" (מגילה ג' ע\"א) שמאי (חברו של הלל) בא ליונתן בן עוזיאל \"במקלו ובתרמילו\" לברר ענין, וא\"ל שמאי: \"אם אתה יכול וכו'\", אמר (שמאי) \"הטיח עלי בן עוזיאל\" (ב\"ב קל\"ג ע\"ב).","cat": "sage"},{"i": 2142,"n": "רבי יונתן בן עכינאי","l": "י","b": "אמורא ארץ ישראל בדור הראשון. חברו של ר' חנינא בר חמא (שבת מ\"ט ע\"א).","cat": "sage"},{"i": 2143,"n": "רבי יונתן בן עכמאי","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יוחנן (סנהדרין י\"ד ע\"א). ר' אבהו מסר ברייתא ששנה לו ר' יונתן בן עכמאי ואמר לר\"ז: \"אדם גדול היה ובקי במשנתו היה\" (ירו', תרומות פי\"א ה\"ה).","cat": "sage"},{"i": 2144,"n": "ר' יונתן בן עמרם","l": "י","b": "תנא בדור החמישי. תלמידו של רבי. לא רצה ליהנות ולהתפרנס מכבוד תורה אף בשנת בצורת (ב\"ב ח' ע\"א). ר' ינאי שאל ממנו (ע\"ז ל\"ו ע\"ב רש\"י).","cat": "sage"},{"i": 2145,"n": "ר' יונתן בן עסמיי","l": "י","b": "תנא בדור החמישי. תלמידו של רבי שמעון בן יוחאי. חברו של ר' יהודה בן גרים (מו\"ק ט' ע\"א). רשב\"י שלח את בנו לקבל ברכה מהם ואמר עליהם: \"בני אדם הללו אנשים של צורה הם\" (שם).","cat": "sage"},{"i": 2146,"n": "ר' יונתן בן שאול","l": "י","b": "מובא בברייתא (סנהדרין נ\"ז ע\"א), ויש סבורים שצ\"ל: ר' יוחנן בן שאול.","cat": "sage"},{"i": 2147,"n": "ר' יונתן בר יוסי","l": "י","b": "הוא ר' יונתן בר יוסף והוא ר' יונתן התנא.","cat": "sage"},{"i": 2148,"n": "ר' יונתן בר יצחק בר אחא","l": "י","b": "מובא בירושלמי (פאה רפ\"ה).","cat": "sage"},{"i": 2149,"n": "ר' יונתן דבית גוברין","l": "י","b": "אמורא ארץ ישראלי בדור השני. מבעלי האגדה. מסר בשם ר' יהושע בן לוי (שהש\"ר פ\"א - א'). ר' סימון מסר בשמו (ירו', יומא פ\"ז ה\"ג).","cat": "sage"},{"i": 2150,"n": "יונתן הקטיני","l": "י","b": "תנא בדור הרביעי. מובא בברייתא שחלק עם ר' נתן (עירובין צ\"ו ע\"א).","cat": "sage"},{"i": 2151,"n": "ר' יונתן ספרא דגיפתרא","l": "י","b": "מובא במסכת סופרים (פי\"ב ה\"ד), ואולי צ\"ל: ר' יוחנן ספרא דגופתא.","cat": "sage"},{"i": 2152,"n": "ר' יונתן קיפא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. אחיו מנחם בר מבסימא מסר בשם ר' אמי (ירו', סוף מעשרות).","cat": "sage"},{"i": 2153,"n": "יונתן שידא","l": "י","b": "מובא: \"א\"ר חנינא אמר לי יונתן שידא\" (יבמות קכ\"א ע\"א). ופרש\"י: \"שד היה או בקי בהן וגם אם נאמר שלא היה שד על כל פנים נראה שלא היה מן החכמים\".","cat": "sage"},{"i": 2154,"n": "ר' יונתן שר הבירה","l": "י","b": "מובא בב\"ר (פצ\"ה - ג'). ונראה שהוא ר' יונתן רבו דר' שמואל בר נחמני.","cat": "sage"},{"i": 2155,"n": "ר' יוסא סבא","l": "י","b": "מובא ב\"זוהר\" (תזריע ע\"ו) שדוסתאי סבא אמר משמו.","cat": "sage"},{"i": 2156,"n": "יוסה","l": "י","b": "הוא יוסי.","cat": "sage"},{"i": 2157,"n": "ר' יוסה בן ביביי","l": "י","b": "אמורא ארץ ישראלי שאין לקבוע את זמנו המדוייק. מובא בירושלמי (מגילה פ\"ד ה\"ט), שהיה שונה ברייתות.","cat": "sage"},{"i": 2158,"n": "ר' יוסה בר אביי","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. ר' יוחנן מסר משמו, הוא אבא יוסף בר אבא (חולין צ\"ז ע\"א).","cat": "sage"},{"i": 2159,"n": "יוסה בריה דר' יהושע בן לוי","l": "י","b": "מובא בירושלמי (תענית פ\"א ה\"ו), והוא רב יוסף בריה דר' יהושע בן לוי.","cat": "sage"},{"i": 2160,"n": "רבי יוסה גלילייא","l": "י","b": "מובא בירושלמי (שבת פ\"ג ה\"ז). והוא רבי יוסי גלילאה.","cat": "sage"},{"i": 2161,"n": "יוסה חפני","l": "י","b": "מובא בירושלמי (כתובות פי\"ב ה\"ג). והוא יוסף חפני.","cat": "sage"},{"i": 2162,"n": "ר' יוסטא","l": "י","b": "מובא בירושלמי (ב\"מ פ\"י ה\"ב), ונראה, שהוא וסטיני תלמידיו דר\"ל.","cat": "sage"},{"i": 2163,"n": "ר' יוסטא בר מתון (2)","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (זבחים צ\"ט ע\"א). ע\"ע ר' דוסתאי בר מתון.","cat": "sage"},{"i": 2164,"n": "ר' יוסטא בר שונה","l": "י","b": "מובא בירושלמי (עירובין פ\"א ה\"י), וצ\"ל: ר' יוסא בר שונם.","cat": "sage"},{"i": 2165,"n": "ר' יוסטא בר שונם","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של ר' מנא (ירו', תרומות פי\"א ה\"ד). מסר גם בשם ר' יהושע דסכנין (תנחומא ויצא - ו').","cat": "sage"},{"i": 2166,"n": "ר' יוסטאי בר מתון","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של ר' יוחנן (זבחים צ\"ט ע\"א).","cat": "sage"},{"i": 2167,"n": "ר' יוסטי בר סימון","l": "י","b": "מובא בירושלמי (עירובין פ\"ו ה\"ד), שאמר משמו של ר' בייתוס.","cat": "sage"},{"i": 2168,"n": "יוסטי חברא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם רבי ברכיה (ב\"ר רפ\"ו).","cat": "sage"},{"i": 2169,"n": "ר' יוסטיני","l": "י","b": "מובא בירושלמי (ב\"ב פ\"ח ה\"ה), והוא וסטיני תלמידו דר\"ל.","cat": "sage"},{"i": 2170,"n": "יוסטני","l": "י","b": "מובא בבבלי (ב\"מ קי\"ז ע\"א). כן גיר' \"דק\"ס\". ולפנינו: וסטיני.","cat": "sage"},{"i": 2171,"n": "יוסי","l": "י","b": "ע\"ע רב יוסף.","cat": "sage"},{"i": 2172,"n": "רב יוסי","l": "י","b": "מובא בבבלי (עירובין י\"ח ע\"ב), והוא רב יוסף מראשי רבנן סבוראי.","cat": "sage"},{"i": 2173,"n": "רבי יוסי (2)","l": "י","b": "מגדולי אמוראי ארץ ישראל בדור הרביעי - החמישי. חברו של ר' יונה, ושניהם היו תלמידים של ר' אלעאי (ירו', תרומות פ\"ב ה\"ד), ר' זירא (ירו', כלאים פ\"א ה\"א) ור' ירמיה (ירו', ברכות פ\"א ה\"ב). לאחר פטירת ר' אמי ור' אסי הם היו גדולי הדור בארץ ישראל, בימי גזירות הם התירו לאפות לחם בשבת בשביל ראש החיל וחיילותיו (ירו', סנהדרין פ\"ג ה\"ה), ושניהם באו לקבל פני המלך באנטוכיא (ירו', ברכות פ\"א ה\"א). כשמת בנו של ר' יוסי צם ר' יונה (ירו', נדרים פ\"ח ה\"א). ר' יונה נפטר לפני ר' יוסי (ירו', מעשרות פ\"ד ה\"ו). בין תלמידיו הרבים היה בנו של ר' יונה ר' מנא, שהיה ראש הדור החמישי בא\"י (ירו', ברכות פ\"א ה\"ב). כשנפטר ר' יוסי נטמאו לו תלמידיו הכהנים (שם פ\"ג ה\"א).","cat": "sage"},{"i": 2174,"n": "ר' יוסי איש צייתור","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. ר' ברכיה כינהו חסיד, וסיפר כיצד הבריח רוח שרצתה להזיק (תנחומא פ' קדושים - ט').","cat": "sage"},{"i": 2175,"n": "ר' יוסי אלעאי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. רבי פנחס מסר משמו (ירו', מגילה פ\"א הי\"ב).","cat": "sage"},{"i": 2176,"n": "ר' יוסי אשיין","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי שמעון בן לקיש (ירו', סוכה פ\"ד ה\"ו).","cat": "sage"},{"i": 2177,"n": "ר' יוסי בן אלישע","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת קל\"ט ע\"א).","cat": "sage"},{"i": 2178,"n": "יוסי בן גילאי","l": "י","b": "תנא בדור השלישי. \"מעשה ושאלו את רבן גמליאל א\"ל: צאו ושאלו את יוסי בן גילאי שהוא בר ובקי בהלכות כלאי הכרם\" (תוספתא כלאים פ\"ג).","cat": "sage"},{"i": 2179,"n": "רבי יוסי בן דולגאי","l": "י","b": "מובא בבבלי (יומא ל\"ט ע\"ב), והוא רבי אלעזר בן דגלאי.","cat": "sage"},{"i": 2180,"n": "רבי יוסי בן דורמסקית","l": "י","b": "תנא בדור השלישי. תלמידו המובהק של רבי אליעזר (חגיגה ג' ע\"ב). כשר' אליעזר כעס עליו התעוור ר' יוסי, ולאחר שדעתו של ר\"א התיישבה עליו ריפא אותו ושב לראות (שם). מסר גם משום רבי יוסי הגלילי (קידושין ל\"ט ע\"א). אמר לר' יהודה [תלמידו של ר\"ע]: למה אתה מעוות עלינו את הכתובים (ספרי דברים פיסקא א'). ר' אלעזר בר יוסי מסר משמו (קידושין שם).","cat": "sage"},{"i": 2181,"n": "ר' יוסי בן החוטף אפרתי","l": "י","b": "תנא בדור הרביעי. תלמידו של ר' ישמעאל. חלק עם רבי מאיר (כלאים פ\"ג מ\"ז).","cat": "sage"},{"i": 2182,"n": "רבי יוסי בן המשולם","l": "י","b": "תנא בדור החמישי. הוא ור' שמעון בן מנסיא מכונים \"עדה קדושה\" (ירו', מע\"ש פ\"ב ה\"ד), משום שהיו משלשין את היום שליש לתורה, שליש לתפילה, שליש למלאכה: ויש אומרים שהיו יגעין בתורה בימות החורף ובמלאכה בימות הקיץ (קה\"ר פ\"ט - ט'). מסר בשם אחיו ר' יוחנן, שאמר משום ר' אלעזר בג חסמא (גיטין ס\"ב ע\"א). חלק עם חנינא בן חכינאי ורבי (מנחות ס\"ב ע\"א).","cat": "sage"},{"i": 2183,"n": "ר' יוסי בן זמרא","l": "י","b": "מאחרוני התנאים. מגדולי הדור בדורו של רבי. בנו של רבי התחתן עם בתו (כתובות ס\"ב ע\"ב). שמו נזכר בברייתא (מכילתא ויהי בשלח פ' ויסע). האריך ימים וחי בזמנו של ר' יהודה נשיאה א' (יומא ע\"ח ע\"א). בשמו מסרו ר' יוחנן (שבת ק\"ה ע\"א) ור' אלעזר (ברכות ל\"א ע\"ב).","cat": "sage"},{"i": 2184,"n": "ר' יוסי בן זעירא דכפר ראמין","l": "י","b": "מובא ב\"זוהר\" (שמיני ל\"ט ע\"ב).","cat": "sage"},{"i": 2185,"n": "יוסי בן חוני","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא במשנה (זבחים ב' ע\"א).","cat": "sage"},{"i": 2186,"n": "רבי יוסי בן חלפתא","l": "י","b": "תנא בדור הרביעי, והוא רבי יוסי סתם במשנה ובברייתא (זבחים נ\"ח סע\"ב רש\"י). מוצא משפחתו היה מבבל (יומא ס\"ו ע\"ב רש\"י). מושבו היה ציפורי (ב\"ב ע\"ה ע\"ב), שם היתה לו ישיבה גדולה (סנהדרין ל\"ב ע\"ב). תלמידו המובהק של רבי עקיבא (פסחים י\"ח ע\"א). כשמתו תלמידי ר\"ע מסופר: \"והיה העולם שמם, עד שבא רבי עקיבא אצל רבותינו שבדרום ושנאה להם: ר' מאיר, ר' יהודה, ור' יוסי, ור' שמעון ור' אלעזר בן שמוע, והם הם העמידו תורה אותה שעה\" (יבמות ס\"ב ע\"ב). הוסמך על ידי ר' יהודה בן בבא (סנהדרין י\"ד ע\"א). קיבל מאביו ר' חלפתא (בכורות כ\"ו ע\"א), ומאבטולמוס, (עירובין ל\"ו ע\"א). חברם של רשב\"ג ור' יהודה (פסחים ק' ע\"א). בין תלמידיו הרבים היה רבינו הקדוש (נדה ס\"ח ע\"ב), שאמר עליו: \"שכשם שבין קדשי הקדשין לבין חולי חולין, כך בין דורנו לדורו של ר' יוסי\" (ירו', גיטין פ\"ו ה\"ז). תוספות סובר שרבי בזקנותו היה גדול מר' יוסי (שבת נ\"א ע\"א תד\"ה: אילו). יבם את אשת אחיו, והיא ילדה לו חמישה תנאים: ר' ישמעאל, ר' אלעזר, ר' מנחם, ר' חלפתא ור' אבדימוס (ירו', ריש יבמות). \"ואמר ר' יוחנן: 'מאן תנא סדר עולם [העוסק בסדרי זמנים ומאורעות הסטוריים] - רבי יוסי'\" (יבמות ס\"ב ע\"ב). אליהו הנביא היה רגיל אצלו וקראו \"רבי\" (ברכות ג' ע\"א). יותר משלש מאות פעמים מובא שמו במשנה וכן בתוספתא. רגיל היה להתוכח עם גויים בעניני אמונה ולנצחם (ב\"ר פ\"ד - ו' שם פס\"ח - ד'). היה אומן מעבד עורות (שבת מ\"ט ע\"ב רש\"י). נפטר אחרי רבי מאיר (נזיר מ\"ט ע\"ב) ולפני רבי יהודה (סוכה י\"ח ע\"ב). ואמרו: \"משמת רבי יוסי, פסקה הבינה\" (ירו', סוף סוטה).","cat": "sage"},{"i": 2187,"n": "ר' יוסי בן חנמאל","l": "י","b": "מובא ב\"ילקוט\" (נחמיה רמז תתרע\"א).","cat": "sage"},{"i": 2188,"n": "ר' יוסי בן טרטס","l": "י","b": "מובא בויק\"ר (פ\"ז - ב'), והוא ר' יוסי בן פטרוס.","cat": "sage"},{"i": 2189,"n": "ר' יוסי בן יאסין","l": "י","b": "תנא בדור השלישי. חברו של ר' יהודה הנחתום, וביחד אמרו שניהם הלכה (תוספתא מנחות פ\"א ט\"ו).","cat": "sage"},{"i": 2190,"n": "ר' יוסי בן יהושע","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. ר' יוחנן מסר משמו (חולין נ\"ו ע\"ב).","cat": "sage"},{"i": 2191,"n": "יוסי בן יוחנן איש ירושלים","l": "י","b": "מחכמי ה\"זוגות\". הוא וחברו יוסי בן יועזר היו בתחילת תקופת ה\"זוגות\", מיד לאחר תקופת אנשי כנסת הגדולה. שימש כאב בית דין וחברו כנשיא. ע\"ע יוסי בן יועזר איש צרידה.","cat": "sage"},{"i": 2192,"n": "ר' יוסי בן יוסי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר משום רבי יוחנן (ירו', גיטין פ\"א ה\"א), ומשום ר' יצחק בן אלעזר (ירו', תרומות פ\"א ה\"ה).","cat": "sage"},{"i": 2193,"n": "ר' יוסי בן יוסי בן יאסיין","l": "י","b": "מובא בבבלי (מנחות ו' ע\"ב), והוא ר' יוסי בן יאסין.","cat": "sage"},{"i": 2194,"n": "רבי יוסי בן יוסי בן פרורה","l": "י","b": "מובא בירושלמי (עירובין פ\"א ה\"ב), והוא ר' יוסי פרידה תלמידו של רבי אליעזר.","cat": "sage"},{"i": 2195,"n": "יוסי בן יועזר איש צרידה","l": "י","b": "מהחכמים הקדמונים. ראשון מחכמי ה\"זוגות\", חמישה דורות לפני התחלת תקופת התנאים. נשיא הסנהדרין. חברו ובן זוגו היה יוסי בן יוחנן איש ירושלים, ששימש אב בית דין (חגיגה ט\"ז ע\"א). שניהם קבלו מאנטיגנוס, ואולי אף משמעון הצדיק (אבות פ\"א מ\"ד). מנהיגי הדור הבא היו תלמידיהם: יהושע בן פרחיה ונתאי הארבלי (אבות פ\"א מ\"ד). \"היה חסיד שבכהונה\" (חגיגה י\"ח ע\"ב). \"מימות משה עד שמת יוסף בן יועזר היו למדין תורה כמשה רבינו\" (תמורה ט\"ו ע\"ב). ואמרו: \"משמת יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים, בטלו האשכולות\" (סוטה מ\"ז ע\"א). יוסי בן יועזר נהרג בתקופת שמד של היוונים על ידי בן אחיו הכהן הגדול, המתיוון אלקימוס (ב\"ר פס\"ה - כ\"ב).","cat": "sage"},{"i": 2196,"n": "רבי יוסי בן יסיאן","l": "י","b": "הוא ר' יוסי בן יאסין.","cat": "sage"},{"i": 2197,"n": "ר' יוסי בן יעקב","l": "י","b": "תנא שחי לפני רבי שמעון בן יוחאי. מובא ב\"זוהר\" (ריש אידרא זוטא האזינו).","cat": "sage"},{"i": 2198,"n": "ר' יוסי בן יעקב איש כפר אונו","l": "י","b": "תנא בדור החמישי. מובא ב\"זוהר\" (שמות י' ע\"ב) ששאל לרבי מאיר.","cat": "sage"},{"i": 2199,"n": "ר' יוסי בן כיפר","l": "י","b": "תנא בדור החמישי. חברו של ר' דוסתאי בר ינאי, ושניהם היו בבבל אצל ר' אחי בר' יאשיה (גיטין י\"ד ע\"א). בצעירותו שלחוהו לבבל יחד עם בן בנו של זכריה בן קבוטל, להשפיע על חנינא בן אחי ר' יהושע לחדול מעיבור שנים וקביעת חדשים (ברכות ס\"ג ע\"א). מסר משום רבי אלעזר (יבמות י\"א ע\"ב).","cat": "sage"},{"i": 2200,"n": "ר' יוסי בן משולם","l": "י","b": "הוא ר' יוסי בן המשולם.","cat": "sage"},{"i": 2201,"n": "ר' יוסי בן נהוראי","l": "י","b": "נראה היה לומר שהיה אמורא ארץ ישראלי בדור הראשון, אך תוספות אומרים במפורש שהיה תנא (ב\"מ מ\"א ע\"ב ד\"ה: קרנא). שאל מר' יהושע בן לוי (חולין נ\"ז ע\"ב). חברו של ר' יוחנן בן ארזא (ע\"ז נ\"ח ע\"א). ר' יוחנן היה תלמידו (ב\"מ מ\"א ע\"ב רש\"י). חכמי ארץ ישראל רבים מסרו משמו.","cat": "sage"},{"i": 2202,"n": "ר' יוסי בן סמאי","l": "י","b": "מובא בירושלמי (יומא פ\"ח ה\"ה). ע\"ע אבא יוסי בן סימאי.","cat": "sage"},{"i": 2203,"n": "ר' יוסי בן עזי","l": "י","b": "מובא בירושלמי (שקלים פ\"ז ה\"ג).","cat": "sage"},{"i": 2204,"n": "ר' יוסי בן עזי דברדילה","l": "י","b": "מובא בירושלמי (שקלים פ\"ז ה\"ה - הנדפס בבבלי). אבל הגיר' בירושלמי: ר' יהודה בן פזי דברדילה.","cat": "sage"},{"i": 2205,"n": "יוסי בן עקיבא","l": "י","b": "מובא בספרי (עקב י\"ח), והוא איסי בן עקביה.","cat": "sage"},{"i": 2206,"n": "ר' יוסי בן פזי (2)","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר' יוסי בן חנינא (ירו', שבת פ\"ד ה\"א).","cat": "sage"},{"i": 2207,"n": "ר' יוסי בן פטרוס","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. חותנו של ר' יהושע בן לוי. חברו של בר קפרא (ירו', מו\"ק פ\"ג ה\"ה) וחלק עמו באגדה (ב\"ר פצ\"ד - ה'). מובאים פסוקים ששניהם אמרו בשעת פטירתם (ירו', ע\"ז פ\"ג ה\"א).","cat": "sage"},{"i": 2208,"n": "ר' יוסי בן פיטרס","l": "י","b": "מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא ר' יוסי בן פטרוס.","cat": "sage"},{"i": 2209,"n": "יוסי בן פכסס","l": "י","b": "נראה שחי בזמן הבית. מובא מעשה ביוסי בן פכסס שעלתה על רגלו נומי כו' וחכמים אמרו עליו \"יש צדיק אובד וכו'\" (ירו', נזיר פ\"ז ה\"א) אבל אין ראיה שהיה מן החכמים.","cat": "sage"},{"i": 2210,"n": "ר' יוסי בן פרטא","l": "י","b": "תנא בדור השלישי. אמר משום רבי אליעזר (נדרים מ\"א ע\"א).","cat": "sage"},{"i": 2211,"n": "ר' יוסי בן פרידה","l": "י","b": "תנא בדור השלישי. תלמידו של רבי אליעזר (עירובין י\"א ע\"ב).","cat": "sage"},{"i": 2212,"n": "יוסי בן קיטונתא","l": "י","b": "מובא בירושלמי (סוף סוטה), והוא ר' יוסי קטנתא.","cat": "sage"},{"i": 2213,"n": "רבי יוסי בן קיסמא","l": "י","b": "תנא בדור השלישי. הרביץ תורה והיו לו תלמידים הרבה (סנהדרין צ\"ח ע\"א). ר' חנינא בן תרדיון קרא לו: \"רבי\" (ע\"ז י\"ח ע\"א). בימיו היו גזירות קשות ונוראות, והוא היה מקורב למלכות, וכשנפטר הלכו כל גדולי רומי לקברו והספידוהו הספד גדול (שם). ולפני פטירתו אמר לר' חנינא בן תרדיון: \"תמה אני אם לא ישרפו אותך ואת ספר תורה באש\" (שם). ממנו המאמר: \"אם אתה נותן לי כל כסף וזהב ואבנים טובות ומרגליות שבעולם, איני דר אלא במקום תורה\" (אבות פ\"ו מ\"ט).","cat": "sage"},{"i": 2214,"n": "ר' יוסי בן שאול","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. תלמידו של רבי (ע\"ז נ\"ב ע\"ב). ורבי אמר לו: \"ברוך אתה לשמים שהחזרת לי אבידתי\" (שם). היה רבם של ר' יהושע בן לוי (ביצה י\"ד ע\"ב), ור' חייא בר גמדא (ר\"ה כ\"ד ע\"א). יתכן שר' יוחנן בן שאול היה אחיו (שבת קכ\"ה ע\"ב).","cat": "sage"},{"i": 2215,"n": "ר' יוסי בן תדאי איש טבריה","l": "י","b": "תנא בדור הרביעי. \"זו שאלה שאל ר' יוסי בר תדאי איש טבריה את רבן גמליאל\" (ד\"א רבה רפ\"א).","cat": "sage"},{"i": 2216,"n": "ר' יוסי בן תחליפא","l": "י","b": "מובא במדרש תהלים (פע\"ב), וסביר שצ\"ל: בן חלפתא.","cat": "sage"},{"i": 2217,"n": "ר' יוסי בר אבא","l": "י","b": "מובא בבבלי (זבחים כ\"ה ע\"ב), ואולי הוא ר' יוסה בר אביי.","cat": "sage"},{"i": 2218,"n": "ר' יוסי בר אבהו","l": "י","b": "מובא בבבלי (קי\"ב ע\"ב), ואולי צ\"ל: רב יוסף בר אבא.","cat": "sage"},{"i": 2219,"n": "ר' יוסי בר אביי","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו (ירו', תענית פ\"ד ה\"ה): \"הלוחות היו מבקשין לפרוח והיה משה תופסן\".","cat": "sage"},{"i": 2220,"n": "ר' יוסי בר אבין","l": "י","b": "מגדולי ואחרוני אמוראי ארץ ישראל בדור החמישי. ירד לבבל (יבמות ע\"ה ע\"ב) וחזר לא\"י (ירו', פסחים פ\"י ה\"ב). שמו מובא פעמים רבות בתלמוד ירושלמי, ורב חלקו בסידור הירושלמי. הוא המסיים בו סוגיות רבות. אין כמעט חכמים אחריו שמסרו בשמו, מלבד \"חכמים דקסרין\" (ירו', שבת פ\"ח ה\"א). קיבל מתלמידי רבי יוחנן - ר' אבהו (ירו', ברכות פ\"ה ה\"א) ר' אבא (ירו', יבמות פ\"ד הי\"א). מסר בשם ר' יוסי בר חנינא (ירו', נזיר פ\"ד ה\"ה). חלק הרבה עם ר' יוסי בר זבידא (ברכות כ\"ב ע\"א).","cat": "sage"},{"i": 2221,"n": "ר' יוסי בר איבו","l": "י","b": "מובא בב\"ר (פל\"ד - י\"ג), ואולי הוא ר' יוסף בר אבא.","cat": "sage"},{"i": 2222,"n": "ר' יוסי בר איקא","l": "י","b": "מובא בשהש\"ר (פ\"א פסוק משכני - ד').","cat": "sage"},{"i": 2223,"n": "ר' יוסי בר אליקים","l": "י","b": "מובא בבבלי (ברכות ט' ע\"ב). אם נניח שהוא אחיו של ר' שמעון בן אליקים, אם כן חי בא\"י בדור השלישי לאמוראים.","cat": "sage"},{"i": 2224,"n": "ר' יוסי בר אלעזר בר ר' שמעון בר יוחאי","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. בן בנו של ר' שמעון בר יוחאי. מסופר שרבי בא למקומו ומצא שלא נהג כשורה, והחזירו למוטב, וכשנפטר רצו להכניסו למערת אביו ונחש ענקי חסם הדרך, ויצאה בת קול ואמרה: \"לא מפני שזה גדול מזה, אלא זה היה בצער מערה וזה לא היה בצער מערה\" (ב\"מ פ\"ה ע\"א).","cat": "sage"},{"i": 2225,"n": "ר' יוסי בר אסיין","l": "י","b": "מובא בבבלי (עירובין נ\"ג ע\"ב), ואולי הוא ר' יוסי אשיון.","cat": "sage"},{"i": 2226,"n": "רבי יוסי בר אשיאן","l": "י","b": "הוא רבי יוסי אסיין.","cat": "sage"},{"i": 2227,"n": "רבי יוסי בר ביבי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר' שמואל [לא שמואל] (ירו', שקלים פ\"ג ה\"ב).","cat": "sage"},{"i": 2228,"n": "רבי יוסי בר ביבין","l": "י","b": "הוא רבי יוסי בר ביבי.","cat": "sage"},{"i": 2229,"n": "ר' יוסי בר ביסא","l": "י","b": "מובא ב\"ילקוט\" (איוב רמז תתצ\"ז).","cat": "sage"},{"i": 2230,"n": "רבי יוסי בר ברתיה דרבי יוסי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם אבי אמו רבי יוסי (ירו', נזיר פ\"ו ה\"א).","cat": "sage"},{"i": 2231,"n": "ר' יוסי בר גזירא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. ר' יונה אמר בשמו (ירו', סוף ברכות).","cat": "sage"},{"i": 2232,"n": "ר' יוסי בר דוסא","l": "י","b": "מובא בב\"ר (פ\"ס - ז').","cat": "sage"},{"i": 2233,"n": "ר' יוסי בר הינא","l": "י","b": "מובא בבבלי (סנהדרין ק\"ה ע\"ב), ונראה שט\"ס וצ\"ל: ר' יוסי בר חנינא, כבמקומות אחרים כגון: (נזיר כ\"ג ע\"ב: הוריות י' ע\"ב).","cat": "sage"},{"i": 2234,"n": "ר' יוסי בר זבידא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. חברו של ר' יוסי בר אבין (ברכות כ\"ב ע\"א). יתכן שבכל מקום שמוזכר ר' יוסי בר זבידא, הכוונה לר' יוסי סתם, האמורא הארץ ישראלי.","cat": "sage"},{"i": 2235,"n": "ר' יוסי בר זבילא","l": "י","b": "מובא בבבלי (סוכה ל\"ז ע\"ב), ונראה ט\"ס וצ\"ל: ר' יוסי בר זבידא.","cat": "sage"},{"i": 2236,"n": "ר' יוסי בר זמינא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ר' יוחנן (ירו', כלאים רפ\"ה).","cat": "sage"},{"i": 2237,"n": "ר' יוסי בר זעירא","l": "י","b": "אמורא ארץ ישראלי בדור השני. מסר בשם ר' יונתן (ירו', כתובות פ\"ה ה\"א).","cat": "sage"},{"i": 2238,"n": "רבי יוסי בר חנינא (2)","l": "י","b": "אמורא ארץ ישראלי מפורסם בדור השני - השלישי. מגדולי תלמידי ר' יוחנן ונסמך על ידו (סנהדרין ל' ע\"ב). כן מסר בשם ר' יהושע בן לוי (ירו', יומא רפ\"ח) ורבי אושעיא (ירו', ע\"ז פ\"ג ה\"ה). הנהיג ישיבה והיו לו תלמידים הרבה. כמה מתלמידי ר' יוחנן היו לתלמידיו וביניהם ר' אבהו (שבת צ\"ד ע\"ב) כל היכא שמצינו: \"מחכו עלה במערבא\", הכונה לר' יוסי בר חנינא (סנהדרין י\"ז ע\"ב). כמה מבניו נפטרו בחייו (תענית י\"ג ע\"ב). רבי זירא סיפר, שר' יוסי בר חנינא נראה לו בחלום, וסיפר לו שיושב בישיבה של מעלה אצל רבי יוחנן (ב\"מ פ\"ה ע\"ב).","cat": "sage"},{"i": 2239,"n": "ר' יוסי בר יאסיניאה","l": "י","b": "מובא בבבלי (ביצה ח' ע\"ב), ואולי הוא ר' יוסי בר אשיין.","cat": "sage"},{"i": 2240,"n": "ר' יוסי בר יהודה","l": "י","b": "תנא בדור החמישי. בנו של התנא רבי יהודה בר אלעאי (מנחות ס\"ג ע\"ב). בר פלוגתיה וחברו של רבי (נדרים ס\"ב ע\"א: בכורות נ\"א ע\"א), ומצינו את שניהם יחד (נדרים שם). פעמים שסתם רבי המשנה אליביה (עירובין ל\"ח ע\"ב רש\"י) \"שראה רבי דבריו במקומות הרבה ושנאן במשנה סתם\". נראה שנפטר לפני רבי: \"שלשה דברים צוה רבי יוסי בר יהודה את רבי\" (פסחים קי\"ב ע\"ב). וממנו המאמר: \"תניא רבי יוסי בר יהודה: שני מלאכי השרת מלוין לו לאדם בערב שבת מבית הכנסת לביתו וכו'\" (שבת קי\"ט ע\"ב).","cat": "sage"},{"i": 2241,"n": "ר' יוסי בר יהודה איש כפר הבבלי","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. ממנו המאמר: \"הלומד מן הקטנים למה הוא דומה? לאוכל ענבים קהות וכו'\" (אבות פ\"ד מ\"כ).","cat": "sage"},{"i": 2242,"n": "ר' יוסי בר יעקב","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. הלך לבקר את חברו של ר' יודן מגדליא ושמע מפיו תפילת הודיה על הגשם, שאותה קיבל מר' סימון (ירו', ברכות פ\"ט ה\"ב).","cat": "sage"},{"i": 2243,"n": "ר' יוסי בר יעקב בר זבדי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי אבהו (ירו', פאה פ\"א ה\"א).","cat": "sage"},{"i": 2244,"n": "ר' יוסי בר יצחק","l": "י","b": "מובא בב\"ר (פמ\"א - ד'). יתכן שיש ט\"ס בשם, וצ\"ל: ר' טובי בר יצחק.","cat": "sage"},{"i": 2245,"n": "ר' יוסי בר ירמיה","l": "י","b": "מובא בשהש\"ר (ספ\"ד).","cat": "sage"},{"i": 2246,"n": "ר' יוסי בר ממל","l": "י","b": "מובא בירושלמי שאמר: \"כהנת מותרת לצאת וכו'\" (קידושין פ\"א ה\"ז), ואותו מאמר מובא בשם ר' דוסא ממלחיא (ירו', סוטה פ\"ג ה\"ז).","cat": "sage"},{"i": 2247,"n": "יוסי בר מניישא","l": "י","b": "מובא בירושלמי (מגילה פ\"ב ה\"ד), שאמר בשם רב. סביר לומר שהוא ר' יוסף בריה דרב מנשיא מדויל תלמידו של רב.","cat": "sage"},{"i": 2248,"n": "יוסי בר מנשיא","l": "י","b": "מובא בירושלמי (סוכה פ\"ג ה\"ב), שאמר בשם רב. סביר לומר שהוא ר' יוסף בריה דרב מנשיא מדויל תלמידו של רב.","cat": "sage"},{"i": 2249,"n": "ר' יוסי בר נחמיה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם לוי (פסדר\"כ ס\"פ רני עקרה).","cat": "sage"},{"i": 2250,"n": "ר' יוסי בר נחמן","l": "י","b": "תנא. מובא ב\"זוהר\" (חדש בראשית פ' אלה תולדות שמים).","cat": "sage"},{"i": 2251,"n": "ר' יוסי בר נתן","l": "י","b": "מובא בבבלי (ב\"ב קכ\"א ע\"א), והוא ר' אסי בר נתן.","cat": "sage"},{"i": 2252,"n": "ר' יוסי בר סימון","l": "י","b": "אמורא ארץ ישראלי בדור השני. מסר משום ר' יהושע בן לוי (ירו', מע\"ש פ\"ד ה\"ב).","cat": "sage"},{"i": 2253,"n": "ר' יוסי בר קסריי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מצינו שחלק עם ר' תנחומא (שהש\"ר פ\"ו - ד').","cat": "sage"},{"i": 2254,"n": "ר' יוסי בר קצרתא","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. ר' יוחנן מסר בשמו (שבת קנ\"א ע\"ב). כן מסר בשמו ר' שמעון בר חנן (מדרש תהלים פע\"ח).","cat": "sage"},{"i": 2255,"n": "ר' יוסי בר רב כהנא","l": "י","b": "אמורא בדור השני. אמר בשם שמואל (ירו', ברכות פ\"ח ה\"ב).","cat": "sage"},{"i": 2256,"n": "ר' יוסי בר שונם","l": "י","b": "מובא בתנחומא (בשלח - י\"א), וצ\"ל: ר' יוסטא בר שונם.","cat": "sage"},{"i": 2257,"n": "ר' יוסי בר שלום","l": "י","b": "מובא במדרש תהלים (הישן רפע\"ב), ונראה שיש ט\"ס בשם.","cat": "sage"},{"i": 2258,"n": "ר' יוסי בר שמעון בר אבא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר משם רבי יוחנן (ירו', סוף ברכות).","cat": "sage"},{"i": 2259,"n": "רבי יוסי בריבי","l": "י","b": "מובא בירושלמי (סוכה פ\"ב ה\"ה), והוא רבי יוסי בר חלפתא, ובריבי פירושו גדול הדור.","cat": "sage"},{"i": 2260,"n": "ר' יוסי בריה דרב חסדא","l": "י","b": "מובא ב\"זוהר\" (חדש רות פ\"א).","cat": "sage"},{"i": 2261,"n": "ר' יוסי בריה דר' יעקב בר אידי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם ר' אחא (מדרש תהלים פפ\"א - ד'). נראה שהוא בנו של האמורא ר' יעקב בר אידו.","cat": "sage"},{"i": 2262,"n": "ר' יוסי בריה דר' תנחום מכפר אגין","l": "י","b": "מובא בירושלמי (שבת פ\"ב ה\"ו).","cat": "sage"},{"i": 2263,"n": "ר' יוסי גלילאה","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של ר' יוסי בר חנינא ומסר משמו (ירו', ברכות פ\"ג ה\"א). \"פעם איקלע לאתריה דר' יוסי בר חנינא, טילטל שרגא, ואיקפד ר' יוסי בר חנינא\" (שבת מ\"ו ע\"א).","cat": "sage"},{"i": 2264,"n": "ר' יוסי דכפר דן","l": "י","b": "מובא בירושלמי (דמאי פ\"ב ה\"א), שאמר בשם רבי בן מעדיה.","cat": "sage"},{"i": 2265,"n": "ר' יוסי דכפר חנן","l": "י","b": "תנא. מובא ב\"זוהר\" (פ' לך פ\"ז ב').","cat": "sage"},{"i": 2266,"n": "ר' יוסי דמן יוקרת","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. רבו של ר' יוסי בר אבין (תענית כ\"ג ע\"ב). ור' יוסי בר אבין בא לפני ר' אשי וסיפר לו שעזב את רבו, כי לא חס על בנו ובתו. בנו אמר פעם לעץ תאנה: \"תאנה תאנה, הוציאי פירותיך ויאכלו פועלי אבא\" וכך היה, אמר לו אביו \"בני, אתה הטרחת את קונך להוציא תאנה פירותיה שלא בזמנו, יאסף שלא בזמנו\" [ומת בנו] וכן סופר שבתו בעלת יופי היתה, ואחד הסתכל בה דרך הגדר לראות ביופיה, אמר לה \"בתי קא מצערת להו לברייתא, שובי לעפריך ואל יכשלו בך בני אדם\" [ומתה] (שם).","cat": "sage"},{"i": 2267,"n": "ר' יוסי דמן קיסרי","l": "י","b": "מובא בבבלי (סנהדרין ק\"ח ע\"א). \"סה\"ד\" כתב שהוא ר' אסי דקיסרין.","cat": "sage"},{"i": 2268,"n": "ר' יוסי דפקיעין","l": "י","b": "תנא בדור החמישי. מובא ב\"זוהר\" (פ' בלק ר\"ד ע\"ב).","cat": "sage"},{"i": 2269,"n": "ר' יוסי דרומייא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של ר' יונה (ירו', שבועות פ\"א ה\"ה).","cat": "sage"},{"i": 2270,"n": "ר' יוסי הארוך","l": "י","b": "תנא בדור החמישי. משרתו של רבי (ב\"ר פצ\"ז - ג', וש\"ר פ\"ב - ה'). ופירש הרד\"ל שהוא יוסף חפני המובא בבבלי (כתובות ק\"ג ע\"א). נפטר קודם לרבי (שם).","cat": "sage"},{"i": 2271,"n": "יוסי הבבלי","l": "י","b": "מובא בירושלמי (ב\"ק פ\"ג ה\"ז), והוא איסי בן עקביה.","cat": "sage"},{"i": 2272,"n": "ר' יוסי הגלילי","l": "י","b": "תנא בדור השלישי. נמנה עם ראשי הזקנים, מראשי חכמי יבנה, ומוזכר לפני רבי טרפון, רבי אלעזר בן עזריה ורבי עקיבא (גיטין פ\"ג ע\"א), וכן מוזכר לפני ראב\"ע ור\"ע (מו\"ק כ\"ח ע\"ב). תוספות כתבו שר' יוסי הגלילי היה תלמיד חבר לר\"ע (ע\"ז מ\"ה ע\"א תד\"ה: אמר). ואילמלא תוספות, חשבנו להיפך, שר' יוסי הגלילי גדול מרבי עקיבא, או לפחות חברו ממש, שכן רבי אלעזר בן עזריה היה תלמידו (ירו', כתובות פי\"א ה\"ג). התוכח בהלכה עם ר\"ט ור\"ע וניצחם (זבחים נ\"ז ע\"א). לר\"ע אמר: \"עקיבא, אפילו אתה מרבה כל היום כולו, איני שומע לך\" (זבחים פ\"ב ע\"א). האומרים בשמו: ר' אלעזר (שם מ\"ד ע\"א) ור' יהודה (שבועות כ\"א ע\"א). בכוחו היה להוריד גשם (ירו', ברכות פ\"ה ה\"ב). שני בניו היו תנאים מפורסמים בדור הרביעי: ר' אלעזר בנו של ר' יוסי הגלילי (ברכות ס\"ג ע\"ב) ור' חנינא בנו של ר' יוסי הגלילי (ר\"ה ל\"ב ע\"א).","cat": "sage"},{"i": 2273,"n": "ר' יוסי החורם","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (מנחות ל\"ז ע\"א). ר' נתן מוסיף על דבריו (שם).","cat": "sage"},{"i": 2274,"n": "רבי יוסי הכהן","l": "י","b": "תנא בדור השני. אחד מחמשת תלמידיו המובהקים ביותר של רבי יוחנן בן זכאי, ונזכר שלישי לפני ר' שמעון בן נתנאל ור' אלעזר בן ערך (אבות פ\"ב מ\"ח). היה בזמנו של ר\"ג (ר\"ה י\"ז ע\"ב). העיד עם ר' זכריה בן הקצב (עדיות פ\"ח מ\"ב). ריב\"ז קראו: \"חסיד\" (שם). פעם הלך עם ר' יהושע ודרשו במעשה המרכבה \"והיו מלאכי השרת מתקבצין ובאין לשמוע, כבני אדם שמתקבצין ובאין לראות\" (חגיגה י\"ד ע\"ב).","cat": "sage"},{"i": 2275,"n": "ר' יוסי הכהן","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"א\"ל ר' אבא הכהן לר' יוסי הכהן: 'אמאי אישתוק ר' יוחנן לר\"ל'\" (ר\"ה ט\"ו ע\"ב).","cat": "sage"},{"i": 2276,"n": "ר' יוסי המודעי","l": "י","b": "תנא בדור השלישי. מובא במכילתא (בשלח ט\"ז - ז') שמביא ראיה לדברי ר' אלעזר המודעי.","cat": "sage"},{"i": 2277,"n": "ר' יוסי זוטא","l": "י","b": "תנא. מובא ב\"זוהר\" (וארא כ\"ט).","cat": "sage"},{"i": 2278,"n": "ר' יוסי חסידא","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא בירושלמי: \"משמת ר' יוסי חסידא ור' יוסי קטונתא, פסקו אנשי חסידות\" (סוף סוטה).","cat": "sage"},{"i": 2279,"n": "ר' יוסי מדאה","l": "י","b": "מובא בבבלי (חולין נ\"א ע\"א). לפי רש\"י (שם) היה תלמידו של רבי. וזה פלא גדול, וכבר השיג עליו ה\"יוחסין\". ר' עוירא סיפר לאביי שר' הונא ציפוראה ורבי יוסי מדאה, ישבו לפני רבי וכו' (שם).","cat": "sage"},{"i": 2280,"n": "ר' יוסי ממלחיא","l": "י","b": "אמורא ארץ ישראלי בדור הראשון - השני. שאל מר' מנא א' (ירו', ע\"ז פ\"ב ה\"ד). נפטר בחיי ר' יוחנן ור\"ל, והם ליווהו (איכ\"ר פ\"א - ל\"ז).","cat": "sage"},{"i": 2281,"n": "ר' יוסי מנהרביל","l": "י","b": "מובא בבבלי (חולין קל\"ו ע\"א). ע\"ע ר' אסי מנהרביל.","cat": "sage"},{"i": 2282,"n": "יוסי מעוני","l": "י","b": "אמורא ארץ ישראלי בדור השני. פגע בכבוד הנשיאות בדרשה, ור' יוחנן ור\"ל הלכו לר' יהודה נשיאה לפייסו, והעידו עליו שהוא גברא רבא (ירו', סנהדרין ספ\"ב).","cat": "sage"},{"i": 2283,"n": "ר' יוסי צוודניה","l": "י","b": "מובא בירושלמי (יבמות פ\"ט ה\"ד), והוא ר' יוסי ציידניא.","cat": "sage"},{"i": 2284,"n": "ר' יוסי צידונייא","l": "י","b": "מובא בירושלמי (כתובות פי\"א ה\"ז), והוא ר' יוסי ציידניא.","cat": "sage"},{"i": 2285,"n": "רבי יוסי ציידניא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' ירמיה (יבמות פ\"ט ה\"ד). מסר בשם ר' יוחנן (ירו', ברכות פ\"ד ה\"ד). שמו מובא בכמה אופנים: ציידנייה, צידוניא, ציידניה.","cat": "sage"},{"i": 2286,"n": "ר' יוסי ציידנייה","l": "י","b": "מובא בירושלמי (נזיר ספ\"ז), והוא ר' יוסי ציידניא.","cat": "sage"},{"i": 2287,"n": "רבי יוסי קטנותא","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא במשנה: \"משמת רבי יוסי קטנתא, פסקו חסידים, ולמה נקרא שמו קטנותא? שהיה קטנותן של חסידים\" (סוטה מ\"ט ע\"א). ובירושלמי במשנה (סוף סוטה): \"משמת רבי חנינא בן דוסא ויוסי בן קיטונתא פסקה החסידות, ולמה נקרא שמו יוסי בן קיטונתא? שהיה תמציתן של חסידים\" ובגמרא שם: \"שהיה תמציתן של צדיקים\".","cat": "sage"},{"i": 2288,"n": "רבי יוסי קטנתא","l": "י","b": "מובא בבבלי (סוטה מ\"ט ע\"א), והוא איסי בן עקביה.","cat": "sage"},{"i": 2289,"n": "ר' יוסנא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אמי (ע\"ז ל\"ג ע\"ב).","cat": "sage"},{"i": 2290,"n": "רב יוסף (2)","l": "י","b": "מגדולי אמוראי בבל בדור השלישי. שם אביו חייא (חולין י\"ח ע\"ב). ריש מתיבתא בישיבת פומבדיתא (סוף ברכות), משנת ד' פ' (023) בערך במשך שנתיים וחצי (\"אגרת רב שרירא גאון\"). תלמידם המובהק של רב הונא (שבת קכ\"ט ע\"ב) ורב יהודה (חולין שם). קיבל גם מרב נחמן (יבמות ס\"ו ע\"ב). חבריו הגדולים ממנו היו ר' אבא: \"יתיב רב יוסף אחורי דר' אבא ויתיב ר' אבא קמיה דרב הונא\" (ב\"ק ק\"ב ע\"א) ור\"ה בר חייא: \"יתיב רב יוסף אחורי דרב הונא בר חייא\" (ב\"ק קט\"ז ע\"ב). חברו המובהק היה רבה: \"רבה ורב יוסף אמוראי דנהרדעא\" (סנהדרין י\"ז ע\"ב). מצינו פעמים רבות: \"רבה ורב יוסף דאמרי תרוייהו\" (זבחים י\"ד ע\"ב), ומחלוקות רבות ביניהם מובאות בש\"ס. אחרי פטירת ר' יהודה רצו למנות את ר' יוסף לריש מתיבתא, שכן הוא היה \"סיני\" (הוריות י\"ד ע\"א, פרש\"י: \"שהיו משניות וברייתות סדורות לו כנתינתן מהר סיני\"), אך רב יוסף ביקש שרבה חברו ימלוך לפניו, ואחרי פטירת רבה, מלך ר' יוסף (ברכות שם). היו לו תלמידים רבים, וארבע מאות מתלמידיו היו מאוכלי שולחנו (כתובות ק\"ו ע\"א רש\"י). מגדולי תלמידיו היו אביי (קדושין ל\"ג ע\"א) ורבא (יומא נ\"ג ע\"א). נראה, שאביי היה בסוף ימיו תלמיד - חבר לר' יוסף (עירובין י' ע\"א). חלה ושכח תלמודו ואביי הזכיר לו מדי פעם (נדרים מ\"א ע\"א). הגמרא אומרת: (פסחים קי\"ג ע\"ב): \"ג' חייהן אינן חיים: הרחמנין והרתחנין ואניני הדעת. ואמר ר' יוסף: 'כולהו איתנהו בי'\" (בי יש כל אלו). היה סגי נהור (שבת ק\"ט ע\"א). והרמב\"ן בחידושיו (קדושין ל\"א ע\"א) מביא שסימא עצמו, כי לא רצה להסתכל מחוץ לד' אמותיו. ו\"סה\"ד\" מביא מספר מקור חיים, שישב ר' יוסף בבית אפל מ' יום, וצוה להביא לפניו אבני שיש, והסתכל בהם ונעשה סגי נהור. צם 021 תעניות וביקש רחמים שלא תמוש התורה מזרעו וזרע זרעו (ב\"מ פ\"ה ע\"א). היה בקי בתרגום (ב\"ק ג' ע\"ב תד\"ה: כדמתרגם). גדול היה כיבוד אם שלו, ומספרת הגמרא כי כאשר שמע קול צעדי אמו, היה אומר: אקום מפני שכינה שבאה (קידושין ל\"א ע\"ב). כשנפטר, ישב אביי על כסאו (גיטין ס' ע\"א, ושם ברש\"י).","cat": "sage"},{"i": 2291,"n": "רבי יוסף","l": "י","b": "ע\"ע רבי יוסי.","cat": "sage"},{"i": 2292,"n": "יוסף איש הוצל (2)","l": "י","b": "מובא בבבלי (פסחים קי\"ג ע\"ב), והוא איסי בן עקביה (ע\"ע).","cat": "sage"},{"i": 2293,"n": "יוסף אפרתי","l": "י","b": "מובא בירושלמי (כתובות פי\"ב ה\"ג), והוא שמעון אפרתי.","cat": "sage"},{"i": 2294,"n": "רב יוסף בן זמרא","l": "י","b": "הוא ר' יוסי בן זמרא הכהן.","cat": "sage"},{"i": 2295,"n": "רב יוסף בן חוני","l": "י","b": "אמורא מובא בבבלי (סנהדרין ק\"ה ע\"ב).","cat": "sage"},{"i": 2296,"n": "יוסף בן יהודה","l": "י","b": "מובא בירושלמי (ב\"ק פ\"ג ה\"ז), והוא איסי בן עקביה.","cat": "sage"},{"i": 2297,"n": "יוסף בן יועזר","l": "י","b": "מובא בבבלי (תמורה ט\"ו ע\"ב), והוא יוסי בן יועזר איש צרידה.","cat": "sage"},{"i": 2298,"n": "ר' יוסף בן סימאי","l": "י","b": "אפוטרופוס של מלך היה, ונפלה בשבת דליקה בחצרו, ולא נתן לכבות הדליקה מפני כבוד השבת, ונעשה לו נס וירדו גשמים וכיבו את האש (שבת קכ\"א ע\"א). נראה, שאולי הוא אבא יוסי בן סימאי.","cat": "sage"},{"i": 2299,"n": "רב יוסף בר אבא","l": "י","b": "אמורא בבלי בדור השלישי - הרביעי. ור' ששת אמר לו: \"אסברא לך\" (עירובין ז' ע\"ב). קיבל גם מרב עוקבא (ב\"ב קמ\"ד ע\"ב). היה כחבר לרבה: \"רבה ורב יוסף בר אבא דאמרי תרוייהו\" (שבת ק\"ח ע\"ב).","cat": "sage"},{"i": 2300,"n": "רב יוסף בר אבדימי","l": "י","b": "אמורא בבלי בדור השלישי. נראה בזמנו של ר\"נ: \"אמר רב יוסף: 'בר אבדימי תנא וחכמים אוסרין', אמר רב נחמן: 'הלכה כדברי חכמים'\" (עירובין ח' ע\"א).","cat": "sage"},{"i": 2301,"n": "רב יוסף בר אמי","l": "י","b": "אמורא בבלי. חי אחרי רבא: \"רב יוסף בר אמי רמי וכו' ומשני מי אמר רבא [כצ\"ל]\" (זבחים ג' ע\"ב).","cat": "sage"},{"i": 2302,"n": "רב יוסף בר דוסאי","l": "י","b": "מובא בבבלי (חולין מ\"ט ע\"א). גיר' \"דק\"ס\": \"אבא יוסי בן דוסתאי\", וגירסת הרי\"ף אבא יוסי בן ביסא (חולין ט\"ו).","cat": "sage"},{"i": 2303,"n": "רב יוסף בר חבו","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. רמי לר' אבהו (יומא פ\"ז ע\"א).","cat": "sage"},{"i": 2304,"n": "יוסף בר חייא","l": "י","b": "מובא בבבלי (חולין י\"ח ע\"ב), והוא רב יוסף.","cat": "sage"},{"i": 2305,"n": "רב יוסף בר חמא","l": "י","b": "אמורא בבלי בדור השלישי. אביו של האמורא המפורסם רבא (ב\"ק צ\"ז ע\"א). מושבו היה במחוזא, ונראה שהיה הריש בעירו (ב\"ב קכ\"ז ע\"ב). תלמידם של רב ששת (ב\"מ ע\"ב ע\"ב), ור' נחמן (גיטין מ\"ג ע\"ב). ר' אבא שלח לו מארץ ישראל כמה הלכות (ב\"ב שם).","cat": "sage"},{"i": 2306,"n": "רב יוסף בר חנין","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. וגירסת \"יתו\"א\": רב יוסף בר חבישמיא. שאל מר' אבהו (שבת קט\"ז ע\"א).","cat": "sage"},{"i": 2307,"n": "רב יוסף בר מניומי","l": "י","b": "אמורא בבלי בדור השלישי. תלמידו של רב נחמן (כתובות ק' ע\"ב). כן קיבל מרב ששת (גיטין ע\"א ע\"א). נראה שרב מניומי בריה דרב נחומי, היה תלמידו (כתובות פ\"א ע\"ב).","cat": "sage"},{"i": 2308,"n": "רב יוסף בר רב נחוניא","l": "י","b": "אמורא בבלי בדור השלישי. מובא בבבלי (ברכות כ\"ד ע\"א) ששאל מרב יהודה.","cat": "sage"},{"i": 2309,"n": "ר' יוסף ברב אלעאי","l": "י","b": "ע\"ע ר' יוסי אלעאי.","cat": "sage"},{"i": 2310,"n": "רב יוסף בריה דרב סלא חסידא","l": "י","b": "אמורא בבלי בדור הששי. מצינו אותו כמה פעמים: \"תרגמא קמיה דרב פפא\" (פסחים ע\"ג ע\"ב).","cat": "sage"},{"i": 2311,"n": "רב יוסף בריה דרב עילאי","l": "י","b": "אמורא בבלי בדור הרביעי החמישי. מובא בבבלי (סוכה כ\"ו ע\"א) שמתרץ את קושיית אביי, ועל דבריו מתקיף ליה רב משרשיא.","cat": "sage"},{"i": 2312,"n": "רב יוסף בריה דרב שמואל","l": "י","b": "אמורא בבלי בדור הששי. מצינו שהקשה לרב פפא (זבחים ו' ע\"ב). גיר' \"שיטה מקובצת\": \"בריה דרב שמעיה\". מובא פעם בש\"ס, ולגירסת \"שט\"מ\" לא היה כלל חכם ושמו ר' יוסף בריה דרב שמואל.","cat": "sage"},{"i": 2313,"n": "רב יוסף בריה דרב שמעיה","l": "י","b": "אמורא בבלי בדור הששי. תלמידו של רב פפא (מנחות ט' ע\"ב).","cat": "sage"},{"i": 2314,"n": "רב יוסף בריה דרבא","l": "י","b": "אמורא בבלי בדור החמישי. בנו ותלמידו של רבא (חולין כ\"ח ע\"ב). למד שלוש שנים לפני רב יוסף (כתובות ס\"ג ע\"ב). היה צריך לשהות שם שש שנים, וחזר כעבור 3 שנים (שם). ליבן את דברי רבו ר' יוסף לפני אביו (יבמות ס\"ד ע\"ב). היו לו שלושה בנים חכמים: רב אבא (חולין קמ\"א ע\"א), רב חביבא (ב\"ב קמ\"ג ע\"ב) ונאנאי (יבמות ס\"ו ע\"ב).","cat": "sage"},{"i": 2315,"n": "רב יוסף בריה דר' יהושע בן לוי","l": "י","b": "אמורא ארץ ישראלי בדור השני. בנו ותלמידו של יהושע בן לוי (חולין נ\"ו ע\"ב). נשא אשה ממשפחת הנשיא, ובגלל זה נהג אביו לקום בפניו (קדושין ל\"ג ע\"ב). פעם חלה ונטה למות, וסיפר לאביו מה ראה בעולם האמת (ב\"ב י' ע\"ב). האריך ימים אחרי אביו (יומא ע\"ח ע\"א).","cat": "sage"},{"i": 2316,"n": "רב יוסף בריה רב מנשיא מדויל","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב (נדה כ\"ו ע\"ב). מסופר שעבד עובדא כותיה דרב, ואיקפד שמואל (קידושין ע\"ט ע\"ב), ושלח לשמואל (אולי אחר פטירתו של רב): \"ילמדנו רבנו\" (גיטין פ\"א ע\"א).","cat": "sage"},{"i": 2317,"n": "יוסף הבבלי","l": "י","b": "מובא בבבלי: \"אמר רבי: כשהלכתי למצות מדותי אצל ר' אלעזר בן שמוע וכו', מצאתי יוסף הבבלי וכו'\" (מנחות י\"ח ע\"א). היו לו כמה שמות כדמצינו: \"תנא הוא יוסף איש הוצל הוא יוסף הבבלי וכו' ומה שמו איסי בן עקביה שמו\" (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 2318,"n": "יוסף הכהן","l": "י","b": "מובא בבבלי: \"מעשה ביוסף הכהן שהלך אצל רבו לצידן ללמוד תורה\" (עירובין מ\"ז ע\"ב). מצינו במשנה: \"יוסף הכהן הביא וכו'\" (סוף חלה). אם נאמר שזה אותו חכם, הרי שהיה תנא.","cat": "sage"},{"i": 2319,"n": "יוסף חפני","l": "י","b": "ע\"ע ר' יוסי הארוך ועוד ע\"ע שמעון אפרתי.","cat": "sage"},{"i": 2320,"n": "ר' יוסף צידונא","l": "י","b": "מובא בבבלי (כתובות מ\"ו ע\"ב). \"סה\"ד\" כתב, שהיה בזמן רבי שמעון בן יוחאי (א\"כ, היה תנא בדור הרביעי).","cat": "sage"},{"i": 2321,"n": "יוסף רישבא","l": "י","b": "אמורא בדור הראשון. מצינו ששאל לר' יהודה בן בתירא (חולין נ\"ד ע\"א) (כך פירש \"סה\"ד\" את הגמרא שם). לוי ביקר בביתו וסיפר אח\"כ לרבי על נוהגיו (שבת ק\"ל ע\"א).","cat": "sage"},{"i": 2322,"n": "יועזר איש הבירה","l": "י","b": "תנא בדור השני. מתלמידי בית שמאי ושאל לרבן גמליאל הזקן (משנה ערלה פ\"ב מ\"ב).","cat": "sage"},{"i": 2323,"n": "יועזר בן יעקב","l": "י","b": "מובא ב\"זוהר\" (שמות י\"ד).","cat": "sage"},{"i": 2324,"n": "רבי יוצדק","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. רבי אבא בר זמינא מסר משמו.","cat": "sage"},{"i": 2325,"n": "ר' יושוע אונייה","l": "י","b": "מובא בירושלמי (פסחים פ\"ג ה\"א), והוא ר' יהושע אונייא.","cat": "sage"},{"i": 2326,"n": "ר' יושוע בר גיזורה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זירא (ירו', תענית פ\"ד ה\"א).","cat": "sage"},{"i": 2327,"n": "ר' יושיע בן קבסא","l": "י","b": "מובא בירושלמי (פסחים פ\"ו ה\"א), והוא ר' יהושע בן כפוסא.","cat": "sage"},{"i": 2328,"n": "יושעה בריה דרב חננאל","l": "י","b": "מובא בירושלמי (מגילה פ\"א ה\"ט).","cat": "sage"},{"i": 2329,"n": "רב יחונה","l": "י","b": "מובא בירושלמי (כתובות פ\"א ה\"ב), והוא רב הונא ב'.","cat": "sage"},{"i": 2330,"n": "רב יחזקאל","l": "י","b": "אמורא בבלי בדור הראשון. אביו של האמורא המפורסם רב יהודה. רב יהודה מספר על מנהגי אביו (ירו', תענית פ\"א ה\"ג); אח\"כ גדל רב יהודה והיה לרבו של אביו (קידושין ל\"ג ע\"ב, פרש\"י: \"אע\"ג דרב יהודה רביה דרב יחזקאל, אבוה הוה\"). שמואל נהג לקום בפני ר' יחזקאל, כי היה \"בעל מעשים\" (שם). היה לו בן חכם נוסף ושמו רמי בר יחזקאל ולימדו תורה (שם ל\"ב ע\"א).","cat": "sage"},{"i": 2331,"n": "ר' יחזקיה","l": "י","b": "מובא בירושלמי (ברכות פ\"ו ה\"א).","cat": "sage"},{"i": 2332,"n": "רב יחיאל","l": "י","b": "אמורא בבלי בדור השני. מובא בבבלי (עירובין ל\"א ע\"ב). חלק עם רב יהודה (מו\"ק י' ע\"א).","cat": "sage"},{"i": 2333,"n": "רב ייבא","l": "י","b": "מובא בבבלי (גיטין ס\"ב ע\"א).","cat": "sage"},{"i": 2334,"n": "ר' ייבא בר יוסי","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב. מובא בבבלי (ערכין ה' ע\"ב).","cat": "sage"},{"i": 2335,"n": "ייבא חמוה דאשיין בר נדבך","l": "י","b": "אמורא בבלי בדור השני. אמר משמיה דרב (ב\"ב כ\"ב ע\"ב). חתנו מסר בשם רב יהודה (מנחות כ\"ט ע\"א).","cat": "sage"},{"i": 2336,"n": "רב ייבא סבא","l": "י","b": "אמורא בבלי בדור השני - השלישי. היה משמש את רב ברונא ורב חננאל, שהיו תלמידי רב, ואמר להם משמו של רב (פסחים ק\"ג ע\"ב).","cat": "sage"},{"i": 2337,"n": "ר' ייבא סבא","l": "י","b": "תנא שאין לקבוע את זמנו המדוייק. מובא מספר פעמים ב\"זוהר\". מסופר על אחד שהירהר אחר מצות מילה ונתן ר' ייבא סבא עיניו בו ונעשה גל של עצמות (\"זוהר\", בראשית נ\"ט).","cat": "sage"},{"i": 2338,"n": "רבי יילי","l": "י","b": "מובא בירושלמי (ע\"ז פ\"ד הי\"ב), והוא רבי אלעאי.","cat": "sage"},{"i": 2339,"n": "רב יימר","l": "י","b": "אמורא בבלי בדור הששי. נראה שהיה תלמידו של רב כהנא ה' (ע\"ז נ\"ט ע\"א). שאל לר' אשי ונשא ונתן עמו בהלכה (כתובות ס\"ט ע\"א). נפטר אחרי רב אשי, וחלק עם מר בר ר' אשי: \"אפכיהו ושדרוהו לקמיה דרב מרדכי\" (גיטין כ\"ט ע\"א), ונראה שהדבר היה אחרי מות רב אשי.","cat": "sage"},{"i": 2340,"n": "רב יימר בר חשו","l": "י","b": "כן גירסת \"סה\"ד\", ולפנינו (כתובות פ\"ד ע\"ב): יימר בר חשו (בלי רב), ופרש\"י: \"שם איש\". חי בבבל בזמנו של רב פפא (דור חמישי לאומראים) וחבו לו כסף: \"פגעו בו רב פפא ורב הונא בריה דרב יהושע אמרו לו וכו'\".","cat": "sage"},{"i": 2341,"n": "רב יימר בר שיזבי","l": "י","b": "אמורא בבלי בדור הששי. מובא בבבלי שהקשה למר זוטרא (ברכות נ\"ג ע\"ב).","cat": "sage"},{"i": 2342,"n": "רב יימר בר שלמיא","l": "י","b": "אמורא בבלי בדור החמישי - הששי. תלמידו של אביי (ב\"ב ס\"ג ע\"א). קיבל גם מרבא (ב\"ב ט' ע\"א), ושלח שאלה לרב פפא (מנחות ל\"א ע\"א).","cat": "sage"},{"i": 2343,"n": "רב יימר בריה דרב הלל","l": "י","b": "אמורא בבלי בדור הרביעי. מובא בבבלי (זבחים ט' ע\"א), ורבא השיב על דבריו (שם).","cat": "sage"},{"i": 2344,"n": "רב יימר מדיפתא","l": "י","b": "אמורא בבלי בדור הששי. חלק עם רב אשי (שבת קמו ע\"ב) ונזכר הראשון (שם).","cat": "sage"},{"i": 2345,"n": "רב יימר סבא","l": "י","b": "אמורא בבלי בדור הששי. תלמידו של רב נחמן (כתובות נ\"ג ע\"א). ר\"נ דיבר על אודותיו בכבוד גדול (ב\"ק מ\"ט ע\"ב). פעם שלחוהו חכמים לרב חסדא, לראות אם הוא נוהג לאמר \"שהחיינו\" בקידוש של ראש השנה (עירובין מ' ע\"ב), ורש\"י גורס שם: ייבא סבא.","cat": "sage"},{"i": 2346,"n": "ר' ייסא","l": "י","b": "מובא ב\"זוהר\" (נשא קמד).","cat": "sage"},{"i": 2347,"n": "יישוע אחוה דדוריי","l": "י","b": "חי בארץ ישראל בדור הרביעי לאמוראים. בא לשאול מרבי אבהו שאלת חכם (ירו', מו\"ק פ\"ג ה\"ה) ואין להכריע אם נמנה על החכמים.","cat": "sage"},{"i": 2348,"n": "רבי ינאי","l": "י","b": "מגדולי אמוראי ארץ ישראל בדור הראשון. תלמידו של רבי (ב\"ב פ\"ד ע\"ב). לדברי הרמב\"ם (בהקדמתו ל\"יד החזקה\") היה מבית דינו של רבי. תלמידו של רבי חייא (ירו', דמאי רפ\"ז). ר' חייא אמר: \"עתיד אתה להנהיג שררה על ישראל\" (שם). מושבו היה בעכברא שליד צפת (ע\"ז ל' ע\"א), ושם יסד ישיבה גדולה שהתקיימה כמה דורות אחריו, ועוד היא מוזכרת בימי ר' יונה (ירו', שבת פ\"ח ה\"א). בין תלמידיו הרבים היו רבי יוחנן (ב\"ב קנ\"ד ע\"ב) שהיה משבחו (ירו', כלאים פ\"ח ה\"א), רבי שמעון בן לקיש (עירובין י\"א ע\"ב), ר' אושעיא (כתובות ע\"ט ע\"א) ור' שמלאי (ב\"ב קי\"א ע\"א). אף ר' יהושע בן לוי מסר בשמו (ירו', קידושין פ\"ג ה\"ב). היה עשיר מופלג (ב\"ב י\"ד ע\"א) ועשרו היה למשל בפי הבריות (קידושין י\"א ע\"א). אחת מבנותיו נישאה ליהודה, בנו של רבי חייא, ויהודה מת על פניו (כתובות ס\"ב ע\"ב). היה לו בן ושמו רבי שמעון (ירו', שבת פי\"ג ה\"ז). נראה שהגיע לזקנה גדולה (ב\"ב קי\"א ע\"א רשב\"ם: רבי ינאי זקן היה והחלו עיניו כהות). קודם פטירתו ציווה לבנו שלא יקברוהו לא בכלים לבנים, שמא לא יזכה ויהיה כחתן בין אבלים, ולא בכלים שחורים, שמא יזכה ויהיה כאבל בין חתנים (שבת קי\"ד ע\"א).","cat": "sage"},{"i": 2349,"n": "ר' ינאי","l": "י","b": "תנא בדור הרביעי. מובא באבות (פ\"ד). פעם מסר בשם רבן שמעון בן גמליאל (תוספתא סנהדרין פ\"ב ה'). אולי הוא אביהם של ר' דוסתאי בר ינאי ור' אלעזר בר ינאי.","cat": "sage"},{"i": 2350,"n": "רב ינאי אחוה דרבי חייא בר אבא","l": "י","b": "מובא בבבלי (סנהדרין ע\"ד ע\"ב), והוא רבנאי אחוה דר' חייא בר אבא.","cat": "sage"},{"i": 2351,"n": "ר' ינאי בר ישמעאל","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ר' יוחנן (ירו', יבמות פ\"ח ה\"א) ורשב\"ל (ירו', עירובין פ\"א ה\"א). כשחלה באו לבקרו רבי זירא וחכמים נוספים (ירו', תרומות פ\"ח ה\"ג).","cat": "sage"},{"i": 2352,"n": "ר' ינאי בר נחמיה","l": "י","b": "אמורא בבלי בדור השני. תלמידו של שמואל (תמיד כ\"ט ע\"א). מאמרו המובא במסכת חולין (צ' ע\"ב), מובא בשם ר' יצחק בר נחמיה, גם הוא תלמידו של שמואל.","cat": "sage"},{"i": 2353,"n": "ר' ינאי בר שמואל","l": "י","b": "מובא בשהש\"ר (פ\"א פסוק ג' - א').","cat": "sage"},{"i": 2354,"n": "ר' ינאי בר שמעון","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מובא בקה\"ר (פ\"ב - ה') שאמר לר' אבא בר כהנא.","cat": "sage"},{"i": 2355,"n": "רבי ינאי בריה דרבי ינאי סבא","l": "י","b": "מובא בבבלי (מגילה ל\"ב ע\"א), שאמר משמיה דר' ינאי רבה.","cat": "sage"},{"i": 2356,"n": "ר' ינאי בריה דר' אמי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה אולי שהיה בנו של ר' אמי האמורא המפורסם. מובא בבבלי: \"וינאי בריה דר' אמי, איקלען לבי יהודה בריה דרבי שמעון בן פזי\" (חולין קי\"א ע\"א).","cat": "sage"},{"i": 2357,"n": "רבי ינאי בריה דר' שמואל בר' ינאי","l": "י","b": "מובא במדרש שמואל (הישן ספכ\"ח), ונראה שצ\"ל: רבי ינאי בריה דר' שמעון בר ינאי.","cat": "sage"},{"i": 2358,"n": "ר' ינאי דשאב","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם ר' שמואל בר נחמן (פס' רבתי פ' פרה - פ\"י).","cat": "sage"},{"i": 2359,"n": "ר' ינאי הכהן","l": "י","b": "מובא במ\"ר (פכ\"ג - ז') ובתנחומא (מסעי - ה').","cat": "sage"},{"i": 2360,"n": "ר' ינאי זעירא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. כשנפטר חמו, שהיה רבו, שאל את ר' יוסי אם מותר להטמא לכבודו, ואסר לו. שמע ר' אחא, והתיר (ירו', ברכות פ\"ג ה\"א).","cat": "sage"},{"i": 2361,"n": "ר' ינאי חמוהי דר' אמי","l": "י","b": "מובא בשהש\"ר (פ\"א - י\"א).","cat": "sage"},{"i": 2362,"n": "רבי ינאי סבא","l": "י","b": "מובא בבבלי: \"ר' ינאי בריה דר' ינאי סבא משמיה דר' ינאי רבה\" (מגילה ל\"ב ע\"א), ומובא שוב: \"בר בריה דר' ינאי סבא אתא לקמיה דר' ינאי סבא, והתיר לו נדרו\" (נדרים כ\"ב ע\"א).","cat": "sage"},{"i": 2363,"n": "ר' ינאי קפודקאי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. שאל דין ירושת הבן משלושה דיינים - רב הונא ב', ר' יהודה בן פזי ור' אחא (ירו', ב\"ב רפ\"ח).","cat": "sage"},{"i": 2364,"n": "רבי ינאי רבה","l": "י","b": "מובא בבבלי: \"ר' ינאי בריה דר' ינאי סבא משמיה דר' ינאי רבה\" (מגילה ל\"ב ע\"ב).","cat": "sage"},{"i": 2365,"n": "ר' ינטה בר חיננא","l": "י","b": "מובא בירושלמי (פסחים רפ\"ד).","cat": "sage"},{"i": 2366,"n": "יסא","l": "י","b": "הוא יוסי או אסי.","cat": "sage"},{"i": 2367,"n": "ר' יסא בי ר' שבתי","l": "י","b": "מובא בירושלמי (גיטין פ\"ט ה\"ז), ונראה שצ\"ל: ר' יסא בשם ר' שבתי.","cat": "sage"},{"i": 2368,"n": "ר' יסא בר אחא","l": "י","b": "מובא בירושלמי (עירובין פ\"ה ה\"א), ואולי צ\"ל: ר' יעקב בר אחא, כפי שמשתמע מהסוגיא שם.","cat": "sage"},{"i": 2369,"n": "ר' יסא בר ברתיה דר' יסא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר' ירמיה (ירו', נזיר פ\"ו ה\"א).","cat": "sage"},{"i": 2370,"n": "יסא בר חלפותא","l": "י","b": "מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא רבי יוסי בן חלפתא.","cat": "sage"},{"i": 2371,"n": "ר' יסא קוצירא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. חתנו של ר' יוסי ואמר בשמו (ירו', ב\"ב פ\"י ה\"א).","cat": "sage"},{"i": 2372,"n": "יסי","l": "י","b": "הוא יוסי או אסי.","cat": "sage"},{"i": 2373,"n": "יעבץ (2)","l": "י","b": "מובא בד\"א זוטא (ספ\"ק), שנכנס חי לגן עדן בנו של ר' יהודה הנשיא, ומזה נראה כאילו היה לר' יהודה הנשיא בן ושמו יעבץ, ולא נזכר בשום מקום בש\"ס ובמדרשים.","cat": "sage"},{"i": 2374,"n": "ר' יעקב (2)","l": "י","b": "אמורא בבלי בדור השלישי. מובא כמה פעמים בש\"ס א\"ל ההוא מרבנן ור' יעקב שמו. תלמידו של רב יהודה (ע\"ז כ\"ח ע\"ב) ולמד גם אצל רב חסדא (ברכות כט ע\"א). עלה לארץ ישראל ולמד לפני רבי יוחנן (עירובין פ' ע\"א). כנראה שגם קיבל מרב אסי והיה בפטירתו בארץ ישראל (קידושין י\"ג ע\"א). תלמידו היה ר' ירמיה וכשנפטר ר' יעקב נראו כוכבים ביום (מו\"ק כ\"ה ע\"ב).","cat": "sage"},{"i": 2375,"n": "יעקב אבי ר' נחמן","l": "י","b": "אמורא בבלי בדור השני - השלישי. מספרי דדיינא של שמואל (ב\"מ ט\"ז ע\"ב). היה אביו של ר' נחמן בר יעקב. רב נחמן בנו קיבל ממנו (זבחים נ\"ו ע\"א).","cat": "sage"},{"i": 2376,"n": "ר' יעקב אחוה דרב אחא בר יעקב","l": "י","b": "אמורא בדור השלישי - הרביעי. התקיף על דברי ר' אלעאי (סנהדרין ע\"ו ע\"א).","cat": "sage"},{"i": 2377,"n": "ר' יעקב איש כפר חיטייה","l": "י","b": "בדור המעבר שבין התנאים לאמוראים בארץ ישראל. מובא בבבלי, שרבי ור' חייא באו למקום אחד, והלכו לקבל אפיה דצורבא מרבנן מאור עינים, והוא סיפר להם ששמע מפרקא דר' יעקב איש כפר חיטייא (חגיגה ה' ע\"ב).","cat": "sage"},{"i": 2378,"n": "יעקב איש כפר נבוריא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. פעם הורה למול גוי בשבת ושמע ר' חגי והלקהו (ירו', יבמות פ\"ב ה\"ו). וכן מובא, שהורה שדגים טעונים שחיטה ואף על זה הלקהו ר' חגי (תנחומא חקת ט\"ו). דרש נגד המתמנים לדיינות תמורת כסף (ירו', בכורות פ\"ג ה\"ג). דרש בקיסרי והיה שם ר' יצחק בן אלעזר וקילסהו (מדרש שמואל פ\"ח - ו').","cat": "sage"},{"i": 2379,"n": "ר' יעקב ארמנייא","l": "י","b": "אמורא בדור השני. רב נחמן אמר משמו (ירו', גיטין פ\"ו ה\"ה).","cat": "sage"},{"i": 2380,"n": "ר' יעקב בן דוסאי","l": "י","b": "מובא בירושלמי (ב\"ב פ\"ב ה\"ט), והוא ר' יעקב בן דוסתאי.","cat": "sage"},{"i": 2381,"n": "ר' יעקב בן יצחק מבית גיפנין","l": "י","b": "תנא. מובא בתוספתא (אהלות פי\"ח) שהעיד עם ר' יהודה בן יעקב מבית גובריא.","cat": "sage"},{"i": 2382,"n": "ר' יעקב בן קורשאי","l": "י","b": "מובא בקה\"ר (פ\"ד - ו'), והוא ר' יעקב (התנא).","cat": "sage"},{"i": 2383,"n": "רבי יעקב בן קרשי","l": "י","b": "מובא בבבלי (הוריות י\"ג ע\"ב), והוא רבי יעקב (התנא).","cat": "sage"},{"i": 2384,"n": "ר' יעקב בר אבא א'","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב. מובא בירושלמי: \"אמר רב: אע\"ג דנצחני ר' יעקב בר אבא בדינא הלכה וכו'\" (סנהדרין פ\"ז הי\"א).","cat": "sage"},{"i": 2385,"n": "ר' יעקב בר אבא ב'","l": "י","b": "אמורא בבלי בדור החמישי. תלמידם של אביי (ב\"מ כ\"ג ע\"ב) ורבא (פסחים ק\"ג ע\"א).","cat": "sage"},{"i": 2386,"n": "ר' יעקב בר אבדימי","l": "י","b": "מובא ברו\"ר (רפ\"א).","cat": "sage"},{"i": 2387,"n": "ר' יעקב בר אבוה","l": "י","b": "אמורא בבלי בדור החמישי. מובא בבבלי, ששאל דין מאביי (קידושין ל\"א ע\"ב).","cat": "sage"},{"i": 2388,"n": "ר' יעקב בר אבון","l": "י","b": "מובא בירושלמי (נדרים פ\"ג ה\"ב), והוא ר' יעקב בר אבין","cat": "sage"},{"i": 2389,"n": "ר' יעקב בר אביי","l": "י","b": "אמורא בדור הרביעי - החמישי. מסר בשם ר' אחא (ירו', ברכות פ\"ב ה\"ג) ובשם רב ששת (ירו', סוכה פ\"א ה\"ו). יש סבורים שהיה בנו של האמורא אביי.","cat": "sage"},{"i": 2390,"n": "ר' יעקב בר אבין","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר\"ש בן לקיש (ירו', שביעית פ\"ג ה\"ה), בשם ר' חנינא (ירו', פאה פ\"ג) ובשם ר' יוסי בר חנינא (ירו', יבמות פ\"י ה\"ז). בימי ר' ירמיה כבר היה גדול הדור (ירו', מו\"ק פ\"ג ה\"א). ר' זריקן היה כתלמידו (ירו', עירובין פ\"ט ה\"ג).","cat": "sage"},{"i": 2391,"n": "ר' יעקב בר אבינא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. חברו של ר' ברכיה (קה\"ר פ\"א - ד'). אמר בשם רב הונא דציפורן (ירו', שבועות פ\"ו ה\"ג).","cat": "sage"},{"i": 2392,"n": "ר' יעקב בר אדא","l": "י","b": "מובא בבבלי (סנהדרין ס\"ו ע\"ב), וגיר' \"דק\"ס\": ר' יעקב בר אבא.","cat": "sage"},{"i": 2393,"n": "ר' יעקב בר אדא בר עתליה","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי אלעזר. היה חברו של ר' זירא (ירו', גיטין פ\"א ה\"ב).","cat": "sage"},{"i": 2394,"n": "רבי יעקב בר אחא","l": "י","b": "תנא בדור החמישי. חברו של רבי. מכונה \"גדול הדור\" (מו\"ק כ\"ב ע\"ב). מסר בשם רבי (נדרים נ\"ו ע\"ב).","cat": "sage"},{"i": 2395,"n": "ר' יעקב בר אחא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה, שאולי היה תלמידו של ר' יוחנן (ירו', שבועות פ\"א ה\"ג). נראה, שהיה גם תלמידו של ר' שמעון בן לקיש (ירו', סוטה פ\"ד ה\"ג). מסר גם בשם ר' אמי (סנהדרין כ' ע\"ב), בשם ר' אסי (תענית כ\"ז ע\"ב) ובשם ר' זירא (ברכות כ\"ז ע\"א). אך נראה יותר שהיה חברו של ר\"ז (ירו', יבמות פ\"ח ה\"ג). ר' יוסי היה תלמידו (ירו', כלאים פ\"ו ה\"ד).","cat": "sage"},{"i": 2396,"n": "ר' יעקב בר אחא בר אידי","l": "י","b": "אמורא בבלי בדור השני. אמר בשם ר' יהודע בן לוי (ירו', דמאי ספ\"א).","cat": "sage"},{"i": 2397,"n": "ר' יעקב בר אחאי","l": "י","b": "אמורא ארץ ישראלי בדור השני. אמר בשם ר' יונתן (מדרש ילמדנו תשא ס\"ד).","cat": "sage"},{"i": 2398,"n": "ר' יעקב בר אידי (2)","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ר' יהושע בן לוי (יבמות ס' ע\"ב). היה גם תלמידם של ר' חנינא (ברכות מ\"ד ע\"א) ור' אושעיא (שם כ\"ט ע\"ב). בתחילה היה תלמידו המובהק של ר' יוחנן (ירו', ברכות פ\"ב ה\"א) ואח\"כ היה לו לתלמיד - חבר (יבמות צ\"ו ע\"ב, וכן מוכח מחולין נ\"ז ע\"ב רש\"י ד\"ה: לא פרכיס). ר\"ז היה תלמידו (חולין ה' ע\"ב), וקרא לו ולר' שמואל בר נחמני \"שני גדולי הדור\" (חולין צ\"ח ע\"א). גם רב נחמן שלח מבבל לשאול אצלו (ביצה כ\"ה ע\"ב).","cat": "sage"},{"i": 2399,"n": "ר' יעקב בר אלעזר","l": "י","b": "מובא במדרש תהלים (פי\"ט - ב').","cat": "sage"},{"i": 2400,"n": "רבי יעקב בר אמי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי שמעון בן לקיש (ירו', כתובות רפ\"ו).","cat": "sage"},{"i": 2401,"n": "ר' יעקב בר אמי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם ר' אחא (פסדר\"כ קע\"ג ב').","cat": "sage"},{"i": 2402,"n": "ר' יעקב בר בין","l": "י","b": "מובא בירושלמי (שביעית פ\"ג ה\"ג), והוא ר' יעקב בר אבין.","cat": "sage"},{"i": 2403,"n": "רבי יעקב בר ברתיה דאחר","l": "י","b": "מובא בבבלי (סוף חולין), והוא רבי יעקב (תנא בדור הרביעי).","cat": "sage"},{"i": 2404,"n": "ר' יעקב בר ברתיה דרב אחא בר יעקב","l": "י","b": "אמורא בבלי בדור החמישי - הששי. גדל אצל סבו ר' אחא בר יעקב (סוטה מ\"ט ע\"א).","cat": "sage"},{"i": 2405,"n": "ר' יעקב בר גיורי","l": "י","b": "מובא בבבלי (עירובין ס\"ב ע\"א ועוד), שר' יצחק בר יעקב בר גיורי היה תלמידו של ר' יוחנן. ר' יעקב בר גיורי מוזכר בש\"ס רק בהקשר לבנו.","cat": "sage"},{"i": 2406,"n": "רבי יעקב בר דוסתאי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי (כתובות קי\"א ע\"ב). ר' יוסי בר אבין מסר בשמו (ירו', פסחים פ\"ו ה\"ד). כן מסרו משמו \"רבנן דקיסרי\" (ירו', יבמות פי\"א ה\"ז). שמו נשתבש בכמה אופנים: בן דוסאי, בר דסי, בר דסיי, בר דסאיי.","cat": "sage"},{"i": 2407,"n": "ר' יעקב בר דסאיי","l": "י","b": "מובא בירושלמי (סנהדרין רפ\"ד), והוא ר' יעקב בר דוסתאי.","cat": "sage"},{"i": 2408,"n": "ר' יעקב בר דסי","l": "י","b": "מובא בירושלמי (מכות פ\"א ה\"ז), והוא ר' יעקב בר דוסתאי.","cat": "sage"},{"i": 2409,"n": "ר' יעקב בר דסיי","l": "י","b": "מובא בירושלמי (פסחים פ\"ו ה\"ד), והוא ר' יעקב בר דוסתאי.","cat": "sage"},{"i": 2410,"n": "ר' יעקב בר זבדי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' אבהו (ירו', שבועות פ\"ד ה\"ב), כן היה תלמידו של ר' יוסי (ירו', ברכות פ\"ב ה\"ו), ושאל מר' ירמיה (ירו', כלאים פ\"א ה\"א). הניח אחריו שני בנים חכמים: ר' זבדי תלמידו של ר' יונה (ירו', ברכות פ\"ג ה\"ה) ור' יוסי (ירו', פאה פ\"א ה\"ד).","cat": "sage"},{"i": 2411,"n": "רבי יעקב בר חמא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם ר' אלעזר (ירו', בכורים פ\"ב ה\"ב). כך מובא ב\"סה\"ד\" ולפנינו הגיר' יעקב בר אחא.","cat": "sage"},{"i": 2412,"n": "ר' יעקב בר חנינא","l": "י","b": "תנא שזמנו אינו ידוע. מובא בבבלי (שבת ע\"ט ע\"ב). ר' אחא מסר בשמו.","cat": "sage"},{"i": 2413,"n": "ר' יעקב בר יוסי","l": "י","b": "מובא בתנחומא (בהעלותך י\"א).","cat": "sage"},{"i": 2414,"n": "ר' יעקב בר ינאי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. ר' נחמיה אמר משמו (מס' סופרים פט\"ז ה\"ג).","cat": "sage"},{"i": 2415,"n": "ר' יעקב בר יעקב","l": "י","b": "מובא ב\"ילקוט\" (תהלים רמז תר\"ל), ונראה שאולי צ\"ל: ר' יעקב ברה דבת יעקב.","cat": "sage"},{"i": 2416,"n": "ר' יעקב בר יצחק","l": "י","b": "מובא בירושלמי (חלה פ\"ב ה\"א).","cat": "sage"},{"i": 2417,"n": "ר' יעקב בר נחמני","l": "י","b": "אמורא בבלי בדור השני. תלמידו של שמואל (חולין נ' ע\"ב).","cat": "sage"},{"i": 2418,"n": "רבי יעקב בר סוסי","l": "י","b": "מובא בירושלמי (מגילה ספ\"ב), והוא ר' יעקב בר סוסיי.","cat": "sage"},{"i": 2419,"n": "ר' יעקב בר סוסיי","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר' אסי (ירו', פסחים פ\"ד ה\"ט). שמו נשתבש בכמה אופנים: סוסיי, סוסי, סיסי.","cat": "sage"},{"i": 2420,"n": "רבי יעקב בר סיסי","l": "י","b": "מובא בירושלמי (חגיגה פ\"ג ה\"ח), והוא ר' יעקב בר סוסיי.","cat": "sage"},{"i": 2421,"n": "ר' יעקב בר פליטי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. ר' מנא היה שושביניה (ירו', סוכה פ\"ב ה\"ה).","cat": "sage"},{"i": 2422,"n": "ר' יעקב ברה דבת יעקב","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. פעם ביקשו ר' זירא שיכנס לר' יעקב בר אידי וישאל ממנו דבר הלכה (עירובין פ' ע\"א). ר' ברכיה מסר בשמו (ירו', מע\"ש פ\"ה ה\"א). ורש\"י פירש (עירובין שם): \"אביו לא היה הגון לפיכך לא הזכירו\".","cat": "sage"},{"i": 2423,"n": "ר' יעקב ברה דבת שמואל","l": "י","b": "אמורא בבלי בדור השלישי. מובא בבבלי (ברכות כ\"ה ע\"ב). החכם באלי אמר משמו (שם). נראה, שהוא אחיו של רב מרי ברה דבת שמואל.","cat": "sage"},{"i": 2424,"n": "ר' יעקב בריה דרב יהודה בר יחזקל","l": "י","b": "מובא במ\"ר (פי\"ד - ג'), וט\"ס וצ\"ל: ר' יצחק בריה דרב יהודה בר יחזקל.","cat": "sage"},{"i": 2425,"n": "ר' יעקב בריה דר' אחא בר יעקב","l": "י","b": "אמורא בבלי בדור החמישי. אביו שלחו ללמוד לפני אביי. כשחזר לא השביעו ידיעותיו את רצון אביו, ואביו הלך במקומו לאביי (קדושין כ\"ט ע\"ב).","cat": "sage"},{"i": 2426,"n": "ר' יעקב גבולייא","l": "י","b": "אמורא ארץ ישראלי בדור השני. היה תלמידו של רבי יוחנן (ירו', יבמות פ\"ח ה\"ב), ומסר בשם ר' חנינא (ירו', חלה פ\"ג ה\"א). שמו השתבש בכמה אופנים: גבליא, גביליא.","cat": "sage"},{"i": 2427,"n": "ר' יעקב גביליא","l": "י","b": "מובא בקה\"ר (פ\"א - ד'), והוא ר' יעקב גבולייא.","cat": "sage"},{"i": 2428,"n": "ר' יעקב גבליא","l": "י","b": "מובא (ירו', יבמות פ\"ח ה\"ב), והוא ר' יעקב גבולייא.","cat": "sage"},{"i": 2429,"n": "ר' יעקב גרוסה","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. ר' שמואל בר נחמני כשביקר את ר' יעקב גרוסה, היה ר' זירא נטמן לשמוע היאך קורא קריאת שמע.","cat": "sage"},{"i": 2430,"n": "ר' יעקב דכפר חנן","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ר' שמעון בן לקיש (ירו', ברכות פ\"ה ה\"ב). שמו נזכר פעמים בב\"ר ובמדרש שמואל.","cat": "sage"},{"i": 2431,"n": "ר' יעקב דקיסרין","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. ר' נחמיה ור' נחמן דיפו אמרו משמו (ויק\"ר פ\"ו - ה'), וכן גם ר' מנחמא (מד' שמואל פט\"ז - א').","cat": "sage"},{"i": 2432,"n": "ר' יעקב דרומאי","l": "י","b": "ע\"ע ר' יעקב דרומייא.","cat": "sage"},{"i": 2433,"n": "ר' יעקב דרומייא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי אלעזר (ירו', סוכה פ\"ד ה\"ב) ושל ר' אסי (ירו', תרומות פ\"ג ה\"א; מובא ר' יוסי, אך הוא רבי אסי).","cat": "sage"},{"i": 2434,"n": "ר' יעקב דרומנא","l": "י","b": "הוא ר' יעקב דרומייא.","cat": "sage"},{"i": 2435,"n": "יעקב הדייבא","l": "י","b": "אמורא בבלי בדור השלישי - הרביעי. שאל מרב חסדא (ב\"ב כ\"ו ע\"ב ופרש\"י: מן הדייב היה).","cat": "sage"},{"i": 2436,"n": "ר' יעקב מנהר פקוד","l": "י","b": "אמורא בבלי בדור הששי - השביעי. תלמידו של רבינא, ישב לפניו ומסר בשם רב הונא בריה דר' יהושע (סנהדרין ס\"ט ע\"א). כן מסר בשם רבא (כתובות ל\"ג ע\"ב).","cat": "sage"},{"i": 2437,"n": "יעקב מעפרתים","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. מסר בשם רבי. ר' חוניא (ואולי זה רב הונא) מסר משמו (ירו', שבת פי\"ד ה\"ג).","cat": "sage"},{"i": 2438,"n": "יעקב מצעה","l": "י","b": "אמורא שאין לקבוע זמנו ומקומו. שאל לר' יהודה (מגילה כ\"ג ע\"א). וגיר' הגמרא (שם): יעקב מינאה, ותוספות גורסים: מצעה, כי יעקב מינאה היה מין ורשע (עיין ע\"ז י\"ז ע\"א תד\"ה: ויעקב). שאל גם מרב (חולין פ\"ד ע\"א), וגם שם גיר' הגמרא: יעקב מינאה (ולפי תוספות צריך לגרוס \"מצעה\").","cat": "sage"},{"i": 2439,"n": "ר' יעקב עמסונייא","l": "י","b": "מובא בירושלמי (ב\"מ פ\"ד ה\"ז), ומפרש המשנה שם.","cat": "sage"},{"i": 2440,"n": "יעקב קרחה","l": "י","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. שונה ברייתות (שבת קל\"ט ע\"ב; חולין כ\"ב ע\"ב).","cat": "sage"},{"i": 2441,"n": "יעקב קרחינאה","l": "י","b": "מובא בבבלי (עירובין פ\"ו ע\"א), ונראה שהוא יעקב קרחה.","cat": "sage"},{"i": 2442,"n": "רב יצחק","l": "י","b": "מובא בירושלמי (שבועות פ\"ד ה\"א), והוא אבוה דשמואל בר יצחק (ע\"ע).","cat": "sage"},{"i": 2443,"n": "רבי יצחק","l": "י","b": "תנא בבלי בדור הרביעי - החמישי. מושבו היה בעיר נהר פקוד, יחד עם חברו ר' נתן (ירו', נדרים פ\"ו ה\"ח). שניהם סייעו שחנניה בן אחי יהושע יפסיק לעבר שנים בחו\"ל (שם). מובא יחד עם רבי ור' נתן בברייתא (ברכות מ\"ח ע\"ב). מובא יותר מעשרים פעם במכילתא.","cat": "sage"},{"i": 2444,"n": "ר' יצחק","l": "י","b": "ע\"ע ר' יצחק בר אחא, וע\"ע ר' יצחק בר פנחס.","cat": "sage"},{"i": 2445,"n": "יצחק אבי רב נחמן","l": "י","b": "בנו רב נחמן. מגדולי אמוראי בבל בדור השני - השלישי. יצחק, אביו של ר\"נ זה, לא נסמך (תענית כ\"א ע\"ב רש\"י).","cat": "sage"},{"i": 2446,"n": "ר' יצחק איש כפר עכו","l": "י","b": "אמורא ארץ ישראלי בדור השני. תלמידו של ר' יוחנן (ע\"ז ז' ע\"ב).","cat": "sage"},{"i": 2447,"n": "רבי יצחק בן אלעא","l": "י","b": "מובא בבבלי (פסחים קי\"ג ע\"ב), וצ\"ל: ר' יצחק בן אלעזר.","cat": "sage"},{"i": 2448,"n": "רבי יצחק בן אלעזר","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יוחנן (ירו', דמאי פ\"ב ה\"א, ושם ר' יצחק בר טבליי והוא ר' יצחק בן אלעזר פסחים קי\"ג ע\"ב). וכשנפטר ר' יוחנן הספידו ופתח: \"קשה היום לישראל וכו'\" (מו\"ק כ\"ה ע\"ב). כן קיבל מרבי אלעזר (ירו', קידושין פ\"ג ה\"א). היה חברם של גדולי תלמידי ר' יוחנן: \"יתיב ר' חייא בר אבא ור' אמי ור' יצחק נפחא, אקלעא דר' יצחק בן אלעזר\" (מו\"ק כ' ע\"א).","cat": "sage"},{"i": 2449,"n": "ר' יצחק בן אלעזר ב'","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. רבו של רבי מנא (ירו', דמאי פ\"ב ה\"א). מסרו בשמו: ר' יוסי בן יוסי (ירו', תרומות פ\"א ה\"ה) ור' תנחומא (ירו', בכורים פ\"א ה\"ג). פעם אחת ראה עצם, והטמינה באדמה, שלא יכשלו בה, ונתגלגלה מאליה למקום אחר, ושוב התגלגלה, ואמר: עצם זו נועדה לבצע שליחות, לבסוף עבר פקיד המלכות ונכשל בה ונהרג, ומצאו אצלו מסמכים נגד היהודים בקיסרין (ב\"ר פ\"י - ז).","cat": "sage"},{"i": 2450,"n": "ר' יצחק בן זעירא","l": "י","b": "אמורא שאין לקבוע זמנו ומקומו. דבריו הובאו אחרי שמואל (שבת כ' ע\"ב). מפורסמת אמרתו: \"תלמידי חכמים כיון שאומרים דבר שמועה מפיהם בעולם הזה, שפתותיהם דובבות בקבר\" (יבמות צ\"ז ע\"א).","cat": "sage"},{"i": 2451,"n": "רבי יצחק בן חקולא","l": "י","b": "ע\"ע ר' יצחק בן חקלא, וע\"ע רבי יצחק בן אלעזר.","cat": "sage"},{"i": 2452,"n": "ר' יצחק בן חקולי","l": "י","b": "מובא בירושלמי (פאה פ\"א ה\"ד), והוא ר' יצחק בן חקלא.","cat": "sage"},{"i": 2453,"n": "ר' יצחק בן חקלא","l": "י","b": "הוא רבי יצחק בן אלעזר [כצ\"ל] (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 2454,"n": "רבי יצחק בן טבלא","l": "י","b": "הוא רבי יצחק בן חקלא, הוא רבי יצחק בן אלעזר [כצ\"ל] (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 2455,"n": "ר' יצחק בן טבלאי","l": "י","b": "מובא בבבלי (יומא ל\"ט ע\"ב), והוא ר' יצחק בן טבלא.","cat": "sage"},{"i": 2456,"n": "ר' יצחק בן פנחס","l": "י","b": "תנא מאחרוני התנאים בדור החמישי. רב יהודה מסר משמו (חולין כ\"ז ע\"ב). מאמרו מובא אחרי מאמרו של איסי בן יהודה (אבות דר\"נ פכ\"ט - ז'): \"כל מי שיש בידו מדרש ואין בידו הלכות, לא טעם טעם של חכמה, יש בידו הלכות ולא מדרש, לא טעם טעם יראת חטא\" (פסחים קי\"ד ע\"א, ברשב\"ם: \"רבי יצחק סתם באגדתא הוא רבי יצחק בן פנחס\").","cat": "sage"},{"i": 2457,"n": "ר' יצחק בן פרנך","l": "י","b": "מובא בכלה רבתי (רפ\"ג). מאמרו: \"כל עונות של אדם חקוקין לו על עצמותיו\".","cat": "sage"},{"i": 2458,"n": "ר' יצחק בן תרדיון","l": "י","b": "מובא במדרש תהלים (פל\"א - ו'), ואולי צ\"ל: ר' יצחק בר מריון.","cat": "sage"},{"i": 2459,"n": "ר' יצחק בר אבא","l": "י","b": "אמורא בדור הרביעי. יתכן שהיה מארץ ישראל, שכן מכונה בתואר \"רבי\" ומצינו אותו בבבל. היה גדול מאביי (זבחים ה' ע\"א).","cat": "sage"},{"i": 2460,"n": "ר' יצחק בר אבא בר מחסיא","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב. ישב יחד עם רב חננאל לפני רב (ירו', מגילה פ\"ב ה\"ב).","cat": "sage"},{"i": 2461,"n": "רבי יצחק בר אבדימי א'","l": "י","b": "תנא בדור החמישי, והוא ר' יצחק רובה (ירו', שבת פ\"ג ה\"ג), או ר' יצחק רבה (ירו', ברכות פ\"ה ה\"ב). מסר משום רבי (ירו', ר\"ה פ\"א ה\"ג) או משום רבינו, והכוונה לרבי (יבמות מ\"ה ע\"א רש\"י). היה ה\"תנא\" (שונה משניות וברייתות) בישיבתו של רבי (ירו', מע\"ש רפ\"ה). ורבי אומר: \"שאלון לרבי יצחק רובא, דבחנת ליה כל מתניתא\" (שם) ומפרש \"פני משה\": \"כלומר, אע\"פ שאני הוא הסותם המשנה, מ\"מ מסרתי לו ההבחנה של כל המשנה שהוא יבחין לסדר אותן על הסדר\". היה מקורב מאוד לרבי, וליווהו אפילו לבית המרחץ (שבת מ' ע\"ב). אחד מתלמידיו היה רב (חולין ק\"י ע\"א). מסרו בשמו ר' יעקב בר אידי (ירו', ברכות פ\"ה ה\"ב) ור' אבא בר יעקב (שם פ\"ו ה\"א).","cat": "sage"},{"i": 2462,"n": "רב יצחק בר אבדימי ב'","l": "י","b": "אמורא בבלי בדור השני - השלישי. היה תלמידו של רב (ברכות ל' ע\"ב). תוספות כתבו: \"דעל כרחך רב יצחק בר אבדימי הוא תלמידו של רב\" (ב\"ב פ\"ז ע\"א ד\"ה: מי). חברו של רב חסדא, ונחלק עמו תדיר באגדה ובעניני מקראות (סנהדרין נ\"ו ע\"ב). רבא קבל ממנו (יבמות ג' ע\"א).","cat": "sage"},{"i": 2463,"n": "ר' יצחק בר אבודימי","l": "י","b": "מובא בבבלי (יבמות מ\"ה ע\"א), והוא רבי יצחק בר אבדימי א'.","cat": "sage"},{"i": 2464,"n": "רב יצחק בר אבין","l": "י","b": "אמורא בבלי שאין לקבוע את זמנו המדוייק. מובא כמה פעמים בש\"ס (קידושין ע\"ז ע\"א). בד\"כ דבריו בענייני הלכה, ומבהיר דברי הקודמים לו.","cat": "sage"},{"i": 2465,"n": "רב יצחק בר אדא","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב (חולין ט\"ו ע\"ב).","cat": "sage"},{"i": 2466,"n": "ר' יצחק בר אוריון","l": "י","b": "אמורא ארץ ישראלי, ומשמע שהיה בדור הרביעי, דור ר' ירמיה (ירו', שבת פ\"י ה\"ו).","cat": "sage"},{"i": 2467,"n": "ר' יצחק בר אחא","l": "י","b": "אמורא ארץ ישראלי בדור השני. כל ר' יצחק האמורא המוזכר בש\"ס בענייני הלכה הוא ר' יצחק בר אחא (פסחים קי\"ד ע\"א רש\"י ורשב\"ם). היה תלמידם של ר' יוחנן (ברכות ל\"ה ע\"ב), ור' שמעון בן לקיש (ע\"ז י\"ד ע\"א) ור' אלעזר (ע\"ז ע' ע\"ב). היה גם בבבל, ורב חסדא שאל ממנו (ברכות כ\"ז ע\"א).","cat": "sage"},{"i": 2468,"n": "רבי יצחק בר איסטייה","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ריש לקיש (ירו', יבמות פ\"א ה\"א).","cat": "sage"},{"i": 2469,"n": "ר' יצחק בר אלישיב","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בענייני הלכה (ירו', סוכה פ\"א הי\"א). ר' מני היה תלמידו המובהק (תענית כ\"ג ע\"ב). היה מפורסם כאדם גדול ובעל מופת (שם). כשנפטר פרצה מכת גניבות, שכן בזכותו לא באו גנבים (מו\"ק כ\"ה ע\"ב). ובירושלמי מובא, שבמותו נעקרו שבעים משקופים בגליל, שהיו תלויים בזכותו (ע\"ז פ\"ג ה\"א).","cat": "sage"},{"i": 2470,"n": "ר' יצחק בר אמי","l": "י","b": "אמורא בבלי בדור השלישי. תלמידו של רב חסדא (מו\"ק י' ע\"ב). ביקר את רב חסדא בביתו (שבת קכ\"ח ע\"א) והיה בפטירתו (מו\"ק כ\"ה ע\"א). ר\"ז מסר בשמו (חולין מ\"ט ע\"א). היה ענו ונוח לבריות (תענית ט\"ז ע\"א רש\"י). היה בקי גדול במקרא (סנהדרין ס' ע\"א).","cat": "sage"},{"i": 2471,"n": "רב יצחק בר אשי","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב (פסחים מ\"ה ע\"ב).","cat": "sage"},{"i": 2472,"n": "רב יצחק בר אשיאן","l": "י","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (סוכה מ\"ב ע\"א). רב אידי בר אבין היה תלמידו (ברכות י\"ד ע\"א).","cat": "sage"},{"i": 2473,"n": "רב יצחק בר ביזנא","l": "י","b": "אמורא בבלי בדור השני. תלמידו של שמואל (ירו', שקלים פ\"ח ה\"ב).","cat": "sage"},{"i": 2474,"n": "רב יצחק בר ביסנא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי. נראה, שהיה גם תלמידו של רבי אסי (זבחים כ' ע\"א). שאל את ר' ביבי (ירו', שקלים פ\"ח ה\"א). מתיב על דברי רבי זירא (זבחים מ\"ג ע\"ב). מובא מעשה שאבדו לו בשבת מפתחות דבית המדרש ושאל לר' פדת, בנו של רבי אלעזר (יבמות קי\"ג ע\"ב).","cat": "sage"},{"i": 2475,"n": "ר' יצחק בר בר חנא","l": "י","b": "אמורא בבלי בדור השני. סיפר: \"אנא חזיתיה לזעירי, דאזל לגבי רב חייא בר אשי תלמידו\" (יומא ע\"ז ע\"ב).","cat": "sage"},{"i": 2476,"n": "רב יצחק בר גופתא","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' מנא (ירו', שבת פ\"ג ה\"ה).","cat": "sage"},{"i": 2477,"n": "רב יצחק בר גיורי","l": "י","b": "מובא בבבלי (תענית כ\"ט ע\"ב), והוא ר' יצחק בר יעקב בר גיורי.","cat": "sage"},{"i": 2478,"n": "ר' יצחק בר חייא","l": "י","b": "מובא בויק\"ר (פכ\"ו - ז').","cat": "sage"},{"i": 2479,"n": "ר' יצחק בר חלוב","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. גדול הדור בימי ר' אמי: \"ור' אמי משדר להו לקמיה דרבי יצחק בר חלוב, דמורי בה להיתירא משום ר' יהושע בן לוי\" (חולין צ\"ט ע\"ב).","cat": "sage"},{"i": 2480,"n": "ר' יצחק בר חלוקה","l": "י","b": "מובא בפדר\"כ (ק\"פ), והוא זהה לר' יצחק בר חלקיה.","cat": "sage"},{"i": 2481,"n": "ר' יצחק בר חלקיה","l": "י","b": "מובא בויק\"ר (פ\"ל - ג'), והוא זהה לר' יצחק בר חלוקה. ר' יצחק בר חמא - אמורא ארץ ישראלי בדור החמישי. מובא במדרש תהלים (פ\"ב - ו'). ומצינו: ר' יצחק הכהן בר חמא בשם ר' חלקיה (פס' רבתי פ' אנכי מנחמכם ס\"ג).","cat": "sage"},{"i": 2482,"n": "רב יצחק בר חנינא","l": "י","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (כתובות ד' ע\"ב).","cat": "sage"},{"i": 2483,"n": "ר' יצחק בר חנינא בר פפא בר יצחק","l": "י","b": "מובא בפס' רבתי (ס\"פ ויקח אליהו כ\"ג).","cat": "sage"},{"i": 2484,"n": "ר' יצחק בר חנניה","l": "י","b": "מובא בבבלי (נדרים ל\"ח ע\"ב), והוא ר' יצחק בר חנינא תלמידו של רב הונא.","cat": "sage"},{"i": 2485,"n": "ר' יצחק בר חקורי","l": "י","b": "מובא בב\"ר (פנ\"ד - ה').","cat": "sage"},{"i": 2486,"n": "רבי יצחק בר טבליי","l": "י","b": "מובא בירושלמי (דמאי פ\"ב ה\"א), והוא רבי יצחק בן טבלא.","cat": "sage"},{"i": 2487,"n": "ר' יצחק בר יונתן","l": "י","b": "אמורא בבלי בדור השני. ישב יחד עם רב הונא ופסק בדיני נדה (ירו', נדה ספ\"ב).","cat": "sage"},{"i": 2488,"n": "ר' יצחק בר יוסי (2)","l": "י","b": "מובא בבבלי (נדה ס\"ה ע\"ב), והוא ר' יצחק בר יוסף.","cat": "sage"},{"i": 2489,"n": "ר' יצחק בר יוסי מחוזאה","l": "י","b": "מובא ב\"זוהר\" (נח ס\"ג).","cat": "sage"},{"i": 2490,"n": "רב יצחק בר יוסף","l": "י","b": "אמורא בדור השלישי - הרביעי. תלמידם המובהק של ר' ירמיה (חולין מ\"ח ע\"א), ורבי אבהו (פסחים ע\"ב ע\"א). היה מ\"הנחותי\" שהעבירו את תורת ארץ ישראל לבבל, ועמד בשורה אחת עם רב דימי, רבין ורב שמואל בר יצחק (ע\"ז ע\"ג ע\"א), ואביי סבר שהיה קטן מרבין, שרבין בר סמכא והוא אינו בר סמכא, ורבין ישנו בחזרה (מצוי כל שעה לפני ר' יוחנן) והוא אינו בחזרה (יבמות ס\"ד ע\"ב). מכונה גם יצחק סומקא (שם). מסר משום ר' יוחנן (שבת נ\"ח ע\"א).","cat": "sage"},{"i": 2491,"n": "ר' יצחק בר יעקב בר גוריא","l": "י","b": "הוא ר' יצחק בר יעקב בר גיורי.","cat": "sage"},{"i": 2492,"n": "רב יצחק בר יעקב בר גיורי","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. (נראה שלא נסמך ולכן מכונה \"רב\" ולא \"רבי\"). תלמידו של רבי יוחנן, ונהג לשלוח משמיה דר' יוחנן מארץ ישראל לבבל (עירובין ס\"ב ע\"א).","cat": "sage"},{"i": 2493,"n": "ר' יצחק בר כהנא","l": "י","b": "מובא בירושלמי (שבת פ\"ח ה\"א), ואולי צ\"ל: ר' יצחק בר ביסנא, וכך מובא במקום אחר (ירו', שקלים פ\"ח ה\"א).","cat": "sage"},{"i": 2494,"n": "ר' יצחק בר מנחם","l": "י","b": "מובא במדרש תהלים (ספל\"ד).","cat": "sage"},{"i": 2495,"n": "ר' יצחק בר מרי","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' יוסי בר אבין. ואמר לפניו משם ר' יוחנן (ירו', ברכות פ\"ו ה\"א).","cat": "sage"},{"i": 2496,"n": "ר' יצחק בר מריון","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם רבי חנינא (ירו', יבמות ספ\"ו) ושאל מרב אלעזר (ירו', סוכה פ\"ב ה\"ה). ר' אבהו מסר בשמו (ירו', יבמות שם). כן מסר בשמו ר' יונתן בר חגי (קה\"ר פ\"ט - י\"ב).","cat": "sage"},{"i": 2497,"n": "ר' יצחק בר משרשיא","l": "י","b": "מובא בירושלמי (שבת פי\"ב ה\"ד) שאמר בשם רבנן דתמן. ואולי הוא זהה לר' יצחק בריה דרב משרשיא.","cat": "sage"},{"i": 2498,"n": "ר' יצחק בר מתנה","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של ר' יוחנן. מובא רק פעם אחת בירושלמי (ע\"ז פ\"ג הי\"א).","cat": "sage"},{"i": 2499,"n": "ר' יצחק בר נחמן","l": "י","b": "מובא בירושלמי (סוכה פ\"ג ה\"ו), והוא ר' יצחק בר נחמני.","cat": "sage"},{"i": 2500,"n": "ר' יצחק בר נחמני","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. היה תלמידו המובהק של ר' יהושע בן לוי (חולין מ\"ה ע\"א) וכן היה תלמידם של ר' אושעיא (שבת ל\"ז ע\"א) ור' שמעון בן לקיש (בכורות י\"ג ע\"א). נראה כתלמידו של ר' אלעזר (חולין מ\"ה ע\"א). גם ר' אלעזר שאל ממנו (ירו', יבמות פ\"ח ה\"א). יתכן שהיה בבבל, שכן מצינו: \"אמר ר' יצחק בר נחמני אמר שמואל\" (ר\"ה י\"ג ע\"ב). חברו היה ר' יעקב בר אידי, ושניהם היו פרנסים (ירו', סוף פאה). ומשמו אמר ר' יעקב בר אחא (ירו', כלאים פ\"ב ה\"ג).","cat": "sage"},{"i": 2501,"n": "רבי יצחק בר נפתלי","l": "י","b": "אמורא בבלי בדור הששי. מובא בבבלי, ש\"אמר לרבינא 'הכי אמרינן משמיה דרבא כוונתך'\" (כתובות צ\"ו ע\"א).","cat": "sage"},{"i": 2502,"n": "ר' יצחק בר סברין","l": "י","b": "אמורא שאין לקבוע זמנו ומקומו. מובא בבבלי (זבחים ט' ע\"א).","cat": "sage"},{"i": 2503,"n": "ר' יצחק בר סימון","l": "י","b": "מובא באיכ\"ר (פ\"א פסוק דרכי ציון).","cat": "sage"},{"i": 2504,"n": "ר' יצחק בר פנחס","l": "י","b": "אמורא ארץ ישראלי בדור השני. כל ר' יצחק סתם באגדתא, הוא ר' יצחק בר פנחס (פסחים קי\"ד ע\"א רש\"י ורשב\"ם). היה תלמידם של ר' יוחנן (שבת קמ\"ט ע\"ב) ור' אלעזר (סנהדרין פ\"ב ע\"א). היה גם בבבל ור' נחמן שאל ממנו (תענית ה' ע\"א).","cat": "sage"},{"i": 2505,"n": "ר' יצחק בר קפרא","l": "י","b": "מובא בקה\"ר (פ\"ט - ח'), ונראה שיש איזה ט\"ס בשם.","cat": "sage"},{"i": 2506,"n": "ר' יצחק בר קצצתה","l": "י","b": "מובא בירושלמי (ר\"ה פ\"א ה\"א), והוא ר' יצחק בר קצרתה.","cat": "sage"},{"i": 2507,"n": "ר' יצחק בר קצרתה","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם ר' יונה (מד' שמואל פכ\"ו - ה'). שמו בא בשיבוש (ירו', ר\"ה פ\"א ה\"א): ר' יצחק בר קצצתה, והגיר' ב\"יוחסין\" וב\"סה\"ד\": \"ר' יצחק קריצפא\".","cat": "sage"},{"i": 2508,"n": "ר' יצחק בר רדיפא","l": "י","b": "אמורא בבלי שעלה לארץ ישראל. היה בדור השלישי - הרביעי. תלמידו של רב הונא (שבת כ\"ג ע\"ב) ורבי אמי (כתובות ק\"ו ע\"א). שאל לר' ירמיה (שביעית פ\"ט ה\"ד).","cat": "sage"},{"i": 2509,"n": "רב יצחק בר שילא","l": "י","b": "אמורא בבלי בדור הרביעי. תלמידו של ר' מתנא, שאמר משום רב חסדא (קידושין ל\"ב ע\"א).","cat": "sage"},{"i": 2510,"n": "רב יצחק בר שמואל","l": "י","b": "מובא בבבלי (כתובות ג' ע\"א), והוא כנראה ט\"ס, וצ\"ל: רב יצחק בר שמואל בר מרתא.","cat": "sage"},{"i": 2511,"n": "רב יצחק בר שמואל בר מרתא","l": "י","b": "אמורא בבלי בדור השני - השלישי. אביו רב שמואל בר מרתא, היה בן דודו של רב. רב יצחק היה תלמידו המובהק של רב (חולין ק\"ו ע\"ב). גם אביו רב שמואל בר מרתא קיבל מרב (פסחים קי\"ג ע\"ב). אחר פטירת רב, היה לתלמידו של רב הונא (כתובות כ\"א ע\"ב). ישב גם לפני רב כהנא ב' (נדה כ\"ו ע\"ב) ולפני רב נחמן (חולין ל\"ה ע\"א). ר' זירא היה תלמידו (חולין ל' ע\"ב). כן קיבלו ממנו: ר' אבא (כתובות כ\"א ע\"ב) ורבה בר בר חנה (גיטין כ\"ח ע\"א).","cat": "sage"},{"i": 2512,"n": "רב יצחק ברבי","l": "י","b": "מובא בבבלי (נדרים כ\"ט ע\"ב) וצ\"ל: רב יצחק בר יוסף.","cat": "sage"},{"i": 2513,"n": "רב יצחק בריה דרב","l": "י","b": "מובא בירושלמי (ברכות פ\"ג ה\"א), ונראה שיבוש בשם.","cat": "sage"},{"i": 2514,"n": "רב יצחק בריה דרב אידי","l": "י","b": "מובא בבבלי (ברכות ד' ע\"א).","cat": "sage"},{"i": 2515,"n": "רב יצחק בריה דרב יהודה","l": "י","b": "אמורא בבלי בדור השלישי. בנו של האמורא המפורסם רב יהודה; אביו לימדו תורה (פסחים ק\"ד ע\"ב) והיה רבו המובהק (עירובין צ\"ז ע\"א). כן למד לפני רב הונא (נדה י\"ז ע\"ב). ולפני רמי בר חמא ועזבו, ובא לפני רב ששת (זבחים צ\"ו ע\"ב). עולא איקלע לפומבדיתא ושאל לרב יהודה: מדוע ר' יצחק בנו טרם התחתן (קדושין ע\"א ע\"ב). בת בנו חומא, התחתנה עם אביי (כתובות ס\"ה ע\"א).","cat": "sage"},{"i": 2516,"n": "רב יצחק בריה דרב משרשיא","l": "י","b": "אמורא בבלי בדור החמישי - הששי. היה מחשובי הדור בזמן רב פפא: \"שאני רב יצחק בריה דרב משרשיא דאדם חשוב הוא\" (ע\"ז ח' ע\"ב). פעם נזדמן לבית רב אשי והסביר שם דין (חולין ק\"ד ע\"ב), ורב אשי הוסיף אחרי דבריו (מנחות כ\"ד ע\"ב).","cat": "sage"},{"i": 2517,"n": "רב יצחק בריה דרבה בר בר חנה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. אולי היה תלמידו של רבא (סוכה מ\"ג ע\"ב). נשא לאשה את חומה, ולאחר שנפטר התחתן עמה אביי (יבמות ס\"ד ע\"ב).","cat": "sage"},{"i": 2518,"n": "ר' יצחק בריה דרבי חייא כהנא","l": "י","b": "כן גורסים התוספות (בכורות י\"ט ע\"א ד\"ה: איש), ובירושלמי שלפנינו הגיר': ר' יצחק בריה דר' חייא כתובה.","cat": "sage"},{"i": 2519,"n": "ר' יצחק בריה דר' חייא ברובה","l": "י","b": "מובא בירושלמי (תרומות פ\"ח ה\"ד), ונראה שצ\"ל: ר' יצחק בריה דר' חייא כתובה, כמו שמובא במקום אחר (ירו', פסחים פ\"א ה\"ח).","cat": "sage"},{"i": 2520,"n": "ר' יצחק בריה דר' חייא כתובה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. \"קרבן העדה\" מפרש: \"כך שמו\" (ירו', פסחים פ\"א ה\"ח). חברו של ר' יודן. ר' יודן בא לבקרו באבל משפחתי (ירו', ברכות פ\"ג ה\"א).","cat": "sage"},{"i": 2521,"n": "ר' יצחק בריה דר' חייא מטיבא","l": "י","b": "מובא בירושלמי (יבמות פי\"ג הי\"ג), והוא ר' יצחק בריה דר' חייא כתובה.","cat": "sage"},{"i": 2522,"n": "יצחק דבי ר' ינאי","l": "י","b": "מובא בבבלי (יומא פ\"ו ע\"א), וגיר' \"דק\"ס\": יצחק בריה דר' אמי.","cat": "sage"},{"i": 2523,"n": "ר' יצחק דהבן","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. כשעבדיו ברחו, בא לברר דין אצל רבי אמי (ירו', גיטין פ\"ד ה\"ו).","cat": "sage"},{"i": 2524,"n": "ר' יצחק דיהבא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מצינו ששאל לר' יוחנן (ירו', ביצה פ\"א ה\"ט).","cat": "sage"},{"i": 2525,"n": "ר' יצחק דמן קרטיגנין","l": "י","b": "מובא בבבלי שאמר: \"הני תשע דראש השנה כנגד מי? כנגד תשעה אזכרות שאמרה חנה בתפלתה\" (ברכות כ\"ט ע\"א).","cat": "sage"},{"i": 2526,"n": "ר' יצחק הבבלי","l": "י","b": "מובא בב\"ר (פמ\"ג - ו'), שאמר מלכי צדק נולד מהול.","cat": "sage"},{"i": 2527,"n": "ר' יצחק הכהן בר חמא","l": "י","b": "מובא בפס' רבתי (פ' אנכי מנחמכם ס\"ג). ונראה שהוא זהה לר' יצחק בר חמא.","cat": "sage"},{"i": 2528,"n": "יצחק כפתורא","l": "י","b": "מובא ב\"זוהר\" (תצוה קפז).","cat": "sage"},{"i": 2529,"n": "ר' יצחק מגדלאה","l": "י","b": "אמורא ארץ ישראלי בדור הראשון. מפרש כוונות המשנה (ב\"מ כ\"ה ע\"א; נדה ל\"ג ע\"א). מסר בשם רבי יהודה הנשיא (ב\"ר פצ\"ג - ז'). רבי יוחנן דן במאמרו (נדה כ\"ז ע\"ב).","cat": "sage"},{"i": 2530,"n": "ר' יצחק מגדלים","l": "י","b": "מובא בפס' רבתי (פ' ותשלם), וצ\"ל: ר' יצחק מגדלאה.","cat": "sage"},{"i": 2531,"n": "ר' יצחק נפחא","l": "י","b": "אמורא ארץ ישראלי בדור השני - השלישי. נראה, שהיה תלמידו של ר' יוחנן (ב\"מ כ\"ד ע\"ב). אולי אף שמע מר' אלעזר (מו\"ק כ\"ד ע\"ב). רבי שמעון בן לקיש החשיבו מאד ואמר עליו: \"טבא דנפחא, מדבר נפחא\" (טובים דברי ר' יצחק נפחא מדברי בן נפחא הוא ר' יוחנן שנקרא בר נפחא על שם יופיו) (סנהדרין צ\"ו ע\"א). חבריו היו ר' אבהו ור' חייא בר פפי (ב\"ק קי\"ז ע\"ב). ר' אמי ור' אסי ישבו לפניו (ב\"ק ס' ע\"ב). היה בבבל ודרש אפתחא דריש גלותא (שבת קכ\"ו ע\"ב), ושוב דרש אקלעא דריש גלותא, שמע ר' ששת, איקפד, אמר: \"אטו דידיה היא וכו'\" (מו\"ק כ\"ד ע\"ב). היה זהיר במעשים טובים (חולין ק\"י ע\"א רש\"י). נראה, שהאריך ימים, שכן בתו נישאה לרב פפי, אמורא בדור החמישי (חולין קי\"א ע\"ב).","cat": "sage"},{"i": 2532,"n": "יצחק סומקא","l": "י","b": "מובא בבבלי (יבמות ס\"ד ע\"ב), הוא ר' יצחק בר יוסף.","cat": "sage"},{"i": 2533,"n": "יצחק סחורה","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (תענית פ\"ד ה\"א), ששאל לר' יצחק.","cat": "sage"},{"i": 2534,"n": "ר' יצחק עטושיא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. היה תלמידו של רבי שמעון בן לקיש (ירו', ביצה פ\"א ה\"ט). רבו היה רבי זירא (ירו', פאה פ\"ח ה\"ד). לפי דעה אחת היה גם תלמידו של ר' ירמיה (ירו', נזיר פ\"ג ה\"א). היה לו בן חכם ושמו ר' חייא, שהיה תלמידו של ר' ירמיה (שם).","cat": "sage"},{"i": 2535,"n": "ר' יצחק פסקאה","l": "י","b": "אמורא ארץ ישראלי בדור השני. כשמת ר' יוסי ממלחיא באו רבי יוחנן, ר' שמעון בן לקיש ור' יצחק פסקאה, והיה שם סבא אחד שרצה להספידו, ואמר לו ר' יצחק: \"איך תספיד לפני אריות אלו\" (איכ\"ר פ\"א - ל\"ז).","cat": "sage"},{"i": 2536,"n": "ר' יצחק קטריקי","l": "י","b": "מובא בפדר\"כ (ל\"ט), ואולי הוא ר' יצחק דמן קרטיגנין.","cat": "sage"},{"i": 2537,"n": "ר' יצחק קסקסאה","l": "י","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר' יוסי בר אבין, ותרגם לפניו משמו של רבי יוחנן (ברכות נ\"א ע\"א).","cat": "sage"},{"i": 2538,"n": "ר' יצחק רבה","l": "י","b": "מובא בירושלמי (ברכות פ\"ה ה\"ב), והוא רבי יצחק בר אבדימי א'.","cat": "sage"},{"i": 2539,"n": "ר' יצחק רביא","l": "י","b": "מובא בב\"ר (פ\"ק - י\"ב), ואולי הוא ר' יצחק רובא.","cat": "sage"},{"i": 2540,"n": "יצחק רובא","l": "י","b": "מובא בירושלמי (שבת פ\"ג ה\"ג), והוא רבי יצחק בר אבדימי א'.","cat": "sage"},{"i": 2541,"n": "יצחק ריש גלותא","l": "י","b": "בן אחותו של רב ביבי (אמורא בבלי בדור השלישי). הלך מקורטבא לאספמיא ומת שם (יבמות קט\"ו ע\"ב). \"סה\"ד\" מביא בשם הרא\"ש בתשובה כלל נ', שלא היה ריש גלותא, אלא כך היה שמו.","cat": "sage"},{"i": 2542,"n": "ר' יקים","l": "י","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מבעלי האגדה. מובא בש\"ר (פמ\"ב - ט').","cat": "sage"},{"i": 2543,"n": "ר' יקים איש הדר","l": "י","b": "תנא בדור השני. העיד עם ר' יהושע (עדיות פ\"ז מ\"ה).","cat": "sage"},{"i": 2544,"n": "ירמיה","l": "י","b": "חי בארץ ישראל בדור השני לאמוראי ארץ ישראל. אחיו עוקבן הבבלי שלח תלונה עליו למר עוקבא לבבל (סנהדרין ל\"א ע\"ב), ואין להוכיח שנמנה עם החכמים.","cat": "sage"},{"i": 2545,"n": "רבי ירמיה (2)","l": "י","b": "מגדולי אמוראי ארץ ישראל בדור הרביעי. נולד בבבל ועלה לארץ ישראל בצעירותו, ובהיותו בבבל עדיין: \"לא ידע מאי קאמרי רבנן\" (כתובות ע\"ה ע\"א). זכה לקבל מר' יוחנן (שבת ס\"ג ע\"ב רש\"י), אך רבו המובהק היה רבי זירא, שקראו \"בני\" (מו\"ק ד' ע\"א). כן היה תלמידם של ר' אבהו (ב\"מ ט\"ז ע\"ב) ור' אבא (יומא פ\"ז ע\"א). היה מראשי חכמי ארץ ישראל, ובכל מקום בש\"ס שאמרו: \"אמרי במערבא\", הכוונה לר' ירמיה (סנהדרין י\"ז ע\"ב). על חכמי בבל אמר: \"בבלאי טפשאי\". (פסחים ל\"ד ע\"ב). על תלמוד בבלי קרא: \"במחשכים הושיבני כמתי עולם\" (סנהדרין כ\"ד ע\"א). רבא אמר עליו שהוא שקול כנגד שנים מחכמי בבל (כתובות ע\"ה ע\"א). גדולי האמוראים בארץ ישראל בדור שלאחריו קיבלו ממנו: ר' יונה (ירו', מגילה פ\"ד ה\"ה) ור' יוסי (ירו', ברכות פ\"א ה\"ב) ורבים אחרים. לפני מותו ציווה להלבישו תכריכים לבנים, ולתת נעליו ברגליו, ומקלו בידו, ולהשכיבו על צדו, שאם יבוא משיח יהיה מוכן (ירו', כלאים פ\"ט ה\"ג).","cat": "sage"},{"i": 2546,"n": "רבי ירמיה ביראה","l": "י","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (גיטין ל\"ב ע\"א). רב יהודה כפאו לתת גט לאשתו (שם ל\"ד ע\"א).","cat": "sage"},{"i": 2547,"n": "ר' ירמיה בן אלעזר (2)","l": "י","b": "תנא שאין לקבוע זמנו המדוייק. בר קפרא מסר בשמו (ויק\"ר פ\"כ - ח'). ועוד מובא: \"אמר ירמיה בן אלעזר: 'עתיד הקב\"ה לחדש מאור פניהם של צדיקים'\" (קה\"ר פ\"א - ז'). בהגהות רד\"ל כתב, שרבי אמר (שם) בשמו לר' ישמעאל בר' יוסי (א\"כ, חי כנראה בדור הרביעי לתנאים).","cat": "sage"},{"i": 2548,"n": "רב ירמיה בר אבא א'","l": "י","b": "אמורא בבלי בדור השני. תלמידו המובהק של רב (ביצה כ\"ב ע\"ב) ואחר כך תלמיד - חבר שלו (ברכות כ\"ז ע\"ב). כן היה תלמידו של שמואל (סוף כתובות). גדולי האמוראים קיבלו ממנו: רב יהודה (בכורות ל\"ו ע\"ב), רב ששת (נדה ס\"ט ע\"א) ורב חסדא (ברכות נ\"ח ע\"ב). רב הונא בר חייא היה חתנו ותלמידו (שבת קנ\"ו ע\"א). בנו רב הונא, ובן בנו מרי, היו חכמים (עירובין כ\"א ע\"א). רב הונא בריה דרב ירמיה מוזכר רק בהקשר לבנו, ואין ממנו בש\"ס. תוספות כתבו ששני ר' ירמיה בר אבא היו (פסחים ק\"ו ע\"ב).","cat": "sage"},{"i": 2549,"n": "ר' ירמיה בר אבא ב'","l": "י","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב הונא (קידושין מ\"ו ע\"א). עלה לארץ ישראל (כתובות קי\"א ע\"א).","cat": "sage"},{"i": 2550,"n": "רב ירמיה בר אחא","l": "י","b": "אמורא בבלי בדור השני. תלמידו של רב (חולין נ\"א ע\"ב). חלק עם רב חסדא (שם).","cat": "sage"},{"i": 2551,"n": "ר' ירמיה בר אלעאי","l": "י","b": "מובא בויק\"ר (רפי\"א).","cat": "sage"},{"i": 2552,"n": "רב ירמיה בר אמי","l": "י","b": "אמורא בדור השני - השלישי. מצינו שחלק עם רב הונא בר חייא (מו\"ק ט' ע\"ב). המאמר המובא שם בשמו בא במקומות אחרים בשינוי שמות (פסחים מ\"ג ע\"א; מגילה י\"ג ע\"א), ונראה שיש שיבוש וט\"ס בשם.","cat": "sage"},{"i": 2553,"n": "ר' ירמיה בר חנינא","l": "י","b": "מובא בירושלמי (שבת פ\"ד ה\"א), ואולי צ\"ל: ר' יוסי בר חנינא, (כדאיתא ריש הלכה א').","cat": "sage"},{"i": 2554,"n": "ר' ירמיה בר יצחק","l": "י","b": "מובא בתנחומא (תשא - י\"ח). יתכן שיש שיבוש בשם (עיין ש\"ר פמ\"ז - ג').","cat": "sage"},{"i": 2555,"n": "ר' ירמיה בר שלום","l": "י","b": "מובא במדרש משלי (רפ\"א).","cat": "sage"},{"i": 2556,"n": "ר' ירמיה בר שמעיה","l": "י","b": "מובא בב\"ר (פצ\"ג - ו').","cat": "sage"},{"i": 2557,"n": "ר' ירמיה בר תחליפא","l": "י","b": "אמורא שאין לקבוע את מקומו. נראה שחי בדור הרביעי. תלמידו של ר' יעקב, שאמר לו: \"אסברה לך\" (ב\"ב ס' ע\"ב).","cat": "sage"},{"i": 2558,"n": "ר' ירמיה בריה דר' חייא בר אבא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של רבי חייא בר אבא. אמר יחד עם ר' ברכיה בשם לוי בר סיסי (ויק\"ר פכ\"ג - ח').","cat": "sage"},{"i": 2559,"n": "ר' ירמיה בר' שמעון","l": "י","b": "מובא בירושלמי (שבת פ\"ג ה\"א דפוס ויניציא).","cat": "sage"},{"i": 2560,"n": "ר' ירמיה כהנא","l": "י","b": "מובא בב\"ר (פ\"ז - ד').","cat": "sage"},{"i": 2561,"n": "רב ירמיה מדיפתיא","l": "י","b": "אמורא בבלי בדור החמישי - הששי. מסר משמו של רבא (זבחים ל\"ד ע\"ב). נראה, שהיה גם תלמידו של רב פפא (ב\"ק ע\"ג ע\"א). היה תלמידו המובהק של רב פפי (ע\"ז ח' ע\"א). רבינא ישב לפניו (קדושין ל\"ג ע\"א). ר' אשי חלק עמו (שבת ע\"ד ע\"א).","cat": "sage"},{"i": 2562,"n": "ר' ירמיה ספרא","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. שאל לר' ירמיה (ירו', תענית פ\"ד ה\"א).","cat": "sage"},{"i": 2563,"n": "ר' ירמיה רבה","l": "י","b": "מובא בבבלי (שבת כ\"ט ע\"ב).","cat": "sage"},{"i": 2564,"n": "ר' ירמיה שיבשב","l": "י","b": "אמורא בבלי בדור השני. חתך זמורה ועשה ממנה עטרה וזה היה בניגוד לדעת החכמים ושמואל רגז על כך ומת ר' ירמיה שיבשב (ירו', סוטה פ\"ט הט\"ו, וראה \"קרבן העדה\" ו\"פני משה\").","cat": "sage"},{"i": 2565,"n": "ר' ישבב","l": "י","b": "תנא בדור השלישי. תלמידו של רבי יהושע (תוספתא חולין פ\"ב ב') וחברו המובהק של רבי עקיבא (כתובות כ\"ט ע\"ב; שם נ' ע\"א). נמנה עם עשרת הרוגי מלכות (איכ\"ר פ\"ב - ד') והיה בן תשעים וחמש שנה כשנהרג. נהג לחלק נכסיו לעניים (ירו', פאה פ\"א ה\"א).","cat": "sage"},{"i": 2566,"n": "ר' ישבב הסופר","l": "י","b": "מובא במדרש (אלה אזכרה), והוא ר' ישבב.","cat": "sage"},{"i": 2567,"n": "רבי ישמעאל","l": "י","b": "תנא בדור השלישי. מושבו היה בדרום, סמוך לאדום (כתובות ס\"ד ע\"א), ונראה ששם היתה ישיבתו הגדולה \"בי ר' ישמעאל\". הוא סתם רבי ישמעאל בש\"ס וההוכחה, שמובא מעשה מרבי ישמעאל בן אלישע (בשבת י\"ב ע\"ב). ואותו מעשה מובא (ירו', שבת פ\"א ה\"ג) בשם סתם רבי ישמעאל. תלמידו המובהק של רבי נחוניא בן הקנה (שבועות כ\"ו ע\"א) ותלמידם של רבי אליעזר (ספרא תזריע פי\"ג) ושל רבי יהושע (ע\"ז כ\"ט ע\"ב) וחברו ובר פלוגתיה המובהק של ר\"ע (יומא ע\"ה ע\"ב). בין תלמידיו הגדולים היו רבי מאיר (עירובין י\"ג ע\"א), רבי יונתן (מנחות נ\"ז ע\"ב), רבי יאשיה (שם), ור' אלעאי [אביו של ר' יהודה] (גיטין ו' ע\"ב). הפירוש על ספר שמות שבידינו, הידוע בשם מכילתא דר' ישמעאל יצא מבית מדרשו. רבי טרפון אמר עליו: \"חכם גדול הוא ובקי באגדות\" (מו\"ק כ\"ח ע\"ב). בילדותו נשבה והובא לרומי ור' יהושע פדאו בממון רב (גיטין נ\"ח ע\"א).","cat": "sage"},{"i": 2568,"n": "ר' ישמעאל אבי ר' יודן","l": "י","b": "מובא בירושלמי (גיטין פ\"א ה\"ב).","cat": "sage"},{"i": 2569,"n": "ישמעאל איש כפר דימא","l": "י","b": "ע\"ע ישמעאל איש כפר ימא.","cat": "sage"},{"i": 2570,"n": "ישמעאל איש כפר ימא","l": "י","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר' אמי ולא ידע להשיב לו ובא לר' יצחק נפחא והשיב לו (נדרים נ\"ז ע\"ב). הגמרא מפקפקת שם אם היה מכפר ימא או דימא.","cat": "sage"},{"i": 2571,"n": "רבי ישמעאל בן אלישע (2)","l": "י","b": "כהן גדול בבית שני (ברכות ז' ע\"א). חברו של רבן שמעון בן גמליאל כמובא בבבלי (סוטה מ\"ח ע\"ב), ושניהם היו מעשרה הרוגי מלכות (אדר\"נ פל\"ח - ג'), ורש\"י פירש: \"כהן גדול ומהרוגי מלכות היה\" (ע\"ז י\"א ע\"ב ד\"ה: קרקיפלו של רבי ישמעאל). \"כשנהרג רבי שמעון ורבי ישמעאל באה השמועה אצל רבי עקיבא ורבי יהודה בן בתירא\" (שמחות פ\"ח). היה אולי סבו של רבי ישמעאל בר פלוגתא דר\"ע (\"סה\"ד\").","cat": "sage"},{"i": 2572,"n": "רבי ישמעאל בן אלעזר","l": "י","b": "תנא שאין לקבוע זמנו. מובא בירושלמי (ברכות ספ\"ב) ובבבלי (שבת ל\"ב ע\"א), ושם גורס \"דק\"ס\" רבי שמעון בן אלעזר.","cat": "sage"},{"i": 2573,"n": "ר' ישמעאל בן אלעזר הקפר","l": "י","b": "מובא באבות דר\"נ (פכ\"ט - ה'). נראה שיש כאן ט\"ס.","cat": "sage"},{"i": 2574,"n": "רבי ישמעאל בן ברוקה","l": "י","b": "מובא בבבלי (שבת כ\"ו ע\"א). \"סה\"ד\" ו\"דק\"ס\" גורסים: רבי ישמעאל בנו של רבי יוחנן בן ברוקה.","cat": "sage"},{"i": 2575,"n": "ר' ישמעאל בן גמליאל","l": "י","b": "כך מביא \"סה\"ד\" מן הירושלמי (ברכות פ\"ט ה\"ב), \"אולי ט\"ס, וצ\"ל ר' שמעון\", אכן בספר 'שדה יהושע' הנוסח גם כן כך. ולפנינו לא נמצא שם זה כלל.","cat": "sage"},{"i": 2576,"n": "ר' ישמעאל בן זירוד","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: שבא לבקר בחוליו את ר' ינאי בר' ישמעאל, ואמר לו: \"הכי אמר רבי שמעון בן לקיש משום רבי חייא וכו'\" (ע\"ז ל' ע\"ב).","cat": "sage"},{"i": 2577,"n": "ר' ישמעאל בן זירוז","l": "י","b": "הוא ר' ישמעאל בן זירוד.","cat": "sage"},{"i": 2578,"n": "ר' ישמעאל בן חנניה","l": "י","b": "תנא בדור השני. מובא באבות דר\"נ (פי\"ד), שהיה תלמידו של רבי יוחנן בן זכאי. אבל יש משבשים שם זה לר' שמעון בן נתנאל ושוב לא מובא שם זה בש\"ס.","cat": "sage"},{"i": 2579,"n": "ר' ישמעאל בן יהוצדק","l": "י","b": "מובא בבבלי (ב\"מ כ\"ב ע\"ב), שרבי יוחנן אמר בשמו. וכבר הגיה \"מסורת הש\"ס\" שצ\"ל: רבי שמעון בן יהוצדק, וכן הוא ב\"ילקוט\" וכך הוא ברא\"ש וכן הגיה \"דק\"ס\".","cat": "sage"},{"i": 2580,"n": "רבי ישמעאל בן יוסף","l": "י","b": "הוא התנא רבי ישמעאל בר יוסי בן חלפתא. מובא בירושלמי: \"תני רבי ישמעאל בר יוסף משום אביי\" (יבמות פ\"ז ה\"ג), וצ\"ל: משום אביו.","cat": "sage"},{"i": 2581,"n": "ר' ישמעאל בן יעקב דמן צור","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, ששאל את רבי יוחנן (כתובות ז' ע\"א).","cat": "sage"},{"i": 2582,"n": "רבי ישמעאל בן לוגא","l": "י","b": "תנא בדור השלישי בדורו של רבי עקיבא, כמובא בבלי (יומא ל\"ח ע\"א). \"סה\"ד\" כתב שהוא ט\"ס וצ\"ל: שמעון בן לוגה, כמובא בירושלמי (שקלים פ\"ה). והגיר' במקום אחר בירושלמי: שמעון בן לגס (יומא פ\"ג ה\"ט).","cat": "sage"},{"i": 2583,"n": "רבי ישמעאל בן סתריאל","l": "י","b": "תנא בדור החמישי. מושבו היה במקום ששמו ערקת לבנה (בכורות נ\"ז ע\"ב). העיד לפני רבי (שם).","cat": "sage"},{"i": 2584,"n": "רבי ישמעאל בנו של רבי אלעזר בן עזריה","l": "י","b": "תנא בדור הרביעי. מובא פעם אחת בבבלי: \"רבי ישמעאל ורבי עקיבא ורבי אלעזר בן עזריה מהלכין בדרך, ולוי הסדר ורבי ישמעאל בנו של רבי אלעזר בן עזריה מהלכין אחריהן, נשאלה שאלה זו בפניהם וכו'\" (יומא פ\"ה ע\"א).","cat": "sage"},{"i": 2585,"n": "רבי ישמעאל בנו של רבי יוחנן בן ברוקא","l": "י","b": "תנא בדור הרביעי. בנו ותלמידו של רבי יוחנן בן ברוקא (ב\"ב ק\"ל ע\"א). חלק על אביו (ב\"ק קי\"ד ע\"א). מובא יחד עם רשב\"ג, אך מוזכר לאחריו (עירובין מ' ע\"ב). ישב גם ביבנה (יבמות מ\"ב ע\"ב).","cat": "sage"},{"i": 2586,"n": "ר' ישמעאל בר אבא","l": "י","b": "אמורא ארץ ישראלי בדור השני. נראה שהיה תלמידו של רבי יהושע בן לוי (חולין קכ\"ב ע\"א) ור\"ל הודה לו (שם).","cat": "sage"},{"i": 2587,"n": "ר' ישמעאל בר אמי","l": "י","b": "מובא בויק\"ר (פ\"א - ג').","cat": "sage"},{"i": 2588,"n": "ר' ישמעאל בר ביבי","l": "י","b": "אמורא. מובא בויק\"ר (פי\"א - ח'), ונראה שיש ט\"ס בשם זה, שכן לא מובא בש\"ס.","cat": "sage"},{"i": 2589,"n": "ר' ישמעאל בר יישוע","l": "י","b": "אמורא ארץ ישראלי בדור השני. \"אמר רבי מתנייה, סלקית לסחורה [עליתי למקום ששמו סחורה] ושמעית ר' יוחנן ור' ישמעאל בני יישוע\" (ירו', יבמות פ\"ז ה\"ו).","cat": "sage"},{"i": 2590,"n": "ר' ישמעאל בר יעקב בר אחא","l": "י","b": "מראשוני האמוראים בארץ ישראל. ר' חנינא מסר משמו (ירו', שבת פ\"ד ה\"ב). \"סה\"ד\" גרס אחרת.","cat": "sage"},{"i": 2591,"n": "רבי ישמעאל בר נחמן","l": "י","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבדימי דמן חיפא (ויק\"ר רפי\"ח).","cat": "sage"},{"i": 2592,"n": "ר' ישמעאל בר ר' יצחק","l": "י","b": "אמורא ארץ ישראלי בדור השלישי. (ירו', יומא פ\"ג ה\"ז).","cat": "sage"},{"i": 2593,"n": "ר' ישמעאל בר תנחום","l": "י","b": "אמורא ארץ ישראלי בדור החמישי. מובא בויק\"ר (רפכ\"ב), שאמר בשם ר' ירמיה. ויש גם ב\"ילקוט\" (קהלת פ\"ה פ' ויתרון): ר' ישמעאל בר תנחומא בשם ר' ירמיה, ואולי שניהם אחד.","cat": "sage"},{"i": 2594,"n": "ר' ישמעאל בר תנחומא","l": "י","b": "מובא ב\"ילקוט\" (קהלת פ\"ה פ' ויתרון) ואולי הוא ר' ישמעאל בר תנחום.","cat": "sage"},{"i": 2595,"n": "רבי ישמעאל בר' יונה","l": "י","b": "מובא בירושלמי (ריש חלה). \"סה\"ד\" מביא בשם \"שדה יהושע\" שט\"ס הוא, ולא היה חכם בשם זה.","cat": "sage"},{"i": 2596,"n": "רבי ישמעאל בר' יוסי","l": "י","b": "תנא בדור החמישי. בנו ותלמידו של רבי יוסי בן חלפתא (שבת נ\"א ע\"א). אמר פעמים רבות משום אביו (יבמות ס\"ז ע\"א). מושבו של אביו היה בציפורי. אחר פטירת אביו מילא שם את מקומו (עירובין פ\"ו ע\"ב רש\"י). היה תלמידו של רבי יהודה (סוכה י\"ח ע\"א). נראה, שלמד מר' ישמעאל בר פלוגתיה דרבי עקיבא (יבמות ק\"ד ע\"א). אמרו עליו: \"ר' ישמעאל בר יוסי תנא הוא ופליג\" (שבת ס\"ד ע\"ב). ואמנם נראה שלמד לפני רבי (יבמות ק\"ה ע\"ב): \"אני ישמעאל בר יוסי שבאתי ללמוד תורה מרבי\". וכן \"פעם חש רבי במעיו וכו'\" אמר לפניו רבי ישמעאל בר יוסי וכו'\" (ע\"ז מ' ע\"ב). וכן \"פעם שאלו את רבי וכו' אמר לפניו רבי ישמעאל בר יוסי וכו'\" (נדה כ\"ה ע\"א). אך רש\"י סובר (שבת נ\"א ע\"א) שרבי ישמעאל בר יוסי היה גדול כאביו רבי יוסי, והיה כפוף ויושב לפני רבי \"מפני כבוד הנשיאות, ולא היה מורה לפניו אעפ\"י שגדול הימנו\" (מרבי). ואכן מצינו: \"בעא מיניה רבי מרבי ישמעאל בר' יוסי\" (שם קי\"ג ע\"ב, וקי\"ט ע\"א). היה חברו של רבי חייא ונכנס לפני רבי חייא לבית הועד (ירו', כלאים פ\"ט ה\"ג). בין תלמידיו היה ר' חנינא בר חמא (קדושין ע\"א ע\"א). ומשמע שרב ראהו מתפלל כמובא (ברכות כ\"ז ע\"ב): \"אמר רב: 'בצד זה התפלל רבי ישמעאל בר יוסי'\". הצטיין בבקיאותו במקרא ואמר שיכול לכתוב את כל המקרא בעל פה (ירו', מגילה פ\"ד ה\"א). היו לו ארבעה אחים (שבת קי\"ח ע\"ב). נפטר לפני רבי חייא (ירו', ב\"ק פ\"ו ה\"ז).","cat": "sage"},{"i": 2597,"n": "ר' ישמעאל השזורי","l": "י","b": "כך מובא בירושלמי (שבת פ\"י ה\"ד), והוא ט\"ס וצ\"ל: ר' שמעון שזורי.","cat": "sage"},{"i": 2598,"n": "ר' ישעיה","l": "י","b": "תנא בדור השני. תלמידו של רבי חנינא בן דוסא. מובא ב\"ילקוט\" (בא רמז קפז) שהתענה שמונים ושמונה תעניות כדי שיזכה להבין מפני מה זכה הכלב לומר שירה.","cat": "sage"},{"i": 2599,"n": "יששכר דפרמנדי","l": "י","b": "אמורא ארץ ישראלי בדור השני. מובא יחד עם ר' חמא בר חנינא (ב\"ר פנ\"ב - ו').","cat": "sage"},{"i": 2600,"n": "ר' יתא","l": "י","b": "הוא ר' איתי.","cat": "sage"},{"i": 2601,"n": "כדי","l": "כ","b": "מובא בבלי 31 פעם (ברכות ל' ע\"א [לגיר' \"דק\"ס\"], יומא מ\"ד ע\"א; ע\"ב ע\"ב; מגילה ב' ע\"ב; גיטין נ\"ד ע\"א; יבמות צ' ע\"א; ב\"מ ב' ע\"א; נזיר ב' ע\"א; הוריות ח' ע\"א; מנחות נ\"ה ע\"ב; חולין ע\"ג ע\"א; פ\"א ע\"א; קי\"ח ע\"א). בב\"מ (ב' ע\"א) פירש הרש\"ל: \"בעלמא רגיל רש\"י לפרש שם חכם או פירש בחינם כמו בכדי, כלומר, שלא נזכר שם אמרו, רק סתמא נ\"ל\". ובחולין פירש רש\"ל: \"הוא שם חכם או פי' בחנם בלאו שום הזכרת חכם\" (ע\"ג ע\"א). ורש\"י פירש: \"וכדי, כלומר בולא כלום באין ספר, כמו כדי נסבה, וכמו [והוי כמו אי נמי], ואמרי לה כדי שם חכם\" (גיטין פ\"ה ע\"ב ד\"ה: ולורכיה).","cat": "sage"},{"i": 2602,"n": "רבי כהן","l": "כ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. אחיו של רבי חייא בר אבא (ירו', שבת פ\"ב ה\"ו). טייל יחד עם רבי אמי, רבי חזקיה ורבי יעקב בר אחא (ירו', ברכות פ\"ג ה\"ח).","cat": "sage"},{"i": 2603,"n": "ר' כהנא","l": "כ","b": "מובא ב\"זוהר\" (תולדות קלט).","cat": "sage"},{"i": 2604,"n": "רב כהנא אחוה דרב יהודה","l": "כ","b": "אמורא בבלי בדור השלישי. מובא בבבלי (חולין קי\"א ע\"ב): \"יתיב 'קמיה' דרב הונא\". הרא\"ש גורס \"יתיב רב כהנא 'אחורי' (במקום אחוה) דרב יהודה\", ולפי גירסה זו לא היה קיים כלל אמורא ושמו רב כהנא אחוה דרב יהודה, שכן שוב לא הובא שמו בש\"ס.","cat": "sage"},{"i": 2605,"n": "רב כהנא א'","l": "כ","b": "אמורא בבלי בדור הראשון. תלמיד חבר לרב. חברו של רב אסי (סנהדרין ל\"ו ע\"ב). רב החשיבם וכיבדם (שבת קמ\"ו ע\"ב). א\"ל רב כהנא ורב אסי לרב: \"מ\"ט לא מפרשת לן וכו' א\"ל: 'אמינא דלמא לא צריכיתו'\" (נזיר י\"ט ע\"א). מספר פעמים הוא ורב אסי הקשו לרב, ורב שתק, כי הודה להם (ב\"ק ס\"ב ע\"א תד\"ה: ומי זה). חברו רב אסי אף היה גדול משמואל (שם פ' ע\"ב רש\"י ד\"ה: מלתא). עלה לארץ ישראל ונפגש עם רבי שמעון בנו של רבי (זבחים נ\"ט ע\"א), ועם יהודה וחזקיה, בני רבי חייא (מנחות כ\"ג ע\"א) ושקיל וטרי עמם כחברים. חכמי ארץ ישראל שקיבלו ממנו: רבי אושעיא [רבו של רבי יוחנן] (ירו', חלה פ\"א ה\"ג), ורבי יוחנן וריש לקיש (ירו', ר\"ה רפ\"ד).","cat": "sage"},{"i": 2606,"n": "רב כהנא בר ביזנא","l": "כ","b": "מובא בילקוט (יחזקאל רמז שמ\"ז). יתכן שט\"ס היא, וצ\"ל: רב חנא בר ביזנא.","cat": "sage"},{"i": 2607,"n": "רב כהנא בר טוביא","l": "כ","b": "מובא בבבלי (עירובין ח' ע\"א) בדפוס שאלוניקי, והגירסא לפנינו: רב כהנא בר מלכיו.","cat": "sage"},{"i": 2608,"n": "כהנא בר ירמיה","l": "כ","b": "אמורא בבלי בדור השלישי. מסר בשם שמואל (ירו', ערלה פ\"ג ה\"ג).","cat": "sage"},{"i": 2609,"n": "רב כהנא בר מלכיה","l": "כ","b": "אמורא בבלי בדור השלישי. מסר בשם רב (ירו', ברכות פ\"ו ה\"א). ע\"ע רב כהנא בר תחליפא.","cat": "sage"},{"i": 2610,"n": "רב כהנא בר מלכיו","l": "כ","b": "מובא בבבלי (עירובין ח' ע\"ב). ע\"ע רב כהנא בר תחליפא.","cat": "sage"},{"i": 2611,"n": "רב כהנא בר מניומי","l": "כ","b": "מובא בבבלי (עירובין ח' ע\"ב). ע\"ע רב כהנא בר תחליפא.","cat": "sage"},{"i": 2612,"n": "רב כהנא בר מתנה","l": "כ","b": "ע\"ע רב כהנא בר תחליפא.","cat": "sage"},{"i": 2613,"n": "רב כהנא בר מתתיהו","l": "כ","b": "ע\"ע רב כהנא בר תחליפא.","cat": "sage"},{"i": 2614,"n": "רב כהנא בר תחליפא","l": "כ","b": "חוסר בהירות גדול יש בשם זה ואין להכריע כיצד לגרוס. מובא בבבלי: \"אמר רב כהנא בר תחליפא משמיה דרב כהנא בר מניומי, משמיה דרב כהנא בר מלכיו, משמיה דרב כהנא רביה דרב, ואמרי לה רב כהנא בר מלכיו וכו'\" (עירובין ח' ע\"ב). והב\"ח גורס שם אחרת, ו\"דק\"ס\" גורס: רב הונא בר תחליפא משמיה דרב כהנא רבה, ובדפוס פיזרו ווינציא רפ\"ה גרס: בר מתתיהו, וכן הוא באו\"ז סקי\"ד. \"סה\"ד\" כתב בערך רב כהנא בר תחליפא: \"וה'יוחסין' כתב בפ\"ק דעירובין כהנא בר מתתיהו בשם רב כהנא בר מניומי וכו', ט\"ס הוא, כי הגיר' כאשר העתקתי וכו', וכבר הראתיך שט\"ס הוא, וצ\"ל וכו' וב\"שארית יוסף\" הביא כתלמיד רב, רב כהנא בר מתנה ולא מצאתי זכרו בכל הש\"ס, אולי כונתו לרב כהנא בר מתתיהו הנ\"ל, ובאמת ט\"ס הוא גם לא מצינו שאמר בשם רב\", עכ\"ל. ואני הכותב לא מצאתי ידי ורגלי בכל הגירסאות הנ\"ל. ואין בידי להכריע ומה גם שראיתי כי ה\"יוחסין\" כתב שרב כהנא בר מלכיו היה רבו דרב, ומצאתי בירושלמי (ברכות פ\"ו ה\"א) ההיפך: שרב כהנא בר מלכיו אמר בשם רב, ולכן לא סיווגתים לא כרב ולא כתלמיד.","cat": "sage"},{"i": 2615,"n": "רב כהנא בריה דרב חיננא סבא","l": "כ","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (פסחים ע\"ו ע\"ב).","cat": "sage"},{"i": 2616,"n": "רב כהנא בריה דרב נחוניא","l": "כ","b": "אמורא בבלי בדור השלישי. שמשו של רב יהודה (תענית כ\"ד ע\"ב).","cat": "sage"},{"i": 2617,"n": "רב כהנא בריה דרב נחמיה","l": "כ","b": "אמורא בבלי. מובא יחד עם רבא ורב פפא, ואולי היה בדורם (יבמות ע\"א ע\"ב).","cat": "sage"},{"i": 2618,"n": "רב כהנא בריה דרב נתן","l": "כ","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. יתכן שהיה בזמנו של רב אשי. מובא בבבלי (יבמות ס' ע\"ב).","cat": "sage"},{"i": 2619,"n": "רב כהנא בריה דר' חייא בר אבא","l": "כ","b": "אמורא ארץ ישראלי בדור הרביעי. בנו של רבי חייא בר אבא. מובא בירושלמי: \"ר' כהנא בריה דר' חייא בר אבא ור' אחא מטי בה בשם ר' יוחנן\". (שבת פ\"א ה\"ד).","cat": "sage"},{"i": 2620,"n": "רב כהנא ב'","l": "כ","b": "אמורא בבלי בדור השני. תלמידו המובהק של רב (ב\"ק קי\"ז ע\"א). כן קיבל משמואל (יבמות ק\"ב ע\"ב). לאחר שהרג מלשין, נאלץ לברוח לארץ ישראל, ולפי בקשת רב קיבל על עצמו לא להקשות לרבי יוחנן שבע שנים. בתחלה אמרו עליו: \"ארי עלה מבבל\", והושיבוהו בשורה הראשונה לפני רבי יוחנן, ולאחר ששתק ולא הקשה החזירוהו משורה לשורה עד שורה השביעית, ור' יוחנן אמר לר\"ל: \"ארי שאמרת נעשה שועל\", ואמר רב כהנא: \"יהי רצון ששבע השורות יהיו תחת שבע השנים\" והחל להקשות לר' יוחנן שלא ידע להשיב לו, והחזירוהו משורה לשורה עד שורה ראשונה, וכשר' יוחנן הסתכל בו נדמה היה לו שרב כהנא מחייך, והיתה לו חלישות הדעת, ומת רב כהנא, ולאחר שהתברר לר' יוחנן שטעה, החיה את רב כהנא (ב\"ק קי\"ז ע\"א). שב לבבל, ולאחר פטירת רב ישב גם לפני רב יהודה (יבמות י\"ז ע\"א). לפי גיר' הרא\"ש ישב גם לפני רב הונא (חולין קי\"ג ע\"ב). בין תלמידיו היו: רבה (שם ק\"כ ע\"א) ורב יוסף (עירובין ס\"ז ע\"ב).","cat": "sage"},{"i": 2621,"n": "רב כהנא ג'","l": "כ","b": "אמורא בבלי בדור הרביעי. תלמידו של רבה. חברו של רב ספרא (סנהדרין מ\"א ע\"ב). עלה לארץ ישראל, והיה תלמידו של רבי חייא בר אבא (ירו', ר\"ה פ\"ב ה\"ה), ורבי חייא בר אבא בירכו שיאריך ימים וכן היה (שם).","cat": "sage"},{"i": 2622,"n": "רב כהנא ד'","l": "כ","b": "אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא (כתובות ס\"ג ע\"ב). מסר בשמו של רבא (ב\"ק מ\"א ע\"ב). שקיל וטרי עם רב ביבי, בנו של אביי (עירובין צ' ע\"א). היה חברו של רב פפא (גיטין פ\"ט ע\"ב). היתה לו ישיבה שכינויה \"בי רב כהנא\" (קידושין ע\"ז ע\"א). בין תלמידיו הרבים היה גם רב אשי, שהיה תלמידו המובהק (ברכות ל\"ט ע\"א), ורב אשי מזכיר פעמים רבות את רב כהנא זה (שם, סוכה מ\"ו ע\"א; חולין י\"א ע\"ב). כשחלה, שלחו את רבי יהושע בריה דרב אידו לבקרו, ומצאו מת (פסחים ג' ע\"ב).","cat": "sage"},{"i": 2623,"n": "רב כהנא ה'","l": "כ","b": "אמורא בבלי בדור השביעי. תלמידו של שימי בר אשי (חולין י\"א ע\"ב; תמורה כ\"ה ע\"א). נראה, שהיה גם תלמידו של רב אשי (ברכות כ\"ד ע\"א).","cat": "sage"},{"i": 2624,"n": "רב כהנא חמוה דרב משרשיא","l": "כ","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב צ\"ז ע\"ב).","cat": "sage"},{"i": 2625,"n": "כייליל","l": "כ","b": "מובא בבבלי (זבחים קי\"ח ע\"ב) ופירש רש\"י שם: \"נראה בעיני כי אביו של אביי כייליל שמו\", ולפי זה היה אחיו של רבה בר נחמני ושל רב חייא ורב אושעיא (לא רבי חייא ורבי אושעיא). כייליל זה מת עוד לפני שנולד אביי בנו (קידושין ל\"א ע\"ב) ואשתו (אמו של אביי) מתה בלידת אביי, וזה לשון הגמרא (שם): \"ר' יוחנן כי עברתו אמו מת אביו ילדתו - מתה אמו וכן אביי\".","cat": "sage"},{"i": 2626,"n": "רב כיני","l": "כ","b": "מובא בירושלמי (ע\"ז פ\"ג ה\"ג), והוא רב בינה כמו שנכתב בפירוש \"מראה פנים\" (ירו', ע\"ז פ\"ב ה\"ז), שדרך הירושלמי להחליף אותיות בי\"ת וכ\"ף.","cat": "sage"},{"i": 2627,"n": "ר' כיריי","l": "כ","b": "מובא בירושלמי (פסחים ספ\"ב). נראה זהה לבירא.","cat": "sage"},{"i": 2628,"n": "כלבא שבוע","l": "כ","b": "ע\"ע בן כלבא שבוע.","cat": "sage"},{"i": 2629,"n": "רבי כרוספדאי","l": "כ","b": "תנא בדור השלישי. מובא ב\"זוהר חדש\" (רות פ\"א) שכאשר חלה, ביקרוהו רב יוסי בן קסמא ורבנן, וביום השבת חשבו שנפטר, ואח\"כ במוצ\"ש ראוהו חי. וכתב ה\"יוחסין\": \"ובזהר אמר שהם שנים\" (ר' כרוספדאי ור' כרוספדאי בריה דר' שבתי).","cat": "sage"},{"i": 2630,"n": "ר' כרוספדאי בריה דר' שבתי","l": "כ","b": "ע\"ע רבי כרוספדאי.","cat": "sage"},{"i": 2631,"n": "רבי לא","l": "ל","b": "מובא בירושלמי (עירובין פ\"ו ה\"ט), והוא רבי אלעאי.","cat": "sage"},{"i": 2632,"n": "ר' לא דכפרא","l": "ל","b": "מובא בירושלמי (סנהדרין פ\"ו ה\"ט), ואולי הוא ר' הלל דכיפרא.","cat": "sage"},{"i": 2633,"n": "לודא","l": "ל","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת צ\"ו ע\"ב; שם קל\"ז ע\"א; יבמות ע\"א ע\"ב). ה\"יוחסין\" ו\"סה\"ד\" כתבו שהיה בזמן שמואל ולעניות דעתי אין כל ראיה מהמקורות הנ\"ל שהיה בזמן שמואל. ובירושלמי (תענית פ\"ג ה\"י): ר' לודה.","cat": "sage"},{"i": 2634,"n": "ר' לודה","l": "ל","b": "מובא בירושלמי (תענית פ\"ג ה\"י), ואולי הוא האמורא לודא.","cat": "sage"},{"i": 2635,"n": "רבי לוונטי","l": "ל","b": "מובא בירושלמי (שבת פ\"ג ה\"ג), והוא רבי לונטי.","cat": "sage"},{"i": 2636,"n": "לוטינוס דרומיה","l": "ל","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר' יודה (יהודה) בר סימון (פדר\"כ ק').","cat": "sage"},{"i": 2637,"n": "לוי","l": "ל","b": "מראשוני אמוראי ארץ ישראל. הוא לוי בר סיסי. וההוכחה, שבבבלי מובא (סוכה נ\"ג ע\"א): לוי, ואותו ענין בירושלמי (ברכות פ\"א ה\"ה): לוי בר סיסי. מבני פמלייתו של רבי ולמד לפניו (זבחים ל' ע\"ב), והיה חביב עליו עד שאמר עליו לבני העיר סימונייא: \"בר נש דכוותי יהבית לכון\" (ירו', יבמות פי\"ב ה\"ו), ופירש \"קרבן העדה\": \"אדם שכמותי גדול בתורה נתתי לכם\". לוי קרא לרבי: \"רבינו הקדוש\" (שבת קנ\"ו ע\"א), ועליו אמרו: \"כל היכא דאיתמר: 'למדין לפני חכמים' היינו לוי, שהיה לומד לפני רבי\" (סנהדרין י\"ז ע\"ב רש\"י). רבי חנינא היה חברו הגדול (כתובות ק\"ג ע\"ב). כן למד יחד עם רב לפני רבי (ביצה כ\"ד ע\"ב). אחרי שר' אפס מת ור' חנינא ישב בראש הישיבה בא\"י, ירד לוי לבבל (שבת נ\"ט ע\"ב), ושם היה לחברו של אבא בר אבא (אבוה דשמואל) ולמדו יחד (מגילה כ\"ט ע\"א). אבוה דשמואל חי אחריו והספידו כשנפטר (ירו', ברכות פ\"ב ה\"ח). ובין תלמידיו היה שמואל (מנחות ל\"ח ע\"ב). מסופר (תענית כ\"ה ע\"א) שפעם אחת גזר תענית שירדו גשמים ולא ירדו, \"אמר לפניו רבש\"ע: עלית וישבת במרום ואין אתה מרחם על בניך?\" ואמנם ירדו גשמים, אבל על שהטיח דברים כלפי מעלה לקה בצליעה, ומצינו שעוד היה צולע אחר פטירת רבי (כתובות ק\"ג ע\"ב). וכן מסופר, שפעם כשבאו גייסות לעירו, נטל ספר תורה ועלה לראש הגג ואמר: \"רבונו של עולם אם ביטלתי דבר אחד מספר תורה זה, יכנסו להם, ואם לאו, ילכו להם\" (ירו', תענית פ\"ג ה\"ח), ומיד הלכו כל הגיסות.","cat": "sage"},{"i": 2638,"n": "ר' לוי","l": "ל","b": "אמורא ארץ ישראלי בדור השלישי. מבעלי האגדה. במשך עשרים ושתים שנה דרש בבית המדרש, קודם שבא רבי יוחנן לשם (ירו', סוכה פ\"ה ה\"א). רבי זירא, אף שהיה מתנגד מובהק לבעלי האגדה, ציוה לתלמידיו ללכת לשמוע דרשותיו של ר' לוי, משום שאי אפשר שלא יהא בהן דבר חידוש (ירו', ר\"ה פ\"ד ה\"א). ר' אבא בר כהנא נשקו על ראשו כששמעו דורש (ירו', סוף הוריות). מסר דרשות בשם התנאים: רבי יוסי בר תחליפא (ב\"ר פנ\"ז - ד') ורבי מאיר (סוכה ח' ע\"ב). כן קיבל מרבי שמעון בן לקיש (מד' שמואל רפ\"ט). מסרו בשמו: ר' יונה (ירו', חגיגה פ\"ב) ור' יוסי (ב\"ר פז\"ח - ה'). ר' יהושע דסכנין מסר ממנו יותר ממאה דרשות.","cat": "sage"},{"i": 2639,"n": "לוי בר בוטי","l": "ל","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (מגילה ל\"א ע\"ב). נראה, שהשם שובש בכמה אופנים (ירו', מגילה פ\"ג ה\"ז): לוי בר פסטי, וכן מצינו (מסכת סופרים פי\"ב): בר פאטי, וכן (קה\"ר פ\"ח - ג'): ר' לוי בר פנטי. ונראה שאולי כולם אחד. \"סה\"ד\" קבע, שלוי בר בוטא ולוי בר פנטי שניים.","cat": "sage"},{"i": 2640,"n": "לוי בר ביריי","l": "ל","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי יהושע בן לוי (ירו', ב\"ב רפ\"ה).","cat": "sage"},{"i": 2641,"n": "ר' לוי בר ברכיה","l": "ל","b": "מובא בתנחומא (בחוקותי - ז').","cat": "sage"},{"i": 2642,"n": "לוי בר היני","l": "ל","b": "מובא בירושלמי (תרומות פ\"ד ה\"ב).","cat": "sage"},{"i": 2643,"n": "ר' לוי בר זבדא","l": "ל","b": "מובא בתנחומא (דפוס וניציא, בחוקותי).","cat": "sage"},{"i": 2644,"n": "ר' לוי בר זכריה","l": "ל","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם רבי ברכיה (פסיקתא דר\"כ ס\"ו ב').","cat": "sage"},{"i": 2645,"n": "רבי לוי בר חויית","l": "ל","b": "מובא בב\"ר (פל\"ט - י\"א). ע\"ע רבי לוי בר חיותא.","cat": "sage"},{"i": 2646,"n": "רבי לוי בר חזותא","l": "ל","b": "כך מובא ב\"ערוך\" ערך אלנסתין. ע\"ע רבי לוי בר חיותא.","cat": "sage"},{"i": 2647,"n": "רבי לוי בר חיותא","l": "ל","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי (ירו', שבת ספ\"ו). יתכן ששמו שובש בכמה אופנים לרבי לוי בר חיתא (מו\"ק כ\"ט ע\"א) ולרבי לוי בר חיתה (ירו', סוטה פ\"ז ה\"א). ענין זה מובא ב\"ערוך\" ערך אלנסתין, ושם: רבי לוי בר חזותא, ומצינו: \"אמר רבי לוי בר חייתא\" (ב\"ר פנ\"ה - ז') ו\"רבי לוי בר חויית\" (ב\"ר פל\"ט - י\"א), ואולי כל השמות הללו או חלקם אחד הם.","cat": "sage"},{"i": 2648,"n": "ר' לוי בר חייא","l": "ל","b": "מובא בבבלי, שאמר: \"היוצא מבית הכנסת ונכנס לבית המדרש ועוסק בתורה, זוכה ומקבל פני השכינה\" (ברכות ס\"ד ע\"א).","cat": "sage"},{"i": 2649,"n": "רבי לוי בר חייתא","l": "ל","b": "מובא בב\"ר (פנ\"ה - ז'). ע\"ע רבי לוי בר חיותא.","cat": "sage"},{"i": 2650,"n": "לוי בר חינא","l": "ל","b": "מובא (ירו', תרומות פ\"ד ה\"ג), והוא לוי בר היני.","cat": "sage"},{"i": 2651,"n": "רבי לוי בר חיתא","l": "ל","b": "מובא בבבלי (מו\"ק כ\"ט ע\"א). ע\"ע רבי לוי בר חיותא.","cat": "sage"},{"i": 2652,"n": "רבי לוי בר חיתה","l": "ל","b": "מובא בירושלמי (סוטה פ\"ז ה\"א). ע\"ע רבי לוי בר חיותא.","cat": "sage"},{"i": 2653,"n": "רבי לוי בר חמא","l": "ל","b": "מובא בבבלי (ברכות ה' ע\"א). \"סה\"ד\" כתב: \"אולי אחד הוא עם רבי לוי בר לחמא\".","cat": "sage"},{"i": 2654,"n": "ר' לוי בר טרפון","l": "ל","b": "אמורא ארץ ישראלי בדור השני. מובא באיכ\"ר (פ\"א - ל\"ג), שר' יהודה בר סימון מסר משמו. יתכן שצריך לגרוס: בר פרטא, כמו בויק\"ר (פכ\"ג - י\"ב).","cat": "sage"},{"i": 2655,"n": "רבי לוי בר לחמא","l": "ל","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי חמא בר חנינא (ר\"ה כ\"ט ע\"ב). וכתב \"סה\"ד\": אולי אחד הוא עם רבי לוי בר חמא (ברכות ה' ע\"א).","cat": "sage"},{"i": 2656,"n": "ר' לוי בר נזירא","l": "ל","b": "מובא בירושלמי (ברכות פ\"ב ה\"א). \"סה\"ד\" כתב שט\"ס בשם, וצ\"ל: שמעון נזירא.","cat": "sage"},{"i": 2657,"n": "לוי בר סוסיי","l": "ל","b": "מובא בירושלמי (יבמות פ\"א ה\"א), והוא לוי תלמידו של רבי.","cat": "sage"},{"i": 2658,"n": "לוי בר סימון","l": "ל","b": "מובא בבבלי (חולין קמ\"א ע\"ב), ש\"אקני פירות שובכו לרב יהודה וכו'\". ואין להכריע אם היה חכם או לא שכן מובא רק פעם אחת בש\"ס. ה\"יוחסין\" ו\"סה\"ד\" מנו אותו בין החכמים.","cat": "sage"},{"i": 2659,"n": "לוי בר סיסי","l": "ל","b": "הוא לוי בר סוסיי.","cat": "sage"},{"i": 2660,"n": "לוי בר פייטם","l": "ל","b": "מובא בתנחומא (פקודי ז'), ויתכן שט\"ס הוא וצ\"ל: ר' יוסי בר פוטרס, כמו בירושלמי (ע\"ז פ\"ג ה\"א).","cat": "sage"},{"i": 2661,"n": "ר' לוי בר פלטא","l": "ל","b": "אמורא ארץ ישראלי. מובא בירושלמי (תרומות פ\"י ה\"ו). נראה זהה ללוי בר פרטא (חולין צ\"ח ע\"א).","cat": "sage"},{"i": 2662,"n": "ר' לוי בר פנטי","l": "ל","b": "מובא בקה\"ר (פ\"ח - ג'). ע\"ע לוי בר בוטי.","cat": "sage"},{"i": 2663,"n": "ר' לוי בר פסטי","l": "ל","b": "מובא בירושלמי (מגילה פ\"ג ה\"ז). ע\"ע לוי בר בוטי.","cat": "sage"},{"i": 2664,"n": "לוי בר פרטא","l": "ל","b": "אמרוא ארץ ישראלי. מובא בבבלי (חולין צ\"ח ע\"א). נראה זהה לר' לוי בר פלטא (ירו', תרומות פ\"י ה\"ו). ר' יהודה בר סימון, מאמוראי א\"י בדור השלישי - הרביעי מסר משמו (ב\"ר רפ\"נ).","cat": "sage"},{"i": 2665,"n": "ר' לוי בר רבי","l": "ל","b": "מובא בתנחומא (בהעלותך - ו'), ונראה שט\"ס הוא, שכן שמו לא נודע לנו.","cat": "sage"},{"i": 2666,"n": "ר' לוי בר שלום","l": "ל","b": "מובא בתנחומא (חיי שרה - ז').","cat": "sage"},{"i": 2667,"n": "לוי בר שמואל","l": "ל","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (מגילה י\"ט ע\"א). למד יחד עם חברו רב הונא בר חייא בישיבת רב יהודה (סנהדרין ק' ע\"א).","cat": "sage"},{"i": 2668,"n": "לוי בריה דרב הונא בר חייא","l": "ל","b": "אמורא בבלי בדור השלישי - הרביעי. היה בן בתו של רבי ירמיה בר אבא (שהיה תלמיד חבר לרב), ובנו של רב הונא בר חייא. ור\"ה בר חייא אביו מסר לו מדברי סבו ר' ירמיה בר אבא (שבת קנ\"ו ע\"א). פעם הלך בדרך עם רבה בר רב הונא (שבת נ\"א ע\"ב), ומשם נראה, שרבה בר רב הונא היה גדול ממנו.","cat": "sage"},{"i": 2669,"n": "ר' לוי בריה דרבי שמואל בר נחמיה","l": "ל","b": "מובא בגמרות ישנות ובש\"ס יונתן (ברכות כ\"ח ע\"ב). ה\"יוחסין\" ו\"סה\"ד\" כתבו, שלר' שמואל נחמני היו שלושה בנים: הלל, לוי, ור\"נ, ובאמת ט\"ס היא וצ\"ל: א\"ר לוי לרבי הלל בריה דרבי שמואל בר נחמני, וכן הוא בש\"ס וילנא שלפנינו, וכן הגיה \"דק\"ס\", וכ\"ה בכ\"י, וב\"ילקוט\" שם (\"דק\"ס\" מסביר כיצד נפלה הטעות). לפי זה לא היה כלל אמורא ושמו לוי בריה דרבי שמואל בר נחמני, שכן לרבי שמואל בר נחמני לא היה בן שנשא שם זה.","cat": "sage"},{"i": 2670,"n": "ר' לוי בריה דר' זעירא","l": "ל","b": "מובא בקה\"ר (פ\"ז - ו').","cat": "sage"},{"i": 2671,"n": "ר' לוי הכהן בר חלפתא","l": "ל","b": "מובא בתנחומא (וירא - כ\"ה).","cat": "sage"},{"i": 2672,"n": "לוי הסדר","l": "ל","b": "תנא בדור הרביעי. תלמידם של רבי עקיבא ורבי ישמעאל. חברו של רבי ישמעאל בנו של רבי אלעזר בן עזריה (יומא פ\"ה ע\"א), שם מסופר, שהלך עם חברו אחרי רבותיו.","cat": "sage"},{"i": 2673,"n": "לוי הסרד","l": "ל","b": "כך גירסת \"הערוך\". ולפנינו: לוי הסדר (ברכות ס\"ה ע\"א), וכן גרס רש\"י: הסדר.","cat": "sage"},{"i": 2674,"n": "ר' לוי חתניה דר' זכריה","l": "ל","b": "מובא בשאלתות (פ' צ\"ו). ו\"סה\"ד\" מפקפק אם ט\"ס היא.","cat": "sage"},{"i": 2675,"n": "לוי סבא","l": "ל","b": "אמורא ארץ ישראלי בדור הראשון. רבי שמעון בן לקיש מסר משמו (חולין כ\"ט ע\"ב). ונראה ששמו שובש בכמה אופנים: ר\"ש בן לקיש בשם ר' סובייה (ירו', פסחים פ\"ו ה\"א), ריש לקיש בשם לוי סוכיא (ירו', עירובין פ\"י ה\"ב), רבי שמעון בן לקיש בשם לוי סיכייה (שם, הי\"ב), ר\"ש (בן לקיש) בשם לוי סוכייה (ירו', יומא פ\"ח ה\"ו). וכן רבי שמעון בשם לוי שובדא (ירו', שבועות פ\"א ה\"ו).","cat": "sage"},{"i": 2676,"n": "לוי סוכיא","l": "ל","b": "מובא בירושלמי (עירובין פ\"י ה\"ב). ע\"ע לוי סבא.","cat": "sage"},{"i": 2677,"n": "לוי סוכייה","l": "ל","b": "מובא בירושלמי (יומא פ\"ח ה\"ו). ע\"ע לוי סבא.","cat": "sage"},{"i": 2678,"n": "לוי סיכייה","l": "ל","b": "מובא בירושלמי (עירובין פ\"י הי\"ב). ע\"ע לוי סבא.","cat": "sage"},{"i": 2679,"n": "לוי סריסא","l": "ל","b": "מובא בירושלמי (שבת פ\"ג ה\"ג) אלבט (פילוסוף נכרי חברו של שמואל) שאל ללוי סריסא. ואולי צ\"ל: לוי בן סיסא (\"סה\"ד\" לא הביאו).","cat": "sage"},{"i": 2680,"n": "לוי פריסה","l": "ל","b": "מובא בירושלמי: \"ר' חנינא הוה מישתעי אהן עובדא לוי פריסה וכו'\" (גיטין פ\"ו ה\"ה). אין לדעת איזה ר' חנינא דיבר עם לוי פריסה, רבי חנינא, או רב חנינא. ואולי ט\"ס היא וצ\"ל: לוי בן סיסי (והוא לוי תלמידו דרבי).","cat": "sage"},{"i": 2681,"n": "רבי לוי צנבריא","l": "ל","b": "אמורא ארץ ישראלי בדור הרביעי. שאל לרבי יצחק ולרבי אמי (ירו', שביעית פ\"ו ה\"ב).","cat": "sage"},{"i": 2682,"n": "לוי שובדא","l": "ל","b": "מובא בירושלמי (שבועות פ\"א ה\"ו). והוא לוי סבא.","cat": "sage"},{"i": 2683,"n": "רבי לויטס איש יבנה","l": "ל","b": "תנא שאין לקבוע זמנו המדוייק. מובא ממנו מאמר אחד במשנה (אבות פ\"ד מ\"ד). וכן באבות דר' נתן (פכ\"ג).","cat": "sage"},{"i": 2684,"n": "ר' לויטס איש כפר אוני","l": "ל","b": "מובא ב\"זוהר\" (משפטים ק\"ג ע\"ב).","cat": "sage"},{"i": 2685,"n": "ר' לויטס חוזאה","l": "ל","b": "מובא ב\"זוהר חדש\" (ריש איכא).","cat": "sage"},{"i": 2686,"n": "ר' לולאני בר שווריה","l": "ל","b": "מובא בפדר\"כ (ל\"ט). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2687,"n": "ר' לוליאני","l": "ל","b": "מובא במדרש תהלים (פי\"ח - כ\"ט). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2688,"n": "ר' לוליאני בר טבריני","l": "ל","b": "אמורא ארץ ישראלי בדור הרביעי. שמו נשתבש כנראה בכמה אופנים: ר' לולייני בר טבריני (תנחומא בראשית - ד'); ר' לולייאני בר טבראי (ב\"ר פ\"ג - ח); ר' לולאני בר שווריה (פדר\"כ ל\"ט); ר' לוליני בר כובריא (פס' רבתי פ' פרה); ר' לולינא בר טברין (ב\"ר פ\"א - ג'); ר' לולינא בר טורין (שם פצ\"ח - כ') - ואולי כולם אחד. מובא גם ר' לוליאני (מדרש תהלים פי\"ח - כ\"ט).","cat": "sage"},{"i": 2689,"n": "ר' לולייאני בר טבראי","l": "ל","b": "מובא בב\"ר (פ\"ג - ח'). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2690,"n": "ר' לולינא בר טברין","l": "ל","b": "מובא בב\"ר (פ\"א - ג'). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2691,"n": "ר' לולינא בר טורין","l": "ל","b": "מובא בב\"ר (פצ\"ח - כ'). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2692,"n": "ר' לוליני בר כוריא","l": "ל","b": "מובא בפס' רבתי (פ' פרה). ע\"ע ר' לוליאני בר טבריני.","cat": "sage"},{"i": 2693,"n": "לחמא בר לואי","l": "ל","b": "מובא ב\"זוהר\" (שמות ט\"ז ע\"ב).","cat": "sage"},{"i": 2694,"n": "רבי ליא","l": "ל","b": "מובא בירושלמי (ברכות פ\"ב ה\"ח), והוא רבי אלעאי.","cat": "sage"},{"i": 2695,"n": "רבי ליונטי","l": "ל","b": "אמורא ארץ ישראלי בדור הששי. תלמידו של רבי יונה (ירו', יבמות פ\"ט ה\"ח), היה כנראה תלמידו המובהק (ירו', שבת פ\"ג ה\"ג).","cat": "sage"},{"i": 2696,"n": "ר' ליל בי ר' אלם","l": "ל","b": "מובא בירושלמי (ביצה פ\"ה ה\"ב). גיר' \"סה\"ד\": רבי הלל בריה דר' וולס. יש גורסים שהוא ר' ליל בר אלס.","cat": "sage"},{"i": 2697,"n": "ר' ליל בר אלם","l": "ל","b": "מובא בירושלמי (ביצה פ\"ה ה\"ג), והוא רבי הלל בריה דר' וולס.","cat": "sage"},{"i": 2698,"n": "רב לילי בר ממל","l": "ל","b": "אמורא בבלי בדור השני - השלישי. תלמידו של מר עוקבא (יבמות י\"ב ע\"א).","cat": "sage"},{"i": 2699,"n": "לילי בר מני","l": "ל","b": "כן גיר' \"יוחסין\". לפנינו: לילי בר ממל (יבמות י\"ב ע\"א).","cat": "sage"},{"i": 2700,"n": "ליליינוס ופפוס","l": "ל","b": "רש\"י כתב: \"צדיקים היו\" (תענית י\"ח ע\"ב), ושם מסופר שנהרגו ע\"י טוריינוס, אך במגילת תענית (רפי\"ב) לא כתוב שנהרגו, ואמנם היו בחיים בימי אדריינוס ורש\"י פירש: \"יש אומרין שנהרגו על בתו של מלך שנמצאה הרוגה ואמרו היהודים הרגוה וגזרו גזירה וכו' ואמרו אנו הרגנוה והרג המלך לאלו בלבד\" (תענית י\"ח ע\"ב) ותוספות מביא (שבת ע\"ב ע\"ב; סנהדרין ס\"א ע\"ב ד\"ה: רבא) ממה שמסופר (בירו', שביעית רפ\"ד): האחים לוליינוס ופפוס שנתנו להם מים בכלי זכוכית צבוע ולא רצו ונהרגו על קידוש ה'. רש\"י כתב: \"אין כל בריה יכולה לעמוד במחיצתן בגן עדן\" (תענית, שם).","cat": "sage"},{"i": 2701,"n": "רבי לעיי","l": "ל","b": "מובא בירושלמי (דמאי פ\"א ה\"א), והוא רבי אלעאי.","cat": "sage"},{"i": 2702,"n": "רבי מאיר","l": "מ","b": "גדול התנאים בדור הרביעי, כפי שאמרו: \"גלוי וידוע לפני מי שאמר והיה העולם, שאין בדורו של רבי מאיר כמותו\" (עירובין י\"ג ע\"ב), ועוד אמרו: \"כל הרואה רבי מאיר בבית המדרש, כאילו עוקר הרי הרים וטוחנן זה בזה\" (סנהדרין כ\"ד ע\"א), והוא היה כה חריף עד שאמרו: \"שלא יכלו חבריו לעמוד על סוף דעתו\" (עירובין שם). חברו רבי יוסי בן חלפתא היה משבח אותו ואומר: \"אדם גדול, אדם קדוש, אדם צנוע\" (ירו', מו\"ק פ\"ג ה\"ה). ריש לקיש אמר עליו \"פה קדוש\" (סנהדרין כ\"ג ע\"א). אביו של רבי מאיר היה שר צבא רומי, גוי ושמו נירון, וסמוך לפני חורבן הבית השני התגייר, ורבי מאיר היה בנו (גיטין נ\"ו ע\"א). רבי מאיר היה תלמידו המובהק של רבי עקיבא (עירובין י\"ג ע\"א). ואמרו: \"סתם משנה רבי מאיר, ואליבא דר\"ע\" (סנהדרין פ\"ו ע\"א). למד גם מרבי ישמעאל (עירובין שם). רבי עקיבא סמכו שעדיין היה בחור (סנהדרין י\"ד ע\"א רש\"י ד\"ה: ולא) ואח\"כ נסמך על ידי רבי יהודה בן בבא (שם). בין רבותיו היה גם אלישע בן אבויה (חגיגה ט\"ו ע\"ב). חבריו הגדולים היו: רבי יהודה (בר אלעאי), רבי שמעון (בר יוחי), רבי יוסי (בן חלפתא), ורבי אלעזר (בן שמוע). כשהעולם היה שמם מתורה, אמרו על רבי מאיר וחבריו: \"הם הם העמידו תורה אותה שעה\" (יבמות ס\"ב ע\"ב), והם מכונים \"רבותינו שבדרום\" (שם). בנוסף לחריפותו היה גם גדול באגדה ובדרוש (סנהדרין ל\"ח ע\"ב) ואמר רבי יוחנן: \"שלש מאות משלות היו לו לרבי מאיר\" (שם), וכן אמרו: \"משמת רבי מאיר בטלו מושלי משלים\" (סוף סוטה). בין תלמידיו המובהקים היו: סומכוס (עירובין י\"ג ע\"ב) ורבי שמעון בן אלעזר (חולין ו' ע\"א). וכן למד אצלו רבי (עירובין י\"ג ע\"ב). כשרבן שמעון בן גמליאל אבי רבי שימש כנשיא, היה רבי מאיר ה\"חכם\", ופעם פגע רשב\"ג בכבוד ר\"מ, והוא ניסה להוריד את רשב\"ג מנשיאותו, ועל כן קבעו שמו כ\"אחרים אומרים\" (עיין סוטה י\"ב ע\"א תד\"ה: אחרים). היה עניו ורודף שלום, עד שהרשה לאשה לירוק בעיניו למען השכנת שלום בינה לבין בעלה (ירו', סוטה פ\"א ה\"ד). התפרנס מהיותו לבלר (עירובין י\"ג ע\"א). ידע על פה כל המקראות בדקדוק חסירות ויתרות, ופעם כשהלך לעבר שנה בעסיא, ולא היתה שם מגילה, כתבה בעל פה (מגילה י\"ח ע\"ב). אשתו היתה ברוריה, בתו של רבי חנינא בן תרדיון (ע\"ז י\"ח ע\"א). היו לו ממנה שני בנים שמתו על פניו ביום שבת (מדרש משלי פל\"א - י'). היתה לו עוד אשה ששם אביה זרוז (חולין ו' ע\"ב). נפטר באסיה וציווה שיעבירוהו לארץ ישראל (ירו', כלאים פ\"ט ה\"ד). נפטר לפני חבריו רבי יהודה ורבי יוסי (קידושין נ\"ב ע\"ב).","cat": "sage"},{"i": 2703,"n": "מבוג","l": "מ","b": "אמורא בבלי בדור הראשון, מראשוני האמוראים. רב אמר משמו (זבחים ט' ע\"ב).","cat": "sage"},{"i": 2704,"n": "מגבילה","l": "מ","b": "מגבילה אחוי דר' אבא בר כהן. אמורא ארץ ישראלי בדור החמישי. \"אמר קומי ר' יוסי בשם ר' אחא\" (ירו', ברכות פ\"ג ה\"א).","cat": "sage"},{"i": 2705,"n": "רבי מונא","l": "מ","b": "תנא בדור החמישי. נראה, שהיה תלמידו של רבי יהודה ומסר כמה פעמים משמו (מגילה י\"ח ע\"ב).","cat": "sage"},{"i": 2706,"n": "מונבז","l": "מ","b": "תנא בדור הרביעי. מתלמידי רבי עקיבא. דן לפני ר\"ע רבו (שבת ס\"ח ע\"ב).","cat": "sage"},{"i": 2707,"n": "ר' מוסיא","l": "מ","b": "מובא בבבלי: \"אמר ר' מוסיא בר בריה דר' מסיא משמיה דר' מוסיא רבה\" (יומא ד' ע\"ב).","cat": "sage"},{"i": 2708,"n": "ר' מחסיא בר אידי","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (יומא ב' ע\"א).","cat": "sage"},{"i": 2709,"n": "מיאשא","l": "מ","b": "מחכמי ארץ ישראל הקדומים לפני תקופת התנאים. מובא במשנה: \"מעשה שזרע ר' שמעון [נראה ט\"ס וצ\"ל שמעון בלי ר'] איש המצפה, [ובא] לפני ר\"ג [הזקן] ועלו ללשכת הגזית ושאלו, אמר נחום הלבלר: מקובל אני מר' מיאשא שקיבל מן הזוגות שקבלו מן הנביאים וכו'\" (פאה פ\"ב מ\"ו).","cat": "sage"},{"i": 2710,"n": "רבי מיאשא","l": "מ","b": "אמורא ארץ ישראלי בדור השני. בר בריה דרבי יהושע בן לוי. מסר משם סבו ריב\"ל (כתובות ע\"ה ע\"ב). נראה שעמו נהג ריב\"ל ללמוד את פרשת השבוע (ירו', שבת פ\"א ה\"ב). כן נראה, שעמו היה המעשה המסופר, שפעם עמד בן בנו של ריב\"ל להחנק, ובא אחד ולחש שם טומאה שיתרפא, ואמר ריב\"ל מוטב היה שימות ולא יתרפא משם טומאה, ואכן כך היה ומת בחיי ריב\"ל (שם פי\"ד ה\"ד), ואמנם מצינו שנפטר עוד בחיי רבי אמי (כתובות פ\"ה ע\"ב).","cat": "sage"},{"i": 2711,"n": "ר' מיאשא א'","l": "מ","b": "תנא בדור השלישי. בר פלוגתיה דר' ישמעאל (פדר\"א פכ\"א).","cat": "sage"},{"i": 2712,"n": "ר' מיאשא ב'","l": "מ","b": "מן האמוראים הארץ ישראלים הראשונים בתחילת הדור הראשון. רבי חנינא היה תלמידו (נדרים ח' ע\"ב).","cat": "sage"},{"i": 2713,"n": "מיישא","l": "מ","b": "הוא מיאשה.","cat": "sage"},{"i": 2714,"n": "ר' מיישא בר ירמיה","l": "מ","b": "אמורא ארץ ישראלי המובא פעם אחת בירושלמי, שאמר משמו של רבי יוסי (נזיר פ\"ט ה\"ג). אם נניח שזה רבי יוסי, חברו של רבי יונה, א\"כ היה בדור החמישי לאמוראי ארץ ישראל, ואם נניח שזה רבי אסי (ולא רבי יוסי, כפי שיש פעמים רבות שיבוש מעין זה בירושלמי), הרי שהיה אמורא ארץ ישראלי בדור הרביעי (ואני סיווגתיו לרבי יוסי).","cat": "sage"},{"i": 2715,"n": "מיניימון","l": "מ","b": "תנא שאין לקבוע זמנו המדוייק. אפשר לומר, שאולי היה בדור הרביעי - החמישי, וזה לפי סדר החכמים המובא בירושלמי: \"כמה היא העראה וכו', ר\"א אומר וכו', מיניימון אומר וכו', בן עזאי אומר וכו', ר\"ע אומר וכו', ר' יהודה בן בתירא אומר וכו', ר\"א בן פנחס אומר וכו', מייניימון אומר וכו'\" (סוטה פ\"א ה\"ב), על אף שעל פי סדר הבאת השמות אין לקבוע את סדר חשיבותם בחכמה, כמו שכתבו התוספות (סוטה ד' ע\"א ד\"ה: בן).","cat": "sage"},{"i": 2716,"n": "מישא","l": "מ","b": "ע\"ע מיישא.","cat": "sage"},{"i": 2717,"n": "ר' מישא","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר משם רבי יוחנן (ירו', שבת פ\"א ה\"א). תלמידו של ר' שמואל בר יצחק (שם ה\"ב) ורבי אבהו (מד' שמואל פ\"ה - ג'). בין האומרים בשמו היה רבי אחא (ירו', כלאים פ\"ב ה\"ג); בין תלמידיו היה רבי יונה (ירו', ביכורים פ\"ב ה\"ג).","cat": "sage"},{"i": 2718,"n": "רבי מלאי","l": "מ","b": "אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"א\"ר מלאי משום רבי אלעזר בר' שמעון\" (שבת קל\"ט ע\"א). \"סה\"ד\" סובר, שר\"א בן מלאי המובא (שם) הוא בנו.","cat": "sage"},{"i": 2719,"n": "ר' מלוך","l": "מ","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (חולין מ\"ט ע\"א). מושבו היה בערביים ועל כן מכונה: ר' מלוך ערבאה (שם ברש\"י).","cat": "sage"},{"i": 2720,"n": "רב מלכיא","l": "מ","b": "ע\"ע רב מלכיו.","cat": "sage"},{"i": 2721,"n": "רב מלכיו","l": "מ","b": "מובא בבבלי: \"אמר רבא: מאן חכים כרב מלכיו דגברא רבה הוא קסבר וכו'\" (יבמות קי\"ג ע\"א). ועל מה שכתב \"שארית יוסף\", שהוא תלמיד רב (רב חי בדור הראשון) כתב \"סה\"ד\" שטעה, כי נראה שהיה בזמן רבא (רבא חי בדור הרביעי). ומצינו: \"רב מלכיא [א' בסוף ולא ו'] איקלע לבי ר' שמלאי\" (שבת מ\"ו ע\"א). ור' שמלאי חי בדור השני לאמוראים. ואכן, \"סה\"ד\" מפרידם לשני חכמים: רב מלכיא ורב מלכיו. ומצינו \"רב אדא בר אהבה אמר רב מלכיו\" (ביצה כ\"ח ע\"ב), ואולי ט\"ס היא וצ\"ל להיפך, שכן מצינו מספר פעמים: \"אמר רב מלכיו אמר רב אדא בר אהבה\" (כתובות ס\"א ע\"ב, ועוד).","cat": "sage"},{"i": 2722,"n": "רבי מנא א'","l": "מ","b": "אמורא ארץ ישראלי בדור השני. תלמידו של רבי ינאי (נדה ס\"א ע\"ב). שאל מרבי יוחנן (מנחות כ\"א ע\"א). חלק עם ריש לקיש (חולין כ\"א ע\"א). תלמיד רבי יוחנן. רב אסי קיבל ממנו (שם). משמו מסרו רבי אלעזר (ירו', מע\"ש פ\"א ה\"א) ורבי אבהו (ירו', סוטה פ\"ה ה\"ב).","cat": "sage"},{"i": 2723,"n": "רבי מנא בר תנחום","l": "מ","b": "אמורא ארץ ישראלי בדור השני - השלישי. היה כנראה מראשי העיר צור, בזמנו של רבי יוחנן (ירו', ע\"ז פ\"ב ה\"ח). רבי חייא בר אבא, שהיה אצלו, סיפר לר' יוחנן שיודע למתק את הים הגדול (שם). מסר בשם רבי חנינא (ירו', תרומות פ\"ח ה\"ג). משמו מסר רבי אסי (שם פ\"ה ה\"ב).","cat": "sage"},{"i": 2724,"n": "רבי מנא ב'","l": "מ","b": "מגדולי ואחרוני האמוראים הארץ ישראלים בדור החמישי. בנו ותלמידו של רבי יונה (ירו', דמאי רפ\"ז). היה גם תלמידו של רבי יוסי (חברו של אביו), כמובא בירושלמי (ברכות פ\"א ה\"ב), והיה בפטירת רבי יוסי רבו (שם פ\"ג ה\"א). חברו הגדול רבי חנינא דציפורין היה תלמיד חבר שלו (ירו', פסחים פ\"ו ה\"א): \"ג' הניחו כתרן בעולם הזה וירשו חיי העולם הבא, ואלו הן: יונתן בן שאול ואליעזר בן עזריה וזקני בתירא וכו', אף רבי חנינא דציפורין לרבי מנא וכו'\", (פירש \"קרבן העדה\", שנתן שררותיה לרבי מנא שהיה גדול ממנו). הלכות רבות משל ר' מנא מובאות בכל הש\"ס הירושלמי. העמיד תלמידים הרבה. נראה שהיה זמן מה בבבל (ירו', ב\"ב פ\"ב ה\"ח) ושם נפגש עם אביי (חברו של רבא), והיה לו דין ודברים עם בית הנשיא, ונרדף על ידם ונעשה לו נס וקיבלו עליהם אנשי בית הנשיא שלא יצערוהו עוד (תענית כ\"ג ע\"ב). בתקופת פטירתו של רבי מנא, גברו הגזרות בארץ ישראל ורבים מן האמוראים ירדו לבבל, ובתקופה ההיא נסתיימה תקופת האמוראים בארץ ישראל.","cat": "sage"},{"i": 2725,"n": "ר' מנא דציפורין","l": "מ","b": "מובא בירושלמי (גיטין פ\"א ה\"ב), ונראה שהוא ר' מנא ב'.","cat": "sage"},{"i": 2726,"n": "רבי מנא דשאב","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. חברו של ר' יהושע דסכנין, ושניהם מסרו משמו של רבי לוי (תנחומא אחרי ז').","cat": "sage"},{"i": 2727,"n": "מנחם","l": "מ","b": "מחכמי ישראל הקדומים בדור האחרון ל\"זוגות\" לפני התחלת תקופת התנאים. חי בדורם של הלל ושמאי, כמאה שנה לפני החורבן. בבלי (חגיגה ט\"ז ע\"ב) יש מחלוקת אמוראים לגביו: לדעת אביי יצא מנחם לתרבות רעה, וזה משמעות המשנה (שם, ט\"ז ע\"א): \"יצא מנחם נכנס שמאי\". ולדעת רבא: \"יצא לעבודת המלך, ויצאו עמו שמונים זוגות תלמידים\". על כל פנים, מנחם יצא ושמאי נכנס תחתיו ושמש כאב בית דין.","cat": "sage"},{"i": 2728,"n": "רבי מנחם","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"אמר רב יוסף בר אבא אמר רבי מנחם אמר רבי אמי\" (כתובות ע\"ד ע\"א) ומצינו: \"א\"ר חגיי כד הוו יתבונן קומי מנחם\" (ירו', עירובין פ\"ז ה\"ה). מסר גם משם רבי יוחנן (ירו', מע\"ש פ\"ב ה\"ג).","cat": "sage"},{"i": 2729,"n": "ר' מנחם אחי ר' גוריון","l": "מ","b": "אמורא ארץ ישראלי בדור הרביעי. פירש לפני רבי אלעאי (ירו', ב\"מ פ\"ט ה\"ח).","cat": "sage"},{"i": 2730,"n": "מנחם איש גופתה אריה","l": "מ","b": "מובא בירושלמי (סנהדרין פ\"י ה\"ב), ונראה שהוא פנחס בן גובתא דאריח, כמובא בספרא (פ' בלק). אין לדעת אם נמנה עם החכמים.","cat": "sage"},{"i": 2731,"n": "ר' מנחם איש גליא","l": "מ","b": "ע\"ע ר' מנחם דגליא.","cat": "sage"},{"i": 2732,"n": "רבי מנחם איש כפר שערים","l": "מ","b": "אמורא ארץ ישראלי בדור הראשון. למד בבית המדרש בו למדו חייא וחזקיה, בני רבי חייא. ונראה שהיה גדול מהם (נדה כ\"ז ע\"א).","cat": "sage"},{"i": 2733,"n": "ר' מנחם בר אבין","l": "מ","b": "מובא רו\"ר (פ\"ב - ג').","cat": "sage"},{"i": 2734,"n": "מנחם בר יהודה בן לוי","l": "מ","b": "חי בדור שני לאמוראי ארץ ישראל. אביו היה חכם. נראה אולי, כי רבי יהושע בן לוי היה אח אביו, וכי הוא עצמו היה חכם (ירו', דמאי פ\"ה ה\"א).","cat": "sage"},{"i": 2735,"n": "רבי מנחם בר יוסי סתומתאה","l": "מ","b": "הוא רבי מנחם בר' יוסי בן חלפתא. ומובא בבבלי: \"אמר רבה בר בר חנה א\"ר יוחנן: 'זו דברי ר' מנחם בר יוסי סתומתאה'\" (מגילה כ\"ו ע\"א).","cat": "sage"},{"i": 2736,"n": "ר' מנחם בר יעקב","l": "מ","b": "מובא בפסיקתא רבתי (פ' תשא - ס\"ט).","cat": "sage"},{"i": 2737,"n": "מנחם בר מבסימא","l": "מ","b": "אמורא ארץ ישראלי בדור הרביעי. מסר משם רבי אמי (ירו', סוף מעשרות).","cat": "sage"},{"i": 2738,"n": "רבי מנחם ברבי סימאי","l": "מ","b": "אמורא ארץ ישראלי בדור הראשון. בנו ותלמידו של רבי סימאי ומסר משם אביו (ירו', ברכות פ\"ה ה\"ב), ואביו רבי סימאי היה תנא (פסחים ק\"ד ע\"א רשב\"ם ד\"ה: ה\"ג). היה חסיד גדול, וקראו לו: \"בנן של קדושים\" (ע\"ז נ\"א ע\"א תד\"ה: ה\"ג) ומעולם לא הסתכל בצורת מטבע. כשנפטר, נתמעכו צורות פרצוף כל צלמים וצורת המטבעות (מו\"ק כ\"ה ע\"ב רש\"י ד\"ה: והוו).","cat": "sage"},{"i": 2739,"n": "רבי מנחם בר' יוסי בן חלפתא","l": "מ","b": "תנא בדור החמישי. הצעיר בחמשת בני ר' יוסי בן חלפתא. מכונה גם ורדימס, שפניו דומים לורד (שבת קי\"ח ע\"ב). רבי סתם כמה משניות אליביה (מגילה כ\"ו ע\"א) וסביר שאליו הכוונה (כתובות ק\"א ע\"ב): \"זו דברי ר' מנחם סתימתאה\". רב יוסף אמר עליו ש\"דרש להאי קרא כי סיני\" (סוטה כ\"א ע\"א). מובא בכמה שמות בש\"ס: אבירודימוס, אבדימוס.","cat": "sage"},{"i": 2740,"n": "ר' מנחם דגליא","l": "מ","b": "מראשוני האמוראים בארץ ישראל. רבי יוחנן מסר משמו (ירו', ברכות פ\"ד ה\"ד). יתכן אולי, שהוא רבי מנחם איש גליא, תנא דברייתא הנזכר בתוספתא (עירובין פ\"ח).","cat": "sage"},{"i": 2741,"n": "ר' מנחם חתניה דר' אלעזר בר אבונה","l": "מ","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בהש\"ר (רפ\"ה), שמסר בשם רבי שמעון בר יאסיניא (שהיה מתלמידי ריש לקיש).","cat": "sage"},{"i": 2742,"n": "מנחם טלמא","l": "מ","b": "אדם גדול, או כנראה אמורא בזמן רבי יוחנן (ירו', סנהדרין ספ\"ב). וכן מובא בקה\"ר (פ\"ה פסוק ברבות).","cat": "sage"},{"i": 2743,"n": "מנחם יודאפה","l": "מ","b": "מובא בבבלי (מעילה י\"ג ע\"ב), ונראה שהוא רבי מנחם יודפאה.","cat": "sage"},{"i": 2744,"n": "רבי מנחם יודפאה","l": "מ","b": "אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו (זבחים ק\"י ע\"ב). נראה, ששמו נשתבש לרבי מנחם יודפייה (ירו', סוכה פ\"ד ה\"ו) ולמנחם יודאפה (מעילה י\"ג ע\"ב).","cat": "sage"},{"i": 2745,"n": "רבי מנחם יודפייה","l": "מ","b": "מובא בירושלמי (סוכה פ\"ד ה\"ו), ונראה שהוא רבי מנחם יודפאה.","cat": "sage"},{"i": 2746,"n": "רבי מנחם סתימתאה","l": "מ","b": "ע\"ע רבי מנחם בר יוסי סתומתאה.","cat": "sage"},{"i": 2747,"n": "רבי מנחמא","l": "מ","b": "אמורא ארץ ישראלי בדור הששי. מסר בשם רבי מנא ב' (מדרש שמואל ספט\"ו), ומשם רב (ירו', שבת פי\"ד ה\"ג).","cat": "sage"},{"i": 2748,"n": "ר' מנחמא בר זעירע","l": "מ","b": "מובא בב\"ר (פל\"ד - ט'), ונראה שצ\"ל: ר' מנחמא בר זעירא.","cat": "sage"},{"i": 2749,"n": "ר' מנחמן","l": "מ","b": "מובא בשהש\"ר (פ\"ב פסוק כתפוח). ב\"סה\"ד\" הגיר': ר' מנאמן.","cat": "sage"},{"i": 2750,"n": "מני","l": "מ","b": "ראה מנא.","cat": "sage"},{"i": 2751,"n": "ר' מני","l": "מ","b": "מובא בבבלי (תענית כ\"ג ע\"ב), והוא ר' מנא ב'.","cat": "sage"},{"i": 2752,"n": "רבי מני בר פטיש","l": "מ","b": "אמורא ארץ ישראלי בדור השני. מסר משמו של רבי ינאי (חולין קל\"ה ע\"א). חלק עם רבי שמעון בן לקיש ורבי שמעון בן אליקם על רבי חנינא, רבי יוחנן ורבי אלעזר (שם מ\"ח ע\"ב).","cat": "sage"},{"i": 2753,"n": "רבי מני דמן צור","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי (סנהדרין ה' ע\"ב).","cat": "sage"},{"i": 2754,"n": "ר' מני דקסרין","l": "מ","b": "אמורא ארץ ישראלי בדור השני. מובא בויק\"ר (ספט\"ז), שחלק עם רבי יוחנן ורבי שמעון בן לקיש.","cat": "sage"},{"i": 2755,"n": "מניומי","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. מצינו שחלק עם ר\"נ (ב\"מ ס\"ו ע\"א).","cat": "sage"},{"i": 2756,"n": "מניומי אסיא","l": "מ","b": "מובא בבבלי (ע\"ז כ\"ח ע\"ב). ספק אם היה חכם.","cat": "sage"},{"i": 2757,"n": "רב מניומי בר חלקיה","l": "מ","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב חמא בר גוריא (שהיה תלמידו המובהק של רב), כמובא בבבלי (מנחות ל\"ב ע\"ב). היה חברם של רב חלקיה בר טוביא ורב הונא בר חייא (גיטין נ\"ז ע\"א).","cat": "sage"},{"i": 2758,"n": "רב מניומי בריה דרב נחומי א'","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. רב יוסף ואביי שלחו אליו לשאול שאלה בהלכה (כתובות פ\"א ע\"ב), לאחר ששאלו קודם לכן אותו ענין מרבי חנינא בר פפא (שם). ע\"ע רב מניומי בריה דרב נחומי ב'.","cat": "sage"},{"i": 2759,"n": "רב מניומי בריה דרב נחומי ב'","l": "מ","b": "אמורא בבלי בדור הששי - השביעי. תלמידו דאמימר (כתובות ס\"ט ע\"א). יתכן שיש שיבוש בשמות שכן קצת קשה להניח שהיו שני רב מניומי בריה דרב נחומי (אם כי הדבר יתכן, כפי שסווגתים). \"סה\"ד\" חיברם בערך אחד, אך כתב: \"אמימר היה הרבה אחר רבא ואיך מניומי דקאי קמי אמימר יהיה בזמן רב יוסף ורבא\".","cat": "sage"},{"i": 2760,"n": "מניומי סבא דגוש חלב","l": "מ","b": "מובא ב\"זוהר חדש\" (ריש שה\"ש).","cat": "sage"},{"i": 2761,"n": "מניומין כנדיקא","l": "מ","b": "מובא בבבלי, שבא לשאול לפני רבא (חולין מ\"ט ע\"ב). ולי נראה שספק אם היה חכם בכלל (מלאכתו היה מכירת כדים), \"יוחסין\" ו\"סה\"ד\" הביאוהו כחכם בלי להעיר מאומה.","cat": "sage"},{"i": 2762,"n": "מנימין בר איהי","l": "מ","b": "אמורא בבלי בדור השני. הוא ואחיו אבות בר איהי נהגו בחסידות (מגילה כ\"ח ע\"א). לאחד מהם היה גילוי אליהו (כתובות ס\"א ע\"א).","cat": "sage"},{"i": 2763,"n": "מנימין גר מצרי","l": "מ","b": "תנא ארץ ישראלי בדור הרביעי. תלמידו של רבי עקיבא. חברו של רבי יהודה (יבמות ע\"ו ע\"ב). משמו עולה, שהיה מצרי שהתגייר. נראה, שהוא בנימין שאמר לו ר\"ע: \"טעית\" (תוספתא שם פ\"ה).","cat": "sage"},{"i": 2764,"n": "מנימין סקסנאה","l": "מ","b": "ע\"ע בנימין גנוביא.","cat": "sage"},{"i": 2765,"n": "ר' מנסיא בר בריה דר' מנסיא","l": "מ","b": "מובא בבבלי (יומא ד' ע\"ב) לפי גיר' השאלתות, ולפנינו: ר' מוסיא בר בריה דר' מסיא.","cat": "sage"},{"i": 2766,"n": "מנשא","l": "מ","b": "אמורא ארץ ישראלי בדור הרביעי. ישב לפני רבי זירא (ירו', מגילה פ\"ב ה\"ב).","cat": "sage"},{"i": 2767,"n": "רבי מנשה","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רבי יהודה (ע\"ז כ\"ו ע\"א) וישב לפני רבי זירא (ירו', מגילה פ\"ה ה\"ב). חברו של רבה (עירובין ק\"ד ע\"א). עולא בא לביתו (שם).","cat": "sage"},{"i": 2768,"n": "רב מנשה בר זביד","l": "מ","b": "מובא בבבלי (יבמות י\"ט ע\"ב), והוא רב מנשיא בר זביד.","cat": "sage"},{"i": 2769,"n": "רב מנשה בר שגובלי","l": "מ","b": "אמורא בבלי בדור השני. מובא בבבלי (עירובין כ\"ט ע\"א): \"גורסק בר דרי משמיה דרב, מנשיא בר שגובלי משמיה דרב וכו', אמר רב יוסף: 'שרא ליה מריה לרב מנשיא בר שגובלי' וכו'\".","cat": "sage"},{"i": 2770,"n": "רב מנשיא בר גדא","l": "מ","b": "אמורא בבלי בדור הרביעי, תלמידו של רב הונא (סוכה י\"ג ע\"ב). לי נראה, שהיה מתלמידיו הקטנים של רב הונא, שכן מצינו: \"יתיב רב מנשיא בר גדא קמיה דאביי\" (מנחות י\"ז ע\"א) [שחי שני דורות אחרי רב הונא], ולא יתכן שתלמיד גדול של רב הונא ישב לפני אביי, אם כי אביי דיבר עליו בכבוד גדול: א\"ל אביי: 'עני מרי'\" (שם). וכן מסר רב מנשיא בר גדא משמיה דרב חסדא (סוכה שם).","cat": "sage"},{"i": 2771,"n": "רב מנשיא בר זביד","l": "מ","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב (שבועות מ\"ה ע\"ב), ואח\"כ ישב לפני רב הונא (יבמות מ\"ה ע\"ב), ושם הגיר': רב מנשה בר זביד.","cat": "sage"},{"i": 2772,"n": "רב מנשיא בר יעקב","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי (ב\"מ כ\"ו ע\"א; מנחות ל\"ב ע\"א).","cat": "sage"},{"i": 2773,"n": "רב מנשיא בר ירמיה","l": "מ","b": "אמורא בבלי בדור השני. תלמידו של רב (נזיר ס\"ה ע\"ב).","cat": "sage"},{"i": 2774,"n": "רב מנשיא בר ירמיה מדיפתי","l": "מ","b": "אמורא בבלי בדור הששי. חברו של רב אבא בר שומני (עירובין ס\"ד ע\"א), וכשנפרדו אמר כל אחד דבר הלכה שכן \"לא יפטר אדם מחברו אלא מתוך דבר הלכה שמתוך כך זוכרו\" (שם). אביו של רב מנשיא, רב ירמיה מדיפתי, היה כנראה תלמידו של רב פפא (ב\"ק ע\"ג ע\"א), ומסר משם רבא (זבחים ל\"ד ע\"ב).","cat": "sage"},{"i": 2775,"n": "מנשיא בר מנחם","l": "מ","b": "מובא בבבלי: \"של בית מנשיא בר מנחם היו סוחטין ברימונים, אמר רב נחמן 'הלכה כשל בית מנשיא בר מנחם' א\"ל רבא לרב נחמן: 'מנשיא בן מנחם תנא הוא' וכו'\" (שבת קמ\"ה ע\"ב). \"יוחסין\" כתב: \"בזמן רב,\" ו\"סה\"ד\": \"לא ידעתי מנ\"ל שהיה בזמן רב\".","cat": "sage"},{"i": 2776,"n": "מנשיא בר מנשה","l": "מ","b": "מובא בירושלמי (שבת פ\"ו ה\"ה), ונראה שט\"ס בשם, ו\"סה\"ד\" גם הוא היה לו ספק.","cat": "sage"},{"i": 2777,"n": "רבי מנשיא בר עות","l": "מ","b": "תנא בבלי בדור החמישי. מובא בבבלי, ששאל את רבי יאשיה רבה בבית עלמין דהוצל (סנהדרין י\"ט ע\"א).","cat": "sage"},{"i": 2778,"n": "רב מנשיא בר שגובלי","l": "מ","b": "אמורא בבלי בדור השלישי, מסר משמיה דרב (עירובין כ\"ט ע\"א). ומצינו: \"אמר רב יוסף: שרא ליה מריה לרב מנשיא בר שגובלי, אנא אמריתא ניהליה אמתני' והוה אמרה אברייתא\" (שם).","cat": "sage"},{"i": 2779,"n": "רב מנשיא בר תחליפא","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. מסר משם רב (פסחים ו' ע\"ב). מסופר, שרמי בר חמא לא אזמין עליה דרב מנשיא בר תחליפא [לא רצה לצרפו לשלשה לזימון], דתנא ספרא וספרי והלכתא, כי נח נפשיה דרמי בר חמא, אמר רבא: 'לא נח נפשיה דרמי בר חמא אלא דלא אזמין ארב מנשיא בר תחליפא'\" (ברכות מ\"ז ע\"ב).","cat": "sage"},{"i": 2780,"n": "רב מנשיא בריה דרבא","l": "מ","b": "מובא בבבלי (ביצה ל' ע\"ב), ולפי גיר' ב\"ח, שגרס \"רב מנשיא\" במקום \"רב מנשיא בריה דרבא\" לא היה בכלל אמורא ושמו רב מנשיא בריה דרבא, שכן שמו מובא בש\"ס רק בפעם זאת.","cat": "sage"},{"i": 2781,"n": "רב מנשיה","l": "מ","b": "אמורא בבלי בדור השני, תלמידו של שמואל (מנחות ל\"ה ע\"ב).","cat": "sage"},{"i": 2782,"n": "ר' מסיא","l": "מ","b": "מובא בבבלי (יומא ד' ע\"ב): \"מוסיא בר בריה דר' מסיא משמיה דר' מוסיא\".","cat": "sage"},{"i": 2783,"n": "מפשאה","l": "מ","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי: \"תני רב יוסף וכו' תני מפשאה\" (נדרים י' ע\"ב), ומפורש שם בפירוש המכונה פרש\"י: \"שם חכם\". \"יוחסין\" ו\"סה\"ד\" לא הביאוהו.","cat": "sage"},{"i": 2784,"n": "מר (4)","l": "מ","b": "אמורא בבלי בדור השלישי. מובא בבבלי: \"מר ממשכי אייתי וכו'\" (מנחות מ\"ג ע\"א), ופירש\"י ד\"ה מר: \"שם חכם\"; ד\"ה ממשכי: \"שם מקום\". ומצינו כמה חכמים ששמם \"מר\", כגון מר בר רב אשי, מר בר רב אידי, מר בר אמימר.","cat": "sage"},{"i": 2785,"n": "מר אחא","l": "מ","b": "מובא בבבלי: \"שהא למר אחא תריסר ירחי\" (ב\"ק קי\"ב ע\"ב), דרבינא, ופירש\"י: \"מר אחא זה שמו\". ספק אם היה חכם, ונראה ששמו המלא היה מר אחא, ו\"מר\" לא שימש אצלו לשון כבוד.","cat": "sage"},{"i": 2786,"n": "מר בר המדורי","l": "מ","b": "מובא בבבלי (שבת ק\"ז ע\"א), והוא בר המדורי.","cat": "sage"},{"i": 2787,"n": "מר בר חייא","l": "מ","b": "אמורא בבלי בדור החמישי - הששי. מובא בבבלי: \"אמימר משמיה דרב נחמן וכו' מר בר רב חייא מתני איפכא וכו'\" (חולין מ\"ה ע\"ב).","cat": "sage"},{"i": 2788,"n": "מר בר פופידתא","l": "מ","b": "חי בבבל בזמן אביי ורב יוסף. מובא בבבלי (עירובין ס' ע\"א). אין הוכחה שהיה חכם. \"סה\"ד\" כתב: \"ולא ידעתי אם חכם הוא\".","cat": "sage"},{"i": 2789,"n": "מר בר רב אדא","l": "מ","b": "אמורא בבלי בדור הראשון או השני. מובא בבבלי: \"רב אחא בר יוסף חש ביוקרא דליבא, אתא לקמיה דמר עוקבא, אמר ליה וכו', אזל שאל ביה מדרשא, אמרי ליה תנא דבי רב אדא, ואמרי לה תנא דבי מר בר רב אדא וכו'\" (שבת ק\"מ ע\"א).","cat": "sage"},{"i": 2790,"n": "מר בר רב אידאי (2)","l": "מ","b": "אמורא בבלי בדור החמישי - הששי. מובא בבבלי, שרב אדא בר שימי הקשה לו (חולין ס\"ג ע\"א). מר בר אמימר - אמורא בבלי בדור השביעי. בנו ותלמידו של אמימר (ב\"ב קע\"ד ע\"א). היה גם תלמידו של רב אשי (שם). מסר משם רבא (שבת מ\"ה ע\"ב).","cat": "sage"},{"i": 2791,"n": "מר בר רב אשי","l": "מ","b": "אמורא בבלי בדור השביעי. כינויו היה טביומי (ב\"ב י\"ב ע\"ב). בנו ותלמידו של מסדר הש\"ס רב אשי (חולין ע\"ו ע\"ב). ישב על כסא אביו רק 82 שנה לאחר פטירתו, שכן כשנפטר רב אשי, ירש מרימר את מקומו ואחרי מרימר מלך רב אידי בר אבין, ואחריו רב נחמן בר רב הונא (\"אגרת רב שרירא גאון\"). רק בשנת ד' קי\"ד (453), כשנפטר ר\"נ בר ר\"ה, הומלך מר בר רב אשי (ב\"ב י\"ב ע\"ב). חברם של יהודה בר אמימר ורב אחא מדיפתי, ושלושתם היו שווים בחוכמה ולא היה אחד מופלג מחברו (ברכות מ\"ה ע\"ב). רש\"י כתב (חולין שם): \"וכמר בר רב אשי קיי\"ל בכל דוכתי בר מתרתי\" (שבועות מ\"א ע\"א תד\"ה: ולמר). \"יוחסין\" כתב: \"מר בר רב אשי, שחתם התלמוד\".","cat": "sage"},{"i": 2792,"n": "מר בריה דרב אחא בריה דרבא","l": "מ","b": "אמורא בבלי בדור הששי. בנו של רב אחא, שהיה בנו של רבא. מסופר שהוא ומריון חברו עשו שותפות בצמד בקר ובאו לברר דין לפני רב אשי (מו\"ק י\"א ע\"ב). ע\"ע מריון בר אבין.","cat": "sage"},{"i": 2793,"n": "מר בריה דרב יוסף","l": "מ","b": "אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא, שכן מסר הרבה משמו (שבת מ\"ה ע\"ב). שקיל וטרי עם רב אשי בענין טריפות (חולין מ\"ח ע\"ב). אמר כי אינו חושש מהמינים ולא פחד ללכת להתוכח עמם (שבת קט\"ז ע\"א).","cat": "sage"},{"i": 2794,"n": "מר בריה דרבינא","l": "מ","b": "אמורא בבלי בדור הרביעי. תלמידו של רב ששת (שבת פ' ע\"ב). מסר משם רב נחמן (ברכות נ\"ח ע\"ב). חברו של רבא (חולין מ\"ג ע\"ב). היה מופלג בחסידות וישב בתענית כל השנה כולה מלבד עצרת ופורים וערב יום כיפור (פסחים ס\"ח ע\"ב). אמרו עליו: \"ירא שמים יוצא ידי שתיהן, ומנו: מר בריה דרבינא\" (שבת ס\"א ע\"א). מסופר על נסים שנעשו לו (ברכות נ\"ד ע\"א). בחתונת בנו ראה שהחכמים התבדחו יותר מהראוי. ושבר כוס של זכוכית לבנה שערכה 004 זוז, ונעצבו (שם, ל' ע\"ב). ממנו סיום תפילת \"שמונה עשרה\": \"אלקי נצור לשוני מרע וכו'\" (שם י\"ז ע\"א).","cat": "sage"},{"i": 2795,"n": "מר הונא בריה דרב נחמן","l": "מ","b": "מובא בבבלי (ב\"מ מ\"ז ע\"א), וגיר' \"דק\"ס\": הונא מר בריה דרב נחמן.","cat": "sage"},{"i": 2796,"n": "מר זוטרא (2)","l": "מ","b": "אמורא בבלי בדור הששי. מלך בפומבדיתא אחר רב כהנא בשנים ד' קע\"ג - קע\"ה (314 - 513) (\"אגרת רב שרירא גאון\"). תלמיד של רב פפא (חולין מ\"ג ע\"א) ושל רב פפי (סוכה כ\"ו ע\"ב) ומסר הרבה משמו, וכן היו בידו שמועות משם רב הונא (עירובין מ\"א ע\"ב). חברם של רב אשי ואמימר (ברכות מ\"ד ע\"ב), ושלושתם ישבו אפיתחא דבי אזגור מלכא (כתובות ס\"א ע\"א). רב אשי היה לו כתלמיד - חבר (מנחות ל\"ה ע\"ב). היו לו שני בנים חכמים, נתן בר מר זוטרא (סנהדרין כ\"ט ע\"א) והונא בריה דמר זוטרא (ב\"ב פ\"ו ע\"א).","cat": "sage"},{"i": 2797,"n": "מר זוטרא בר טוביה","l": "מ","b": "ע\"ע רב זוטרא בר טוביה.","cat": "sage"},{"i": 2798,"n": "מר זוטרא בריה דרב הונא בריה דרב פפי","l": "מ","b": "אמורא בבלי בדור הששי. חברו של רבינא ושקיל וטרי עמו (חולין מ\"ח ע\"א).","cat": "sage"},{"i": 2799,"n": "מר זוטרא בריה דרב טבי","l": "מ","b": "אמורא בבלי בדור הששי. חברו של רבינא ושקיל וטרי עמו (זבחים מ\"ח ע\"ב).","cat": "sage"},{"i": 2800,"n": "מר זוטרא בריה דרב מרי","l": "מ","b": "אמורא בבלי בדור החמישי. נין לשמואל, אביו היה רב מרי. בנה של רחל בת שמואל שנשבתה, והתחתנה עם גר, ששמו היה איסר גיורא. היה צעיר מרבינא ומצינו ששאל אותו (חולין ק\"ח ע\"א), וחלק עמו (ב\"מ ס\"ז ע\"ב). היה לו אח ושמו ר' אחא סבא (קידושין ס\"ה ע\"ב).","cat": "sage"},{"i": 2801,"n": "מר זוטרא בריה דרב נחמן","l": "מ","b": "אמורא בבלי בדור הרביעי. בנו ותלמידו של ר\"נ (סוטה י' ע\"א). היה גדול בדורו. \"אמרוה רבנן קמיה דרבא משמיה דמר זוטרא בריה דר\"נ\" (ב\"ב קנ\"א ע\"ב). פעם דן דין תורה וטעה בפסק דין, ושאל את ר' יוסף אם חייב לשלם (סנהדרין ה' ע\"א). היה עשיר ומדקדק במעשיו (מו\"ק י\"ב ע\"א).","cat": "sage"},{"i": 2802,"n": "מר זוטרא חסידא","l": "מ","b": "אמורא בבלי שאין לקבוע זמנו במדוייק. נראה שהיה הריש במקומו: \"מר זוטרא חסידא כי הוו מכתפי ליה בשבתא דריגלא\" (סנהדרין ז' ע\"ב). היה זהיר במעשיו: \"דמר זוטרא חסידא כי מחייב בר בי רב שמתא, משמית נפשיה ברישא\" (נדרים ז' ע\"ב).","cat": "sage"},{"i": 2803,"n": "מר זוטרא מדרישבא","l": "מ","b": "אמורא בבלי בדור הששי - השביעי. בא לפני רב אשי לשאול בדין ירושה (ב\"ב קכ\"ו ע\"ב).","cat": "sage"},{"i": 2804,"n": "מר זוטרא רבה","l": "מ","b": "אמורא בבלי בדור החמישי. מר זוטרא דרש משמו (ביצה ח' ע\"א).","cat": "sage"},{"i": 2805,"n": "מר יהודה","l": "מ","b": "אמורא בבלי בדור השלישי. מסר בשם אבימי [רבו של ר' חסדא] (חולין מ\"ח ע\"א). הקשה לרב יוסף ולרב שמואל בריה דרבה בר בר חנה, ולא ידעו להשיב לו, ורבה קרא לו: קנטרן פלגא [קנטרן רגיל לחלוק על חברו] (קידושין נ\"ח ע\"א). פעם ישב לפני המלך הפרסי שבור מלכא, והמלך אמר עליו שהוא מכיר בו שהוא פרוש ולא יאכל דבר איסור (סוף ע\"ז).","cat": "sage"},{"i": 2806,"n": "מר יוחנא בריה דרב חנא בר אדא","l": "מ","b": "אמורא בבלי בדור הרביעי. רבא ורב ספרא ביקרו אצלו (חולין קל\"ג ע\"א), והגמרא מפקפקת אם צ\"ל \"בר ביזנא\" או \"בר אדא\".","cat": "sage"},{"i": 2807,"n": "מר יוחנא בריה דרב חנא בר ביזנא","l": "מ","b": "אמורא בבלי בדור הרביעי (ע\"ע מר יוחנא בריה דרב חנא בר אדא).","cat": "sage"},{"i": 2808,"n": "מר יחוני","l": "מ","b": "זו גירסת הרי\"ף (מו\"ק כ\"ד ע\"א).","cat": "sage"},{"i": 2809,"n": "מר ינוקא (2)","l": "מ","b": "אמורא בבלי. בנו של רב חסדא ואחיו של מר קשישא. דעת תוספות (ב\"ב ז' ע\"ב ד\"ה: מר) ש\"מר ינוקא\" הוא האח הקשיש, ועל שם שנולד בינקותו של רב חסדא, נקרא \"מר ינוקא\", ו\"מר קשישא\" הוא הצעיר ונולד בקשישותו של רב חסדא, ורש\"י פירש (כתובות פ\"ט ע\"ב): שני בנים היו לרב חסדא ושניהם שוים, אלא שהגדול קורין לו \"מר קשישא\" ולצעיר קורין לו \"מר ינוקא\". מוזכר רבות עם רב אשי, כגון: \"א\"ל מר ינוקא ומר קשישא בריה דרב חסדא לרב אשי וכו'\" (פסחים ק\"ז ע\"א). לפי הזמנים קשה להולמו, כי רב חסדא נפטר ד' ס\"ח (803), ורב אשי נפטר ד' קפ\"ו (624) (811 שנה הבדילו ביניהם).","cat": "sage"},{"i": 2810,"n": "מר ממשכי","l": "מ","b": "אמורא ששמו מר ושם מקומו משכי (מנחות מ\"ג ע\"א רש\"י). ע\"ע מר.","cat": "sage"},{"i": 2811,"n": "מר מר קשישא בריה דר' חסדא","l": "מ","b": "ע\"ע מר קשישא.","cat": "sage"},{"i": 2812,"n": "מר נתן אסיא","l": "מ","b": "כך גירסת הרי\"ף, ולפנינו ר' נתן בר אסיא (פסחים נ\"ב ע\"א).","cat": "sage"},{"i": 2813,"n": "מר עוקבא (4)","l": "מ","b": "אמורא בבלי בדור הראשון - השני. היה ראש הגולה אחרי רב הונא ריש גלותא (\"אגרת רב שרירא גאון\"), וכן כתבו תוספות (סנהדרין ל\"א ע\"ב ד\"ה: אי). רש\"י כתב (מו\"ק ט\"ז ע\"ב) שהיה נשיא (ראש גולה בבבל כמו נשיא בא\"י). בלימוד תורה ישב מר עוקבא לפני שמואל, וכשהיו יושבים בדין ישב שמואל לפני מר עוקבא (שם). היה אב\"ד בכפרי (קידושין מ\"ד ע\"ב). האריך ימים אחרי רב ושמואל (כתובות ס\"ט ע\"ב). בין תלמידיו היו רב חסדא (ברכות י' ע\"ב) ורבי זירא (שבת ק\"ח ע\"ב). היה עשיר (שם נ\"ד ע\"ב רש\"י). נתן צדקה בסתר (כתובות ס\"ז ע\"ב). לפני שנפטר בדק ומצא כתוב בספריו שפיזר שבעת אלפי דינרי זהב, ואמר: \"צידה קלה לדרך רחוקה\", עמד ופיזר מחצית ממונו (שם).","cat": "sage"},{"i": 2814,"n": "מר עוקבא בן ברתא דרב","l": "מ","b": "אמורא בבלי בדור השלישי. הוא ואחיו נחמיה מכונים: \"שרים גאים היוצאים מישראל\" (חולין צ\"ב ע\"א). ע\"ע רבנא נחמיה בן ברתא דרב, וכן רבנא עוקבא.","cat": "sage"},{"i": 2815,"n": "מר עוקבא בר חייא","l": "מ","b": "אמורא בבלי בדור הראשון. מרבותיו של רב חסדא (יבמות ס\"ג ע\"ב).","cat": "sage"},{"i": 2816,"n": "מר עוקבא בר חמא","l": "מ","b": "אמורא בבלי בדור השלישי - הרביעי. נראה שהוא רב עוקבא בר חמא. הוא ואחיו רמי בר חמא היו חתניו של רב חסדא, ונשאו שתי אחיות: בנותיו של רב חסדא (ברכות מ\"ד ע\"א). ומצינו: \"רמי בר חמא ורב עוקבא בר חמא זבון אמתא בהדי הדדי וכו', אתו לקמיה דאביי\" (ב\"ב כ\"ט ע\"ב). הקשה לרב נחמן (ב\"מ ס\"ה ע\"א). נראה, שהיה גם תלמידו של רבי יוסי בר חנינא (זבחים נ\"ה ע\"ב).","cat": "sage"},{"i": 2817,"n": "מר עוקבן","l": "מ","b": "אמורא בבלי בדור השני. אמר בשם רב (ירו', עירובין פ\"ח ה\"ה). ומצינו: \"ר' יעקב בר אחא ורבי זירא חד בשם מר עוקבן וחד בשם ר\"נ בר יהודה\" (שם פ\"ו ה\"ח), וכן מצינו: \"ר' יונה ור' יוסי חד בשם מר עוקבן וחד בשם ר\"נ בר יעקב\" (שם פ\"ז ה\"א).","cat": "sage"},{"i": 2818,"n": "מר קשישא","l": "מ","b": "אמורא בבלי בדור החמישי. בנו של האמורא המפורסם רב חסדא, ואחיו של מר ינוקא. תוספות סוברים שמר ינוקא הוא הגדול (ב\"ב ז' ע\"ב ד\"ה: מר). רש\"י סובר שמר קשישא הוא הגדול (כתובות פ\"ט ע\"ב ד\"ה: מר). לקח חלק בסידור הש\"ס עם רב אשי (פסחים ק\"ז ע\"א; ב\"מ ס\"ו ע\"ב; ב\"ב ז' ע\"ב). לפי סדר השנים נראה שנפטר בחיי רב אשי, ונראה שאחיו נפטר לפניו, שכן מצינו אותו עם רב אשי ללא אחיו (כתובות פ\"ט ע\"ב; שבת קי\"ד ע\"ב; סוכה ח' ע\"א).","cat": "sage"},{"i": 2819,"n": "מר קשישא בריה דרבא","l": "מ","b": "אמורא בבלי בדור הששי. מובא בבבלי: \"אשכחוה לרב אשי דקא מצטער מהבלא (שהיה אבק עולה ומרבה הבל), א\"ל: 'לא סבר לה מר להא דתניא, הרוצה לרבץ ביתו בשבת וכו'\" (שבת צ\"ה ע\"א).","cat": "sage"},{"i": 2820,"n": "מר קשישא בריה דרבה","l": "מ","b": "מובא בבלי (שבת צ\"ו ע\"א), ודף קודם לכן (שבת צ\"ה ע\"א) הגיר': \"מר קשישא בריה דרבא\".","cat": "sage"},{"i": 2821,"n": "מר שמואל (2)","l": "מ","b": "מובא בבבלי (חולין ק\"ה ע\"א), והוא שמואל, ובאותו עמוד מובא גם \"שמואל\" וגם \"מר שמואל\" ואחד הם.","cat": "sage"},{"i": 2822,"n": "מר שמואל מר","l": "מ","b": "אמורא בבלי בדור החמישי. היה בזמנו של רבא ורב פפא. ומצינו (ביצה כ\"א ע\"ב): \"אדבריה רבא למר שמואל\" (מר - דק\"ס); (שם י\"ד ע\"ב): \"רב פפי איקלע לבי מר שמואל\" (מר - דק\"ס) \"אייתי ליה דייסא ולא אכל וכו' מפני פריצותא דעבדי\".","cat": "sage"},{"i": 2823,"n": "רב מרדכי א'","l": "מ","b": "אמורא בבלי בדור הרביעי. מובא בבבלי: \"בעא מיניה רב מרדכי וכו', אתא שיליה לרב יוסף וכו'\" (שבת צ\"ט ע\"ב).","cat": "sage"},{"i": 2824,"n": "רב מרדכי ב'","l": "מ","b": "אמורא בבלי בדור הששי. תלמיד תלמידו של רבא, ואמר לרב אשי: \"הכי אמר אבימי מהגרוניא משמיה דרבא\" (כתובות ק\"ט ע\"ב).","cat": "sage"},{"i": 2825,"n": "רב מרי א'","l": "מ","b": "אמורא בדור השני - השלישי. תלמידו של רבי יוחנן (ברכות מ' ע\"א). ר\"נ הסתמך עליו ואמר: \"ולאו אמר רב מרי וכו'\" (שבת קנ\"ב ע\"ב). אביי אמר לרב יוסף: \"והאמר רב מרי\" (ב\"ב כ\"ג ע\"א).","cat": "sage"},{"i": 2826,"n": "רב מרי בר אבוה","l": "מ","b": "אמורא בדור השלישי - הרביעי תלמידו של ר' יצחק (פסחים פ\"ג ע\"א).","cat": "sage"},{"i": 2827,"n": "רב מרי בר איסור גיורא","l": "מ","b": "אמורא בבלי בדור הרביעי. ופרש\"י: בכמה מקומות קרי ליה בר רחל, [ואמו] בתו של שמואל היתה ונשבית בין נכרים ונתעברה מנכרי, ואח\"כ התגייר הנכרי ושמו איסור והתחתן עמה ונולד רב מרי, כמובא (ב\"ב קמ\"ט ע\"א): רב מרי הורתו שלא בקדושה ולידתו בקדושה הואי (ברכות ט\"ז ע\"א). היה חכם גדול ורבא קרא לו \"מר\" (ב\"מ ע\"ג ע\"ב). אמר משמיה דאביי, (ב\"ב ס\"א ע\"ב). זכה לראות מלאכים (תענית כ\"ד ע\"ב). העמיד שני בנים חכמים ושמם מר זוטרא ורב אדא סבא, שהיו בימי רב אשי (קידושין ס\"ה ע\"ב). ההבדל בשנים בין בת שמואל לרב אשי גדול מאד, ואכן הגמרא תמהה דילמא תרי מרי בר רחל היו (שבת קנ\"ד ע\"א).","cat": "sage"},{"i": 2828,"n": "מרי בר איסק","l": "מ","b": "שני מרי בר איסק היו, אחד בימי רב חסדא ואחד בימי רב אשי, כפי שפירשו התוספות (יבמות כ\"א ע\"ב ד\"ה: רב אשי), ונראה ששניהם לא היו חכמים. \"יוחסין\" ו\"סה\"ד\" הביאום מבלי לציין שלא היו חכמים.","cat": "sage"},{"i": 2829,"n": "מרי בר בריה דרב הונא בריה דרבי ירמיה בר אבא","l": "מ","b": "מובא בבבלי (ברכות ל\"א ע\"א), וצ\"ל מרי בריה דר\"ה וכו'.","cat": "sage"},{"i": 2830,"n": "רב מרי בר חמא","l": "מ","b": "אמורא בבלי בדור הרביעי. הקשה לרב חסדא, ונראה שהיה תלמידו (ערכין כ\"א ע\"א).","cat": "sage"},{"i": 2831,"n": "רב מרי בר יעקב","l": "מ","b": "אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. מסר משם רבי יודן (מדרש שמואל פי\"ג - ח').","cat": "sage"},{"i": 2832,"n": "רב מרי בר מר","l": "מ","b": "אמורא בבלי בדור השלישי. תלמידו של מר עוקבא (יבמות ע\"ו ע\"א). ר' אבא בר זבדא שלח [מארץ ישראל] למרי בר מר, שישאל הלכה מרב הונא, ואדהכי נפטר רב הונא (גיטין פ\"ו ע\"ב). חי עד דורו של רבה ואביי (מגילה ז' ע\"ב). רבה שדר ליה למרי בר מר ביד אביי (שם). ה\"יוחסין\" כתב שהיה בזמן שמואל, ו\"סה\"ד\" כתב: \"לא מצאתי\".","cat": "sage"},{"i": 2833,"n": "מרי בר מר עוקבא","l": "מ","b": "אמורא בבלי בדור השני. בנו של מר עוקבא. תלמידו של שמואל (חולין מ\"ג ע\"ב). יש משבשים וגורסים מר בר מר אמר מר עוקבא, ולגירסתם לא היה למר עוקבא בן ושמו מרי.","cat": "sage"},{"i": 2834,"n": "מרי בר מרי","l": "מ","b": "מובא בבבלי (ב\"ב צ\"א ע\"א), וכתב \"דק\"ס\" שצ\"ל: מרי בר מר.","cat": "sage"},{"i": 2835,"n": "רבי מרי בר רב כהנא","l": "מ","b": "אמורא בבלי בדור השלישי. בנו של רב כהנא (תלמידו של רב). נראה, שהיה תלמידו של רב יהודה (ע\"ז מ\"ט ע\"א).","cat": "sage"},{"i": 2836,"n": "רב מרי בר רחל","l": "מ","b": "מובא בבבלי (שבת קנ\"ד ע\"א), והוא רב מרי בר איסור גיורא.","cat": "sage"},{"i": 2837,"n": "רב מרי ברה דבת שמואל","l": "מ","b": "ע\"ע רב מרי בר איסור גיורא.","cat": "sage"},{"i": 2838,"n": "רב מרי ברה דבת שמואל בר שילת","l": "מ","b": "מובא בבבלי (ב\"ב ס\"א ע\"ב). \"סה\"ד\" הגיה מסברתו למחוק תיבות בר שילת, וכן הגיה \"דק\"ס\"; א\"כ, מעולם לא היה חכם בשם זה, שכן הוא מובא בש\"ס רק במקום זה.","cat": "sage"},{"i": 2839,"n": "רב מרי בריה דבת שמואל","l": "מ","b": "מובא בבבלי (ברכות ט\"ז ע\"א), והוא רב מרי בר איסור גיורא.","cat": "sage"},{"i": 2840,"n": "רב מרי בריה דרב אשי","l": "מ","b": "מובא בבבלי (ב\"מ ק\"ג ע\"א), ונראה ט\"ס, כמוכח ב\"סה\"ד\" וב\"דק\"ס\", וא\"כ לא היה ולא נברא חכם בשם זה שכן מובא בש\"ס רק במקום זה.","cat": "sage"},{"i": 2841,"n": "רב מרי בריה דרב ביזנא","l": "מ","b": "אמורא בבלי בדור השלישי, בזמנו של רב יוסף (ביצה כ\"ח ע\"ב).","cat": "sage"},{"i": 2842,"n": "רב מרי בריה דרב הונא בריה דרב ירמיה בר אבא","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בן בנו של ר' ירמיה בר אבא (תלמיד חבר של רב). \"א\"ל רב חסדא למרי בריה דר\"ה בריה דר' ירמיה בר אבא וכו': 'הא אמר אבוה דאבוך משמיה דרב'\" (עירובין כ\"א ע\"א). אמר בשם רבי יוחנן (ברכות כ\"ו ע\"א).","cat": "sage"},{"i": 2843,"n": "רב מרי בריה דרב חסדא","l": "מ","b": "אמורא בבלי בדור הרביעי. בנו של רב חסדא. היה גיסו של רבא (רבא התחתן עם אחותו). מסופר עליו ועל אחיו רב פנחס, שלאחד מהם נגלה אליהו הנביא ודבר עמו (כתובות ס\"א ע\"א).","cat": "sage"},{"i": 2844,"n": "רב מרי בריה דרב פנחס","l": "מ","b": "אמורא בבלי בדור הששי. חי בימי רב אשי. בן בנו של רב חסדא כמובא \"ההוא גברא דאנסוהו נכרים, ואחוי אחמרא דרב מריה בריה דרב פנחס בריה דרב חסדא וכו', אתא לקמיה דרב אשי וכו'\" (ב\"ק קי\"ז ע\"א).","cat": "sage"},{"i": 2845,"n": "מרי בת רב הונא","l": "מ","b": "מובא בבבלי (עירובין ס\"ד ע\"א), ונראה אולי שצ\"ל: מרי בריה דרב הונא בריה דר' ירמיה בר אבא.","cat": "sage"},{"i": 2846,"n": "רב מרי ב'","l": "מ","b": "אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא (קדושין ל\"ב ע\"ב). שאל מרב פפא (ברכות כ\"ד ע\"א). רב אשי הקשה לו (זבחים כ\"ט ע\"ב).","cat": "sage"},{"i": 2847,"n": "רבי מריון","l": "מ","b": "אמורא ארץ ישראלי בדור השני. תלמידו של רבי יהושע בן לוי, כמובא: \"והאמר רבי מריון אמר רבי יהושע בן לוי, ואמרי לה חנא רבה בר מריון בדבי רבן יוחנן בן זכאי וכו'\" (עירובין י\"ט ע\"א).","cat": "sage"},{"i": 2848,"n": "מריון בר אבין","l": "מ","b": "אמורא בבלי בדור הששי. חברו של מר בריה דרב אחא בריה דרבא. מסופר, שהיה להם צמד בקר בשותפות, ואירע אבילות למר בריה דרב אחא, ולא שלח את שורו לחרוש בשדה לפי שהיה אבל (כי חשב שמצווה על שביתת בהמתו מדרבנן), ורב אשי העמידו על טעותו ואמר: \"גברא רבא כמר בריה דרב אחא בריה דרבא עביד הכי, נהי וכו'\" (מו\"ק י\"א ע\"ב).","cat": "sage"},{"i": 2849,"n": "מריון בריה דרבין","l": "מ","b": "ע\"ע מריון בר אבין.","cat": "sage"},{"i": 2850,"n": "מרימר","l": "מ","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא (חברו של רב אשי), שמצינו: \"א\"ל רבינא למרימר וכו' ורבינא לשיבושי למרימר וכו'\" (יבמות ע\"ה ע\"ב), ופרש\"י: \"לידע אם מחודד הוא להשיב על שאלתו\". נראה, שהיה קטן ממר זוטרא (פסחים ק' ע\"א), ואמר משמו של מר זוטרא (סוכה מ\"ה ע\"א). רבינא האחרון היה תלמידו: \"אמר רבינא: 'אמר לי מרימר'\" (חולין קל\"ב ע\"א), וכן: \"יתיב מרימר וקאמר וכו', איתיביה רבינא למרימר וכו'\" (שבת פ\"א ע\"ב). באו לשאול ממנו: יהודה בר מרימר (בנו), מר בר רב אשי ורב אחא מדיפתא (ברכות מ\"ה ע\"ב). נראה, שישב על כסאו של רב אשי משנים ד' קפ\"ו - קצ\"א (624 - 134).","cat": "sage"},{"i": 2851,"n": "מרימר בר חנינא","l": "מ","b": "חי בדור הרביעי לאמוראי בבל, ואין להכריע אם היה חכם. מובא בבבלי, ששכר פרידה ומתה ובאו לשאול מרבא אם חייב לשלם (ב\"מ צ\"ז ע\"א) ומהענין שם, שלא טען לפני רבא את הטענות שרבנן אמרו לרבא, ניתן אולי לומר שבאמת לא היה חכם.","cat": "sage"},{"i": 2852,"n": "רבי מרינוס (2)","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי. לדעתו של הרשב\"ם (ב\"ב נ\"ו ע\"א), מסר משום רבי יוחנן (ועיין שם תוספות ד\"ה: אין).","cat": "sage"},{"i": 2853,"n": "מרינוס בי רבי יהושע","l": "מ","b": "מובא בירו' (ברכות פ\"ו ה\"ה), והוא מרינוס בריה דרבי אושעיא רבה.","cat": "sage"},{"i": 2854,"n": "רבי מרינוס בריה דרבי אושעיא רבה","l": "מ","b": "אמורא ארץ ישראלי בדור הראשון - השני. חברו של רבי חנינא, ויחד מסרו בשם אבא נהוראי (ב\"ר פצ\"א - ט'). חלק עם אביו רבי אושעיא (ירו', גיטין פ\"ד ה\"ו).","cat": "sage"},{"i": 2855,"n": "מרתא (2)","l": "מ","b": "אחיו של רבי חייא ודודו של רב וחמישה אחים היו: \"איבו (אביו של רב) וחנה (אביו של רבה בר חנה) ושילא ומרתא ורבי חייא כולהו בני אבא בר אחא וכו'\" (סנהדרין ה' ע\"א).","cat": "sage"},{"i": 2856,"n": "משה בר עצרא הכהן","l": "מ","b": "חי בבבל בזמנו של אביי, ואין לדעת אם היה חכם. בנו רב הונא היה חכם: \"משה בר עצרי ערבה דכתובתה דכלתיה הוה, רב הונא בריה צורבא מדרבנן היה וכו', אמר אביי וכו'\" (ב\"ב קע\"ד ע\"ב).","cat": "sage"},{"i": 2857,"n": "ר' משין בר נגרי","l": "מ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר יחד עם ר' יודן ור' איבו משמו של ר' יוחנן (ב\"ר פפ\"ב - ד').","cat": "sage"},{"i": 2858,"n": "רב משרשיא","l": "מ","b": "אמורא בבלי בדור החמישי. תלמידו המובהק של אביי (קידושין ל\"ג ע\"א), ותלמידו של רבא (גיטין צ' ע\"א). למד יחד עם חברו רבינא לפני רבא (יבמות ל\"ו ע\"ב), היה חתנו של רב כהנא (ב\"ב צ\"ז ע\"ב). חותנו רב כהנא שאל מרבא (שם). היה לו בן חכם ושמו רב סמא, שהיה תלמידו של רב אשי (חולין י\"ז ע\"ב). אמר לבנו שלמד לפני רב פפא, שישאל מרב פפא שאלה מסובכת, ורב פפא אמר לבנו של רב משרשיא: \"אי דייקינן כולי האי לא הוי תנינן\" (עירובין מ\"ח ע\"א).","cat": "sage"},{"i": 2859,"n": "רב משרשיא בר בריה דרב אחא בר רב","l": "מ","b": "מאחרוני האמוראים הבבליים בדור השמיני. נראה, שהיה מראשי רבנן סבוראי. מובא בבבלי: \"אמר רב משרשיא מ\"ט דאבוה דאבא וכו'\" (סנהדרין ע\"ז ע\"א).","cat": "sage"},{"i": 2860,"n": "רב משרשיא בר חיקלאי","l": "מ","b": "אמורא בבלי שאין לקבוע זמנו המדוייק. מובא פעם אחת בבבלי (כתובות ק' ע\"ב).","cat": "sage"},{"i": 2861,"n": "רב משרשיא בר פקוד","l": "מ","b": "אמורא בבלי. \"סה\"ד\" כתב, שחי בזמנו של רב סמא בר רבא (בדור השביעי), ומלך פרס הרגו.","cat": "sage"},{"i": 2862,"n": "רב משרשיא בר רב דימי","l": "מ","b": "מובא בבבלי (גיטין ע\"ח ע\"א), ונראה שצ\"ל: רב משרשיא בר רב אמי.","cat": "sage"},{"i": 2863,"n": "רב משרשיא בר רבא","l": "מ","b": "אמורא בבלי בדור החמישי. בנו ותלמידו של רבא. רבא אמר על בנו: \"חכים ברי בטרפות כרבי יוחנן\" (חולין נ' ע\"א).","cat": "sage"},{"i": 2864,"n": "רב משרשיא בריה דרב אחא","l": "מ","b": "אמורא בבלי בדור הששי. מובא בבבלי: \"אמר ליה רב משרשיא בריה דרב אחא לרבינא וכו'\" (חולין ס\"ז ע\"ב), היימן, שגורס: \"א\"ל רב משרשיא בר בריה דרב אחא\", עקר מהש\"ס את האמורא רב משרשיא בריה דרב אחא, והפכו לרב משרשיא בר בריה דרב אחא, שהיה מרבנן סבוראי.","cat": "sage"},{"i": 2865,"n": "רב משרשיא בריה דרב אידי","l": "מ","b": "אמורא בבלי. מובא בבבלי (גיטין ל' ע\"ב). ונראה שחי בזמנו של אביי או לאחריו.","cat": "sage"},{"i": 2866,"n": "רב משרשיא בריה דרב אמי","l": "מ","b": "אמורא ארץ ישראלי בדור השני - השלישי. חלק עם רבי יוחנן ועם רב אדא בר אהבה (ב\"ב פ\"ה ע\"ב; גיטין ע\"ח ע\"א - ושם הגיר': רב משרשיא בר רב דימי). אמר לר' אסי: \"אסברא לך\" (קידושין ס' ע\"א).","cat": "sage"},{"i": 2867,"n": "רב משרשיא בריה דרב חייא","l": "מ","b": "אמורא בבלי. נראה שחי בזמנו של רב אשי בן הדור הששי (ב\"ב פ\"ב ע\"א).","cat": "sage"},{"i": 2868,"n": "רב משרשיא בריה דרב נתן","l": "מ","b": "אמורא בבלי בדור החמישי - הששי. נראה, שאולי היה גדול מרבינא כמובא: \"אמר רבינא: אמר לי רב משרשיא בריה דרב נתן וכו'\" (פסחים קט\"ו ע\"א).","cat": "sage"},{"i": 2869,"n": "רב משרשיא מתוסנייא","l": "מ","b": "אמורא בבלי בדור החמישי - הששי. מובא בבבלי, ששלח לרב פפי: \"ילמדנו רבינו\" (יבמות כ\"א ע\"ב).","cat": "sage"},{"i": 2870,"n": "רבי מתון","l": "מ","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ב\"ק צ\"ו ע\"א). שאל מרבי יוחנן (ירו', מו\"ק פ\"ג ה\"ז).","cat": "sage"},{"i": 2871,"n": "רב מתיא בן חרש","l": "מ","b": "תנא בדור השלישי - הרביעי. הלך לרומי ויסד שם ישיבה גדולה (סנהדרין ל\"ב ע\"ב): \"אחר רבי מתיא לרומי\". וכשהיה רבי שמעון בן יוחאי ברומי, ביקר אצלו בישיבה (מעילה י\"ז ע\"א). נראה, שלמד מרבי אליעזר בן הורקנוס (יומא נ\"ג ע\"ב). היה חברם של רבי יהודה בן בתירא (השני), חנינא בן אחי רבי יהושע ורבי יונתן, ומצינו שהלכו יחד מארץ ישראל לחוץ לארץ וחזרו למקומם (ספרי ראה - נ\"ג). היה בקי ברפואות (יומא פ\"ד). מעולם לא הסתכל באשה. זיו פניו דמה לחמה, וקלסתר פניו למלאכי השרת (\"ילקוט\" פ' ויחי בשם מד' אבכיר).","cat": "sage"},{"i": 2872,"n": "מתיא מן דבתרה","l": "מ","b": "אמורא ארץ ישראלי. מובא בירושלמי (ערלה פ\"א ה\"א). אם נלמד פשט שענה על דברי רבי יוסי א\"כ יתכן שאפשר להוכיח, שחי בדור הששי לאמוראי א\"י.","cat": "sage"},{"i": 2873,"n": "ר' מתנה (2)","l": "מ","b": "בהגהות ר\"ש שלום ב\"יוחסין\" כתב, שראה ב\"מגילת סתרים\" לרב נסים גאון, שר' מתנה היה בנו של רבי יוחנן, והלך לבבל ללמוד לפני שמואל, ור' מתנה זה נשאר מעשרת בניו של ר' יוחנן שכן לר' יוחנן היו עשרה בנים וכולם מתו על פניו (ברכות ה' ע\"ב).","cat": "sage"},{"i": 2874,"n": "ר' מתנה א'","l": "מ","b": "אמורא בבלי בדור השני. תלמידו המובהק של שמואל (עירובין ו' ע\"ב). תלמידו של רב (שבת כ\"א ע\"א). חברו של רב יהודה (קידושין ע' ע\"ב). רבי אבא שאל ממנו (ברכות י\"א ע\"ב). רבי זירא היה מתלמידיו (שבת ק\"ח ע\"ב). מושבו היה בפופוניא ושם דרש בדיני פסח (פסחים מ\"ב ע\"א).","cat": "sage"},{"i": 2875,"n": "רב מתנה ב'","l": "מ","b": "אמורא בבלי בדור החמישי. מרבותיו של רב אשי (זבחים כ\"ט ע\"א). נשא - ונתן עם אביי (כתובות ל\"ה ע\"ב).","cat": "sage"},{"i": 2876,"n": "רבי מתניא","l": "מ","b": "אמורא ארץ ישראלי בדור החמישי - הששי. בנו של רבי יודן, נראה, שהיה גדול מאביו, שכן את אביו מיחסים אליו, כמובא בירושלמי: \"א\"ר יודן אבוי דרבי מתניא\" (דמאי פ\"ז ה\"ד). הורה יחד עם רבי אליעזר (כנראה רבי אליעזר ברבי יוסי האמורא הארץ ישראלי בדור החמישי - הששי) ועם רבי אבא מרי (ירו', ביצה פ\"א ה\"ט). מסופר כיצד השיא את בתו (ירו', כתובות פ\"א ה\"א).","cat": "sage"},{"i": 2877,"n": "מתתיה בן יהודה","l": "מ","b": "מובא פעמיים בבבלי: \"תני מתתיהו בן יהודה\" (חולין ס\"ז ע\"א; מנחות ע\"ט ע\"ב). \"יוחסין\" ו\"סה\"ד\" כתבו שהיה תלמידו של שמואל. (ואני לא ידעתי את המקור לזה, ואולי גיר' אחרת נזדמנה להם: א\"כ, לפי דעתם היה אמורא בבלי בדור השני).","cat": "sage"},{"i": 2878,"n": "נאנאי בריה דרב יוסף בריה דרבא","l": "נ","b": "אמורא בבלי בדור הששי. בן בנו של האמורא הידוע רבא. מובא בבבלי (יבמות ס\"ו ע\"ב): \"א\"ל נאנאי בריה דרב יוסף בריה דרבא, לרב כהנא: והאמר רבא וכו'\".","cat": "sage"},{"i": 2879,"n": "נבו","l": "נ","b": "חי בתקופת התנאים בדור השלישי - הרביעי. מובא בתוספתא (פסחים ספ\"ג). ואולי הוא בן בוהיין.","cat": "sage"},{"i": 2880,"n": "נגדא","l": "נ","b": "שם חכם. מובא בויק\"ר (פכ\"ה - ו'): \"א\"ר תנחומא מסתברא דנגדא וכו'\".","cat": "sage"},{"i": 2881,"n": "רבי נהוראי (2)","l": "נ","b": "תנא בדור הרביעי. מובא בבבלי (קידושין פ\"ב ע\"א). חלק על רבי מאיר (רבי מאיר עצמו גם כן נקרא \"רבי נהוראי\" [עירובין י\"ג ע\"ב], וכן נקרא רבי אלעזר בן ערך \"ר' נהוראי\" [שבת קמ\"ז ע\"ב]). מסר משם רבי יהושע (נזיר ה' ע\"א). אליהו הנביא שאל ממנו, וכשהשיב לו אמר לו אליהו הנביא \"בני חייך כן הוא\" (ירו', ברכות פ\"ט ה\"ב), ואין להכריע אם הכוונה אליו או לר' נהוראי האמורא.","cat": "sage"},{"i": 2882,"n": "ר' נהוראי","l": "נ","b": "הוא רבי מאיר (עירובין י\"ג ע\"ב).","cat": "sage"},{"i": 2883,"n": "נהוראי בן שונייא","l": "נ","b": "תנא בדור החמישי. מסר משום רבי שמעון בן יוחאי (תוספתא ריש מעשרות).","cat": "sage"},{"i": 2884,"n": "נהוראי בר שיניא","l": "נ","b": "מובא בירושלמי (מעשרות פ\"א ה\"ג), והוא נהוראי בן שונייא.","cat": "sage"},{"i": 2885,"n": "רבי נהוראי סבא","l": "נ","b": "חי בזמן התנאים. האניה שבה הפליג טבעה והוא ניצל בנס (\"זוהר\" ויקרא ו'). מובא עם רבי שמעון בן יוחאי (שם, ספ' תצוה).","cat": "sage"},{"i": 2886,"n": "ר' נהילאי בר אידי","l": "נ","b": "אמורא בבלי בדור השני. תלמידו של שמואל (תענית ו' ע\"א).","cat": "sage"},{"i": 2887,"n": "נהרבלאי","l": "נ","b": "מובא בבבלי (סנהדרין י\"ז ע\"ב). ב\"נהרבלאי\" הכוונה לרמי בר ברבי ורש\"י גרס: \"רמי בר ברוכי\" (ביצה ח' ע\"ב). בהקדמת הרמב\"ם לזרעים בהגהה, ובספר הכריתות לשון לימודים (שער ג' פ\"ו), כתבו, שמה שאמרו בסנהדרין \"נהרבלאי\" הוא רב ביבי בר ביזנא.","cat": "sage"},{"i": 2888,"n": "נהרדעי","l": "נ","b": "מובא בבבלי (ב\"ב ז' ע\"ב); ופירשו התוספות: \"רב חמא נהרדעא הוא וכו' ושמואל נמי נהרדעי הוא\". ע\"ע אמוראי דנהרדעא.","cat": "sage"},{"i": 2889,"n": "נוולא","l": "נ","b": "\"סה\"ד\" תמה על ה\"יוחסין\" מדוע הביאו בין שמות החכמים, וזה לשון \"סה\"ד\": \"לא ידעתי מי הגיד לו [ל\"יוחסין\"] שהוא חכם וכו' יהיה איך שיהיה הוא שם אשה\", עכ\"ל. ורש\"י באמת מפרש כך וזה לשונו: \"ואני אומר שזה שמה\" (ב\"מ ס\"ז ע\"א); א\"כ, בוודאי אינו שם חכם. רש\"י מביא תשובת הגאונים ש\"נוולא\" זה לשון ארמי כשרוצה לומר אתה והוא או אתה והיא (שם).","cat": "sage"},{"i": 2890,"n": "רבי נזירא","l": "נ","b": "אמורא ארץ ישראלי בדור השני - השלישי. רבי לוי מסר משמו (ב\"ר פי\"ב - ו'). וכן מובא בירושלמי (ברכות פ\"ח ה\"ח).","cat": "sage"},{"i": 2891,"n": "נחום","l": "נ","b": "אמורא ארץ ישראלי בדור הראשון - השני. מסר בשם רב (ירו', שבת פ\"י ה\"ו). ומצינו: ר' נחום בבבלי (ברכות נ\"ה ע\"ב; חולין צ\"ח ע\"א).","cat": "sage"},{"i": 2892,"n": "רבי נחום","l": "נ","b": "מובא בבבלי (שבת פ\"ח ע\"ב). אותו ענין מובא במקום אחר (סוכה ה' ע\"א) ושם \"רבי תנחום\".","cat": "sage"},{"i": 2893,"n": "ר' נחום אחוה דר' אילא","l": "נ","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ירו', ביצה פ\"ה ה\"ב).","cat": "sage"},{"i": 2894,"n": "נחום איש גליה","l": "נ","b": "תנא דברייתא. וא\"ר יוסף הלכה כמותו (כתובות ס' ע\"א).","cat": "sage"},{"i": 2895,"n": "נחום איש גם זו","l": "נ","b": "תנא בדור השלישי. רבו המובהק של רבי עקיבא. רבי עקיבא שימשו עשרים ושתיים שנה (חגיגה י\"ב ע\"א). היה דורש כל אתין שבתורה (שם). היה צדיק וחסיד גדול ומלומד בנסים, ועל כל דבר ודבר שקרה לו נהג לומר: \"גם זו לטובה\" (תענית כ\"א ע\"א). פעם אחת ביקש ממנו עני מזון לאכול, ושהה לרגע והעני מת מרעב, וקילל עצמו שיהא סומא בעיניו ויקטעו ידיו ורגליו וכל גופו יהיה מצורע, כעונש על שלא נתן מייד מזון לעני, וכך היה - שכב במטה בבית רעוע, ורגלי מטתו מונחות בספלים של מים, שלא יעלו עליו נמלים.","cat": "sage"},{"i": 2896,"n": "רבי נחום בר סימאי","l": "נ","b": "מובא בירושלמי (ע\"ז רפ\"ג), והוא רבי מנחם בר סימאי.","cat": "sage"},{"i": 2897,"n": "רבי נחום בר פפא","l": "נ","b": "מובא בבבלי, שאמר משום רבי אלעזר הקפר (יומא ס\"ז ע\"א). גיר' \"יוחסין\": ר' נחמן בר פפא; גיר' \"דק\"ס\": ר' נחום בר פרנק.","cat": "sage"},{"i": 2898,"n": "נחום בר שימלאי","l": "נ","b": "מובא ב\"זוהר חדש\" (רות פ\"א).","cat": "sage"},{"i": 2899,"n": "נחום הזקן","l": "נ","b": "תנא. מובא בבבלי (ברכות מ\"ח ע\"ב). \"סה\"ד\" תמה על \"יוחסין\" המפקפק אם הוא נחום הלבלר או נחום המדי, ולדעתו ברור שהיה בזמן רבי (ואינו מבין פליאת \"סה\"ד\", שכן יתכן שמסדר הש\"ס שיבצם יחד ואין ראיה שהיה בזמן רבי).","cat": "sage"},{"i": 2900,"n": "נחום הלבלר","l": "נ","b": "מחכמי ישראל בסוף תקופת ה\"זוגות\" ותחילת תקופת התנאים. ישב בלשכת הגזית. רבן גמליאל שאל ממנו (משנה פאה פ\"ב מ\"ו).","cat": "sage"},{"i": 2901,"n": "נחום המדי","l": "נ","b": "תנא קדמון בדור הראשון לתנאים. יליד ארץ מדי, שעלה לירושלים (ע\"ז ז' ע\"ב) ונתמנה בה לדיין. היה מ\"גוזרי גזירות שבירושלים\" (כתובות ק\"ה ע\"א). בימיו נחרב הבית (נזיר ל\"ב ע\"ב). לדעת חכמים טעה בהוראה (שם). ה\"יוחסין\" כתב: \"סתם נחום הוא נחום המדי\".","cat": "sage"},{"i": 2902,"n": "נחום הפיקולי","l": "נ","b": "מובא ב\"זוהר חדש\" (רות פ\"ב).","cat": "sage"},{"i": 2903,"n": "ר' נחום שמעיה דר' אבהו","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. שמשו ותלמידו של רבי אבהו: \"מסתמיך ואזיל רבי אבהו, אכתפיה דר' נחום שמעיה\" (יבמות מ\"ב ע\"ב).","cat": "sage"},{"i": 2904,"n": "רב נחומאי","l": "נ","b": "ע\"ע רב נחומי.","cat": "sage"},{"i": 2905,"n": "נחומאי בן אפקשיון","l": "נ","b": "תנא בדור השלישי - הרביעי. מובא בברייתא, נזכר אחר רבי ישמעאל ורבי עקיבא וחלק עליהם (יומא כ\"ח ע\"ב).","cat": "sage"},{"i": 2906,"n": "רב נחומי","l": "נ","b": "אמורא בבלי בדור הרביעי. הקשה לאביי: \"אמר ליה רב נחומאי, ואית דאמר רב חנניה בר מניומי, לאביי\" (ב\"ב קל\"א ע\"א), אבל אין ראיה שהיה תלמידו. מצינו: \"אמר רבי נחוניא שאילתינהו לכולהו טרופאי\" [מורי הוראות של טריפות] (חולין נ\"ה ע\"ב). \"דק\"ס\" כתב: ובכל כתבי היד רבי נחומי\". וכן מצינו: \"פליגי בה ר' נחומי ורבה\" (עירובין ע\"א ע\"ב), ושם גרס הרא\"ש: רחומי ולא נחומי.","cat": "sage"},{"i": 2907,"n": "רב נחומי בר אדא","l": "נ","b": "מובא בבבלי (ביצה ל\"א ע\"ב), וגיר' \"סה\"ד\": רב נחמן בר אדא (כמו הגיר' עירובין ל\"ד ע\"ב).","cat": "sage"},{"i": 2908,"n": "רב נחומי בר זכריה","l": "נ","b": "אמורא בבלי בדור החמישי. תלמידו של אביי (ב\"ק כ\"ה ע\"ב). חברו של מר בריה דרבינא (שבת קל\"ו ע\"א). (בב\"ק כ\"ה ע\"ב. הגירסא נחמן וכתב \"סה\"ד\" נ\"ל שצ\"ל נחומי).","cat": "sage"},{"i": 2909,"n": "ר' נחומי בריה דר' חייא בר אבא","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. בנו ותלמידו של ר' חייא בר אבא (ירו', דמאי פ\"א ה\"ב), ויש שהגיהו: ר' נחמיה בריה דר' חייא בר אבא (ירו', ברכות פ\"ג ה\"א).","cat": "sage"},{"i": 2910,"n": "ר' נחוניא","l": "נ","b": "מובא בבבלי: \"ר' נחוניא אמר מהכא\" (ב\"ק נ' ע\"א). ובאותו ענין מובא: \"ר' חנינא אמר מהכא\" (יבמות קכ\"א ע\"ב). ע\"ע רב נחומי.","cat": "sage"},{"i": 2911,"n": "ר' נחוניא איש בקעת בית חורתן","l": "נ","b": "מובא בבבלי, שר' יוחנן אמר משמו (מו\"ק ג' ע\"ב), והוא רבי חוניא דברת חוורין (ירו', שביעית פ\"ו ה\"א). שמו שובש בכמה פנים, ו\"סה\"ד\" מביא ערך נפרד לר' נחוניא איש בקעת בית חורתן, בנוסף לערך רבי חוניא דמן חוורן. ה\"יוחסין\" מביא ערך נוסף: נחמיה איש בקעת בית חורתן: \"א\"ר יוחנן משום חוניא איש בקעת בית חורתן\" (סוכה מ\"ד ע\"א). לענ\"ד כולם אחד.","cat": "sage"},{"i": 2912,"n": "רבי נחוניא בן אלינתן איש כפר הבבלי","l": "נ","b": "תנא בדור השני. העיד יחד עם רבי יהושע על אבר מן המת שהוא טמא, בניגוד לדעתו של רבי אליעזר (עדיות פ\"ו מ\"ב). ושנה במשנה (מ\"ב): \"רבי יהושע ורבי נחוניא מטהרים ורבי אליעזר מטמא\". וכן שם בענין אחר: \"רבי נחוניא מטמא ורבי אלעזר ורבי יהושע מטהרין\". נראה שצ\"ל: רבי נחוניא בן אלינתן.","cat": "sage"},{"i": 2913,"n": "רבי נחוניא בן גודגדתא","l": "נ","b": "מובא במשנה (עדיות פ\"ז מ\"ט), ו\"סה\"ד\" כתב: \"עיין ר' יוחנן בן גודגדא\". נראה, ששני השמות הם של תנא אחד.","cat": "sage"},{"i": 2914,"n": "רבי נחוניא בן הקנה","l": "נ","b": "תנא בדור השני. נראה, שהיה מתלמידיו של רבן יוחנן בן זכאי: ששאל רבן יוחנן בן זכאי לתלמידיו: מהו וכו', נענה רבי אליעזר וכו', נענה רבי יהושע וכו', נענה רבן גמליאל וכו', א\"ל רבן יוחנן בן זכאי לתלמידיו: \"נראין דברי נחוניא בן הקנה [כן גיר' \"דק\"ס\", ולפנינו: רבי נחוניא בן הקנא] מדברי ומדבריכם\" (ב\"ב י' ע\"ב). היה רבו המובהק של רבי ישמעאל (שבועות כ\"ו ע\"א). היה דורש את כל התורה כולה בכלל ופרט. (שם) זכה לאריכות ימים, ותלמידיו שאלוהו במה זכה, וענה להם: \"מימי לא נתכבדתי בקלון חברי, ולא עלתה על מטתי קללת חברי, וותרן בממוני הייתי\". \"יוחסין\" כתב שהוא כתב את \"ספר הבהיר\" על סודות הקבלה.","cat": "sage"},{"i": 2915,"n": "רבי נחוניא הגדול","l": "נ","b": "תנא בדור השני. ומסופר שרבי עקיבא שאלו \"במה הארכת ימים?\" (מגילה כ\"ח ע\"א), שם מוכח לכאורה, שאין זה רבי נחוניא בן הקנה המובא באותו עמוד, ו\"סה\"ד\" חיברם לאחד.","cat": "sage"},{"i": 2916,"n": "נחוניא חופר שיחין","l": "נ","b": "חסיד שהיה אחד מט\"ו הממונים במקדש, והיה ממונה לראות שיהיו מים מצויים לעולי רגל, והיה חופר שיחין ומערות (ירו', שקלים רפ\"ה). ופעם נפלה בתו לבור גדול, באו והודיעו לרבי חנינא בן דוסא, והוא אמר להם שתינצל (ב\"ק נ' ע\"א). בנו מת מצמא (שם), ש\"הקב\"ה מדקדק עם סביביו אפילו כחוט השערה\".","cat": "sage"},{"i": 2917,"n": "נחונייה בן יוסי בן פכסס","l": "נ","b": "מובא בירושלמי (נזיר רפ\"ז), ואין להכריע אם היה מן החכמים. \"סה\"ד\" מביאו בין החכמים.","cat": "sage"},{"i": 2918,"n": "רבי נחמיה","l": "נ","b": "תנא בדור הרביעי. אחד משבעת תלמידיו הגדולים של רבי עקיבא, כמו שכתבו התוספות (יומא מ' ע\"ב ד\"ה: כיון) \"דר' יהודה ור' נחמיה נמי תלמידיו [של ר\"ע] כדאיתא בפ' הבא על יבמתו (יבמות ס\"ב ע\"ב)\", ולפנינו שם ליתא ר' נחמיה, אך כך היתה גיר' התוס'. וכן מצינו (ב\"ר פס\"א - ג') שמחשיב את ר' נחמיה בן ז' תלמידיו של רבי עקיבא. ולפי דעתו של ר' אויא נסמך ר' נחמיה יחד עם תלמידיו של ר\"ע ע\"י ר' יהודה בן בבא (סנהדרין י\"ד ע\"א). וכן מצינו אותו בין תלמידיו של ר\"ע: \"ת\"ר, כשנכנסו רבותינו לכרם ביבנה, היה שם רבי יהודה ורבי יוסי ורבי נחמיה וכו'\" (ברכות ס\"ג ע\"ב). וכן מצינו: \"סתם מתניתין רבי מאיר, סתם תוספתא רבי נחמיה\" (סנהדרין פ\"ו ע\"א). שם אביו לא מוזכר בשום מקום, אך נראה שהיה חכם, שמצינו: \"רבי נחמיה אומר משום אביו\" (פסחים נ\"ד ע\"א).","cat": "sage"},{"i": 2919,"n": "ר' נחמיה","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. היה מחכמי האגדה. מסר משום רבי אבהו (ב\"ר פמ\"ג). כן מסר בשם רבי שמואל בר יצחק (מ\"ר פ\"ג - ב'). היה חברם של ר' ברכיה, ר' עזריה ור' פנחס (שו\"ט כ\"ד - ה').","cat": "sage"},{"i": 2920,"n": "נחמיה איש בית דלי","l": "נ","b": "תנא בדור השני שירד לבבל. מובא בבבלי: \"אמר רבי עקיבא: כשירדתי לנהרדעא לעבר שנה, מצאתי נחמיה איש בית דלי ואמר לי וכו'\" (יבמות קכ\"א ע\"א). וכן: \"העיד רבי עקיבא משמו שמשיאין האשה וכו'\" (עדיות פ\"ח מ\"ה).","cat": "sage"},{"i": 2921,"n": "ר' נחמיה איש בקעת חורתן","l": "נ","b": "ע\"ע רבי חוניה דברת חוורין.","cat": "sage"},{"i": 2922,"n": "ר' נחמיה איש כפר סיחון","l": "נ","b": "אמורא ארץ ישראלי בדור החמישי. מחכמי האגדה. חברו של ר' עזריה וחלק עמו (ב\"ר פי\"ב - ה').","cat": "sage"},{"i": 2923,"n": "נחמיה איש שיחין","l": "נ","b": "תנא בדור השלישי - הרביעי. מובא בירושלמי: אמר רבי יהודה: \"העיד נחמיה איש שיחון משום רבי עקיבא\" (סוטה פ\"ב ה\"ה). ובמקום אחר שובשה הגירסא ל\"נחמיה חופר שיחין\" (סוטה י\"ח ע\"ב). מסופר עליו, שעני אחד ביקשו ליתן לו תרנגולת, ונתן לו מעות שיקנה בשר ואכל ומת, ואמר: \"ספדי להרוגי נחמיה\" (ירו', סוף פאה).","cat": "sage"},{"i": 2924,"n": "ר' נחמיה בן אלעזר","l": "נ","b": "מובא באיכ\"ר (פ\"ב - ג'): \"ר' ברכיה ואמרי לה ר' נחמיה בן אלעזר\".","cat": "sage"},{"i": 2925,"n": "נחמיה בר ברוך","l": "נ","b": "מובא בבבלי (מו\"ק ט\"ז ע\"א), ואולי הוא ר' נחמן בר ברוך.","cat": "sage"},{"i": 2926,"n": "ר' נחמיה בר חנינא","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. חברו של ר' יצחק בר חייא (מד' תהלים הישן פע\"ה).","cat": "sage"},{"i": 2927,"n": "ר' נחמיה בר מר עוקבן בריה דר' יוסי","l": "נ","b": "אמורא ארץ ישראלי. מובא בירושלמי (יבמות י\"ד ע\"א).","cat": "sage"},{"i": 2928,"n": "ר' נחמיה בר עוקבן","l": "נ","b": "אמורא ארץ ישראלי. מובא בירושלמי (פאה פ\"א ה\"ה).","cat": "sage"},{"i": 2929,"n": "רב נחמיה בריה דרב הונא בר חנילאי","l": "נ","b": "כן גיר' הרי\"ף והרא\"ש, אך לפנינו: ר' נחמיה בריה דר' חנילאי (עירובין י\"ג ע\"ב).","cat": "sage"},{"i": 2930,"n": "רב נחמיה בריה דרב חנילאי","l": "נ","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב נחמן: \"א\"ל רב חסדא לרב נחמן: 'נחמיה תלמידך שרוי בצער'\" (עירובין מ\"ג ע\"ב).","cat": "sage"},{"i": 2931,"n": "רב נחמיה בריה דרב יוסף","l": "נ","b": "אמורא בבלי בדור החמישי. תלמידו המובהק של רבא: \"אמר הוה קאימנא קמיה דרבא וכו'\" (ביצה כ\"ח ע\"א), לפי גירסת \"סה\"ד\" ו\"דק\"ס\" היה חברם של רב פפא ור' פפי (מו\"ק י\"ט ע\"ב) שאמר: \"אשכחתינהו דיתבי וקא אמרי\". היה הריש בעירו (כתובות ס\"ה ע\"א).","cat": "sage"},{"i": 2932,"n": "ר' נחמיה בריה דר' חייא בר אבא (2)","l": "נ","b": "מובא בירושלמי (ברכות פ\"ג ה\"א), ונראה שהוא ר' נחומי בריה דר' חייא בר אבא.","cat": "sage"},{"i": 2933,"n": "רב נחמיה בריה דר' יהושע","l": "נ","b": "אמורא בבלי בדור החמישי. מובא בבבלי, שאמר: \"אשכחתינהו לרב פפי ולרב פפא דיתבי וקאמרי וכו'\" (מו\"ק י\"ט ע\"ב), אבל גיר' \"דק\"ס\": רב נחמיה בריה דרב יוסף, וכן גרס \"סה\"ד\".","cat": "sage"},{"i": 2934,"n": "ר' נחמיה דיפו","l": "נ","b": "אמורא ארץ ישראלי. מובא (פדר\"כ קע\"ג). יתכן שהוא ר' נחמן דיפו.","cat": "sage"},{"i": 2935,"n": "נחמיה חתניה דבי נשיאה","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידם של ר' אמי ור' אסי כמובא בבבלי, שאמר \"אנא חזיתיה לר' אמי ור' אסי דמטי וכו'\" (יומא ע\"ח ע\"א).","cat": "sage"},{"i": 2936,"n": "רב נחמן","l": "נ","b": "אמורא בבלי בדור השני - השלישי, והוא רב נחמן בר יעקב סתם בש\"ס (ב\"ב מ\"ו ע\"ב תד\"ה: שלח). אביו רבי יעקב היה מסופרי הדיינים בבית דינו של שמואל בנהרדעא (ב\"מ ט\"ז ע\"ב) רב נחמן מסר בשם אביו (ביצה כ\"ו ע\"ב), רבו המובהק היה רבה בר אבהו: \"והאמר רב נחמן: 'כי הוינן בי רבה בר אבהו'\" (ברכות כ\"א ע\"א), וכן: \"אף לדידי קשיא לי, ושאלתיה לרבה בר אבהו\" (ע\"ז נ\"א ע\"א). נראה, שרב נחמן היה לחתנו של רבה בר אבהו (יבמות פ' ע\"ב), קיבל תורה גם משמואל (ברכות כ\"ז ע\"ב), ואף מצינו: \"דרש רב נחמן משום רבינו שמואל\" (עירובין ט\"ז ע\"ב). היה גם תלמידו של רב, כמו שרש\"י כתב במפורש (ביצה כ\"ה ע\"א ד\"ה: מדברי). שלח לשאול מחכמי ארץ ישראל (ביצה כ\"ה ע\"ב). רב יהודה היה גדול ממנו (קידושין ע' ע\"א רש\"י ד\"ה: לא מיבעי). בין תלמידיו הרבים היו רבה (יבמות ס\"ו ע\"ב), רב יוסף (ב\"ק קט\"ז ע\"ב) ורבי אבא (עירובין ע\"ו ע\"ב). רב נחמן היה הראש בנהרדעא (קידושין שם). היה מומחה גדול לדיני ממונות, ואמר לרב ששת: \"אנא דיינא, ומר לאו דיינא\" (כתובות צ\"ד ע\"ב). רב נחמן אמר: ד\"כולי עלמא לגבי דידי בדינא דרדקי [תינוקות] נינהו\" (ב\"מ ס\"ו ע\"א), ואכן נקבע הכלל: \"דקיימא לן הלכתא כרב נחמן בדיני\" (כתובות י\"ג ע\"א) שם אשתו היה ילתא (ברכות נ\"א ע\"ב) היו לו כמה בנים חכמים, הון (יבמות ל\"ד ע\"ב), הונא (הוריות, י\"ב ע\"ב), מר זוטרא (ב\"ב קנ\"א ע\"ב), רב פפא (ב\"מ קי\"ג ע\"א) ורבה (חולין קי\"א ע\"א). היתה לו בת ושמה דונג (קידושין ע' ע\"א). שתי בנותיו נשבו (גיטין מ\"ה ע\"א). על פטירתו מובא שרבא היה לידו בזמן שנפטר (מו\"ק כ\"ח ע\"א).","cat": "sage"},{"i": 2937,"n": "רבי נחמן","l": "נ","b": "אמורא ארץ ישראלי בדור הששי. מסר משמו של רבי מנא (ירו', ברכות פ\"א ה\"א). מסר גם בשם רבי אחא (איכ\"ר פתיחתא ה').","cat": "sage"},{"i": 2938,"n": "ר' נחמן","l": "נ","b": "פעמים, הכונה לר' נחמני.","cat": "sage"},{"i": 2939,"n": "רב נחמן בר אבא","l": "נ","b": "מובא בבבלי (ע\"ז ל\"ט ע\"א), אבל גירסת הר\"י, והרא\"ש: רב נחמן בר רבא.","cat": "sage"},{"i": 2940,"n": "רב נחמן בר אדא","l": "נ","b": "אמורא בבלי בדור השני. תלמידו של שמואל (עירובין ל\"ד ע\"ב). והגירסא במקום אחר: רב נחומי בר אדא (ביצה ל\"א ע\"ב), אך \"סה\"ד\" גורס בשניהם: רב נחמן בר אדא, וכולם אחד.","cat": "sage"},{"i": 2941,"n": "רב נחמן בר אושעיא","l": "נ","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"רב נחמן בר אושעיא אמר רבי יוחנן\" (שבת ס\"ה ע\"א), וגירסת הרי\"ף: ר' נתן בר אושעיא. כן כתב \"סה\"ד\", שרב נחמן בר אושעיא ט\"ס היא, וצ\"ל: ר' נתן בר אושעיא.","cat": "sage"},{"i": 2942,"n": "רב נחמן בר אושפזתי","l": "נ","b": "אמורא בבלי בדור החמישי. מסופר, שרב פפא גזר תעניתא, חלש ליביה וטעם מידי, בעא רחמי ולא בא גשם: \"א\"ל רב נחמן בר אושפזתי וכו'\" (תענית כ\"ד ע\"ב), וה\"ערוך\" גרס: \"א\"ל רב נחמן בר אושפרתי וכו'\", כלומר, רב נחמן אמר לרב פפא: \"בר אושפרתי\" (בנו של אושפרתי; וסובר הערוך ששם אמו של רב פפא היה אושפרתי); א\"כ, לפי גירסת ה\"ערוך\" לא היה כלל חכם ושמו רב נחמן בר אושפזתי.","cat": "sage"},{"i": 2943,"n": "רב נחמן בר אמי","l": "נ","b": "לפי גירסת ה\"ערוך\" (במו\"ק כ\"ב ע\"ב, ערך אסיתא) היה אמורא בבלי בדור השני - השלישי. ה\"ערוך\" גרס: א\"ל רב חסדא לרב נחמן בר אמי. ועוד מצינו: \"אמר רב נחמן בר אמי משמיה דאולפנא\" (עירובין ס\"ז ע\"א) ופרש\"י: ששמע מרבו ורבו מרבו.","cat": "sage"},{"i": 2944,"n": "רב נחמן בר ברוך","l": "נ","b": "אמורא שאין לנו פרטים עליו. מובא בבבלי: \"אמר אדא מרי, אר\"נ בר ברוך\" (שבת ס\"ו ע\"ב), ואולי הוא נחמיה בר ברוך.","cat": "sage"},{"i": 2945,"n": "רב נחמן בר זכריה","l": "נ","b": "מובא בבבלי (ב\"ק כ\"ה ע\"ב). לפי \"סה\"ד\" צריך לגרוס: רב נחומי בר זכריה.","cat": "sage"},{"i": 2946,"n": "רב נחמן בר חנין","l": "נ","b": "מובא בב\"ר (פמ\"א - ז').","cat": "sage"},{"i": 2947,"n": "רב נחמן בר יהודה","l": "נ","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי: \"ר' יעקב בר אחא ור\"ז וכו' חד אמר בשם מר עוקבן וחד בשם ר\"נ בר יהודה\" (עירובין פ\"ו ה\"ח).","cat": "sage"},{"i": 2948,"n": "רב נחמן בר יעקב","l": "נ","b": "ע\"ע רב נחמן.","cat": "sage"},{"i": 2949,"n": "רב נחמן בר יצחק","l": "נ","b": "אמורא בבלי בדור הרביעי - החמישי. מלך בפומבדיתא אחר פטירתו של רבא בשנים ד' קי\"א - קט\"ו (153 - 653) (\"אגרת רב שרירא גאון\"). היה מתלמידי רב חסדא (ע\"ז ס\"ג ע\"א). ישב מאחורי רבא לפני רב נחמן, וכשלא הבין את אשר רמז רב נחמן, שאל לרבא (ב\"ב קנ\"ב ע\"א). לפי פירוש התוספות היה תלמידו של רבא (שם מ\"ו ע\"ב תד\"ה: שלח). היה ריש כלה (שם כ\"ז ע\"א). בין תלמידיו היו רב הונא בריה דרב נחמן (פסחים מ\"ו ע\"ב), וכן רב אשי לפי גירסת התוספות (ב\"ב מ\"ו ע\"ב ד\"ה: שלח). לפי פירושו של רש\"י (תענית כ\"א ע\"ב ד\"ה: פרס), אביו של רב נחמן בר יצחק לא נסמך. חוזי הכוכבים ניבאו לאמו, שרב נחמן בר יצחק יהיה גנב, לכן הקפידה אמו לחנכו ליראת שמים והיתה אומרת לו תדיר שיכסה ראשו ויבקש רחמים. יום אחד ישב תחת צל אילן, ונפל כיסוי ראשו מעליו, ויצרו גבר עליו וחתך בשיניו אשכול תמרים מהאילן, שלא היה שייך לו (שבת קנ\"ו ע\"ב). היה ירא שמים גדול, עד שאמר אביי לרב יוסף: \"הא רב נחמן בר יצחק מרי דעובדא\" (שבת ל\"ז ע\"ב), ופירש\"י: \"מדקדק במעשיו\". נמנה עם חסידי בבל (מגילה כ\"ח ע\"ב רש\"י).","cat": "sage"},{"i": 2950,"n": "רב נחמן בר כהן","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי: \"כי אתא רב דימי אמר: דרש רב נחמן בר כהן מאי דכתיב וכו'\" (סנהדרין ז' ע\"ב).","cat": "sage"},{"i": 2951,"n": "רב נחמן בר נתן","l": "נ","b": "מובא בבבלי (ב\"ב ח' ע\"ב) לפי גירסת הרא\"ש. ולפנינו: רב נחמן סתם.","cat": "sage"},{"i": 2952,"n": "רב נחמן בר פפא","l": "נ","b": "אמורא בבלי בדור הרביעי. מצינו אותו מתיב על דברי רפרם בר פפא, שהיה תלמידו של רב חסדא (ב\"מ פ' ע\"ב). היה חסיד גדול, וכשביקש גשם נענה משמים וירד גשם לגינתו (חולין ס' ע\"ב).","cat": "sage"},{"i": 2953,"n": "ר' נחמן בר פרנק","l": "נ","b": "ע\"ע רבי נחום בר פפא.","cat": "sage"},{"i": 2954,"n": "רב נחמן בר רב הונא","l": "נ","b": "אמורא בבלי בדור השביעי. עמד בראש ישיבת סורא אחרי רב אידי בר אבין במשך שלוש שנים, משנת דרי\"א עד דרי\"ד (154 - 454) ואז נפל שמדא, שגזר יזדגרד מלך פרס לחלל שבת\" (\"אגרת רב שרירא גאון\"). אחריו מלך מר בר רב אשי.","cat": "sage"},{"i": 2955,"n": "רב נחמן בר רב זבדא","l": "נ","b": "מובא בבבלי: \"דאמר רב נחמן בר רב זבדא ואמרי לה אמר רב נחמן בר רבא אמר רב\" (שבת כ\"ה ע\"ב).","cat": "sage"},{"i": 2956,"n": "רב נחמן בר רב חסדא","l": "נ","b": "אמורא בבלי בדור הרביעי. בנו ותלמידו של האמורא המפורסם רב חסדא (שבת קמ\"ז ע\"א). ואף ששלח לרב נחמן: \"ילמדנו רבנו\" (ב\"ב מ\"ו ע\"ב), לא מצינו שרב נחמן בר רב חסדא למד לפני רב נחמן. כן שלח לרבה: \"ילמדנו רבנו\" (גיטין פ' ע\"ב), ולא מצינו שהיה תלמידו של רבה. חברו היה רב נחמן בר יצחק (תענית כ\"א ע\"ב). נראה, שהיה הריש בעיר דרוקרת (שם).","cat": "sage"},{"i": 2957,"n": "רב נחמן בר רבא","l": "נ","b": "אמורא בבלי בדור השני. תלמידו של רב (שבת כ\"ה ע\"ב). סביר לומר, שהוא, רב נחמן בר אבא אמר רב\", המובא בבבלי (ע\"ז ל\"ט ע\"א).","cat": "sage"},{"i": 2958,"n": "רבי נחמן בר שמואל בר נחמן","l": "נ","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של רבי שמואל בר נחמן (ירו', שבת פ\"א ה\"ד). נתפס לעבודת המלך ובא לפני רבי אמי (ירו', ב\"ב פ\"ט ה\"ד). כשרבי חלבו אמר לו שישב פעמים רבות לפני אביו רבי שמואל בר נחמן, ולא שמע מה שר' נחמן אמר, השיב לו רבי נחמן: \"כל מה דהוה אבא שמיע את שמיע\". נראה, שרבי תנחומא היה תלמידו (קה\"ר פ\"ב - כ\"ד).","cat": "sage"},{"i": 2959,"n": "רב נחמן ברב גוריא","l": "נ","b": "אמורא בבלי שאיקלע לנהרדעא ושאלו ממנו ולא השיב נכון, אמרו ליה: \"רבך קטיל קני באגמא היה\" (שבת צ\"ה ע\"א), ופרש\"י: \"חותך קנים מן האגם הוה לא ידע לפרש משנה\". \"דק\"ס\" גורס: רב חמא בר גוריא.","cat": "sage"},{"i": 2960,"n": "רב נחמן בריה דרב איקא","l": "נ","b": "מובא בבבלי (מכות כ\"א ע\"א), ו\"סה\"ד\" וכתב ט\"ס. וכתב \"משה\"ס\": \"בכל המקומות איתא ר' חנינא\" ו\"סה\"ד\" גרס: רב חיננא בריה דרב איקא.","cat": "sage"},{"i": 2961,"n": "רב נחמן בריה דרב יוסף","l": "נ","b": "מובא בבבלי (בכורות י\"א ע\"א), וגירסת \"סה\"ד\": רב נחמיה בריה דרב יוסף.","cat": "sage"},{"i": 2962,"n": "ר' נחמן דיפו","l": "נ","b": "אמורא ארץ ישראלי בדור החמישי. מסר בשם ר' יעקב דקיסרין (ב\"ר פנ\"ג - ד'), ובשם ר' פנחס (תנחומא אחרי - ח').","cat": "sage"},{"i": 2963,"n": "נחמן העמסוני","l": "נ","b": "תנא בדור הרביעי. תלמידו המובהק של רבי עקיבא. שימש את רבי עקיבא עשרים ושתיים שנה, ולמדו אתים וגמים, ריבויין, אכין ורקין, ומיעוטין (ירו', ברכות פ\"ט ה\"ה).","cat": "sage"},{"i": 2964,"n": "רב נחמן מנהרדעא","l": "נ","b": "אמורא בבלי בדור החמישי. מובא בבבלי, שאיקלע לרב כהנא לפום נהרא בערב יום הכפורים (חולין צ\"ה ע\"ב).","cat": "sage"},{"i": 2965,"n": "רב נחמן מפרהטיא","l": "נ","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (קידושין פ\"א ע\"א).","cat": "sage"},{"i": 2966,"n": "נחמן סבא","l": "נ","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי: \"רבי יוסי [חברו של רבי יונה, אמורא ארץ ישראלי בדור החמישי] אומר: תנא נחמן סבא וכו'\" (ברכות פ\"ב ה\"ד).","cat": "sage"},{"i": 2967,"n": "נחמני (2)","l": "נ","b": "אביהם של ארבעה אחים חכמים: רבה בר נחמני, שהוא סתם רבה בש\"ס (גיטין ל\"ד ע\"ב רש\"י ד\"ה: והלכתא כנחמני); כייליל אבי אביי (זבחים קי\"ח ע\"ב רש\"י ד\"ה: חד ברא); רב (לא רבי!) חנניה; רב (לא רבי!) אושעיא (סנהדרין י\"ד ע\"א מהרש\"א).","cat": "sage"},{"i": 2968,"n": "ר' נחשון","l": "נ","b": "מובא ב\"ילקוט\" (תהלים רמז תשנ\"ב).","cat": "sage"},{"i": 2969,"n": "ניולי","l": "נ","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא: \"ת\"ש, דאמר ניולי אמר רב הונא\" (חולין מ\"ה ע\"ב), ופרש\"י: \"ניולי שם חכם\".","cat": "sage"},{"i": 2970,"n": "ניותי","l": "נ","b": "מובא בבבלי: \"אמר רבי אבא בר כהנא: פעם אחת נפל [בשבת] אחד [נחש] בבית המדרש, ועמד ניותי אחד והרגו\" (שבת קכ\"א ע\"ב), ופרש\"י: \"ניותי על שם מקומו, וישראל היה\", ואמנם אין להוכיח שהיה חכם, אך מסתבר כך, שכן היה בבית המדרש ונראה שם שהיה מלומדי הישיבה, ולאחר שהרג לנחש: \"אמר רבי: 'פגע בו כיוצא בו'\" ופרש\"י: \"ולא לגנאי אמר רבי\", וזה שרש\"י אומר: \"ישראל היה\" ולא כתב: \"חכם\", אינו אומר ולא כלום, שכן כך דרכו של רש\"י, ומצינו הרבה בש\"ס שכך פירש. \"יוחסין\" ו\"סה\"ד\" מביאים אותו בין החכמים.","cat": "sage"},{"i": 2971,"n": "ר' ניחא בר סבא","l": "נ","b": "אמורא ארץ ישראלי בדור הששי. תלמידו של רבי יונה: \"בעי קומי ר' יונה\" (ירו', יבמות רפ\"ט).","cat": "sage"},{"i": 2972,"n": "נימוס אחי רבי יהושע הגרסי","l": "נ","b": "תנא בדור הרביעי. מובא בבבלי: \"אמר רבי יוסי [תלמידו של רבי עקיבא]: 'סח לי נימוס, אחיו של רבי יהושע הגרסי, [תלמידו ומשרתו של ר\"ע (עירובין כ\"א ע\"ב)] שהשוחט את העורב להתלמד בו דמו מכשיר רבי אליעזר אומר וכו'\" (בכורות י' ע\"ב).","cat": "sage"},{"i": 2973,"n": "נימוס הגרדי","l": "נ","b": "מובא בבבלי (חגיגה ט\"ו ע\"ב). ע\"ע אבנימוס הגרדי (פילוסוף נכרי).","cat": "sage"},{"i": 2974,"n": "ניפטיים הגר","l": "נ","b": "גר שחי בארץ ישראל בדור הרביעי לתנאים. מובא בבבלי: \"ת\"ש דא\"ר יוסי [תלמידו של ר\"ע]: מעשה בניפטיים הגר שנשא אשת אחיו מאמו, ובא מעשה לפני חכמים ואמרו וכו'\" (יבמות צ\"ח ע\"א), ואין ראיה שנמנה עם החכמים. ואולי קצת ראיה יש שהיה חכם, כי שם באותו עמוד מובא מעשה בגר אחר והוא לא מוזכר בשמו, אך אין זו ראיה ברורה כלל.","cat": "sage"},{"i": 2975,"n": "ניקומכי","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זעירא: \"תני קומי ר' זעירא\" (ירו', סנהדרין פ\"ו ה\"ט).","cat": "sage"},{"i": 2976,"n": "נירון קיסר","l": "נ","b": "שר צבא רומי שהתגייר, והיה אביו של רבי מאיר (גיטין נ\"ו ע\"א).","cat": "sage"},{"i": 2977,"n": "רב ניתאי","l": "נ","b": "אמורא בבלי בדור השני. תלמידו של שמואל: \"רב נתאי סבר למעבד עובדא כרבי זכריה בן הקצב [התנא] א\"ל שמואל: 'אפס זכריה'\" (ב\"ב קי\"א ע\"א), כלומר, אין הלכה כזכריה בן הקצב.","cat": "sage"},{"i": 2978,"n": "ניתאי איש תקוע","l": "נ","b": "מובא במשנה: \"נתאי איש תקוע הביא חלות מביתר, ולא קבלו ממנו\" (חלה פ\"ד מ\"י). כן מובא בירושלמי: \"ניתאי איש תקוע הביא חלות מבייתות, ולא קבלו מממנו\" (חלה פ\"ד ה\"ה), ואין ראיה שנמנה עם החכמים. \"יוחסין\" כתב: \"היות והיה מן החסידים לכן הזכיר שמו\".","cat": "sage"},{"i": 2979,"n": "ניתאי הארבלי","l": "נ","b": "חכם קדמון מחכמי ה\"זוגות\". עמד בראש העם בימי החשמונאים. שימש כאב בית דין תחת נשיאותו של יהושע בן פרחיה (חגיגה ט\"ז ע\"ב), ושניהם היו הזוג השני מחמשת ה\"זוגות\" בימי בית שני - קיבלו תורתם מיוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים (אבות פ\"א מ\"ו). פתגמו היה: \"הרחק משכן רע, ואל תתחבר לרשע, ואל תתייאש מן הפורענות\" (אבות שם מ\"ז).","cat": "sage"},{"i": 2980,"n": "רבי נסא","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. מסר משמו של רבי אלעזר (ירו', שביעית פ\"ד ה\"ב) ורבי יוסי בר חנינא (ירו', ב\"מ רפ\"ג). חברו של ר' יונה (ירו', עירובין פ\"ב ה\"א; ב\"מ רפ\"ג). ר' רדיפא מסר משמו (ירו', עירובין ספ\"ק). נפטר בגיל צעיר ולא הכיר את אביו שהיה חכם (ירו', סוף תרומות).","cat": "sage"},{"i": 2981,"n": "ר' נסא דקסרין","l": "נ","b": "מובא באיכ\"ר (בפתיחתא - כ\"ו).","cat": "sage"},{"i": 2982,"n": "ר' נסים","l": "נ","b": "מובא בש\"ר (פט\"ו - י\"ט). ואולי יש ט\"ס בשם. \"סה\"ד\" לא הביאו.","cat": "sage"},{"i": 2983,"n": "ר' נפתלי","l": "נ","b": "חי בארץ ישראל בדור הששי לאמוראים. היות ומכונה \"ר'\", נראה שנמנה עם החכמים. היה כהן, והיתה לו אצבע עקומה וכו' ושאל לרבינא אם מותר לו לעלות לדוכן, ור' מנא ענה לו מכיון שאתה \"דש בעירך\" (בני העיר הורגלו לראותך בכך) - מותר.","cat": "sage"},{"i": 2984,"n": "נקדימון בן גוריון","l": "נ","b": "חסיד גדול. חי בירושלים בזמן בית המקדש. שמו היה: \"בוני\", ולמה נקרא שמו נקדימון? ש\"קדרה חמה עבורו\", שהקב\"ה עשה לו נס כפול: בראשונה התפלל לה' שירדו גשמים, וירדו, והוסיף לבקש מה' שהשמש תזרח, וזרחה (תענית י\"ט ע\"ב). היה משלושת עשירי ירושלים, וקיבל על עצמו לזון ולכלכל את כל בני העיר במשך עשרים ואחת שנה (גיטין נ\"ו ע\"א). נראה, שהיה מן החכמים (כתובות ס\"ו ע\"ב). \"סה\"ד\" לא הביא את שמו.","cat": "sage"},{"i": 2985,"n": "נקיי","l": "נ","b": "כך שמו. חי בזמן הבית. נראה שלא היה מן החכמים. מובא בירושלמי (מע\"ש פ\"ה ה\"ב). \"פני משה\" פירש: \"כך שמו והיה שמש [במקום שמו] מגדלא דצבעייא\". פירוש שני, שהיה סופר מלמד תינוקות.","cat": "sage"},{"i": 2986,"n": "רב נתן","l": "נ","b": "אמורא בבלי בדור הששי. מושבו היה בהגרוניא. מובא בבבלי: \"ריש גלותא איקלע להגרוניא לבי רב נתן רפרם וכולהו רבנן אתו לפירקא, רבינא לא אתא\" (יומא ע\"ח ע\"א).","cat": "sage"},{"i": 2987,"n": "רבי נתן","l": "נ","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי: \"אמר רבי נתן טעמא דנתן בר הושעיה\" (תרומות פ\"ז ה\"א).","cat": "sage"},{"i": 2988,"n": "רב נתן אבוה דרב הונא בריה דרב נתן","l": "נ","b": "אמורא בבלי בדור החמישי. מובא בבבלי (פסחים מ\"ג ע\"ב; זבחים ע' ע\"ב). נקרא על שם בנו, אולי מפני שבנו היה ראש גולה (סמוך לאחר רב אשי) והיו בו (בבנו זה) תורה וגדולה במקום אחד, שלא היה מימי רבי (גיטין נ\"ט ע\"א). היה תלמידו של רב פפא, ואמר הקידוש לפני רב פפא [כסבי דפומבדיתא] ושבחיה רב פפא (פסחים קי\"ז ע\"ב).","cat": "sage"},{"i": 2989,"n": "רבי נתן ביראה","l": "נ","b": "מובא בבבלי (כתובות ע\"ה ע\"א). בברייתא ששנה שקלו וטרו רב אשי ורב אחא בריה דרבא (שם).","cat": "sage"},{"i": 2990,"n": "רבי נתן בן אבטולמיס","l": "נ","b": "תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (זבחים מ\"ט ע\"ב), והגיר' במקום אחר: רבי יונתן בן אבטולמיס (נדה י\"ט ע\"א).","cat": "sage"},{"i": 2991,"n": "ר' נתן בן אלעזר","l": "נ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (בראשית י') ששאל לר' שמואל.","cat": "sage"},{"i": 2992,"n": "רבי נתן בן עמרם","l": "נ","b": "מובא בבבלי (ע\"ז ל\"ו ע\"ב), וצ\"ל: רבי יונתן בן עמרם.","cat": "sage"},{"i": 2993,"n": "רב נתן בר אבא א'","l": "נ","b": "אמורא בבלי בדור השני. תלמיד של רב: \"תרגמא רב נתן בר אבא קמיה דרב\" (ב\"מ מ\"א ע\"א), וכן היה תלמידו של שמואל. מסופר, שאמר לפני שמואל שיודע להבדיל בין עוברי דגים טמאים לטהורים, וטעה ואמר על טהור טמא, ושמואל הקפיד על כך, ואמר לו: אין אתה מתבייש לומר על טהור טמא, סופך לומר על טמא טהור (ירו', ע\"ז ספ\"ב).","cat": "sage"},{"i": 2994,"n": "רבי נתן בר אבא ב'","l": "נ","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי, שבא לבקר את רבי שמואל בר אבא באבלו (מו\"ק פ\"ג ה\"א), וכן בא רבי אלעזר (שם).","cat": "sage"},{"i": 2995,"n": "רב נתן בר אביי","l": "נ","b": "אמורא בבלי בדור השלישי. מובא בבבלי (חולין צ\"ה ע\"ב) שבא לפני רב חסדא, ורב חסדא החזיר לו אבידה לפי טביעת עין, מבלי שהיה לו סימן. \"סה\"ד\" מפקפק אם צריך לגרוס: רב נתן בר אדא או רב נתן בר אבין.","cat": "sage"},{"i": 2996,"n": "רב נתן בר אבין","l": "נ","b": "אמורא בבלי בדור השני. תלמידו של רב ויתיב לפניו ובדק בטרפות (חולין מ\"ה ע\"ב). גיר' \"דק\"ס\": רב נתן בר אבא, ואם נגרוס כך, הרי לא קיים חכם בשם רב נתן בר אבין, שכן שוב לא נזכר בש\"ס.","cat": "sage"},{"i": 2997,"n": "רבי נתן בר אבישלום","l": "נ","b": "תנא דברייתא. מובא במחלוקת עם תלמידיו של רבי עקיבא - רבי יוסי, רבי יוחנן הסנדלר ורבי יהודה (ברכות כ\"ב ע\"א). סביר לומר, שחי בדור הרביעי לתנאים.","cat": "sage"},{"i": 2998,"n": "רב נתן בר אושעיא","l": "נ","b": "אמורא בבלי בדור השני - השלישי. עלה לארץ ישראל וישב לפני רבי יוחנן (ירו', ב\"ב רפ\"ט). בר פלוגתיה דרב יהודה (קידושין ל\"ב ע\"א) ושל רב חסדא (חולין קל\"ח ע\"א). אביי תירץ קושייתו (גיטין י\"ח ע\"א).","cat": "sage"},{"i": 2999,"n": "ר' נתן בר אמי","l": "נ","b": "אמורא בבלי בדור החמישי. ממקורבי תלמידיו של רבא (שבת ק\"נ ע\"ב). רבא לימדו דרכי חיים וחינוך בנים (קידושין ל' ע\"א) היה עשיר גדול. רבא לקח ממנו ד' מאות זוזי לצדקה (ב\"ב ח' ע\"ב).","cat": "sage"},{"i": 3000,"n": "רב נתן בר אסיא","l": "נ","b": "אמורא בבלי בדור הרביעי. מובא בבבלי, שהלך מבי רב לפומבדיתא ביו\"ט שני של עצרת, ושמתיה רב יוסף (פסחים נ\"ב ע\"א).","cat": "sage"},{"i": 3001,"n": "ר' נתן בר טובי","l": "נ","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ברכות כ\"ח ע\"א). ר\"ז ישב ליד פתח בית המדרש, ור' נתן בר טובי מסר לו דין ששמע בבית המדרש מרבי יוחנן, ור\"ז שיננו 04 פעם (שם). וטעות ב\"סה\"ד\", שכתב שרבי נתן בר טובי קיבל מר\"ז.","cat": "sage"},{"i": 3002,"n": "ר' נתן בר יוסף","l": "נ","b": "מובא בבבלי (מגילה ל\"א ע\"ב), והוא ר' יונתן התנא.","cat": "sage"},{"i": 3003,"n": "רב נתן בר מניומי","l": "נ","b": "אמורא בבלי בדור הרביעי - חמישי. רב כהנא מסר משמו שתי דרשות שמסר בשם ר' תנחום (שבת כ\"א ע\"ב).","cat": "sage"},{"i": 3004,"n": "נתן בר מר זוטרא","l": "נ","b": "אמורא בבלי בדור השביעי. בנו של מר זוטרא. נראה, שהיה כחבר לרב אשי בישיבתו: \"אמר רב אשי: 'אמר לי נתן בר מר זוטרא'\" (סנהדרין כ\"ט ע\"א). גם אחיו הונא היה חכם, תלמיד של רבינא (ב\"ב פ\"ו ע\"א).","cat": "sage"},{"i": 3005,"n": "רב נתן בר מר עוקבא","l": "נ","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (ברכות י\"ג ע\"ב).","cat": "sage"},{"i": 3006,"n": "נתן בר שילא","l": "נ","b": "ראש טבחי צפורי בזמנו של רבי. העיד לפני רבי משום רבי נתן: \"איזו כרס הפנימית וכו'\" (חולין נ' ע\"ב). ואין ראיה שהיה חכם, גם אם העיד לפני רבי משמו של רבי נתן. \"יוחסין\" ו\"סה\"ד\" הביאוהו בין החכמים.","cat": "sage"},{"i": 3007,"n": "ר' נתן בריבי","l": "נ","b": "כך מביא \"סה\"ד\" הגיר' בספרי (פ' ואתחנן).","cat": "sage"},{"i": 3008,"n": "ר' נתן בריה דר' ברכיה","l": "נ","b": "אמורא ארץ ישראלי בדור החמישי. יחד עם ר' ישמעאל בר תנחום מסר משום רבי ירמיה (ילקוט קהלת פ\"ה פסוק ויתרון).","cat": "sage"},{"i": 3009,"n": "ר' נתן דבית גוברין","l": "נ","b": "מובא בקהלת רבה (פסוק עת ללדת). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: ר' יונתן דבית גוברין\".","cat": "sage"},{"i": 3010,"n": "נתן דצוציתא","l": "נ","b": "הוא עוקבן בר נחמיה, ראש גלותא בבבל בדור השלישי לאמוראים. היה בעל תשובה גדול, ועל כינויו \"נתן דציצותא\" כתב רש\"י: על שם ניצוצין דנורא, שהמלאך פשט ידו וקבל תשובתו (שבת נ\"ו ע\"ב ד\"ה: נתן). תוספות כתבו שם, שהיה נר דלוק על ראשו, ועל כן קראו לו ר' נתן ציציתא.","cat": "sage"},{"i": 3011,"n": "ר' נתן דרומה","l": "נ","b": "מובא בירושלמי שרבי חנינא ורבי יונתן שאלו ממנו (עירובין פ\"ו ה\"ד). יתכן שיש ט\"ס בשם.","cat": "sage"},{"i": 3012,"n": "רבי נתן הבבלי","l": "נ","b": "תנא בבלי בדור הרביעי, שעלה לארץ ישראל (גיטין ס\"ה ע\"ב רש\"י ד\"ה: רבי נתן דבבלאה הוא). כשבא לא\"י, מינה אותו רבן שמעון בן גמליאל (אבי רבי) ל\"חכם\", דהיינו אב\"ד (ב\"מ קי\"ז ע\"ב רש\"י). אביו היה ריש גלותא בבבל (\"ערוך\" ערך קמרא, וכן מוכח מהוריות י\"ג ע\"ב). מסר משום רבי אליעזר (פסחים מ\"ח ע\"א), ורבי ישמעאל (שם ס\"ז ע\"ב) ורבי יוסי הגלילי (מנחות ל\"ח ע\"ב). היה חברו של רבי מאיר (הוריות י\"ג ע\"ב) וכשרשב\"ג פגע בכבוד רבי נתן ורבי מאיר, ניסו שניהם להוריד את רשב\"ג מנשיאותו (שם), ועל כך נקנס רבי נתן ובמקום שיזכירו את שמו מסרו את מאמריו בכינוי: \"יש אומרים\" (שם). היה רבו של רבי (ירו', כתובות פ\"ד הי\"א). מסכת אבות דרבי נתן מיוחסת לו. היה לו גילוי אליהו (גיטין ע' ע\"א). ועליו אמרו: \"רבי ורבי נתן סוף משנה\" (ב\"מ פ\"ו ע\"א), הרמ\"א כתב: \"רבי ורבי נתן הלכה כרבי נתן\".","cat": "sage"},{"i": 3013,"n": "נתן החבר","l": "נ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (תולדות - כ\"ב), שאמר בשם רבי אחא.","cat": "sage"},{"i": 3014,"n": "ר' נתן כהן אחוי דר' חייא בר אבא","l": "נ","b": "ע\"ע רבי כהן.","cat": "sage"},{"i": 3015,"n": "ר' נתנאל","l": "נ","b": "מובא בפדר\"א (פי\"ז).","cat": "sage"},{"i": 3016,"n": "סבטא בן אלס","l": "ס","b": "מובא בבבלי (סנהדרין ס\"ד ע\"א). רש\"י גרס: סבטאי, ופירש: \"שם יהודי הוא\", \"בן אלס\" פרש\"י: \"שם מקום\". ואין לדעת אם היה מן החכמים.","cat": "sage"},{"i": 3017,"n": "סביא","l": "ס","b": "אמורא ארץ ישראלי בדור הראשון - השני. מובא בבבלי: \"רבי יוחנן וסביא, חד אמר וכו'\" (יבמות ט\"ז ע\"ב). אולי הוא לוי סבא, שריש לקיש מסר משמו.","cat": "sage"},{"i": 3018,"n": "ר' סובייה","l": "ס","b": "מובא בירושלמי (פסחים פ\"ו ה\"א). ע\"ע לוי סבא.","cat": "sage"},{"i": 3019,"n": "סומא בר כתבה","l": "ס","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי שמעון בן לקיש (במ\"ר פי\"ד - א').","cat": "sage"},{"i": 3020,"n": "סומכוס","l": "ס","b": "תנא בדור החמישי. פעם אחת בש\"ס הובא שמו במלואו: \"סומכוס בן יוסף\" (ירו', ברכות פ\"ב ה\"א). תלמידו המובהק של רבי מאיר. היה חריף ביותר ואמרו עליו: \"תלמיד הוה לו לרבי מאיר וסומכוס שמו, שהיה אומר על כל דבר ודבר של טומאה ארבעים ושמונה טעמי טומאה, ועל כל דבר ודבר של טהרה ארבעים ושמונה טעמי טהרה\" (עירובין י\"ג ע\"ב). אחרי פטירת רבי מאיר, ביקש סומכוס ללמוד לפני רבי יהודה (נזיר מ\"ט ע\"ב). האריך ימים, עד שרב למד ממנו (כתובות פ' ע\"א): \"א\"ר אבא שאלתי את סומכוס\", ופי' רבינו האי גאון שזה ר' אבא הוא רב.","cat": "sage"},{"i": 3021,"n": "סורחב בר פפא","l": "ס","b": "אמורא בדור השלישי. אמר משמיה דזעירי (כתובות י\"ז ע\"ב).","cat": "sage"},{"i": 3022,"n": "רב סחורה","l": "ס","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (ברכות ה' ע\"א). רבו המובהק של רבא (יבמות ק\"ו ע\"א תד\"ה: רבא) ורבו שיבחו לפני רב נחמן שאדם גדול הוא (נדרים כ\"ב ע\"ב).","cat": "sage"},{"i": 3023,"n": "רבי סידור","l": "ס","b": "אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי: \"אמר רבי סידור, יהודה ברבי [יהודה בנו של רבי חייא] למד מכשירין ששה ירחים, לבסוף בא אחד מתלמידי רבי סימאי ושאלו דבר במכשירין ולא ידע לענות לו\" (שבת פ\"ז ה\"ב).","cat": "sage"},{"i": 3024,"n": "סילני","l": "ס","b": "מובא בירושלמי (שביעית רפ\"ג) ששאל לרבי חייא בר אבא. אין לדעת אם היה מן החכמים. \"סה\"ד\" הביאו בין החכמים (ונדפס ב\"סה\"ד\" בטעות \"שבועות רפ\"ג\", וצ\"ל \"שביעית\").","cat": "sage"},{"i": 3025,"n": "רב סימא בריה דרב אידי","l": "ס","b": "אמורא בבלי בדור השביעי. מתלמידי רב אשי והקשה לו (מנחות כ\"ה ע\"א).","cat": "sage"},{"i": 3026,"n": "רב סימא בריה דרב אשי","l": "ס","b": "מובא בבבלי (מנחות כ\"ה ע\"א), והוא רב סמא בריה דרב אשי.","cat": "sage"},{"i": 3027,"n": "רבי סימאי","l": "ס","b": "מאחרוני התנאים בארץ ישראל. שמו מוזכר בברייתא (יבמות פ\"ג ע\"ב). רבי יונתן היה מתלמידיו (ב\"מ צ' ע\"ב). רבי יוחנן מסר משמו (ירו', מעשרות פ\"א ה\"א) ושם הגיר' רבי סיסיי, אך נראה שט\"ס היא וצ\"ל: סימאי. וכן היה ריש לקיש מתלמידיו (יבמות ע\"ד ע\"א). הלך לעבר שנה בלוד (חולין נ\"ו ע\"ב). לבנו מנחם קראו: \"בנן של קדושים\", שכן לא הסתכל בצורת מטבע מימיו (פסחים ק\"ד ע\"א). בנו היה תנא (שם).","cat": "sage"},{"i": 3028,"n": "ר' סימאי בר קיסי","l": "ס","b": "מובא בפסדר\"כ (ספי\"ז - קלד).","cat": "sage"},{"i": 3029,"n": "רבי סימון","l": "ס","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ב\"ק קט\"ו ע\"ב), והיה מסדר לפניו דברי אגדה (ברכות י' ע\"א). מסר בשם רבי יוחנן (ירו', פסחים פ\"ד ה\"א). היו לו שדות בהר המלך, שלא יכול לעבדם בעצמו, ושאל לרבי יהושע בן לוי וגם לרבי יוחנן כיצד לנהוג (ירו', דמאי פ\"א ה\"א). מחבריו היה בעל האגדה רבי לוי (ירו', ברכות פ\"א ה\"א). אמרו משמו: רבי ברכיה (ב\"ר רפ\"ו - ספ\"י) ורבי תנחום בר חמא (ירו', מו\"ק פ\"ג ה\"ז). מצינו: \"א\"ל ר\"ז לר' סימון: 'לוכחינהו מר להני דבי ריש גלותא'\" (שבת נ\"ה ע\"א), ומזה ניתן אולי להסיק שר' סימון היה בבבל, או אולי ר\"ז, שהיה בבלי, קרא לנשיא: \"ריש גלותא\".","cat": "sage"},{"i": 3030,"n": "רבי סימון אחוה דר' יהודה בר זבדי","l": "ס","b": "אמורא ארץ ישראלי בדור השני. תלמידם של רבי אסי (ירו', שביעית פ\"ב ה\"ה) ורבי אלעאי (ירו', פסחים פ\"ח ה\"ו), נפטר בחיי ר' אלעאי, שהספידו (ירו', ברכות פ\"ח ה\"ו). מסר בשם רב (ירו', ב\"ב רפ\"ג). והמוסרים בשמו היו ר' חזקיה ר' יונה ור' פנחס (קה\"ר פ\"ב - א'). היו לו שני אחים: ר' יהודה ור' אבא.","cat": "sage"},{"i": 3031,"n": "ר' סימון בן קיזות","l": "ס","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי לוי (שהש\"ר פ\"ח - ו').","cat": "sage"},{"i": 3032,"n": "רבי סימון בר זבדי","l": "ס","b": "מובא בירושלמי (שביעית פ\"ב ה\"ה). נראה שהוא רבי סימון אחוה דרבי יהודה בר זבדי.","cat": "sage"},{"i": 3033,"n": "ר' סימון בר יהושע","l": "ס","b": "מובא בויק\"ר (פכ\"ח - ט').","cat": "sage"},{"i": 3034,"n": "ר' סימון בר מרתא","l": "ס","b": "מובא בב\"ר (ספ\"ט).","cat": "sage"},{"i": 3035,"n": "ר' סימון בר תדאי","l": "ס","b": "כן גיר' הר\"ן ולפנינו ר' סימון דתרי (ירו', שבת פ\"ג ה\"א).","cat": "sage"},{"i": 3036,"n": "רבי סימון ברבי יהושע בן לוי","l": "ס","b": "מובא בירושלמי (מגילה פ\"א ה\"ה). יתכן שיש כאן ט\"ס וצ\"ל: ר' סימון בשם רבי יהושע בן לוי.","cat": "sage"},{"i": 3037,"n": "ר' סימון דתרי","l": "ס","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי אושעיא (ירו', שבת פ\"ג ה\"א).","cat": "sage"},{"i": 3038,"n": "ר' סימון מן דרומא","l": "ס","b": "מובא באס\"ר (פ\"ד - ד').","cat": "sage"},{"i": 3039,"n": "רב סימונא","l": "ס","b": "מראשי הדור השני של רבנן סבוראי. חברו ובן זוגו של רב עינא. עמד בראש ישיבת פומבדיתא. לא מובא בתלמוד, אך מוזכר ב\"אגרת רב שרירא גאון\", שרב עינא ורב סימונא הכניסו כמה הבהרות וסברות כהוספות בתלמוד.","cat": "sage"},{"i": 3040,"n": "רבי סימיי","l": "ס","b": "מובא בירושלמי (מע\"ש פ\"ב ה\"א), ונראה שהוא רבי סימאי.","cat": "sage"},{"i": 3041,"n": "סימן","l": "ס","b": "מובא בבבלי: \"סימן אמר רבה בר רב שילא, אמר קרא וכו'\" (ב\"ב קי\"ג ע\"א), ו\"מסורת הש\"ס\" כתב: \"יש לומר שהוא שם אמורא\". אם כן, הרי שהיה אמורא בבלי בדור הרביעי - החמישי.","cat": "sage"},{"i": 3042,"n": "ר' סיסא","l": "ס","b": "אמורא בבלי בדור השני. מובא בש\"ר (פנ\"א - ח') שחלק עם רב הונא.","cat": "sage"},{"i": 3043,"n": "רבי סיסיי","l": "ס","b": "מובא בירושלמי (מעשרות פ\"א ה\"א), ונראה שצ\"ל רבי סימאי.","cat": "sage"},{"i": 3044,"n": "רב סלא","l": "ס","b": "אמורא בדור הרביעי - החמישי. תלמידו של רבי ירמיה (ביצה ל\"א ע\"א). כן היה תלמידו של רב המנונא (תענית ז' ע\"ב).","cat": "sage"},{"i": 3045,"n": "רב סמא","l": "ס","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (מנחות מ\"ב ע\"א): \"רבינא ורב סמא הוו יתבי קמיה דרב אשי וכו' א\"ל [רב אשי לר' סמא] וכו' איכסיף\".","cat": "sage"},{"i": 3046,"n": "רב סמא בר חילקאי","l": "ס","b": "אמורא בבלי בדור הששי. נראה שהיה חברו של רבינא: \"אמר רבינא: 'אמר לי סמא בר חילקאי [ולא אמר רב סמא]: אקשי בה אבוה דבר אבוברם וכו'\" (חולין ל\"ח ע\"א).","cat": "sage"},{"i": 3047,"n": "רב סמא בר רקתא","l": "ס","b": "אמורא בבלי בדור הששי. מובא בבבלי, שחלק עם רבינא ונשבע \"בכתר המלך\" שדבריו נכונים (קידושין ט' ע\"א).","cat": "sage"},{"i": 3048,"n": "רב סמא בריה דרב אסי","l": "ס","b": "אמורא בבלי בדור השביעי. היה מתלמידיו של רב אשי והקשה לו (כתובות ל\"ג ע\"ב). אביו רב אסי היה בן דורו של רב אשי.","cat": "sage"},{"i": 3049,"n": "רב סמא בריה דרב אשי","l": "ס","b": "אמורא בבלי בדור השביעי. בנו ותלמידו של רב אשי והקשה לאביו (כתובות ל\"ג ע\"ב). ולפי דעתו של רש\"י (שם, ס\"ט ע\"א ד\"ה: למיגבה) מת רב סמא בחיי רב אשי אביו.","cat": "sage"},{"i": 3050,"n": "רב סמא בריה דרב ייבא","l": "ס","b": "אמורא בבלי בדור הששי. תלמידו של רב פפא (ב\"ב ט' ע\"א).","cat": "sage"},{"i": 3051,"n": "רב סמא בריה דרב ירמיה","l": "ס","b": "אמורא בבלי. אולי אפשר לומר, שהיה בזמנו של אביי (דור הרביעי לאמוראים), כמובא בבבלי: \"הדר אמר אביי וכו', מתקיף לה רב סמא בריה דרב ירמיה וכו' אמר קרא וכו'\" (כתובות ל\"ג ע\"א). אין לדעת אם אביי ענה לו: \"אמר קרא\", או שזה ממסדר הש\"ס.","cat": "sage"},{"i": 3052,"n": "רב סמא בריה דרב מרי","l": "ס","b": "אמורא בבלי בדור הרביעי. רב חנא בר אדא אמר משמו (ברכות ס\"ב ע\"ב).","cat": "sage"},{"i": 3053,"n": "רב סמא בריה דרב משרשיא","l": "ס","b": "אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי: \"א\"ל רבינא לרב אשי: אמר לן רב סמא בריה דרב משרשיא משמך דאמרת ליה משמיה דרבא וכו'\" (חולין י\"ז ע\"ב).","cat": "sage"},{"i": 3054,"n": "רב סמא בריה דרבא","l": "ס","b": "אמורא בבלי בדור השביעי. היה ראש ישיבה בפומבדיתא בשנים ד' ר\"ה - רל\"ה (544 - 574) (\"אגרת רב שרירא גאון\"). מוזכר בבבלי קודם לרב אשי (ב\"מ מ\"ב ע\"ב). בימיו היו גזירות קשות על ישראל במלכות פרס, וכמה חכמים נהרגו על ידי המלך יזדגר השני, וביקשו רחמים ובא תנין ובלע את המלך בחדר משכבו ובטלו הגזירות (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 3055,"n": "סמוכוס בר יוסף","l": "ס","b": "מובא בירושלמי (ברכות פ\"ה ה\"א). ע\"ע סומכוס.","cat": "sage"},{"i": 3056,"n": "רבי סמיא","l": "ס","b": "מובא בבבלי, דאמר ריש לקיש אמר רבי סמיא (יבמות ע\"ד ע\"א), ונראה אולי שצ\"ל: רבי סימאי.","cat": "sage"},{"i": 3057,"n": "סמליון","l": "ס","b": "מובא בבבלי: \"סמליון אומר\" (סוטה י\"ג ע\"ב), ופרש\"י: \"שם חכם\", והר\"ח וה\"ערוך\" ותוספות מפקפקים אם זה שם מלאך או שם חכם.","cat": "sage"},{"i": 3058,"n": "רב סעורם","l": "ס","b": "מובא בבבלי (ב\"מ ע\"ג ע\"ב), והוא רב שעורם.","cat": "sage"},{"i": 3059,"n": "רב ספרא","l": "ס","b": "אמורא בבלי בדור השלישי - הרביעי. היה מספר פעמים בארץ ישראל. שאל מרבי אבא (פסחים נ\"א ע\"ב) וקרא לו לרבי אבא: \"משה\" (פרש\"י בחולין צ\"ג ע\"א: תלמיד חכם). רבי אבהו אמר למינים שהוא אדם גדול (ע\"ז ד' ע\"א). רבא קרא לו: \"גברא רבא\" (ב\"ב קמ\"ד ע\"א). הקשה לרבי אבהו ורבי חנינא בר פפא ורבי יצחק נפחא, ולא ידעו להשיבו, ואמר רבא: \"קפחינהו רב ספרא לתלתא רבנן סמיכי\" (גיטין כ\"ט ע\"ב). אביי ביקש ממנו, שבבואו לארץ ישראל ישאל שם שאלה בהלכה, והוא שאל מרבי זריקא, וכשחזר מסר לאביי (חולין ק\"י ע\"ב). היה חברו של רב נחמן: וא\"ל רב ששת לרב נחמן: \"ספרא חברך תרגומה וכו'\" (בכורות י' ע\"ב). נזהר ביותר להתרחק מכל דבר שקר (חולין צ\"ד ע\"ב). ודרשו: \"ודובר אמת בלבבו כגון רב ספרא\" (מכות כ\"ד ע\"א). רש\"י מביא מעשה עד כמה היה ירא שמים ואיש אמת: פעם הלך בשיירה ואריה נלוה אליהם ונעשה נס לרב ספרא (ב\"ק קט\"ז ע\"א), וכשנפטר רב ספרא צוה אביי שיקרעו עליו קריעה שהלכותיו מצויות בכל יום בבית המדרש (מו\"ק כ\"ה ע\"א).","cat": "sage"},{"i": 3060,"n": "רב ספרא בריה דרב ייבא","l": "ס","b": "אמורא בבלי בדור הששי. חברו של רבינא: \"א\"ל רב ספרא בריה דרב ייבא לרבינא: אמרי אינשי וכו'\" (ב\"ב ה' ע\"א).","cat": "sage"},{"i": 3061,"n": "רב עובדיה","l": "ע","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (ברכות ט\"ו ע\"ב). ישב לפני רבא כששלחה אפרא הורמיז, אמו של שבור מלכא, לשאול שאלה מרבא (נדה כ' ע\"ב).","cat": "sage"},{"i": 3062,"n": "רבי עוזיאל בר בריה דרבי עוזיאל רבה","l": "ע","b": "מובא בבבלי (מו\"ק ה' ע\"א).","cat": "sage"},{"i": 3063,"n": "ר' עוזיאל בריה דר' נחוניא דברת חוורין","l": "ע","b": "אמורא ארץ ישראלי בדור השני. מובא בירושלמי (שבת פ\"א ה\"ז). אביו. רבי נחוניא דברת חוורן, היה מרבותיו של רבי יוחנן.","cat": "sage"},{"i": 3064,"n": "רב עוירא א'","l": "ע","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידם של רבי אמי ורב אסי: \"דרש רב עוירא, זימנין משמיה דרבי אמי, וזימנין משמיה דרבי אסי\" (ברכות כ' ע\"ב). ורש\"י פירש שקיבל משניהם (שבת ק\"ח ע\"ב ד\"ה: זימנין). היה חברם של רבי חלבו ורבי יוסי בר חנינא (כתובות קי\"ב ע\"א). ביקר בבבל, ואביי בא אליו (חולין נ\"א ע\"א).","cat": "sage"},{"i": 3065,"n": "רב עוירא ב'","l": "ע","b": "אמורא בבלי בדור החמישי - הששי. חברו של רבינא, ושניהם אמרו משמיה דרבא (ב\"ב קל\"א ע\"ב). תירץ קושיית רבינא (פסחים ע\"ג ע\"א).","cat": "sage"},{"i": 3066,"n": "רב עוירא סבא","l": "ע","b": "אמורא בבלי בדור השלישי. מובא בבבלי: \"כי אתה רבה בר בר חנה אכל דאייתרא [חלב שבכפיפת הקיבה שבני א\"י נהגו בו היתר], על לגביה רב עוירא סבא ורבה בריה דרב הונא, כיון דחזינהו כסייה מינייהו\" [נחבא מהם] (פסחים נ\"א ע\"א).","cat": "sage"},{"i": 3067,"n": "עולא (2)","l": "ע","b": "אמורא ארץ ישראלי בדור השני - השלישי. שם אביו היה ישמעאל: \"עולא בר ישמעאל, בשם רבי אלעזר: שלמי חגיגה ששחטן מערב הרגל אינו יוצא בהן ידי חובתו ברגל\" (ירו', סוכה פ\"ד ה\"ה). מאמר זה מובא בבבלי: \"אמר עולא אמר רבי אלעזר וכו'\" (פסחים ע' ע\"א). רבו היה רבי יוחנן (מעילה י\"ב ע\"א). ועוד קיבל מהאמוראים של דור הראשון: רבי אושעיא (חולין ע\"ו ע\"א) ורבי חנינא (מנחות ל' ע\"א). מראשוני החכמים שניתן לו התואר \"נחותא\" (ירו', כלאים פ\"ט ה\"ג). תפקידו כ\"נחותא\" היה למסור תורת ארץ ישראל לחכמי בבל: \"דרש רב חסדא וכו' ורבותינו היורדין מארץ ישראל ומני עולא משמיה דרבי יוחנן וכו'\" (ברכות ל\"ח ע\"ב). וכן: \"עולא איקלע לבי רב יהודה וכו'\" (קידושין ע\"א ע\"ב), וכן: \"עולא איקלע לבי רב נחמן וכו'\" (ברכות נ\"א ע\"ב). בין תלמידיו המובהקים היו רבי אבא ורבה בר בר חנה, כמו שמצינו, שעולא רכב ורבי אבא לימינו ורבה בר בר חנה לשמאלו (פסחים נ\"ג ע\"ב). וכן היו בין תלמידיו: רבה, רבי זירא (שם ל\"ז ע\"ב) ורב יוסף (שם). עולא נפטר בבבל, בחיי רבי אלעזר (כתובות קי\"א ע\"א).","cat": "sage"},{"i": 3068,"n": "עולא ביראה","l": "ע","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר (מו\"ק כ\"ו ע\"א). רבו של רבי חלבו (ויק\"ר ספי\"א).","cat": "sage"},{"i": 3069,"n": "רב עולא בר אבא","l": "ע","b": "אמורא בבלי בדור השלישי - הרביעי. היה מופלג בחסידות ובמידות טובות, כמובא: \"שלחו מתם, איזהו בן עולם הבא? חסיד ועניו ושפל ברך, נכנס לבית המדרש ויצא בצנעה, ועוסק בתורה תדיר ואינו מחזיק טובה לנפשו, ונתנו רבנן עיניהם ברב עולא בר אבא\" (סנהדרין פ\"ח ע\"ב).","cat": "sage"},{"i": 3070,"n": "עולא בר חיננא","l": "ע","b": "מובא בבבלי: \"תנא עולא בר חיננא: נקטם ראשו וכו' בעי רבי ירמיה: נקטם ראשו מעיו\"ט וכו'\" (סוכה ל\"ג ע\"א).","cat": "sage"},{"i": 3071,"n": "עולא בר ישמעאל","l": "ע","b": "מובא בירושלמי (סוכה פ\"ד ה\"ה), והוא סתם עולא.","cat": "sage"},{"i": 3072,"n": "עולא בר מנשיא","l": "ע","b": "אמורא בבלי בדור השלישי. אמר משמיה דאבימי (גיטין ע\"ט ע\"א).","cat": "sage"},{"i": 3073,"n": "עולא בר קושב","l": "ע","b": "חי בדור הראשון לאמוראי ארץ ישראל. חויב במיתה ע\"י המלך וברח ללוד לרבי יהושע בן לוי, וחיילים באו ללוד והקיפו העיר ותבעו את הסגרתו. אחרת יחריבו את לוד, והסגיר את עצמו, ואליהו הנביא הקפיד עליו ואמר שכחסיד היה לו להסתלק מכל הענין (ירו', תרמות ספ\"ח). ואין ראיה שעולא בר קושב היה מן החכמים.","cat": "sage"},{"i": 3074,"n": "עולא בר רב","l": "ע","b": "אמורא בבלי בדור החמישי. תלמידם של אביי (מגילה כ\"ד ע\"ב) ורבא (שם כ\"א ע\"ב). ושאל מהם. היה חזן והתפלל לפני רבא (פסחים קי\"ז ע\"ב).","cat": "sage"},{"i": 3075,"n": "עולא בר ר' זכאי","l": "ע","b": "כן גירסת התוספות (חולין נ\"ב ע\"א ד\"ה; נעקרה), אך לפנינו הגיר': אמר עולא, בן זכאי אמר.","cat": "sage"},{"i": 3076,"n": "עולא בריה דרב אידי אמורא בבלי בדור השלישי","l": "ע","b": "הרביעי. רבא הקשה על דבריו ואמר: \"יציבא בארעא וגיורא בשמי שמיא\" (ב\"ק מ\"ב ע\"א).","cat": "sage"},{"i": 3077,"n": "רב עולא בריה דרב עילאי","l": "ע","b": "אמורא בבלי בדור השלישי. חברו של רב יוסף: \"רב עולא בריה דרב עילאי הוה ליה דינא קמיה דרב נחמן, שלח ליה רב יוסף: 'עולא חברנו עמית בתורה ובמצות'\" (שבועות ל' ע\"א). נזכר בהלכה (זבחים י\"א ע\"ב).","cat": "sage"},{"i": 3078,"n": "עולא בריה דר' אלעזר","l": "ע","b": "מובא ב\"ילקוט\" (שה\"ש רמז תתקפ\"א), ואולי שם ט\"ס וצ\"ל: עולא ביראה.","cat": "sage"},{"i": 3079,"n": "ר' עולא דקסרין","l": "ע","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי חנינא. רבי יעקב בר אחא היה תלמידו (ירו', נדה פ\"ב ה\"ז).","cat": "sage"},{"i": 3080,"n": "עולא משגש ארחתיה דאימיה","l": "ע","b": "מובא בבבלי (ב\"ב ט' ע\"ב). לפירש\"י הכוונה לרב ששת, ולפירוש רבנו גרשום הכוונה לרב אחדבוי בר אמי.","cat": "sage"},{"i": 3081,"n": "ר' עולא רבה","l": "ע","b": "מובא בבבלי: \"דרש ר' עולא רבה אפיתחא דבי נשיאה\" (כתובות ס\"ה ע\"ב).","cat": "sage"},{"i": 3082,"n": "עולא שכפא","l": "ע","b": "אמורא ארץ ישראלי בדור הרביעי. למד ברייתות לפני ר' דוסא, ואמר לו ר' דוסא: \"חזור בך\" [מאחת הברייתות] א\"ל ר\"ז: (לעולא שכפא) \"לא תחזור בך\" (ירו', ע\"ז פ\"ב ה\"ט).","cat": "sage"},{"i": 3083,"n": "רב עוקבא","l": "ע","b": "מובא בירושלמי, שאמר בשם רבי יהושע בן לוי (יומא פ\"א ה\"ב), ונראה שהוא מר עוקבא הירושלמי, תלמידו של ריב\"ל (עיין מר עוקבא).","cat": "sage"},{"i": 3084,"n": "רב עוקבא בר אבא","l": "ע","b": "אמורא בבלי בדור השלישי - הרביעי. מתלמידיו של רב נחמן, כמובא בבבלי: \"איתיביה רב עוקבא בר אבא לרב נחמן\" (עירובין ל\"ד ע\"ב).","cat": "sage"},{"i": 3085,"n": "רבי עוקבא בר אחא","l": "ע","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. חברם של רבי זירא ורבי אבא \"אמר רבי עקיבא בר אחא: עמו הייתי כד אמר רבי אבא וכו'\" (ירו', קדושין פ\"ג הי\"ב).","cat": "sage"},{"i": 3086,"n": "רב עוקבא בר חיננא מפרישנא","l": "ע","b": "אמורא בבלי בדור החמישי. תלמידו של רבא והקשה לרבא (פסחים צ\"א ע\"א). אולי אביו הוא רב חיננא בריה דרבא מפשרוניא.","cat": "sage"},{"i": 3087,"n": "רב עוקבא בר חמא","l": "ע","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב נחמן (ב\"מ ס\"ה ע\"א). נראה, שהוא מר עוקבא בר חמא.","cat": "sage"},{"i": 3088,"n": "רב עוקבא ממישן","l": "ע","b": "אמורא בדור הששי. נראה אולי שהיה בארץ ישראל שכן מצינו (שבת ל\"ז ע\"ב) שאמר לרב אשי: \"אתון דמקרביתו לרב ושמואל וכו' [אף שפעמים \"אתון\" אינו מוכח כלום] אנו נעביד כרבי יוחנן\" (ורב ושמואל היו בבבל ורבי יוחנן היה בארץ ישראל). הרא\"ש סובר שהיה קשיש מרב אשי (שם ל\"ג ע\"ב).","cat": "sage"},{"i": 3089,"n": "עוקבן בר נחמיה","l": "ע","b": "ע\"ע נתן דצוציתא.","cat": "sage"},{"i": 3090,"n": "עוקבן הבבלי","l": "ע","b": "מובא בבבלי, ששלח מארץ ישראל לבבל למר עוקבא תלונה על אחיו ירמיה (סנהדרין ל\"א ע\"ב), ואין לקבוע אם עוקבן הבבלי או אחיו ירמיה נמנו עם החכמים.","cat": "sage"},{"i": 3091,"n": "ר' עזרא","l": "ע","b": "מובא בירושלמי (תרומות פ\"ז ה\"א), והוא ר' עזריה.","cat": "sage"},{"i": 3092,"n": "ר' עזרא בר בריה דר' אבטולס","l": "ע","b": "אמורא מיוצאי חלציו של רבי אלעזר בן עזריה, שהיה מיוצאי חלציו של עזרא. מסופר (מנחות נ\"ג ע\"א) שבא לבית מדרשו של ר' פרידה (שחי 004 שנה - עירובין נ\"ד ע\"ב). קשה לקבוע את זמנו המדוייק.","cat": "sage"},{"i": 3093,"n": "עזריה (2)","l": "ע","b": "חי בדור השני לתנאים. אביו של התנא רבי אליעזר בן עזריה. נראה, שהיה אדם גדול. לכאורה אפשר לומר שגם הוא היה תנא, שכן רבי דוסא בן הרכינס מכנהו: \"עזריה חברינו\" (יבמות ט\"ז ע\"א), אך מאידך נראה שזה רק לשון כבוד, שכן מצינו במשנה: \"שמעון אחי עזריה אומר\" (זבחים כ' ע\"א), ופרש\"י: \"על שם שעזריה עסק בפרקמטיא וסיפק צרכי שמעון אחיו בשעה שהיה עוסק בתורה והתנו ביניהן שיהא חלק לעזריה בשכר למודו של שמעון וכו', לפיכך נקרא על שמו שלמד על ידו\". ראיה ברורה יותר שלא היה תנא (סוטה כ\"א ע\"א) ופרש\"י (ד\"ה: שמעון אחי עזריה): \"תנא הוא במשנה קמייתא דזבחים שלמד תורה ע\"י אחיו שעסק בפרקמטיא כדי שיחלוק בזכות למודו של שמעון\", וא\"כ נראה יותר ששמעון היה תנא ולא הוא.","cat": "sage"},{"i": 3094,"n": "ר' עזריה","l": "ע","b": "אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. תלמידו של רבי מנא (ירו', פסחים פ\"א ה\"ח). כן מסר יחד עם יונתן בן חגי בשם ר' יצחק בר מריון (קה\"ר פ\"ט - י\"ב) ור' יוסי בר חנינא (תנחומא ראה - ט\"ז). ר' תנחומא מסר בשמו (ר\"ור פ\"ג - ו').","cat": "sage"},{"i": 3095,"n": "ר' עזריה איש כפר אונו","l": "ע","b": "מובא ב\"זוהר חדש\" (רות פ\"א).","cat": "sage"},{"i": 3096,"n": "ר' עזריה בר' סימון","l": "ע","b": "מובא ברו\"ר (פ\"ב - ז'), ואולי ט\"ס שם.","cat": "sage"},{"i": 3097,"n": "ר' עזריה דכפר חטיא","l": "ע","b": "אמורא ארץ ישראלי בדור השני. רבי אבא בר כהנא אמר משמו (ויק\"ר פ\"ז - ד').","cat": "sage"},{"i": 3098,"n": "עייא","l": "ע","b": "רבי כינה את רבי חייא: \"עייא\" (מו\"ק ט\"ז ע\"ב פרש\"י: \"כך כינו שמו של רבי חייא לשון גנאי, כי רבי הקפיד על ר' חייא שעבר על דבריו\"). גם בר קפרא כינהו כך (כריתות ח' ע\"א).","cat": "sage"},{"i": 3099,"n": "רב עילא","l": "ע","b": "אמורא בבלי בדור הרביעי. מובא בבבלי, שאביי ורבנן עלו לבקרו כשחלה (מנחות פ\"א ע\"א).","cat": "sage"},{"i": 3100,"n": "עילא בר חנינא","l": "ע","b": "מובא בבבלי (נזיר ס\"ה ע\"א), והוא עולא בר חיננא.","cat": "sage"},{"i": 3101,"n": "ר' עילאי","l": "ע","b": "מובא בבבלי (ע\"ז י\"ג ע\"ב), ו\"דק\"ס\" גרס: \"אלעאי\" (האמורא הנודע).","cat": "sage"},{"i": 3102,"n": "רב עיליש","l": "ע","b": "אמורא בבלי בדור הרביעי. נפטר לפני רבא (ב\"ב ס\"ח ע\"ב). רבא אמר עליו: \"גברא רבא\" (שם). נראה, שהיה כפוף לרבא (ב\"ב קל\"ג ע\"ב). פעם אחת הקשה לרבא ורבא איכסיף (גיטין ע\"ז ע\"ב). פעם נשבה רבי עיליש ובאותו שבי היו גם בנות רב נחמן, והוא ברח משביו (שם מ\"ה ע\"א).","cat": "sage"},{"i": 3103,"n": "רב עינא","l": "ע","b": "אמורא בבלי בדור השני. חברו של רב יהודה ושניהם מכונים \"סבי דפומבדיתא\" (סנהדרין י\"ז ע\"ב): \"איתמר רב יהודה ורב עינא, חד תני שואבה וחד תני חשובה\" (סוכה נ' ע\"ב). ומצינו: \"דרש רב עינא אפתחא דבי ריש גלותא וכו', אמר להו רבה וכו' לישמטו\" (חולין פ\"ד ע\"ב), ופרש\"י: \"יחתכו את לשונו, וכו' לביישו\". \"יוחסין\" סבר שרב עינא ורב עינא סבא (פסחים פ\"ח ע\"א) אחד הוא, לכן לא הביא את רב עינא בערך נפרד, אלא רק את רב עינא סבא.","cat": "sage"},{"i": 3104,"n": "רב עינא סבא","l": "ע","b": "אמורא בבלי בדור השלישי. מובא בבבלי, שהקשה לרב נחמן ור\"נ אמר לו: \"פתיא אוכמא\" (פסחים פ\"ח ע\"א).","cat": "sage"},{"i": 3105,"n": "עיפא בן רחבא מפומבדיתא","l": "ע","b": "אמורא בבלי בדור הרביעי. אחיו הוא אבימי, ושניהם כונו \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב). וכן ברש\"י (קידושין ל\"ט ע\"א). כן כונו \"בני רחבא\" (שבת ק\"ג ע\"א). עיפא היה תלמידו של רבה (שבועות כ\"ח ע\"ב).","cat": "sage"},{"i": 3106,"n": "רב עמרם א'","l": "ע","b": "אמורא בבלי בדור השני. תלמידו של רב (פסחים ק\"ה ע\"א). וכן קיבל מרב אסי (תלמיד חבר של רב), שמצינו: \"שלח ליה רמי בר יחזקל לרב עמרם נימא לן מר מהלין מילי מעלייתא דאמרת משמיה דרב אסי\" (עירובין ק\"ב ע\"א). היה זקן מרב נחמן ומרמי בר חמא (בכורות כ\"ז ע\"ב). ורמי בר חמא אמר לרב נחמן: \"לא לחוש מר לסבא\" (הכוונה לרב עמרם).","cat": "sage"},{"i": 3107,"n": "רב עמרם בריה דר' שמעון בר אבא","l": "ע","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. יתכן שקיבל מרבי חנינא כמובא: \"אמר רב עמרם בריה דרבי שמעון בר אבא אמר רבי חנינא\" (סנהדרין ע' ע\"א), ויתכן שנשמטו מספר מלים וצריך לומר כמובא במקום אחר: \"אמר רב עמרם בריה דרבי שמעון בר אבא אמר רבי שמעון בר אבא אמר רבי חנינא\" (שבת קי\"ט ע\"ב).","cat": "sage"},{"i": 3108,"n": "רב עמרם ב'","l": "ע","b": "אמורא בבלי בדור השלישי. חברם של רבה ורב יוסף. רבה כינהו: \"תרדא\" ופקע ארזא דבי רב (ב\"מ כ' ע\"ב). היה תלמידו של רב ששת: \"אמר רב עמרם: 'האי מילתא אמר לן רב ששת ואנהר לן עיינין' וכו' א\"ל רב יוסף וכו'\" (סוטה ו' ע\"א). רב ששת אמר לרב עמרם: \"דילמא מפומבדיתא את דמעיילין פילא בקופא דמחטא\" (ב\"מ ל\"ח ע\"ב).","cat": "sage"},{"i": 3109,"n": "רב עמרם חסידא","l": "ע","b": "אמורא בבלי בדור השני. נפטר לפני רב יוסף (ע\"ז ל\"ט ע\"א). על חסידותו מסופר שאנשי בית ריש גלותא היו מענים אותו, פרש\"י: \"מפני שהיה חסיד ופרוש, ומחמיר עליהן באיסורין\" (גיטין ס\"ז ע\"ב), וילתא אשת רב נחמן הצילתו מידם, ומעשה מופלא מסופר עליו במקום אחר (קידושין פ\"א ע\"א).","cat": "sage"},{"i": 3110,"n": "עמרם צבעא","l": "ע","b": "חי בבבל בדור השלישי לאמוראים. היה אפוטרופוס של יתומים והם באו לפני רב נחמן (גיטין נ\"ב ע\"ב). אין ראיה שהיה חכם. \"סה\"ד\" כתב: \"לא ידעתי אם חכם היה\".","cat": "sage"},{"i": 3111,"n": "רב ענן","l": "ע","b": "אמורא בבלי בדור השני. שם אביו היה רב: רב ענן בר רב (עירובין ע\"ד ע\"ב). היה תלמידו המובהק של שמואל (עירובין צ\"ה ע\"א). כן היה תלמידו של רב (ברכות ל' ע\"ב). קרא לרב הונא: \"הונא חברין\", ורב הונא הקפיד על כך (כתובות ס\"ט ע\"א). לרב נחמן קרא: \"נחמן חקלאה\" (שם ע\"א ע\"א פרש\"י: \"אינו בקי בדינין\"). אליהו הנביא היה רגיל לבוא אליו ועל פיו כתב את אליהו רבה ואליה זוטא (כתובות ק\"ו ע\"א).","cat": "sage"},{"i": 3112,"n": "רב ענן בר יוסף","l": "ע","b": "אמורא ארץ ישראלי בדור הרביעי. יחד עם רבי ברכיה ורבי חלקיה אמרו בשם רבי אידו (מד' תהלים פס\"ה - ד'). כן מצינו: \"רבי ברכיה בשם רבי ענן בר' יוסי\" (פד\"כ פ' שובה).","cat": "sage"},{"i": 3113,"n": "רב ענן בר רבא","l": "ע","b": "אמורא בבלי בדור השני. מסר בשם רב (ר\"ה ל\"א ע\"א). ואולי יש ט\"ס בשם. \"סה\"ד\" כתב: \"ס\"א רב חנן בר רבא\".","cat": "sage"},{"i": 3114,"n": "רב ענן בר תחליפא","l": "ע","b": "אמורא בבלי בדור השני. תלמידו המובהק של שמואל: \"זימנין סגיאין הוה קאימנא קמיה דשמואל\" (פסחים ק\"א ע\"א), וכן: \"לדידי מיפרשא לי מיניה דמר שמואל\" (מו\"ק י\"ח ע\"א).","cat": "sage"},{"i": 3115,"n": "רבי ענן בר' יוסי","l": "ע","b": "מובא בפד\"כ (פ' שובה), ונראה שהוא רב ענן בר יוסף.","cat": "sage"},{"i": 3116,"n": "רב ענן ר חייא","l": "ע","b": "אמורא בבלי בדור הראשון, כמובא: \"ההוא שטרא דנפיק מבי דינא דמר שמואל והוה כתיב בו, מדאתא רב ענן בר חייא וכו'\" (כתובות כ\"א ע\"א). נראה אולי, שהוא המובא בשם ענן בר חייא (יבמות קט\"ז ע\"א).","cat": "sage"},{"i": 3117,"n": "רבי ענני בר נחשון","l": "ע","b": "מובא בקה\"ר (פ\"ג - י\"א), ואולי הוא רבי אנינייא בר סיסי (ע\"ע).","cat": "sage"},{"i": 3118,"n": "רבי ענני בר ששון","l": "ע","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, שדרש אפיתחא דבי נשיא, שמע רבי אמי ואיקפד, אמר: \"אטו דידיה הוא, דרבי אלעזר אמר רב אושעיא היא\" (מו\"ק כ\"ד ע\"ב).","cat": "sage"},{"i": 3119,"n": "ר' ענניאל בר ששון","l": "ע","b": "מובא בש\"ר (פ\"ג - ו').","cat": "sage"},{"i": 3120,"n": "עקביא בן מהללאל","l": "ע","b": "מחכמי ישראל הקדומים. חי בדור החמישי ל\"זוגות\" בסמוך לחורבן הבית. ורבי יהודה אמר עליו ש\"אין העזרה ננעלת על כל אדם בישראל בחכמה ובטהרה וביראת חטא כעקביא בן מהללאל\" (ברכות י\"ט ע\"א). חלק על חכמים בארבעה דינים, והם אמרו לו \"עקביא חזור בך בארבע דברים שהיית אומר, ונעשך אב\"ד לישראל, אמר להן: מוטב להקרא שוטה כל ימי ולא לעשות שעה אחת רשע לפני המקום, שלא יהיו אומרים בשביל שררה חזר בו\" (עדיות פ\"ה מ\"ו). ומסופר (שם) שנידוהו ומת בנידויו וסקלו ב\"ד את ארונו אמר רבי יהודה חס ושלום שעקביא נתנדה וכו' בשעת פטירתו אמר לבנו חזור בד' דברים שהייתי אומר וכו'.","cat": "sage"},{"i": 3121,"n": "עקביה","l": "ע","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי, ששאל את רבי חנינא ואת רבי שמעון בן לקיש (סוטה פ\"ד ה\"ג).","cat": "sage"},{"i": 3122,"n": "רב עקביה","l": "ע","b": "אמורא בבלי בדור הרביעי. רבא אמר עליו: \"מאן חכים למיעבד כי הא מילתא אי לא רב עקביה דגברא רבה הוא\" (ע\"ז ע\"ו ע\"ב). תוספות גורסים: \"מר עוקבא\" (פסחים מ' ע\"ב ד\"ה: האילפס), ו\"מסורת הש\"ס\" תיקן: \"רב עוקבא\", וכך גם גרס התוספות במקום אחר (שבת מ\"ג ע\"ב ד\"ה אבל), וגם שם תיקן \"מסורת הש\"ס\" ל\"רב עוקבא\".","cat": "sage"},{"i": 3123,"n": "רבי עקיבא (2)","l": "ע","b": "מגדולי התנאים בכל הדורות. ראש הדור השלישי לתנאים. זמן פעילותו היה בין חורבן הבית לחורבן ביתר. חי 021 שנה (ספרי ברכות סל\"ו). \"סה\"ד\" כתב, שיש אומרים שנולד ג' תש\"ס (1 לס') ונהרג ג' תת\"פ (021). שם אביו היה יוסף (מנחות כ\"ט ע\"ב). רבי דוסא בן הרכינס אמר על ר\"ע: \"אתה הוא עקיבא בן יוסף ששמך הולך מסוף העולם ועד סופו\" (יבמות ט\"ז ע\"א). ומסופר (מנחות כ\"ט ע\"ב): \"אמר לו [הקב\"ה למשה רבנו] אדם אחד יש שעתיד להיות בסוף כמה דורות ועקיבא בן יוסף שמו, שעתיד לדרוש על כל קוץ וקוץ תילין תילין של הלכות וכו'\", אמר [משה רבנו] לפניו: \"רבש\"ע, יש לך אדם כזה ואתה נותן תורה על ידי?\" ומובא (במד\"ר פי\"ט): דברים שלא נתגלו למשה רבנו נתגלו לר\"ע. ומסופר: \"ארבעה נכנסו לפרדס [פרש\"י עלו לרקיע על ידי שם] ואלו הן: בן עזאי, בן זומא, אחר, ורבי עקיבא וכו', בן עזאי הציץ ומת, בן זומא הציץ ונפגע, אחר קצץ בנטיעות [יצא לתרבות רעה], רבי עקיבא יצא בשלום\" (חגיגה י\"ד ע\"ב). וכן: \"ואף רבי עקיבא בקשו מלאכי השרת לדוחפו, אמר להם הקב\"ה: 'הניחו לזקן זה שראוי להשתמש בכבודי'\" (שם ט\"ו ע\"ב). הרמב\"ם (בהקדמתו ל\"יד החזקה\") כתב שיוסף, אבי רבי עקיבא, היה גר צדק וכתב רב נסים גאון: \"מבני בניו של סיסרא למדו תורה וכו', ומאן אינון, רבי עקיבא\" (ברכות כ\"ז ע\"ב). עד גיל 04 לא למד דבר ולא ידע אפילו צורת אות אחת (אבות דר' נתן פ\"ו). היה רועה אצל כלבא שבוע מעשירי ירושלים, ורחל בת כלבא שבוע אמרה לו שאם ילך ללמוד תורה תתחתן עמו. לאחר שהתחתנו הדיר אותה אביה מכל נכסיו (כתובות ס\"ב ע\"ב). רבי עקיבא הלך ולמד תורה עשרים וארבע שנה (שם), וחזר לביתו עם עשרים וארבעה אלף תלמידים, ואשתו יצאה לקראתו ונשקה את רגליו, וכשדחפוה תלמידיו מעליו, אמר להם ר\"ע: 'שלי ושלכם שלה היא' (כלומר בזכות אשתו רחל שהשפיעה עליו להתחיל ללמוד והיה למה שהיה). את נחום איש גם זו, שימש עשרים ושתיים שנה (חגיגה י\"ב ע\"א). שלוש עשרה שנה שימש את רבי אליעזר (ירו', פסחים פ\"ו ה\"ג). וגם רבי יהושע היה רבו המובהק (ברכות ס\"ב ע\"א), ואח\"כ גדל רב עקיבא והיה לתלמיד - חבר לרבי אליעזר ורבי יהושע (מסכת כלה רבתי רפ\"ב): \"כיון דחזו דקא גבר עלייהו הוו להו חבריו\" (שם). גם רבי טרפון היה בתחלה רבו ואח\"כ היה לו ר\"ע לתלמיד - חבר (כתובות פ\"ד ע\"ב), ור\"ט אמר עליו \"כל הפורש ממך כפורש מן החיים\" (קידושין ס\"ו ע\"ב). יסד ישיבה גדולה בבני ברק (סנהדרין ל\"ב ע\"ב). לקח חלק בסנהדרין ביבנה, והיה אחד מארבעה שידעו 07 לשון (שם י\"ז ע\"ב). מחבריו הגדולים היו רבי אליעזר בן עזריה (חגיגה י\"ד ע\"א) ור' יוחנן בן נורי (ערכין ט\"ז ע\"ב). וחברו המובהק ביותר היה רבי ישמעאל (סנהדרין נ\"א ע\"ב). תלמידיו הגדולים היו רבי מאיר (עירובין י\"ג ע\"א), רבי יהודה (שם מ\"א ע\"א), רבי יוסי (פסחים י\"ח ע\"א), רבי שמעון בן יוחאי (מעילה ז' ע\"א) ורבי אלעזר בן שמוע (זבחים צ\"ג ע\"א). ואמרו: \"סתם מתני' רבי מאיר, סתם תוספתא רבי נחמיה, סתם סיפרא רבי יהודה, סתם ספרי רבי שמעון, וכולהו אליבא דרבי עקיבא\" (סנהדרין פ\"ו ע\"א). רבי עקיבא מוזכר 622 פעם במשנה ו - 465 פעם בתלמוד. עוד טרם החל ללמוד היו בו מידות תרומיות. הוא היה צנוע (כתובות ס\"ב ע\"ב) וירא שמים (עירובין כ\"א ע\"ב) וחסיד (שם). הוא אמר: \"מוטב אמות מיתת עצמי ולא אעבור על דעת חברי\", וכן: \"שבקה רבי עקיבא לחסידותיה\" (שם ק\"י ע\"ב). ומסופר: \"וכשהיה מתפלל בינו לבין עצמו, אדם מניחו בזוית זו ומוצאו בזוית אחרת, וכל כך למה, מפני כריעות והשתחויות\" (ברכות ל\"א ע\"א), והיה מעביר על מידותיו (תענית כ\"ה ע\"ב) ונהג לומר: \"הכל לטובה\" (ברכות ס' ע\"ב). היו לו ארבע נשים בחייו. עוד בהיותו עם הארץ התחתן, ומאשתו זו נולד לו בן והוא ובנו החלו ללמוד אלף בית (אבות דר\"נ פ\"ו). אשתו השניה היתה בתו של כלבא שבוע (כתובות ס\"ב ע\"ב). ועוד שתי נשים היו לו: אלמנתו או גרושתו של טורנוסרופוס (נדרים נ' ע\"ב) ובתו של יהושע (ידים פ\"ג מ\"ה). היו לו בנים חכמים: בנו ר' יהושע בן קרחה (לפירוש רש\"י שבועות ו' ע\"א ד\"ה: יהושע), ובנו שמעון שהוליכו לחופה (ירו', ברכות ספ\"ו) ומת בחיי ר\"ע (שמחות פ\"ח). וכן הוליך לחופה את בתו שניצלה בנס ביום חופתה (שבת קנ\"ו ע\"ב). ושם חתנו היה ר' יהושע בן כפוסאי (שבת קמ\"ז ע\"ב). בן עזאי תלמידו אירס לו לאשה את בתו (כתובות ס\"ג ע\"א). האמין בבר כוכבא ואמר עליו: \"דרך כוכב מיעקב\" (ירו' תענית פ\"ד ה\"ה). הרמב\"ם כתב בסוף ספר משפטים, כי ר\"ע היה נושא כליו של בר כוכבא. הרומאים תפסו את ר\"ע ועינוהו ביסורים נוראים והיו סורקים את בשרו במסרקות של ברזל (ברכות ס\"א ע\"ב), וכן מסופר שחתכו בשרו כמו באטליז (מנחות כ\"ט ע\"ב), והמושל הרומי טורנוסרופוס לא יכול להאמין למראה עיניו כיצד ר\"ע מקבל את היסורין בשלוה ובאהבה ושאלו: \"סבא סבא או חרש את או מבעט ביסורין\" (ירו', סוטה פ\"ה ה\"ה), וקרא \"שמע ישראל\" ונשמתו יצאה בקריאת \"ה' אחד\" ויצאה בת קול ואמרה: \"אשריך רבי עקיבא שיצאה נשמתך באחד\" (ברכות ס\"א ע\"ב). ואמרו: \"משמת רבי עקיבא, בטל כבוד התורה\" (סוטה מ\"ט ע\"א), (ושם ע\"ב): \"משמת ר\"ע, בוטלו זרועי תורה ונסתתמו מעיינות החכמה\".","cat": "sage"},{"i": 3124,"n": "ר' עקיבא בן דוסא","l": "ע","b": "\"סה\"ד\" כתב: \"בזמן רבי מאיר, כ\"כ ב'אגרת רב שרירא גאון'\"; וא\"כ, היה תנא בדור הרביעי.","cat": "sage"},{"i": 3125,"n": "רבי עקיבא בר אחא","l": "ע","b": "מובא בירושלמי (יבמות פט\"ז ה\"ה), ואולי יש ט\"ס בשם.","cat": "sage"},{"i": 3126,"n": "ר' עקיבא בר זבדי","l": "ע","b": "אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי אבהו (\"ילקוט\" אמור רמז תרמ\"ב).","cat": "sage"},{"i": 3127,"n": "רבי עקיבא ברבי חנינא","l": "ע","b": "תנא מובא בבבלי, שרב אחא מסר משמו (מנחות ל\"ב ע\"ב). יתכן, שתנא בשם זה לא היה ולא נברא; \"שיטה מקובצת\" מחק \"עקיבא\" וגרס: \"רבי יעקב ברבי חנינא\", וכן ציין \"מסה\"ש\", וכן הגירסא במקום אחר: \"רבי אחא מכשיר משום אחי בר חנינא, ואמרי לה משום רבי יעקב בר חנינא\" (שבת ע\"ט ע\"ב), וכן גרס \"סה\"ד\" (ואילו לא גדולי עולם גרסו כשם שגרסו, מי יערוב לידנו שלא צריך לגרוס ההיפך גם במסכת שבת כמו במנחות, כלומר, רבי עקיבא ברבי חנינא, ולא רבי יעקב בר' חנינא בשני המקומות, שכן שמות שני תנאים אלה לא נמצאו בש\"ס?)","cat": "sage"},{"i": 3128,"n": "רבי עקיבה בן יוסף","l": "ע","b": "הוא רבי עקיבא.","cat": "sage"},{"i": 3129,"n": "עקילס","l": "ע","b": "ע\"ע אונקלוס.","cat": "sage"},{"i": 3130,"n": "עקילס הגר","l": "ע","b": "ע\"ע אונקלוס.","cat": "sage"},{"i": 3131,"n": "רב פדא","l": "פ","b": "הוא בר פדא.","cat": "sage"},{"i": 3132,"n": "ר' פדא","l": "פ","b": "מובא בבבלי (קידושין י\"ז ע\"ב). וכן: \"א\"ר יהודה בריה דרבי חייא וכו', שמעה אילפא אמרה קמיה דרב פדא\" (זבחים י\"ג ע\"ב) ואולי צ\"ל: בר פדא.","cat": "sage"},{"i": 3133,"n": "ר' פדיה","l": "פ","b": "הוא בר פדא.","cat": "sage"},{"i": 3134,"n": "רבי פדת","l": "פ","b": "ע\"ע רבי פדת הזקן או רבי פדת בנו של רבי אלעזר.","cat": "sage"},{"i": 3135,"n": "רבי פדת בנו של רבי אלעזר","l": "פ","b": "אמורא ארץ ישראלי בדור השלישי. בנו ותלמידו רבי אלעזר בן פדת (מו\"ק כ' ע\"א). שימש בתפקיד \"אמורא\" אצל רבי אסי (ירו', מגילה פ\"ד ה\"י). ר\"ז היה כמו חברו (נדה ח' ע\"א). רבי ירמיה מסר משמו (ירו', יומא פ\"ד ה\"ו).","cat": "sage"},{"i": 3136,"n": "רבי פדת הזקן","l": "פ","b": "חי בסוף תקופת התנאים או בתחילת תקופת האמוראים בארץ ישראל. \"יוחסין\" כתב בסדר הקבלה עם הגהות הרמ\"א: \"רבי פדת חברו של רבי, ורבי אלעזר בן פדת בנו, ורבי פדת בן אלעזר נכדו\". ומובא, שר' אלעזר בר' שמעון אמר עליו דצדיק גמור הוא (\"תיקוני זוהר\" ס\"ט), וכן מובא (\"אגרת רב שרירא גאון\"): ר' פדת קמאי בדור שלפני רבי. מובא בירושלמי, שרבי יהושע בן לוי מסר משמו (פ\"י הי\"ב).","cat": "sage"},{"i": 3137,"n": "פוגא","l": "פ","b": "שמשו של רבי יוסי בר חנינא (ב\"ב צ' ע\"ב), ואין לדעת אם היה מן החכמים. היו שמשים של אמוראים שהיו חכמים מובהקים, אך יתכן שמש שלא היה חכם כלל.","cat": "sage"},{"i": 3138,"n": "פזי","l": "פ","b": "השם \"פזי\" שימש כשם גבר וכשם אשה. מצינו פזי בדור החמישי לתנאים (תוספתא אהלות פי\"ח): \"מעשה ברבי ורבי ישמעאל ברבי יוסי ורבי אלעזר הקפר ששבתו בחנותו של פזי בלוד\" (ויש גירסאות בחנותו של כותי). ויש \"פזי\" אשה, בתו של רבי חייא, אחות תאומה לטוי, שילדה לו אשתו יהודית (יבמות ס\"ה ע\"ב). ומצינו: \"ר' שמעון בן פזי\" (מגילה י\"ג ע\"א), אך תוספות כתבו (ב\"ב קמ\"ט ע\"א ד\"ה: רב) שפזי שם אמו של רבי שמעון בן פזי (ז\"א שם אשה). ומצינו: \"רבי יודה בן פזי\" (ירו', ביצה פ\"ד ה\"ד). ומצינו מפורש שפזי הוא שם גבר: \"רבי יודה בן פזי בשם רבי פזי בשם רבי יוחנן\" (ירו', סנהדרין פ\"ב ה\"ג).","cat": "sage"},{"i": 3139,"n": "רבי פטרוקי אחוה דרבי דרוסא","l": "פ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (יומא פ\"ד ה\"ד).","cat": "sage"},{"i": 3140,"n": "רבי פילא","l": "פ","b": "אמורא ארץ ישראלי בדור הראשון. מובא בש\"ר (רפכ\"ד - ה'), שאמר רבי תחליפא דקסרין משמו.","cat": "sage"},{"i": 3141,"n": "פיליפא בר ר' פריט","l": "פ","b": "מובא במסכת סופרים (פכ\"א), והוא רבי פליפה בר פרוטה.","cat": "sage"},{"i": 3142,"n": "פישון הגמל","l": "פ","b": "מובא בבבלי: \"תניא, אמרו להן בית הלל לבית שמאי: 'והלא פישון הגמל מיאנה אשתו שלא בפניו' אמרו להן בית שמאי לבית הלל: 'פישון הגמל וכו'\" (יבמות ק\"ז ע\"ב). אין לדעת אם נמנה עם החכמים.","cat": "sage"},{"i": 3143,"n": "פלטון איש רומי","l": "פ","b": "מובא (במדרש תהלים כ\"ח - ב'), ונראה שהוא פלטיון איש רומי.","cat": "sage"},{"i": 3144,"n": "ר' פלטיא דנוה","l": "פ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בקה\"ר (פ\"א - ה') שר' שמואל אמר בשמו.","cat": "sage"},{"i": 3145,"n": "פלטיון איש רומי","l": "פ","b": "מובא (שהש\"ר פ\"ח - ה'). נראה, שהוא פלטון איש רומי.","cat": "sage"},{"i": 3146,"n": "פלימו","l": "פ","b": "תנא בדור החמישי. שאל מרבי: \"מי שיש לו שני ראשין וכו'\" (מנחות ל\"ז ע\"א), ורבי הקפיד עליו ורצה להענישו בחשבו שדרך שחוק שאל, אדהכי בא אדם ואמר לרבי שנולד לו תינוק בעל שני ראשים. ומסופר: \"פלימו אומר: 'אני ראיתי אותו בית'\" [שרבי חנינא בן דוסא עשה בו נס] (תענית כ\"ה ע\"א). היה מופלג בחסידות ובפרישות והתגרה בשטן (קידושין פ\"א ע\"א).","cat": "sage"},{"i": 3147,"n": "רבי פליפא בר פרוטה","l": "פ","b": "מובא בירושלמי (מגילה פ\"א ה\"א), והוא פליפה בר פריטה.","cat": "sage"},{"i": 3148,"n": "רבי פליפה בר פרוטה","l": "פ","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי זירא (ירו', תענית פ\"ד ה\"ג). קיבל גם מרבי יונה (ירו', מגילה פ\"א ה\"א). שמו שובש כמה פנים: פיליפא בר ר' פריט (מס' סופרים פכ\"א), ר' פליפא בר פרוטה (ירושלמי שם). \"סה\"ד\" כתב, שמה שמצינו (ב\"ר פע\"א - ט'): \"א\"ל ר' פליפי בר נהוראי\" צ\"ל: \"א\"ל ר' פליפי לרבי נהוראי\" (והוא ר' פליפה בר פרוטה).","cat": "sage"},{"i": 3149,"n": "ר' פליפי בר נהוראי","l": "פ","b": "מובא בב\"ר (פע\"א - ט'). \"סה\"ד\" גורס: א\"ל ר' פליפי לר' נהוראי. ע\"ע רבי פליפה בר פרוטה.","cat": "sage"},{"i": 3150,"n": "ר' פנדא","l": "פ","b": "מובא בבבלי: \"א\"ר ביזנא בר זבדא א\"ר עקיבא א\"ר פנדא א\"ר נחום אמר רבי בירים משום זקן אחד, ומנו ר' בנאה\" (ברכות נ\"ה ע\"ב); (ואם אין ט\"ס, הרי שלא ידעתי מיהו ר' פנדא זה). \"דק\"ס\" מביא כמה גירסאות: ר' פבנא ור' פרנא.","cat": "sage"},{"i": 3151,"n": "פנחס","l": "פ","b": "ע\"ע פנחס בר אבא (אחיו של שמואל).","cat": "sage"},{"i": 3152,"n": "רב פנחס","l": "פ","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (שבת מ\"ו ע\"ב). תירץ דברי רב פפא (שבועות כ\"ב ע\"א). רב אשי הקשה על דבריו (מו\"ק י\"ד ע\"ב).","cat": "sage"},{"i": 3153,"n": "רבי פנחס","l": "פ","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (שהיה חברו של רבי יונה) (ירו', פסחים פ\"ה ה\"ג). חברם של רב הונא ב' ור' חזקיה (ירו', פאה פ\"ג ה\"ז). יש מדרשים מר' פנחס בר חמא שנאמרו בשם ר' פנחס סתם.","cat": "sage"},{"i": 3154,"n": "פנחס אחוה דמר שמואל","l": "פ","b": "מובא בבבלי (בכורות ל\"ז ע\"א). ע\"ע פנחס בר אבא.","cat": "sage"},{"i": 3155,"n": "רבי פנחס בי ר' חנינא","l": "פ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (שקלים פ\"ב ה\"א), שחלק עם ר' אבא מרי.","cat": "sage"},{"i": 3156,"n": "רבי פנחס בן יאיר","l": "פ","b": "תנא בדור החמישי. מקומו בלוד (תוספתא סוף אהלות). חתנו של רבי שמעון בן יוחאי (שבת ל\"ג ע\"ב). קודם שישב רבי שמעון בן יוחאי במערה, היה ר' פנחס בן יאיר מתרץ את קושיות רשב\"י, ולאחר שיצא רשב\"י מהמערה, היה רשב\"י מתרץ בעשרים וארבעה תירוצים את קושיות ר' פנחס בן יאיר (שם). היה חברו של רבי (חולין ז' ע\"ב), וכשראה פרדות לבנות בביתו של רבי סירב לאכול אצלו, ואמר: \"מלאך המות בביתו של זה ואני אסעד אצלו?\" (שם). היה מופלג בחסידות ובפרישות. מימיו לא נהנה משל אחרים. ומיום שעמד על דעתו לא נהנה מסעודת אביו (שם). היה זהיר ביותר במצוות מעשר, ומסופר שאפילו חמורו סירב לאכול תבואה בלתי מעושרת (שם). היה מלומד בנסים, וכשהלך למצות פדיון שבויים, נבקעו מי הנהר לפניו (שם ע\"א). בירושלמי מסופרים עליו נסים רבים. וממנו מאמר: \"א\"ר פנחס בן יאיר תורה מביאה לידי זהירות, זהירות מביאה לידי זריזות, זריזות מביאה לידי נקיות, נקיות מביאה לידי פרישות, פרישות מביאה לידי טהרה, טהרה מביאה לידי קדושה, קדושה מביאה לידי ענוה, ענוה מביאה לידי יראת חטא, יראת חטא מביאה לידי חסידות, חסידות מביאה לידי רוח הקודש רוח הקודש מביאה לידי תחית המתים\" (ע\"ז כ' ע\"ב). בעל \"מסילת ישרים\" (רמח\"ל) ביסס את ספרו על מאמר זה. מקום קבורתו בצפת. \"סה\"ד\" כתב: \"קבורתו בכפר ברעם\".","cat": "sage"},{"i": 3157,"n": "ר' פנחס בן לוי","l": "פ","b": "מובא בירושלמי (שקלים פ\"ב).","cat": "sage"},{"i": 3158,"n": "רבי פנחס בן ערובה","l": "פ","b": "תנא בדור השני. מובא בבבלי \"אני הייתי בין גדולי רומי וכשמת טיטוס [הרשע שהחריב את בית המקדש] פצעו את מוחו ומצאו יתוש כצפור דרור משקל ב' סלעים\" (גיטין נ\"ו ע\"ב). רבי יוחנן (האמורא) אמר משמו (בכורות ל\"ח ע\"ב).","cat": "sage"},{"i": 3159,"n": "רב פנחס בן רב חסדא","l": "פ","b": "אמורא בבלי בדור הרביעי. גיסו של רבא. מסופר שהיה בחתונת בנו של רבא יחד עם אחיו רב מרי (קידושין ל\"ב ע\"ב). זכה לגילוי אליהו (כתובות ס\"א ע\"א).","cat": "sage"},{"i": 3160,"n": "פנחס בר אבא","l": "פ","b": "אמורא בבלי בדור הראשון. אחיו של שמואל (חברו של רב). ושאל משמואל שאלה שלא ידע להשיב עליה (בכורות ל\"ט ע\"א): קרי שמואל עליה \"פוסחים בזזו\" פרש\"י: \"כלומר, אתה אינך מחודד ושאלת שאלה כזו שאיני יודע תשובה\". הוא ושמואל נשאו אחיות לנשים (סנהדרין כ\"ח ע\"ב). שמואל הלך לבקר את פנחס אחיו כשהיה אבל, ובגלל פליטת פיו של פנחס נעשה גם שמואל אבל (מו\"ק י\"ח ע\"א).","cat": "sage"},{"i": 3161,"n": "ר' פנחס בר אבין","l": "פ","b": "מובא במ\"ר (פי\"א).","cat": "sage"},{"i": 3162,"n": "ר' פנחס בר אידי","l": "פ","b": "מובא מ\"ר (פ\"א - י\"א).","cat": "sage"},{"i": 3163,"n": "ר' פנחס בר זבאי","l": "פ","b": "מובא בירושלמי (מו\"ק פ\"ב ה\"א).","cat": "sage"},{"i": 3164,"n": "ר' פנחס בר חייא הכהן","l": "פ","b": "מובא בתנחומא (נ\"ח - ה'), וכנראה שצ\"ל: ר' פנחס בר חמא (מ' הפך לשני יודים) הכהן.","cat": "sage"},{"i": 3165,"n": "רב פנחס בר חמא הכהן","l": "פ","b": "אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מוזכר הרבה במדרשים. פעמים מובא כסתם רבי פנחס או רבי פנחס הכהן. קיבל מגדולי דורו ומסר מדורות שלפניו, מרבי יוחנן (ירו', ברכות פ\"ב ה\"א) ומרבי שמעון בן לקיש (ירו', שקלים פ\"ו ה\"א). האומרים בשמו: ר' יוחנן דיפו (מ\"ר פכ\"ב - כ\"ד) ור' יהודה נשיאה ג' (רו\"ר ספ\"ה). היה לו אח ושמו ר' שמואל, שמת בחייו (מד' שמואל פ\"ט - ג').","cat": "sage"},{"i": 3166,"n": "ר' פנחס בר ראובן","l": "פ","b": "\"סה\"ד\" כתב: \"ובילקוט ר' פנחס בר' ראובן ט\"ס וצ\"ל: בש\"ר ראובן (ר' פנחס בשם ר' ראובן)\".","cat": "sage"},{"i": 3167,"n": "רב פנחס בריה דרב אמי","l": "פ","b": "אמורא בבלי בדור החמישי. חברם הגדול של רב פפא ורב הונא בריה דרב יהושע (כתובות פ\"ה ע\"א). מרבותיו של רב אשי (זבחים ז' ע\"ב). ומצינו: \"מרימר, ואיתימא רב יימר, איקלע לפרקיה דרב פנחס בריה דרב אמי, וקם תנא ותני קמיה\" (כתובות ק' ע\"א).","cat": "sage"},{"i": 3168,"n": "רב פנחס בריה דרב מרי","l": "פ","b": "מובא בבבלי (זבחים צ' ע\"ב), וגירסת \"דק\"ס\": \"בריה דרב אמי\".","cat": "sage"},{"i": 3169,"n": "ר' פנחס בריה דר' שמעון","l": "פ","b": "מובא ב\"ילקוט\" (רות רמז תר\"ה), אבל הגירסא ברו\"ר (סוף פ\"ו): ר' פנחס בר חמא.","cat": "sage"},{"i": 3170,"n": "ר' פנחס דדהובא","l": "פ","b": "מובא בקה\"ר (פ\"ב - ב'): \"א\"ר פנחס דדהובא מערבב וכו'\". ו\"סה\"ד\" כתב: \"אל יטעך לבך דשם מקום הוא כי ט\"ס הוא, וצ\"ל: דחוכה מערבב וכו'\" (כלומר אמר ר' פנחס, דחוכה מערבב וכו').","cat": "sage"},{"i": 3171,"n": "ר' פנחס דיפו","l": "פ","b": "מובא בירושלמי (פסחים פ\"א ה\"א).","cat": "sage"},{"i": 3172,"n": "ר' פנחס החבר","l": "פ","b": "אמורא ארץ ישראלי בדור החמישי. מובא בש\"ר (פ\"א - י\"ד) שמסר בשם רבי יונה.","cat": "sage"},{"i": 3173,"n": "ר' פנחס צפוראה","l": "פ","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי, שר' פנחס מסר משמו (יומא ע\"ז ע\"ב). כך גירסת \"דק\"ס\" ו\"יוחסין\". ו\"סה\"ד\" כתב: \"לא מצאתי זכרו\". ולפנינו: רב הונא צפוראה.","cat": "sage"},{"i": 3174,"n": "פנימין","l": "פ","b": "מובא בילקוט המכירי (תהלים פכ\"ה - י\"ד), ואולי צ\"ל מינימון (כמו בירו', סוטה פ\"א ה\"ב).","cat": "sage"},{"i": 3175,"n": "רבי פס","l": "פ","b": "מובא בירושלמי (קדושין פ\"ג ה\"ה), והוא רבי אפס.","cat": "sage"},{"i": 3176,"n": "רב פפא","l": "פ","b": "מגדולי אמוראי בבל בדור החמישי. תלמידם המובהק של אביי (פסחים קי\"א ע\"ב) ורבא (כתובות פ\"ה ע\"א). והיה תלמיד כל כך מובהק לרבא, עד שאמרו תוספות (שבת כ\"ז ע\"ב) שהתלמידים לא ידעו אם רב פפא אמר משם עצמו או משם רבו רבא. ולאחר פטירתו של רבא, כשנחלקה ישיבת מחוזא לשנים, מלך רב נחמן בר יצחק בפומבדיתא, ורב פפא מלך תשע עשרה שנה בנרש (\"אגרת רב שרירא גאון\") וחברו המובהק: רב הונא בריה דרב יהושע שימש על ידו כראש כלה (ברכות נ\"ז ע\"א, \"אגרת רב שרירא גאון\"), ושניהם הגיעו להוראה עוד בחיי רבא (ב\"ב ק\"ל ע\"ב). היו לו תלמידים רבים, ביניהם מאתיים מתלמידיו שהיו מאוכלי שולחנו (כתובות ק\"ו ע\"א). בין תלמידיו היה רב אשי (ע\"ז מ' ע\"א). רבינא הקשה לרב פפא (ב\"מ ע\"ד ע\"ב). התנהג לפנים משורת הדין (כתובות צ\"ז ע\"א). על בנו אבא העיד רב פפא, שמעולם לא הוציא דבר שקר מפיו (כתובות פ\"ה ע\"א). היה עשיר גדול (ב\"מ מ\"ו ע\"א). בתחילה היה עני (הוריות ו' ע\"ב) התעשר מעשיית שכר (פסחים קי\"ג ע\"א). אשתו היתה כהנת ותלה את עושרו בזכותה (שם מ\"ט ע\"א). שם אביו של רב פפא לא מוזכר בש\"ס, ולפי דעת ה\"ערוך\" (ערך בר) היה שם אמו אושפרתי (תענית כ\"ד ע\"ב). פעם אחת גבר על רבו אביי והקפיד עליו אביי, ואמר: \"כמדומה אני שיש לך אב ואם סמוכין לך לספק צרכיך לפיכך אתה חריף מדי\", והענישם ומתו הוריו. ואחר פטירתו של רב פפא מלך רב אשי (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 3177,"n": "רב פפא בר אבא","l": "פ","b": "אמורא בבלי בדור החמישי. היה בימיו של רב פפא, שאמר כגון: \"כלתיה דבי רב פפא בר אבא\" (יבמות כ\"א ע\"ב). היו לו בנים חכמים ושאלו מרב פפא (שבת קי\"ט ע\"א).","cat": "sage"},{"i": 3178,"n": "רב פפא בר אבא רישבא","l": "פ","b": "אמורא בדור הרביעי. מובא בבבלי, ששאל מרבי אבא (חולין נ\"ד ע\"א). \"סה\"ד\" כתב: \"וה'יוחסין' לא הביאו, כמדומה, שלא היה חכם. וצריך לומר: דבי פפא בר אבא רישבא ולא רב פפא\".","cat": "sage"},{"i": 3179,"n": "רב פפא בר יעקב","l": "פ","b": "מובא בבבלי (חגיגה י\"ד ע\"א). גירסת \"עין יעקב\": רב אחא בר יעקב. מובא ב\"ילקוט\" (ישעיה רמז ס\"ג).","cat": "sage"},{"i": 3180,"n": "רב פפא בר שמואל","l": "פ","b": "אמורא בבלי בדור הרביעי. תלמידם של רב ששת (כתובות ל\"ז ע\"א) ורב חסדא (שבת נ\"ד ע\"ב). תירץ קושית רב חסדא (פסחים מ\"ז ע\"ב). היה ראש הדיינים בפומבדיתא: \"דייני דפומבדיתא - רב פפא בר שמואל\" (סנהדרין י\"ז ע\"ב). רבא היה חברו (ר\"ה י\"ז ע\"א), ועל ספורי נפלאותיו של רבה בר בר חנה אמר, שאילולי היה שם לא היה מאמין (ב\"ב ע\"ג ע\"ב).","cat": "sage"},{"i": 3181,"n": "רב פפא בריה דרב אחא בר אדא","l": "פ","b": "אמורא בבלי בדור הרביעי - החמישי. מסר בשם אביו ששמע מרב (ברכות כ\"ט ע\"ב). אמר לאביי (לגירסת השאלתות): \"הכי אמרינן משמיה דרבא\" (סנהדרין כ\"ט ע\"ב). רבא התקיף לה על מימרא שאמר (עירובין כ\"א ע\"ב).","cat": "sage"},{"i": 3182,"n": "רב פפא בריה דרב חנין (2)","l": "פ","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (מנחות כ\"ח ע\"ב). רב יוסף אמר לו: \"סמי דידך מקמי דידי וכו'\".","cat": "sage"},{"i": 3183,"n": "רב פפא בריה דרב חנן מבי כלוחית","l": "פ","b": "אמורא בבלי בדור הששי. נראה, שהיה תלמידו של רב שימי בר אשי (כתובות מ' ע\"ב). \"סה\"ד\" איחד את רב פפא בריה דרב חנן מבי כלוחית עם רב פפא בריה דרב חנין לאחד.","cat": "sage"},{"i": 3184,"n": "רב פפא בריה דרב יוסף","l": "פ","b": "אמורא בבלי בדור הרביעי. בנו ותלמידו של רב יוסף. מובא בבבלי, שתירגם לפני אביו (ב\"מ קי\"ג ע\"ב).","cat": "sage"},{"i": 3185,"n": "רב פפא בריה דרב נחמן","l": "פ","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף, ותירגם לפני רב נחמן (ב\"מ קי\"ג ע\"א).","cat": "sage"},{"i": 3186,"n": "רב פפא סבא","l": "פ","b": "אמורא בבלי בדור השני. תלמידו של רב (קידושין מ\"ט ע\"ב). \"סה\"ד\" כתב שהיו לו י\"א בנים: דארו, סורחב, רכיש, רפרם, אבא, אחא, רמי, חנינא, אבא מרי, נחמן, אדא. \"יוחסין\" כתב, \"שקיבל מאביו שקיבל מחכמים וזקנים שמועילים לשכחה ויאמרו אותם ז' פעמים\". ספר \"האשכול\" כתב, שי\"א בני רב פפא אינם מרב פפא אחד, אלא היו בזמנים שונים ויש לו קבלה שמועילים לשכחה, ועל כן נהגו להזכירם כשמסיימים מסכתא.","cat": "sage"},{"i": 3187,"n": "פפא תוראה","l": "פ","b": "חי בבבל בדור החמישי לאמוראים: \"אורי ליה רב פפא לפפא תוראה\" (גיטין י\"ט ע\"א), ופרש\"י: \"ספסר של שוורים\". נראה לומר, שלא נמנה עם החכמים. \"יוחסין\" ו\"סה\"ד\" לא הביאו שמו.","cat": "sage"},{"i": 3188,"n": "פפוס","l": "פ","b": "ע\"ע ליליינוס ופפוס.","cat": "sage"},{"i": 3189,"n": "פפוס בן יהודה","l": "פ","b": "תנא בדור השלישי. חברו של רבי עקיבא. כשמצא את רבי עקיבא מקהיל קהילות ברבים ועוסק בתורה אמר לו עקיבא: \"אי אתה מתירא מפני המלכות\", לבסוף נתפסו שניהם, ואמר פפוס בן יהודה לרבי עקיבא: \"אשריך ר\"ע שנתפסת על דברי תורה, אוי לו לפפוס שנתפס על דברים בטלים\" (ברכות ס\"א ע\"ב). ומצינו: \"דריש פפוס וכו' א\"ל: 'ר\"ע דייך פפוס'\" (מכילתא פ' בשלח).","cat": "sage"},{"i": 3190,"n": "רב פפי","l": "פ","b": "אמורא בבלי בדור החמישי. תלמידו של רבא (פסחים ז' ע\"א). חברו של רב פפא ורב הונא בריה דרב יהושע, ושקיל וטרי עמם (כתובות ס' ע\"ב). היה חברו של רב ביבי בר אביי (יבמות ע\"ה סע\"ב). רב אשי היה תלמידו (ר\"ה כ\"ט ע\"ב). נראה, שגם רבינא קיבל ממנו (ב\"מ נ\"ד ע\"ב). היה חתנו של רבי יצחק נפחא (חולין ק\"י ע\"א).","cat": "sage"},{"i": 3191,"n": "רבי פפייס","l": "פ","b": "תנא בדור השני. העיד יחד עם רבי יהושע [רבו של רבי עקיבא]. (עדיות פ\"ז מ\"ו). סיפר מעשה מימי הבית (שם).","cat": "sage"},{"i": 3192,"n": "רבי פרוזדק","l": "פ","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם רבי יהודה בר סימון (מד' תהלים רפצ\"א).","cat": "sage"},{"i": 3193,"n": "ר' פרורי","l": "פ","b": "מובא בירושלמי (פאה פ\"ז ה\"ג), והוא רבי פרידא.","cat": "sage"},{"i": 3194,"n": "ר' פרחיה","l": "פ","b": "מובא ב\"זוהר\" (חדש רות).","cat": "sage"},{"i": 3195,"n": "רבי פרטא","l": "פ","b": "תנא בדור הרביעי - החמישי. חי בימי רבי ודן עמו בהלכה, ואמר לו \"א\"כ מה כח ב\"ד יפה\" (כתובות ק' ע\"א). נכדו של רבי פרטא הגדול (שם).","cat": "sage"},{"i": 3196,"n": "ר' פרטא בנו של ר\"א בן פרטא","l": "פ","b": "ע\"ע רבי פרטא הגדול.","cat": "sage"},{"i": 3197,"n": "רבי פרטא הגדול","l": "פ","b": "תנא בדור הראשון - השני. מובא בבבלי (כתובות ק' ע\"א). בנו רבי אליעזר בן פרתא, שהיה חברו של ר' חנינא בן תרדיון. ונכדו רבי פרטא, חי בזמן רבי (ע\"ע ר' פרטא בנו של ר\"א בן פרטא).","cat": "sage"},{"i": 3198,"n": "ר' פריגורי דקיסרין","l": "פ","b": "אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (תרומות פי\"א ה\"ב).","cat": "sage"},{"i": 3199,"n": "רבי פרידא","l": "פ","b": "אין לקבוע את זמנו המדוייק ואם היה תנא או אמורא. מובא בבבלי, שהוסיפו לו 004 שנות חיים על שחזר עם תלמידו 004 פעם את לימודו (עירובין נ\"ד ע\"ב). הרמב\"ם כתב בהקדמה לפי' המשניות שר' פרידא נולד קודם לחורבן. מצינו שהיה בימי רבי (ירו', פאה פ\"ז ה\"ג), וכן מצינו שהיה בימי רבי אמי ושאל ממנו (מנחות נ\"ב ע\"ב), ראה את ר' עזרא בר בריה דר' אבטילס שהיה דור עשירי לר' אלעזר בן עזריה (שם נ\"ג ע\"א).","cat": "sage"},{"i": 3200,"n": "רבי פרירא","l": "פ","b": "כן גירסת \"סה\"ד\" מירושלמי (פאה פ\"ז ה\"ג), ולפנינו \"רבי פרידא\".","cat": "sage"},{"i": 3201,"n": "רבי פרנק","l": "פ","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (שבת י\"ד ע\"א). מסר גם בשם רבי חנינא (ירו', פסחים פ\"ה ה\"ז). מצינו: \"אמר רבי פרנק אמר רבי יוחנן: 'כל שהוא תלמיד חכם ובנו תלמיד חכם ובן בנו תלמיד חכם, שוב אין תורה פוסקת מזרעו לעולם'\" (ב\"מ פ\"ה ע\"א).","cat": "sage"},{"i": 3202,"n": "פשפשה","l": "פ","b": "מובא בירושלמי: \"פשפשה א\"ר יוסי: שאלית לרבי אחא ושרא וכו'\" (שבועות פ\"ו ה\"א). בפשטות משמע, שהיה פשפשה אמורא בדור החמישי, והיה תלמידו של רבי יוסי (חברו של ר' יונה). \"פני משה\" פירש, שפשפשה שם איש ששאל לר' אחא ושרא ליה, ואם כן, לדעתו נמנה עם החכמים. הספר \"אהבת ציון\" מפרש: \"פשפשה הוא כמו שצריכין לבדוק ואינו שם איש\".","cat": "sage"},{"i": 3203,"n": "רבי צדוק","l": "צ","b": "תנא בדור הראשון. ישב ארבעים שנה בתענית שלא תחרב ירושלים (גיטין נ\"ו ע\"א). רבי יוחנן בן זכאי ביקש מאספסינוס שירפאו את ר' צדוק (שם). ורבי יוחנן בן זכאי קם לפניו (איכ\"ר פ\"א - ה'). עליו מסופר: \"מעשה בשני כהנים וכו' עמד רבי צדוק על מעלות האולם ואמר וכו'\" (יומא כ\"ג ע\"א). היה חברם של ר\"א ור' יהושע, ואמר להם: \"עד מתי אתם מניחים כבודו של מקום\" (קידושין ל\"ב ע\"ב). כשהורידו את ר\"ג מנשיאותו אמרו: \"אשתקד צעריה בבכורות במעשה דר' צדוק\" (ברכות כ\"ז ע\"ב). בנו הוא ר\"א בר' צדוק.","cat": "sage"},{"i": 3204,"n": "ר' צדוק בן חלוקה","l": "צ","b": "אמורא ארץ ישראלי בדור הראשון. תלמידו של רבי יוסי בן זמרא: \"אמר רבה בר בר חנא: שאלו את רבי אלעזר (בן פדת) וכו'\", \"עמד ר' צדוק בן חלוקה על רגליו ואמר: אני ראיתי את ר' יוסי בן זמרא שזקן ויושב בישיבה היה וכו'\" (יומא ע\"ח ע\"א).","cat": "sage"},{"i": 3205,"n": "רבי קורייס","l": "ק","b": "מובא בירושלמי (ערלה פ\"ב ה\"ב).","cat": "sage"},{"i": 3206,"n": "רב קטינא","l": "ק","b": "אמורא בבלי בדור השני. מתלמידי ריש לקיש (בכורות מ\"ד ע\"ב). אולי היה זמן - מה בארץ ישראל. מרבותיו של רב חסדא (ב\"מ ע\"ט ע\"א). מצינו: \"אמר ליה רב מרדכי לרבא: 'יתיב רק קטינא תיובתא'\" (שבת נ' ע\"ב). יש ממנו כמה מאמרי אגדה בש\"ס. היה מופלג בחסידות וזכה לגילוי מלאכים ואף דיבר עמם בדברי הלכה (מנחות מ\"א ע\"א). מסופרות נפלאות נוספות עליו (ברכות כ\"ט ע\"א). גם בנו רב דניאל בר קטינה היה מופלג בחסידות ובעל מופת (תענית ט' ע\"ב).","cat": "sage"},{"i": 3207,"n": "ר' קיסמא בן גירי","l": "ק","b": "\"מובא בזוהר\" (חדש רות צ\"ו) יחד עם רב רחומי (שלשה רב רחומי היו: א' בדור הרביעי, ב' בדור השביעי וג' בדור השמיני ואף נמנה על הסבוראים).","cat": "sage"},{"i": 3208,"n": "ר' קיריס דאירמא","l": "ק","b": "מובא בירושלמי (ביצה פ\"ג ה\"ח). מאמרו: \"מי שיש בידו למחות ואינו מוחה, קלקלה תלויה בו\". ואותו מאמר מובא בירושלמי בשם רבי קיריס דידמא (שבת ספ\"ה) והוא ר' קיריס דאירמא.","cat": "sage"},{"i": 3209,"n": "ר' קיריס דידמא","l": "ק","b": "מובא בירושלמי (שבת ספ\"ה) והוא ר' קיריס דאירמא.","cat": "sage"},{"i": 3210,"n": "קלא","l": "ק","b": "חי בדור השלישי - הרביעי לאמוראים. \"וכן אורי ליה ר' אבא לקלא: 'הלכה כר' יוסי'\" (נדה נ\"ט ע\"ב). התוספות כתבו: \"נראה דקלא שם חכם\", ורש\"י כתב: \"שם אדם שהוצרך לדבר\". נראה לי, שרש\"י לא סבר שהוא חכם, שכן כשהשם הוא של חכם הוא נוהג לכתוב זאת כגון \"ניולי - שם חכם\" (חולין מ\"ה ע\"ב). \"בריבי שם חכם\" (שם נ\"ב ע\"ב); \"מבוג שם חכם\" (זבחים ט' ע\"ב); \"בר קזא - שם חכם\" (כתובות ק\"ד ע\"א); \"איו - שם חכם\" (עירובין ל\"ו ע\"ב); \"בלווטי - שם חכם\" (ערכין י\"א ע\"א); ואמנם מצינו שרש\"י כתב \"טבי - שם האיש\" (שבת י\"ז ע\"ב) והוא היה החכם טבי רישבא תלמידו דשמואל.","cat": "sage"},{"i": 3211,"n": "ר' קצרה","l": "ק","b": "אמורא ארץ ישראלי בדור השני. מובא בתנחומא (ויחי) שהלך עם רבי אלעזר ליד טבריה.","cat": "sage"},{"i": 3212,"n": "רבי קרוספאי","l": "ק","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (כריתות כ\"ד ע\"א). מסר גם בשם ריש לקיש (ירו', יבמות רפ\"א). בשמו מסרו רבי יונה (ירו', כתובות פ\"א ה\"א), ורבי יוסי (ירו', מע\"ש פ\"ד ה\"ב). נפטר בחיי רבי אמי (ירו', סוף מו\"ק). שמו השתבש בכמה פנים: ר' כרוספדאי (כריתות שם), ר' קריספי (ירו', סוף מו\"ק), ר' קריצפי (מד' משלי פ\"ד - כ\"ז), ר' קרציפא (ויק\"ר פ\"ד - ב'), ר' קריספדא (ירו', שבת פ\"א ה\"ד), ר' קרוצפי (קה\"ר פ\"ד - ז'), ר' קריספא (ירו', מע\"ש פ\"ד ה\"ב).","cat": "sage"},{"i": 3213,"n": "רב קרוספי","l": "ק","b": "מובא בירושלמי (סוף מו\"ק), והוא רבי קרוספאי.","cat": "sage"},{"i": 3214,"n": "רבי קרוצפי","l": "ק","b": "מובא בקה\"ר (פ\"ד - י\"ז), והוא רבי קרוספאי.","cat": "sage"},{"i": 3215,"n": "רבי קריספא","l": "ק","b": "מובא בירושלמי (מע\"ש פ\"ד - ה\"ב), ר' יוסי בשם ר' קריספא, והוא רבי קרוספאי.","cat": "sage"},{"i": 3216,"n": "רבי קריספאי","l": "ק","b": "הוא ר' קרוספאי.","cat": "sage"},{"i": 3217,"n": "רבי קריספדא","l": "ק","b": "מובא בירושלמי (שבת פ\"א ה\"ד), והוא רבי קרוספאי.","cat": "sage"},{"i": 3218,"n": "רבי קריצפי","l": "ק","b": "מובא במדרש משלי (פ\"ד - כ\"ז), והוא רבי קרוספאי.","cat": "sage"},{"i": 3219,"n": "קרנא","l": "ק","b": "אמורא בבלי בדור הראשון. והוא ושמואל מכונים: \"דייני גולה\" (סנהדרין י\"ז ע\"ב), וכן גיר' הרשב\"ם (ב\"ב ק\"ז ע\"ב). שמואל הענישו (ב\"ב פ\"ט ע\"א), ומשמע שהיה תלמידו, וחלק עמו (קידושין מ\"ד ע\"ב) וכשרב בא לבבל, שלח שמואל את קרנא לתהות על קנקנו, ורב הקפיד והענישו (שבת ק\"ח ע\"א). חיבר ברייתות הקרויות \"נזיקין דבי קרנא\" (ב\"ק מ\"ז ע\"ב).","cat": "sage"},{"i": 3220,"n": "רבי קרציפא","l": "ק","b": "מובא בויק\"ר (פ\"ד - ב'), והוא רבי קריספאי.","cat": "sage"},{"i": 3221,"n": "ר חסדיי","l": "ר","b": "כך נקרא לפעמים ר' חסדא בירושלמי.","cat": "sage"},{"i": 3222,"n": "רבי ראובן (2)","l": "ר","b": "אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי: \"שלח משמיה דרבי יוחנן\" (מנחות נ\"ז ע\"ב), אבל גיר' רש\"י: \"שלח רבין משמיה דרבי יוחנן\" (שם). כן: (ירו', כתובות פי\"א ה\"ז), \"רבי אבין בעא קומי רמי מנא [א]. ו\"סה\"ד\" גרס: \"ר' ראובן\". בשמו מסרו: רבי פנחס (תנחומא בראשית) ורבי ביבי (ירו', סנהדרין פ\"א ה\"א).","cat": "sage"},{"i": 3223,"n": "ר' ראובן איצטרובילי","l": "ר","b": "הוא רבי ראובן איסטרובלי.","cat": "sage"},{"i": 3224,"n": "ר' ראובן בן איסטרובלי","l": "ר","b": "תנא בדור הרביעי. היה מקורב למלכות בזמן רבי שמעון בן יוחאי (מעילה י\"ז ע\"א). פעם גזרה המלכות גזרה שלא ישמרו את השבת ולא ימולו את בניהם, והוא בחכמתו גרם לביטול זמני של הגזרה (שם). שני בניו היו תלמידיו של רבי (ירו', כלאים פ\"ט ה\"ג). רב מסר בשמו (מו\"ק י\"ח ע\"ב).","cat": "sage"},{"i": 3225,"n": "רבי ראובן בן אצטרובילי","l": "ר","b": "מובא בבבלי (מו\"ק י\"ח ע\"ב), והוא ר' ראובן בן איסטרובלי.","cat": "sage"},{"i": 3226,"n": "ר' ראובן בר איסטרובילוס","l": "ר","b": "מובא בירושלמי (כלאים פ\"ט ה\"ג), והוא ר' ראובן בן איסטרובלי.","cat": "sage"},{"i": 3227,"n": "ראמי בר תמרי","l": "ר","b": "מובא בבבלי (מנחות כ\"ט ע\"ב), והוא רמי ברי תמרי. ותיבת \"חמוה\" שם נראית ט\"ס, ונראה שצ\"ל: ראמי (רמי) בר תמרי, הוא רמי בר דיקולי (חולין ק\"י ע\"א).","cat": "sage"},{"i": 3228,"n": "רב","l": "ר","b": "אמורא בבלי בדור הראשון. מגדולי האמוראים. נפטר בשנת ד' ו' (642) (\"אגרת רב שרירא גאון\"). רב תנא הוא ופליג (עירובין נ' ע\"ב). מוזכר פעמים בברייתא (כתובות פ\"א ע\"א; שם מ\"ט ע\"א). שמו היה אבא, בלשון כבוד קראו לו: בבבל \"רב\" כמו שקראו \"רבינו\" לרבי יהודה הנשיא בא\"י (ב\"ב קי\"ט ע\"ב רשב\"ם). יש אומרים, שבכל מקום שנאמר בש\"ס: \"והאמר מר\" הכוונה לרב. מובא ג\"כ בהג\"ה בהקדמת הרמב\"ם לסדר זרעים. עלה לא\"י ולמד תורה מר' חייא, שהיה דודו (סנהדרין ה' ע\"א) ורבו המובהק (מו\"ק ט\"ז ע\"ב). גם רבי היה רבו המובהק (חולין קל\"ז ע\"ב). כשרב שימש את רבי בישיבה, עדיין שימש רבי יוחנן את רבי בעמידה (שם נ\"ד ע\"א), וכשר' יוחנן שימש את רבי בישיבה, ישב 71 שורות מאחרי רב (שם קל\"ז ע\"ב). את רבי היה מכנה \"רבינו הקדוש\" (ביצה כ\"ב ע\"ב). למד עם חברו לוי לפני רבי (שם כ\"ד ע\"ב). נמנה עם חשובי החכמים בא\"י ופסיק סידרא קמיה רבי ור' חייא, ובר קפרא, ור' שמעון בן רבי ואחר בא גם ר' חנינא בר חמא (יומא פ\"ז ע\"ב). נמנה עם בית דינו של רבי (גיטין נ\"ט ע\"א). ירד לבבל ומשם שלח שאלותיו לרבי (כתובות ס\"ט ע\"א). אח\"כ חזר לא\"י (ירו', סוטה פ\"ט ה\"ה; פסחים ד' ע\"א). נראה שנשאר בא\"י עד לאחר פטירת רבי (ירו', חגיגה פ\"א ה\"ח). בשנת ג' תתקע\"א (812) ירד לבבל והשתקע שם (\"אגרת רב שרירא גאון\"). כשהגיע לבבל לא הכירו שמואל (שבת ק\"ח ע\"א), וגם חכמים אחרים לא הכירוהו (יומא כ' ע\"ב). אח\"כ הפכו רב ושמואל לחברים. היה גדול משמואל (כתובות כ\"ב ע\"א), ושמואל היה כפוף לו (מגילה כ\"ב ע\"א). הניח לשמואל להיות הראש בנהרדעא, וייסד ישיבה בסורא (גיטין ו' ע\"א רש\"י). ישיבתו התקיימה כ - 008 שנה עד סוף תקופת הגאונים (\"אגרת רב שרירא גאון\"). תלמידיו מנו אלפים (כתובות ק\"ו ע\"א). מבין גדולי תלמידיו: רב הונא (שבת קכ\"ח ע\"א), רב יהודה (קדושין פ\"א ע\"א), ורבי חננאל (פסחים ק\"ג ע\"א), היו לו גם תלמידי - חברים: רבי ירמיה בר אבא (ברכות כ\"ז ע\"ב), רב כהנא ורב אסי (שבת קמ\"ו ע\"ב רש\"י). רב ושמואל נקראו בש\"ס: \"רבותינו שבבבל\" (סנהדרין י\"ז ע\"ב). הש\"ס מלא במחלוקותיהם הקרויות \"הוויות דרב ושמואל\" (ברכות ל' ע\"א). תלמידיו קראו לו: \"רבנו הגדול\" (סוכה ל\"ג ע\"א). רש\"י פירש: \"ומאדם חשוב כמו רב וכו' פרכינן כאילו כתוב במשנה\" (ב\"ק ל\"ג ע\"ב) וכן: \"ואע\"ג דרב אמורא הוא, מקשי מיניה, מפני שרבן של כל בני הגולה היה חוץ משמואל\" (ביצה ט' ע\"א). ההלכה נקבעה כרב בדיני איסורים, וכשמואל בדיני ממונות (בכורות מ\"ט ע\"ב). נהג בחסידות מופלגת (\"תשובות הגאונים\", \"שערי תשובה\" סימן קע\"ח). כשבא לבבל היה עני גדול: \"אין לו מה יאכל הוה\" (מו\"ק י\"ב ע\"ב), אח\"כ התעשר: \"והאמר רב: 'לא איעתרי עד וכו'\" (ברכות נ\"ז ע\"ב) כמה מן התפלות הנאמרות התקין רב: \"יהי רצון וכו' חיים ארוכים וכו'\", שאומרים בשבת מברכים ראש חודש (ברכות ט\"ז ע\"ב). \"אתה זוכר\" בתפילת מוסף של ראש השנה (ירו', ר\"ה פ\"א ה\"ג), וכן \"תודיענו\" למוצש\"ק מכונה: \"מרגניתא\", שרב ושמואל התקינו בבבל (ברכות ל\"ב ע\"ב). כשנפטר קרע עליו שמואל 21 בגדים (מו\"ק כ\"ד ע\"א), ותלמידיו באו לפני שמואל (ברכות י\"ב ע\"א). אשתו ציערה אותו (יבמות ס\"ג ע\"א). את בנו חייא לימד בעצמו (פסחים ע' ע\"א). בנו השני איבו ניהל את ענייניו המסחריים (פסחים קי\"ג ע\"א). שלש בנות היו לו, אחת נישאה לתלמידו רב חנן בר רבא (חולין צ\"ה ע\"ב), אחת היתה אם החכמים: איבו וחזקיה (סוכה מ\"ד ע\"ב) ואחת היתה אם האחים רבנא עוקבא ורבנא נחמיה, שהיו עשירים ומקורבים למלכות (חולין צ\"ב ע\"א).","cat": "sage"},{"i": 3229,"n": "רבא (2)","l": "ר","b": "מגדולי אמוראי בבל ומראשי הדור הרביעי. אביו היה האמורא רב יוסף בר חמא (עירובין נ\"ד ע\"א). רש\"י כתב: \"רבא בריה דרב יוסף בר חמא (כצ\"ל) הוא והוא רבא בכולי גמרא בר פלוגתיה דאביי\" (חולין מ\"ג ע\"ב). היה ראש ישיבת מחוזא ארבע עשרה שנה נפטר בשנת ד' קי\"א (153). במותו נחלקה ישיבת מחוזא לשתים: רב נחמן בר יצחק תלמידו מלך בפומבדיתא ורב פפא תלמידו מלך בנרש (\"אגרת רב שרירא גאון\"). רב נחמן היה רבו המובהק (ברכות כ\"ג ע\"ב). רבא היה אצלו כשרב נחמן נפטר (מו\"ק כ\"ח ע\"א). וגם רב חסדא היה רבו (קידושין נ\"ג ע\"ב), וכן היה חותנו (יבמות ל\"ד ע\"ב). גם רב יוסף היה רבו המובהק (יומא נ\"ג ע\"א). וכשנודע לרב יוסף שרבא מכבדו מאוד, ברכו שיהיה ראש ישיבה (שם). ולדעת תוספות היה גם רב סחורה רבו המובהק. \"רב סחורה רבו המובהק של רבא היה\" (ע\"ז י\"ט ע\"א ד\"ה: אמר). חברו הגדול והמובהק היה אביי, ועל שמם נקרא הש\"ס: \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). מחלוקותיהם ושקלי וטרי שלהם פזורים בכל הש\"ס, וכבר בילדותם למדו יחד (ברכות מ\"ח ע\"א). כשנפטר רב יוסף, מינו את אביי לראש (סוף הוריות), וכשאביי נפטר בשנת ד' צ\"ח (833) בפומבדיתא, מלך רבא. אך במקום בפומבדיתא, יסד את ישיבתו במחוזא, והיא היתה הישיבה המרכזית בבבל (\"אגרת רב שרירא גאון\"), ורב נחמן בר יצחק שימש כראש כלה אצלו (ב\"ב כ\"ב ע\"א). דרך לימודו של רבא היה בחריפות: \"אמר רבא וכו' היינו דאמרי אינשי: 'טבא פילפלתא חריפתא ממלי צנא דקרי'\" (חגיגה י' ע\"א). אהב את הסברא: \"אמר להו (רבא): 'זיל בתר סברא'\" (גיטין ע\"ג ע\"א). והלכה כרבא שהוא בתראה (ברכות י\"ג ע\"ב תוס'). תוספות כתבו: \"בכל מקום שהרב והתלמיד חולקין הלכה כדברי הרב באמוראי עד אביי ורבא, אבל מכאן ואילך פסקינן כבתראי\" (קידושין מה ע\"ב ד\"ה: הוה). בין תלמידיו הרבים היו רבינא (ב\"ב ט\"ז ע\"ב), רב פפא (כתובות פ\"ה ע\"א), ובניו רב יוסף (חולין כ\"ח ע\"ב) ורב משרשיא (שם ע\"א), ועל שניהם אמר רבא: \"חכים ברי בטריפות\" (שם). היה מופלג בחסידות ולא בוש לומר: \"טעיתי\" (עירובין ק\"ד ע\"א). נהג לצום שני ימים ביום הכיפורים משום ספיקא (ר\"ה כ\"א ע\"א). ובכל ערבי יום כפורים יצאה בת קול מהשמים ושאלה לשלומו (תענית כ\"א ע\"ב). היה עשיר מופלג וחכם נדיר (מו\"ק כ\"ח ע\"א). היה מקורב למלכות (ב\"ב י' ע\"ב). לפי דרישתו של שבור מלכא מלך פרס, שניסה אותו, ביקש פעם מן השמים בחודש תמוז שירד גשם שוטף ובקשתו נתקבלה, ואביו בא לו בחלום ואמר שלא ישן במיטתו בלילה, שכן יש הקפדה מהשמים שהטריח בעניין הגשמים, ובלילה, חתכו השדים את מיטתו (תענית כ\"ד ע\"ב). ושוב שלחו מבית שבור מלכא לשאלו אם יודע להבחין בין סוגי דם, וידע להבחין יותר מששים סוגי דם (נדה כ' ע\"ב). ומסופר (מו\"ק שם) על פטירתו, שרב שעורים אחיו של רבא היה אצלו כשמת, וביקש רבא את אחיו שיאמר למלאך המות שלא יצערו. אחרי פטירתו נגלה לאחיו רב שעורים וסיפר לו שהיתה לו מיתה קלה בלי צער, והתחושה היתה כאילו הקיזו דם. כשמת רב יהודה, נולד רבא, וכשמת רבא, נולד רב אשי (קידושין ע\"ב ע\"ב).","cat": "sage"},{"i": 3230,"n": "רבא אבוה דרב מרי בר רחל","l": "ר","b": "מובא בבבלי (שבת קנ\"ד ע\"א). ע\"ע רב מרי בר איסור גיורא.","cat": "sage"},{"i": 3231,"n": "רבא אחוה דר' מרי בר רחל","l": "ר","b": "מובא בבבלי (שבת קנ\"ד ע\"א). ע\"ע רב מרי בר איסור גיורא.","cat": "sage"},{"i": 3232,"n": "רבא בר אבא","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רבי חייא בר אשי: \"אמר רבא אמר רבי חייא בר אשי אמר שמואל\" (פסחים ל' ע\"ב).","cat": "sage"},{"i": 3233,"n": "רבא בר אבין","l": "ר","b": "אמורא בבלי בדור השני - השלישי (פסחים מ' ע\"א).","cat": "sage"},{"i": 3234,"n": "רבא בר אהילאי","l": "ר","b": "אמורא בבלי בדור החמישי. מובא בבבלי, שמתקיף על דברי רבא (זבחים י' ע\"ב). רבינא ורב אשי שקלו וטרו בדבריו (פסחים ל' ע\"ב).","cat": "sage"},{"i": 3235,"n": "רבא בר אהינא","l": "ר","b": "מובא בבבלי (מנחות ל\"ז ע\"ב). אולי הוא בר אהינא.","cat": "sage"},{"i": 3236,"n": "רבא בר איתי","l": "ר","b": "אמורא בדור השלישי - הרביעי. נראה, שהיה בארץ ישראל ובבבל. בארץ ישראל היה תלמידו של ריש לקיש (כריתות כ\"ד ע\"א), ובבבלי מצינו: \"אמר להו רבא בר איתי\" [לתלמידי רבה] (שבועות ל\"ו ע\"א).","cat": "sage"},{"i": 3237,"n": "רבא בר אפיתון","l": "ר","b": "כך מובא ב\"ילקוט\" (אסתר תתרנ\"ו), ונראה שצ\"ל: רבה בר עופרון.","cat": "sage"},{"i": 3238,"n": "רבא בר בונא","l": "ר","b": "מובא בירושלמי (סנהדרין פ\"ג ה\"ג). ע\"ע רבי אבא בר אבינא.","cat": "sage"},{"i": 3239,"n": "רבא בר בריה דרב פפי","l": "ר","b": "מובא בירושלמי (שבת פ\"א).","cat": "sage"},{"i": 3240,"n": "רבא בר זבדא","l": "ר","b": "מובא בירושלמי (יבמות פ\"א ה\"ו), ונראה שהוא רבי אבא בר זבדא.","cat": "sage"},{"i": 3241,"n": "רבא בר זוטרא","l": "ר","b": "מובא בירושלמי (שבת פי\"ג ה\"ד). ע\"ע ר' אבא בר זוטרא.","cat": "sage"},{"i": 3242,"n": "רבא בר זימונא","l": "ר","b": "מובא בבבלי (שבת קי\"ב ע\"ב). ע\"ע ר' אבא בר זמינא.","cat": "sage"},{"i": 3243,"n": "רבא בר זימנא","l": "ר","b": "הוא אבא בר זמינא.","cat": "sage"},{"i": 3244,"n": "רבא בר זמינא","l": "ר","b": "הוא רבי אבא בר זמינא.","cat": "sage"},{"i": 3245,"n": "רבא בר חיננא","l": "ר","b": "אמורא בבלי בדור הששי, ואולי הוא ורבה בר חנינא אחד הוא. מובא ממנו, שהכריז על שחיטתו של שוחט כטריפה, כי לא הראה לו את הסכין, ומר זוטרא ורב אשי מצאו זכות עבורו: \"אמר ליה מר זוטרא [לרב אשי] ולא ליחש מר לסברא\" (חולין י\"ח ע\"א), ופרש\"י: \"לרבא בר חיננא שהעבירו, ואתה מכשירו\" לפי שקראו לו \"סבא\", יתכן שהיה בדור הרביעי וחי עד ימי רב אשי. שמו רבא ורבה וחנינא וחיננא - מתחלפים. ומה שמצאנו: \"אמר רבא בר חנינא אמר רבי יוחנן\" (שבת י\"ט ע\"ב), כבר גרסו הרי\"ף והרא\"ש: רבה בר בר חנה במקום רבא בר חנינא.","cat": "sage"},{"i": 3246,"n": "רבא בר חקלאי","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא ושאל ממנו (עירובין ס\"ז ע\"ב).","cat": "sage"},{"i": 3247,"n": "רבא בר יוסף","l": "ר","b": "מובא בבבלי (סוטה ל\"ד ע\"א) אחרי אביי, ואולי הוא רבא סתם, כדמפרש רש\"י: \"רבא בריה דרב יוסף וכו' והוא רבא דכולי גמרא\" (חולין מ\"ג ע\"ב). אך הרא\"ש גורס: \"רבא בר יוסף משמיה דרבא\" (ב\"מ ס\"ז ע\"א), ולפנינו שם: \"מר בריה דרב יוסף משמיה דרבא\".","cat": "sage"},{"i": 3248,"n": "רבא בר ירמיה","l": "ר","b": "מובא בבבלי (ברכות מ\"ג ע\"א), והוא רבה בר ירמיה.","cat": "sage"},{"i": 3249,"n": "רבא בר ישמעאל","l": "ר","b": "מובא בבבלי (מו\"ק ו' ע\"ב).","cat": "sage"},{"i": 3250,"n": "רבא בר מחסיא","l": "ר","b": "אמורא בבלי בדור השלישי. תלמיד תלמידו של רב. עשרה מאמרים של רב קיבל מרב חמא בר גוריא, תלמידו של רב (שבת י' ע\"ב).","cat": "sage"},{"i": 3251,"n": "רבא בר מרי","l": "ר","b": "מובא בבבלי (עירובין פ\"ו ע\"א). ו\"עין יעקב\" גרס: רבה בר מרי.","cat": "sage"},{"i": 3252,"n": "רבא בר משרשיא","l": "ר","b": "אמורא בדור החמישי. הקשה לרבא (נזיר מ' ע\"ב) (\"סה\"ד\" בתמה על מה שהקשה רבא בר משרשיא לרבא מהשקלא וטריא של רבא מברניש עם רב אשי, שהיו מאוחרים יותר, לענ\"ד לא קשה מידי וזה ממסדר הש\"ס, ולא שרבא ראה לרב אשי).","cat": "sage"},{"i": 3253,"n": "רבא בר מתנה","l": "ר","b": "ע\"ע רבה בר מתנה.","cat": "sage"},{"i": 3254,"n": "רבא בר נתן בר אמי","l": "ר","b": "כן גרס \"סה\"ד\" (קדושין ל' ע\"א), ולפנינו: \"אמר ליה רבא לרב נתן בר אמי\"; א\"כ, לפי גיר' \"סה\"ד\" לא היה אמורא בשם זה, שכן שוב לא מובא בש\"ס.","cat": "sage"},{"i": 3255,"n": "רבא בר פפא","l": "ר","b": "מובא בבבלי: \"מאי לוקמטין, א\"ר אבהו: 'חמרא דאכפא', רבא בר פפא אמר: 'קשירי', רבא בר רב הונא אמר: 'פרמי'\" (שבת ס\"ו ע\"ב). \"יוחסין\" גרס: רבא בריה דרב פפא, ורי\"ף גרס: רפרם בר פפא.","cat": "sage"},{"i": 3256,"n": "רבא בר קיסי","l": "ר","b": "כך גירסת מהרש\"ל בבבלי (חולין כ' ע\"ב). ע\"ע רביא בר קיסי.","cat": "sage"},{"i": 3257,"n": "רבא בר קיסנא","l": "ר","b": "מובא בבבלי (ב\"ב י\"ב ע\"א).","cat": "sage"},{"i": 3258,"n": "רבא בר רב אדא","l": "ר","b": "אמורא בבלי בדור השלישי. הוא ואחיו רבין בר רב אדא היו תלמידיו של רב יהודה (ביצה ל\"ג ע\"ב). היה תלמידו של רב (קידושין ע' ע\"א). גם אביו רב אדא היה חכם והוא קיבל מאביו (מנחות ל\"ט ע\"א).","cat": "sage"},{"i": 3259,"n": "רבא בר רב הונא זוטי","l": "ר","b": "אמורא בבלי בדור החמישי. \"שלח לו רב נחמיה בריה דרב יוסף [לרבא בר רב הונא זוטא]: כי אתיא הא איתתא לקמך וכו'\" (כתובות ס\"ט ע\"א). היה הדיין בנהרדעא (שם).","cat": "sage"},{"i": 3260,"n": "רבא בר רב חנן","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (עירובין נ\"א ע\"ב בפירוש הר\"ח) ושקיל וטרי עמו. וכן שקיל וטרי עם אביי (ברכות מ\"ה ע\"א). ישב לפני רבא (זבחים נ\"ה ע\"א), וקשה להניח שהיה תלמידו ממש.","cat": "sage"},{"i": 3261,"n": "רבא בר רב חסדא","l": "ר","b": "מובא בב\"ר (פ\"ה - י\"ג).","cat": "sage"},{"i": 3262,"n": "רבא בר רב עזא","l": "ר","b": "אמורא בבלי בדור הרביעי. מצינו: \"אמר רבא בר רב עזא: 'בען במערבא וכו' א\"ל אביי' וכו'\" (תמורה כ\"א ע\"א).","cat": "sage"},{"i": 3263,"n": "רבא בר רב שילא","l": "ר","b": "מובא בבבלי (עירובין ס' ע\"ב), והוא רבה בר שילא.","cat": "sage"},{"i": 3264,"n": "רבא בר שאילנא","l": "ר","b": "הוא רבה בר שילא.","cat": "sage"},{"i": 3265,"n": "רבא בר שאילתא","l": "ר","b": "אמורא בבלי בדור החמישי. מובא בבבלי, ששאל מרב נחמן בר יצחק כנראה שהוא הוא רבה בר שילא (גיטין ל\"ט ע\"ב).","cat": "sage"},{"i": 3266,"n": "רבא בר שבא","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא (שבת קל\"ט ע\"ב).","cat": "sage"},{"i": 3267,"n": "רבא בר שירא","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי, שמתקיף על דברי רב יוסף: \"לא שמיע להו הא דתני רב חנן בר רבא לחייא בר רב וכו'\" (שבת ס\"ו ע\"א).","cat": "sage"},{"i": 3268,"n": "רבא בר שמואל (2)","l": "ר","b": "אמורא בבלי בדור החמישי. חברם של רב פפא ורב הונא בריה דרב יהושע (ברכות כ\"ב ע\"ב).","cat": "sage"},{"i": 3269,"n": "רבא בר שרשום","l": "ר","b": "חי בבבל בדור הרביעי. יצא עליו קול, שלקח קרקע של יתומים, ואביי אמר לו: \"אימא לי איזו גופא דעובדא וכו'\" (ב\"ב ל\"ב ע\"ב). אין הכרח מוחלט, אך נראה שהיה אמורא.","cat": "sage"},{"i": 3270,"n": "רבא בר תחליפא","l": "ר","b": "אמורא בבלי בדור הששי. מצינו: \"אמר ליה רבא בר תחליפא לרבינא\" (עירובין מ' ע\"א). יש רבה בר תחליפא, שמסר משם רב (שבת ק\"כ ע\"ב).","cat": "sage"},{"i": 3271,"n": "רבא בריה דרב אויא","l": "ר","b": "כן גיר' \"אור זרוע\" (הלכות טרפות סתי\"א) בבבלי (חולין מ\"ז ע\"א), ולפנינו הגיר': רב הונא בר מר אויא. והיה בדורו של רב אשי (בדור הששי לאמוראי בבל).","cat": "sage"},{"i": 3272,"n": "רבא בריה דרב אחא בר הונא","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (נדה ל\"א ע\"ב).","cat": "sage"},{"i": 3273,"n": "רבא בריה דרב אידי בר אבין","l": "ר","b": "אמורא בבלי בדור החמישי. כן גיר' הרא\"ש בבבלי (שבת קל\"ו ע\"א), ולפנינו הגיר': רב פפא ורב הונא בריה דרב יהושע, איקלעו לבי בריה דרב אידי בר אבין, (בלי המלה \"רבא\").","cat": "sage"},{"i": 3274,"n": "רבא בריה דרב עילאי","l": "ר","b": "אמורא. נראה שהיה בדור השלישי: \"דרש רבא בריה דרב עילאי: מאי דכתיב: ויאמר ה' יען כי גבהו בנות ציון וכו', א\"ר יצחק דבי רב אמי [תלמידו של רב חסדא]: 'מלמד שמטילות מור ואפרסמון במנעליהן וכו'\" (שבת ס\"ב ע\"ב).","cat": "sage"},{"i": 3275,"n": "רבא בריה דרבה","l": "ר","b": "אמורא בבלי בדור הרביעי. בנו של האמורא המפורסם רבה. שלח לרב יוסף: \"ילמדנו רבנו\" (שבת קכ\"ג ע\"א; יבמות ע\"ו ע\"א, ועוד), אך לא מצינו שישב לפני רב יוסף. מצינו: \"רבה בריה דרבא\" (מגילה כ\"ב ע\"א ועוד), וצ\"ל: רבא בריה דרבה, ומסופר: (מכות י' ע\"א): \"אמר רבה בר מרי: 'מי אוהב בהמון וכו', יהבי בי רבנן עינייהו ברבא בריה דרבה'\" [שהיה אוהב תלמידי חכמים ביותר והיו לו בנים תלמידי חכמים] (מכות י' ע\"א).","cat": "sage"},{"i": 3276,"n": "רבא בריה דרבה בר רב הונא","l": "ר","b": "אמורא בבלי בדור הרביעי. בן בנו של רב הונא המפורסם. חלק עם אביו רבה בר רב הונא (עירובין נ\"ה ע\"ב). אביי אמר: \"כוותיה דרבא בריה דרבה בר רב הונא מסתברא\". אולי הוא אבא בריה דרבה בר רב הונא (סוטה מ\"ט ע\"א).","cat": "sage"},{"i": 3277,"n": "רבא זעירא","l": "ר","b": "אמורא שאין לקבוע זמנו ומקומו. מצינו: \"אמר רבי אלעזר: 'כל שארגו' וכו' מתקיף לה רבא זעירא ואיתמא רבי שמואל בר נחמני וכו'\" (ערכין ט\"ז ע\"ב). הגמרא מפקפקת אם רבא זעירא הקשה או רבי שמואל בר נחמני הקשה, אך אין בכך להוכיח מאומה שהיה בזמנו של ר' שמואל בר נחמני.","cat": "sage"},{"i": 3278,"n": "רבא מברניש","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (ב\"מ ע\"ג ע\"ב), שקיל וטרי עמו (שבת כ\"ח ע\"א).","cat": "sage"},{"i": 3279,"n": "רבא מפרזקיא","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (תמורה ל' ע\"א), ושקיל וטרי עמו (כתובות ל\"ט ע\"ב). נראה, שהיה דיין במקומו: \"ההיא ביניתא וכו', אסרה רבא מפרזיקיא\" (פסחים ע\"ו ע\"ב).","cat": "sage"},{"i": 3280,"n": "רב רבאי דמן רוב","l": "ר","b": "מחכמי רבנן סבוראי האחרונים. ראש ישיבת פומבדיתא אחרי רב סימונא. האריך ימים. שם עירו היה רוב, והעיר רוב היתה בסביבות נהרדעא (\"אגרת רב שרירא גאון\"). מוזכר בש\"ס הבבלי (סנהדרין מ\"ג ע\"א) לגירסת הר\"ח.","cat": "sage"},{"i": 3281,"n": "רבה (3)","l": "ר","b": "מגדולי אמוראי בבל בדור השלישי, והוא סתם רבה בכל הש\"ס. שם אביו נחמני, בר פלוגתיה דרב יוסף (ב\"מ פ\"ו ע\"א רש\"י). ראש ישיבת פומבדיתא במשך עשרים ושתיים שנה בשנים ד' נ\"ח - ד' פ' (892 - 023). מלך אחרי רב יהודה רבו. אחרי שנפטר מלך רב יוסף (\"אגרת רב שרירא גאון\"). בגיל 81 היה לראש ישיבה, ובגיל 04 נפטר (מו\"ק כ\"ח ע\"א). לפי דברי תוספות, הלך לארץ ישראל ולמד לפני רבי יוחנן (עירובין כ\"ב ע\"ב ד\"ה: קרקפנא). רבותיו היו רב הונא (עירובין י\"ז ע\"א), רב חסדא (ב\"מ מ' ע\"א רש\"י), רב ששת (עירובין ס\"ה ע\"ב) ורב נחמן (יבמות ס\"ו ע\"א). בין חבריו היה רבי זירא (חולין מ\"ו ע\"א), ופעם עשו שניהם סעודת פורים, ורבה השתכר ושחט את רבי זירא, ואחרי שהתפכח ביקש רחמים והחיה אותו (מגילה ז' ע\"ב). חברו המובהק ובר פלוגתיה היה רב יוסף. רבה הצטיין בפלפול ובחריפות וקראו לו: \"עוקר הרים\" ולרב יוסף קראו: \"סיני\", על שהצטיין בשמועות רבות וכשנפטר רבי יהודה רבם שלחו מבבל לא\"י לשאול את מי להמליך, והשיבו שימליכו את רב יוסף, אלא שרב יוסף ויתר, ורבה מלך במקומו (ברכות ס\"ד ע\"א). היו לו מאות תלמידים, ו - 004 מהם היו אוכלי שולחנו (כתובות ק\"ו ע\"א רש\"י). בחודשים ניסן ותשרי התאספו אליו שנים עשר אלף איש לשמוע את דרשותיו לחגים (ב\"מ פ\"ו ע\"א). לא ישן ביום יותר משינת הסוס, שהיא ששים נשימות (סוכה כ\"ו ע\"ב). בצעירותו היה עני מרוד עד שלא נמצא לחם שעורים בביתו (מו\"ק כ\"ח ע\"א), ואחרי שמלך כנראה שהעשירוהו, כמו שכתב רש\"י: \"מנהג הוא, מי שהוא ראש ישיבה היו מגדלין אותו\" (תענית כ\"א ע\"א ד\"ה: מלך). וכן מוכח מזה, שאביי אמר לרבה: \"נעשית מלך וראש בפומבדיתא ואינך שולח לו אלא דברים המצויין לכל\" (מגילה ז' ע\"ב רש\"י ד\"ה: אי). היו לו שלושה אחים, שניים, רב חייא ורב אושעיא, היו בארץ ישראל ושלחו לו לבוא לא\"י ללמוד לפני רבי יוחנן (כתובות קי\"א ע\"א), והשלישי היה כייליל, אביו של אביי (זבחים קי\"ח ע\"ב רש\"י ד\"ה: חד). בין תלמידיו המובהקים היה אביי בן אחיו (ברכות ל\"ג ע\"ב). היה לו בן חכם ושמו רבא (שבת קכ\"ג ע\"א). כשנודע למלכות שאלפי אנשים מתאספים לשמוע את דרשותיו, ואינם משלמים מסים למלכות, שלחו לתפסו, והוא ברח. ובאותו זמן היתה מחלוקת הלכתית במתיבתא דרקיע, ושלחו למלאך המות שיביאוהו, ולא יכול מלאך המות לקרב אליו. ובשעת פטירתו אמר: \"טהור טהור\" ויצאה בת קול ואמרה: \"אשריך רבה בר נחמני שגופך טהור ויצאה נשמתך בטהור\", ונפל פתק מהשמים לפומבדיתא: \"רבה בר נחמני נתבקש לישיבה של מעלה\". ולאחר שהספידוהו שלשה ימים, נפל פתק שני: \"מי שפורש יהיה בנידוי\", ולאחר שבעה ימי הספד נפל פתק שלישי: \"לכו לביתכם לשלום\".","cat": "sage"},{"i": 3282,"n": "רבה בר אבוה","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (שבת קכ\"ט ע\"ב). רבו המובהק של רב נחמן (ברכות כ\"א ע\"א) נראה, שנתן לרב נחמן את בתו ילתא לאשה (יבמות פ' ע\"ב). יותר ממאה פעמים מצינו בש\"ס: \"אמר רב נחמן אמר רבה בר אבוה\". רבה בר אבוה היה ממשפחת הנשיאים (\"אגרת רב שרירא גאון\"). בשנת ד' י\"ח (852), כשנחרבה נהרדעא על ידי פפא בן נצר, הלך כנראה, רבה בר אבוה למחוזא (עירובין כ\"ו ע\"א) והיה מראשי הדיינים שם (יבמות קט\"ו ע\"ב). היה עני מרוד ואליהו הנביא נגלה לו והעשירו (שם קי\"ד ע\"ב). היה לו בן חכם (עירובין ג' ע\"א).","cat": "sage"},{"i": 3283,"n": "רבה בר אהיליי","l": "ר","b": "מובא בבבלי (זבחים צ\"ה ע\"ב). ע\"ע רבא בר אהילאי.","cat": "sage"},{"i": 3284,"n": "רבה בר איבו","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (גיטין ל\"ב ע\"א).","cat": "sage"},{"i": 3285,"n": "רבה בר איסי","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (סוטה ל' ע\"א).","cat": "sage"},{"i": 3286,"n": "רבה בר איתא","l": "ר","b": "אמורא. תלמידו של ריש לקיש (כריתות כ\"ד ע\"א), והוא רבא בר איתי. נראה, שהיה בבבל ודיבר עם תלמידי רבה (שבועות ל\"ז ע\"א).","cat": "sage"},{"i": 3287,"n": "רבה בר איתי","l": "ר","b": "הוא רבא בר איתי.","cat": "sage"},{"i": 3288,"n": "רבה בר בר חנא","l": "ר","b": "אמורא בדור השלישי. ממשפחת רב (סנהדרין ה' ע\"א). היה יליד בבל, כמובא שריש לקיש שחה בירדן, ובא רבה בר בר חנא והושיט לו ידו, אמר לו ר\"ל: \"סנינא לכו\" [אני שונא לכם לכל בני בבל, שלא עלו בימי עזרא לא\"י] (יומא ט' ע\"ב). תלמידו המובהק של רבי יוחנן (ברכות מ\"ד ע\"א), ויותר ממאתים מאמרים מסר בשמו. כן היה תלמידו המובהק של רבי אלעזר (שבת י\"ב ע\"ב). כן קיבל מרבי יהושע בן לוי (ברכות כ\"ד ע\"ב). היה מה\"נחותאי\", כמובא: \"כי אתא רבה בר בר חנא אכל דאייתרא\" [חלק שבכפיפת הקיבה שבני א\"י נוהגים בו היתר ובני בבל נוהגים בו איסור] (פסחים נ\"א ע\"א). ורב יהודה שאל ממנו: \"מידי שמיע לך בהא, א\"ל: הכי אמר רבי יוחנן\" (מו\"ק י\"ז ע\"א). רב יוסף קבל ממנו (יבמות ט\"ז ע\"ב), וגם רב נחמן קיבל ממנו (ב\"ק ק' ע\"ב). אביו רבה בר חנא היה שני בשני עם רב (סנהדרין ה' ע\"א). סיפר מראות מופלאים ממסעותיו (ב\"ב ע\"ג ע\"ב). סיפוריו נראים כגוזמאות גדולות, אך יש בהם רמזים עמוקים. בנו רב יצחק שהיה אף הוא חכם (יבמות ס\"ד ע\"ב), נשא לאשה את חומא בת איסי, נכדתו של רב יהודה ואחרי שרב יצחק זה מת, התחתן אביי עם חומא (שם).","cat": "sage"},{"i": 3289,"n": "רבה בר בר חנן","l": "ר","b": "מובא בבבלי (סוטה ל\"ד ע\"ב). אולי יש שיבוש בשם, שכן במקום אחר: \"רבה בר רב חנן\" (תמורה י\"ד ע\"ב), וכן ברוב המקומות בש\"ס. אך נראה שגירסתם של התוספות (סוטה ל\"ד ע\"ב ד\"ה: ואמר) היתה כמו לפנינו: רבה בר בר חנן.","cat": "sage"},{"i": 3290,"n": "רבה בר ברונא","l": "ר","b": "אמורא בבלי בדור השלישי. מובא בבבלי (שבת ק\"י ע\"א). תלמיד תלמידו של רב. אביו רב ברונא היה תלמידו המובהק של רב (פסחים ק\"ג ע\"א).","cat": "sage"},{"i": 3291,"n": "רבה בר זבדא","l": "ר","b": "מובא בבבלי (שבת י\"ט ע\"ב). נראה, שהוא ר' אבא בר זבדי.","cat": "sage"},{"i": 3292,"n": "רבה בר זוטרא","l": "ר","b": "מובא בירושלמי (גיטין פ\"ד ה\"ד). ע\"ע ר' אבא בר זוטרא.","cat": "sage"},{"i": 3293,"n": "רבה בר חייא קטוספאה","l": "ר","b": "אמורא בבלי בדור השני. מסר משם רב (ב\"ב צ\"ג ע\"ב). אותו מאמר מובא בירושלמי, ושם מכונה: \"אבא בר חייא\" (כלאים פ\"ב ה\"א). עשה חליצה בניגוד לדעתו של שמואל, ועל כך אמר עליו שמואל: \"כמה רב גובריה דעביד כיחידאה\" (יבמות ק\"ד ע\"א), ופרש\"י: \"בלשון גנאי אמרה\".","cat": "sage"},{"i": 3294,"n": "רבה בר חיננא סבא","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (ברכות י\"ב ע\"ב).","cat": "sage"},{"i": 3295,"n": "רבה בר חנה","l": "ר","b": "אמורא בבלי. עלה לארץ ישראל. בן אחיו של רבי חייא ואביו של רבה בר בר חנא (סנהדרין ה' ע\"א). היה שני בשני עם רב ויחד עם רב למד לפני רבי חייא (מו\"ק ט\"ז ע\"ב). לפני שחזר לבבל נתן לו רבי רשות לדון ולהתיר בכורות (שם). עם תלמידיו נמנה רב חננאל, שהיה גם תלמידו של רב (מו\"ק י\"ט ע\"א).","cat": "sage"},{"i": 3296,"n": "רבה בר חנינא","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של רב נחמן (ב\"ב קי\"ג ע\"ב). ע\"ע רבא בר חיננא.","cat": "sage"},{"i": 3297,"n": "רבה בר טוביה בר יצחק","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (עירובין כ\"ח ע\"א). \"דק\"ס\" גרס: \"רבה בר יצחק\" (ולא טוביה), ולגירסתו לא היה כלל חכם ושמו רבה בר טוביה בר יצחק, שכן מובא בש\"ס רק במקום זה.","cat": "sage"},{"i": 3298,"n": "רבה בר יונתן","l": "ר","b": "אמורא בבלי בדור השלישי (יומא מ\"ז ע\"א). תלמידו של רב יחיאל [ורבי יחיאל היה בר פלוגתיה של רב יהודה] (מו\"ק י' ע\"א).","cat": "sage"},{"i": 3299,"n": "רבה בר יוסף","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (ערכין ה' ע\"ב).","cat": "sage"},{"i": 3300,"n": "רבה בר יוסף בר חמא","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. נראה תלמידו של רב ששת (ב\"מ ע' ע\"א). יש גורסים: אמר רב יוסף בר חמא.","cat": "sage"},{"i": 3301,"n": "רבה בר ירמיה","l": "ר","b": "אמורא בבלי בדור השני - השלישי. מושבו היה בסורא (ע\"ז ט\"ז ע\"ב). מסר בשם רב (שם) והיה תלמידו של שמואל (נדה י\"א ע\"ב). רבו של רבי זירא (שם), שבא אליו לסורא לקבל הלכות (ע\"ז שם). מסרו בשמו רבי אבא (ירו', ר\"ה פ\"ד ה\"ו) ורבי יונה (ויק\"ר פי\"א - ב').","cat": "sage"},{"i": 3302,"n": "רבה בר ליואי","l": "ר","b": "אמורא בבלי בדור הרביעי. חברו של רבא ונהג להקשות לרבא ברבים, ופעמים שרבא נכלם מקושיותיו ונענש על כך (פסחים ק\"י ע\"א).","cat": "sage"},{"i": 3303,"n": "רבה בר לימא","l": "ר","b": "אמורא בבלי, כנראה בדור השני. אמר בשם רב (מגילה י\"ג ע\"ב).","cat": "sage"},{"i": 3304,"n": "רבה בר ממל","l": "ר","b": "מובא בבבלי (ב\"מ נ\"ו ע\"ב).","cat": "sage"},{"i": 3305,"n": "רבה בר מרי","l": "ר","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין ק\"ה ע\"א). כן קיבל מרבי יהושע בן לוי (ברכות מ\"ב ע\"ב). מצינו הלשון: \"אמרי במערבא משמיה דרבה בר מרי\" (יומא פ\"ו ע\"ב; סנהדרין ק' ע\"א, ועוד). אח\"כ ירד לבבל ורבא קיבל ממנו (ב\"ב ח' ע\"ב) ובירר אצלו סתירות באגדה, ורבה בר מרי תירץ לו מאמרי רבי יוחנן, ואמר לו: \"הכי אמר רבי יוחנן\" (מו\"ק כ\"ח ע\"ב). כן שאל ממנו ר' אבא והוא השיב לו: \"הכי אמר ר' יוחנן\" (סנהדרין ק\"א ע\"א).","cat": "sage"},{"i": 3306,"n": "רבה בר מריון","l": "ר","b": "מובא בבבלי: \"תנא רבה בר מריון בדבי רבי יוחנן בן זכאי\" (עירובין י\"ט ע\"א), ופרש\"י: \"ברייתא שסידר בביהמ\"ד\" ובמקום אחר מובא המאמר: \"תני רבה בר מרי משום רבי יוחנן בן זכאי\" (סוכה ל\"ב ע\"ב).","cat": "sage"},{"i": 3307,"n": "רבה בר מתנה","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידם של רבה ורב ששת (פסחים ל\"ד ע\"א). חברם של אביי ורבא ורב זירא. לאחר פטירת רב יוסף היו ארבעתם מועמדים להבחר לראש מתיבתא בפומבדיתא, ואביי נבחר לשמש ראש ישיבה (סוף הוריות). אמרו עליו שבניגוד לרבי זירא, שהיה חריף ומקשה, הוא היה: \"מתון ומסיק\" (שם), ופירש\"י: \"שהוא שוהה ומעיין יפה יפה\".","cat": "sage"},{"i": 3308,"n": "רבה בר נחמני","l": "ר","b": "הוא סתם רבה (גיטין ל\"ד ע\"ב רש\"י ד\"ה: והלכתא).","cat": "sage"},{"i": 3309,"n": "רבה בר נתן","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא (ב\"ק ל\"ב ע\"א). חברם של ר' חייא בר אבא ורב אסי. שלושתם ישבו ורב נחמן ישב לידם (עירובין ל\"ב ע\"ב). עלה לארץ ישראל ולמד שם לפני רבי יוחנן (ב\"ב קע\"ו ע\"ב). פעם נדמה לרבי יוחנן שהוא מגחך והקפיד עליו, ומת בו במקום (ירו', נזיר פ\"ז ה\"ב).","cat": "sage"},{"i": 3310,"n": "רבה בר עולא","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. חברם של אביי ורבא ושקיל וטרי עמם בהלכה (מנחות כ\"א ע\"א). חלק עם עולא (חגיגה כ\"ה ע\"ב). שקיל וטרי עם עולא (יבמות ע\"ז ע\"א). לא מוכח וגם לא נראה, שהיה בנו של עולא.","cat": "sage"},{"i": 3311,"n": "רבה בר עופרן","l": "ר","b": "מובא בבבלי (מגילה י' ע\"ב) וגירסת התוספות: \"עופרון ולא עפרון, דעפרון היה רשע ולא קוראים יהודי בשם רשע\".","cat": "sage"},{"i": 3312,"n": "רבה בר עשבי","l": "ר","b": "חי בבבל בדור השלישי לאמוראים. רב יהודה התיר לו לעשות נפה בחול המועד (מו\"ק י\"א ע\"א), ואין ראיה שנמנה על החכמים. \"יוחסין\" גורס: \"רבה בר עסבי\" ומביאו בין החכמים, וכן הביאו \"סה\"ד\" בין החכמים.","cat": "sage"},{"i": 3313,"n": "רבה בר קיריא","l": "ר","b": "אמורא ארץ ישראלי בדור השני. חברו של ר' אלעזר וטיילו יחד (ירו', כלאים פ\"ט ה\"ג). ויש גיר' אחרת: רבי בר קיריא (פ' רבתי פ' דשבת ור\"ח - ו'), ויש גורסים: ר' ברוקאי.","cat": "sage"},{"i": 3314,"n": "רבה בר רב הונא","l": "ר","b": "אמורא בבלי בדור השלישי. בנו ותלמידו המובהק של האמורא המפורסם רב הונא (ברכות נ\"ג ע\"ב). היה גם תלמידו של רב (ב\"ב קל\"ו ע\"ב). קיבל משמואל (ערכין מ\"ט ע\"א). בעצת אביו קיבל תורה מרב חסדא (שבת פ\"ב ע\"א), ואח\"כ הפך לו לתלמיד - חבר [ראיה לכך, שאת רב חמא בר גיורא מכנה: \"רבותינו\", ואת רב חסדא מכנה: \"חברינו\" (גיטין פ\"ו ע\"ב)]. רב חסדא ישב עמו יחד בדין כדיינים (שם י' ע\"א). ושניהם ביקרו את רב נחמן כשבא לסורא (סוכה י\"ד ע\"ב). נראה, שהיה בארץ ישראל וישב לפני רבי יוחנן (מנחות נ\"ט ע\"ב). היה עשיר, בעל יערות (ב\"מ ק\"ח ע\"א). היה מופלג בענוה עד שרבא התפלל שיזכה להיות עניו כמוהו (מו\"ק כ\"ח ע\"א). היה לו בן חכם ושמו רבא (חולין ע\"ו ע\"א). הוא ורב המנונא נפטרו באותו זמן ואת ארונות שניהם העלו לארץ ישראל (מו\"ק כ\"ה ע\"ב).","cat": "sage"},{"i": 3315,"n": "רבה בר רב הונא זוטא מנהרדעא","l": "ר","b": "מובא בבבלי (כתובות ס\"ט ע\"א). ע\"ע רבא בר רב הונא זוטי.","cat": "sage"},{"i": 3316,"n": "רבה בר רב יצחק","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב (יבמות ע\"א ע\"ב). אח\"כ ישב לפני רב יהודה (מנחות כ\"ו ע\"א).","cat": "sage"},{"i": 3317,"n": "רבה בר רב כהנא","l": "ר","b": "כך הגיר' בתוספות (נזיר מ\"ב ע\"ב), ולפנינו שם: \"אמר רבה אמר רב הונא\".","cat": "sage"},{"i": 3318,"n": "רבה בר רב שילא","l": "ר","b": "אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב חסדא (שבת פ\"א ע\"א). היה גם תלמידו של רב נחמן (ב\"ב קנ\"ה ע\"ב). רבי זירא קיבל ממנו (כתובות מ' ע\"א). היה דיין במקומו, ופעם אחת עירערו על פסק דינו לפני רבא, ורבא הצדיק את פסק הדין (שם ק\"ד ע\"ב). זכה לגילוי אליהו ושאל לאליהו: \"מאי קעביד הקב\"ה וכו'\" (חגיגה ט\"ו ע\"ב). לימד זכות על רבי מאיר, שלמד תורה מ\"אחר\" ואמר לאליהו הנביא: \"תוכו אכל וקליפתו זרק\", וטיעונו זה של רבה בר רב שילא התקבל בשמים (שם).","cat": "sage"},{"i": 3319,"n": "רבה בר שאילתא","l": "ר","b": "מובא בבבלי (גיטין פ\"א ע\"ב), והוא רבה בר שילא.","cat": "sage"},{"i": 3320,"n": "רבה בר שילא","l": "ר","b": "הוא רבה בר רב שילא.","cat": "sage"},{"i": 3321,"n": "רבה בר שימי א'","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף, ואמר לרבא \"מר לא אמר הכי, ומנו, רב יוסף\" (חולין כ\"ט ע\"ב). היה גם תלמידו של רב חסדא (שם ק\"ב ע\"א).","cat": "sage"},{"i": 3322,"n": "רבה בר שימי ב'","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא, כדמצינו שא\"ל רבנן לרבינא: \"ודילמא וכו' ואמר להו רבה בר שימי בפירוש אמר מר וכו'\" (קידושין מ\"ה ע\"ב), ופרש\"י: \"מר - רבינא\". אך קשה להניח שרבה בר שימי האריך ימים הרבה והיה תלמידו של רב יוסף (חולין כ\"ט ע\"א), שחי בדור השלישי, ותלמידו של רבינא שחי בדור הששי, ולכן כתב \"יוחסין\" ששניים היו, ו\"סה\"ד\" כתב: \"לא ידעתי מנ\"ל שהיו שנין או משום שדיבר עם רב יוסף ועם רבינא וכו' אין הכרח שמא האריך ימים\", עכ\"ל. אך גם אם נניח שהאריך ימים, לא סביר שאמורא בדור הרביעי ידבר לרבינא בדור הששי כדבר תלמיד לרבו, ולכן הסקתי ששנים היו.","cat": "sage"},{"i": 3323,"n": "רבה בר שמואל","l": "ר","b": "אמורא בבלי בדור השלישי. זכה להיות תלמידו של רב (יומא ל\"ו ע\"ב). וכן היה תלמידו של רב חסדא (חולין ק\"כ ע\"א). היה מן התנאים השונים ובקיאים בברייתות. אף רב חסדא רבו שאלו: \"אשכחית רב חסדא א\"ל: 'תנית מידי באיסורי הנאה', א\"ל: 'אין תנינא וכו'\" (ב\"ק צ\"ח ע\"ב). כן שאלו רב ששת כמה פעמים: \"אשכחיה רב ששת א\"ל: 'תני מר מידי בצורת הפתח וכו'\" (עירובין י\"א ע\"ב ועוד). הגמרא מקשה כמה פעמים: \"והתני רבה בר שמואל וכו'\" (שם צ\"ז ע\"א, ועוד). \"יוחסין\" כתב שהיה בנו של שמואל (בר פלוגתיה של רב).","cat": "sage"},{"i": 3324,"n": "רבה בר תחליפא","l": "ר","b": "אמורא בבלי בדור השני - השלישי. מסר משם רב (שבת ק\"כ ע\"ב). כן היה תלמידו של רב ירמיה בר אבא (חולין מ\"ה ע\"ב).","cat": "sage"},{"i": 3325,"n": "רבה בריה דרבא","l": "ר","b": "מובא בבבלי (מגילה כ\"ב ע\"א) רבה בריה דרבא, וצ\"ל רבא בריה דרבה (ע\"ע).","cat": "sage"},{"i": 3326,"n": "רבה דבי רב שילא","l": "ר","b": "מובא בבבלי (שבת ז' ע\"א), והוא רבה בר שילא.","cat": "sage"},{"i": 3327,"n": "רבה זוטי","l": "ר","b": "אמורא בבלי בדור הששי. חברו ובר פלוגתיה של רב אשי ושקיל וטרי עמו הרבה (ב\"ב ק\"כ ע\"א). כן שקיל וטרי עם רבינא (בכורות ל\"ו ע\"א).","cat": "sage"},{"i": 3328,"n": "רבה מקובי","l": "ר","b": "אמורא בבלי בדור השביעי. מושבו בעיר מקובי. מר בר רב אשי קנה סודר מאמו שוי עשרה בתליסר (קידושין ח' ע\"א). \"יוחסין\" ו\"סה\"ד\" גרסו: רבה מקובריה, ולגירסתם מר בר רב אשי קנה מרבה מקובריה את הסודר, ולא מאמו.","cat": "sage"},{"i": 3329,"n": "רבה ריחומי","l": "ר","b": "מובא בבבלי (מנחות ל\"ג ע\"ב), והוא ר' רחומי ג' מרבנן סבוראי.","cat": "sage"},{"i": 3330,"n": "רבה תוספתא","l": "ר","b": "אמורא בבלי בדור השביעי - השמיני. עמד בראש ישיבת סורא אחרי מר בר רב אשי בשנים ד' רכ\"ז - רל\"ג (764 - 374) (\"אגרת רב שרירא גאון\"). נראה, שהיה תלמידו של רבינא (חברו של רב אשי), שמצינו שהקשה לרבינא והוא השיב לו (סוכה ל\"ב ע\"א), וכן שקיל וטרי עמו (ב\"ב ס\"ד ע\"א). מובאת ממנו הלכה אחת שחידש באשה שהלך בעלה למדינת הים (יבמות פ' ע\"ב). נראה שבימיו כבר היה התלמוד בגמר עריכתו, והוא הוסיף עליו, ויתכן שלכן כינוהו רבה תוספתא.","cat": "sage"},{"i": 3331,"n": "רבי","l": "ר","b": "הוא רבי יהודה הנשיא.","cat": "sage"},{"i": 3332,"n": "רביא בר קיסי","l": "ר","b": "אמורא בבלי בדור הששי. נפטר בזמן שרבינא חלק עם רבי ירמיה מדיפתא, ושמו של רביא בר קיסי שימש להם כסימן במחלוקתם (יומא מ\"ב ע\"א), ואולי הוא רבין בר קיסי (ע\"ע).","cat": "sage"},{"i": 3333,"n": "רבין (2)","l": "ר","b": "אמורא בדור השלישי - הרביעי. נולד כנראה בבבל (\"אגרת רב שרירא גאון\"). היה יתום, כדברי עצמו: \"פטור אני מכיבוד אב ואם\"; כשעיברתו אמו מת אביו, וכשילדתו מתה (ירו', קידושין פ\"א ה\"ז). בצעירותו למד בא\"י בבית מדרשו של ר' יוחנן (קידושין מ\"ד ע\"א). היה מצוי כל שעה לפני רבי יוחנן (יבמות ס\"ד ע\"ב - רש\"י). היה גם תלמידו של רבי אבהו (פסחים פ\"ד ע\"א). מחשובי ה\"נחותי\", שתפקידם היה להביא מתורת א\"י לבבל ומבבל לא\"י. בזמן אביי ורבא, כשנתרבו הגזרות בא\"י, ירדו רבין ורב דימי ונחותי אחרים לבבל (\"אגרת רב שרירא גאון\"), ויתכן שלכך מתכוונת הגמרא: \"כי אתא רבין וכל נחותי וכו'\" (חולין קכ\"ד ע\"א). מסר בשם חכמי ארץ ישראל: \"כי אתא רבין, אמר: 'מתיב ר' יוסי בר חנינא'\" (נדה י\"ח ע\"ב); \"כי אתא רבין, אמר: 'ר' חייא בר אבא אמר ר' יוחנן'\" (קידושין ע\"ה ע\"ב). פעמים, הבהיר את דברי ר' דימי שגם הוא היה מ\"נחותי\", כגון: \"כי אתא ר' דימי, אמר ר' יוחנן: 'שלוש לשונות שמעתי וכו' ואין לי לפרש' [ואיני יודע לפרש], כי אתא רבין, פירשה משמיה דר' יונתן\" (יומא מ\"א ע\"ב). במסרו את תורת חכמי א\"י בבואו לבבל סמכו על דבריו. אביי נתן בו אמון רב וחשבו לבר סמכא (יבמות ס\"ד ע\"ב). כן הביא עמו לא\"י מאמרים של חכמי בבל: \"רבי אבין [רבין] בשם רבנן דתמן [בבל]\" (ירו', פאה פ\"ז ה\"ג). נהג לעלות לא\"י ולשוב מפעם לפעם. בשבתו בא\"י היה שולח איגרות לבבל: \"דשלח רבין משמיה דרבי אבהו\" (גיטין ט' ע\"ב).","cat": "sage"},{"i": 3334,"n": "רבין בר אבא","l": "ר","b": "אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (חולין פ\"ו ע\"א).","cat": "sage"},{"i": 3335,"n": "רבין בר חיננא","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב חסדא (כתובות נ\"ג ע\"א). אמר משם רבי אלעזר (שם). אמר לרבי זירא: \"הכי אמר עולא\" (חולין קכ\"ב ע\"א). הגיע לזקנה מופלגת, שכן רב אשי קיבל ממנו (פסחים ק\"ט ע\"ב). פעם התדיינו הוא ואחיו רב דימי בר חיננא לפני רבא (ב\"ב י\"ג ע\"ב).","cat": "sage"},{"i": 3336,"n": "רבין בר חנינא","l": "ר","b": "מובא בבבלי (כתובות נ\"ג ע\"א). ע\"ע רבין בר חיננא.","cat": "sage"},{"i": 3337,"n": "רבין בר כהנא","l": "ר","b": "הוא אבין בר כהנא.","cat": "sage"},{"i": 3338,"n": "רבין בר ממל","l": "ר","b": "מובא בירושלמי (ב\"מ פ\"ה ה\"ה), וגירסת \"סה\"ד\" שהוא אבא בר ממל.","cat": "sage"},{"i": 3339,"n": "רבין בר קיסי","l": "ר","b": "אמורא בבלי בדור החמישי. מרבותיו של רבינא (חולין כ' ע\"ב).","cat": "sage"},{"i": 3340,"n": "רבין בר רב אדא","l": "ר","b": "אמורא בבלי בדור השלישי. למד עם רבא בר רב אדא (נראה שהיה אחיו), ושניהם למדו יחד בבית מדרשו של רב יהודה (ביצה ל\"ג ע\"ב).","cat": "sage"},{"i": 3341,"n": "רבין בר רב חסדא","l": "ר","b": "אמורא ארץ ישראלי בדור השני. הביא גט לפני רבי יוחנן (גיטין ה' ע\"ב). יש ממנו מאמרי אגדה (ב\"ר פי\"א - ב').","cat": "sage"},{"i": 3342,"n": "רבין בר שבא","l": "ר","b": "אמורא בדור השלישי. מרבותיו של רבא (חולין מ\"ח ע\"א). מאמרו: \"משעלו בני הגולה פסקו הזיקין\" (שם פ\"ו ע\"א).","cat": "sage"},{"i": 3343,"n": "רבין בר שמואל","l": "ר","b": "אמורא בבלי בדור השני. מסר בשם שמואל (ב\"ב מ\"ג ע\"א).","cat": "sage"},{"i": 3344,"n": "רבין בריה דרב נחמן","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו החביב של רב יהודה, שפנה אליו בלשון חיבה: \"אחי\" (ב\"מ ק\"ז ע\"א). עמד בקשר עם רב ששת (יבמות ק\"ט ע\"ב).","cat": "sage"},{"i": 3345,"n": "רבין דמן נרש","l": "ר","b": "חי בבבל בדור הששי לאמוראים. מצינו שעשה רפואה לבתו של רב אשי ונתרפאה (גיטין ס\"ט ע\"ב). אינו בהכרח חכם.","cat": "sage"},{"i": 3346,"n": "רבין חסידא","l": "ר","b": "זמנו ומקומו אינם ידועים, מצינו שהלך לקדש אשה לבנו וקדשה לנפשיה (קדושין נ\"ט ע\"א).","cat": "sage"},{"i": 3347,"n": "רבין סבא א'","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (קידושין נ\"ג ע\"ב). \"דק\"ס\" משנה הגירסאות וסובר, שרק רבין סבא אחד היה, תלמידו של רב פפא.","cat": "sage"},{"i": 3348,"n": "רבין סבא ב'","l": "ר","b": "אמורא בבלי בדור הששי. תלמידו של רב פפא (ב\"ב קמ\"ו ע\"ב). ע\"ע רבין סבא ב'.","cat": "sage"},{"i": 3349,"n": "רבין תכלא","l": "ר","b": "מובא בבבלי (חולין ק\"י ע\"א), והוא רבין. ופרש\"י: \"קובר בניו היה\" (פסחים ע' ע\"ב ד\"ה: אבין).","cat": "sage"},{"i": 3350,"n": "רבינא (2)","l": "ר","b": "מגדולי אמוראי בבל בדור הששי. בנעוריו היה תלמידו המובהק של רבא (ב\"ב ט\"ז ע\"ב). הקשה לרבא ורבא איכסיף (ע\"ז כ\"ב ע\"א). בחיי רבא הגיע להוראה (עירובין מ' ע\"א), ולמד יחד עם רב פפא לפני רבא (זבחים ב' ע\"ב), ובכל זאת היה לתלמיד - חבר לרב אשי (עירובין ס\"ג ע\"א) שמעולם לא ראה את רבא (קידושין ע\"ב ע\"ב), ושניהם שקלו וטרו בכל הש\"ס, ולהם מיוחסת עריכת התלמוד: \"רב אשי ורבינא סוף הוראה\" (ב\"מ פ\"ו ע\"א) - נראה, שהכוונה שאז התחילו לערוך ולסדר את התלמוד, שכן התלמוד נחתם בשנת ד' ר\"ס (005). מושבו היה במתא מחסא (ליד סורא), כמו שכתב רש\"י (יומא פ\"ו ע\"א ד\"ה: ומתא מחסא), וגם מקומו של רב אשי היה שם (ברכות י\"ז ע\"ב), ורש\"י כתב שרבינא מארץ ישראל היה (מנחות מ\"ב ע\"א ד\"ה: חד) נפטר 07 שנה אחרי רבא, בשנת ד' קפ\"א (124) (ספר כריתות - ויטרי).","cat": "sage"},{"i": 3351,"n": "רבינא בר אבינא","l": "ר","b": "מובא בויק\"ר (פ\"ד - ג'), ונראה שצ\"ל: רבי ביבי בר אבינא.","cat": "sage"},{"i": 3352,"n": "רבינא בר ירמיה","l": "ר","b": "אמורא בבלי בדור השביעי. רב סמא בריה דרב אשי הקשה לו (ע\"ז נ' ע\"ב). \"דק\"ס\" מחק תיבת בר ירמיה.","cat": "sage"},{"i": 3353,"n": "רבינא בר סילא","l": "ר","b": "מובא בבבלי (זבחים ל\"ו ע\"ב), וצ\"ל: רבינא בר שילא.","cat": "sage"},{"i": 3354,"n": "רבינא בר סיסי","l": "ר","b": "מובא ב\"ילקוט\" (איוב רמז תתקכ\"ג).","cat": "sage"},{"i": 3355,"n": "רבינא בר קיסי","l": "ר","b": "מובא בבבלי (ב\"ב ס\"ג ע\"א), ואולי הוא רביא בר קיסי (ע\"ע).","cat": "sage"},{"i": 3356,"n": "רבינא בר שילא","l": "ר","b": "אמורא בבלי בדור הראשון. רב חסדא קיבל ממנו (מו\"ק י\"ט ע\"ב).","cat": "sage"},{"i": 3357,"n": "רבינא בריה דר' עולא","l": "ר","b": "מובא בבבלי (ביצה ג' ע\"ב). \"סה\"ד\" סבור, שהוא ר' בנאה בריה דר' עולאי.","cat": "sage"},{"i": 3358,"n": "רבינא זוטי","l": "ר","b": "אמורא בבלי בדור השביעי, ואולי הוא רבינא האחרון, שהוא רבינא בר רב הונא. היה בן אחות רבינא, והיה יתום, והחזיק ברשותו את חמוריו (כתובות ק' ע\"ב).","cat": "sage"},{"i": 3359,"n": "רבינא מפרזקיא","l": "ר","b": "אמורא בבלי בדור השביעי. הקשה לרב אשי (נזיר ל\"ח ע\"ב). אולי צ\"ל: רבא מפרזיקא.","cat": "sage"},{"i": 3360,"n": "רבינו הקדוש","l": "ר","b": "הוא רבי יהודה הנשיא.","cat": "sage"},{"i": 3361,"n": "רבמי","l": "ר","b": "מובא בירושלמי (ע\"ז פ\"ה הי\"א), והוא רבי אמי.","cat": "sage"},{"i": 3362,"n": "רבנא אשי","l": "א","b": "מובא בבבלי (כתובות כ\"ב ע\"א), והוא רב אשי.","cat": "sage"},{"i": 3519,"n": "רבנא נחמיה (2)","l": "נ","b": "ע\"ע רבנא נחמיה.","cat": "sage"},{"i": 3520,"n": "רבנא נחמיה אחוה דריש גלותא","l": "נ","b": "מובא בבבלי (שבת כ' ע\"ב), שרבין ואביי ישבו לפניו. נראה, שהוא רבנא נחמיה בר ברתיה דרב.","cat": "sage"},{"i": 3521,"n": "רבנא נחמיה בן ברתא דרב","l": "נ","b": "אמורא בבלי בדור השלישי. עליו ועל אחיו עוקבא אמרו שהם \"שרי גאים היוצאים מישראל\" (חולין צ\"ב ע\"א), ואולי היו מתלמידיו של רב חסדא (ב\"ב נ\"א ע\"ב). נראה, שהוא רבנא נחמיה אחוה דריש גלותא, שאביי ישב לפניו (שבת כ' ע\"ב).","cat": "sage"},{"i": 3534,"n": "רבנא עוקבא (2)","l": "ע","b": "אמורא בבלי בדור השלישי. הוא ואחיו רבנא נחמיה, היו בני בתו של רב, ושניהם מכונים: \"שרי גאים היוצאים מישראל\" (חולין צ\"ב ע\"א). הוא ואחיו רבנא נחמיה אמרו לרב חסדא: \"שביק מר רברבי ועבוד כזוטרי\" (ב\"ב נ\"א ע\"ב), אך אין בכך ראיה שהיו תלמידיו, ואפשרי שהיו חבריו ואין ראיה ממה שמצינו: \"אדבריה רב חסדא לרבנא עוקבא\" (ביצה כ\"ט ע\"א). פרש\"י: \"הנהיג ומטייל עמו במבואות העיר\".","cat": "sage"},{"i": 3535,"n": "רבנא עוקבא בר ברתיה דרב","l": "ע","b": "ע\"ע רבנא עוקבא.","cat": "sage"},{"i": 3536,"n": "רבנא עוקבא ורבנא נחמיה בני ברתיה דרב","l": "ע","b": "ע\"ע רבנא נחמיה בן ברתא דרב; רבנא עוקבא.","cat": "sage"},{"i": 3554,"n": "רבנאי","l": "ר","b": "אמורא בבלי בדור השביעי. מובא בבבלי, שאמר משמיה דאביי (ברכות ל\"ח ע\"ב).","cat": "sage"},{"i": 3555,"n": "רבנאי אחוה דר' חייא בר אבא","l": "ר","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי (כתובות כ\"א ע\"ב), והוא רב ינאי אחוה דר' חייא בר אבא.","cat": "sage"},{"i": 3556,"n": "רבנאי חוזאי","l": "ר","b": "אמורא ארץ ישראלי בדור הראשון - השני. אחיו היה רב תחליפא: \"רב תחליפא אחוה דרבנאי חוזאה\" (ביצה ט\"ו ע\"ב). רבי אבהו הוסיף על דבריו.","cat": "sage"},{"i": 3557,"n": "רבסי","l": "ר","b": "מובא בירושלמי (ע\"ז פ\"ה הי\"א), והוא רבי אסי.","cat": "sage"},{"i": 3558,"n": "רבי רדיפה","l": "ר","b": "אמורא ארץ ישראלי בדור הששי. מסר הרבה משם רבי יונה (ירו', פאה פ\"ד ה\"ה).","cat": "sage"},{"i": 3559,"n": "רובין","l": "ר","b": "כינוי ליהודה וחזקיה, בניו של רבי חייא (חולין כ' ע\"א).","cat": "sage"},{"i": 3560,"n": "רבי רומנוס","l": "ר","b": "מהתנאים האחרונים או מהאמוראים הראשונים. תלמידו של רבי: \"א\"ר רומנוס 'לי התיר רבי לטלטל'\" (שבת מ\"ז ע\"א). רבי שלחו לאנטונינוס קיסר (ירו', מגילה פ\"א הי\"א), וכן שלחו לעיר אחת בארץ ישראל (יבמות ס' ע\"ב).","cat": "sage"},{"i": 3561,"n": "רחבא","l": "ר","b": "הוא רחבא דפומבדיתא.","cat": "sage"},{"i": 3562,"n": "רחבא דפומבדיתא","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו המובהק של רב יהודה (פסחים נ\"ב ע\"ב), והיה מדקדק בלשון רבו וקבע לעצמו סימנים (ברכות ל\"ג ע\"ב רש\"י). התחתן עם חומה בת איסי (נכדתו של רב יהודה), ואחרי פטירתו התחתנה חומה עם רב יצחק בריה דרבה בר בר חנה, ואחרי שהוא נפטר התחתנה עם אביי, וגם הוא מת בחייה (יבמות ס\"ד ע\"ב). רחבא הניח שני בנים חכמים, איפא ואבימי, שנקראו \"חריפי שפומבדיתא\" (סנהדרין י\"ז ע\"ב), או \"בני רחבא\" (שבת ק\"ג ע\"א). \"סה\"ד\" כתב: \"ונראה דאיפא ואבימי לא היו מן אשתו חומה\".","cat": "sage"},{"i": 3563,"n": "ר' רחומאי","l": "ר","b": "חי בזמן התנאים בדור הרביעי. מובא ב\"זוהר\", שהיה זקן מאד ועיניו כהות, ואמר לר' פנחס: \"שמעתי שלרבי שמעון [בן יוחאי] יש מרגלית אבן טובה [בנו רבי אלעזר בר שמעון]\" (הקדמה י\"א).","cat": "sage"},{"i": 3564,"n": "רב רחומי א'","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של אביי (פסחים ל\"ט ע\"א). תלמידו המובהק של רבא (כתובות ס\"ב ע\"ב), ונפטר בחייו. מסופר, שבכל ערב יום כיפור היה שב לביתו מישיבתו של רבא, ופעם נמשך אחרי לימודו ולא חזר לביתו, ואשתו ציפתה לשובו וכל הזמן אמרה: עכשיו יבוא עכשיו יבוא, ולא בא, והתחילה לבכות, ובאותה שעה ישב רב רחומי בקומה שניה, ונשברה הרצפה תחתיו ונפל ומת (כתובות ס\"ב ע\"ב).","cat": "sage"},{"i": 3565,"n": "רב רחומי ב'","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רבינא (חברו של רב אשי): \"יתיב רב רחומי קמיה דרבינא, ויתיב וקאמר משמיה דרב הונא בר תחליפא\" (זבחים ע\"ז ע\"א). עמד בראש ישיבת פומבדיתא אחרי רפרם בשנים ד' ר\"ב - ר\"ח (244 - 844). בסוף ימיו היו גזרות חמורות מהמלך יזדגרד (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 3566,"n": "רב רחומי ג'","l": "ר","b": "מאמוראי בבל האחרונים בדור השמיני. נמנה עם חכמי רבנן סבוראי (\"אגרת רב שרירא גאון\"). דבריו מובאים בתלמוד (עירובין י\"א ע\"א). חלק עם רב יוסף, גם הוא מרבנן סבוראי (שם), ומובא לפניו.","cat": "sage"},{"i": 3567,"n": "רב רחומי מבירתא דשחורי","l": "ר","b": "כן הביא ה\"אור זרוע\" (מגילה כ\"א ע\"ב).","cat": "sage"},{"i": 3568,"n": "ר' רימון","l": "ר","b": "כן גיר' \"סה\"ד\" ממדרש שמואל (רפי\"ג), ולפנינו: ר' סימון.","cat": "sage"},{"i": 3569,"n": "ריש לקיש","l": "ר","b": "הוא רבי שמעון בן לקיש.","cat": "sage"},{"i": 3570,"n": "רכיש בר פפא","l": "ר","b": "אמורא בבלי בדור השני. מסר משם רב (חולין מ\"ב ע\"ב).","cat": "sage"},{"i": 3571,"n": "רמי בר אבא א'","l": "ר","b": "אמורא בבלי בדור השני - השלישי. תלמידו של רב הונא (עירובין ס\"א ע\"א). נראה, שהיה בארץ ישראל וקיבל מרבי אסי (שם ק' ע\"ב). היה רבו של רב יוסף (שם ס\"א ע\"א). סיפר על תקנות שרבי יוסי (בר חלפתא) התקין בציפורי (סנהדרין י\"ט ע\"א). אילולי ידענו שרמי בר אבא אמור, וחי דורות אחרי רבי יוסי בר חלפתא, היינו מדמים בטעות שהוא מספר את שראה. יש ממנו כמה מאמרי אגדה בתלמוד (נדרים ל\"ב ע\"א), ושם יש גורסים: ר' אמי בר אבא.","cat": "sage"},{"i": 3572,"n": "רמי בר אבא ב'","l": "ר","b": "אמורא בבלי בדור הששי. מובא בבבלי: \"אתא לקמיה דרב פפא ואסר ליה\" (מגילה כ\"ו ע\"ב). קשה לומר שזה רמי בר אבא תלמידו של רב הונא.","cat": "sage"},{"i": 3573,"n": "רמי בר אבא חמוה דרב אשי","l": "ר","b": "מובא בבבלי (חולין קי\"א ע\"ב).","cat": "sage"},{"i": 3574,"n": "רמי בר אבין","l": "ר","b": "אמורא בבלי. נראה שהיה בדור השלישי, בזמנו של רב יוסף. דבריו מובאים אחרי רב יוסף: \"אלא אמר רב יוסף: 'שוכא דארזא'. רמי בר אבא אמר: 'זאזא'\" (שבת כ' ע\"ב).","cat": "sage"},{"i": 3575,"n": "רמי בר ברבי","l": "ר","b": "מובא בבבלי: \"נהרבלאי\" (סנהדרין י\"ז ע\"ב), והכוונה לרמי בר ברבי. רש\"י גרס: רמי בר ברוכי (ביצה ח' ע\"ב ד\"ה: נהרבלאי; וכן גירסת ה\"ערוך\" בערך נהר).","cat": "sage"},{"i": 3576,"n": "רמי בר ברוכי","l": "ר","b": "(ע\"ע רמי בר ברבי).","cat": "sage"},{"i": 3577,"n": "רמי בר דיקולי","l": "ר","b": "מובא בבבלי, והוא רמי בר תמרי (יבמות פ' ע\"א).","cat": "sage"},{"i": 3578,"n": "רמי בר חמא","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (עירובין ח' ע\"ב). הוא ואחיו רב עוקבא בר חמא נשאו לנשים את בנות רב חסדא (ברכות מ\"ד ע\"א). למד יחד עם רבא לפני רב חסדא (ב\"ב י\"ב ע\"ב). נפטר בחיי רבא (ברכות מ\"ז ע\"ב). אשתו התחתנה אח\"כ עם רבא (יבמות ל\"ד ע\"ב, ושם רש\"י ותוס'). בהיות בת רב חסדא ילדה קטנה התנבאה שרוצה להתחתן עם שניהם (ב\"ב י\"ב ע\"ב). הצטיין בחריפות (עירובין צ' ע\"א; ב\"ב קט\"ז ע\"ב; ב\"מ צ\"ו ע\"ב). רב ירמיה קרא לו: גברא רבא (עירובין צ' ע\"א). מסופר, שרב יצחק בר יהודה היה רגיל ללמוד אצל רמי בר חמא, ועבר ללמוד אצל רב ששת, והסביר לרמי בר חמא שעזבו, מפני שמתרץ מסברא, ורב ששת מתרץ ומביא ברייתות לסיוע (זבחים צ\"ו ע\"ב). היו לו שתי בנות: אחת היתה אמו של האמורא אמימר (כתובות כ\"א ע\"ב), ואחת התחתנה עם רב אשי (ביצה כ\"ט ע\"ב).","cat": "sage"},{"i": 3579,"n": "רמי בר יחזקל","l": "ר","b": "אמורא בבלי בדור השני. אחיו של רב יהודה האמורא המפורסם. כשלמד לפני אביו רב יחזקל תיקן אחיו רב יהודה לאביו, ושמואל העיר לו שלא יתקן לאביו (קידושין ל\"ב ע\"א). למד גם לפני רב (חולין מ\"ד ע\"א) ולפני שמואל (כתובות ס' ע\"א). ביקר בארץ ישראל (שם קי\"א ע\"ב), וחזר משם: \"כי אתא רמי בר יחזקל, אמר: 'לא תציתינהו להני כללי דכייל יהודה אחי משמיה דשמואל'\" (שם כ\"א ע\"א).","cat": "sage"},{"i": 3580,"n": "רמי בר פפא","l": "ר","b": "אמורא בבלי בדור השלישי. שאל לרב יהודה בעמדו על שפת נהר אמברא, ורב יהודה עמד בעבר השני (יומא ע\"ז ע\"ב). אחותו נישאה לרב אויא, ומתה בחיי רב אויא (ב\"ב ק' ע\"ב). ואמר רב יוסף עליו שטעה בשני דברים (שם).","cat": "sage"},{"i": 3581,"n": "רמי בר רב","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (שבת ל\"ב ע\"ב).","cat": "sage"},{"i": 3582,"n": "רמי בר רב יוד","l": "ר","b": "אמורא בבלי בדור השני. תלמידו של רב (פסחים ס\"ב ע\"ב). ע\"ע רמי בר רב יודא.","cat": "sage"},{"i": 3583,"n": "רמי בר רב יודא","l": "ר","b": "כך מובא בבבלי: \"רמי בר רב יודא אמר רב\" (זבחים נ\"ה ע\"ב). \"דק\"ס\" גרס: רב יוד, ו\"סה\"ד\" חילקם לשניים: רב יוד (תענית כ\"ב ע\"ב) ורב יודא וא\"כ, שניהם היו לדעת \"סה\"ד\" תלמידיו של רב, ורש\"י פירש: \"חכם ששמו יוד\" (תענית, שם). וכן: \"רמי בר רב יודא אמר רב\" (פסחים ס\"ב ע\"ב).","cat": "sage"},{"i": 3584,"n": "רמי בר שמואל","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא. יחד עם חברו רב יצחק בריה דרב יהודה למדו מסכת נדה בישיבת רב הונא ושמע רבה בנו של רב הונא שלמדו וכו', הלך ואמר לרב הונא וכו' (נדה י\"ז ע\"ב). היה חברו של רב נחמן ואמר לו לר\"נ על פסק דינו: \"א\"כ נמצאת מכשילן לעתיד לבוא וכו'\" (כתובות צ\"ז ע\"א).","cat": "sage"},{"i": 3585,"n": "רמי בר תמרי","l": "ר","b": "אמורא בבלי בדור השלישי. תלמידו של רב יהודה (חולין ק\"י ע\"א) והוא רמי בר דיקולי (שם). היה חריף ושקיל וטרי עם רב חסדא שאמר לו: \"חזינא לך דחריפא טובא\". היה גם תלמידו של ר\"ז (מנחות כ\"ט ע\"ב).","cat": "sage"},{"i": 3586,"n": "רמי בריה דרב ייבא","l": "ר","b": "אמורא בבלי. נראה, שהיה בזמנו של אביי או אחריו (ערכין י\"א ע\"ב).","cat": "sage"},{"i": 3587,"n": "רפרם","l": "ר","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי (כתובות צ\"ה ע\"ב). חברו של רבינא האחרון: \"רבינו סבר לאכשורי וכו' אמר ליה רפרם וכו'\" (גיטין י\"א ע\"א). אחרי רב גביהה מבי כתיל עמד בראש ישיבת פומבדיתא בשנים ד' קצ\"ב - ד' ר\"ב (234 - 244). רב אבהו האחרון היה מראשי כלה בישיבתו: \"אמר רב שמואל בריה דרב אבהו [היה מראשוני רבנן סבוראי]: 'אבא מרישי כלי דרפרם הוה'\" (חולין מ\"ט ע\"א).","cat": "sage"},{"i": 3588,"n": "רפרם בר פפא א'","l": "ר","b": "אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (שבת פ\"ב ע\"א) ותירגם קמיה. ומצינו: \"אמר רפרם בר פפא אמר רב חסדא וכו', א\"ל רבא לרפרם בר פפא: 'מנא ליה לסבא הא וכו'\" (נדה ס\"א ע\"ב). היה קשיש מרבא: \"א\"ל רבא [לרפרם בר פפא]: 'לימא לן מר מהני מילי מעלייתא דאמרת משמיה דרב חסדא'\" (ברכות ח' ע\"א), הכיר את רב הונא ורבא אמר לו: \"לימא לן מר מהני מילי מעליתא דהוה עביד רב הונא\" (תענית כ' ע\"א).","cat": "sage"},{"i": 3589,"n": "רפרם בר פפא ב'","l": "ר","b": "אמורא בדור החמישי נראה תלמידו של רבא, ורבא קראו לו: \"פתיא אוכמא\" (ברכות נ' ע\"א), ופרש\"י: \"כלי חרס\". נראה, שהוא רפרם המוזכר שמלך בפומבדיתא בשנים ד' קמ\"ד - קנ\"ד (483 - 493) אחר רב דימי מנהרדעא (\"אגרת רב שרירא גאון\").","cat": "sage"},{"i": 3590,"n": "רפרם בר פפא מסיכרא","l": "ר","b": "מובא בבבלי (פסחים ל\"א ע\"ב). מצינו אותו ענין \"רפרם מסיכרא\" (ב\"מ מ\"ב ע\"א) ופרש\"י: \"שם מקום\".","cat": "sage"},{"i": 3591,"n": "רפרם מסיכרא","l": "ר","b": "מובא בבבלי (ב\"מ מ\"ב ע\"א), ובמקום אחר הגיר': רפרם בר פפא מסיכרא (פסחים ל\"א ע\"ב).","cat": "sage"},{"i": 3629,"n": "רבי שאול","l": "ש","b": "אמורא ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא בירושלמי: \"רבי זירא בעי וכו' א\"ר שאול וכו'\" (מעשרות פ\"ג ה\"ב), ואין ראיה מכך שהיה בזמנו של רבי זירא. \"יוחסין\" כתב: \"ר' שאול בזמן ר' זירא\" (נראה, שהסתמך על המקור הנ\"ל), ו\"סה\"ד\" כתב: \"לא מצאתי\".","cat": "sage"},{"i": 3630,"n": "ר' שאול דנוה","l": "ש","b": "מובא בקה\"ר (פי\"ב - י').","cat": "sage"},{"i": 3631,"n": "רב שבא","l": "ש","b": "אמורא בבלי. \"יוחסין\" כתב, שהיה בזמן רבא (דור רביעי לאמוראים). מצינו: \"א\"ל רב שבא לרב כהנא\" (הוריות ה' ע\"ב).","cat": "sage"},{"i": 3632,"n": "שבור מלכא","l": "ש","b": "כינוי לשמואל (פסחים נ\"ד ע\"א). ויש אומרים (שם) שהוא כינוי לרבא (ו\"מסה\"ש\" כתב: רבה). הרשב\"ם פירש: \"שמואל, קרי ליה רבא שבור מלכא [רבא קרא לו שבור מלכא] משום דבקי היה בדינין, והלכתא כוותיה בדיניה, כדין היוצא מפי המלך שמתקיים, ושבור מלכא, מלך פרסיים היה בימי רבא\". ע\"ע אריוך.","cat": "sage"},{"i": 3633,"n": "שבנא אחי הלל","l": "ש","b": "אחיו של הלל הנשיא. עסק במסחר, ורצה לפרנס את הלל ולהיות שותף ללימודו של הלל, ויצאה בת קול ומנעה את העיסקה (סוטה כ\"א ע\"א). אין ראיה שנמנה עם החכמים.","cat": "sage"},{"i": 3634,"n": "שבנא איש ירושלים","l": "ש","b": "מובא בבבלי (שבת י\"ב ע\"ב), ופרש\"י: \"אדם גדול היה\".","cat": "sage"},{"i": 3635,"n": "ר' שבתאי","l": "ש","b": "ע\"ע ר' שבתי.","cat": "sage"},{"i": 3636,"n": "ר' שבתי","l": "ש","b": "אמורא ארץ ישראלי בדור הראשון - השני. תלמידו של רבי יצחק מגדלאה (נדה כ\"ז ע\"ב), הגמרא מפקפקת שם מי אמר בשם מי - ר' יצחק מגדלאה בשם ר' שבתי או ר' שבתי בשם ר' יצחק מגדלאה. רבי יוחנן וריש לקיש דנו במאמרו (שם). שמו של ר' שבתי שובש בכמה פנים: שבתאי, שובתיי, שובתי. תוספות כתבו, שצריך לגרוס \"שבתי\", כי שבתאי הוא שם עכו\"ם (גיטין י\"א ע\"א), ואכן מצינו, שהיה רשע ושמו שבתאי (יומא פ\"ב ע\"ב).","cat": "sage"},{"i": 3637,"n": "שבתי בריה דר' מרינוס","l": "ש","b": "חי בארץ ישראל בדור הראשון לאמוראים. ביקר בבבל (ביצה ל\"ב ע\"ב), ושם אולי מוכח שהיה מן החכמים, אך מצינו שכתב לכלתו בכתובתה לבוש של משי, וכשאבדה כתובתה אמר: \"לא היו דברים מעולם\" (ב\"מ י\"ז ע\"א). אם כן, קצת קשה לומר שהיה מן האמוראים. ולפי גיר' הרי\"ף והרא\"ש (שם) יתכן לומר שהיה מן החכמים.","cat": "sage"},{"i": 3638,"n": "שובחה","l": "ש","b": "מובא בבבלי (ב\"ק צ\"א ע\"ב). ע\"ע שכחת.","cat": "sage"},{"i": 3639,"n": "ר' שובתי","l": "ש","b": "ע\"ע ר' שבתי.","cat": "sage"},{"i": 3640,"n": "ר' שובתי הצדוקי","l": "ש","b": "אמורא ארץ ישראלי בדור השני. רבי אלעזר הורה לו כמו שאמר רבי שמעון בן שזורי (ירו', שבועות פ\"ב ה\"ה).","cat": "sage"},{"i": 3641,"n": "ר' שובתיי","l": "ש","b": "ע\"ע ר' שבתי.","cat": "sage"},{"i": 3642,"n": "שוקד","l": "ש","b": "ע\"ע שקוד.","cat": "sage"},{"i": 3643,"n": "שיבחה ברי","l": "ש","b": "מובא בבבלי (ב\"ק צ\"א ע\"ב). ע\"ע שכחת.","cat": "sage"},{"i": 3644,"n": "רב שיזבי","l": "ש","b": "אמורא בבלי בדור הרביעי. רב חסדא נהג לעבור ליד ביתו של אביו של רב שיזבי, וכשראה שהיה מדליק נרות רבים לכבוד שבת, אמר: אדם גדול יצא מכאן, ונולד לו רב שיזבי (שבת כ\"ג ע\"ב). היה תלמידם של רב חסדא (שם ק\"כ ע\"א) ושל רב הונא (בכורות י\"א ע\"א). קיבל גם מרבא (ב\"מ קי\"ד ע\"ב). רבא אמר עליו: \"גברא רבא\" (גיטין נ\"ה ע\"ב).","cat": "sage"},{"i": 3645,"n": "רב שייא","l": "ש","b": "אמורא בבלי בדור השביעי. מצינו: \"אמר רב שייא: כוותיה דרב אשי מסתברא\" (זבחים ל\"ד ע\"ב).","cat": "sage"},{"i": 3646,"n": "רבי שיין","l": "ש","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רב אחא (ירו', עירובין פ\"א ה\"ו). מצינו: \"א\"ר שיין: 'זה שהוא מתמני בכסף אין עומדין בפניו, ואין קורין אותו רבי, והטלית שעליו כמרדעת של חמור'\" (ירו', בכורים פ\"ג ה\"ג). נראה לומר, שרבי אשיאן ור' אשיין אחד הוא.","cat": "sage"},{"i": 3647,"n": "שילא (2)","l": "ש","b": "אחיו של רבי חייא, ודודו של רב (סנהדרין ה' ע\"א), היו לו עוד ארבעה אחים: איבו (אביו של רב), מרתא, חנה (אביו של רבה בר חנה) ורבי חייא.","cat": "sage"},{"i": 3648,"n": "רב שילא","l": "ש","b": "אמורא בבלי בדור הראשון. היה ריש סידרא בבבל, אחר פטירת רבי (\"אגרת רב שרירא גאון\"). כשרב בא לבבל לא הכירו רב שילא, ורב היה זמנית האמורא שלו, וכשר' שילא הכיר בו שהוא רב, אמר לו: \"לך ושב בכבודך שאינך כדאי שתהא מתורגמני\" (יומא כ' ע\"ב). ואחרי כן קיבל רב שילא מרב (ברכות מ\"ט ע\"ב). רב לא רצה לפגוע בכבודו: \"דרוש ר' שילא וכו', בתר דנפק איקום רב אמורא עליה ודרש וכו'\" (סנהדרין מ\"ד ע\"א) ופרש\"י: \"ולא יפה דרש רבי שילא\", ולכן תיקן רב את דבריו. התיר אשה שבעלה טבע במים שאין להם סוף, ורב רצה לנדותו על כך (כי טעה בדין) ושמואל מנעו מכך (יבמות קכ\"א ע\"א). בין תלמידיו היה רב חסדא (כתובות ע\"ה ע\"א).","cat": "sage"},{"i": 3649,"n": "רבי שילא","l": "ש","b": "תנא בדור השלישי. מינוהו שופט על פי הקיסר. מסופר שנעשו לו נסים לאחר שהלשינו עליו (ברכות נ\"ח ע\"א), ואליהו בא להצילו (שם). רבן שמעון בן גמליאל (אבי רבי) מסר משמו (תוספתא כלים פ\"ד ט').","cat": "sage"},{"i": 3650,"n": "רבי שילא איש כפר תמריתא","l": "ש","b": "מובא בבבלי (מגילה ט\"ז ע\"ב), והוא רב שילא איש כפר תמרתה.","cat": "sage"},{"i": 3651,"n": "רב שילא איש כפר תמרתה","l": "ש","b": "אמורא ארץ ישראלי בדור השני - השלישי. מסר משם רבי יוחנן (ירו', חגיגה פ\"ג ה\"ח). ר' לוי אמר בשמו (ב\"ר פמ\"ה - ד'), וכן מצינו: \"אמר רבי אסי: 'דרש רבי שילא איש כפר תמרתא'\" וכן מצינו: \"א\"ר חנינא בר פפא: 'דרש ר' שילא איש כפר תמריתא'\" (מגילה ט\"ז ע\"ב).","cat": "sage"},{"i": 3652,"n": "רב שילא בר אבינא","l": "ש","b": "אמורא בבלי בדור השני. מתלמידיו המובהקים של רב. לפני פטירתו של רב אמר לרב אסי: \"זיל צנעיה [אמור לרב שילא בר אבינא שיחזור בו מדעתו על דין מסויים] ואי לא גרייה\" [כלומר אם לא ירצה משוך אותו בדברי טעם ושכנוע וראיות שיחזור בו], ורב אסי הבין במקום \"גרייה\" \"גדייה\" (כלומר הכריחו בשמתא), ומאחר שרב שילא בר אבינא לא רצה לחזור בו, הכניסו רב אסי לשמתא, ורב אסי חלה ונפטר. ובעקבות זאת נפטר מיד לאחריו גם רב שילא בר אבינא.","cat": "sage"},{"i": 3653,"n": "שילא בר בריה דרב אחא","l": "ש","b": "מובא ב\"ילקוט\" (יחזקאל רמז שסו).","cat": "sage"},{"i": 3654,"n": "ר' שילא בר יצחק","l": "ש","b": "מובא במדרש תהלים (הישן פצ\"א).","cat": "sage"},{"i": 3655,"n": "שילא בר מרי","l": "ש","b": "מובא בבבלי (גיטין נ\"ח ע\"א), ו\"סה\"ד\" כתב: \"תיבת בר ט\"ס\", וצ\"ל: שילא מרי.","cat": "sage"},{"i": 3656,"n": "ר' שילא דינוה","l": "ש","b": "מובא בירושלמי, שרבנן דקיסרין אמרו בשמו (שבת פ\"ב ה\"ה).","cat": "sage"},{"i": 3657,"n": "ר' שילא דכפר תמרתא","l": "ש","b": "ע\"ע רב שילא איש כפר תמרתה.","cat": "sage"},{"i": 3658,"n": "שילא מרי","l": "ש","b": "מובא בבבלי: \"אמר רב כהנא ואיתימא שילא מרי\" (שבת ל\"ב ע\"ב). וכן: \"אמר רב שמואל בר יהודה: 'וכן תני שילא מרי'\" (שם מ\"ג ע\"ב).","cat": "sage"},{"i": 3659,"n": "רבי שילא משלנייא","l": "ש","b": "אמורא בבלי בדור הששי. לרב אשי היה יער במקום ששמו שלנייא, והלך לגזום בחול המועד, ואמר לו רב שילא משלנייא שאביי אסר ורב אשי ענה לו שהוא סובר שמותר. הגרזן נפל, וכמעט חתך את רגלו של רב אשי, וחש רב אשי שבגלל שעבר על דברי אביי כמעט נענש והפסיק את המלאכה (מו\"ק י\"ב ע\"ב).","cat": "sage"},{"i": 3660,"n": "ר' שילה דנוהא","l": "ש","b": "מובא בויק\"ר (פל\"ד - ט'), והוא ר' שילא דינוה.","cat": "sage"},{"i": 3661,"n": "ר' שימי","l": "ש","b": "הוא ר' שמאי.","cat": "sage"},{"i": 3662,"n": "רב שימי בר אבא","l": "ש","b": "אמורא בבלי בדור החמישי - הששי. \"יוחסין\" כתב, ששניים היו: אחד בימי רבי יוחנן ואחד בימי רב פפא. \"סה\"ד\" כתב: \"לא ידעתי מנין לו כי שניים היו\". וכנראה הוכיח \"יוחסין\" ששנים היו, שכן מצינו \"א\"ל רב שמן בר אבא [אמורא ארץ ישראלי בדור השלישי] לרב פפא\" [אמורא בבלי בדור הרביעי] (פסחים מ\"ט ע\"ב), ודק\"ס\" גרס: \"א\"ל רב שמי בר אבא לרב פפא\" (ולא רב שמן). וכן מצינו: \"מתיר ר' שימי בר אבא\" (נדרים ל\"ו ע\"א).","cat": "sage"},{"i": 3663,"n": "רב שימי בר אביי","l": "ש","b": "אמורא בבלי בדור הרביעי. מובא בבבלי, שאמר הלכה כר' יצחק שאמר משום רבי יוחנן (כתובות ס' ע\"א).","cat": "sage"},{"i": 3664,"n": "רב שימי בר אדא","l": "ש","b": "אמורא בבלי בדור הרביעי. מובא פעם בבבלי: \"א\"ל רב שימי בר אדא לרב פפא וכו' תיקו\" (נזיר נ' ע\"ב). אין להכריע שהיה תלמיד של רב פפא. \"סה\"ד\" מפקפק אולי יש ט\"ס בשם, וצ\"ל: רב שימי בר אבא, ואם נניח כדבריו כי אז יש למחוק שם חכם מהש\"ס, או שלא היה קיים חכם ושמו רב שימי בר אבא, או שלא היה קיים חכם ושמו רב שימי בר אדא.","cat": "sage"},{"i": 3665,"n": "רב שימי בר אשי","l": "ש","b": "אמורא בבלי בדור החמישי. תלמיד מובהק של אביי (גיטין ס' ע\"ב). בתחילה אביי נהג להשקות את שדהו בלילה ורב שימי בר אשי השקה את שדהו של אביי ביום, ואביי למד עמו בלילה (נדה ל\"ג ע\"ב). מסר גם משם רבא (יומא ס\"ב ע\"ב). נהג לשאול הרבה מרב פפא, ופעם שמע את ר\"פ שהתפלל שה' יצילנו מבושות שאלותיו, ומיד גזר על עצמו שתיקה. נראה, שהיה לתלמיד - חבר לרב פפא (נדה שם). רב כהנא (חברו של רב אשי) היה תלמידו (תמורה כ\"ח ע\"א). בלע נחש ונתרפא על ידי אליהו הנביא (שבת ק\"ט ע\"ב). ריפא נכרי מצרעתו (גיטין ע' ע\"א). \"יוחסין\" כתב, שבשיטתו ריפא הרמב\"ם לישמעאלים (סמ\"ג מל\"ת מ\"ה).","cat": "sage"},{"i": 3666,"n": "רב שימי בר זירי","l": "ש","b": "אמורא בבלי בדור החמישי. תלמידו של רב פפא (תמורה כ\"ד ע\"א).","cat": "sage"},{"i": 3667,"n": "רב שימי בר חזקיה","l": "ש","b": "אמורא בבלי בדור השני. מסר בשם רב (כתובות ו' ע\"א).","cat": "sage"},{"i": 3668,"n": "שימי בר חייא בר רב","l": "ש","b": "אמורא בבלי בדור השלישי. בן בנו של רב. זכה להיות תלמידו המובהק (קידושין י\"ב ע\"א). רב אמר לו: \"שימי את\" (פרש\"י בכורות מ\"ג ע\"ב) \"חכם גדול כמותך אינו יודע לתרץ מתני'\". רב ביקר אצלו (חולין קי\"א ע\"ב). פעם ישבו רב ושמואל ואכלו, ושימי בר חייא בר רב הצטרף אליהם לזימון (ברכות מ\"ז ע\"א).","cat": "sage"},{"i": 3669,"n": "רב שימי בר עוקבא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, שהיה שכיח קמיה דר' שמעון בן פזי, והיה מסדר אגדתא קמיה דרבי יהושע בן לוי (ברכות י' ע\"א).","cat": "sage"},{"i": 3670,"n": "רב שימי מבירתא דשיחורי","l": "ש","b": "מובא בבבלי: \"והתני רב שימי: \"מבירתא דשיחורי וכו'\" (סוטה ל\"ח ע\"א).","cat": "sage"},{"i": 3671,"n": "רב שימי מחוזנאה","l": "ש","b": "אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (מכות ט\"ז ע\"א).","cat": "sage"},{"i": 3672,"n": "רב שימי מנהרדעא","l": "ש","b": "אמורא בבלי בדור החמישי. תלמידו של רבא, ו\"רבא טפח ליה בסנדליה וא\"ל עטו וכו'\" (ב\"ק ל\"ב ע\"ב). ומפרש פלוגתא דרבה ורבא (עירובין כ\"ה ע\"א). ומצינו (שבועות י\"ב ע\"ב) רבא אמר: \"הא בורכא\" [פרש\"י: \"דבר הבדוי מן הלב דמנא לך הא\"] אמר ליה רב נחמן בר יצחק לרבא: \"מאי בוכרא אנא אמריתא ניהליה ומשמיה דרב שימי מנהרדעא אמריתא ניהליה\" (שבועות י\"ב ע\"ב).","cat": "sage"},{"i": 3673,"n": "רב שיננא בריה דרב אידי","l": "ש","b": "מובא בבבלי (גיטין פ\"ט ה\"ב). וגירסת הרי\"ף והרא\"ש: רב שישא. \"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: שישא\".","cat": "sage"},{"i": 3674,"n": "רב שישא בריה דרב אידי בר אבין","l": "ש","b": "אמורא בבלי בדור החמישי. בנו ותלמידו של האמורא רב אידי בר אבין (תענית י\"ג ע\"א). אחיו של האמורא רב יהושע בריה דרב אידי. הקשה על דברי רבא: \"ומי מצית אמרת וכו'\" [ורבא ענה] (יבמות ע\"ד ע\"ב). שקיל וטרי עם רב פפא (ב\"מ ק\"ט ע\"א).","cat": "sage"},{"i": 3675,"n": "שכחת","l": "ש","b": "לדעת הרשב\"ם היה שכחת בנו של רבי חנינא (ב\"ב קכ\"ו ע\"ב ד\"ה שכחת ברי), אבל דעתו של רש\"י (שם כ\"ו ע\"א ד\"ה: שכחת ברי) ששמו של האיש היה שכחת ברי, והגירסא במקום אחר (ב\"קצ\"א ע\"ב): שיבחה.","cat": "sage"},{"i": 3676,"n": "שכחת ברי","l": "ש","b": "מובא בבבלי (ב\"ב קכ\"ו ע\"ב), ע\"ע שכחת.","cat": "sage"},{"i": 3677,"n": "ר' שלום","l": "ש","b": "מובא בב\"ר (פל\"ד - ט'), שאמר בשם ר' מנחמא בר זעירא.","cat": "sage"},{"i": 3678,"n": "ר' שלום בר מניומי","l": "ש","b": "מובא ב\"זוהר\" (בראשית קכ\"ד).","cat": "sage"},{"i": 3679,"n": "רב שלמון","l": "ש","b": "מובא במדרש (סוף רו\"ר), והוא רב שלמן.","cat": "sage"},{"i": 3680,"n": "ר' שלמוני","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\"ל (ב\"ר פס\"ח - י\"ב).","cat": "sage"},{"i": 3681,"n": "רב שלמן","l": "ש","b": "אמורא בבלי בדור החמישי. שימש \"תנא\" שונה ברייתות, לפני רב נחמן בר יצחק. ומצינו: \"תני תנא קמיה דרנב\"י וכו' א\"ל: 'מה שמך' א\"ל: 'שלמן', א\"ל: 'שלום אתה ושלמה משנתך ששמת שלום בין התלמידים'\" (ברכות ל\"ט ע\"ב), ומצינו: \"תרגמא רב שלמן\" (ב\"ב י\"ג ע\"ב).","cat": "sage"},{"i": 3682,"n": "שלמן בר לוי","l": "ש","b": "אמורא ארץ ישראלי בדור השני. אחיו של זבדי בר לוי. מסר בשם רב יהושע בן לוי (ירו', כלאים פ\"א ה\"ד).","cat": "sage"},{"i": 3683,"n": "רב שלמן מבי כלוחית","l": "ש","b": "מובא בבבלי: \"רב אדא ורב שלמן תרווייהו מבי כוחלת\" (ביצה ה' ע\"ב).","cat": "sage"},{"i": 3684,"n": "שמאי (2)","l": "ש","b": "מחכמי ה\"זוגות\" האחרונים. הוא וחברו הלל הזקן היו ה\"זוג\" החמישי והאחרון שהפריד בין סוף תקופת ה\"זוגות\" לתקופת התנאים. הלל שימש כנשיא ושמאי כאב בית דין (חגיגה ט\"ז ע\"א), ושניהם קיבלו מבני ה\"זוג\" שלפניהם, שמעיה ואבטליון (אבות פ\"א מי\"ב). הלל ושמאי הם אבות בית הלל ובית שמאי. ומסופר: \"ת\"ר, לעולם יהא אדם ענוותן כהלל ואל יהא קפדן כשמאי, מעשה בשני בני אדם וכו'\" (שבת ל' סע\"ב). כל חייו היה אוכל לכבוד שבת, מצא בהמה נאה, אמר: \"זו לשבת, מצא אחרת נאה הימנה וכו'\" (ביצה ט\"ז ע\"א). מתלמידיו מצינו את בבא בן בוטא, החכם שהורדוס עיוור את עיניו (גיטין נ\"ז ע\"א), ואת רבן יוחנן בן זכאי (אבות רפ\"ב).","cat": "sage"},{"i": 3685,"n": "ר' שמאי","l": "ש","b": "אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רב אחא ומסר הרבה משמו (ירו', דמאי פ\"ח ה\"א). היה גם תלמידו של רבי יוסי (ירו', מעשרות פ\"ה ה\"א). ושקיל וטרי עם רבי מנא (ירו', שבת פ\"ג ה\"ב). בנו רבי אושעיא בר שמאי היה, כנראה, מחכמי קיסרין.","cat": "sage"},{"i": 3686,"n": "שמואל","l": "ש","b": "מגדולי אמוראי בבל בדור הראשון. מכונה בכמה כינויים בש\"ס: \"מר שמואל\" (ברכות י\"ט ע\"א), \"שמואל ירחינאה\" ע\"ש חכמת העיבור (ב\"מ פ\"ה ע\"ב), \"שקוד\" (כתובות מ\"ג ע\"ב); פרש\"י: \"על שום ששוקד על דבריו לאומרם כהלכה\", ו\"הערוך\" פי' שהיה שוקד על דלתי תורה. \"שבור מלכא\" (ב\"ב קט\"ו ע\"ב) פרשב\"ם: \"ולפי שהלכה כמותו בדין, קרי ליה הכי, וכן נקרא: \"אריוך\" (חולין ע\"ו ע\"ב) ופרש\"י: \"קרי שמואל על שם אריוך מלך אלסר דהלכתא כוותיה בדיני\". לאחר שרב נפטר בסורא מלך הוא בנהרדעא, משנת ד' ז' - ד' י\"ג (742 - 352). אביו נודע בשם אבוה דשמואל, וכונה על שם בנו אף שהוא עצמו היה חכם גדול. מתלמידיו של רבי (ירו', ר\"ה פ\"ג ה\"ו), וראש בנהרדעא (ביצה ט\"ז ע\"ב). מסופר, שאביו בא בשם המפורש לביתו והוליד את שמואל (קידושין ע\"ג ע\"א תד\"ה: מאי). עלה לארץ ישראל ולמד לפני רבי, אך לא נסמך (ב\"מ פ\"ה ע\"ב). לוי היה רבו המובהק (מנחות ל\"ח ע\"ב). חברו המובהק של רב והלכותיהם פזורות בכל הש\"ס. ומצינו: \"רבותינו שבבבל - רב ושמואל\" (סנהדרין י\"ז ע\"ב). וכן \"הוויות דרב ושמואל\" (ברכות כ' ע\"א). אך רב היה גדול ממנו (ב\"ק פ' ע\"ב), ושמואל היה כייף לרב (מגילה כ\"ב ע\"א), ולמד ממנו 04 פעם (כתובות כ\"ב ע\"ב). כשנפטר רב, קרע עליו 21 בגדים ואמר: הלך אדם שפחדתי ממנו מקושיותיו (מו\"ק כ\"ד ע\"א). גדולי הדור שלאחריו היו תלמידיו, ובינהם רב יהודה (ברכות ל\"ו ע\"א), רב נחמן (שם כ\"ז ע\"ב) ורבי אבא (ירו', עירובין פ\"ו ה\"ז). כשנפטר רב, הלכו מתלמידי רב ללמוד לפני רב אסי. כדמצינו (יבמות י\"ז ע\"א רש\"י ד\"ה: כי) ורב אסי נפטר סמוך אחרי רב (נדה ל\"ו ע\"ב), ואז באו רבים מתלמידי רב לפני שמואל: \"שלחו מבי רב לשמואל: 'ילמדנו רבנו'\" (גיטין ס\"ו ע\"ב) וסידר תוספתא כדפירש\"י \"בתוספתא שסידר שמואל מתנאים שלפניו, כמו שסידרו רבי חייא ורבי אושעיא, וכמו שסידר רבי את המשנה\" (ביצה כ\"ט סע\"א). שמואל היה רופא גדול (ב\"מ קי\"ג ע\"ב). הלך לארץ ישראל וריפא את רבי (ב\"מ פ\"ה ע\"ב). היה ידען גדול בחכמת התכונה, ואמר: \"נהירין לי שבילי דשמיא כשבילי נהרדעא\" (ברכות נ\"ח ע\"ב). היה מומחה גדול בדיני ממונות, ובכל המחלוקות בין רב לשמואל בדיני ממונות ההלכה כשמואל (בכורות מ\"ט ע\"ב). כן היה מומחה גדול בענייני טריפות, וכשרבי יוחנן כתב לו לקדם \"חברנו\", שלח לו שמואל 31 גוילים (גיר' הר\"ח) בענייני טריפות, ואז כתב רבי יוחנן לקדם \"רבותינו שבבבל\". הוא ואחיו פנחס נשאו שתי אחיות (סנהדרין כ\"ח ע\"ב). בנים לא נתקיימו לו, כי רב קיללו (שבת ק\"ח ע\"א), ובגלל קללה זו כיבדו רב ולא רצה להכנס לפני שמואל (ב\"ק פ' ע\"ב). שתיים מבנותיו נשבו והובאו לארץ ישראל. נראה, שבת שלישית ושמה רחל היתה אמו של רב מרי בר איסק, כמו שפירש רש\"י (ברכות ט\"ז ע\"א ד\"ה: ברה). כשנפטר שמואל, מלך בסורא רב הונא, ורב יהודה יסד את ישיבת פומבדיתא.","cat": "sage"},{"i": 3687,"n": "ר' שמואל","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אבהו (ירו', סנהדרין ספ\"א). כן היה תלמידו של רב זירא (ירו', כלאים פ\"ב ה\"ו).","cat": "sage"},{"i": 3688,"n": "ר' שמואל אחוה דר' פנחס בר חייא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. נפטר בחיי אחיו ר' פנחס שהיה רחוק ממנו בשעה שמת, ור' פנחס חש במיתת אחיו, אף שלא היה לידו (מדרש שמואל פ\"ט - ג').","cat": "sage"},{"i": 3689,"n": "ר' שמואל אחוי דרב","l": "ש","b": "מובא בירושלמי (יומא פ\"ג ה\"ח), ו\"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: אחוי דר' ברכיה\".","cat": "sage"},{"i": 3690,"n": "ר' שמואל אחוי דר' אושעיא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שאמר שר' ירמיה בעי וכו' (חגיגה פ\"ב ה\"ז).","cat": "sage"},{"i": 3691,"n": "ר' שמואל אחוי דר' ברכיה","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. אחיו של בעל האגדה הידוע רבי ברכיה. הכיר את רבי אמי, כדמוכח בירושלמי (הוריות פ\"ג ה\"ה). רבי יוסי הקשה עליו (ירו', שבת ספט\"ו).","cat": "sage"},{"i": 3692,"n": "ר' שמואל בן אלעזר","l": "ש","b": "כך מובא בירושלמי (שבת פי\"ד ה\"ג), ונראה שהיה כתוב: ר\"ש, ועשו מזה \"ר' שמואל\" ואותו עניין בבבלי (שבת קל\"ד ע\"א), וצ\"ל: ר' שמעון בן אלעזר, וכן הוא בירושלמי (ברכות פ\"א ה\"א).","cat": "sage"},{"i": 3693,"n": "רבי שמואל בן יהוצדק","l": "ש","b": "מובא בירושלמי (ברכות ג' ע\"א), והוא ט\"ס וצ\"ל: רבי שמעון בן יהוצדק (רבו דרבי יוחנן), כמו שמובא במקום אחר (ירו', נזיר פ\"ז ה\"א). וחכם ושמו רבי שמואל בן יהוצדק נראה שלא היה קיים כלל שכן מובא רק בפעם הזאת בש\"ס, ונראה שהיה כתוב: \"ר\"ש בן יהוצדק\", והמדפיס פיענח: \"רבי שמואל\" במקום \"רבי שמעון\".","cat": "sage"},{"i": 3694,"n": "ר' שמואל בן סיסרטא","l": "ש","b": "מובא בירושלמי (כלאים רפ\"ג), והוא רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3695,"n": "רבי שמואל בר אבא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמיד מובהק של רבי יוחנן (מגילה כ\"ג ע\"א). וכן קיבל מרבי אסי (ירו', נזיר סה\"ב). רבי אלעזר ביקרו בארץ (ירו', מו\"ק פ\"ג ה\"א). נראה שביקר בבבל, ורב ששת אמר לו: \"אסברה לך\" (עירובין ז' ע\"ב).","cat": "sage"},{"i": 3696,"n": "רב שמואל בר אבא מהגרוניא","l": "ש","b": "אמורא בבלי בדור הרביעי. תלמידו של רבי אבא ושאל ממנו (ב\"ק ז' ע\"ב). אמו נישאה לרבי אבא, וכתבה נכסיה לבנה רב שמואל (שהיה בנו של ר' אבא מהגרוניא), ורבי אבא ערער על כך, ופסק רב יהודה שהנכסים שייכים לרבי אבא (ב\"ק פ\"ח ע\"א).","cat": "sage"},{"i": 3697,"n": "ר' שמואל בר אבדומי","l": "ש","b": "אמורא ארץ ישראלי בדור הששי. תלמידו של רבי מנא (ירו', הוריות פ\"ב ה\"ה). פעם היה צריך למול בשבת ושכח להביא איזמל מע\"ש ושאל את רבי מנא (ירו', שבת פי\"ט ה\"א). אמו מתה ח' ימים קודם המועד ובא לשאול את רבי מנא (ירו', מו\"ק פ\"ג). פעם אחת הובא שמו באגדה (תנחומא תצא י').","cat": "sage"},{"i": 3698,"n": "ר' שמואל בר אבין","l": "ש","b": "מובא בירושלמי (כלאים פ\"ג ה\"ב), ואביו, שגם הוא היה חכם, מתייחס אליו: \"דתני אבוה דשמואל בר אבין\" (סנהדרין נ\"א ע\"ב).","cat": "sage"},{"i": 3699,"n": "רב שמואל בר אוניא","l": "ש","b": "מובא בבבלי (מגילה ג' ע\"ב), והוא רב שמואל בר איניא.","cat": "sage"},{"i": 3700,"n": "רב שמואל בר אחא","l": "ש","b": "אמורא בבלי בדור הששי. תלמידו של רב פפא: \"אמר קמיה דרב פפא\" (מנחות ל\"ד ע\"א).","cat": "sage"},{"i": 3701,"n": "רב שמואל בר אחיתאי","l": "ש","b": "אמורא בבלי בדור הרביעי. תלמידו של רב המנונא סבא (גיטין ל\"ט ע\"ב).","cat": "sage"},{"i": 3702,"n": "רב שמואל בר איביה","l": "ש","b": "מובא בויק\"ר (פ\"י - ט'), ונראה שהוא רב שמואל בר איניא.","cat": "sage"},{"i": 3703,"n": "רב שמואל בר אידי","l": "ש","b": "אמורא בבלי בדור החמישי. תלמידו של רבא. אחרי פטירתו של רבא היה לתלמידו של רב פפא (תענית ט' ע\"א). ע\"ע רב הונא בר מנוח.","cat": "sage"},{"i": 3704,"n": "רב שמואל בר אינא","l": "ש","b": "מובא בבבלי (כתובות י\"ז ע\"א), והוא רב שמואל איניא.","cat": "sage"},{"i": 3705,"n": "רב שמואל בר איניא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אחא ומסר משמו (ירו', תענית פ\"ב הי\"ג) וכן מסר בשם רב (עירובין ס\"ג ע\"ב). שמו שובש בכמה פנים: רב שמואל בר אוניא (מגילה ג' ע\"ב), רב שמואל בר איני (כתובות י\"ז ע\"א), ובירושלמי שמואל בר בונא (סנהדרין פ\"י ה\"ב), ונראה אולי שהוא ר' שמואל בר יונה (ויק\"ר פ\"ל - ג'), וכן ר' שמואל בר איביה (ויק\"ר פ\"י - ט'), ור' שמואל בר חובה (קה\"ר פ\"א - ז' - ח'), וכן ר' שמואל בר חנא (ב\"ר פ\"ה - ז').","cat": "sage"},{"i": 3706,"n": "רב שמואל בר אמי","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. אביו אימי (אמי) מתיחס לבנו, ומסר בשם רב יהודה (ירו', יבמות פ\"י ה\"ו): \"אימי אבוה דשמואל בר אימי\". רבי זירא שקיל וטרי עמו (פסחים ט\"ז ע\"ב). חותנו שמואל סבא מסר משמו (סוטה י' ע\"ב): \"אמר שמואל סבא, חמוה דרב שמואל בר אמי, משמיה דרב שמואל בר אמי\".","cat": "sage"},{"i": 3707,"n": "שמואל בר בונא","l": "ש","b": "מובא בירושלמי (סנהדרין פ\"י ה\"ב), והוא רב שמואל בר איניא.","cat": "sage"},{"i": 3708,"n": "ר' שמואל בר בידרי","l": "ש","b": "אמורא בבלי בדור השני. תלמידו של רב (מנחות ל\"ה ע\"ב).","cat": "sage"},{"i": 3709,"n": "רב שמואל בר ביסנא","l": "ש","b": "אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (נדה מ\"ב ע\"א), ושאל מרב יוסף, וכן תרגם קמיה דרב יוסף (קידושין כ\"ו ע\"ב). היה גם תלמידו של רב נחמן (כתובות ק' ע\"א).","cat": "sage"},{"i": 3710,"n": "רב שמואל בר בר חנה","l": "ש","b": "הוא רב שמואל בריה דרבה בר בר חנה.","cat": "sage"},{"i": 3711,"n": "ר' שמואל בר ברכיה","l": "ש","b": "מובא בירושלמי (תרומות ספ\"ח).","cat": "sage"},{"i": 3712,"n": "ר' שמואל בר גדליה","l": "ש","b": "מובא בתנחומא (בהר).","cat": "sage"},{"i": 3713,"n": "ר' שמואל בר גוריא","l": "ש","b": "מובא בתנחומא (הישן בהר).","cat": "sage"},{"i": 3714,"n": "רב שמואל בר זוטרא","l": "ש","b": "אמורא בבלי בדור החמישי. אולי אפשר להסיק מלשון הגמרא, שהיה תלמידו של רבא \"אמר רבא וכו' רב שמואל בר זוטרא מתני לה לשמעתא דרבי בהאי לישנא\" (נדה מ\"ו ע\"א). מובא: \"אמר רב פפי: 'אמר לי רבינא לדידי אמר לי ההוא מרבנן וכו' ואמרי לה רב שמואל בר זוטרא שמיה, דאי הוו יתבי ליה כל חללא דעלמא לא הוי קא משני בדיבוריה'\" (ב\"מ מ\"ט ע\"א).","cat": "sage"},{"i": 3715,"n": "ר' שמואל בר זעירא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. אמר בשם ר' הונא הכהן (מ\"ר פ\"ג - ח').","cat": "sage"},{"i": 3716,"n": "רב שמואל בר חובה","l": "ש","b": "מובא בקה\"ר (פ\"א - ז' - ח'), ונראה שהוא רב שמואל בר איניא.","cat": "sage"},{"i": 3717,"n": "רב שמואל בר חייא","l": "ש","b": "אמורא בדור השלישי. תלמידו של רבי אלעזר (ב\"מ ע\"ב ע\"ב).","cat": "sage"},{"i": 3718,"n": "רבי שמואל בר חייא בר יהודה","l": "ש","b": "אמורא ארץ ישראלי בדור השני. מסר בשם רבי חנינא (ירו', מע\"ש פ\"ג ה\"ב).","cat": "sage"},{"i": 3719,"n": "רבי שמואל בר חלף","l": "ש","b": "מובא בירושלמי (מגילה רפ\"ג), והוא רבי שמואל בר חלפתא (אמורא).","cat": "sage"},{"i": 3720,"n": "רבי שמואל בר חלפתא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רב אדא בר אהבה. רבו של רבי ירמיה (ירו', ברכות פ\"ג ה\"ה). ובמקום אחר: \"רבי שמואל בר חלף\" (ירו', מגילה רפ\"ג).","cat": "sage"},{"i": 3721,"n": "ר' שמואל בר חנא","l": "ש","b": "מובא בב\"ר (פ\"ה - ז'), ונראה שהוא ר' שמואל בר איניא.","cat": "sage"},{"i": 3722,"n": "ר' שמואל בר חנינא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רב אסי: \"רבי יסא (הוא רבי אסי) הורי לשמואל בר חנינא\" (ירו', מו\"ק פ\"א ה\"ח). מסר בשם רבי אלעזר (ירו', יומא פ\"ה ה\"ד).","cat": "sage"},{"i": 3723,"n": "רב שמואל בר חתאי","l": "ש","b": "מובא בבבלי (סוכה מ\"ב ע\"א), והוא רב שמואל בר אחיתאי.","cat": "sage"},{"i": 3724,"n": "רב שמואל בר יהודה","l": "ש","b": "אמורא בבלי בדור השלישי, והוא ואביו התגיירו (יבמות ק\"א ע\"ב רש\"י), ואמו היתה ישראלית (כתובות מ\"ד ע\"ב תוספות ישנים). היה חברו של רב יהודה ואמר לו (כדוגמת שמואל רבו דרב יהודה) \"שיננא וכו'\" (כתובות י\"ב ע\"ב). כשרב יהודה התיר בשבת למיכחל עינא, אמר רב שמואל בר יהודה: \"מאן ציית ליהודה\" (ע\"ז כ\"ח ע\"ב). רב יהודה אמר עליו שיודע בו שאינו משקר (כתובות מ\"ד ע\"ב). הלך לארץ ישראל וקיבל מרבי יוחנן (שבת ל\"ז ע\"ב). נראה, שהיה לאחד מן ה\"נחותי\", שמצינו: \"כי אתא רב שמואל בר יהודה אמר רבי יוחנן\" (גיטין כ\"ג ע\"ב), וכן אמר הוא וה\"נחותי\" ר' דימי משמיה דרבי אלעזר (שבת ל\"ח ע\"ב). אביי קיבל ממנו (מנחות מ\"ב ע\"ב).","cat": "sage"},{"i": 3725,"n": "רב שמואל בר יונה","l": "ש","b": "מובא בויק\"ר (פ\"ל - ג'). נראה, שהוא רב שמואל בר איניא.","cat": "sage"},{"i": 3726,"n": "רבי שמואל בר יוסי","l": "ש","b": "מובא בבבלי (קידושין ל\"ג ע\"א), ונראה שהוא ט\"ס וצ\"ל: רבי ישמעאל בר יוסי. הקפיד על רבי שמעון בר רבי, וכן נראה שצ\"ל במד' תהלים (הישן פ\"ג). ונראה אולי שלא היה קיים כלל חכם ושמו רבי שמואל בר יוסי.","cat": "sage"},{"i": 3727,"n": "רב שמואל בר ייבא","l": "ש","b": "אמורא בדור הרביעי. הקשה לרב אבא (נדה ט\"ו ע\"ב).","cat": "sage"},{"i": 3728,"n": "ר' שמואל בר ינא","l": "ש","b": "מובא (ירו', תענית פ\"ב ה\"א) והוא ר' שמואל בר איניא.","cat": "sage"},{"i": 3729,"n": "ר' שמואל בר ינאי","l": "ש","b": "מובא במדרש שמואל (פכ\"א - ג').","cat": "sage"},{"i": 3730,"n": "רב שמואל בר יעקב","l": "ש","b": "אמורא בבלי מובא בירושלמי (נדרים פ\"ג ה\"ב) ובבבלי (מנחות ל\"ב ע\"א).","cat": "sage"},{"i": 3731,"n": "רב שמואל בר יצחק","l": "ש","b": "אמורא בבלי בדור השלישי. תלמידו של רב (נדה ס\"ב ע\"ב) ושל רב הונא (עירובין ל\"ו ע\"ב). עלה לארץ ישראל ולקח תורה מרבי חייא בר אבא (חולין צ\"ח ע\"א). מסר בשם רבי יוחנן (חולין קט\"ז ע\"ב). הוא ורבי זירא מכונים \"שני גדולי הדור\" (גיטין נ\"ג ע\"ב). המוסרים בשמו: רבי ירמיה (ירו', עירובין פ\"א ה\"א), רבי יונה ורבי יוסי (ירו', ר\"ה פ\"א ה\"ב). אביו היה חסיד גדול ונהג לצום שני ימים ביום כיפור ומת בגלל זה (שם ה\"ד). רב שמואל בר יצחק נהג לרקוד לפני חתן וכלה ובידו בדי הדס. רבי זירא נהג לומר, שמבייש אותם בזה. בשעת מותו היו שלש שעות קולות וברקים, ויצאה בת קול ואמרה: נפטר רב שמואל בר יצחק וירדה אש מן השמים בצורת בדי הדס והפרידה בין מטתו לבין מלוויו (ירו', ע\"ז פ\"ג ה\"א). בתו התחתנה עם רב אושעיא, אחיו של רבה (ירו', סנהדרין פ\"א ה\"א).","cat": "sage"},{"i": 3732,"n": "רבי שמואל בר כהנא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. ורבי ירמיה מסר בשמו (שהש\"ר פ\"ז - ח').","cat": "sage"},{"i": 3733,"n": "רב שמואל בר מינא","l": "ש","b": "מובא (ירו', ברכות פ\"א ה\"א), והוא ר' שמואל בר איניא.","cat": "sage"},{"i": 3734,"n": "רב שמואל בר מרתא","l": "ש","b": "אמורא בבלי. תלמידו של רב (פסחים קי\"ג ע\"ב). הרשב\"ם סובר שהיה אחי רבי חייא (ב\"ב נ\"ב ע\"א) ואם כן היה בדור הראשון והיה בן דורו של רב. ורבנו גרשום פירש ש\"מרתא\" \"זו שם של אשה\". רבה בר בר חנא היה תלמידו של רב שמואל בר מרתא (פסחים קי\"ג ע\"ב).","cat": "sage"},{"i": 3735,"n": "רבי שמואל בר נדב","l": "ש","b": "אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"בעא מיניה רבי שמואל בר נדב מרבי חנינא, ואמר לה רבי שמואל בר נדב חתניה דרבי חנינא מרבי חנינא, ואמרי לה מרבי יהושע בן לוי\" (ערכין ט\"ז ע\"ב).","cat": "sage"},{"i": 3736,"n": "רבי שמואל בר נחום","l": "ש","b": "אמורא ארץ ישראלי בדור הראשון - השני. מובא בבבלי: \"שאל רבי חנינא בן עגיל את רבי חייא בר אבא: 'מפני מה בדברות הראשונות לא נאמר בהם טוב, ובדברות האחרונות נאמר בהם טוב? ' אמר לו: וכו' 'כלך אצל ר' תנחום בר חנילאי שהיה רגיל אצל ריב\"ל' וכו' אזל לגביה א\"ל: 'ממנו לא שמעתי אלא כך אמר לי שמואל בר נחום וכו'\" (ב\"ק נ\"ה ע\"ב).","cat": "sage"},{"i": 3737,"n": "רבי שמואל בר נחמני","l": "ש","b": "אמורא ארץ ישראלי בדור השני - השלישי. מבעלי האגדה החשובים. מושבו היה בלוד (ויק\"ר פל\"ה - ב'). בבבלי מכונה בדרך כלל: \"רבי שמואל בר נחמני\" ובירושלמי מכונה בד\"כ: \"רבי שמואל בר נחמן\". היה יליד ארץ ישראל. נראה, שהגיע לזקנה מופלגת שכן בהיותו ילד זכה לראות, ואף לשמוע את דרשותיו של התנא רבי שמעון בן אלעזר (ב\"ר פ\"ט - ה'). קרא לרב יהודה: \"חברנו\" (מו\"ק י\"ז ע\"א) ונפטר אחרי רב יהודה, כדמוכח (שם). רבו המובהק היה רבי יונתן (פסחים כ\"ד ע\"א). גם רבי יהושע בן לוי היה רבו המובהק (ירו', ר\"ה פ\"ד ה\"ד). קיבל גם מרבי יוחנן (ירו', תרומות רפ\"ה), ונראה שגם מרבי אלעזר (ירו', חגיגה פ\"ה ה\"א). היה מקורב לרבי יהודה נשיאה, ונהגו ללכת יחד להתרחץ במרחצאות של טבריה, ופעם בא לשם שליחו של הקיסר דיוקליטינוס להזמינם לבוא לחצר הקיסר (ירו', תרומות ספ\"ח), ומסופר על הנסים שנעשו להם (שם). הוא ורבי יעקב בר אידי מכונים: \"גדולי הדור\" (חולין צ\"ח ע\"א). היתה לו ישיבה (ברכות י\"ז סע\"א). והאומרים בשמו רבים, ומהם מתלמידי רבי יוחנן, כגון ר' אבהו (ירו', תענית ספ\"ג) ורבי אלעאי (ירו', שקלים פ\"ג ה\"ב). עיקר דבריו היו באגדה, וכך פנו אליו ר' חלבו ואחרים, כדמצינו: \"מפני ששמעתי עליך שאתה בעל אגדה\" (איכ\"ר פ\"ג - ס', ועוד). רבות מדרשותיו נשארו בידינו. כשהתאכסן אצל ר' יעקב גרוסה, התחבא רבי זירא כדי לשמוע האיך קורא קריאת שמע (ירו', ברכות פ\"א ה\"א). היו לו שני בנים חכמים, רבי נחמן (ירו', מגילה פ\"א ה\"א) ור' הלל (שבת פ' ע\"א).","cat": "sage"},{"i": 3738,"n": "ר' שמואל בר נפחא","l": "ש","b": "מובא בפדר\"כ (נ\"ד), ואולי צ\"ל: ר' שמואל בר נחמני.","cat": "sage"},{"i": 3739,"n": "ר' שמואל בר נתן","l": "ש","b": "אמורא ארץ ישראלי בדור השני. תלמידו של רבי חנינא (ע\"ז ע\"ד ע\"א). חברו של רבי אלעזר ובר פלוגתיה (סוכה מ\"ג ע\"ב).","cat": "sage"},{"i": 3740,"n": "רב שמואל בר סוטר","l": "ש","b": "מובא בירושלמי (ברכות פ\"א ה\"א), והוא כנראה רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3741,"n": "רב שמואל בר סוסרטאי","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבהו (ירו', סנהדרין פ\"ז ה\"א). שמו נשתבש בכמה אופנים: רבי שמואל בר סוסרטיי (ירו', ב\"מ פ\"ב ה\"ה), ושם מסופר שהלך לרומא ומצא מציאה של המלכות וקידש שם שמים בהחזרתה; רב שמואל בר ססרטי (ב\"ק ק\"ב ע\"ב), ושם מובא שרבי אבהו השיב על דבריו; רב שמואל בר ססרטאי (תענית י\"ד ע\"א): שמואל בן סיסרטא (ירו', כלאים רפ\"ג): ר' שמואל בר סיסרטיי (ירו', ביצה פ\"ד ה\"א). ונראה אולי שלגבי המובא בירושלמי: \"ר' חנינא בר אנדריי בשם ר' שמואל בר סוטר\" (ברכות פ\"א ה\"א), כי (לפי השינויים שיש בירושלמי בד\"כ) ר' שמואל בר סוטר הוא ר' שמואל בר סוסרטאי, ופלא ש\"סה\"ד\" קבע שהם שני חכמים ללא הטלת כל ספק בדבר. היו לו שני אחים, אחד ר' הוריינא נראה חכם והאחר, ושמו אלכסנדריי, ספק אם היה חכם (ירו', ב\"ב פ\"ט ה\"ג).","cat": "sage"},{"i": 3742,"n": "רבי שמואל בר סוסרטיי","l": "ש","b": "מובא בירושלמי (ב\"מ פ\"ב ה\"ה), והוא רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3743,"n": "ר' שמואל בר סימון","l": "ש","b": "מובא ברו\"ר (פ\"ג - ו'), והגיר' ב\"ילקוט\" (רות רמז תרא) ר' שמואל בר נחמני.","cat": "sage"},{"i": 3744,"n": "רב שמואל בר סיסרטיי","l": "ש","b": "מובא בירושלמי (ביצה פ\"ד ה\"א), והוא רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3745,"n": "רב שמואל בר ססרטאי","l": "ש","b": "מובא בבבלי (תענית י\"ד ע\"א), והוא רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3746,"n": "רב שמואל בר ססרטי","l": "ש","b": "מובא בבבלי (ב\"ק ק\"ב ע\"ב), והוא רב שמואל בר סוסרטאי.","cat": "sage"},{"i": 3747,"n": "ר' שמואל בר פוניא","l": "ש","b": "מובא: \"א\"ר יודן בשם ר' שמואל בר פוניא בשם בר קפרא\" (פדר\"כ ט').","cat": "sage"},{"i": 3748,"n": "רב שמואל בר פפא","l": "ש","b": "אמורא בבלי בדור השלישי. תירגם קמיה דרב אדא (יומא ל\"ז ע\"א).","cat": "sage"},{"i": 3749,"n": "רב שמואל בר רב קטינא","l": "ש","b": "אמורא בבלי בדור השלישי - הרביעי. מצינו: \"רבה בר בר חנא הוה עסיק ליה לבריה בי רב שמואל בר קטינא וכו'\" (ברכות מ\"ז ע\"א).","cat": "sage"},{"i": 3750,"n": "רב שמואל בר שבא","l": "ש","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא ורבו של רבא (שבועות י\"ז ע\"ב).","cat": "sage"},{"i": 3751,"n": "רב שמואל בר שילת","l": "ש","b": "אמורא בבלי בדור הראשון - השני. תלמידו של רב ושאל ממנו (ירו', פ\"ז ה\"ב). היה מלמד תינוקות במסירות רבה, ושלוש עשרה שנה ברציפות לא הפסיק ולא נח ממלאכתו, ורב היללו מאד (ב\"ב ח' ע\"ב) והדריכו כיצד להתנהג עם הילדים (שם כ\"א ע\"א). ורב ביקשו שיספידו לאחר פטירתו בחמימות, כדי שהמלווים יבכו (שבת קנ\"ג ע\"א). היה לו בן ושמו רב יהודה וגם הוא היה תלמידו של רב (ברכות מ\"ז ע\"א).","cat": "sage"},{"i": 3752,"n": "רב שמואל בר שימי","l": "ש","b": "אמורא בבלי בדור הששי. תלמידו של רב פפא ותירגם קמיה (כריתות כ\"ז ע\"ב).","cat": "sage"},{"i": 3753,"n": "ר' שמואל בר תנחום","l": "ש","b": "מובא שהש\"ר (רפ\"ז), ואולי יש ט\"ס והוא ר' ישמעאל בר תנחום.","cat": "sage"},{"i": 3754,"n": "ר' שמואל בריבי","l": "ש","b": "מובא בקה\"ר (פ\"ו - ו').","cat": "sage"},{"i": 3755,"n": "רב שמואל בריה דרב אבהו","l": "ש","b": "מאמוראי בבל האחרונים בדור השמיני, ונחשב לבן דור הראשון לרבנן סבוראי. אביו, רב אבהו, היה מראשי הכלה בישיבתו של רפרם בפומבדיתא (חולין מ\"ט ע\"א). ועוד מובאת מחלוקת שלו עם רב אחאי, שגם כן היה מרבנן סבוראי (שם נ\"ט ע\"ב). ומובא (\"אגרת רב שרירא גאון\" דפוס ב\"ג) שנפטר בכסלו בשנת ד' רס\"ו (605).","cat": "sage"},{"i": 3756,"n": "רב שמואל בריה דרב איקא","l": "ש","b": "מובא בבבלי (ע\"ז ס\"ט ע\"א). גירסת \"דק\"ס\": \"בריה דר' אבהו\" (מראשי רבנן סבוראי), א\"כ, לדעתו לא היה קיים כלל חכם ושמו \"רב שמואל בריה דרב איקא\", שכן אינו מובא במקום אחר.","cat": "sage"},{"i": 3757,"n": "רב שמואל בריה דרבה בר בר חנא","l": "ש","b": "אמורא בבלי בדור הרביעי. חברם של רב אחא בר הונא ורב יצחק בריה דרב יהודה, ושלושתם למדו מסכת שבועות בבית מדרשו של רבה, ורב כהנא שאלם (שבועות ל\"ו ע\"ב). מצינו אותו עם רב יוסף אפיתחא דבי רבה (קידושין נ\"ח ע\"א) ואמר לרב יוסף: \"בפירוש אמרת לן\" (שבת נ\"ט ע\"ב).","cat": "sage"},{"i": 3758,"n": "רבי שמואל בר' יוסי בר בון","l": "ש","b": "מאחרוני אמוראי ארץ ישראל בדור הששי. בנו ותלמידו של אביו האמורא הידוע רבי יוסי בר אבין (ירו', גיטין פ\"ה ה\"ג). חברו של רב מתנייה (שם).","cat": "sage"},{"i": 3759,"n": "ר' שמואל דסופפתא","l": "ש","b": "בירושלמי (סנהדרין פ\"ב ה\"ב) הגירסא \"ר' שמעון דתוספתא\" ויש גירסא (ירו', ברכות פ\"ג ה\"ב) ר' שמעון דתוספתא, ואין לדעת הנכון, ונראה שהיה כתוב \"ר\"ש\" ופיענחוהו פעם \"ר' שמואל\" ופעם \"ר' שמעון\".","cat": "sage"},{"i": 3760,"n": "שמואל הזקן","l": "ש","b": "אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי אחא (ירו', סנהדרין פ\"ב ה\"ג).","cat": "sage"},{"i": 3761,"n": "שמואל הקטן","l": "ש","b": "תנא בדור השני, שחי מדורו של הלל עד לר' אליעזר בן הורקנוס: \"מעשה שנכנסו זקנים לעלית בית גדיא, ויצאה בת קול ואמרה להן: 'יש ביניכם שנים ראויין לרוח הקודש והלל הזקן אחד מהן', ונתנו עיניהן בשמואל הקטן, [שהוא השני]. ושוב נכנסו זקנים לעליה ביבנה, ויצאה בת קול ואמרה להן: 'יש ביניכן שנים ראויין לרוח הקודש ושמואל הקטן אחד מהן', ונתנו עיניהן ברבי אליעזר בן הורקנוס\" (ירו', סוף סוטה). רבן גמליאל הזקן (בן בנו של הלל) קרא לו: \"בני\" (סנהדרין י\"א ע\"א). ומה שמצינו: \"ואף הוא [שמואל הקטן] אמר בשעת מיתתו: 'שמעון וישמעאל לחרבא'\" (סוטה מ\"ח ע\"ב), פרש\"י: \"רבן שמעון בן גמליאל שהיה נשיא ור' ישמעאל בן אלישע שהיה כהן גדול שהרגתם מלכות יון\", מוכיח ששמואל הקטן היה צעיר בזמן פטירת הלל הזקן ורבי אליעזר היה צעיר בזמן פטירת שמואל הקטן, וכשמת שמואל הקטן הספידוהו: \"הי עניו, הי חסיד, תלמידו של הלל\". הוא שחיבר את ברכת \"המינים\" (ברכות כ\"ח ע\"ב). ולמה נקרא שמו \"קטן\"? לפי שהיה מקטין עצמו, ויש אומרים: לפי שמעט היה קטן משמואל הרמתי (ירו', סוטה פ\"ט הי\"ג).","cat": "sage"},{"i": 3762,"n": "ר' שמואל חתניה דר' חנינא חברון דרבנן","l": "ש","b": "מובא בב\"ר (ספי\"ד).","cat": "sage"},{"i": 3763,"n": "שמואל ירחינאה","l": "ש","b": "כינוי לשמואל (ב\"מ פ\"ה ע\"ב), ופרש\"י: \"הוא שמואל בר אבא חבירו של רב, ועל שהיה בקי בסוד העיבור, כדאמרינן במס' ראש השנה (דף כ' ע\"ב) אמר שמואל: \"יכילנא לתקוני כולה גלותא, קרי ליה ירחינאה\".","cat": "sage"},{"i": 3764,"n": "ר' שמואל כוזית","l": "ש","b": "אמורא ארץ ישראלי בדור החמישי. רבי תנחומא מסר בשמו. כך הגיר' ב\"ערוך\" ערך כזית (מב\"ר פכ\"ד), ולפנינו הגיר' שונה.","cat": "sage"},{"i": 3765,"n": "רב שמואל מדיפתא","l": "ש","b": "אמורא בבלי בדור הששי. חלק עם רב אחא בריה דרבא היכן צריך להניח נר חנוכה (שבת כ\"ב ע\"א). ו\"השאלתות\" פ' וישלח סי' כ\"ו גורס: רב ירמיה וכן גרס \"דק\"ס\": רב ירמיה מדיפתא. א\"כ, לא היה חכם ושמו רב שמואל מדיפתא, שכן הוא מובא בש\"ס רק במקום זה.","cat": "sage"},{"i": 3766,"n": "רב שמואל מזרוקיניא","l": "ש","b": "מובא בבבלי: \"מתקיף לה רב אשי ואיתימא רב שמואל מזרוקיניא\" (חולין קי\"א ע\"א), ומלשון הש\"ס אין ראיה שהיה בזמנו של רב אשי.","cat": "sage"},{"i": 3767,"n": "רב שמואל מתואך","l": "ש","b": "אמורא בבלי בדור החמישי. מובא שרב פפא ביקר בביתו, רב שמואל מתואך שחט לכבודו שור, ושאל מרב פפא ולא ידע להשיב כראוי, והלך רב פפא וסיפר לרב שימי בר אשי ואמר לו רב שימי בר אשי מדוע לא השבת לו וכו' (נדה ל\"ג ע\"ב).","cat": "sage"},{"i": 3768,"n": "שמואל סבא חתניה דרבי חנינא","l": "ש","b": "אמורא ארץ ישראלי בדור השני. חתנו ותלמידו של רבי חנינא (ברכות ס\"ב ע\"ב). אמר משמו של רבי חנינא ור' יוחנן חלק עמו (שם).","cat": "sage"},{"i": 3769,"n": "ר' שמואל פרגריטא","l": "ש","b": "מובא דב\"ר (פ\"ב - כ\"ד).","cat": "sage"},{"i": 3770,"n": "רב שמואל קפודקיא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. ר' יונה מסר משמו (ירו', חלה פ\"ג ה\"א).","cat": "sage"},{"i": 3771,"n": "ר' שמי","l": "ש","b": "הוא ר' שמאי.","cat": "sage"},{"i": 3772,"n": "רבי שמלאי","l": "ש","b": "אמורא בדור השני. נולד בבבל בנהרדעא ועלה לארץ ישראל וחי בלוד (פסחים ס\"ב ע\"ב). שמו של אביו היה אבא, ושאל אבא פעם את שמואל (חברו של רב) שאלה בסוד העיבור ולא ידע להשיב (ר\"ה כ' ע\"ב). תלמידו של רבי ינאי (ב\"ב קי\"א ע\"ב) ותלמידו המובהק של רבי יהודה נשיאה א' (ע\"ז ל\"ז ע\"א). כשרבי יהודה נשיאה א' התיר את השמן הלך ר' שמלאי לנציבין בבבל ודרש על היתר השמן (שם ל\"ו ע\"א). בין תלמידיו היה רבי אלעזר (סנהדרין פ\"ח ה\"א). הרבה להתווכח עם המינים (ב\"ר פ\"ח - ט'). הרבה לדרוש: \"דרש רבי שמלאי, שש מאות ושלש עשרה מצות נאמרו לו למשה, שס\"ה לאוין כמנין ימות החמה, ורמ\"ח עשה כנגד איבריו של אדם\" (מכות כ\"ג ע\"ב).","cat": "sage"},{"i": 3773,"n": "ר' שמלאי","l": "ש","b": "מובא ב\"זוהר\" (אחרי עה).","cat": "sage"},{"i": 3774,"n": "ר' שמלאי דבירא","l": "ש","b": "מובא בירושלמי: \"א\"ר שמלאי דבירא א\"ל ובדברך עשיתי ובדיבורך עשיתי (מגילה פ\"א הי\"א), ופירש \"קרבן העדה\": \"כך שמו\". \"פני משה\" פירש שר' שמלאי אמר: דבירא אמר ליה, מפי הדובר נאמר לו לעשות כדכתיב ובדברך וכו' (א\"כ אינו שם חכם).","cat": "sage"},{"i": 3775,"n": "רב שמן","l": "ש","b": "אמורא בבלי בדור הששי. אמר לרב אשי, והתני רמי בר יחזקל (קידושין כ\"ד ע\"ב).","cat": "sage"},{"i": 3776,"n": "רב שמן בר אבא","l": "ש","b": "אמורא בבלי בדור השני. ר' שמעון בר אבא הוא רב שמן בר אבא כמובא בבבלי (כתובות כ\"ג ע\"א), שמכונה שמן בר אבא, ואותו ענין מובא בירושלמי (כתובות פ\"ב ה\"ו) ושם מכונה ר' שמעון בר אבא. עלה לארץ ישראל ולמד לפני רבי יוחנן והיה תלמידו המובהק (שבת ס\"א ע\"א). רבי יוחנן קרא לו בבלייא (ירו', שבת פ\"ו ה\"ב). היה בדעתו לחזור לבבל ואולי בגלל זה קראו לו רב ולא רבי. ורש\"י פירש (חולין צ\"ג ע\"ב ד\"ה: אל): \"שאתה מבבל ושם נוהגין בו איסורא\". לקח תורה מרבי חנינא (כתובות כ\"ג ע\"א) ומרבי יהושע בן לוי (גיטין ה' ע\"א). כשהובאו בנות שמואל כשבויות מבבל לארץ ישראל א\"ל רבי חנינא שישא אחת מהן לאשה (ירו', כתובות פ\"ב ה\"ו). ומיד לאחר נשואיה מתה והוא התחתן עם אחותה ומתה אף היא (ירו', כתובות פ\"ה ה\"ו). היה עני מרוד ולא היה לו לחם לאכול ור' יוחנן פיזר סלעים כדי שיזכה בהן רב שמן בר אבא (רו\"ר פ\"ה - ז'). לפני שנפטר ציווה לפנות הכלים מפני הטומאה (ירו', נזיר פ\"ג ה\"ה). הניח אחריו בן חכם ושמו רב עמרם (שבת קי\"ט ע\"ב).","cat": "sage"},{"i": 3777,"n": "ר' שמן בר רב יצחק","l": "ש","b": "מובא ב\"ילקוט\" (ישעיה סוף רמז רנז), ואולי יש ט\"ס בשם.","cat": "sage"},{"i": 3778,"n": "רבי שמעון","l": "ש","b": "סתם רבי שמעון הוא רבי שמעון בן יוחאי. נראה (פסחים קי\"ב ע\"א), שאמר רבי שמעון לר\"ע וכו' \"ואם אין אתה מלמדני אני אומר ליוחי אבא\".","cat": "sage"},{"i": 3779,"n": "שמעון אחי עזריה","l": "ש","b": "תנא בדור השני. דודו של רבי אלעזר בן עזריה ואחיו של עזריה. עזריה עסק במסחר לספק לשמעון אחיו את צרכיו, והיות ושמעון למד תורה ע\"י אחיו נקרא על שמו (סוטה כ\"א ע\"א רש\"י ד\"ה: ר' שמעון). מובא במשנה, שחלק על רבי אליעזר ויוסי בן חונא (זבחים ב' ע\"א), וכן מובא שחלק על רבי אליעזר ורבי יהושע (טהרות פ\"ח מ\"ז).","cat": "sage"},{"i": 3780,"n": "ר' שמעון אחיה דר' ברכיה","l": "ש","b": "מובא בירושלמי (ברכות פ\"ז ה\"א), ואולי יש ט\"ס בשם.","cat": "sage"},{"i": 3781,"n": "שמעון איש המצפה","l": "ש","b": "תנא בדור הראשון. חי בזמן הבית. מובא (פאה פ\"ב מ\"ו) שזרע שני מיני חיטים ובא לפני רבן גמליאל ועלו ללשכת הגזית ושאלו אמר נחום הלבלר וכו' (פאה פ\"ב מ\"ו), ומובא: \"מאן תנא סדר יומא רבי שמעון איש המצפה\" (יומא י\"ד ע\"ב).","cat": "sage"},{"i": 3782,"n": "שמעון איש קטרון","l": "ש","b": "תנא. מובא במכלתא (פ' בשלח פ\"ג).","cat": "sage"},{"i": 3783,"n": "שמעון אפרתי","l": "ש","b": "תנא בדור החמישי. משרתו של רבי. קודם פטירתו אמר רבי: \"יוסף חפני ושמעון אפרתי הם שמשוני בחיי והם ישמשוני במותי\" (כתובות ק\"ג ע\"א). הם נפטרו מיד לפני שרבי נפטר, והובן שכוונת רבי היתה שישמשוהו בעולם הבא.","cat": "sage"},{"i": 3784,"n": "רבי שמעון בולוטה","l": "ש","b": "אמורא ארצישראלי בדור השני. מסר בשם רבי חנינא (ירו', פסחים רפ\"ד). ר' יעקב בר אחא היה תלמידו (שם).","cat": "sage"},{"i": 3785,"n": "שמעון בן אבטולמוס","l": "ש","b": "מובא בבבלי (ב\"ב ס\"ח ע\"א).","cat": "sage"},{"i": 3786,"n": "רבי שמעון בן אבישלום","l": "ש","b": "מובא בבבלי (ברכות ז' ע\"ב, מגילה י\"ד ע\"א), וצריך לגרוס אבישלום ולא אבשלום. כן פירשו תוספות, כי אבשלום אין לו חלק לעולם הבא (יומא ל\"ח ע\"ב).","cat": "sage"},{"i": 3787,"n": "רבי שמעון בן איסי בן לקוניא","l": "ש","b": "מובא בבבלי (ב\"מ פ\"ה ע\"א), והוא ר' שמעון בן יוסי בן לקוניא.","cat": "sage"},{"i": 3788,"n": "רבי שמעון בן אליקים","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של רבי יוחנן (סנהדרין ל' ע\"ב). הקשה לרבי שמעון בן לקיש (ע\"ז ל\"ד ע\"ב), אך אין להכריע אם היה תלמידו. אף שקרא לרבי אלעזר רבי (כתובות נ' ע\"ב), נראה יותר שהיו חברים. שאל את רבי אלעזר, ואמר לו: \"דבר שהראשונים לא אמרו בו טעם תשאלני בבית המדרש כדי לביישני\" (ב\"ב פ\"א ע\"ב).","cat": "sage"},{"i": 3789,"n": "רבי שמעון בן אלעזר","l": "ש","b": "תנא בדור החמישי. תלמידו המובהק של רבי מאיר (חולין ו' ע\"א). אמר: \"משרת רבי מאיר הייתי וכו'\" (ירו', מו\"ק פ\"ג ה\"א). יש אומרים מקלו של רבי מאיר היה בידו. וכן מצינו: 'אמר רבי שמעון בן אלעזר: 'פעם אחד חש רבי מאיר בעיניו וביקשני לטרוף לו יין ושמן' וכו'\" (שבת קל\"ד ע\"א). מובא מעט במשנה ופעמים רבות בתוספתא ובברייתא. ומסופר מעשה שבא מבית רבו ושמח שמחה רבה והיתה דעתו גסה עליו מפני שלמד תורה הרבה; נזדמן לו אדם אחד מכוער ביותר, א\"ל: 'ריקא כמה מכוער אותו איש' ענה לו האיש: 'לך לאומן שעשני ואמור לו', כיון שידע בעצמו שחטא ירד מן החמור וביקש ממנו מחילה (אדר\"ב פמ\"א). וממנו המאמר במשנה: \"ראית מימיך חיה ועוף שיש להם אומנות והם מתפרנסין שלא בצער\" (קידושין פ\"א ע\"א). האריך ימים עד שרבי יוחנן בהיותו תינוק ראהו (ירו', מעשרות פ\"א ה\"ב), וכן ראהו רבי שמואל בר נחמני (ב\"ר פ\"ט - ה').","cat": "sage"},{"i": 3790,"n": "שמעון בן אנטיפרס","l": "ש","b": "חי בדור השני לתנאים. מובא (ד\"א רבה פ\"ו), שהיה מלקה את אורחיו ורבי יהושע הלך אליו לברר הסיבה. ואין להוכיח שהיה מן החכמים.","cat": "sage"},{"i": 3791,"n": "רבי שמעון בן בתירא","l": "ש","b": "תנא בדור השני - השלישי. מובא במשנה: \"העיד ר\"ש בן בתירא וכו' הוסיף רבי עקיבא\" (עדיות פ\"ח מ\"א).","cat": "sage"},{"i": 3792,"n": "שמעון בן גודא","l": "ש","b": "תנא. העיד לפני בנו של ר\"ג (ע\"ז ל\"ב ע\"א). אם נניח שהעיד לפני בנו של רבן גמליאל הזקן, הרי שהיה בדור השני - השלישי לתנאים, ואם נניח שהעיד לפני בנו של ר\"ג דיבנה, הרי שהיה בדור הרביעי - החמישי. ועיין שם בתוספות (ד\"ה: אבל) והגמרא מפקפקת אם היה תנא אחד או שנים - אחד גודא ואחד גודע.","cat": "sage"},{"i": 3793,"n": "שמעון בן גודע","l": "ש","b": "מובא בבבלי (ע\"ז ל\"ב ע\"א). ע\"ע שמעון בן גודא.","cat": "sage"},{"i": 3794,"n": "רבן שמעון בן גמליאל (2)","l": "ש","b": "תנא בדור הראשון - השני. היה הנשיא הרביעי מבית הלל ושימש בנשיאות קודם החורבן, שאמרו: הלל שמעון גמליאל (הוא רבן גמליאל הזקן) ושמעון (הוא רבן שמעון בן גמליאל שלנו) נהגו נשיאותן בפני הבית מאה שנה (שבת ט\"ז ע\"א). היה מעשרת הרוגי מלכות, ושמואל הקטן ניבא קודם פטירתו ואמר: \"שמעון וישמעאל לחרבא\", ופרש\"י: \"רבן שמעון שהוא נשיא ור' ישמעאל בן אלישע כהן גדול שהרגתם מלכות יון\" (סוטה מ\"ח ע\"ב). וכן מצינו: \"כשנהרגו רשב\"ג הזקן ור' ישמעאל בן אלישע כהן גדול באה השמועה אצל רבי עקיבא ור' יהודה בן בתירא עמדו וחגרו שקים וקרעו בגדיהם (שמחות פ\"ח). \"אמרו עליו על רשב\"ג כשהיה שמח שמחת בית השואבה היה נוטל שמונה אבוקות של אור וזורק אחת ונוטל אחת ואין נוגעות זו בזו וכשהוא משתחוה נועץ שני גודליו בארץ ושוחה ונושק את הריצפה וזוקף ואין כל בריה [בדורו] יכולה לעשות כן\" (סוכה נ\"ג ע\"א). בנו הוא רבן גמליאל דיבנה ובתו היא אימא שהתחתנה עם רבי אליעזר בן הורקנוס (ב\"מ נ\"ט ע\"ב).","cat": "sage"},{"i": 3795,"n": "רבן שמעון בן הלל הזקן","l": "ש","b": "נשיא ישראל. בנו של הלל. מובא רק פעם אחת בש\"ס: \"הלל ושמעון גמליאל [רבן גמליאל הזקן] ושמעון [רבן שמעון הנהרג] נהגו נשיאותן בפני הבית מאה שנה\" (שבת ט\"ו ע\"א), והיות שידוע לנו שהלל החל בנשיאותו 001 שנה לפני החורבן, ושימש כנשיא 04 שנה (ספרי ברכות סל\"ו), א\"כ החל שמעון נשיאותו 06 שנה לפני החורבן. הנשיא אחריו היה רבן גמליאל הזקן בנו. לא מובאת ממנו שום הלכה, תקנה, מימרה או אגדה.","cat": "sage"},{"i": 3796,"n": "רבי שמעון בן הסגן","l": "ש","b": "לדעתו של הרמב\"ם (בהקדמתו לזרעים) היה בנו של רבי חנינא סגן הכהנים, ואם כן היה תנא בדור השני - השלישי. רשב\"ג אמר משמו כמה פעמים (מנחות ק' ע\"ב).","cat": "sage"},{"i": 3797,"n": "שמעון בן זומא","l": "ש","b": "תנא בדור השלישי. אמרו: \"ראוי להוראה כגון מאן אמר רבא כגון שמעון בן עזאי ושמעון בן זומא\" (הוריות ב' ע\"ב), ופרש\"י: \"שהיו יושבין לפני חכמים והיו ראויין להוראה\". ועל אף שלא הגיע לסמיכה כמו חברו בן עזאי לא היו בימיהם כמותם בתורה (קידושין מ\"ט ע\"ב רשי ד\"ה: בן), ועל שניהם אמרו: \"דנין לפני חכמים\" (סנהדרין י\"ז ע\"ב). היה תלמידו של רבי יהושע (ירו', נזיר פ\"ח ה\"א) וחברו של רבי עקיבא (חגיגה י\"ד ע\"ב). נמנה עם ארבעת החכמים שנכנסו ל\"פרדס\" (פרש\"י: \"עלו לרקיע על ידי שם\") ואלו הן: בן עזאי ובן זומא אחר ורבי עקיבא וכו', והוא הציץ ונפגע (שם), ופירש\"י: \"נטרפה דעתו\". היה עשיר גדול (ברכות כ\"ה ע\"א רש\"י). היה דרשן גדול ואמרו: \"משמת בן זומא בטלו הדרשנים\" (סוטה מ\"ט ע\"א). ואמרו: \"הרואה בן זומא בחלום יצפה לחכמה\" (ברכות נ\"ז ע\"ב). נראה, שנפטר בחיי רבי יהושע (תוספתא חגיגה פ\"ב).","cat": "sage"},{"i": 3798,"n": "ר' שמעון בן זירא","l": "ש","b": "אמורא בבלי. מובא בבבלי: \"אמר אביי בירושלים וכן תני רב שמעון בר זירא בקידושי דבי לוי\" (קידושין ע\"ו ע\"ב).","cat": "sage"},{"i": 3799,"n": "רבי שמעון בן זירוז","l": "ש","b": "הוא רבי שמעון בר זירוד.","cat": "sage"},{"i": 3800,"n": "ר' שמעון בן זכריה","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. רבי יונה מסר משמו (ירו', דמאי פ\"ב ה\"א).","cat": "sage"},{"i": 3801,"n": "רבי שמעון בן חלפתא","l": "ש","b": "תנא בדור החמישי. בן בנו של רבי יוסי בן חלפתא, כמובא שרבי יוסי יבם את אשת אחיו ונטע חמשה ארזים בישראל: רבי ישמעאל ורבי אלעזר ורבי חלפתא וכו' (שבת קי\"ח ע\"ב). מסר בשם רבי מאיר (ירו', תענית פ\"ד ה\"א) והיה חביב על רבי, שא\"ל רבי לרבי שמעון בן חלפתא: \"מפני מה לא הקבלנו פניך ברגל וכו'\" (שבת קנ\"ב ע\"א). הלך יחד עם רבי חייא בבקעת ארבל וראו איילת השחר שבקע אורה (ירו', ברכות פ\"א ה\"א), וכן מצינו אותו יחד עם רבי חייא ורבי שמעון בר רבי (ב\"ר פע\"ט - ז'). היה עני מרוד (רו\"ר פ\"ה - ז'). נתנו לו מרגלית מן השמים והחזירה (רו\"ר פ\"ג - ז'). פעם אחת פגעו בו שני אריות ואירע לו נס וירדו מן השמים שתי ירכים האחת אכלו האריות והשניה הביא לבית המדרש (סנהדרין נ\"ט ע\"ב). בירך בברית מילה שיזכה התינוק להכנס לחופה ובלילה פגש במלאך המות שבא ליטול את נשמת התינוק וביטל את הגזירה והתינוק נשאר בחיים (קה\"ר פ\"ג - ב').","cat": "sage"},{"i": 3802,"n": "רבי שמעון בן חנניה","l": "ש","b": "תנא בדור השלישי - הרביעי. חברו של רבי יוסי הגלילי. ומצינו: \"פעם היה ר' יוסי הגלילי יושב ודורש בפרה בטבריה ור' שמעון בן חנינא יושב עמו\" (ילקוט חוקת פ' ולקח). ומצינו: א\"ר חלפתא איש כפר חנניא שאלתי את שמעון בן חנניה ששאל בנו של רבי חנינא בן תרדיון\" (תוספתא כלים פ\"ט ט').","cat": "sage"},{"i": 3803,"n": "שמעון בן טרפון","l": "ש","b": "תנא שאין לקבוע זמנו ומקומו. מובא בבבלי (שבועות מ\"ז ע\"ב). קשה להניח שהיה בנו של רבי טרפון.","cat": "sage"},{"i": 3804,"n": "רבי שמעון בן יאסיניה","l": "ש","b": "הוא רבי שמעון בן יוסינא.","cat": "sage"},{"i": 3805,"n": "רבי שמעון בן יהודה","l": "ש","b": "נראה שהוא רבי שמעון בן יהודה איש כפר עכו (ע\"ע).","cat": "sage"},{"i": 3806,"n": "רבי שמעון בן יהודה איש כפר עכו","l": "ש","b": "תנא בדור החמישי. מסר הרבה פעמים בשם רבי שמעון בן יוחאי (סוטה ל\"ז ע\"ב), אך לא מצינו במפורש שיש קשר ביניהם. קשה לקבוע בוודאות מי היה יהודה אביו. סביר לומר שרבי שמעון בן יהודה (שבת ע\"ט ב') הוא הוא רבי שמעון בן יהודה איש כפר עכו.","cat": "sage"},{"i": 3807,"n": "רבי שמעון בן יהוצדק א'","l": "ש","b": "תנא, וכתבו תוספות (סוכה י\"א ע\"ב ד\"ה: דברי). מאחרוני התנאים בארץ ישראל. רבו של רבי יוחנן (יומא מ\"ג ע\"ב), ולא מצינו בשום מקום בש\"ס שדיברו יחד או ישב לפניו. היה כהן ונפטר בלוד. ובא יוחנן אחיו להטמא לו (שמחות פ\"ד י\"א) ורבי יוחנן ורבי ינאי הלכו אחרי מטתו (ירו', נזיר פ\"ז ה\"א).","cat": "sage"},{"i": 3808,"n": "רבי שמעון בן יהוצדק ב'","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. חברו של ר' חייא בר זרנוקי. שניהם הלכו לעבר שנה באסיא (סנהדרין כ\"ו ע\"א), וריש לקיש פגש בהם והקשה להם כמה קושיות ולבסוף קרא להם \"רועי בקר\" ובאו להתלונן לפני רבי יוחנן (שם).","cat": "sage"},{"i": 3809,"n": "רבי שמעון בן יוחאי","l": "ש","b": "מגדולי התנאים בדור הרביעי, וסתם רבי שמעון בש\"ס הוא רבי שמעון בן יוחאי (שבועות ב' ע\"ב רש\"י). מחשובי תלמידיו של רבי עקיבא (כתובות ס\"ב ע\"ב) ולמד אצלו שלש עשרה שנה (ויק\"ר פכ\"א - ח') ורבי עקיבא קראו \"בני\" (מעילה ז' ע\"א). גם כשרבי עקיבא נחבש בבית האסורים היה רבי שמעון לידו (פסחים קי\"ב ע\"א). בצעירותו למד ביבנה ומצינו (ברכות כ\"ז ע\"ב) מעשה בתלמיד אחד שבא לפני רבי יהושע וכו' בא לפני רבן גמליאל (דיבנה וכו') ושם (כ\"ח ע\"א) \"ואותו תלמיד רבי שמעון בן יוחאי הוה\". אח\"כ הוסמך יחד עם חבריו על ידי רבי יהודה בן בבא (סנהדרין י\"ד ע\"א). דיבר נגד המלכות ורצו להרגו וברח יחד עם בנו רבי אלעזר למערה. לסוף י\"ב שנה בא אליהו ואמר להם לצאת וכשיצאו ראו אנשים מניחים חיי עולם ועוסקים בחיי שעה וכל מקום שנתנו עיניהם מיד נשרף. יצאה בת קול ואמרה: \"להחריב עולמי יצאתם?\" חזרו למערתם וחזרו ושהו בה שנה נוספת (שבת ל\"ג ע\"ב). חתנו רבי פנחס בן יאיר היה גדול ממנו בטרם נכנס למערה, אך לאחר שיצא משם היה רבי שמעון בן יוחאי גדול ממנו (שם). ורבי שמעון אמר לבנו אלעזר: \"די לעולם אני ואתה\" (שם), ורבי עקיבא אמר לו: \"דייך שאני ובוראך מכירין כוחך\" (ירו', סנהדרין פ\"א ה\"ז) וכן אמר רשב\"י: \"יכול אני לפטור את כל העולם כולו מן הדין וכו' ואלמלא אלעזר בני עמי וכו'\" (סוכה מ\"ה ע\"ב). ומצינו (סנהדרין פ\"ו ע\"א) סתם ספרי רבי שמעון אליבא דר\"ע. וכן יצא מבית מדרשו של רבי שמעון מדרש הלכה לספר שמות הוא מכילתא דרשב\"י (להבדילה ממכילתא דר' ישמעאל), ומיוחס לו ספר \"הזוהר\". פעם אחת גזרה המלכות גזרה שלא ישמרו את השבת ולא ימולו את בניהם ויבעלו נדות וכו'. אמרו: 'מי ילך ויבטל הגזרות? ילך ר\"ש בן יוחאי, שהוא מלומד בנסים' (מעילה י\"ז ע\"א). פעם יצא אחד מתלמידי רשב\"י לחו\"ל וחזר עשיר והיו מהתלמידים מקנאים בו, ואמר רשב\"י: \"בקעה בקעה המלאי זהב\", וכך היה, ואמר לתלמידיו: \"טלו לכם זהב, אך מחלקכם בעולם הבא אתם נוטלים\" (שמו\"ר פנ\"ב - ג') האריך ימים אחר ר' ישמעאל (יומא נ\"ט ע\"ב תד\"ה: משכיה). בין תלמידיו היה בנו רבי אלעזר (שבת ל\"ג ע\"ב) ורבינו הקדוש (עירובין צ\"א ע\"ב).","cat": "sage"},{"i": 3810,"n": "רבי שמעון בן יוסי","l": "ש","b": "מובא בבבלי (הוריות ב' ע\"א), ואולי צ\"ל: רבי שמעון בן יהודה.","cat": "sage"},{"i": 3811,"n": "רבי שמעון בן יוסינא (2)","l": "ש","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ריש לקיש (בכורות מ\"ז ע\"ב). מסר בשם רבי אושעיא (ירו', יבמות פי\"ג ה\"א). רבי אלעאי מסר בשמו (שם).","cat": "sage"},{"i": 3812,"n": "רבי שמעון בן יעקב דמן צור","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן. שאל את רבי יוחנן (ברכות ל\"ג ע\"א). מצינו: \"אמר רבי אבהו שאל רבי ישמעאל בן יעקב דמן צור את ר' יוחנן בציידן\" [בענין אחר] (כתובות ז' ע\"א), ולכן \"סה\"ד\" כתב שאולי אחד ט\"ס עכ\"ל, ואני סיווגתי את שניהם כתלמידי רבי יוחנן.","cat": "sage"},{"i": 3813,"n": "רבי שמעון בן יקים","l": "ש","b": "מובא בירושלמי (פאה פ\"ז ה\"א), והוא רבי שמעון בן אליקים.","cat": "sage"},{"i": 3814,"n": "שמעון בן לגס","l": "ש","b": "מובא בירושלמי (יומא פ\"ג ה\"ט), והוא כנראה רבי ישמעאל בן לוגא.","cat": "sage"},{"i": 3815,"n": "שמעון בן לוגא","l": "ש","b": "מובא בירושלמי (שקלים פ\"ה), והוא רבי ישמעאל בן לוגא.","cat": "sage"},{"i": 3816,"n": "רבי שמעון בן לוי","l": "ש","b": "מובא בבבלי (קדושין ל' ע\"ב) המאמר המובא שם במקום אחר (סוכה נ\"ב ע\"ב) בשם רבי שמעון בן לקיש, ואולי היה כתוב רשב\"ל והמדפיס פיענח רבי שמעון בן לוי במקום לקיש. כן מובא מאמרו: \"כל שהוא רחמן על האכזרים סוף שנעשה אכזר על הרחמנים\" (מדרש שמואל פי\"ח). וב\"ילקוט\" (שם) מובא מאמר זה בשם ריב\"ל.","cat": "sage"},{"i": 3817,"n": "רבי שמעון בן לקיש","l": "ש","b": "מגדולי אמוראי ארץ ישראל בדור הראשון. גיסו (בעל אחותו) של רבי יוחנן (ב\"מ פ\"ד ע\"א). בתחילה היה תלמידו המובהק של רבי יוחנן ולמד בשקידה עצומה והיה מסדר מתניתיה ארבעים פעם לפני שבא לפני רבי יוחנן ללמוד (תענית ח' ע\"א) ואח\"כ הפך להיות לו לתלמיד חבר: \"אמר להו [ר' יוחנן] מה אעשה כנגדי\" [ריש לקיש שקול כמותי] (כתובות פ\"ד ע\"ב). רבי יוחנן קראו מר (יומא ג' ע\"ב). ומצינו: \"איתיביה רבי יוחנן לריש לקיש\" (יבמות י' ע\"ב). היה צעיר מרבי יוחנן (מעילה ז' ע\"ב רש\"י ד\"ה: אמר). מוצאו ממשפחת חכמים (שבת קי\"ט ע\"ב) בצעירותו זכה להיות מתלמידיו הקטנים של רבינו הקדוש, כפי שהוא עצמו אמר: \"לא זכינן לאורייתא אלא בגיל דחמינן אצבעתיה דרבי\" (ירו', ביצה פ\"ה ה\"ב). תוספות כתבו \"מכאן אמר ר\"ת דריש לקיש מתחילה ידע הרבה אלא שפרק עול תורה ונעשה עם הארץ\" (ב\"מ שם ד\"ה: אי) - [אולי על המשקל של רבי אלעזר בן ערך, שנמשך אחר היין והרחיצה ונעקר תלמודו ושכחו ואחר כך חזר אליו, (שבת קמ\"ז ע\"ב)]. ועסק בליסטות ופגש ברבי יוחנן, ורבי יוחנן התפעל מכוחו העצום, ובהשפעתו התחיל ללמוד תורה ונתן לו את אחותו לאשה. ומשמע שיגיעתו בתורה היתה כמו של רבי חייא (ירו', כלאים פ\"ט ה\"ג). והיה כה חריף עד שאמר הרואה את ריש לקיש בבית המדרש כאילו עוקר הרים וטוחנן זה בזה (סנהדרין כ\"ד ע\"א). היה מתפלפל עם רבי יוחנן ועל כל דבר ודבר הקשה לו עשרים וארבע קושיות ומתרץ עשרים וארבעה תירוצים (ב\"מ פ\"ד ע\"א) ולשניהם קראו \"שני גדולי עולם\" (ירו', ברכות פ\"ח ה\"ו). היה גם תלמידם של רבי יהושע בן לוי (ירו', מו\"ק פ\"ב ה\"ד) רבי חנינא (שבת קי\"ד ע\"א) ורבי אושעיא (יבמות נ\"ז ע\"א תוס'). צם 003 תעניות כדי לראות את רבי חייא (ירו', כלאים פ\"ט ה\"א). כשהיה מראשי הדור תפסו גזלנים את רבי אמי, ור\"ל אמר אני ארדוף אחריהם, או שאהרגם או שיהרגו אותי, ולבסוף הסתכן והצילו מידם (ירו', תרומות ספ\"ח). פעם הרג לחבורת רוצחים שלמה וניצל (גיטין מ\"ז ע\"א). נקרא \"תקיפי ארעא דישראל\" (חולין קכ\"ב ע\"א). לא היה מתחיל לדבר עם איש, ולמי שר\"ל דיבר עמו יכלו לתת הלואה ללא עדים (יומא ט' ע\"ב). מאחר שהיה כתלמיד - חבר לרבי יוחנן היו להם תלמידים משותפים רבים ור\"ל היה חוזר ושונה לתלמידים מה שדרש רבי יוחנן (ב\"ק קי\"ז ע\"א רש\"י ד\"ה: וסיים). לא רצה ליהנות מכבוד התורה (מגילה כ\"ח ע\"ב). כל ימיו כל מה שהיה משתכר לא היה מצמצם להצניע ליום מחר (גיטין מ\"ז ע\"א רש\"י ד\"ה: יתיב). כשמת היה כל עזבונו שהניח אחריו קב של מוריקא, וקרא על עצמו \"ועזבו לאחרים חילם\" (שם). על פטירתו מסופר (ב\"מ שם) שפעם אחת בשעת ויכוח הלכתי עם רבי יוחנן על כלי זין לענין טומאה הזכיר לו ר' יוחנן את עברו, שהיה משתמש בכלי זין, ור\"ל השיב לו בתקיפות רבה ורבי יוחנן הקפיד עליו וחלה ריש לקיש ומת, ורבי יוחנן קרע בגדיו ומיאן להתנחם עד שדעתו נעקרה עליו וחכמים בקשו רחמים ומת גם הוא (ב\"מ שם). ריש לקיש השאיר אחריו בן צעיר חכם גדול וחריף (תענית ט' ע\"א).","cat": "sage"},{"i": 3818,"n": "רבי שמעון בן מנסיא","l": "ש","b": "תנא בדור החמישי. מסר בשם רבי שמעון בן יוחאי (אבות פ\"ו מ\"ט), אך נראה מדברי רש\"י שלא היה תלמידו של רשב\"י (ביצה כ\"ו ע\"א ד\"ה: א\"ל רבי). גם ממה שמצינו: \"רבי שמעון בן אלעזר אומר משום רבי מאיר וכן היה רבי שמעון בן מנסיא אומר כדבריו\" (כתובות י\"ד ע\"ב) אין ראיה, שהיה תלמידו של רבי מאיר. ר' יוסי בן המשלם היה חברו ושניהם מכונים \"עדה קדושה\" והיה חברו של רבי וחלק עמו (ביצה כ\"ו ע\"א) ואמר על רבי \"שבע מידות שמנו חכמים לצדיקים כולן נתקיימו ברבי ובניו\" (אבות פ\"ו מ\"ט).","cat": "sage"},{"i": 3819,"n": "שמעון בן נזירא","l": "ש","b": "אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי (שקלים פ\"ב ה\"ה) ע\"ע בר טירא.","cat": "sage"},{"i": 3820,"n": "רבי שמעון בן ננס","l": "ש","b": "תנא בדור השלישי. חברם של רבי ישמעאל ורבי עקיבא ובר פלוגתיה שלהם. רבי ישמעאל אמר עליו: \"הרוצה שיחכים יעסוק בדיני ממונות וכו' והרוצה שיעסוק בדיני ממונות ישמש את שמעון בן ננס\" (ב\"ב קע\"ה ע\"ב). חלק עם רבי עקיבא (מנחות מ\"ה ע\"ב). לפי דעת הרמב\"ם (בהקדמה לזרעים) וכן לדעת הר\"ח (סנהדרין י\"ז ע\"ב) היה שמעון בן ננס מן הדנים לפני חכמים ביבנה (שם).","cat": "sage"},{"i": 3821,"n": "רבי שמעון בן נתנאל","l": "ש","b": "תנא בדור השני. תלמיד רביעי מחמשת תלמידיו המצויינים של רבי יוחנן בן זכאי (אבות פ\"ב מ\"ח). ריב\"ז אמר עליו: \"ירא חטא\". רבן גמליאל הזקן נתן לו את בתו לאשה (תוספתא ע\"ז פ\"ג). דרש במעשה מרכבה: \"בתקופת תמוז היה ורעשה הארץ ונראתה הקשת בענן ויצאה בת קול ואמרה: 'הרי המקום פנוי לכם והטרקלין מוצע לכם וכו'\" (ירו', חגיגה פ\"ב ה\"א).","cat": "sage"},{"i": 3822,"n": "שמעון בן עזאי","l": "ש","b": "תנא בדור השלישי - הרביעי. תלמידו המובהק של רבי עקיבא (ברכות ס\"ב ע\"א) והפך לו לתלמיד חבר (ב\"ב קנ\"ח ע\"ב), ונכנס עמו ל\"פרדס\" (חגיגה י\"ד ע\"ב, וע\"ע שמעון בן זומא) והציץ ומת. אף שהיה מן \"הדנים לפני חכמים\" (סנהדרין י\"ז ע\"ב) לא נסמך מעולם (קידושין מ\"ט ע\"ב רש\"י). כשדרש בן עזאי (יבמות ס\"ג ע\"ב): \"כל יהודי שאין עוסק בפריה ורביה וכו' כאילו שופך דמים\" אמרו לו: \"נאה דרש ואין נאה מקיים\" (שלא התחתן מעולם או התחתן ופרש - סוטה ד' ע\"ב) ענה להן בן עזאי: \"ומה אעשה שנפשי חשקה בתורה\". ולקח את בת רבי עקיבא באירוסין ופרש ממנה (כתובות ס\"ג ע\"א תד\"ה: ברתיה). רבנו גרשום כתב, שלמד לפני רבי אליעזר בן הורקנוס (ב\"ב קנ\"ח ע\"ב) [לא מצאתי את המקור לדברי רבנו גרשום] וכן מסר בשם רבי יהושע (יומא כ\"ה ע\"א), והצטער על שלא שימש את רבי ישמעאל (חולין ע' ע\"ב). רבי ישמעאל ורבי עקיבא ובן עזאי מכונים \"ג' זקנים\" (תמורה כ\"א ע\"ב). היה סמל השקידה ואמרו: \"משמת בן עזאי בטלו השקדנים\" (סוטה מ\"ט ע\"א). רש\"י כתב: \"ולא היה בימיהם [בן זומא ובן עזאי] כמותם בתורה\" (קידושין מ\"ט ע\"ב). וכך הפך בן עזאי להיות לסמל בידיעת התורה. רבי יוחנן אמר: \"אנא בן עזאי, דהכא\" (ירו', בכורים פ\"ב ה\"ב), אביי אמר: \"הריני כבן עזאי בשוקי טבריה\" (קידושין כ' ע\"א) וכן אמר רבא: (עירובין כ\"ט ע\"א). ומצינו: \"בן עזאי אומר: 'כל חכמי ישראל דומין עלי כקליפת השום חוץ מן הקרח הזה'\" (בכורות נ\"ח ע\"א), ופירש רש\"י: רבי עקיבא. ודעת המדרש, שבן עזאי היה מעשרת הרוגי מלכות (איכ\"ר פ\"ב פ' בלע).","cat": "sage"},{"i": 3823,"n": "ר' שמעון בן עקשיה","l": "ש","b": "תנא שאין לקבוע זמנו. מאמרו היחיד מובא במשנה (סוף קנים).","cat": "sage"},{"i": 3824,"n": "רבי שמעון בן פזי","l": "ש","b": "אמורא ארץ ישראלי בדור השני. תלמידו המובהק של רבי יהושע בן לוי (ברכות י' ע\"א) מסר גם בשם בר קפרא (זבחים ס\"א ע\"ב) רבין מסר משמו: \"כי אתא רבין אמר ר\"ש בן פזי וכו'\". הניח אחריו בן חכם ושמו רב יהודה (ברכות ט' ע\"ב).","cat": "sage"},{"i": 3825,"n": "רבי שמעון בן קיסמא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי שמעון בן לקיש.","cat": "sage"},{"i": 3826,"n": "ר' שמעון בן רבי עקיבא","l": "ש","b": "תנא בדור הרביעי. בנו של רבי עקיבא. רבי עקיבא הביאו לחופה ועשה לו משתה ופתח חביות יין במשתה (ירו', ברכות ספ\"ו). בנו זה מת על פני אביו ורבי עקיבא הספידו ואמר: \"יודע אני שהוא בן עולם הבא, שזיכה את הרבים\" (שמחות פ\"ח).","cat": "sage"},{"i": 3827,"n": "שמעון בן שטח","l": "ש","b": "מחכמי ה\"זוגות\" שלפני התנאים. הוא וחברו יהודה בן טבאי היו ה\"זוג\" השלישי. קיבלו מיהושע בן פרחיה ונתאי הארבלי ומסרו לשמעיה ואבטליון. יהודה בן טבאי היה הנשיא ושמעון בן שטח היה אב\"ד (חגיגה ט\"ז ע\"ב). כשיהודה בן טבאי טעה פעם בפסק דין והרג שלא כדין עד זומם, אמר לו שמעון בן שטח: \"אראה בנחמה אם לא שפכת דם נקי\", ומאז קיבל עליו יהודה בן טבאי להורות רק ע\"פ שמעון בן שטח (תוספתא סנהדרין פ\"ו ז'). אחותו המלכה שלומציון היתה נשואה לינאי המלך (ברכות מ\"ח ע\"ב). הסתכסך עם ינאי המלך ומכעס המלך ברח (ירו', ברכות פ\"ז ה\"ב), וכשבאו שרים גדולים מפרס ושאלו עליו החזירו המלך (שם). פעם הרג עבדו של ינאי המלך נפש וכשהעמידוהו לדין ציווה עליו שמעון בן שטח שיעמוד על רגליו וסירב ואמר שהסנהדרין יצוו עליו והיו הסנהדרין יראים מינאי מלומר לו שיעמוד. אמר להם שמעון בן שטח: \"בעלי מחשבות אתם, יבוא בעל המחשבות וייפרע מכם, מיד בא גבריאל וחבטן בקרקע ומתו\" (סנהדרין י\"ט ע\"ב). תלה 08 מכשפות באשקלון (ירו', חגיגה פ\"ב ה\"ב) והענין מובא ברש\"י (סנהדרין מ\"ד ע\"ב). כשמת ינאי המלך ציווה לפני מותו שאשתו שלומציון תמלוך ויעץ לה להשלים עם הפרושים (סוטה כ\"ב ע\"ב), ומאז היה למנהיג האומה כולה (קדמוניות היהודים). ואז היו הימים הטובים לישראל כמסופר, שבימי שמעון בן שטח \"ירדו להם גשמים בלילי רביעית ובלילי שבתות עד שנעשו חטים ככליות ושעורים כגרעיני זיתים ועדשים כדינרי זהב וצררו מהם דוגמא לדורות\" (תענית כ\"ג ע\"א). בימיו היה חוני המעגל (בכורות י\"ט ע\"א). בבנו העידו שני עדי שקר (מקרובי המכשפות שנתלו באשקלון) על חיוב מיתה ונגמר דינו וחזרו בהם העדים ואעפ\"כ הרגוהו בית דין על פי הדין שנגמר נגדו (סנהדרין מ\"ד ע\"ב רש\"י).","cat": "sage"},{"i": 3828,"n": "ר' שמעון בן שקפא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. מובא בקה\"ר, שאמר רבי יודן בשמו (פ\"א - רפי\"א).","cat": "sage"},{"i": 3829,"n": "רבי שמעון בן תחליפא","l": "ש","b": "מובא בבבלי (כתובות קי\"א ע\"ב), וגירסת הגר\"א: רבי שמעון בן תחלפא.","cat": "sage"},{"i": 3830,"n": "רבי שמעון בנו של רבי יוחנן בן ברוקא","l": "ש","b": "מובא בבבלי (פסחים צ\"א ע\"א), וצ\"ל כנראה \"רבי ישמעאל בנו\" וכו'.","cat": "sage"},{"i": 3831,"n": "רבי שמעון בר אבא","l": "ש","b": "הוא רב שמן בר אבא.","cat": "sage"},{"i": 3832,"n": "רבי שמעון בר אחא","l": "ש","b": "מובא (ירו', ע\"ז פ\"ב ה\"ד) ונראה שצריך לומר רבי שמעון בר אבא.","cat": "sage"},{"i": 3833,"n": "רבי שמעון בר אמי","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. רבי ברכיה מסר משמו: \"אשרי לאדם שהוא גבוה מפשעיו\" (ב\"ר פכ\"ב - ו').","cat": "sage"},{"i": 3834,"n": "ר' שמעון בר בא","l": "ש","b": "הוא רב שמן בר אבא.","cat": "sage"},{"i": 3835,"n": "ר' שמעון בר ביסנא","l": "ש","b": "מובא בתנחומא (הישן פ' נשא), וכן גירסת הב\"ח בבבלי (שבת ע\"ה ע\"ב) ולפנינו רבי שמעון בן קיסמא.","cat": "sage"},{"i": 3836,"n": "רבי שמעון בר ברסנה","l": "ש","b": "מובא בירושלמי (ע\"ז פ\"א ה\"א), וצ\"ל: רבי שמעון בר כרסנא.","cat": "sage"},{"i": 3837,"n": "ר' שמעון בר הלל","l": "ש","b": "מאחרוני האמוראים בארץ ישראל בדור הששי. אביו רבי הלל בר פזי היה תלמידו של רבי יוסי (חברו של רבי יונה), כדמצינו בירושלמי (כתובות רפ\"ט). בנו ר' שמעון היה תלמידו של אביו (ירו', סנהדרין פ\"ז ה\"ה).","cat": "sage"},{"i": 3838,"n": "שמעון בר ווא","l": "ש","b": "הוא רב שמן בר אבא.","cat": "sage"},{"i": 3839,"n": "רבי שמעון בר זביד","l": "ש","b": "אמורא בדור הרביעי. תלמידו של רבי יצחק בן טבלא (נדרים ח' ע\"ב). גם אחיו היה חכם גדול: \"משתבחין ליה רבנן לר' זירא את בר רב זביד אחוה דרבי שמעון בר רב זביד\" (ברכות ל\"ח ע\"א).","cat": "sage"},{"i": 3840,"n": "רבי שמעון בר זירוד","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין י\"ד ע\"א).","cat": "sage"},{"i": 3841,"n": "שמעון בר חוטא","l": "ש","b": "מובא בב\"ר (פכ\"ו - א'), ויש בר חטייא (ב\"ר פ\"ל - ח').","cat": "sage"},{"i": 3842,"n": "שמעון בר חייא","l": "ש","b": "אמורא בבלי בדור השני. מתלמידיו הגדולים של רב ורבו של חייא בנו של רב (ירו', ע\"ז פ\"ד ה\"א). מסרו משמו רב יהודה (ירו', שבת ספ\"ה) ורבי אלעאי (שם פ\"ו ה\"א).","cat": "sage"},{"i": 3843,"n": "ר' שמעון בר חנן","l": "ש","b": "אמורא ארץ ישראלי בדור השני. מסר בשם ר' יוסי בר קצרתא (מדרש תהלים פע\"ח).","cat": "sage"},{"i": 3844,"n": "רבי שמעון בר יוסי בן לקוניא","l": "ש","b": "תנא בדור החמישי. גיסו של רבי אליעזר בן שמעון [שהיה חתנו של רבי יוסי בן לקוניא] (ב\"מ פ\"ח ע\"א). חברו של רבי חייא (ירו', ברכות פ\"ב ה\"ג). רבו של רבי יונתן (ירו', הוריות פ\"ב ה\"ה). כשנפטר רבי שמעון בר יוסי בן לקוניא הלכו שניהם אחרי מיטתו (ירו', ברכות שם). לימד תורה לבנו של רבי אלעזר בן שמעון ורבי קרא עליו: \"ולוקח נפשות חכם\" (ב\"מ פ\"ה ע\"א). \"יוחסין\" כתב, שהיה מבית דינו של רבי.","cat": "sage"},{"i": 3845,"n": "רבי שמעון בר ינאי","l": "ש","b": "אמורא ארץ ישראלי בדור השני. בנו של רבי ינאי האמורא הנודע. נראה, שבדרך כלל קיבל מאביו כמובא: \"דאמר רבי שמעון בי רבי ינאי אני לא שמעתי מאבא\" (ירו', שבת פי\"ג ה\"ז) ונראה דוקא בשאלה זו לא שמע, אבל בד\"כ שמע. מובא מעשה על ר' ינאי שקטף בכרמו במועד (מו\"ק י\"ב ע\"ב), ובירושלמי מובא אותו מעשה על רבי שמעון בר ינאי (מו\"ק פ\"ב ה\"ב). היה לו בן ושמו ר' ינאי (ב\"ר ספס\"א).","cat": "sage"},{"i": 3846,"n": "ר' שמעון בר ישמעאל","l": "ש","b": "מובא בש\"ר (פנ\"א - ד').","cat": "sage"},{"i": 3847,"n": "רבי שמעון בר כהנא","l": "ש","b": "תנא בדור השלישי. תלמידו של רבי אליעזר בן הורקנוס (ירו', דמאי פ\"ג ה\"ב). ורבנן שמעון בן גמליאל (אבי רבי) היה תלמידו (ירו', חלה פ\"ד ה\"ה). מובא מעשה בליסטים שנתפס בקיסרין שבקפודקיא וכשהיה יוצא ליהרג אמר להם צאו ואימרו לאשתו של שמעון בר כהנא שהרגתיו בכניסתו ללוד ובא מעשה לפני חכמים וכו' (תוספתא יבמות פ\"ד). \"סה\"ד\" סבר, כנראה, שאין זה התנא רבי שמעון בר כהנא אלא אחר ועל כן חילקו לשני ערכים.","cat": "sage"},{"i": 3848,"n": "רבי שמעון בר כרסנא","l": "ש","b": "אמורא ארץ ישראלי בדור החמישי. מסר משמו של רבי אחא ונראה שהיה תלמידו (ירו', שבת פ\"א רה\"ח).","cat": "sage"},{"i": 3849,"n": "ר' שמעון בר מיישא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר ושאל ממנו (ירו', מגילה פ\"א הי\"ב).","cat": "sage"},{"i": 3850,"n": "שמעון בר נרשייא","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם ריש לקיש (ירו' כלאים פ\"ג ה\"א). רבו של רבי אבא בר כהנא (שם).","cat": "sage"},{"i": 3851,"n": "ר' שמעון בר סימון","l": "ש","b": "מובא במדרש תהלים (פכ\"ה - ב'), ונראה שאולי יש ט\"ס בשם.","cat": "sage"},{"i": 3852,"n": "רבי שמעון בר סני","l": "ש","b": "מובא בירושלמי (דמאי פ\"ג ה\"א), ונראה שיבוש ואולי צ\"ל: רבי שמעון בר כרסנא.","cat": "sage"},{"i": 3853,"n": "רבי שמעון בר רב יצחק","l": "ש","b": "מובא בירושלמי (שבת פ\"ב ה\"ג).","cat": "sage"},{"i": 3854,"n": "רבי שמעון בר רבי","l": "ש","b": "תנא, מהתנאים האחרונים בדור המעבר בין התנאים לאמוראים. שמו מובא במשנה (מכות כ\"ג ע\"ב). בנו הצעיר של רבי (כתובות ק\"ג ע\"ב). \"יוחסין\" כתב, שהיה קטן מרבן גמליאל אחיו וגדול ממנו בחכמה. למד יחד עם ר' חייא ור' ישמעאל בר יוסי (יבמות ק\"ה ע\"ב). היה תלמידו המובהק של אביו (ב\"ק קי\"א ע\"ב). אביו קרא לו \"נר ישראל\" (ערכין י' ע\"א) לפני פטירתו מינה אותו אביו ל\"חכם\" ומסר לו את \"סדרי החכמה\" (כתובות ק\"ג ע\"ב). למד בחברותא יחד עם בר קפרא (מו\"ק ט\"ז ע\"א), וכן עם רבי חייא (קידושין ל\"ג ע\"א). היה גדול מרבי חייא (גיטין פ\"ד ע\"ב תד\"ה: רבי) כשהתחתן, עדיין רבי מאיר חי (ירו', ביצה פ\"ה ה\"ב). היה עשיר גדול (מנחות פ\"ו ע\"א). עסק בסחר משי בשותפות עם רבי חייא (ב\"ר פע\"ז - ב'). היה לו קול עבה ור' חייא אמר לו: \"אלמלא לוי אתה פסול אתה מן הדוכן משום דעבי קולך\" (מגילה כ\"ד ע\"ב). לא מצאנו שהיו לו בנים, וכשנולדה לו בת ניחמו אביו, ובר קפרא אמר לו: תנחומים של הבל ניחמך אביך (ב\"ב ט\"ז ע\"ב).","cat": "sage"},{"i": 3855,"n": "רבי שמעון בריה דרבי אייבו","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי (יבמות פי\"א ה\"ב) שעל קושייתו השיב רבי אלעאי.","cat": "sage"},{"i": 3856,"n": "ר' שמעון בריה דר' אבהו","l": "ש","b": "אמורא בדור הרביעי. בנו של רבי אבהו. מובא (ב\"ר פי\"ח - ה'), ואולי יש ט\"ס בשם וצ\"ל \"ר' שמעון בריה דר' אייבו\", כמובא בירושלמי (יבמות פי\"א ה\"ב).","cat": "sage"},{"i": 3857,"n": "ר' שמעון בר' אלעזר בן פרטא","l": "ש","b": "כן גיר' \"יוחסין\", ולפנינו אין.","cat": "sage"},{"i": 3858,"n": "ר' שמעון דיינא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי זירא וישב לפניו (ירו', נדרים פ\"ז ה\"י).","cat": "sage"},{"i": 3859,"n": "ר' שמעון דתוספתא","l": "ש","b": "מובא בירושלמי (ברכות פ\"ג ה\"ב). ע\"ע ר' שמואל דסופפתא.","cat": "sage"},{"i": 3860,"n": "רבי שמעון החסיד","l": "ש","b": "תנא דברייתא. מובא כמה פעמים באגדה (חגיגה י\"ג ע\"ב). רב הונא בר תורתא היה תלמידו (חולין קכ\"ז ע\"ב).","cat": "sage"},{"i": 3861,"n": "רבי שמעון המחוזי","l": "ש","b": "אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו: \"ורבי יוחנן משום רבי שמעון המחוזי משום רבי יוחנן המכותי\" (סוכה מ\"ה ע\"ב).","cat": "sage"},{"i": 3862,"n": "רבי שמעון הנשיא","l": "ש","b": "מובא בבבלי, והגמרא שואלת: \"נשיא היה או משמיה דנשיא אמר?\", ונשארת הגמרא בתיקו (גיטין ט\"ו ע\"א).","cat": "sage"},{"i": 3863,"n": "שמעון העמסוני","l": "ש","b": "מובא בבבלי: שמעון העמסוני ואמרי לה נחמיה העמסוני היה דורש כל אתים שבתורה כיון שהגיע לאת ה' אלקיך תירא פירש וכו' עד שבא ר\"ע וכו' (פסחים כ\"ב ע\"ב). אם כן נראה שהיה קודם רבי עקיבא, אך אין זו ראיה מוחלטת שכן מצינו: \"אמר רבי אלעזר בן עזריה וכו' עד שדרשה בן זומא וכו'\" (ברכות י\"ב ע\"ב) ובן זומא היה בן דורו של ראב\"ע. ומאידך, הגמרא מפקפקת אם שמעון העמסוני או נחמיה העמסוני היה, ומצינו שנחמיה העמסוני שימש את ר\"ע עשרים ושתים שנה, ואם כן אולי יתכן, ששניהם - גם נחמיה וגם שמעון העמסוני - היו תלמידים של ר\"ע (ירו', ברכות פ\"ט ה\"ה).","cat": "sage"},{"i": 3864,"n": "שמעון הפקולי","l": "ש","b": "תנא בדור השני - השלישי. סידר י\"ח ברכות (תפלת שמונה עשרה) לפני רבן גמליאל (ברכות כ\"ח ע\"ב), ואת שמו פיקולי פרש\"י: \"יש אומרים שמשתכר בצמר גפן שנקרא פקולא\" (מגילה י\"ז ע\"ב ד\"ה: הפקולי).","cat": "sage"},{"i": 3865,"n": "שמעון הצדיק","l": "ש","b": "אחרון החכמים מאנשי כנסת הגדולה: \"שמעון הצדיק היה משירי אנשי כנסת הגדולה\" (אבות פ\"א מ\"ב), וממנו ומתלמידו אנטיגנוס ואילך החלה תקופת ה\"זוגות\". בימיו בא אלכסנדר מוקדון לארץ ישראל, וכיון שראה לשמעון הצדיק ירד ממרכבתו והשתחווה לפניו ואמר: \"דמות דיוקנו של זה מנצחת לפני בבית מלחמתי\" (יומא ס\"ט ע\"א). מתקופתו החלה ספירת מנין השטרות (וזה מנין השטרות שהחל בשנת ג' תמ\"ח /213 לפה\"ס). שימש ארבעים שנה בכהונה גדולה (יומא ט' ע\"א). ובגמרא מסופר: \"אותה שנה שמת שמעון הצדיק, אמר להן 'שנה זו הוא מת'. אמרו לו: 'מניין אתה יודע? ' אמר להן: 'כל יום הכיפורים נזדמן לי זקן אחד לבוש לבנים ונתעטף לבנים ונכנס עמי ויצא עמי (מנחות ק\"ט ע\"ב). שנה זו נזדמן לי זקן אחד לבוש שחורים ונתעטף שחורים ונכנס עמי ולא יצא עמי'. לאחר הרגל חלה שבעת ימים ומת\" (מנחות ק\"ט ע\"ב). ופירשו תוספות שכתב הירושלמי דשמא שכינה היתה (שם). היו לו שני בנים, שמעי וחוניו, ואמר להם: \"חוניו בני ישמש תחתי\", ונתקנא שמעי באחיו והטעה את חוניו והלבישו לבוש שאינו מתאים בזמן העבודה ורצו אחיו הכהנים להורגו וברח חוניו לאלכסנדריה של מצרים ובנה שם מזבח (שם).","cat": "sage"},{"i": 3866,"n": "ר' שמעון השילוני","l": "ש","b": "תנא שאין לקבוע זמנו. מובא בבבלי (פסחים קי\"ח ע\"א), ועל דרשתו חלק רבי נתן (שם).","cat": "sage"},{"i": 3867,"n": "שמעון השקמוני","l": "ש","b": "תנא בדור הרביעי. תלמידו של רבי עקיבא וחברו של רבי חדקא: \"א\"ר חדקא שמעון השקמוני היה לי חבר מתלמידי רבי עקיבא\" (ב\"ב קי\"ט ע\"א).","cat": "sage"},{"i": 3868,"n": "שמעון התימני","l": "ש","b": "תנא בדור השלישי. מכונה תימני, כי מתמנה היה (תענית י\"ט ע\"א רש\"י). היה מן הארבעה ביבנה שידעו שבעים לשון (סנהדרין י\"ז ע\"ב). תלמידם של רבי אליעזר ור' יהושע ור' עקיבא: \"רבי אליעזר רבי יהושע רבי עקיבא ושמעון התימני דן לפניהם בקרקע\" ופרש\"י: \"תלמיד היה ולא נסמך שלא בא לכלל זקנה\" (שם). חלק על רבי עקיבא ורבי עקיבא ענה לו (ב\"ק צ' ע\"ב). מסופר מעשה בשמעון התימני שלא בא לבית המדרש, מצאו רבי יהודה בן בבא ושאלו למה לא בא לבית המדרש (ביצה כ\"א ע\"א).","cat": "sage"},{"i": 3869,"n": "ר' שמעון חסידא","l": "ש","b": "אמורא בדור השני. רב חנא בר ביזא, שהיה מבבל, היה תלמידו ומסר ממנו אגדות (יומא ע\"ז ע\"א). גם ר' יעקב בר אידי מארץ ישראל היה מתלמידיו: \"כי אתא רבין אמר רבי יעקב בר אידי א\"ר שמעון חסדא\" (סוף ר\"ה). גם רבי יונה מארץ ישראל מסר משמו, ולכן אין לקבוע את מקומו של ר' שמעון חסידא.","cat": "sage"},{"i": 3870,"n": "רבי שמעון יאסיניא","l": "ש","b": "מובא בבבלי (בכורות מ\"ז ע\"ב), והוא רבי שמעון בן יוסינא.","cat": "sage"},{"i": 3871,"n": "ר' שמעון לודייא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. מובא בש\"ר (פ\"ג - ה'), שאמר בשם ר' סימון.","cat": "sage"},{"i": 3872,"n": "שמעון נזירא","l": "ש","b": "מובא בבלי (יבמות צ\"ז ע\"א). ע\"ע בר טירא.","cat": "sage"},{"i": 3873,"n": "שמעון סיכנא איש עוצה","l": "ש","b": "חי בארץ ישראל בדור הראשון לתנאים. אמר לרבן יוחנן בן זכאי: אני גדול כמוך, שהיה חופר בורות ושיחין בירושלים וקרא עליו הפסוק \"וקרוב לשמוע מתת הכסילים\" (קה\"ר ספ\"ד). מהענין שלפנינו אין להכריע אם היה חכם, ו\"יוחסין\" ו\"סה\"ד\" הביאוהו בין החכמים.","cat": "sage"},{"i": 3874,"n": "ר' שמעון ספרא דטרכנס","l": "ש","b": "סופר בעיר טרכנס שבארץ ישראל חי בדור השני - השלישי לאמוראים וקרא בתורה ורצו בני עירו שיפסיק בקריאתו באמצע פסוק, כדי שיקראו עם בניהן, ושאל את רבי חנינא וא\"ל: \"אפילו יחתכו ראשך לא תשמע להם\" והעבירוהו ממשרתו, ואמר רבי זירא: \"אילו היה בימי הייתי ממנה אותו לא לסופר אלא לחכם\" (ירו', מגילה פ\"ד ה\"ה). אין להכריע שהיה חכם, שמא סופר היה, ו\"יוחסין\" ו\"סה\"ד\" הביאוהו בין שמות החכמים.","cat": "sage"},{"i": 3875,"n": "שמעון קמטריא","l": "ש","b": "אמורא ארץ ישראלי בדור הרביעי. שאל את רבי חייא בר אבא (ירו', ברכות פ\"ט ה\"ב). עלה כל שנה לירושלים עם חמורים טעונים משא (שם). ופירש \"שדה יהושע\", שהיה עושה ארגזים.","cat": "sage"},{"i": 3876,"n": "רבי שמעון שזורי","l": "ש","b": "תנא בדור הרביעי. תלמידו של רבי טרפון (מנחות ל\"א ע\"א). מובא במחלוקת עם תלמידי רבי עקיבא, רבי מאיר רבי יהודה ורבי יוסי (מנחות ל' ע\"ב) ואמרו: \"כל מקום ששנה רבי שמעון שזורי הלכה כמותו\" (שם). \"יוחסין\" כתבו: \"נקרא שזורי על מלאכתו כ\"כ הרמב\"ם ולי נראה מקום יש בגליל העליון נקרא שזור\", וכן כתב \"כפתור ופרח\" שהוא שם עיר.","cat": "sage"},{"i": 3877,"n": "שמעיה (2)","l": "ש","b": "מחכמי ה\"זוגות\" לפני התנאים. הוא וחברו אבטליון היו \"זוג\" רביעי. שימש כנשיא וחברו אבטליון היה אב\"ד (חגיגה ט\"ז ע\"א). שניהם קיבלו מיהודה בן טבאי ושמעון בן שטח (אבות פ\"א מ\"י), ושניהם היו גרים (גיטין נ\"ז ע\"ב): \"מבני בניו של סנחריב למדו תורה ברבים מאן אינון שמעיה ואבטליון\". יהודה בן דורתאי אמר עליהם (פסחים ע' ע\"ב): \"חכמים גדולים ודרשנין גדולים\". הלל, שהיה תלמידם המובהק (יומא ל\"ה ע\"ב), אמר עליהם: \"שני גדולי הדור שמעיה ואבטליון\" (פסחים ס\"ו ע\"א). ומסופר: \"מעשה בכהן גדול אחד שיצא מבית המקדש והלכו כל העם ללוותו, כיון שראו את שמעיה ואבטליון הניחו את הכהן גדול והלכו אחריהם\" (יומא ע\"א ע\"ב). מהלל ושמאי שהיו תלמידיהם, החלה תקופת התנאים.","cat": "sage"},{"i": 3878,"n": "שמעיה איש כפר עותני","l": "ש","b": "מובא בתוספתא \"אמר רבי אליעזר מעשה בשמעיה איש כפר עותני וכו' ושאל לרבי יוחנן בן זכאי\" (פרה פ\"י - צוקרמנדל). וגיר' שלנו: רבי אליעזר בן שמעיה איש כפר אותני.","cat": "sage"},{"i": 3879,"n": "רב שמעיה א'","l": "ש","b": "אמורא בבלי בדור השלישי - הרביעי. חברו של רבי אבא ושקיל וטרי עמו (סוף נדה). מצינו, שאביי ורבא דנים בקטע ברייתא ששנה רב שמעיה (סנהדרין מ\"ז ע\"א). ע\"ע רב שמעיה ב'.","cat": "sage"},{"i": 3880,"n": "רב שמעיה בקלנב","l": "ש","b": "מובא בבבלי רב שמעיה בקלנבו (יומא כ\"א ע\"א). ושוב מובא (זבחים צ\"ו ע\"א) אישתמיטתיה הא דתני שמעיה בקלנבו (נ\"א רב שמעיה), ופרש\"י: \"שם מקום שנקרא על שם עכו\"ם\".","cat": "sage"},{"i": 3881,"n": "רב שמעיה בר זירא","l": "ש","b": "מובא בבבלי (כתובות פ\"א ע\"א) והוא שמעיה בר זעירא.","cat": "sage"},{"i": 3882,"n": "רב שמעיה בר זעירא","l": "ש","b": "אמורא בבלי בדור החמישי. תלמידם של אביי ורבא, שמצינו: \"שלח ליה רבא לאביי ביד רב שמעיה בר זעירא\" (עירובין צ\"ג ע\"א). ומצינו, שאביי תירץ לו את קושייתו (חולין קט\"ז ע\"א).","cat": "sage"},{"i": 3883,"n": "רב שמעיה ב'","l": "ש","b": "אמורא בבלי בדור החמישי. מובא בבבלי (עירובין מ' ע\"א). \"סה\"ד\" חילקם לשניים - ר' שמעיה א' ור' שמעיה ב', ואולי הדין עמו אף שאין הכרח בכך, שכן יתכן שהאריך ימים עד רבינא, וגם לשון הגמרא אינה מוכיחה זאת בוודאות גמורה, וזה לשון הגמרא: \"א\"ל רבא בר תחליפא לרבינא וכו' ומתקיף לה רב שמעיה וכו' אזלו שיילוה לרבא אמר להו וכו'\".","cat": "sage"},{"i": 3884,"n": "ר' שמעיה חסידא","l": "ש","b": "מובא ב\"זוהר\" (פ' בלק קפ\"ו).","cat": "sage"},{"i": 3885,"n": "רב שעורים","l": "ש","b": "אמורא בבלי בדור הרביעי. אחיו של רבא. נכח בפטירת רבא, ורבא ביקשו שיאמר למלאך המות שלא יצערו. רב שעורים ביקש את רבא אחיו שיבוא לראותו אחרי פטירתו ורבא בא וסיפר לו שצער מיתתו היה אך כהקזת דם (מו\"ק כ\"ח ע\"א). מובא גם במקום אחר, ושם הגיר' רב סעורם (ב\"מ ע\"ג ע\"ב).","cat": "sage"},{"i": 3886,"n": "רבי שפטיה","l": "ש","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן. מובא בבבלי, שאמר ה' מאמרים מרבי יוחנן רבו (מגילה ל\"ב ע\"א).","cat": "sage"},{"i": 3887,"n": "שפיפון בן ליש","l": "ש","b": "מובא ב\"סה\"ד\", שהיה צדיק וחברו של בן סבר; מלאך המות לא יכול לו, שכן השביעו בשם המפורש, ויצאה בת קול ואמרה: \"מה אעשה לצדיקים שאנו גוזרים והם מבטלים\", והוסיפו לו שבעים שנה לחייו. מעשה זה אינו נמצא בש\"ס או במדרשים, ומקורו של \"סה\"ד\" הוא \"ספר קטן מעשיות\".","cat": "sage"},{"i": 3888,"n": "רב שפיר","l": "ש","b": "אמורא בבלי בדור הראשון. מובא בבבלי \"רב איקלע לבי רב שפיר\" (מו\"ק י\"א ע\"א). ו\"סדר תנאים ואמוראים\" גרס: בר שפיר.","cat": "sage"},{"i": 3889,"n": "שקוד","l": "ש","b": "כינוי לשמואל על שם ששוקד על דבריו לאומרם כהלכה (כתובות מ\"ג ע\"ב), והירושלמי גרס: שוקד (כתובות פ\"ד ה\"ב).","cat": "sage"},{"i": 3890,"n": "רב שרביה","l": "ש","b": "אמורא בבלי בדור החמישי. תלמידו המובהק של רבא, והוא ורבינא אמרו משמו של רבא (שבת קט\"ו ע\"ב). הקשה לרבא מברייתא, ורבא ענה לו: \"אי תניא תניא\" (יבמות קי\"ב ע\"א). היה גם תלמידו של אביי, ואביי תירץ לו את קושייתו (בכורות י\"ט ע\"א).","cat": "sage"},{"i": 3891,"n": "ר' ששא בנו של ר' אבא","l": "ש","b": "מובא בש\"ר (רפכ\"ד).","cat": "sage"},{"i": 3892,"n": "רב ששעה","l": "ש","b": "מאחרוני האמוראים בארץ ישראל בדור הששי. בנו של ר' שמואל בר אבדימי. מובא בירושלמי, שר' שמואל בר אבדימי היה צריך למול את בנו של רב ששעה בשבת ושכח האיזמל והורה ר' מנא לר' שמואל בר אבדימי לדחות הברית ליום א' (שבת פי\"ט ה\"א).","cat": "sage"},{"i": 3893,"n": "רב ששת","l": "ש","b": "אמורא בבלי בדור השני - השלישי. תלמידו המובהק של רב הונא: \"דרב ששת איעקר מפירקיה דרב הונא\" (יבמות ס\"ב ע\"ב), ופרש\"י: \"שהיה מאריך בדרשותיו וצריכים למי רגלים ומעמידים עצמם ונעקרים\". היה גם תלמידו של רב ירמיה בר אבא (נזיר ס\"ח ע\"א). היה חוזר על לימודו כל שלושים יום (פסחים ס\"ח ע\"ב). היה בקי גדול במשניות ומצינו שרב חסדא היה נרעד מבקיאותו בהיפגשו עימו (עירובין ס\"ז ע\"א), ופרש\"י שם: \"שהיו משניותיו סדורות לו וירא רב חסדא שלא יקשה לו ממשנה על משנה ויאמר לו לתרצן\". וכן אמר רב יצחק בר יהודה: \"רב ששת כי בעינא מילתא מיניה פשיט לי ממתניתא\" (זבחים צ\"ו ע\"ב). היה חריף, ורבא אמר: \"אדם קשה שהוא קשה כברזל ומנו רב ששת\" (מנחות צ\"ו ע\"ב), ופרש\"י: \"חכם ומחודד לחתוך הלכה כברזל\". נהג לומר: \"אמינא כי ניים ושכיב רב אמר להאי שמעתתא\" (יבמות כ\"ד ע\"ב). וכתב בשו\"ת \"חות יאיר\" סי' קנ\"ב, שלא לגנאי אמר כך רק שבח גדול וכו'. בין תלמידיו היו גם אביי (קידושין ט\"ז ע\"ב) ורבא (ברכות ל\"ד ע\"ב). גם רבותיהם של אביי ורבא רבה ורב יוסף, שמעו ממנו (עירובין ס\"ה ע\"ב). היה עיוור (ברכות נ\"ח ע\"א): \"רב ששת סגי נהור הוה\" ונראה שעיוורונו לא בא לו מלידה, שמצינו: \"שראה נחש בחלום והרגו\" (שם נ\"ז ע\"ב), (אילו היה עוור איך ידע צורת נחש?). היה לו גילוי שכינה (מגילה כ\"ט ע\"א). לא היו לו בנים אלא בנות (יבמות ס\"ב ע\"ב). ביום פטירתו פגש בו מלאך המות בשוק ורצה לקחת נשמתו, אמר לו רב ששת: \"בשוק כבהמה?\" (מו\"ק כ\"ה ע\"א).","cat": "sage"},{"i": 3894,"n": "רב ששת בריה דרב אידי","l": "ש","b": "מובא בבבלי (פסחים מ\"ט ע\"א), והוא רב שישא בריה דרב אידי. \"יוחסין\" חילקם לשניים וכתב לכל אחד ערך נפרד.","cat": "sage"},{"i": 3895,"n": "רב ששת בריה דרב יהושע","l": "ש","b": "מובא בבבלי (פסחים קט\"ו ע\"א), ואולי יש ט\"ס בשם.","cat": "sage"},{"i": 3896,"n": "רב ששת מקטרזיא","l": "ש","b": "אמורא בבלי בדור השביעי. תלמידו של רב אשי: \"רב ששת מקטרזיא איקלע לקמיה דרב אשי\" (מגילה כ\"א ע\"ב) ומלשון הש\"ס יש להוכיח שהיה תלמידי דרב אשי, שכן אילולא היה תלמידו, היה לשון הש\"ס \"איקלע\" בלי \"לקמיה\".","cat": "sage"},{"i": 3913,"n": "רבי תדאי","l": "ת","b": "אמורא ארץ ישראלי בדור השני. רבו של רבי אבא (שבת ל\"ח ע\"ב). רבי אמי אמר: \"רבי תדאי לגרמיה [לנפשו] הוא דעבד\" (שם).","cat": "sage"},{"i": 3914,"n": "תודוס איש רומי","l": "ת","b": "חי ברומי בזמנו של שמעון בן שטח, בדורם של ה\"זוג\" השלישי לפני תקופת התנאים. שמעון בן שטח שלח לו: \"אלמלא תודוס אתה גוזרני עליך נידוי\" (ברכות י\"ט ע\"א), ובמקום אחר מפקפקת הגמרא אם היה גברא רבה או גברא אלימא (פסחים נ\"ג ע\"ב), ומסקנת הגמרא שהיה גברא רבה או שהיה מפרנס תלמידי חכמים.","cat": "sage"},{"i": 3915,"n": "תודוס הרופא","l": "ת","b": "חי בדור השלישי לתנאים. מובא במשנה (בכורות כ\"ח ע\"ב) \"ומעשה בפרה וכו' ובא מעשה לפני חכמים ביבנה והתירוה שאמר תודוס הרופא אין פרה וכו'\". ומובא בירושלמי \"מעשה שהביאו קופה מליאה עצמות וכו' ונכנס תודרוס הרופא ונכנסו כל הרופאים עמו אמר תודרוס הרופא אין כאן שדרה ממת אחת ולא גולגולת ממת אחד אמרו הואיל ויש כאן מטהרין ויש כאן מטמאין נעמוד על המנין התחילו מר\"ע וכו'\" (ברכות פ\"א ה\"א). אין ראיה שתודוס זה היה חכם, גם לשון המשנה שאומרת שחכמים התירוה שאמר (כן גורס \"מסה\"ש\") תודוס וכו' (כלומר המשנה מסתמכת על דברי תודוס הרופא) וכן מירושלמי, אין ראיה לכך, ויתכן שרק ידע מקצועי הביאו ממנו ולא ציטטו דבריו כחכם.","cat": "sage"},{"i": 3916,"n": "תודרוס הרופא","l": "ת","b": "מובא בירושלמי (ברכות פ\"א ה\"א), והוא תודוס הרופא.","cat": "sage"},{"i": 3917,"n": "תוטאי","l": "ת","b": "תנא דברייתא. מובא בבבלי: \"אביי אמר הכי אמר רב ששת הא מני תוטאי הוא דתניא תוטאי אומר וכו'\" (קידושין ט\"ז ע\"ב).","cat": "sage"},{"i": 3918,"n": "רב תחליפא","l": "ת","b": "אמורא בבלי בדור השלישי. תלמידו של רב הונא, ומספר: \"אנא חזיתיה לרב הונא וכו'\" (מו\"ק כ\"ה ע\"א).","cat": "sage"},{"i": 3919,"n": "רבי תחליפא","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי. אביו של רב נסא. ר' נסא מספר, שבילדותו אכל עם ר' תחליפא אביו ועם ר' אינייני בר סיסי דודו, ולא צירפוהו לזימון עד שגדל (ירו', ברכות פ\"ז ה\"ב).","cat": "sage"},{"i": 3920,"n": "רב תחליפא אבוה דרב הונא בר תחליפא","l": "ת","b": "אמורא בבלי בדור הרביעי - החמישי. מסר משמו של רבא (יומא ו' ע\"ב). גם בנו רב הונא בר תחליפא היה תלמידו של רבא (יבמות ח' ע\"ב). נראה, שהבן היה גדול מאביו ועל כן נקרא האב על שם בנו.","cat": "sage"},{"i": 3921,"n": "רב תחליפא אחוה דרבנאי חוזאה","l": "ת","b": "אמורא ארץ ישראלי בדור הראשון - השני. מתיחס לאחיו כמובא בבבלי: \"תני רב תחליפא אחוה דרבנאי חוזאה כל מזונותיו של אדם קצובים לו מראש השנה ועד יום הכפורים חוץ מהוצאת שבתות והוצאת יו\"ט והוצאת בניו לתלמוד תורה\" (ביצה ט\"ו ע\"ב).","cat": "sage"},{"i": 3922,"n": "רב תחליפא בר אבדימי","l": "ת","b": "אמורא בבלי בדור השני. תלמידו של שמואל (ע\"ז ו' ע\"א), ומובא: דרב תחליפא בר אבדימי עבד עובדא כותיה דשמואל ואמר רב תחלת הוראה דהאי צורבא מרבנן לקלקולא (ביצה ט\"ז ע\"ב), ופרש\"י: \"דרב פליג עליה ואמר הלכה כתנא קמא\". אמר לרב חסדא \"הכי אמר שמואל\" (בכורות ל\"ז ע\"ב).","cat": "sage"},{"i": 3923,"n": "רב תחליפא בר אבודימי","l": "ת","b": "מובא בבבלי, והוא רב תחליפא בר אבדימי (בכורות ל\"ז ע\"ב).","cat": "sage"},{"i": 3924,"n": "רב תחליפא בר אבינא","l": "ת","b": "אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (חולין ס' ע\"ב).","cat": "sage"},{"i": 3925,"n": "רב תחליפא בר אימי","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר וחברו של הונא בר חיננא, ושניהם ישבו לפני רבי אלעזר (ירו', מעשרות פ\"ד ה\"ד).","cat": "sage"},{"i": 3926,"n": "רב תחליפא בר אמיבי","l": "ת","b": "מובא בבבלי (פסחים ק\"ז ע\"א), ונראה שהוא רב תחליפא בר אבדימי.","cat": "sage"},{"i": 3927,"n": "רב תחליפא בר בר חנא","l": "ת","b": "מובא באס\"ר (פ\"א - א').","cat": "sage"},{"i": 3928,"n": "רב תחליפא בר גזא","l": "ת","b": "מובא בבבלי (זבחים ל\"ט ע\"א), והוא רב תחליפא בר גיזא.","cat": "sage"},{"i": 3929,"n": "רב תחליפא בר גיזא","l": "ת","b": "אמורא בבלי בדור הששי. מובא בבבלי, שא\"ל לרבינא: דילמא וכו' (ע\"ז ס\"ט ע\"א).","cat": "sage"},{"i": 3930,"n": "ר' תחליפא בר יעקב","l": "ת","b": "אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי יהודה בר סימון (מד' תהלים הישן פקי\"ד).","cat": "sage"},{"i": 3931,"n": "רב תחליפא בר מערבא","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. היה מארץ ישראל, ולכן קראו לו בר מערבא (רש\"י ב\"מ ז' ע\"א). תלמידו של רבי אבהו ושאל ממנו (גיטין נ\"ב ע\"ב). שמע מדברי רבי יוחנן והלך ומסרם לרבי אבהו (ברכות נ\"ה ע\"א). נראה, ששנה ברייתא בישיבת רבי יוחנן (מנחות י\"ד ע\"ב). ביקר בבבל (כתובות ח' ע\"א) ובחוזרו משם מסר מדברי רב חסדא לרבי אבהו רבו (עירובין נ\"ד ע\"ב).","cat": "sage"},{"i": 3932,"n": "ר' תחליפא בר קרויה","l": "ת","b": "מובא בפס' רבתי (פכ\"ו). הגיר' במדרש תהלים: ר' אילפא בר קרויא (פקל\"ז - ג').","cat": "sage"},{"i": 3933,"n": "רב תחליפא בר רב חסדא","l": "ת","b": "אמורא בבלי בדור הרביעי. בנו ותלמידו של רב חסדא (גיטין ל\"א ע\"ב). רבא היה גיסו, שכן התחתן עם אחותו.","cat": "sage"},{"i": 3934,"n": "רב תחליפא בר שאול","l": "ת","b": "מובא בבבלי (מו\"ק י' ע\"א), וגיר' \"דק\"ס\": ר' חלפתא בר שאול.","cat": "sage"},{"i": 3935,"n": "ר' תחליפא חמיו דר' אבהו","l": "ת","b": "אמורא ארץ ישראלי בדור השני. חמיו של רבי אבהו. רבי אבהו אמר משמו (קה\"ר ספ\"י).","cat": "sage"},{"i": 3936,"n": "ר' תחליפא חמיו דר' אחא","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. ושניהם ר' אחא וחמו אמרו משמו של רבי שמואל בר נחמני (ירו', ברכות פ\"א ה\"א).","cat": "sage"},{"i": 3937,"n": "רב תחליפא ממערבא","l": "ת","b": "מובא בבבלי (מנחות י\"ד ע\"ב), והוא רב תחליפא בר מערבא.","cat": "sage"},{"i": 3938,"n": "ר' תחליפא קיסריא","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי (תענית רפ\"ב). חברו של ר\"ז ושקיל וטרי עמו (ירו', סוטה ספ\"ה).","cat": "sage"},{"i": 3939,"n": "ר' תחנא","l": "ת","b": "\"סה\"ד\" מביאו שמובא בפדר\"א.","cat": "sage"},{"i": 3940,"n": "ר' תימא בר פפייס","l": "ת","b": "אמורא ארץ ישראלי בדור החמישי. מובא פעם בש\"ס הירושלמי, ומסר בשם רב אושעיא (ירו', סנהדרין פ\"ד ה\"ז). אם נניח שיש ט\"ס, וצ\"ל \"רבי אושעיא\" במקום \"רב אושעיא\" (רב אושעיא היה אחיו של רבה), הרי שלא היה אמורא בדור החמישי אלא בדור השני, שכן רבי אושעיא היה רבו של ר' יוחנן וחי בדור הראשון, וא\"כ תלמידו היה בדור השני. דבר זה אין להכריע, ואני כתבתיו בדור החמישי, שכך נראה לי.","cat": "sage"},{"i": 3941,"n": "תנא דבי אליהו","l": "ת","b": "מובא בבבלי (פסחים צ\"ד ע\"א). \"סה\"ד\" כתב: \"אינו אליהו הנביא, אלא הוא תנא ואין לקבוע את זמנו\".","cat": "sage"},{"i": 3942,"n": "רבי תנחום","l": "ת","b": "אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ברכות כ\"ח ע\"ב) מסר גם בשם רבי יוחנן (שבת ל\"ט ע\"ב).","cat": "sage"},{"i": 3943,"n": "ר' תנחום אדרייא","l": "ת","b": "מובא בירושלמי (תענית פ\"א ה\"א).","cat": "sage"},{"i": 3944,"n": "ר' תנחום איסבולסטיקא","l": "ת","b": "מובא בירושלמי (ברכות פ\"ד ה\"ב).","cat": "sage"},{"i": 3945,"n": "ר' תנחום בוצרייא","l": "ת","b": "אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (כלאים פ\"ג ה\"א). מסר בשם רבי ירמיה (ויק\"ר פט\"ו - ו'). רבי אלעזר בר' יוסי מסר משמו (שם).","cat": "sage"},{"i": 3946,"n": "ר' תנחום בר אחא","l": "ת","b": "מובא בשהש\"ר (פ\"א פ' כי טובים).","cat": "sage"},{"i": 3947,"n": "רבי תנחום בר חייא","l": "ת","b": "אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם רבי יהושע בן לוי (ירו', שקלים רפ\"ג) ובשם רבי יוחנן (ירו', שבת פ\"א ה\"ד). רבי יונה מסר משמו (ירו', ברכות פ\"ה ה\"א).","cat": "sage"},{"i": 3948,"n": "ר' תנחום בר חכינאי","l": "ת","b": "מובא בבבלי (שבועות ל\"ו ע\"א).","cat": "sage"},{"i": 3949,"n": "ר' תנחום בר חמא","l": "ת","b": "מובא בפסדר\"כ (קע\"ג).","cat": "sage"},{"i": 3950,"n": "רבי תנחום בר חנילאי","l": "ת","b": "אמורא ארץ ישראלי בדור השני. היה רגיל ללמוד אגדה לפני רבי יהושע בן לוי (ב\"ק נ\"ה ע\"א). כשר' חנינא בר עגיל בא לשאול ממנו א\"ל: \"מריב\"ל לא שמעתי אך כך אמר לי שמואל בר נחום אחי אמי\" (שם). בין האומרים בשמו רבי לוי (ב\"ר פ\"ד - ו'). יש ממנו דרושי אגדות רבים בש\"ס (ב\"מ פ\"ו ע\"ב ועוד).","cat": "sage"},{"i": 3951,"n": "ר' תנחום בר חנינא","l": "ת","b": "מובא בירושלמי (ברכות פ\"ד ה\"ד).","cat": "sage"},{"i": 3952,"n": "ר' תנחום בר יודן","l": "ת","b": "מובא בירושלמי (ברכות פ\"ו ה\"א).","cat": "sage"},{"i": 3953,"n": "ר' תנחום בר יוסי","l": "ת","b": "מובא בתנחומא (פ' ויצא - כ\"ב).","cat": "sage"},{"i": 3954,"n": "ר' תנחום בר ירמיה","l": "ת","b": "מאחרוני האמוראים בארץ ישראל בדור הששי. מתלמידיו של רבי מנא. היה בעיר חפר והורה שם ואמר לו: לימדתנו שאסור להורות הלכה בפני רבו עד שיהא במרחק י\"ב מיל ור' מנא יושב בציפורין שהיא קרובה מי\"ב מיל, וענה להם שלא ידע (ירו', גיטין פ\"א ה\"ב).","cat": "sage"},{"i": 3955,"n": "ר' תנחום בר מרי","l": "ת","b": "אמורא ארץ ישראלי בדור החמישי - הששי. מסר בשם רבי יוסי (חברו דרבי יונה), כדמצינו בירושלמי (כתובות פ\"ח ה\"י).","cat": "sage"},{"i": 3956,"n": "ר' תנחום בר מריון","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו', מעשרות פ\"א ה\"ב). סיפר מענייני רומי (ב\"ר פכ\"ב - ו').","cat": "sage"},{"i": 3957,"n": "ר' תנחום בר עילאי","l": "ת","b": "אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם רבי יוסי בר חנינא (ירו', חגיגה פ\"א ה\"ב). נפטר בחנוכה (ירו', סוף מו\"ק).","cat": "sage"},{"i": 3958,"n": "ר' תנחום בר פפא","l": "ת","b": "חכם, כנראה אמורא בדור הרביעי - החמישי. חי באלכסנדריה ושלח לשאול לרבי יוסי (חברו דר' יונה). ר' יוסי צוה לר' מנא תלמידו לחתום על התשובה (ירו', קדושין פ\"ג הי\"ב).","cat": "sage"},{"i": 3959,"n": "ר' תנחום ברבי חתניה דר' שמלאי","l": "ת","b": "","cat": "sage"},{"i": 3960,"n": "רבי תנחום בריה דר' חייא","l": "ת","b": "(איש כפר עכו) - אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר' יעקב בר אחא (מו\"ק ט\"ז ע\"ב). מושבו היה בטבריה, ופעם הביאו שבויות יהודיות לטבריה ואחת מהן היתה מעוברת לנוכרי ובאו לשאול הוא וחברו ר' אחא שר הבירא מרבי אמי (יבמות מ\"ה ע\"א). יש ממנו כמה מאמרי אגדות. (תענית ז' ע\"ב) כשנפטר נשברו כל האנדרטאות בעירו (מו\"ק כ\"ה ע\"ב - \"דק\"ס\").","cat": "sage"},{"i": 3961,"n": "ר' תנחום דכפר גון","l": "ת","b": "אמורא ארץ ישראלי, מאחרוני האמוראים בדור הששי. מובא בירושלמי, שאמר בשם רבי אלעזר ברבי יוסי (ב\"ב פ\"ה ה\"א), אביו רבי יוסי היה מראשי הדור הרביעי לאמוראי א\"י, חברו של רבי יונה.","cat": "sage"},{"i": 3962,"n": "ר' תנחום דמן יפו","l": "ת","b": "אמורא ארץ ישראלי שאין לקבוע את זמנו המדוייק. יתכן שחי בדור הרביעי - החמישי. אמר בשם ר' נחוניא (פדר\"כ ר\"פ בחצי הלילה), וכן בשם ר' מנא דקיסרין (פס' רבתי שם).","cat": "sage"},{"i": 3963,"n": "ר' תנחום דמן נוי","l": "ת","b": "אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. חי אחרי הדור השלישי. היה דרשן ודיין בעירו (שבת ל' ע\"א). דיבר בענווה (שם ע\"ב רש\"י).","cat": "sage"},{"i": 3964,"n": "ר' תנחום דמן פרוד","l": "ת","b": "אמורא. נראה, שהיה בדור הראשון. רבי יוחנן נזדמן לעיר פרוד: \"אמר: 'כלום יש משנת בר קפרא', תנא ליה ר' תנחום דמן פרוד\" (ע\"ז ל\"א ע\"א). אין לקבוע שרבי יוחנן קיבל ממנו. ונראה שר' תנחום דמן פרוד היה מתלמידי בר קפרא.","cat": "sage"},{"i": 3965,"n": "ר' תנחום חתניה דר\"א בר אבינא","l": "ת","b": "מובא (ריש פסדרו\"כ), ונראה, שהוא ר' מנחם חתניה דר\"א בר אבונה.","cat": "sage"},{"i": 3966,"n": "רבי תנחומא","l": "ת","b": "אמורא ארץ ישראלי בדור הששי. מחבר מדרש תנחומא. מגדולי בעלי האגדה ובעלי הדרוש. אחרון הדרשנים הארץ ישראלים הידוע לנו בשמו, והוא החותם של תקופת המדרש העתיקה, ששורשיה נעוצים בתקופת הסופרים ואנשי כנסת הגדולה. ידועות כמה מהדורות של מדרש תנחומא מלבד שתי המהדורות השלמות שבידינו והן \"מדרש ילמדנו\" (ע\"ש תחילת כל דרשה \"ילמדנו רבנו\"), וכן הפסיקתות המכילות דרשות השאובות הרבה ממדרש תנחומא. ר' תנחומא ידוע גם בתור ר' תנחומא בר אבא ורבותיו היו ר' הונא ב', ומסר הרבה בשמו (ירו', פאה פ\"א ה\"א; חלה פ\"א ה\"ג, ועוד) ורבי פנחס, והקשה לפניו (ירו', שקלים פ\"ו ה\"א). מסר גם משם חכמים רבים אחרים. מקומו היה בעיר אנטוכיא (ב\"ר פי\"ט - ד'). מובא גם בהלכה בירושלמי (חלה פ\"א ה\"ג) ובבבלי (חולין נ\"ה ע\"ב).","cat": "sage"},{"i": 3967,"n": "ר' תנחומא אדרעיה","l": "ת","b": "מובא בירושלמי (ברכות פ\"ד ה\"ב), והוא ר' תנחום אדרייא.","cat": "sage"},{"i": 3968,"n": "ר' תנחומא בי ר' יונה מבצוצרא","l": "ת","b": "ע\"ע ר' תנחומא בי ר' יונה ממצוצרא.","cat": "sage"},{"i": 3969,"n": "ר' תנחומא בי ר' יונה ממצוצרא","l": "ת","b": "מובא בפסיקתא רבתי (פ' תשא - ח').","cat": "sage"},{"i": 3970,"n": "ר' תנחומא בי ר' מנחם בר יעקב","l": "ת","b": "מובא בפס' רבתי (פ' תשא - ט'), שאמר בשם אביו.","cat": "sage"},{"i": 3971,"n": "ר' תפדאי","l": "ת","b": "אמורא ארץ ישראלי בדור החמישי. אמר בשם רבי אחא (ב\"ר פ\"ח - י\"א). \"סה\"ד\" גורס: ר' תפריי.","cat": "sage"},{"i": 3972,"n": "ר' תפדיי","l": "ת","b": "מובא בב\"ר (פ\"ח - י\"א), ואולי הוא ר' תפדאי.","cat": "sage"},{"i": 4431,"n": "אבגתא","l": "א","b": "","cat": "biblical"},{"i": 3987,"n": "אביאל","l": "א","b": "","cat": "biblical"},{"i": 4448,"n": "אביאסף בן קרח","l": "א","b": "","cat": "biblical"},{"i": 3988,"n": "אביגיל","l": "א","b": "","cat": "biblical"},{"i": 4380,"n": "אבידע","l": "א","b": "","cat": "biblical"},{"i": 3989,"n": "אביה","l": "א","b": "","cat": "biblical"},{"i": 3990,"n": "אביה","l": "א","b": "","cat": "biblical"},{"i": 4445,"n": "אביהוא","l": "א","b": "","cat": "biblical"},{"i": 4397,"n": "אביטל","l": "א","b": "","cat": "biblical"},{"i": 4330,"n": "אבימאל","l": "א","b": "","cat": "biblical"},{"i": 4002,"n": "אבימלך","l": "א","b": "","cat": "biblical"},{"i": 4009,"n": "אבישג","l": "א","b": "","cat": "biblical"},{"i": 4010,"n": "אבישי","l": "א","b": "","cat": "biblical"},{"i": 4011,"n": "אביתר","l": "א","b": "","cat": "biblical"},{"i": 4012,"n": "אבנר","l": "א","b": "","cat": "biblical"},{"i": 4013,"n": "אבצן","l": "א","b": "","cat": "biblical"},{"i": 4014,"n": "אברהם","l": "א","b": "אברהם הוא אבי העם היהודי ובעלה של שרה. הוא נשלח על ידי האל ממולדתו לארץ כנען עם הבטחה שיהפוך לגוי גדול. בכנען הוא גדל ברכוש ובקניין. בנו הצעיר יצחק היה יורשו וממשיך דרכו.","cat": "biblical"},{"i": 4015,"n": "אבשלום","l": "א","b": "","cat": "biblical"},{"i": 4016,"n": "אגג","l": "א","b": "","cat": "biblical"},{"i": 4017,"n": "אגור","l": "א","b": "","cat": "biblical"},{"i": 4325,"n": "אדבאל","l": "א","b": "","cat": "biblical"},{"i": 4018,"n": "אדום","l": "א","b": "אֱדום, שמשמעותו הצבע האָדום, הוא שמה של הממלכה שהקים אחיו של יעקב, עֵשָׂו, שהתורה מתארת כמי שנולד \"אדמוני כולו\". ממלכת אדום הייתה אחת מאויביו של עם ישראל ומאוחר יותר זוהתה עם הרומאים ועם המערב בכלל. ממלכת אדום שכנה בירדן של ימינו.","cat": "biblical"},{"i": 4048,"n": "אדוניה","l": "א","b": "","cat": "biblical"},{"i": 4066,"n": "אדם הראשון","l": "א","b": "אדם נוצר ביום השישי לבריאה, הראשון בין בני מינו. הוא ובת זוגו חוה גורשו מגן עדן לאחר אכילת הפרי האסור מעץ הדעת. אדם הראשון הוא אבי האנושות.","cat": "biblical"},{"i": 4433,"n": "אדני צדק","l": "א","b": "","cat": "biblical"},{"i": 4067,"n": "אהוד","l": "א","b": "","cat": "biblical"},{"i": 4068,"n": "אהליאב","l": "א","b": "","cat": "biblical"},{"i": 4069,"n": "אהרון","l": "א","b": "אהרן הוא אחיהם של משה ומרים. יחד איתם הנהיג את בני ישראל ביציאת מצרים ובמסעם במדבר. הוא נתמנה לכוהן הגדול הראשון והיה לאבי שושלת הכהונה.","cat": "biblical"},{"i": 4410,"n": "אוזל","l": "א","b": "","cat": "biblical"},{"i": 4070,"n": "אויל מרודך","l": "א","b": "","cat": "biblical"},{"i": 4430,"n": "אומר","l": "א","b": "","cat": "biblical"},{"i": 4100,"n": "און בן פלת","l": "א","b": "","cat": "biblical"},{"i": 4119,"n": "אוריה","l": "א","b": "","cat": "biblical"},{"i": 4386,"n": "אוריהו בן שמעיהו","l": "א","b": "","cat": "biblical"},{"i": 4118,"n": "אוריה החתי","l": "א","b": "","cat": "biblical"},{"i": 4485,"n": "אוריה הכהן","l": "א","b": "","cat": "biblical"},{"i": 4117,"n": "אוֹנָן","l": "א","b": "","cat": "biblical"},{"i": 4120,"n": "אחאב","l": "א","b": "אחאב, המלך השביעי בממלכת ישראל, היה מלך רשע. תחת השפעתה של איזבל אשתו התיר ועודד פריחה של עבודה זרה בתקופתו והסכים לנשל את נתיניו מאדמותיהם באופן שרירותי. נהרג במערכה צבאית נגד הארמים.","cat": "biblical"},{"i": 4121,"n": "אחז","l": "א","b": "","cat": "biblical"},{"i": 4122,"n": "אחזיה","l": "א","b": "","cat": "biblical"},{"i": 4123,"n": "אחיה השילוני","l": "א","b": "","cat": "biblical"},{"i": 4124,"n": "אחימלך","l": "א","b": "","cat": "biblical"},{"i": 4125,"n": "אחימן","l": "א","b": "","cat": "biblical"},{"i": 4126,"n": "אחימעץ","l": "א","b": "","cat": "biblical"},{"i": 4411,"n": "אחינועם היזרעאלית","l": "א","b": "","cat": "biblical"},{"i": 4336,"n": "אחיקם","l": "א","b": "","cat": "biblical"},{"i": 4127,"n": "אחיתופל","l": "א","b": "","cat": "biblical"},{"i": 4419,"n": "אחשוורוש","l": "א","b": "אחשוורוש הוא מלך פרס במגילת אסתר. הוא תמך בתוכניותיו של המן, הבכיר בשריו, להשמיד את כל היהודים במדינות מלכותו ולבזוז את רכושם, אך אסתר המלכה ובן דודהּ מרדכי סיכלו יחדיו את תוכניתו כאשר אסתר גילתה למלך את זהותה האמיתית, היהודית.","cat": "biblical"},{"i": 4025,"n": "איזבל","l": "א","b": "","cat": "biblical"},{"i": 4395,"n": "אילון הזבולוני","l": "א","b": "","cat": "biblical"},{"i": 4026,"n": "איש בושת","l": "א","b": "","cat": "biblical"},{"i": 4027,"n": "איתיאל","l": "א","b": "","cat": "biblical"},{"i": 4028,"n": "איתמר","l": "א","b": "","cat": "biblical"},{"i": 4349,"n": "איתן האזרחי","l": "א","b": "","cat": "biblical"},{"i": 4029,"n": "אכיש","l": "א","b": "","cat": "biblical"},{"i": 4061,"n": "אלדד ומידד","l": "א","b": "","cat": "biblical"},{"i": 4156,"n": "אליאב","l": "א","b": "","cat": "biblical"},{"i": 4157,"n": "אליהו","l": "א","b": "אליהו הוא נביא בספר מלכים בתקופת מלוכתו של אחאב. בתקופה זו פנו רבים לעבודת האל הכנעני בעל. אליהו השתמש בניסים ובמופתים להוכחת עליונותו של אלוהים. אליהו לא מת אלא נלקח לשמים במרכבה של סוסי אש.","cat": "biblical"},{"i": 4158,"n": "אליהוא","l": "א","b": "","cat": "biblical"},{"i": 4159,"n": "אלימלך","l": "א","b": "","cat": "biblical"},{"i": 4160,"n": "אליעזר","l": "א","b": "אליעזר הוא עבד אברהם, מנהל משק ביתו, ולפי המדרש, השליח שנשלח לחרן כדי למצוא אישה ליצחק. העבד התפלל שאישה תראה לו חסד והכנסת אורחים, ועוד בטרם סיים את תפילתו, הופיעה לפניו רבקה והוכיחה שהיא האישה הראויה ליצחק.","cat": "biblical"},{"i": 4161,"n": "אליפז","l": "א","b": "בנו של עשו","cat": "biblical"},{"i": 4483,"n": "אליפז","l": "א","b": "","cat": "biblical"},{"i": 4162,"n": "אליקים","l": "א","b": "","cat": "biblical"},{"i": 4163,"n": "אלישבע","l": "א","b": "","cat": "biblical"},{"i": 4461,"n": "אלישה","l": "א","b": "","cat": "biblical"},{"i": 4164,"n": "אלישמע בן פיכאי","l": "א","b": "","cat": "biblical"},{"i": 4165,"n": "אלישע","l": "א","b": "אלישע היה נביא בספר מלכים ויורשו של אליהו. נודע בתור עושה ניסים, למשל החיה נער מת וריפא חולים. הוא גם סייע ליואש מלך ישראל והציל את חייו.","cat": "biblical"},{"i": 4166,"n": "אלעזר","l": "א","b": "אלעזר, בנו של אהרן הכהן, ירש את מקומו ככוהן גדול. הוא המשיך בתפקיד זה אחרי הכניסה לארץ ישראל ויחד עם יהושע חילק את הארץ לשבטים ולמשפחות.","cat": "biblical"},{"i": 4212,"n": "אלקנה","l": "א","b": "","cat": "biblical"},{"i": 4213,"n": "אמון","l": "א","b": "","cat": "biblical"},{"i": 4214,"n": "אמנון","l": "א","b": "","cat": "biblical"},{"i": 4215,"n": "אמציה","l": "א","b": "","cat": "biblical"},{"i": 4216,"n": "אמרפל","l": "א","b": "","cat": "biblical"},{"i": 4217,"n": "אמתלאה","l": "א","b": "","cat": "biblical"},{"i": 4394,"n": "אם סיסרא","l": "א","b": "","cat": "biblical"},{"i": 4324,"n": "אנוש","l": "א","b": "","cat": "biblical"},{"i": 4218,"n": "אסא","l": "א","b": "","cat": "biblical"},{"i": 4219,"n": "אסנת","l": "א","b": "","cat": "biblical"},{"i": 4220,"n": "אסף","l": "א","b": "","cat": "biblical"},{"i": 4221,"n": "אסתר","l": "א","b": "אסתר המלכה היא גיבורת מגילת אסתר. היא הסתירה את זהותה היהודית לאחר שנבחרה להיות אשתו של אחשוורוש מלך פרס, ומלכה בממלכתו. יחד עם בן דודה מרדכי הצילה את העם היהודי מגזרת הכליה של המן, שהיה בכיר שרי אחשוורוש.","cat": "biblical"},{"i": 4270,"n": "אפרים","l": "א","b": "אפרים הוא בנם השני של יוסף ואסנת. על אף היותו הבן הצעיר קיבל את ברכת הבכורה של סבו יעקב.","cat": "biblical"},{"i": 4271,"n": "ארבע","l": "א","b": "","cat": "biblical"},{"i": 4331,"n": "ארד","l": "א","b": "","cat": "biblical"},{"i": 4272,"n": "ארונה","l": "א","b": "","cat": "biblical"},{"i": 4416,"n": "אריוך","l": "א","b": "","cat": "biblical"},{"i": 4273,"n": "ארם","l": "א","b": "ארם, בנו של שם, היה אבי הארמים. אברהם הוא מצאצאיו, וכך גם רבקה כלתו ואחיה לבן. בספרות חז\"ל לבן ידוע בכינוי \"הארמי\".","cat": "biblical"},{"i": 4442,"n": "ארפכשד","l": "א","b": "","cat": "biblical"},{"i": 4281,"n": "אשור","l": "א","b": "","cat": "biblical"},{"i": 4036,"n": "אשכנז","l": "א","b": "","cat": "biblical"},{"i": 4037,"n": "אשר","l": "א","b": "","cat": "biblical"},{"i": 4441,"n": "אשת איוב","l": "א","b": "","cat": "biblical"},{"i": 4452,"n": "אשת מנוח","l": "א","b": "","cat": "biblical"},{"i": 4328,"n": "אתבעל מלך צידונים","l": "א","b": "","cat": "biblical"},{"i": 4038,"n": "אתי הגתי","l": "א","b": "","cat": "biblical"},{"i": 4494,"n": "אֱלִיחוֹרֶף","l": "א","b": "","cat": "biblical"},{"i": 4495,"n": "אֱלִיעֶזֶר","l": "א","b": "","cat": "biblical"},{"i": 4487,"n": "אֲבִירָ֨ם","l": "א","b": "","cat": "biblical"},{"i": 4378,"n": "אֵלוֹן","l": "א","b": "","cat": "biblical"},{"i": 4384,"n": "אֵלָה","l": "א","b": "","cat": "biblical"},{"i": 4309,"n": "אָמוֹץ","l": "א","b": "","cat": "biblical"},{"i": 4039,"n": "בארה","l": "ב","b": "","cat": "biblical"},{"i": 4470,"n": "בגתא","l": "ב","b": "","cat": "biblical"},{"i": 4049,"n": "בגתן ותרש","l": "ב","b": "","cat": "biblical"},{"i": 4050,"n": "בועז","l": "ב","b": "בועז הוא מעשירי העיר בית לחם וממנהיגיה. מתוך נדיבותו סייע לעניים ובכלל זה לרות המואבייה שבאה ללקט שיבולים בשדותיו. מאוחר יותר נשא אותה לאישה ונולד להם בן. דוד המלך הוא מצאצאיו.","cat": "biblical"},{"i": 4143,"n": "בלדד","l": "ב","b": "","cat": "biblical"},{"i": 4301,"n": "בלהה","l": "ב","b": "","cat": "biblical"},{"i": 4144,"n": "בלעם","l": "ב","b": "בלעם בן בעור הוא נביא מקראי שאינו מבני ישראל. בשעת נדודי בני ישראל במדבר שילם לו בלק מלך מואב שיקלל את בני ישראל. הוא הצליח להוציא מפיו רק את המילים שהאל שם בפיו, וכך בסופו של דבר בירך את עם ישראל במקום לקללו.","cat": "biblical"},{"i": 4310,"n": "בלע בן בעור","l": "ב","b": "","cat": "biblical"},{"i": 4490,"n": "בלק","l": "ב","b": "","cat": "biblical"},{"i": 4145,"n": "בלשאצר","l": "ב","b": "","cat": "biblical"},{"i": 4202,"n": "בניהו","l": "ב","b": "","cat": "biblical"},{"i": 4203,"n": "בנימין","l": "ב","b": "בנימין הוא הצעיר בבני יעקב, בן זקונים לאביו. אימו רחל מתה בלידתו. הוא היה אהוב במיוחד על יעקב. כאשר נסע עם אֶחיו למצרים לבקש אוכל, יוסף, שהיה המשנה למלך מצרים, האשים אותו בגנבה. יתר אחיו הגנו עליו בהפגנת נאמנות שהעידה על שינוי בגישתם כלפי בני רחל.","cat": "biblical"},{"i": 4146,"n": "בן הדד","l": "ב","b": "","cat": "biblical"},{"i": 4415,"n": "בן-הדד השני","l": "ב","b": "","cat": "biblical"},{"i": 4404,"n": "בן־עמי","l": "ב","b": "","cat": "biblical"},{"i": 4371,"n": "בעלת האוב מעין דור","l": "ב","b": "","cat": "biblical"},{"i": 4204,"n": "בעשא","l": "ב","b": "","cat": "biblical"},{"i": 4406,"n": "בצלאל","l": "ב","b": "","cat": "biblical"},{"i": 4222,"n": "ברוך בן נריה","l": "ב","b": "","cat": "biblical"},{"i": 4223,"n": "ברזילי הגלעדי","l": "ב","b": "","cat": "biblical"},{"i": 4438,"n": "ברע","l": "ב","b": "","cat": "biblical"},{"i": 4476,"n": "ברק","l": "ב","b": "","cat": "biblical"},{"i": 4454,"n": "בשמת בת ישמעאל","l": "ב","b": "","cat": "biblical"},{"i": 4003,"n": "בתואל","l": "ב","b": "","cat": "biblical"},{"i": 4521,"n": "בתיה","l": "ב","b": "בִּתְיָה הוא השם שנותן המדרש לבת פרעה, שהצילה את משה מן היאור וגידלה אותו בארמון פרעה. בספרות המדרשית בת פרעה מתגיירת וניתן לה השם בִּתְיָה שמשמעותו \"בתו של האל\".","cat": "biblical"},{"i": 4475,"n": "בת שבע","l": "ב","b": "בת שבע הייתה אחת מנשיו של דוד המלך. דוד ראה אותה רוחצת על גג ביתה ודאג שבעלה אוריה יישלח לחזית המלחמה כדי שייהרג והוא עצמו יוכל לשאת אותה לאישה. בנם שלמה ירש את המלוכה מאביו, אף שהיו לו אחים רבים מבוגרים ממנו.","cat": "biblical"},{"i": 4358,"n": "בת-שוע","l": "ב","b": "","cat": "biblical"},{"i": 4519,"n": "בֶּן מִֹשֶׁה","l": "ב","b": "","cat": "biblical"},{"i": 4429,"n": "בַּלע","l": "ב","b": "","cat": "biblical"},{"i": 4491,"n": "בַּעֲרָה","l": "ב","b": "","cat": "biblical"},{"i": 4492,"n": "בָלָק בֶּן צִפּוֹר","l": "ב","b": "","cat": "biblical"},{"i": 4005,"n": "גד","l": "ג","b": "גד, בנו השביעי של יעקב ובנה הראשון של זלפה פילגש יעקב, הוא אבי שבט גד.","cat": "biblical"},{"i": 4006,"n": "גדליה","l": "ג","b": "","cat": "biblical"},{"i": 4418,"n": "גדעון","l": "ג","b": "גדעון היה שופט ומנהיג צבאי בספר שופטים. הוא הוביל את בני ישראל, שהיו חלשים בתקופתו, לניצחון על המדיינים. העם הציע להמליכו, אבל הוא סירב בהדגישו שהאל הוא הריבון היחיד.","cat": "biblical"},{"i": 4004,"n": "גד החוזה","l": "ג","b": "","cat": "biblical"},{"i": 4472,"n": "גומר בן יפת","l": "ג","b": "","cat": "biblical"},{"i": 4482,"n": "גומר בת דבלים","l": "ג","b": "","cat": "biblical"},{"i": 4114,"n": "גחזי","l": "ג","b": "","cat": "biblical"},{"i": 4115,"n": "גלית","l": "ג","b": "","cat": "biblical"},{"i": 4116,"n": "געל","l": "ג","b": "","cat": "biblical"},{"i": 4130,"n": "גרשם","l": "ג","b": "","cat": "biblical"},{"i": 4334,"n": "גשם הערבי","l": "ג","b": "","cat": "biblical"},{"i": 4365,"n": "גתר","l": "ג","b": "","cat": "biblical"},{"i": 4496,"n": "גִישְׁפָּא","l": "ג","b": "","cat": "biblical"},{"i": 4497,"n": "גֵּרְשׁוֹם","l": "ג","b": "","cat": "biblical"},{"i": 4168,"n": "דבורה","l": "ד","b": "דבורה, נביאה בספר שופטים, שפטה את ישראל תחת עץ תומר. היא יעצה לברק בנוגע למלחמה נגד סיסרא, שר הצבא האשורי.","cat": "biblical"},{"i": 4167,"n": "דבורה מינקת רבקה","l": "ד","b": "","cat": "biblical"},{"i": 4375,"n": "דדנים","l": "ד","b": "","cat": "biblical"},{"i": 4169,"n": "דואג","l": "ד","b": "דואג, משרתו האדומי של שאול המלך, הוציא להורג כמה כוהנים שסייעו לדוד בתקופת בריחתו משאול.","cat": "biblical"},{"i": 4170,"n": "דוד המלך","l": "ד","b": "דוד המלך הוא המלך השני של ישראל ומייסד שושלת בית דוד. הוא קבע את ירושלים כעיר הבירה. מקובל לייחס לו את כתיבת ספר תהילים. יורש העצר שלו היה בנו שלמה. נאמר שהמשיח העתידי הוא מצאצאיו.","cat": "biblical"},{"i": 4171,"n": "דומה","l": "ד","b": "","cat": "biblical"},{"i": 4227,"n": "דינה","l": "ד","b": "דינה היא בתו של יעקב אבינו. כאשר יצאה אל העיר שכם, נלקחה בכוח על ידי נסיך העיר, עונתה והוחזקה בארמונו. כנקמה הרגו אחֶיה שמעון ולוי את כל הזכרים בשכם והחזירו את דינה אחותם.","cat": "biblical"},{"i": 4379,"n": "דלילה","l": "ד","b": "","cat": "biblical"},{"i": 4228,"n": "דן","l": "ד","b": "דן, בנו החמישי של יעקב ובנה הראשון של בלהה פילגש יעקב, הוא אבי שבט דן.","cat": "biblical"},{"i": 4229,"n": "דניאל","l": "ד","b": "דניאל הוא הגיבור של ספר דניאל המקראי. לאחר כיבוש ירושלים וחורבן העיר על ידי הבבלים הוא נלקח לחצר נבוכדנצר מלך בבל. הוא גדל בבית המלך אך נותר נאמן לאמונתו. הוא ניבא את חורבן בבל על ידי ממלכת פרס ואת עליית האימפריה המקדוני והסלאוקי.","cat": "biblical"},{"i": 4230,"n": "דריוש","l": "ד","b": "","cat": "biblical"},{"i": 4231,"n": "דתן ואבירם","l": "ד","b": "","cat": "biblical"},{"i": 4474,"n": "דְּבוֹרָה הַנְּבִיאָה","l": "ד","b": "","cat": "biblical"},{"i": 4327,"n": "האישה החכמה מאבל בית מעכה","l": "ה","b": "","cat": "biblical"},{"i": 4387,"n": "האישה החכמה מתקוע","l": "ה","b": "","cat": "biblical"},{"i": 4381,"n": "האישה מצרפת","l": "ה","b": "","cat": "biblical"},{"i": 3976,"n": "הבל","l": "ה","b": "הבל, בנם השני של אדם וחוה, היה רועה הצאן הראשון. האל קיבל את מנחתו שהובאה מבכורות צאנו  אבל דחה את מנחת פירות האדמה של אחיו קין. בשל כך רצח קין, האח הקנאי, את הבל.","cat": "biblical"},{"i": 3977,"n": "הגי","l": "ה","b": "","cat": "biblical"},{"i": 3978,"n": "הגר","l": "ה","b": "שרה סבלה מעקרות והציעה לאברהם לקחת את שפחתה הגר לפילגש. הגר ילדה לו את ישמעאל ומאוחר יותר שולחה עם בנה אל המדבר. השניים ניצלו על ידי מלאך והיו לאבות האומה הישמעאלית.","cat": "biblical"},{"i": 4439,"n": "הדד בן בדד","l": "ה","b": "","cat": "biblical"},{"i": 4437,"n": "הדורם","l": "ה","b": "","cat": "biblical"},{"i": 3979,"n": "הושע בן אלה","l": "ה","b": "","cat": "biblical"},{"i": 3980,"n": "הושע (הנביא)","l": "ה","b": "הושע היה נביא בממלכת ישראל. האל ציווה אותו לקחת אישה זנונית בתור מטפורה לעם ישראל שזנו אחרי אלוהים אחרים.","cat": "biblical"},{"i": 3981,"n": "הימן","l": "ה","b": "","cat": "biblical"},{"i": 4030,"n": "המלך מנשה","l": "ה","b": "מנשה היה המלך הארבעה־עשר של יהודה ומתואר כמלך רשע. הוא חידש את עבודת האלילים ביהודה והיה כפוף למלך אשור.","cat": "biblical"},{"i": 4280,"n": "המלך שאול","l": "ה","b": "שאול הוא המלך הישראלי הראשון. הוא נמשח למלוכה על ידי שמואל הנביא ששימש לו יועץ. אף על פי שבתחילה היה לו קשר טוב עם דוד ששירת בחצרו, בחלוף הזמן פיתח חשדנות כלפיו וביקש להורגו. דוד נבחר על ידי האל למלוך תחת שאול ונשא לאישה את מיכל בתו. לאחר ששאול שלח יד בנפשו בקרב, קיבל דוד את המלוכה.","cat": "biblical"},{"i": 4083,"n": "המן","l": "ה","b": "המן הוא הרשע במגילת אסתר והבכיר בין שרי המלך אחשוורוש. הוא תכנן לבצע רצח עם שבו יושמדו היהודים בכל מדינות המלך אחשוורוש. תוכניתו סוכלה על ידי מרדכי ואסתר.","cat": "biblical"},{"i": 4084,"n": "הצללפוני","l": "ה","b": "","cat": "biblical"},{"i": 3991,"n": "הרן","l": "ה","b": "","cat": "biblical"},{"i": 3992,"n": "התך","l": "ה","b": "","cat": "biblical"},{"i": 4101,"n": "ושתי","l": "ו","b": "ושתי הייתה אשתו של אחשוורוש. הוא קרא לה להציג לראווה את יופייה בפני רעיו שישבו איתו במשתה. כאשר סירבה לבוא, הוא גירש אותה.","cat": "biblical"},{"i": 4408,"n": "זבד בן נתן","l": "ז","b": "","cat": "biblical"},{"i": 4374,"n": "זבודה בת פדיה","l": "ז","b": "","cat": "biblical"},{"i": 4102,"n": "זבולון","l": "ז","b": "זבולון, הבן העשירי של יעקב והבן השישי של לאה, הוא אבי שבט זבולון.","cat": "biblical"},{"i": 4104,"n": "זכריה","l": "ז","b": "זכריה היה נביא בתקופת דריווש מלך פרס. נבואותיו נגעו לימות המשיח.","cat": "biblical"},{"i": 4103,"n": "זכריה בן יהוידע","l": "ז","b": "","cat": "biblical"},{"i": 4105,"n": "זלפה","l": "ז","b": "","cat": "biblical"},{"i": 4106,"n": "זמרי","l": "ז","b": "בן סלוא","cat": "biblical"},{"i": 4399,"n": "זמרן","l": "ז","b": "","cat": "biblical"},{"i": 4136,"n": "זרובבל","l": "ז","b": "","cat": "biblical"},{"i": 4466,"n": "זרח","l": "ז","b": "","cat": "biblical"},{"i": 4477,"n": "זרח מלך כוש","l": "ז","b": "","cat": "biblical"},{"i": 4181,"n": "זרש","l": "ז","b": "","cat": "biblical"},{"i": 4182,"n": "חבקוק","l": "ח","b": "","cat": "biblical"},{"i": 4373,"n": "חבר הקיני","l": "ח","b": "","cat": "biblical"},{"i": 4291,"n": "חגי","l": "ח","b": "","cat": "biblical"},{"i": 4340,"n": "חגלה","l": "ח","b": "","cat": "biblical"},{"i": 4417,"n": "חוה","l": "ח","b": "חוה היא האישה הראשונה מבנות מינה ואם כל חי. היא נוצרה מצלעו של אדם והופרדה ממנו. הנחש בגן עדן שכנע אותה לטעום מפרי עץ הדעת, וממנו האכילה גם את אדם. בעקבות זאת גורשו שניהם מגן עדן, ובנות מינה קוללו בלידות קשות ובשיעבוד לגברים.","cat": "biblical"},{"i": 4459,"n": "חוילה","l": "ח","b": "","cat": "biblical"},{"i": 4312,"n": "חול","l": "ח","b": "","cat": "biblical"},{"i": 4183,"n": "חולדה נביאה","l": "ח","b": "","cat": "biblical"},{"i": 4184,"n": "חור","l": "ח","b": "","cat": "biblical"},{"i": 4185,"n": "חושי","l": "ח","b": "","cat": "biblical"},{"i": 4186,"n": "חושים בן דן","l": "ח","b": "","cat": "biblical"},{"i": 4499,"n": "חוּשִׁים","l": "ח","b": "","cat": "biblical"},{"i": 4187,"n": "חזאל","l": "ח","b": "","cat": "biblical"},{"i": 4188,"n": "חזקיה","l": "ח","b": "חזקיהו הוא ממלכי יהודה שהנהיג רפורמה דתית שמטרתה ביסוס המונותאיזם הישראלי. הוא חיזק את ירושלים לקראת מצור אשורי, והעיר ניצלה בזכות שילוב של השגחת האל עם המפעל המרשים של חזקיהו: חציבת נקבת השילוח שהבטיחה אספקת מים לעיר במהלך המצור.","cat": "biblical"},{"i": 4189,"n": "חיאל","l": "ח","b": "","cat": "biblical"},{"i": 4205,"n": "חירם","l": "ח","b": "","cat": "biblical"},{"i": 4246,"n": "חלקיה","l": "ח","b": "","cat": "biblical"},{"i": 4357,"n": "חלקיהו בן שלום","l": "ח","b": "","cat": "biblical"},{"i": 4247,"n": "חם","l": "ח","b": "חם, בנו של נח, קולל משום שהביט בערוות אביו בזמן היותו שיכור. הוא אבי העם הכנעני.","cat": "biblical"},{"i": 4302,"n": "חמוטל בת ירמיהו","l": "ח","b": "","cat": "biblical"},{"i": 4396,"n": "חמור","l": "ח","b": "","cat": "biblical"},{"i": 4248,"n": "חנה","l": "ח","b": "חנה היא אשת אלקנה ואם שמואל הנביא. היא התמודדה עם עקרות ממושכת, ובמצוקתה הגיעה למשכן בשילה. במקום להקריב קורבן בלבד היא נשאה תפילה בפה לילד, תפילה מילולית. האל שמע את תפילתה, והיא ילדה את שמואל, שבבגרותו היה לנביא ולמנהיג שהוביל את עם ישראל. על פי המסורת, חנה שימשה מודל לתפילה מילולית.","cat": "biblical"},{"i": 4249,"n": "חנוך בן ירד","l": "ח","b": "","cat": "biblical"},{"i": 4250,"n": "חנניה מישאל ועזריה","l": "ח","b": "","cat": "biblical"},{"i": 4480,"n": "חפני","l": "ח","b": "","cat": "biblical"},{"i": 4251,"n": "חפצי בה","l": "ח","b": "","cat": "biblical"},{"i": 4318,"n": "חצרון","l": "ח","b": "","cat": "biblical"},{"i": 4252,"n": "חרבונה","l": "ח","b": "","cat": "biblical"},{"i": 4498,"n": "חֲנַנְיָה בֶּן עַזּוּר","l": "ח","b": "","cat": "biblical"},{"i": 4440,"n": "טובי","l": "ט","b": "","cat": "biblical"},{"i": 4465,"n": "טוביה","l": "ט","b": "","cat": "biblical"},{"i": 4051,"n": "יאיר","l": "י","b": "","cat": "biblical"},{"i": 4486,"n": "יאיר","l": "י","b": "","cat": "biblical"},{"i": 4337,"n": "יאשיהו","l": "י","b": "יאשיהו היה המלך השישה־עשר של יהודה ומתואר כמלך צדיק, שלא כרבים מאבותיו. הוא שיפץ את בית המקדש וגילה ספר תורה אבוד, ככל הנראה ספר דברים.","cat": "biblical"},{"i": 4432,"n": "יבחר","l": "י","b": "","cat": "biblical"},{"i": 4368,"n": "יבל","l": "י","b": "","cat": "biblical"},{"i": 4052,"n": "ידותון","l": "י","b": "","cat": "biblical"},{"i": 4053,"n": "יהוא","l": "י","b": "","cat": "biblical"},{"i": 4054,"n": "יהודה","l": "י","b": "יהודה הוא בנו הרביעי של יעקב, אבי שבט יהודה, ודוד המלך הוא מצאצאיו. נחלת יהודה קרויה על שמו, וכן עם ישראל בגלגוליו המאוחרים קרוי על שמו עד היום. בברכת יעקב לבניו לפני מותו התברך יהודה שיהיה גביר לאֶחיו.","cat": "biblical"},{"i": 4317,"n": "יהודי","l": "י","b": "","cat": "biblical"},{"i": 4055,"n": "יהוידע","l": "י","b": "","cat": "biblical"},{"i": 4056,"n": "יהויכין","l": "י","b": "","cat": "biblical"},{"i": 4057,"n": "יהויקים","l": "י","b": "יהויקים היה המלך השמונה־עשר של יהודה. בתחילה היה כפוף לממלכת מצרים אך לאחר מכן הכריז על נאמנותו לבבל בתקווה למנוע את חורבן ירושלים. בספרות חז\"ל מתואר כמלך רשע.","cat": "biblical"},{"i": 4484,"n": "יהונדב","l": "י","b": "","cat": "biblical"},{"i": 4058,"n": "יהונדב בן רכב","l": "י","b": "","cat": "biblical"},{"i": 4059,"n": "יהונתן בן גרשם","l": "י","b": "","cat": "biblical"},{"i": 4060,"n": "יהונתן בן שאול","l": "י","b": "יהונתן, בנו של שאול המלך וחבר נפש של דוד המלך, צידד בדוד במקום באביו שאול והציל את חיי דוד. נהרג בקרב בצד אביו ואֶחָיו.","cat": "biblical"},{"i": 4071,"n": "יהורם מלך יהודה","l": "י","b": "","cat": "biblical"},{"i": 4072,"n": "יהורם מלך ישראל","l": "י","b": "","cat": "biblical"},{"i": 4074,"n": "יהושע","l": "י","b": "בתור יורשו של משה, יהושע הוביל את בני ישראל לתוך הארץ המובטחת. תחת הנהגתו כבש העם חלקים נרחבים מן הארץ. יהושע וכלב הם היחידים מדור יוצאי מצרים ששרדו את המדבר ונכנסו לארץ המובטחת.","cat": "biblical"},{"i": 4073,"n": "יהושע כהן גדול","l": "י","b": "","cat": "biblical"},{"i": 4075,"n": "יהושפט","l": "י","b": "","cat": "biblical"},{"i": 4076,"n": "יואב","l": "י","b": "יואב היה האחיין של דוד המלך ושר צבאו. הוא הנהיג את כוחותיו של דוד נגד מרד בנו אבשלום. מאוחר יותר הצטרף יואב למרד של אדניה, גם הוא בנו של דוד, ובעקבות זאת הורה דוד לשלמה להוציאו להורג.","cat": "biblical"},{"i": 4426,"n": "יואח בן אסף","l": "י","b": "","cat": "biblical"},{"i": 4077,"n": "יואל","l": "י","b": "","cat": "biblical"},{"i": 4078,"n": "יואש","l": "י","b": "","cat": "biblical"},{"i": 4079,"n": "יואש","l": "י","b": "","cat": "biblical"},{"i": 4345,"n": "יובב","l": "י","b": "","cat": "biblical"},{"i": 4478,"n": "יובל","l": "י","b": "","cat": "biblical"},{"i": 4306,"n": "יוון","l": "י","b": "","cat": "biblical"},{"i": 4080,"n": "יוכבד","l": "י","b": "יוכבד היא דמות בספר שמות ואימם של אהרון, מרים ומשה. מחשש לצו של פרעה להשליך את כל ילדי ישראל אל היאור, היא הסתירה את בנה התינוק, משה. כאשר לא היה אפשר עוד להסתירו, יוכבד הניחה אותו בתבה על נהר הנילוס, שם מצאה אותו בת פרעה.","cat": "biblical"},{"i": 4108,"n": "יונה הנביא","l": "י","b": "יונה, גיבורו של ספר יונה המקראי, הוא נביא מסויג. הוא נצטווה על ידי האל לנבא לבני העיר נינווה על חורבנה אם לא יחזרו אנשיה בתשובה, אבל ניסה להתחמק משליחות זו. הוא ברח באונייה ללב ים, הוטל ממנה בשעת סערה גדולה ונבלע על ידי דג גדול. לאחר שניצל באורח נס, הלך לנינווה להזהיר את אנשי העיר מפני החורבן, ואלה נענו לו וחזרו בתשובה.","cat": "biblical"},{"i": 4469,"n": "יונתן בן אביתר","l": "י","b": "","cat": "biblical"},{"i": 4110,"n": "יוסף","l": "י","b": "יוסף הוא בנו האחד־עשר של יעקב, אחד משנים־עשר האחים. לאחר שנמכר לעבדות במצרים על ידי אֶחיו, היה לפותר חלומות ומונה למשנה ויועץ לפרעה. בזכותו עלה בידי יעקב ובניו לרדת למצרים והם ניצלו מהרעב הכבד בארץ כנען, ובזכותו הם השתקעו במצרים בתמיכת פרעה.","cat": "biblical"},{"i": 4111,"n": "יותם","l": "י","b": "","cat": "biblical"},{"i": 4479,"n": "יותם","l": "י","b": "","cat": "biblical"},{"i": 4501,"n": "יוֹחָנָן בֶּן קָרֵחַ","l": "י","b": "","cat": "biblical"},{"i": 4502,"n": "יוֹנָתָן","l": "י","b": "","cat": "biblical"},{"i": 4112,"n": "יחזקאל","l": "י","b": "יחזקאל הוא נביא בתקופת המלכים יאשיהו ויהויכין. נבואותיו מתאפיינות בחזיונות בעלי משמעות מיסטית של מרכבת האל, מלוכתו וצבאותיו. על פי המסורת היהודית, נבואותיו נכתבו כספר בתקופה מאוחרת יותר.","cat": "biblical"},{"i": 4376,"n": "יחלאל","l": "י","b": "","cat": "biblical"},{"i": 4344,"n": "יטור","l": "י","b": "","cat": "biblical"},{"i": 4350,"n": "יכין","l": "י","b": "","cat": "biblical"},{"i": 4400,"n": "ימימה","l": "י","b": "","cat": "biblical"},{"i": 4436,"n": "יסכה","l": "י","b": "","cat": "biblical"},{"i": 4128,"n": "יעבץ","l": "י","b": "","cat": "biblical"},{"i": 4449,"n": "יעוש","l": "י","b": "","cat": "biblical"},{"i": 4129,"n": "יעל אשת חבר הקיני","l": "י","b": "יעל, דמות בספר שופטים, פיתתה את סיסרא, שר הצבא הכנעני, והזמינה אותו להיכנס לתוך האוהל שלה. לאחר שנתנה לו חלב חם והרדימה אותו, נעצה יתד ברקתו והרגה אותו.","cat": "biblical"},{"i": 4194,"n": "יעקב","l": "י","b": "יעקב הוא האחרון בין שלושת האבות של עם ישראל, ונשותיו הן רחל ולאה. לאחר שנאבק עם מלאך אלוהים, ניתן לו השם \"ישראל\", שאומץ כשם האומה היהודית עד היום הזה. ליעקב נולדו שנים־עשר בנים ובת אחת. בניו הם אבות שנים־עשר שבטי ישראל הקרויים על שמם.","cat": "biblical"},{"i": 4195,"n": "יפת","l": "י","b": "","cat": "biblical"},{"i": 4196,"n": "יפתח","l": "י","b": "","cat": "biblical"},{"i": 4444,"n": "יצהר","l": "י","b": "","cat": "biblical"},{"i": 4197,"n": "יצחק","l": "י","b": "יצחק הוא השני בין שלושת אבות העם היהודי ובעלה של רבקה. אביו אברהם צוּוה להקריבו כניסיון אמוני, ולאחר שניצל המשיך יצחק את דרכו ואת פועלו של אביו. שושלת העם היהודי המשיכה באמצעות בנו הצעיר יעקב.","cat": "biblical"},{"i": 4199,"n": "יקטן","l": "י","b": "","cat": "biblical"},{"i": 4382,"n": "יקשן","l": "י","b": "","cat": "biblical"},{"i": 4200,"n": "ירבעם בן יואש","l": "י","b": "","cat": "biblical"},{"i": 4201,"n": "ירבעם בן נבט","l": "י","b": "ירבעם היה המלך הראשון בממלכת ישראל אחרי שמרד במלכות שושלת דוד. הוא יצר בממלכתו מערך מקביל של פולחן וכהונה כקריאת תגר על בית המקדש ובכהונה ביהודה.","cat": "biblical"},{"i": 4254,"n": "ירמיהו","l": "י","b": "ירמיהו הוא אחד הנביאים הבולטים במקרא. הוא הזהיר את העם שירושלים תיחרב על ידי הבבלים כעונש על חטאי עם ישראל, אך העם לעג לו והתעלם מדבריו. עם חורבן ירושלים גלה ירמיהו לבבל עם רבים מבני יהודה. מקובל לייחס לו את כתיבת ספר ירמיהו וספר איכה.","cat": "biblical"},{"i": 4255,"n": "ישבי","l": "י","b": "","cat": "biblical"},{"i": 4332,"n": "ישבק","l": "י","b": "","cat": "biblical"},{"i": 4256,"n": "ישי","l": "י","b": "","cat": "biblical"},{"i": 4258,"n": "ישמעאל","l": "י","b": "ישמעאל הוא בנו הבכור של אברהם ובנה של הגר פילגשו. בעקבות עצת שרה וצו האל שולחו ישמעאל והגר מבית אברהם. לאחר שנקלעו למצוקה במדבר, נגלה אליהם מלאך שהוביל אותם לבאר מים ועודד אותם בנוגע לעתידם. ישמעאל הוא אבי העם הישמעאלי.","cat": "biblical"},{"i": 4257,"n": "ישמעאל בן נתניה","l": "י","b": "","cat": "biblical"},{"i": 4259,"n": "ישעיהו","l": "י","b": "ישעיהו הוא אחד הנביאים החשובים במקרא, ומקובל לייחס לו את ספר ישעיהו. הוא נודע בזכות נבואות החורבן והגאולה שלו. נבואותיו משלבות מרכיבים פוליטיים ומשיחיים.","cat": "biblical"},{"i": 4267,"n": "יששכר","l": "י","b": "יששכר, בנו התשיעי של יעקב והבן החמישי של לאה, הוא אבי שבט יששכר.","cat": "biblical"},{"i": 4269,"n": "יתרו","l": "י","b": "יתרו הוא אבי צפורה, אשת משה, וכוהן מדיין. הוא שימש יועץ למשה בתקופת הנדודים במדבר.","cat": "biblical"},{"i": 4304,"n": "יתרעם","l": "י","b": "","cat": "biblical"},{"i": 4268,"n": "יתר הישמעאלי","l": "י","b": "","cat": "biblical"},{"i": 4500,"n": "יִשְׁמָעֵ֣אל בֶּן־נְ֠תַנְיָה בֶּן־אֱלִ֨ישָׁמָ֝ע","l": "י","b": "","cat": "biblical"},{"i": 4457,"n": "יֶרֶד","l": "י","b": "","cat": "biblical"},{"i": 4451,"n": "כדרלעומר","l": "כ","b": "","cat": "biblical"},{"i": 4085,"n": "כורש","l": "כ","b": "","cat": "biblical"},{"i": 4086,"n": "כוש","l": "כ","b": "כוש הייתה ממלכה אפריקאית קדומה בדרומו של עמק הנילוס, ובמקורות היהודיים היא מזוהה לרוב עם אתיופיה. בחלק מן המקורות המושג מיוחס לכל אפריקה שמדרום לסהרה או לאנשים כהי עור באופן כללי.","cat": "biblical"},{"i": 4087,"n": "כושן רשעתים","l": "כ","b": "","cat": "biblical"},{"i": 4088,"n": "כזבי","l": "כ","b": "","cat": "biblical"},{"i": 4113,"n": "כלאב","l": "כ","b": "","cat": "biblical"},{"i": 4131,"n": "כלב בן יפונה","l": "כ","b": "כלב בן יפונה היה אחד משנים־עשר המרגלים שיצאו לתור את ארץ כנען אחרי יציאת מצרים. בעוד רוב המרגלים חששו מפני הכנענים ועריהם הבצורות והביאו לעם דיווחים מייאשים, היה דיווחו של כלב מעודד, והותר לו להיכנס לארץ המובטחת.","cat": "biblical"},{"i": 4333,"n": "כליון","l": "כ","b": "","cat": "biblical"},{"i": 4401,"n": "כנען","l": "כ","b": "","cat": "biblical"},{"i": 4190,"n": "כתים","l": "כ","b": "","cat": "biblical"},{"i": 4493,"n": "כָּלֵב בֶּן חֶצְרוֹן","l": "כ","b": "","cat": "biblical"},{"i": 4191,"n": "לאה","l": "ל","b": "לאה היא אחת מארבע האימהות של עם ישראל ואשתו הראשונה של יעקב. נישואיה ליעקב נבעו ממעשה הרמאות של אביה, לבן הארמי, שהשיא אותה ליעקב במקום את אחותה רחל. אהבת יעקב לרחל ולא לה ציערה אותה. היא בורכה בשישה בנים ובבת אחת, ומזרעם של השישה נוצרו שישה משבטי ישראל.","cat": "biblical"},{"i": 4192,"n": "לבן בן בתואל","l": "ל","b": "","cat": "biblical"},{"i": 4198,"n": "לוד","l": "ל","b": "","cat": "biblical"},{"i": 4232,"n": "לוט","l": "ל","b": "לוט היה אחיינו של אברהם. כשהתעשר הפריד את עצמו ואת ביתו מבית אברהם והתיישב בסדום. מלאכים הצילו אותו ואת משפחתו מהפיכת סדום. בנותיו חשבו שהן ולוט הם אחרוני האנשים ששרדו, ולכן הן ילדו לו בנים, שהיו לאבות העמים עמון ומואב.","cat": "biblical"},{"i": 4305,"n": "לוי","l": "ל","b": "לוי הוא בנם השלישי של יעקב ולאה. לאחר שאחותו דינה נאנסה ונשבתה בידי שכם, יצא לוי עם אחיו שמעון לנקום בבני עירו. בשל פזיזותו קילל אותו יעקב שצאצאיו יחולקו ויפוצו. הוא אבי שבט לוי.","cat": "biblical"},{"i": 4243,"n": "למואל","l": "ל","b": "","cat": "biblical"},{"i": 4244,"n": "למך","l": "ל","b": "","cat": "biblical"},{"i": 4503,"n": "לֶמֶךְ","l": "ל","b": "","cat": "biblical"},{"i": 4361,"n": "מבשם","l": "מ","b": "","cat": "biblical"},{"i": 4414,"n": "מגוג","l": "מ","b": "","cat": "biblical"},{"i": 3973,"n": "מדי","l": "מ","b": "","cat": "biblical"},{"i": 3974,"n": "מדין","l": "מ","b": "ארץ  מִדְיָן שכנה בין ארץ ישראל למצרים. היא יושבה לראשונה בידי צאצאי מדיין, אחד מבני אברהם, ומכאן שמה. את מרבית זמן גלותו ממצרים עשה משה במדיין, וכן הוא נישא לאישה מדיינית. מאוחר יותר, בשלבים האחרונים של המסע לארץ ישראל, התנכלו המדיינים לעם ישראל.","cat": "biblical"},{"i": 4346,"n": "מהללאל","l": "מ","b": "","cat": "biblical"},{"i": 3975,"n": "מואב","l": "מ","b": "המואבים הם צאצאי לוט, והתורה מצווה על בני ישראל לא לתקוף אותם אך גם לא להטמיע אותם בהם. דוד המלך הוא צאצא של מואבייה שהתגיירה – רות. ממלכת מואב שכנה בירדן של ימינו.","cat": "biblical"},{"i": 4398,"n": "מחויאל","l": "מ","b": "","cat": "biblical"},{"i": 4458,"n": "מחלון","l": "מ","b": "","cat": "biblical"},{"i": 3982,"n": "מחלת","l": "מ","b": "","cat": "biblical"},{"i": 3983,"n": "מיכה הנביא","l": "מ","b": "","cat": "biblical"},{"i": 3984,"n": "מיכל","l": "מ","b": "","cat": "biblical"},{"i": 3985,"n": "מישע","l": "מ","b": "","cat": "biblical"},{"i": 3986,"n": "מכיר","l": "מ","b": "","cat": "biblical"},{"i": 3995,"n": "מלאכי","l": "מ","b": "","cat": "biblical"},{"i": 4303,"n": "מלכה","l": "מ","b": "","cat": "biblical"},{"i": 3996,"n": "מלכי צדק","l": "מ","b": "","cat": "biblical"},{"i": 4467,"n": "מלכת שבא","l": "מ","b": "","cat": "biblical"},{"i": 4032,"n": "מלך סדום","l": "מ","b": "","cat": "biblical"},{"i": 3997,"n": "ממוכן","l": "מ","b": "","cat": "biblical"},{"i": 4288,"n": "ממרא","l": "מ","b": "","cat": "biblical"},{"i": 4019,"n": "מנוח","l": "מ","b": "","cat": "biblical"},{"i": 4313,"n": "מעכה","l": "מ","b": "","cat": "biblical"},{"i": 4341,"n": "מעכה בת תלמי","l": "מ","b": "","cat": "biblical"},{"i": 4046,"n": "מפיבושת","l": "מ","b": "","cat": "biblical"},{"i": 4047,"n": "מצרים","l": "מ","b": "למצרים תפקיד חשוב בתנ\"ך, והיא מוזכרת בו גם כמקום מפלט וגם כארץ של סכנה ושעבוד, בייחוד בסיפור יציאת מצרים. עבור היהודים מצרים היא תסביך – מצד אחד זהו מקום לידתו של העם היהודי, ומצד שני זהו המקום היחיד שנאסר עליו לגור בו.","cat": "biblical"},{"i": 4446,"n": "מרב בת שאול","l": "מ","b": "","cat": "biblical"},{"i": 4096,"n": "מרדכי","l": "מ","b": "מרדכי הוא מגיבורי מגילת אסתר. הוא היה מחצרני המלך אחשוורוש, הציל את המלך מניסיון רצח וסייע לבת דודו אסתר להציל את העם היהודי מכליה.","cat": "biblical"},{"i": 4097,"n": "מרודך בלאדן","l": "מ","b": "","cat": "biblical"},{"i": 4098,"n": "מרים","l": "מ","b": "מרים היא נביאה מקראית, ויחד עם אחיה משה ואהרן הנהיגה את בני ישראל בדרכם במדבר. היא הובילה את הנשים בשיר ובריקוד אחרי קריעת ים סוף. על פי המדרש, בזכותה ליוותה באר מים חיים את בני ישראל במסעותיהם במדבר, והבאר שקעה ונעלמה עם מותה.","cat": "biblical"},{"i": 4099,"n": "מררי","l": "מ","b": "","cat": "biblical"},{"i": 4338,"n": "מש","l": "מ","b": "","cat": "biblical"},{"i": 4323,"n": "משא","l": "מ","b": "","cat": "biblical"},{"i": 4253,"n": "משה","l": "מ","b": "משה היה גדול הנביאים במסורת המקראית. הוא גדל בבית פרעה, ברח ממצרים ונשלח לשם בחזרה על ידי אלוהים כדי להוציא את בני ישראל מעבדות ולהביאם לארץ המובטחת. משה קיבל את התורה בהר סיני כדי למסור אותה לבני ישראל. הוא נפטר לפני כניסת העם לארץ המובטחת.","cat": "biblical"},{"i": 4314,"n": "משך","l": "מ","b": "","cat": "biblical"},{"i": 4315,"n": "משמע","l": "מ","b": "","cat": "biblical"},{"i": 4468,"n": "מתושאל","l": "מ","b": "","cat": "biblical"},{"i": 4089,"n": "מתושלח","l": "מ","b": "","cat": "biblical"},{"i": 4504,"n": "מְנַשְּׁה","l": "מ","b": "","cat": "biblical"},{"i": 4427,"n": "מַחְלָה","l": "מ","b": "","cat": "biblical"},{"i": 4090,"n": "נבוזראדן","l": "נ","b": "","cat": "biblical"},{"i": 4091,"n": "נבוכדנאצר","l": "נ","b": "נבוכדנצר הוא ממלכי בבל. הוא כבש את ירושלים והגלה את תושביה לבבל. בספר דניאל מתואר שבתקופה מאוחרת יותר הכיר נבוכדנצר בגדולת אלוהי ישראל ואיבד את שפיותו.","cat": "biblical"},{"i": 4092,"n": "נבות","l": "נ","b": "","cat": "biblical"},{"i": 4093,"n": "נבח","l": "נ","b": "","cat": "biblical"},{"i": 4094,"n": "נבט","l": "נ","b": "","cat": "biblical"},{"i": 4409,"n": "נביות","l": "נ","b": "","cat": "biblical"},{"i": 4095,"n": "נבל","l": "נ","b": "","cat": "biblical"},{"i": 4425,"n": "נדב","l": "נ","b": "","cat": "biblical"},{"i": 4172,"n": "נון","l": "נ","b": "","cat": "biblical"},{"i": 4173,"n": "נח","l": "נ","b": "נח הוא הצדיק היחיד בדור של רשעים. כאשר החליט האל להחריב את העולם במבול, הוא הזהיר את נח וציווה עליו לבנות תיבה. נח ובני משפחתו ניצלו, ועימם שרדו זוג בעלי חיים מכל מין שנח הביא לתיבה.","cat": "biblical"},{"i": 4174,"n": "נחום","l": "נ","b": "","cat": "biblical"},{"i": 4175,"n": "נחור","l": "נ","b": "","cat": "biblical"},{"i": 4180,"n": "נחמיה","l": "נ","b": "נחמיה היה חצרן יהודי בפרס שהיה לאחד ממנהיגי היהודים בימי שיבת ציון. הוא ניהל את הבנייה המחודשת של בית המקדש וכונן מחדש אורח חיים המבוסס על קיום חוקי התורה.","cat": "biblical"},{"i": 4355,"n": "נחשון בן עמינדב","l": "נ","b": "נחשון בן עמינדב היה גיסו של אהרן הכהן, ושימש כנשיא שבט יהודה בתקופת שהייתם של בני ישראל במדבר. נחשון נודע בעיקר בגלל המדרש המתאר את אומץ לבו לקפוץ ראשון למי ים סוף בזמן קריעת ים סוף. כתוצאה מכך, נחשון נחשב לסמל של ההשתדלות אותה האדם צריך לעשות בנוסף לבטחונו באל.","cat": "biblical"},{"i": 4233,"n": "נחש העמוני","l": "נ","b": "","cat": "biblical"},{"i": 4405,"n": "נכו","l": "נ","b": "","cat": "biblical"},{"i": 4234,"n": "נמרוד","l": "נ","b": "","cat": "biblical"},{"i": 4343,"n": "נעה","l": "נ","b": "","cat": "biblical"},{"i": 4236,"n": "נעמה","l": "נ","b": "","cat": "biblical"},{"i": 4235,"n": "נעמה העמונית","l": "נ","b": "","cat": "biblical"},{"i": 4237,"n": "נעמי","l": "נ","b": "נעמי, אחת הדמויות המרכזיות במגילת רות, הייתה חמותה של רות. היא עזבה את בית לחם עם משפחתה בעקבות רעב ששרר בארץ והתיישבה במואב. לאחר שמתו בעלה ובניה, שבה עם רות לביתה בבית לחם ענייה וחסרת כול. תקוותה שבה אליה כשרות התחתנה עם בועז וילדה לו בן.","cat": "biblical"},{"i": 4238,"n": "נעמן","l": "נ","b": "","cat": "biblical"},{"i": 4471,"n": "נפיש","l": "נ","b": "","cat": "biblical"},{"i": 4245,"n": "נפתלי","l": "נ","b": "נפתלי, בנו השישי של יעקב ובנה השני של בלהה, הוא אבי שבט נפתלי.","cat": "biblical"},{"i": 4282,"n": "נר אבי קיש","l": "נ","b": "","cat": "biblical"},{"i": 3994,"n": "נתנאל","l": "נ","b": "","cat": "biblical"},{"i": 3993,"n": "נתן הנביא","l": "נ","b": "","cat": "biblical"},{"i": 4307,"n": "סבתה","l": "ס","b": "","cat": "biblical"},{"i": 4033,"n": "סיחון","l": "ס","b": "","cat": "biblical"},{"i": 4034,"n": "סיסרא","l": "ס","b": "","cat": "biblical"},{"i": 4035,"n": "סנבלט","l": "ס","b": "","cat": "biblical"},{"i": 4081,"n": "סנחריב","l": "ס","b": "סנחריב היה מלך אשורי שביקש לכבוש את ירושלים. ישעיהו ניבא את מפלתו. הוא הטיל מצור על העיר, אבל המלך חזקיהו עמד במצור. לאחר שמלאך הביס את הכוחות האשוריים, נסוג סנחריב מהעיר.","cat": "biblical"},{"i": 4024,"n": "ספר איוב","l": "ס","b": "","cat": "biblical"},{"i": 4377,"n": "סרד","l": "ס","b": "","cat": "biblical"},{"i": 4082,"n": "סרח בת אשר","l": "ס","b": "סרח בת אשר הייתה בתו של אשר בן יעקב. לפי המדרש היא מעולם לא מתה והמשיכה ללוות את בני ישראל בכל מקום שהיו בו.","cat": "biblical"},{"i": 4512,"n": "סְנָאָה בֶן בִּנְיָמִן","l": "ס","b": "","cat": "biblical"},{"i": 4366,"n": "עבדאל","l": "ע","b": "","cat": "biblical"},{"i": 4329,"n": "עבדון בן הלל","l": "ע","b": "","cat": "biblical"},{"i": 4107,"n": "עבד מלך הכושי","l": "ע","b": "","cat": "biblical"},{"i": 4147,"n": "עבר בן שם","l": "ע","b": "","cat": "biblical"},{"i": 4148,"n": "עגלון","l": "ע","b": "","cat": "biblical"},{"i": 4149,"n": "עדו","l": "ע","b": "","cat": "biblical"},{"i": 4150,"n": "עדינו","l": "ע","b": "","cat": "biblical"},{"i": 4462,"n": "עדריאל המחולתי","l": "ע","b": "","cat": "biblical"},{"i": 4152,"n": "עובד","l": "ע","b": "","cat": "biblical"},{"i": 4153,"n": "עובדיה","l": "ע","b": "","cat": "biblical"},{"i": 4151,"n": "עובד אדום","l": "ע","b": "","cat": "biblical"},{"i": 4154,"n": "עוג","l": "ע","b": "עוג היה מלך אמורי שמלך בבשן, ובספר במדבר מתואר שהובס על ידי משה ובני ישראל. ממסורת חז\"ל עולה שהוא היה ענק.","cat": "biblical"},{"i": 4372,"n": "עודד","l": "ע","b": "","cat": "biblical"},{"i": 4176,"n": "עוזא","l": "ע","b": "","cat": "biblical"},{"i": 4177,"n": "עוזיאל","l": "ע","b": "","cat": "biblical"},{"i": 4178,"n": "עוזיה","l": "ע","b": "","cat": "biblical"},{"i": 4179,"n": "עוץ","l": "ע","b": "","cat": "biblical"},{"i": 4383,"n": "עזובה","l": "ע","b": "","cat": "biblical"},{"i": 4224,"n": "עזרא","l": "ע","b": "עזרא הוא כוהן בתקופת שיבת ציון. אחרי כיבוש בבל על ידי הפרסים, התיר כורש מלך פרס ליהודים לשוב לארץ ישראל ולבנות מחדש את בית המקדש. עזרא עמד בראשם והנהיג סדרה של רפורמות שנועדה להשיב את היהודים למסורת הדתית שלהם.","cat": "biblical"},{"i": 4225,"n": "עזריהו בן עודד","l": "ע","b": "","cat": "biblical"},{"i": 4226,"n": "עידית","l": "ע","b": "","cat": "biblical"},{"i": 4363,"n": "עילם","l": "ע","b": "","cat": "biblical"},{"i": 4402,"n": "עיפה","l": "ע","b": "","cat": "biblical"},{"i": 4239,"n": "עירא היאירי","l": "ע","b": "","cat": "biblical"},{"i": 4364,"n": "עירד","l": "ע","b": "","cat": "biblical"},{"i": 4240,"n": "עכן","l": "ע","b": "","cat": "biblical"},{"i": 4241,"n": "עכסה","l": "ע","b": "","cat": "biblical"},{"i": 4242,"n": "עלי","l": "ע","b": "","cat": "biblical"},{"i": 4007,"n": "עמוס","l": "ע","b": "","cat": "biblical"},{"i": 4385,"n": "עמינדב","l": "ע","b": "","cat": "biblical"},{"i": 4008,"n": "עמלק","l": "ע","b": "עמלק הוא עם שהתקיף את בני ישראל במדבר. העמלקי התקיף מאחור ושם לו למטרה את החלשים בעם. בשל מעשה זה התורה מצווה על בני ישראל לזכור לנצח את עמלק ובד בבד למחות את שמו.","cat": "biblical"},{"i": 4040,"n": "עמרי","l": "ע","b": "","cat": "biblical"},{"i": 4041,"n": "עמרם","l": "ע","b": "","cat": "biblical"},{"i": 4042,"n": "עמשא","l": "ע","b": "","cat": "biblical"},{"i": 4367,"n": "ענה בן צבעון","l": "ע","b": "","cat": "biblical"},{"i": 4043,"n": "ענר","l": "ע","b": "","cat": "biblical"},{"i": 4044,"n": "עפרון","l": "ע","b": "","cat": "biblical"},{"i": 3999,"n": "ערפה","l": "ע","b": "","cat": "biblical"},{"i": 3998,"n": "ער בכור יהודה","l": "ע","b": "","cat": "biblical"},{"i": 4000,"n": "עשהאל","l": "ע","b": "","cat": "biblical"},{"i": 4001,"n": "עשיו","l": "ע","b": "עֵשָׂו הוא בכורם של יצחק ורבקה ואחי יעקב. הוא נודע כצייד מוכשר שוויתר על בכורתו ומכרהּ ליעקב עבור נזיד עדשים. בעקבות מעשה המרמה של יעקב הפסיד גם את ברכת הבכורה של אביו.","cat": "biblical"},{"i": 4132,"n": "עתליה","l": "ע","b": "","cat": "biblical"},{"i": 4133,"n": "עתניאל","l": "ע","b": "","cat": "biblical"},{"i": 4489,"n": "עֲבֵ֣ד נְג֔וֹ","l": "ע","b": "","cat": "biblical"},{"i": 4488,"n": "עֲזַרְיָה֖וּ נְגִ֥יד בֵּֽית־הָֽאֱלֹהִֽים","l": "ע","b": "","cat": "biblical"},{"i": 4370,"n": "עֶגְלָה","l": "ע","b": "","cat": "biblical"},{"i": 4347,"n": "עָדָה","l": "ע","b": "","cat": "biblical"},{"i": 4342,"n": "פדיה","l": "פ","b": "","cat": "biblical"},{"i": 4316,"n": "פוט","l": "פ","b": "","cat": "biblical"},{"i": 4134,"n": "פוטיאל","l": "פ","b": "","cat": "biblical"},{"i": 4135,"n": "פוטיפר","l": "פ","b": "","cat": "biblical"},{"i": 4062,"n": "פיכול","l": "פ","b": "","cat": "biblical"},{"i": 4064,"n": "פינחס","l": "פ","b": "פינחס נודע בעיקר בשל תגובתו האלימה נגד המשתחווים לבעל פעור. פולחן בעל פעור היה כרוך במגע מיני בין גברים מבני ישראל ונשים מואביות ומדייניות, ופינחס הרג זוג כזה בשעת מעשה. הוא היה מבכירי ההנהגה של עם ישראל בכניסתם לארץ המובטחת.","cat": "biblical"},{"i": 4321,"n": "פלג","l": "פ","b": "","cat": "biblical"},{"i": 4063,"n": "פלטי בן ליש","l": "פ","b": "","cat": "biblical"},{"i": 4481,"n": "פנחס","l": "פ","b": "","cat": "biblical"},{"i": 4065,"n": "פנינה","l": "פ","b": "","cat": "biblical"},{"i": 4138,"n": "פרעה","l": "פ","b": "במקרא מוזכרים כמה פרעונים, אך הידוע בהם הוא פרעה ששעבד את בני ישראל במצרים והקשה את ליבו כאשר נדרש לשחררם. בתקופת שלטונו הִכה האל את מצרים בעשר מכות. פרעה וחילו טובעו בים סוף לאחר שהחליטו לרדוף אחרי העם הבורח ממצרים.","cat": "biblical"},{"i": 4137,"n": "פרעה נכה","l": "פ","b": "","cat": "biblical"},{"i": 4139,"n": "פרץ","l": "פ","b": "","cat": "biblical"},{"i": 4522,"n": "פרשת בלק","l": "פ","b": "בפרשת בלק מסופר על בלק מלך מואב הפונה לבלעם ומבקש ממנו לקלל את בני ישראל. אלוהים מרשה לבלעם ללכת לקללם בתנאי שישמע בקול אלוהים. בדרך האתון של בלעם פותחת את פיה ומדברת. בלעם מנסה לקלל את בני ישראל שלוש פעמים, ובכל פעם קללתו הופכת לברכה בפיו. כאשר ישראל מתחילים לזנות עם בנות מואב ולזבוח לאלוהיהן אלוהים שולח מגפה בעם, ונהרגים בה עשרות אלפים. המגפה מסתיימת אחרי מעשה הקנאות של פינחס.","cat": "biblical"},{"i": 4140,"n": "פשחור","l": "פ","b": "","cat": "biblical"},{"i": 4141,"n": "פתואל","l": "פ","b": "","cat": "biblical"},{"i": 4142,"n": "פתחיה","l": "פ","b": "","cat": "biblical"},{"i": 4505,"n": "פַחַת מוֹאָב","l": "פ","b": "","cat": "biblical"},{"i": 4356,"n": "צביה","l": "צ","b": "","cat": "biblical"},{"i": 4407,"n": "צבעון החוי","l": "צ","b": "","cat": "biblical"},{"i": 4348,"n": "צדקיהו","l": "צ","b": "צדקיהו היה המלך האחרון ביהודה לפני כיבושה על ידי הבבלים. הוא נשבה, הובא לבבל ומת בשביו.","cat": "biblical"},{"i": 4155,"n": "צדקיה בן כנענה","l": "צ","b": "","cat": "biblical"},{"i": 4206,"n": "צופר","l": "צ","b": "","cat": "biblical"},{"i": 4207,"n": "צור","l": "צ","b": "צור המקראית הייתה עיר נמל פיניקית בלבנון של ימינו. היא נבנתה על אי ולכן הייתה בטוחה מפני צבאות פולשים ונהנתה משגשוג כלכלי. אף שבימי המלך חירם הייתה צור בת ברית של ישראל, על פי רוב היא נתפסה כאויבת.","cat": "biblical"},{"i": 4510,"n": "צוֹפַר הַנַּעֲמָתִי","l": "צ","b": "","cat": "biblical"},{"i": 4208,"n": "ציבא","l": "צ","b": "","cat": "biblical"},{"i": 4209,"n": "צלה","l": "צ","b": "","cat": "biblical"},{"i": 4210,"n": "צליה","l": "צ","b": "","cat": "biblical"},{"i": 4211,"n": "צלפחד","l": "צ","b": "","cat": "biblical"},{"i": 4260,"n": "צפניה","l": "צ","b": "","cat": "biblical"},{"i": 4109,"n": "צפנת פענח","l": "צ","b": "","cat": "biblical"},{"i": 4447,"n": "צרויה","l": "צ","b": "","cat": "biblical"},{"i": 4261,"n": "צרפית","l": "צ","b": "","cat": "biblical"},{"i": 4520,"n": "צְפַנְיָה֭ כֹּהֵ֣ן","l": "צ","b": "","cat": "biblical"},{"i": 4518,"n": "צִיחָ֥א","l": "צ","b": "","cat": "biblical"},{"i": 4463,"n": "קדמה","l": "ק","b": "","cat": "biblical"},{"i": 4262,"n": "קדר","l": "ק","b": "","cat": "biblical"},{"i": 4263,"n": "קהלת","l": "ק","b": "","cat": "biblical"},{"i": 4264,"n": "קהת","l": "ק","b": "","cat": "biblical"},{"i": 4020,"n": "קטורה","l": "ק","b": "","cat": "biblical"},{"i": 4021,"n": "קין","l": "ק","b": "קין הוא בנם הבכור של אדם וחוה, הראשון בין בני מינו שהוא יילוד אישה, והיה עובד אדמה. הוא ואחיו הצעיר הבל הביאו קורבנות לאל, אך לאחר שנדחה קורבן המנחה שהביא קין מן הצומח, ואילו קורבן הבהמה של הבל נתקבל, רצח קין את הבל אחיו. הוא קולל להיות נע ונד בארץ, אך אלוהים הגן עליו מפני נקמת דם.","cat": "biblical"},{"i": 4022,"n": "קינן","l": "ק","b": "","cat": "biblical"},{"i": 4023,"n": "קמואל","l": "ק","b": "","cat": "biblical"},{"i": 4031,"n": "קנז","l": "ק","b": "","cat": "biblical"},{"i": 4335,"n": "קציעה","l": "ק","b": "","cat": "biblical"},{"i": 4193,"n": "קרח","l": "ק","b": "קֹרַח הוא בן שבט לוי שמרד בסמכותו של משה. הוא וְיתר המורדים שהצטרפו אליו קיפחו את חייהם – חלקם נשרפו למוות ואת חלקם בלעה האדמה עם בני משפחותיהם.","cat": "biblical"},{"i": 4362,"n": "קרן הפוך","l": "ק","b": "","cat": "biblical"},{"i": 4045,"n": "ראובן","l": "ר","b": "ראובן הוא אבי שבט ראובן ובנם הבכור של יעקב ולאה. הוא שכנע את אחיו לא להרוג את אחיהם הצעיר יוסף אלא לזרוק אותו לבור, בהנחה שיוכל להצילו מאוחר יותר. הברכה של יעקב לראובן בסוף ימיו מורכבת, משום שהיא מזכירה שראובן שכב עם בלהה, פילגש אביו","cat": "biblical"},{"i": 4265,"n": "רבקה","l": "ר","b": "רבקה היא אחת מארבע האימהות של עם ישראל. במעשי החסד והכנסת האורחים שלה הוכיחה כי היא ראויה להצטרף למשפחת אברהם ולהינשא לבנו יצחק. היא העדיפה את בנה הקטן יעקב על פני אחיו התאום עֵשָׂו ולכן עזרה לו לרמות את יצחק בגנבת ברכת הבכורה.","cat": "biblical"},{"i": 4266,"n": "רבשקה","l": "ר","b": "","cat": "biblical"},{"i": 4274,"n": "רות","l": "ר","b": "רות היא גיבורת מגילת רות. אף שהייתה מואבייה נוכרייה, הלכה אחרי חמותה העברייה נעמי וליוותה אותה בשובה לבית לחם לאחר ששתיהן שכלו את בעליהן. רות התמסרה לנעמי ולעם היהודי. בארץ נישאה לבועז, והמלך דוד היה אחד מצאצאיהם.","cat": "biblical"},{"i": 4507,"n": "רוֹמֻס","l": "ר","b": "","cat": "biblical"},{"i": 4275,"n": "רחב","l": "ר","b": "רחב הייתה זונה שהתגוררה בחומת יריחו. היא הסתירה שני מרגלים מבני ישראל בביתה, וכגמול על עזרתה ניצלו היא ומשפחתה כאשר כבשו בני ישראל את יריחו.","cat": "biblical"},{"i": 4276,"n": "רחבעם","l": "ר","b": "","cat": "biblical"},{"i": 4277,"n": "רחל","l": "ר","b": "רחל היא אחת מארבע האימהות של עם ישראל. היא אשתו האהובה והבכירה של יעקב, שנישא קודם לכן לאחותה לאה. רחל סבלה מעקרות ממושכת לפני שילדה את שני בניו הצעירים והאהובים ביותר של יעקב, יוסף ובנימין. היא מתה בשעת לידתו של בנימין.","cat": "biblical"},{"i": 4435,"n": "ריפת","l": "ר","b": "","cat": "biblical"},{"i": 4326,"n": "רם","l": "ר","b": "","cat": "biblical"},{"i": 4403,"n": "רעו","l": "ר","b": "","cat": "biblical"},{"i": 4278,"n": "רעואל","l": "ר","b": "","cat": "biblical"},{"i": 4319,"n": "רעי איוב","l": "ר","b": "","cat": "biblical"},{"i": 4311,"n": "רצין מלך ארם-דמשק","l": "ר","b": "","cat": "biblical"},{"i": 4279,"n": "רצפה בת איה","l": "ר","b": "","cat": "biblical"},{"i": 4516,"n": "רִבִּי שְׁמוּאֵל אֲחוֹי דְרִבִּי בֶרֶכְיָה","l": "ר","b": "","cat": "biblical"},{"i": 4517,"n": "רִבִּי שְׁמוּאֵל אַחֲוֵי דְרִבִי בְּרֶכְיָה","l": "ר","b": "","cat": "biblical"},{"i": 4515,"n": "רִבִּי שְׁמוּאֵל אָחִיו דְּרִבִּי בְּרֶכְיָה","l": "ר","b": "","cat": "biblical"},{"i": 4513,"n": "רִבִּי שִׁמְעוֹן אַחֲוֵי דְּרִבִּי בְּרֶכְיָה","l": "ר","b": "","cat": "biblical"},{"i": 4506,"n": "רָם","l": "ר","b": "","cat": "biblical"},{"i": 4412,"n": "שאר ישוב","l": "ש","b": "","cat": "biblical"},{"i": 4283,"n": "שבואל","l": "ש","b": "","cat": "biblical"},{"i": 4284,"n": "שבנא","l": "ש","b": "","cat": "biblical"},{"i": 4285,"n": "שבע בן בכרי","l": "ש","b": "","cat": "biblical"},{"i": 4286,"n": "שגוב","l": "ש","b": "","cat": "biblical"},{"i": 4287,"n": "שובך","l": "ש","b": "","cat": "biblical"},{"i": 4455,"n": "שולמית","l": "ש","b": "","cat": "biblical"},{"i": 4289,"n": "שונמית","l": "ש","b": "","cat": "biblical"},{"i": 4308,"n": "שוע","l": "ש","b": "","cat": "biblical"},{"i": 4290,"n": "שישק","l": "ש","b": "","cat": "biblical"},{"i": 4293,"n": "שכם","l": "ש","b": "שכם הייתה עיר כנענית מצפון לירושלים, והיא נזכרת לראשונה בספר בראשית כאשר אברהם מקריב בה קורבן ובונה בה מזבח. שכם ידועה לשמצה משום שבה נאנסה דינה בת יעקב.","cat": "biblical"},{"i": 4322,"n": "שלה","l": "ש","b": "","cat": "biblical"},{"i": 4295,"n": "שלומיאל","l": "ש","b": "","cat": "biblical"},{"i": 4294,"n": "שלום בן תקוה","l": "ש","b": "","cat": "biblical"},{"i": 4297,"n": "שלמון","l": "ש","b": "","cat": "biblical"},{"i": 4413,"n": "שלמיהו","l": "ש","b": "","cat": "biblical"},{"i": 4359,"n": "שלף","l": "ש","b": "","cat": "biblical"},{"i": 4298,"n": "שלתיאל","l": "ש","b": "","cat": "biblical"},{"i": 4299,"n": "שמגר","l": "ש","b": "","cat": "biblical"},{"i": 4300,"n": "שמואל הנביא","l": "ש","b": "הנביא שמואל הנהיג את בני ישראל לפני תקופת המלוכה. תחת הנהגתו נלחם עם ישראל בפלישתים. הוא משח את שאול למלך הראשון של ישראל ושימש לו יועץ ונביא, עד שבסתר, במצוות האל, משח את דוד למלך במקומו.","cat": "biblical"},{"i": 4388,"n": "שמעון","l": "ש","b": "שמעון הוא בנם השני של יעקב ולאה. לאחר שאחותו דינה נאנסה ונשבתה בידי שכם, יצא שמעון עם אחיו לוי לנקום בבני עירו. בשל פזיזותו קילל אותו יעקב שצאצאיו יחולקו ויפוצו. הוא אבי שבט שמעון.","cat": "biblical"},{"i": 4389,"n": "שמעי","l": "ש","b": "","cat": "biblical"},{"i": 4390,"n": "שמעיה","l": "ש","b": "","cat": "biblical"},{"i": 4391,"n": "שמשון","l": "ש","b": "שמשון היה שופט, נזיר ומנהיג צבאי בספר שופטים. אחרי שהוביל כמה ניצחונות על הפלישתים, הצליחה דלילה, המאהבת שלו, להערים עליו ולגלות את מקור כוחו. הוא נשבה על ידי הפלישתים שעיוורו את עיניו, אך הצליח להרוג את שוביו ופלישתים רבים אחרים והתאבד כשהחריב את מקדשם.","cat": "biblical"},{"i": 4392,"n": "שעיר","l": "ש","b": "","cat": "biblical"},{"i": 4369,"n": "שפטיה בן אביטל","l": "ש","b": "","cat": "biblical"},{"i": 4393,"n": "שפן","l": "ש","b": "","cat": "biblical"},{"i": 4428,"n": "שפרה ופועה","l": "ש","b": "המיילדות העבריות","cat": "biblical"},{"i": 4450,"n": "שרה","l": "ש","b": "שרה היא דמות מקראית המופיעה בספר בראשית. היא הראשונה מבין 'ארבע האמהות' והיתה אשת אברהם. לאחר התמודדות עם עקרות ממושכת זכתה בזקנתה לבן יחיד, יצחק.","cat": "biblical"},{"i": 4443,"n": "שרוג","l": "ש","b": "","cat": "biblical"},{"i": 4420,"n": "שת","l": "ש","b": "","cat": "biblical"},{"i": 4508,"n": "שְׁבוּאֵל בֶּן גֵּרְשָׁם בֶּן מִֹשֶׁה","l": "ש","b": "","cat": "biblical"},{"i": 4514,"n": "שְׁמוּאֵל אַחֲוָה דְרַב בְּרֶכְיָה","l": "ש","b": "","cat": "biblical"},{"i": 4511,"n": "שְׁפַטְיָה בֶּן אֲבוּטָל","l": "ש","b": "","cat": "biblical"},{"i": 4509,"n": "שְׂרָיָה֙ כֹּהֵ֣ן הָרֹ֔אשׁ","l": "ש","b": "","cat": "biblical"},{"i": 4296,"n": "שְׁלֹמֹה","l": "ש","b": "שלמה הוא המלך השני בשושלת דוד, והוא נודע בייחוד בזכות בניית בית המקדש בירושלים. כמו כן בנה ממלכה מפוארת והרחיב את גבולות ישראל. הוא ידוע בתור מלך חכם בצורה יוצאת דופן, וספרי התנ\"ך משלי, שיר השירים וקהלת מיוחסים לו.","cat": "biblical"},{"i": 4292,"n": "שֵׁם","l": "ש","b": "שם, אחד מבני נח, ניצל במהלך המבול, והוא אביהם של עמים רבים, ביניהם העבריים.","cat": "biblical"},{"i": 4464,"n": "שֶׁלַח","l": "ש","b": "","cat": "biblical"},{"i": 4421,"n": "תבני","l": "ת","b": "","cat": "biblical"},{"i": 4422,"n": "תגלת פלאסר","l": "ת","b": "","cat": "biblical"},{"i": 4473,"n": "תגרמה","l": "ת","b": "","cat": "biblical"},{"i": 4460,"n": "תדעל","l": "ת","b": "","cat": "biblical"},{"i": 4423,"n": "תובל קין","l": "ת","b": "","cat": "biblical"},{"i": 4424,"n": "תולע בן פואה","l": "ת","b": "","cat": "biblical"},{"i": 4351,"n": "תימא","l": "ת","b": "","cat": "biblical"},{"i": 4360,"n": "תימן","l": "ת","b": "","cat": "biblical"},{"i": 4339,"n": "תירס","l": "ת","b": "","cat": "biblical"},{"i": 4453,"n": "תלמי מלך גשור","l": "ת","b": "","cat": "biblical"},{"i": 4352,"n": "תמנע","l": "ת","b": "","cat": "biblical"},{"i": 4353,"n": "תמר","l": "ת","b": "","cat": "biblical"},{"i": 4354,"n": "תמר","l": "ת","b": "תמר הייתה כלתו של יהודה. היא נישאה לשני בניו, אך שניהם מתו, ולמרות חובתו הוא סירב להשיא לה את בנו השלישי. לפיכך היא התחפשה לזונה ופיתתה את יהודה. היא שמרה את כליו כמשכון והשתמשה בהם להוכחת אחריותו כלפיה. דוד המלך היה מצאצאיו של בנם פרץ.","cat": "biblical"},{"i": 4456,"n": "תרח","l": "ת","b": "","cat": "biblical"},{"i": 4320,"n": "תרצה","l": "ת","b": "","cat": "biblical"},{"i": 4434,"n": "תתני","l": "ת","b": "","cat": "biblical"}];
